// The self-tests and their made-up people, places and paths: compiled only
// with SKILLI_SELFTEST (Debug, and the self-test modes of
// script/build_and_run.sh), never in a release (script/release/build.sh checks).
#if SKILLI_SELFTEST
import AVFoundation
import AppKit
import CoreAudio
import Network
import ScreenCaptureKit
import ApplicationServices
import Carbon.HIToolbox
import ImageIO
import SkilliCore
import SwiftUI
import Synchronization
import UniformTypeIdentifiers

/// `--selftest`: drives the real app end to end.
///
/// Posts hardware-like key events (no skil.li marker, so the event tap treats
/// them exactly like the user's keyboard), then checks the outcome in a test
/// window, TextEdit and Safari. Needs Accessibility, and must be launched
/// through LaunchServices (`open`) so skil.li — not the shell — is the
/// responsible process for TCC. See `./script/build_and_run.sh selftest`.
@MainActor
final class SelfTest {
    struct Check: Codable {
        let name: String
        let passed: Bool
        var skipped = false
        let detail: String
        let latencyMs: Double?
    }

    struct Report: Codable {
        let passed: Int
        let failed: Int
        var skipped = 0
        let checks: [Check]
    }

    struct Context {
        let launcher: LauncherController
        let actions: ActionRunner
        let selection: SelectionService
        let layout: KeyboardLayout
        let overlay: LeaderOverlay
        /// The real Hyper trigger (Caps Lock's F-key, F20 with Raycast).
        let triggerKeyCode: CGKeyCode
        /// Whether our tap ever saw `triggerKeyCode` (false when another
        /// Hyper tool's tap consumes it first).
        let receivesTrigger: @MainActor () -> Bool
        let settings: SettingsWindowController
        let preferences: Preferences
        let shortcuts: ShortcutStore
        let router: KeyRouter
        /// Triggers the status menu's Settings… item, as a click would.
        let performStatusMenuSettings: @MainActor () -> Bool
        /// Uses its own Keychain item, never the user's API key.
        let ai: AIStore
        let aiActions: AIActionController
        let aiCommands: AICommandsModel
        /// skil.li's MCP server, on the self-test's own socket and tools.json.
        let tools: MCPService
        /// The clipboard history, on the self-test's own scratch store.
        let clipboard: ClipboardHistory
        /// Snippets, in the self-test's own folder.
        let snippets: SnippetLibrary
        let snippetExpander: SnippetExpander
        /// Window layouts, in the self-test's own folder.
        let arranger: WindowArranger
        /// Where a layout is looked over before it is saved.
        let layoutEditor: LayoutEditorController
        /// The question asked when a display is plugged in, and offering
        /// displays as if they had just been plugged.
        let displayPrompt: DisplayPrompt
        let offerDisplays: ([DisplayFingerprint]) -> Void
        /// Timers, in the self-test's own defaults.
        let timers: TimerCenter
        /// The next meeting in the menu bar, joined or offered as it starts.
        let meetingWatch: MeetingWatch
        /// Today's reminders in the menu bar.
        let reminderWatch: ReminderWatch
        /// A meeting alert in the middle of the screen.
        let meetingCard: MeetingCard
        /// Settings → Windows → Quit apps you stopped using.
        let autoQuitter: AutoQuitter
        /// Backups of the self-test's own scratch folder and settings.
        let backup: BackupCenter
        /// Inline skillies in the menu bar.
        let menuBarSkillies: MenuBarSkillies
        /// The cup in the menu bar while the Mac is kept awake.
        let awakeIndicator: AwakeIndicator
        let scheduler: AskScheduler
        /// Where to write Settings tab snapshots, if anywhere.
        let snapshotDirectory: URL?
        /// `skilli://` links, opened as another app would.
        var links: LinkRunner?
        /// Settings → Launcher → Type in English while open.
        var englishTyping: EnglishTyping?
        /// Every delete of the user's data, undone by ⌘Z in the card.
        var deletes: UndoableDeletes?
        /// The status menu, and where its icon is in the menu bar (nil
        /// while hidden), to open it with a real click.
        var statusMenu: @MainActor () -> NSMenu? = { nil }
        var statusItemFrame: @MainActor () -> NSRect? = { nil }
        /// The app's own welcome, shown on a step: the keys and the
        /// launcher report to it as they do for the person.
        var welcome: @MainActor (WelcomeModel.Step) -> SetupWindowController? = { _ in nil }
        /// Where the report goes (standard output when nil): the watchdog
        /// writes it there if the run never ends.
        var reportPath: String?
        /// The meeting recorder, made when first asked for.
        var recorder: @MainActor () -> RecorderCenter? = { nil }
        /// The recordings as the launcher and Settings → Recorder list them;
        /// Keep recordings in's move (nil, or why it was refused).
        var recordings: @MainActor () -> RecordingLibrary? = { nil }
        var moveRecordings: @MainActor (URL) async -> String? = { _ in nil }
        /// Where the user puts windows (Arrange Windows), in the
        /// self-test's own placements.json.
        var windowLearner: WindowLearner?
        /// Better transcription's download, in the self-test's own folder.
        var betterTranscription: @MainActor () -> BetterTranscription? = { nil }
    }

    enum Scope: String, Sendable {
        case all
        /// Only the Settings checks (about 20 s).
        case settings
        /// Only the on-screen glass checks (about 15 s; Screen Recording).
        case glass
        /// Only the AI checks (about 10 s; one real Claude request, ~850
        /// tokens of the user's plan).
        case ai
        /// Only draws the setup window off screen (no keys, no focus): safe
        /// while the Mac is in use.
        case setup
        /// Only the live decisions (Ask's routes, menus, apps, commands;
        /// emoji, clipboard and files by meaning) on the user's decision
        /// keys: no keys typed, no windows, nothing opened.
        case decide
        /// Only Ask's routes on volume (`AskRouteCorpus`, both halves) on
        /// the user's decision keys: no keys typed, nothing opened.
        case routes
        /// Only the clipboard history on a scratch store and a private
        /// pasteboard (OCR included): no keys, safe while the Mac is in use.
        case clipboard
        /// Only the browser tabs check (Safari, local pages; keys).
        case browser
        /// Only the file search checks (a few files seeded in the home
        /// folder for Spotlight, removed after; keys).
        case files
        /// Only the sound device checks (switches the output, puts it
        /// back; keys).
        case sound
        /// Only the editor projects check (scratch Cursor and Zed lists;
        /// keys).
        case projects
        /// Only Clean Keyboard (turns the keys off a few seconds; keys).
        case keyboard
        /// Only skillies (scratch folder; keys).
        case scripts
        /// Only the browser history checks (scratch histories; keys).
        case history
        /// Only backups (scratch folder, settings and destination; no keys,
        /// no windows).
        case backup
        /// Only Jev with images: tags, icons, a screen; tokens and time per
        /// size (the user's TypeSafe key; no keys typed).
        case vision
        /// Only Homebrew (search, dry-run install; keys).
        case brew
        /// Only the Raycast imports (scratch snippets; no keys, no windows).
        case imports
        /// Only ✦K → U in TextEdit and in a Safari text area (keys).
        case roundtrip
        /// Only where the AI card goes (fake engine; keys).
        case card
        /// Only "do it here" in a test form, another skil.li process, with
        /// the user's decision key (mouse and keys).
        case control
        /// Only "do it here" seeing the window: icon-only buttons in a test
        /// form and a Safari page, in words then with Jev's picture (the
        /// user's TypeSafe key; mouse and keys). Also in `control`.
        case sight
        /// Only "do it here" from outside Ask (docs/do-it-here-from-anywhere.md):
        /// `skilli://do` links asked, denied, trusted, chained; a skillie's
        /// two links through macOS (TextEdit then Finder); `do_in_app` for
        /// a real agent and from a terminal; skillies that wait for their
        /// step and branch on it, and one stopped at its time limit with its
        /// step (the user's decision key, Claude; mouse and keys).
        case doit
        /// Only Chess, "do it here" in any app (docs/click-what-you-see.md):
        /// spots picked on its board seen as a picture only, moves chosen
        /// by Jev or planned by Claude, the demo through Ask, recorded
        /// (the user's TypeSafe key, Claude; mouse and keys).
        case chess
        /// Only "change default browser to …" typed in Ask: the agent does
        /// it (the browser is not just opened), then puts the first one
        /// back the same way. Changes the Mac's default browser for a while
        /// (the user's decision key and Ask's model; keys, System Settings).
        case defaultbrowser
        /// The launcher over a card, Mac commands, Kill Process and timers,
        /// then the calculator (keys).
        case calc
        /// Continue a conversation in Claude Code or Codex (keys, terminals).
        case handoff
        /// MCP sign-in against a stand-in server, Tools settings kept
        /// across launches (no keys, no windows).
        case mcpauth
        /// Other servers' tools and their rights: a stand-in server, the
        /// bridge over stdio, blocked tools, the rights tools for the user's
        /// AI (Return and Esc in the card), its session in a terminal, the
        /// pane and the Tools… sheet (keys).
        case toolrights
        /// Only GitHub, against a stand-in (keys).
        case github
        /// Typing speed in the launcher and in the card, key by key, with
        /// thousands of contacts kept in memory (keys).
        case speed
        /// Only the window places and layouts (TextEdit; keys).
        case windows
        /// Only the writers: Codex's and the OpenAI key's models, a real
        /// answer from ChatGPT through a command and from the OpenAI API
        /// (the user's plan and key), the Model menus captured open (keys).
        case models
        /// Only System Settings' panes: read on this Mac, found in the
        /// launcher (Return opens one), picked by Ask on the user's
        /// decision key (keys).
        case panes
        /// Only the Catalog ("?"): groups, filter, Return, keycaps, ⌘K,
        /// what is Off in Settings dimmed, captured light and dark (keys).
        case catalog
        /// Only the root search: ↑ recent searches, Pin from ⌘K, Opens on,
        /// Starts again empty, Settings → Launcher, the caret keys in the
        /// launcher, Settings' fields and the Ask card (keys).
        case rootsearch
        /// Only the linked apps (CleanShot X): ✦K C, the launcher's rows,
        /// ⌘K's captures, the front window's frame, files sent to it (⌘K
        /// on files and clipboard images, the Finder selection,
        /// `run_action file=`); nothing captured (keys).
        case apps
        /// Only skil.li's settings through its tools, on scratch
        /// preferences: the table covers every setting, get_settings,
        /// set_setting through the card, refusals, the lists' tools, the
        /// skill (keys).
        case settingtools
        /// Only snippets and pasting: keywords at once and after a space or
        /// ↩, an app left out, Search Snippets by name and by meaning (the
        /// user's key), the history pasted from the launcher, Paste in
        /// Sequence, Paste Latest Screenshot, the two panes light and dark
        /// (keys).
        case snippets
        case schedule
        /// Only Dictate and the voice it shares with Ask by Voice: spoken
        /// files stand in for the microphone; the contacts' names, ✦D into
        /// TextEdit, ✦D again, password fields (keys).
        case dictation
        /// Only the shortcuts' keys: a macOS shortcut against skil.li's
        /// tap, the same key twice in a chain, what the recorder refuses,
        /// the launcher's keys in General, Keys and the status menu (keys).
        case shortcuts
        /// Only Settings' search: ⌘F, typing, ↑↓, ↩ to a row and its glow,
        /// esc, nothing found, the sidebar's keys; then every setting,
        /// section, permission and shortcut shown in sight (keys).
        case settingsearch
        /// Only the clipboard history's previews, on its own store: each
        /// kind of copy walked with ↓ and captured light and dark, links
        /// read from pages served on 127.0.0.1 (keys).
        case previews
        /// Only the meeting in the menu bar: each moment from stand-in
        /// events and a stand-in microphone, captured as the menu bar shows
        /// it, light and dark; Settings → Calendar's preview; the card
        /// offering it as it starts; no alert and no Join at once for a call
        /// joined already, a card going as it is joined (no keys).
        case meetingbar
        /// Only the emoji picker: by name, by feeling (the user's key), the
        /// skin tone picked in Settings → Launcher typed, words found by
        /// meaning found again by name at once (keys).
        case emoji
        /// Only Search Menu Items: TextEdit's menus by name, an item chosen
        /// through Accessibility (keys).
        case menus
        /// Only Search GIFs: a stand-in Klipy on 127.0.0.1 and a GIF seeded
        /// in the home folder; Trending, a search, ↩ pasted animated, the
        /// share counted, Recently Used, this Mac's, no key (keys).
        case gifs
        /// Search GIFs as users get it: the build's own Klipy key (build
        /// with SKILLI_KLIPY_KEY), the real Klipy; Trending, a search, the
        /// tile playing, ↩ pasted animated, Recently Used (keys, network).
        case gifslive
        /// Every delete of the user's data and its undo card: gone at once,
        /// Undo ⌘Z, ↩ to the app, ⌘Z puts it back (scratch stores; keys).
        case undo
        /// Only the meeting recorder (docs/meeting-recorder.md, phase 1): a
        /// scripted call played back (another app plays the other side, a
        /// file stands in for the microphone), its transcript against the
        /// script, the tracks in step across a pause, a recording never
        /// stopped (another skil.li killed), links and tools (keys, sound).
        case recorder
        /// Only the recorder's moment (phase 2): the five cases, Record ⌘R
        /// on the meeting card, the launcher's row and the menu bar, never
        /// while the card is not the user's; a browser call's microphone
        /// mapped to Chrome (a scratch Chrome); the call's end; Search
        /// Recordings; Settings → Recorder, Delete after and the folder's
        /// move (keys, Chrome, stand-in events).
        case moment
        /// Only the recorder's webcam and screen (phase 3): a stand-in
        /// camera, a test window showing slides at known times recorded
        /// with a call whose beeps it flashes with: `slides.json` at those
        /// times, the pictures in step with the sound across a pause; a
        /// window minimized or covered said in the menu bar; a scratch
        /// Chrome's window (keys, Chrome).
        case pictures
        /// Only the recorder's phase 4 without Better transcription: the
        /// played-back calls through the recorder's own transcript, the
        /// voices told apart (SpeakerKit in skil.li Transcriber); an import;
        /// a line edited, given to another speaker, deleted and brought
        /// back; speakers renamed and merged; Transcribe Again (keys,
        /// ~10 min).
        case voices
        /// Only Better transcription (phase 4): its download from a stand-in
        /// server (the model on this Mac's ~/recorder-measure: cancelled,
        /// resumed, a wrong file refused), its row in Settings → Recorder,
        /// taught once in a window; whisper on the played-back calls; the
        /// echo drop with its times on the recording's clock (~25 min).
        case whisper
    }

    /// Extra trigger only the self-test registers. No Hyper tool listens to
    /// F19, so it exercises skil.li's own Hyper handling even when Raycast
    /// owns Caps Lock.
    static let ownTriggerKeyCode = CGKeyCode(kVK_F19)

    private let context: Context
    private var checks: [Check] = [] {
        didSet { watchdog.recorded(checks) }
    }
    /// Set when focus is not where a test expects it. Every later test is
    /// skipped: synthetic keys must never land in the user's own apps.
    private var aborted = false {
        didSet { if aborted { watchdog.focusLost() } }
    }
    /// Ends the run if it stops moving on, main thread held or not.
    private let watchdog: SelfTestWatchdog
    private let window: NSWindow
    /// Big enough that the AI card, its glass margin and the capture's
    /// padding stay over this window: captures never show the user's own
    /// windows behind the card.
    private let textView = NSTextView(frame: NSRect(x: 80, y: 510, width: 560, height: 120))
    private let recorder = KeyRecorderView(frame: NSRect(x: 80, y: 20, width: 560, height: 40))
    /// Stands in for a menu item Ask finds (skil.li's own menu bar is not
    /// exposed: it is an accessory app): pressing it counts.
    private let menuStandIn = NSButton(title: "Stand-in", target: nil, action: nil)
    private let menuStandInTarget = PressCounter()
    /// Controls the screen tools read and use.
    private let rememberBox = NSButton(checkboxWithTitle: "Remember me", target: nil, action: nil)
    private let emailField = NSTextField(frame: NSRect(x: 320, y: 80, width: 220, height: 24))
    /// A known color for the eyedropper: skil.li's mint, #3E8E7E.
    private let colorSwatch = NSView(frame: NSRect(x: 560, y: 80, width: 100, height: 60))

    init(context: Context) {
        self.context = context
        watchdog = SelfTestWatchdog(reportPath: context.reportPath)
        window = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: 720, height: 660),
            styleMask: [.titled],
            backing: .buffered,
            defer: false
        )
        window.title = "skil.li self-test"
        window.isReleasedWhenClosed = false
        window.center()
        textView.isRichText = false
        textView.allowsUndo = true
        textView.font = .systemFont(ofSize: 15)
        window.contentView?.addSubview(textView)
        window.contentView?.addSubview(recorder)
        menuStandIn.frame = NSRect(x: 80, y: 80, width: 120, height: 28)
        menuStandIn.target = menuStandInTarget
        menuStandIn.action = #selector(PressCounter.press(_:))
        menuStandIn.setAccessibilityLabel("Self-test Menu Item")
        window.contentView?.addSubview(menuStandIn)
        rememberBox.frame = NSRect(x: 210, y: 82, width: 110, height: 20)
        window.contentView?.addSubview(rememberBox)
        emailField.placeholderString = "Email"
        emailField.setAccessibilityLabel("Email")
        window.contentView?.addSubview(emailField)
        colorSwatch.wantsLayer = true
        colorSwatch.layer?.backgroundColor = NSColor(srgbRed: 62 / 255, green: 142 / 255, blue: 126 / 255, alpha: 1).cgColor
        window.contentView?.addSubview(colorSwatch)
    }

    /// A check, or a few, run as one step of a scope.
    typealias Step = @MainActor () async -> Void

    func run(scope: Scope = .all) async -> Report {
        let clipboard = PasteboardSnapshot(NSPasteboard.general)
        defer { clipboard.restore(to: NSPasteboard.general) }
        // The checks answer agents' questions with keys at once; the one that
        // tests the pause and the grace puts them back.
        context.aiActions.typingPause = 0
        context.aiActions.unpromptedGrace = .zero

        if scope == .ai {
            return await finish(after: [aiChecks])
        }
        if scope == .models {
            return await finish(after: [writerChecks])
        }
        if scope == .setup {
            return await finish(after: [
                drawWelcome,
                setupAsksOnlyForTwo,
                welcomeLiveSteps,
                settingsGuideFollowsTheWindow,
                reopenAfterSystemSettings
            ])
        }
        if scope == .browser {
            window.center()
            return await finish(after: [takeFocus, browserTabsAreFound])
        }
        if scope == .mcpauth {
            return await finish(after: [toolSettingsSurviveRelaunches, mcpServerSignIn])
        }
        if scope == .github {
            window.center()
            return await finish(after: [githubInbox, relayTokenRemovalUndoes])
        }
        if scope == .toolrights {
            return await finish(after: [
                toolSettingsSurviveRelaunches,
                serversImportedFromOtherApps,
                serverToolsListed,
                toolRightsDecide,
                approvalRulesDecide,
                rightsToolsForYourAI,
                rightsSessionLaunches,
                rightsHelperChoice,
                toolsPaneSnapshot,
                serverRemovalUndoes,
                ruleRemovalUndoes
            ])
        }
        if scope == .handoff {
            window.center()
            return await finish(after: [handoffFromCard, handoffLaunchesTerminal])
        }
        if scope == .calc {
            window.center()
            let calculations: [Step] = [macControlsWork, launcherCalculates]
            return await finish(after: [
                macCommandsUseRealAPIs,
                keepAwakeHoldsTheMac,
                keepAwakeForAWhile,
                keepAwakeSeenInTheLauncher,
                keepAwakeSurvivesARestart,
                killProcessByNameAndPort,
                timersCountDown,
                appsQuitHideAndMicrophone,
                wifiBluetoothAndVolumeLevel,
                autoQuitKeepsWhatIsInUse,
                launcherKeysOverCard
            ] + calculations + calculations + calculations)
        }
        if scope == .speed {
            window.center()
            return await finish(after: [
                { await self.launcherTypesFast() },
                {
                    await self.launcherTypesFast(off: ["catalog.calculator", "catalog.soundOutput", "catalog.settingsPanes", "cmd:searchContacts",
                                                       "cmd:killProcess", "system:lockScreen", "system:window.leftHalf", "catalog.timer",
                                                       "cmd:searchProjects", "si:ask"])
                },
                cardTypesFast
            ])
        }
        if scope == .control {
            window.center()
            return await finish(after: [
                askUnsureCommandOffersChoices,
                aliasesOpenWhatTheyName,
                askQuitsWhatItNames,
                uninstallMovesAppAndLeftovers,
                controlDoesItInAnotherApp,
                controlSeesWhatOnlyThePictureTells,
                controlSeesAWebPage,
                controlExportsFromWord,
                formDetailsUndo
            ])
        }
        if scope == .chess {
            return await finish(after: [chessChecks])
        }
        if scope == .defaultbrowser {
            window.center()
            return await finish(after: [askChangesTheDefaultBrowser])
        }
        if scope == .doit {
            window.center()
            return await finish(after: [
                doLinksAskTrustAndChain,
                doLinksChainTwoApps,
                doInAppForAgents,
                skilliesWaitForTheirStep,
                skillieStopsWithItsStep
            ])
        }
        if scope == .sight {
            window.center()
            return await finish(after: [controlSeesWhatOnlyThePictureTells, controlSeesAWebPage])
        }
        if scope == .windows {
            window.center()
            return await finish(after: [
                windowsPlaceTheFrontWindow,
                arrangeWindowsLearnsAndPutsBack,
                windowLayoutsAndSwitching,
                layoutOpensAFileAndALink,
                layoutDeleteUndoes
            ])
        }
        if scope == .card {
            window.center()
            return await finish(after: [
                cardTakesLauncherPlace,
                cardsLeaveTheAppItsKeys,
                cardBesideAFieldNotADocument,
                askFollowsUpInTheCard,
                rewriteFollowsUp,
                askOffersANamedService,
                askSendsMediaKeys,
                askShowsMarkdown,
                askAsksForWhatIsMissing,
                askFoundCardChooses,
                contactsFoundAndWritten,
                contactCardActs,
                actionsForTheSelectedRow,
                appRowQuitsARunningApp,
                askFindsContacts,
                agendaFoundAndJoined,
                agendaEventsAdded,
                meetingInMenuBarAndOffered,
                meetingBarStates,
                meetingAlertsBefore,
                meetingAlertsNotWhenJoined,
                meetingCardChecksCameraAndMic,
                remindersSaidAndDone,
                remindersInMenuBarPlacesAndMail,
                reminderDeleteUndoes,
                eventDeleteUndoes,
                placeForgetUndoes,
                calendarReadsThisMac,
                eventKitAnswersOffTheMainActor,
                microphoneHeardForReal
            ])
        }
        if scope == .roundtrip {
            return await finish(after: [textEditRoundTrip, safariTextareaRoundTrip])
        }
        if scope == .imports {
            return await finish(after: [raycastExportsImport])
        }
        if scope == .vision {
            return await finish(after: [jevSeesImages, imagesTaggedAndFound])
        }
        if scope == .backup {
            return await finish(after: [backupGoesAndComesBack, backupLeavesTheWordsSaidOut])
        }
        if scope == .brew {
            window.center()
            return await finish(after: [homebrewSearchAndInstall])
        }
        if scope == .history {
            window.center()
            return await finish(after: [historyPickedByMeaning, browserHistorySearch])
        }
        if scope == .scripts {
            window.center()
            return await finish(after: [askRunsScripts, scriptCommandsRun, skillieFilesAdded, agentCreatesSkillie])
        }
        if scope == .keyboard {
            window.center()
            return await finish(after: [
                cleanKeyboardBlocksKeys,
                showDesktopMovesWindowsAside,
                unboundHyperPassesThrough,
                hyperReleasedAfterSecureInput
            ])
        }
        if scope == .projects {
            window.center()
            return await finish(after: [askOpensProjects, editorProjectsFound])
        }
        if scope == .apps {
            window.center()
            return await finish(after: [
                takeFocus,
                cleanShotRouting,
                cleanShotFromLauncher,
                cleanShotFromSkillies,
                cleanShotOpensFiles,
                appFilesFromFiles,
                appsPaneShown,
                appleShortcutsRun
            ])
        }

        if scope == .rootsearch {
            window.center()
            return await finish(after: [
                takeFocus,
                recentSearchesComeBack,
                pinsComeFirst,
                startsAgainAfterAWhile,
                opensOnTheChosenScreen,
                launcherSettingsShown,
                controlKeysMoveLikeArrows,
                caretKeysEditEverywhere,
                quicklinkTakesTheSelection,
                typesInEnglishWhileOpen
            ])
        }
        if scope == .catalog {
            window.center()
            return await finish(after: [
                catalogListsWhatSkilliDoes,
                catalogShortcutsReachEverything,
                catalogOffLeavesResults,
                takeFocus,
                linksRunWhatTheyName,
                linksTrustedPerEntry,
                quicklinksSectionShown,
                newFromLauncherOpensEditors,
                quicklinkDeleteUndoes,
                aliasRemovalUndoes
            ])
        }
        if scope == .settingtools {
            window.center()
            return await finish(after: [settingToolsChecks])
        }
        if scope == .snippets {
            window.center()
            return await finish(after: [
                takeFocus,
                snippetsExpandAndInsert,
                snippetsExpandInSafari,
                snippetsWaitForADelimiter,
                snippetsFoundByMeaning,
                snippetsMaybeRow,
                snippetDeleteUndoes,
                clipboardPastesFromLauncher,
                clipboardForgetUndoes,
                pasteInSequenceWithKeys,
                pasteLatestScreenshot,
                snippetsAndClipboardPanes,
                clipboardRetentionWaitsForTheHour
            ])
        }
        if scope == .schedule {
            window.center()
            return await finish(after: [
                scheduleSaidInAskIsKept,
                scheduledAskFiresAndShowsItsCard,
