    /// Runs `steps` in turn. Once one finds the focus lost (`aborted`), the
    /// rest never run, so no key or click lands in another app: the report
    /// says how many were left.
    private func finish(after steps: [Step]) async -> Report {
        for (done, step) in steps.enumerated() {
            if aborted {
                checks.append(Check(name: "Steps after the focus was lost", passed: true, skipped: true,
                                    detail: "\(steps.count - done) of \(steps.count) not run", latencyMs: nil))
                break
            }
            await step()
        }
        return finish()
    }

    private func finish() -> Report {
        window.orderOut(nil)
        // Ended by the watchdog already: its report, the one written.
        return watchdog.stop() ?? Report(checks: checks)
    }

    /// A step: the test window to front, or the run stops there.
    private func takeFocus() async {
        _ = await focusTestWindow()
    }

    /// Brings the test window to front and confirms it, or aborts the run.
    private func focusTestWindow() async -> Bool {
        guard !aborted else { return false }
        // Re-asked every 250 ms: right after a non-activating panel closes,
        // AppKit can report our window as key without it being key yet.
        var focused: Duration?
        let start = ContinuousClock.now
        for _ in 0..<8 {
            NSApp.activate()
            // Cooperative activation lets the user's frontmost app refuse;
            // Accessibility can still bring us forward.
            Self.makeFrontmost(pid: getpid())
            window.makeKeyAndOrderFront(nil)
            // Keys go to the active, frontmost app, which dispatches them to its
            // key window: that is what keeps synthetic keys out of the user's
            // apps. `isKeyWindow` can lag behind `NSApp.keyWindow` after a
            // non-activating panel closed, so either one will do.
            // Accessibility's focus too: selections are read through it, and
            // it can still point at the user's app for a moment.
            if await waitUntil(timeout: 0.25, {
                NSWorkspace.shared.frontmostApplication?.processIdentifier == getpid()
                    && NSApp.isActive
                    && (self.window.isKeyWindow || NSApp.keyWindow === self.window)
                    && Self.accessibilityFocusIsOurs()
            }) != nil {
                focused = .now - start
                break
            }
        }
        if focused == nil {
            aborted = true
            let keyWindow = NSApp.windows.filter { $0.isVisible || $0.isKeyWindow || $0 === NSApp.keyWindow }.map { "\(type(of: $0))“\($0.title)” key=\($0.isKeyWindow) visible=\($0.isVisible) appKey=\($0 === NSApp.keyWindow)" }.joined(separator: " | ")
            record("Focus", false, "test window not key after “\(checks.last?.name ?? "start")” (frontmost: \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"), key window: \(keyWindow), isKey: \(window.isKeyWindow), active: \(NSApp.isActive), visible: \(window.isVisible)); aborting so no key lands elsewhere", nil)
            return false
        }
        return true
    }

    /// The system-wide focused element belongs to skil.li.
    private static func accessibilityFocusIsOurs() -> Bool {
        let system = AXUIElementCreateSystemWide()
        AXUIElementSetMessagingTimeout(system, 0.25)
        var focused: CFTypeRef?
        var pid: pid_t = 0
        guard AXUIElementCopyAttributeValue(system, kAXFocusedUIElementAttribute as CFString, &focused) == .success,
              let focused, CFGetTypeID(focused) == AXUIElementGetTypeID(),
              AXUIElementGetPid(unsafeDowncast(focused, to: AXUIElement.self), &pid) == .success
        else { return false }
        return pid == getpid()
    }

    /// For real-app steps: confirms `bundleID` is still frontmost, or aborts.
    private func ensureFrontmost(_ bundleID: String, before step: String) -> Bool {
        if NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID { return true }
        aborted = true
        record("Focus", false, "\(bundleID) lost focus before \(step) (frontmost: \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?")); aborting", nil)
        return false
    }

    // MARK: - Checks in the test window

    private func transformInTestWindow(
        name: String,
        original: String,
        expected: String,
        keys: [Character],
        trigger: CGKeyCode? = nil,
        expectedSource: SelectionService.Read.Source,
        checkUndo: Bool
    ) async {
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = original
        textView.undoManager?.removeAllActions()
        textView.selectAll(nil)
        let sentinel = "skilli-selftest-\(UUID().uuidString)"
        setClipboard(sentinel)
        await pause(60)

        let transformsBefore = context.actions.transformCount
        let start = await hyperChord(keys, trigger: trigger)
        guard await waitUntil(timeout: 2, { self.textView.string == expected }) != nil else {
            record(name, false, "text is \"\(textView.string)\", expected \"\(expected)\"", nil)
            return
        }
        let latency = ContinuousClock.now - start
        // The action reports once its clipboard restore finished.
        _ = await waitUntil(timeout: 1.5) { self.context.actions.transformCount > transformsBefore }

        var problems: [String] = []
        if let last = context.actions.lastTransform, last.source != expectedSource {
            problems.append("read via \(last.source.rawValue), expected \(expectedSource.rawValue)")
        }
        await pause(450)
        if NSPasteboard.general.string(forType: .string) != sentinel {
            problems.append("clipboard not restored")
        }
        if checkUndo {
            guard await focusTestWindow() else { return }
            await pressKey("z", flags: .maskCommand)
            if await waitUntil(timeout: 1, { self.textView.string == original }) == nil {
                problems.append("⌘Z did not restore \"\(original)\" (got \"\(textView.string)\")")
            }
        }
        let visible = context.actions.lastTransform.map { "visible \(String(format: "%.1f", $0.visible.milliseconds)) ms after trigger" } ?? ""
        record(name, problems.isEmpty, problems.isEmpty ? "ok, \(visible)" : problems.joined(separator: "; "), latency.milliseconds)
    }

    /// Reports who handles the real Caps Lock trigger on this Mac.
    private func realTriggerPath() async {
        guard await focusRecorder() else { return }
        postKey(context.triggerKeyCode, down: true)
        await pause(30)
        postKey(context.triggerKeyCode, down: false)
        await pause(150)
        if context.receivesTrigger() {
            let escaped = recorder.events.contains { $0.keyCode == UInt16(kVK_Escape) }
            record("Real Caps Lock trigger handled by skil.li; tap → Escape", escaped, escaped ? "Escape delivered" : "got \(recorder.summary)", nil)
        } else {
            checks.append(Check(
                name: "Real Caps Lock trigger",
                passed: true,
                skipped: true,
                detail: "another Hyper tool (Raycast) consumes the trigger before skil.li's tap; Hyper reaches skil.li as ⌘⌃⌥⇧ and tap-for-Escape follows that tool's setting",
                latencyMs: nil
            ))
        }
    }

    private func tapSendsEscape() async {
        guard await focusRecorder() else { return }
        postKey(Self.ownTriggerKeyCode, down: true)
        await pause(30)
        postKey(Self.ownTriggerKeyCode, down: false)
        let latency = await waitUntil(timeout: 1) { self.recorder.events.contains { $0.keyCode == UInt16(kVK_Escape) } }
        record("Tap skil.li's Hyper alone → Escape (F19)", latency != nil, latency != nil ? "Escape delivered" : "no Escape received; got \(recorder.summary)", latency?.milliseconds)
    }

    private func unboundHyperPassesThrough() async {
        guard await focusRecorder() else { return }
        postKey(Self.ownTriggerKeyCode, down: true)
        await pause(20)
        await pressKey("j")
        postKey(Self.ownTriggerKeyCode, down: false)
        let hyper: NSEvent.ModifierFlags = [.command, .control, .option, .shift]
        let latency = await waitUntil(timeout: 1) {
            self.recorder.events.contains { $0.characters == "j" && $0.flags.isSuperset(of: hyper) }
        }
        record("Unbound ✦J reaches the app as ⌘⌃⌥⇧J (F19)", latency != nil, latency != nil ? "ok" : "got \(recorder.summary)", latency?.milliseconds)
    }

    /// Hyper held, then Secure Input on and the trigger's release never
    /// seen (stood in for: the self-test's own process would still see its
    /// keys): when Secure Input ends, Hyper lets go, and J comes plain.
    private func hyperReleasedAfterSecureInput() async {
        let name = "Secure Input hides the trigger's release: Hyper lets go when it ends; the next key comes plain"
        guard await focusRecorder() else { return }
        let router = context.router
        let real = router.secureInputEnabled
        defer { router.secureInputEnabled = real }
        var secure = true
        router.secureInputEnabled = { secure }
        postKey(Self.ownTriggerKeyCode, down: true)
        await pause(600)
        // The release is lost while Secure Input is on; then it ends.
        secure = false
        await pause(600)
        recorder.events.removeAll()
        await pressKey("j")
        let plain = await waitUntil(timeout: 1) {
            self.recorder.events.contains { $0.characters == "j" && $0.flags.isDisjoint(with: [.command, .control, .option]) }
        }
        // Hyper still works afterwards.
        postKey(Self.ownTriggerKeyCode, down: false)
        await pause(50)
        recorder.events.removeAll()
        postKey(Self.ownTriggerKeyCode, down: true)
        await pause(20)
        await pressKey("j")
        postKey(Self.ownTriggerKeyCode, down: false)
        let hyper: NSEvent.ModifierFlags = [.command, .control, .option, .shift]
        let again = await waitUntil(timeout: 1) { self.recorder.events.contains { $0.characters == "j" && $0.flags.isSuperset(of: hyper) } }
        record(name, plain != nil && again != nil, "j plain after Secure Input: \(plain != nil); Hyper works again: \(again != nil) (\(recorder.summary))", nil)
    }

    private func sequenceCancelSwallowsKey() async {
        guard await focusRecorder() else { return }
        _ = await hyperChord(["k"])
        let overlayShown = await waitUntil(timeout: 1) { self.context.overlay.isVisible } != nil
        await pressKey("x")
        await pause(200)
        let leaked = recorder.events.contains { $0.characters == "x" }
        let passed = overlayShown && !leaked && !context.overlay.isVisible
        record(
            "Unknown key cancels a pending sequence and is swallowed",
            passed,
            "overlay shown: \(overlayShown), x leaked: \(leaked), overlay still visible: \(context.overlay.isVisible)",
            nil
        )
    }

    private func sequenceTimesOut() async {
        guard await focusRecorder() else { return }
        _ = await hyperChord(["k"])
        let hidden = await waitUntil(timeout: 4.5) { !self.context.overlay.isVisible }
        await pressKey("u")
        let delivered = await waitUntil(timeout: 1) { self.recorder.events.contains { $0.characters == "u" && $0.flags.isDisjoint(with: [.command, .control, .option]) } }
        record(
            "Pending sequence times out, next key passes through",
            hidden != nil && delivered != nil,
            "overlay hid after \(hidden.map { String(format: "%.0f ms", $0.milliseconds) } ?? "never"), u delivered: \(delivered != nil)",
            hidden?.milliseconds
        )
    }

    /// Types like a fast typist: the query starts right after the hotkey,
    /// before the launcher is known to be on screen. Uses skil.li's own Hyper
    /// (F19): with synthetic events, Raycast's Hyper Key keeps adding ⌘⌃⌥⇧
    /// to the keys that follow, which a real keyboard does not show.
    private func launcherHotkeyAndSearch() async {
        guard await focusRecorder() else { return }
        let spaceDown = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "saf" {
            await pressKey(character)
        }
        let shown = context.launcher.isVisible ? ContinuousClock.now - spaceDown : nil
        let found = await waitUntil(timeout: 1) { self.context.launcher.topResultName == "Safari" }
        let leaked = recorder.events.contains { "saf".contains($0.characters) && !$0.characters.isEmpty }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let closed = await waitUntil(timeout: 1) { !self.context.launcher.isVisible }
        record(
            "✦Space then typing \"saf\" at once finds Safari, Esc closes (F19)",
            found != nil && closed != nil && !leaked,
            "top result \"\(context.launcher.topResultName ?? "none")\", keys leaked to previous window: \(leaked), closed: \(closed != nil)",
            shown?.milliseconds
        )
    }

    /// The real Caps Lock path (through Raycast's Hyper Key here).
    private func launcherHotkeyToggles() async {
        guard await focusRecorder() else { return }
        let spaceDown = await hyperChord([" "])
        let opened = await waitUntil(timeout: 1) { self.context.launcher.isVisible }
        let openLatency = opened.map { _ in ContinuousClock.now - spaceDown }
        await pause(100)
        _ = await hyperChord([" "])
        let closed = await waitUntil(timeout: 1) { !self.context.launcher.isVisible }
        record(
            "✦Space with the real trigger opens, ✦Space again closes",
            opened != nil && closed != nil,
            "opened: \(opened != nil), closed: \(closed != nil)",
            openLatency?.milliseconds
        )
    }

    private func cleanShotRouting() async {
        let name = "✦K → C routes to CleanShot capture area"
        guard let commands = context.aiActions.systemCommands else {
            record(name, false, "no SystemCommands", nil)
            return
        }
        let saved = commands.openAppLink
        commands.openAppLink = { _ in }
        commands.lastAppLink = nil
        defer { commands.openAppLink = saved }
        guard await focusRecorder() else { return }
        _ = await hyperChord(["k", "c"])
        let installed = LinkedApps.installed("cleanshot") != nil
        let routed: Duration?
        if installed {
            routed = await waitUntil(timeout: 1) { commands.lastAppLink?.absoluteString == "cleanshot://capture-area" }
        } else {
            // Not installed: the card says so, and no link is opened.
            await pause(500)
            routed = commands.lastAppLink == nil ? .zero : nil
        }
        record(
            name,
            routed != nil,
            "opened: \(commands.lastAppLink?.absoluteString ?? "nothing"), CleanShot installed: \(installed) (dry run, no capture started)",
            routed?.milliseconds
        )
    }

    /// CleanShot X's commands are launcher rows (docs/apps.md): “capture
    /// front” lists Capture Front Window, ⌘K its captures, ↩ opens
    /// CleanShot's capture-area with the test window's frame. Dry run:
    /// the link is read, nothing captured.
    private func cleanShotFromLauncher() async {
        let name = "CleanShot X in the launcher: “capture front” lists Capture Front Window, ⌘K its captures (copy, save…), ↩ opens capture-area with the front window's frame"
        guard let commands = context.aiActions.systemCommands else {
            record(name, false, "no SystemCommands", nil)
            return
        }
        guard let front = LinkedApp.command(id: "cleanshot.capture-front-window") else {
            record(name, false, "no Capture Front Window command", nil)
            return
        }
        let launcher = context.launcher
        let installed = LinkedApps.installed("cleanshot")
        // Not installed, or a version that does not take it: no row at
        // all, rather than one that fails.
        guard let installed, front.runs(onVersion: installed.version) else {
            guard await openLauncher() else {
                record(name, false, "the launcher did not open", nil)
                return
            }
            for character in "capture front" { await pressKey(character) }
            await pause(300)
            let rows = launcher.resultTitles
            await closeLauncher()
            let why = installed.map { "CleanShot X \($0.version ?? "?") does not take it" } ?? "CleanShot X is not installed here"
            record(name, !rows.contains(front.title), "\(why): rows \(rows.prefix(8).joined(separator: ", "))", nil)
            return
        }
        let saved = commands.openAppLink
        commands.openAppLink = { _ in }
        commands.lastAppLink = nil
        defer { commands.openAppLink = saved }
        guard await openLauncher() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        for character in "capture front" { await pressKey(character) }
        guard await waitUntil(timeout: 1, { launcher.topResultName == "Capture Front Window" }) != nil else {
            let top = launcher.topResultName
            await closeLauncher()
            record(name, false, "top result “\(top ?? "none")”", nil)
            return
        }
        await pressKey("k", flags: .maskCommand)
        _ = await waitUntil(timeout: 1) { launcher.isShowingActions }
        let actions = launcher.shownActions.map(\.title)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !launcher.isShowingActions }
        // The window in front once the launcher is gone: the test window.
        let expected = CleanShot.frame(of: WindowManager.topLeft(window.frame), screens: NSScreen.screens.map(\.frame)) ?? []
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let ran = await waitUntil(timeout: 2) { commands.lastAppLink != nil }
        let link = commands.lastAppLink
        let items = link.flatMap { URLComponents(url: $0, resolvingAgainstBaseURL: false)?.queryItems } ?? []
        let read = items.map { AppLinkCommand.Parameter($0.name, $0.value ?? "") }
        // The captures this version takes (`action=`, 4.7+).
        let variants = front.variants(forVersion: installed.version).map(\.title)
        let listsVariants = variants.allSatisfy(actions.contains)
        let passed = ran != nil && link?.host() == "capture-area" && read == expected && listsVariants && !launcher.isVisible
        record(name, passed,
               "⌘K: \(actions.joined(separator: ", ")); opened \(link?.absoluteString ?? "nothing"), expected the frame \(expected.map { "\($0.name)=\($0.value)" }.joined(separator: "&")) (dry run)",
               ran?.milliseconds)
    }

    // MARK: - Apple's Shortcuts

    /// The test shortcut (docs/apps.md): one Text action, "echo:" then its
    /// input, so each run says what it was given. Signed and imported for
    /// the test, deleted after it: none of the Mac's own shortcuts is run.
    private static let echoShortcut = "skil.li Self-Test Echo"

    /// The user's shortcuts as rows (docs/apps.md, Next apps 1), on a test
    /// shortcut imported for it: found by name with Shortcuts' accessory,
    /// ↩ shows what it gave back; ⌘K Run with the Selection gives it the
    /// test window's selection, Edit in Shortcuts listed; a key with the
    /// selection; its link asks first, then runs; Ask runs it on the
    /// selection; `list_shortcuts` and `run_shortcut`. Then deleted.
    private func appleShortcutsRun() async {
        let name = "Shortcuts: a shortcut is a row (“Shortcuts”); ↩ runs it (Shortcuts asks once to hand its text over), its text in the card; ⌘K Run with the Selection, Edit in Shortcuts; a key on the selection; its link asks, then runs; Ask; run_shortcut"
        let shortcutsWasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: AppleShortcut.bundleID).isEmpty
        let (imported, why) = await importEchoShortcut()
        guard let shortcut = imported else {
            record(name, false, why, nil)
            return
        }
        await appleShortcutChecks(shortcut, name: name, imported: why)
        await deleteEchoShortcut(shortcut, shortcutsWasRunning: shortcutsWasRunning)
    }

    /// The shortcuts as Apple's tool lists them now, read off the main
    /// thread (a process, ~10 ms).
    private static func readShortcuts() async -> [AppleShortcut] {
        await Task.detached(priority: .utility) { AppleShortcuts.read() }.value
    }

    /// Reads the list every 500 ms until `found` says yes or `seconds` pass.
    private static func pollShortcuts(for seconds: Double, until found: ([AppleShortcut]) -> Bool) async -> Bool {
        let deadline = ContinuousClock.now + .milliseconds(Int(seconds * 1000))
        while ContinuousClock.now < deadline {
            if found(await readShortcuts()) { return true }
            try? await Task.sleep(for: .milliseconds(500))
        }
        return found(await readShortcuts())
    }

    /// Shortcuts' own question before a shortcut hands what it made to
    /// skil.li ("Allow “…” to produce 1 text item?"), answered Always
    /// Allow as a person would, unless the run is `done` first; whether it
    /// was asked within `seconds`.
    private func allowShortcutsOutput(within seconds: Double, unless done: @escaping @MainActor () -> Bool) async -> (asked: Bool, covered: Bool) {
        var answered = false
        var covered = false
        let card = context.aiActions.popover.window
        _ = await waitUntil(timeout: seconds) {
            for view in NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.WorkflowKit.ShortcutsViewService") {
                let root = AXUIElementCreateApplication(view.processIdentifier)
                AXUIElementSetMessagingTimeout(root, 1)
                guard let question = Self.axElements(roles: [kAXButtonRole], under: root, where: { ["Always Allow", "Toujours autoriser"].contains($0) }).first
                else { continue }
                // The card must leave Shortcuts' question in sight.
                if card.isVisible, let button = Self.axFrame(question), let main = NSScreen.screens.first {
                    let cardFrame = CGRect(x: card.frame.minX, y: main.frame.maxY - card.frame.maxY, width: card.frame.width, height: card.frame.height)
                    covered = cardFrame.intersects(button)
                }
                if AXUIElementPerformAction(question, kAXPressAction as CFString) == .success { answered = true }
            }
            return answered || done()
        }
        return (answered, covered)
    }

    private func appleShortcutChecks(_ shortcut: AppleShortcut, name: String, imported why: String) async {
        let launcher = context.launcher
        let popover = context.aiActions.popover
        var details = ["imported: \(why)"]
        /// The card's text once it shows `expected`, then closed.
        func cardSays(_ expected: String, timeout: Double = 8) async -> String {
            _ = await waitUntil(timeout: timeout) { popover.isVisible && popover.shownText == expected }
            let shown = popover.isVisible ? popover.shownText : "no card"
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
            return shown
        }
        /// The test window's text "zebra", selected.
        func selectZebra() async -> Bool {
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            textView.string = "zebra"
            textView.selectAll(nil)
            return true
        }

        // The row: by name, Shortcuts' accessory; ↩ with no input. The
        // first time, Shortcuts asks before handing its text over.
        /// A step that could not start: the check fails, saying where.
        func stopped(_ step: String) {
            record(name, false, (details + ["stopped: \(step)"]).joined(separator: "; "), nil)
        }
        guard await focusTestWindow(), await openLauncher() else { return stopped("the launcher did not open on the test window") }
        for character in "self-test echo" { await pressKey(character) }
        let found = await waitUntil(timeout: 2) { launcher.topResultName == Self.echoShortcut } != nil
        let accessory = launcher.resultAccessories.first ?? ""
        let footer = launcher.shownFooter
        await captureLauncher(as: "launcher-shortcut-row.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let working = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText == "Running “\(Self.echoShortcut)”…" } != nil
        let (askedOnce, covered) = await allowShortcutsOutput(within: 8) { popover.shownText != "Running “\(Self.echoShortcut)”…" }
        let plain = await cardSays("echo:")
        details.append("row first: \(found) (\(accessory)), footer \(footer); ↩: working card \(working), Shortcuts asked to hand its text over: \(askedOnce) (its Always Allow under the card: \(covered)), then “\(plain)”")

        // ⌘K: the selection read as it opened (“zebra”), the editor.
        guard await selectZebra(), await openLauncher() else { return stopped("the launcher did not open over the selection") }
        for character in "self-test echo" { await pressKey(character) }
        _ = await waitUntil(timeout: 2) { launcher.topResultName == Self.echoShortcut }
        _ = await waitUntil(timeout: 1) { launcher.shownSelection == "zebra" }
        await pressKey("k", flags: .maskCommand)
        _ = await waitUntil(timeout: 1) { launcher.isShowingActions }
        let actions = launcher.shownActions.map(\.title)
        await captureLauncher(as: "launcher-shortcut-actions.png")
        for character in "with" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.selectedActionTitle == "Run with the Selection" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let withSelection = await cardSays("echo:zebra")
        details.append("⌘K \(actions.joined(separator: ", ")), with the selection: “\(withSelection)”")

        // A key with the selection (✦K O), read as it runs.
        let store = context.shortcuts
        let key = store.add(.mac(.shortcut(shortcut, withSelection: true)))
        try? store.setKeys(Chord.sequence("hyper+k o"), for: key)
        defer { store.remove(key) }
        guard await selectZebra() else { return stopped("no focus on the test window for the key") }
        _ = await hyperChord(["k", "o"], trigger: Self.ownTriggerKeyCode)
        let keyed = await cardSays("echo:zebra")
        details.append("✦K O on the selection: “\(keyed)”")

        // Its link: asked first (Allow ↩), then it runs.
        var linked = "no link runner"
        var asked = false
        if let links = context.links {
            let link = SkilliLink.run(FeatureCatalog.shortcutEntryID(shortcut.id)).url
            guard await focusTestWindow() else { return stopped("no focus on the test window for the link") }
            textView.string = ""
            let opening = Task { await links.openNow(link) }
            asked = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.contains("link") && popover.shownTitle.contains(Self.echoShortcut) } != nil
                || links.log.last == "asked \(FeatureCatalog.shortcutEntryID(shortcut.id))"
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            await opening.value
            linked = await cardSays("echo:")
            details.append("link \(link.absoluteString): asked \(asked), then “\(linked)”")
        }

        // Ask's pick (real ones in `selftest decide`), on the selection.
        context.aiActions.decisionOverride = AskRouter.Decision(route: .command, confidence: 0.95, menu: [], routes: [(.command, 0.95)],
                                                                command: (.shortcut(shortcut, withSelection: false), 0.95),
                                                                commands: [(.shortcut(shortcut, withSelection: false), 0.95)], label: "Test")
        defer { context.aiActions.decisionOverride = nil }
        var asked2 = "no question in the card"
        if await selectZebra(), await openAsk() {
            for character in "lance mon raccourci echo" { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            asked2 = await cardSays("echo:zebra")
        }
        details.append("Ask: “\(asked2)”")

        // Agents.
        let tools = context.tools.tools
        let listed = (try? await tools.call("list_shortcuts", arguments: [:], run: nil))?.split(separator: "\n").contains { $0 == Self.echoShortcut } == true
        let ran = (try? await tools.call("run_shortcut", arguments: ["name": Self.echoShortcut, "input": "camille"], run: nil)) ?? "failed"
        let unknown = (try? await tools.call("run_shortcut", arguments: ["name": "No Such Shortcut Selftest"], run: nil)) == nil
        details.append("list_shortcuts: \(listed), run_shortcut: “\(ran)”, an unknown one refused: \(unknown)")

        // From a skillie (skillies/README.md): its row's link, and the
        // agents' action with an input or the selection.
        let fromSkillies = await shortcutFromSkillies(shortcut)
        details.append(fromSkillies.detail)

        // A shortcut left by a run that stopped was allowed already.
        let passed = found && accessory == "Shortcuts" && working && (askedOnce || why.hasPrefix("left")) && !covered
            && actions.starts(with: ["Run", "Run with the Selection", "Edit in Shortcuts"])
            && actions.contains("Copy Link") && withSelection == "echo:zebra" && plain == "echo:" && keyed == "echo:zebra" && asked
            && linked == "echo:" && asked2 == "echo:zebra" && listed && ran == "echo:camille" && unknown && fromSkillies.passed
        record(name, passed, details.joined(separator: "; ") + "; launcher-shortcut-row.png, launcher-shortcut-actions.png", nil)
    }

    /// The test shortcut run from three skillies, as the launcher runs
    /// them: `open "skilli://run/system:shortcut:<id>"` (the link asks in the
    /// card, ↩), then `"$SKILLI_CLI" call run_shortcut` with `input=` and
    /// with `selection=true` (each call asked in the skillie's card, ↩),
    /// branching on its exit; each one's last line in the card.
    private func shortcutFromSkillies(_ shortcut: AppleShortcut) async -> (passed: Bool, detail: String) {
        guard let links = context.links else { return (false, "from skillies: no link runner") }
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let (mode, right) = (settings.mode, settings.override(for: "run_shortcut"))
        // Ask Before Changes, run_shortcut not made Always: each call asks.
        settings.mode = .auto
        settings.setOverride(nil, for: "run_shortcut")
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-shortcut-skillies-\(getpid())", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        links.opensFromMacOS = true
        defer {
            settings.mode = mode
            settings.setOverride(right, for: "run_shortcut")
            links.opensFromMacOS = false
            try? FileManager.default.removeItem(at: folder)
        }
        func skillie(_ name: String, _ body: String) -> ScriptCommand? {
            let file = folder.appendingPathComponent("\(name).sh")
            let text = "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Shortcut From Skillie \(name)\n# @skilli.mode compact\n\(body)\n"
            try? text.write(to: file, atomically: true, encoding: .utf8)
            try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: file.path)
            return ScriptCommand.parse(text, path: file.path)
        }
        /// Run as the launcher does, the test window's text `selected`; ↩
        /// on each card that asks (after the moment an unprompted card
        /// leaves to the app); the card's text once it says `expected`.
        func run(_ command: ScriptCommand?, selected: String, expecting expected: String) async -> String {
            guard let command else { return "not a skillie" }
            guard await focusTestWindow() else { return "no focus" }
            window.makeFirstResponder(textView)
            textView.string = selected
            textView.selectAll(nil)
            var asked = 0
            var seen: (text: String, at: ContinuousClock.Instant)?
            // The card answered last: ↩ once, however long it stays.
            var answered: String?
            context.aiActions.runScript?(command, false)
            _ = await waitUntil(timeout: 40) {
                guard popover.isVisible, popover.phase == .approving else {
                    answered = nil
                    return popover.isVisible && popover.shownText == expected
                }
                let text = popover.shownText
                if text == answered { return false }
                answered = nil
                if seen?.text != text {
                    seen = (text, .now)
                } else if let at = seen?.at, .now - at > .milliseconds(900) {
                    answered = text
                    seen = nil
                    asked += 1
                    Task { await self.pressKey(nil, code: CGKeyCode(kVK_Return)) }
                }
                return false
            }
            let said = popover.isVisible ? popover.shownText : "no card"
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 2) { !popover.isVisible }
            return "asked \(asked)×, “\(said)”"
        }
        let call = { (argument: String) in
            "if said=$(\"$SKILLI_CLI\" call run_shortcut name=\"\(Self.echoShortcut)\" \(argument) 2>&1); then echo \"Got: $said\"; else echo \"Failed: ${said%%$'\\n'*}\"; fi"
        }
        let link = await run(skillie("Link", "open \"\(SkilliLink.run(FeatureCatalog.shortcutEntryID(shortcut.id)).url.absoluteString)\""),
                             selected: "", expecting: "echo:")
        let input = await run(skillie("Input", call("input=zebra")), selected: "", expecting: "Got: echo:zebra")
        let selection = await run(skillie("Selection", call("selection=true")), selected: "camille", expecting: "Got: echo:camille")
        let passed = [link, input, selection].allSatisfy { $0.hasPrefix("asked 1×") }
            && link.hasSuffix("“echo:”") && input.hasSuffix("“Got: echo:zebra”") && selection.hasSuffix("“Got: echo:camille”")
        return (passed, "from skillies: open its link \(link); call with input= \(input); call with selection=true \(selection)")
    }

    /// The test shortcut, imported as a person would: its file signed by
    /// Apple's tool (`shortcuts sign`), opened, Shortcuts' Add button
    /// pressed (Accessibility), then read back. One left by a run that
    /// stopped is used again.
    private func importEchoShortcut() async -> (AppleShortcut?, String) {
        if let left = await Self.readShortcuts().first(where: { $0.name == Self.echoShortcut }) { return (left, "left by an earlier run") }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-shortcut-\(getpid())", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        let unsigned = folder.appendingPathComponent("unsigned.shortcut")
        let signed = folder.appendingPathComponent("\(Self.echoShortcut).shortcut")
        guard let file = Self.echoShortcutFile(), (try? file.write(to: unsigned)) != nil else { return (nil, "the shortcut file was not written") }
        let signing = try? await ChildProcess.run(URL(fileURLWithPath: AppleShortcut.tool),
                                                  ["sign", "--mode", "anyone", "--input", unsigned.path, "--output", signed.path], timeout: 60)
        guard signing?.status == 0, FileManager.default.fileExists(atPath: signed.path) else {
            return (nil, "shortcuts sign failed: \(signing?.output.suffix(200) ?? "did not run")")
        }
        NSWorkspace.shared.open(signed)
        var pressed = false
        _ = await waitUntil(timeout: 15) {
            pressed = Self.pressShortcutsImport()
            return pressed
        }
        var found: AppleShortcut?
        _ = await Self.pollShortcuts(for: 15) { list in
            found = list.first { $0.name == Self.echoShortcut }
            return found != nil
        }
        // Shortcuts came forward to ask: the test window again.
        _ = await focusTestWindow()
        return (found, found == nil ? "not listed after the import (Add pressed: \(pressed))" : "signed, opened, Add pressed")
    }

    /// The shortcut file: a Text action whose text is "echo:" and the
    /// shortcut's input (an attachment at its sixth character), text in.
    private static func echoShortcutFile() -> Data? {
        let text: [String: Any] = [
            "Value": ["attachmentsByRange": ["{5, 1}": ["Type": "ExtensionInput"]], "string": "echo:\u{FFFC}"],
            "WFSerializationType": "WFTextTokenString"
        ]
        let workflow: [String: Any] = [
            "WFWorkflowActions": [["WFWorkflowActionIdentifier": "is.workflow.actions.gettext", "WFWorkflowActionParameters": ["WFTextActionText": text]]],
            "WFWorkflowClientVersion": "2607.0.2",
            "WFWorkflowIcon": ["WFWorkflowIconGlyphNumber": 59511, "WFWorkflowIconStartColor": 463140863],
            "WFWorkflowImportQuestions": [Any](),
            "WFWorkflowInputContentItemClasses": ["WFStringContentItem"],
            "WFWorkflowMinimumClientVersion": 900,
            "WFWorkflowMinimumClientVersionString": "900",
            "WFWorkflowTypes": [Any](),
            "WFWorkflowHasShortcutInputVariables": true,
            "WFWorkflowOutputContentItemClasses": ["WFStringContentItem"]
        ]
        return try? PropertyListSerialization.data(fromPropertyList: workflow, format: .binary, options: 0)
    }

    /// Presses the Add button of Shortcuts' window that asks to add a
    /// shortcut opened from a file.
    private static func pressShortcutsImport() -> Bool {
        guard let app = NSRunningApplication.runningApplications(withBundleIdentifier: AppleShortcut.bundleID).first else { return false }
        let root = AXUIElementCreateApplication(app.processIdentifier)
        AXUIElementSetMessagingTimeout(root, 1)
        return ["Add This Shortcut", "Add Shortcut", "Ajouter ce raccourci"].contains { pressButton($0, under: root) }
    }

    /// The test shortcut deleted, as a person would in Shortcuts: its
    /// editor closed, its tile clicked in the library, Edit → Delete (and
    /// Delete in a question, if Shortcuts asks one: macOS 27's does not).
    /// Shortcuts quit again when the test opened it.
    private func deleteEchoShortcut(_ shortcut: AppleShortcut, shortcutsWasRunning: Bool) async {
        let name = "Shortcuts: the test shortcut deleted afterwards (Edit → Delete in Shortcuts)"
        func shortcutsApp() -> NSRunningApplication? {
            NSRunningApplication.runningApplications(withBundleIdentifier: AppleShortcut.bundleID).first
        }
        // Quit meanwhile: its own link opens it again.
        if shortcutsApp() == nil, let library = URL(string: "shortcuts://") {
            NSWorkspace.shared.open(library)
            _ = await waitUntil(timeout: 10) { shortcutsApp() != nil }
            await pause(1500)
        }
        guard let app = shortcutsApp() else {
            record(name, false, "Shortcuts did not open", nil)
            return
        }
        let root = AXUIElementCreateApplication(app.processIdentifier)
        AXUIElementSetMessagingTimeout(root, 1)
        var steps: [String] = []
        // Its editor (Edit in Shortcuts) and a window that imported it
        // (untitled, its "More, <name>" button; the library has a title).
        for window in Self.shortcutsWindows(root) where Self.axString(window, kAXTitleAttribute) == Self.echoShortcut
            || Self.axString(window, kAXTitleAttribute).isEmpty
            && !Self.axElements(roles: [kAXButtonRole], under: window, where: { $0.hasSuffix(", " + Self.echoShortcut) }).isEmpty {
            var button: CFTypeRef?
            if AXUIElementCopyAttributeValue(window, kAXCloseButtonAttribute as CFString, &button) == .success, let button,
               CFGetTypeID(button) == AXUIElementGetTypeID() {
                AXUIElementPerformAction(unsafeDowncast(button, to: AXUIElement.self), kAXPressAction as CFString)
                steps.append("its window closed")
            }
        }
        // Shortcuts' "What's new", shown once over its library.
        for button in Self.axElements(roles: [kAXButtonRole], under: root, where: { _ in true })
            where Self.axString(button, kAXIdentifierAttribute) == "Primary Button" {
            AXUIElementPerformAction(button, kAXPressAction as CFString)
            steps.append("what's new closed")
        }
        app.activate()
        _ = await waitUntil(timeout: 2) { NSWorkspace.shared.frontmostApplication?.processIdentifier == app.processIdentifier }
        await pause(500)
        let source = CGEventSource(stateID: .hidSystemState)
        func post(_ types: [CGEventType], at point: CGPoint) async {
            for type in types {
                CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
                await pause(60)
            }
        }
        /// Its tile in the library; the pointer kept off the tiles (over
        /// one, its name becomes its run button's).
        func tile() async -> AXUIElement? {
            if let library = Self.shortcutsWindows(root).first(where: { !Self.axString($0, kAXTitleAttribute).isEmpty
                && Self.axString($0, kAXTitleAttribute) != Self.echoShortcut }), let frame = Self.axFrame(library) {
                await post([.mouseMoved], at: CGPoint(x: frame.midX, y: frame.minY + 12))
                await pause(300)
            }
            return Self.axElements(roles: [kAXButtonRole], under: root, where: { $0 == Self.echoShortcut }).first
        }
        // Its library closed: Shortcuts' own link opens it again.
        if await tile() == nil, let library = URL(string: "shortcuts://") {
            NSWorkspace.shared.open(library)
            await pause(1500)
            steps.append("library opened")
        }
        guard let tile = await tile(), let frame = Self.axFrame(tile) else {
            await captureWindow(of: app.processIdentifier, as: "shortcuts-delete-library.png")
            let titles = Self.shortcutsWindows(root).map { "“\(Self.axString($0, kAXTitleAttribute))”" }
            record(name, false, (steps + ["no tile in the library; windows \(titles)"]).joined(separator: ", "), nil)
            _ = await focusTestWindow()
            return
        }
        // A click selects it (Accessibility's press does not); a second
        // one when the first only brought its window forward. Only with
        // Shortcuts in front: a click never lands in another app.
        let point = CGPoint(x: frame.midX, y: frame.midY)
        var delete: MenuReader.Item?
        for _ in 0..<2 where delete == nil {
            app.activate()
            guard await waitUntil(timeout: 2, { NSWorkspace.shared.frontmostApplication?.processIdentifier == app.processIdentifier }) != nil else {
                let front = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "none"
                record(name, false, (steps + ["Shortcuts not in front (\(front) is): nothing clicked"]).joined(separator: ", "), nil)
                _ = await focusTestWindow()
                return
            }
            await post([.mouseMoved, .leftMouseDown, .leftMouseUp], at: point)
            await pause(600)
            delete = MenuReader.items(pid: app.processIdentifier).first {
                $0.components.count == 2 && ["Supprimer", "Delete"].contains($0.components[1]) && $0.isEnabled
            }
        }
        guard let delete, AXUIElementPerformAction(delete.element, kAXPressAction as CFString) == .success else {
            await captureWindow(of: app.processIdentifier, as: "shortcuts-delete-click.png")
            let front = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "none"
            record(name, false, (steps + ["Edit → Delete not enabled after the click at \(point) (tile \(frame)), in front \(front)"]).joined(separator: ", "), nil)
            _ = await focusTestWindow()
            return
        }
        steps.append("Edit → Delete")
        // Its question: Delete.
        var confirmed = false
        _ = await waitUntil(timeout: 3) {
            confirmed = ["Supprimer", "Delete", "Supprimer le raccourci", "Delete Shortcut"].contains { Self.pressButton($0, under: root) }
            return confirmed
        }
        steps.append("asked, Delete pressed: \(confirmed)")
        let gone = await Self.pollShortcuts(for: 5) { !$0.contains(shortcut) }
        if gone, !shortcutsWasRunning {
            app.terminate()
            steps.append("Shortcuts quit")
        }
        _ = await focusTestWindow()
        record(name, gone, steps.joined(separator: ", "), nil)
    }

    /// Shortcuts' windows through Accessibility.
    private static func shortcutsWindows(_ root: AXUIElement) -> [AXUIElement] {
        var value: CFTypeRef?
        AXUIElementCopyAttributeValue(root, kAXWindowsAttribute as CFString, &value)
        return (value as? [AXUIElement]) ?? []
    }

    /// A skillie reaches CleanShot X as agents do (skillies/README.md):
    /// `Skilli call run_action` with a variant opens its link
    /// (`action=copy`); a variant it does not take is said with the ones
    /// it takes; upload asks in the card even with run_action allowed for
    /// good, and esc opens nothing. Dry run: nothing captured.
    private func cleanShotFromSkillies() async {
        let name = "CleanShot X from a skillie: `Skilli call run_action variant=copy` opens capture-area?action=copy; a wrong variant lists the right ones and opens nothing; upload asks every time, through run_action or open_url, even right after run_action was allowed in the card"
        guard let commands = context.aiActions.systemCommands else {
            record(name, false, "no SystemCommands", nil)
            return
        }
        guard LinkedApps.installed("cleanshot") != nil else {
            record(name, true, "CleanShot X is not installed here: nothing to call", nil)
            return
        }
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let saved = (link: commands.openAppLink, mode: settings.mode, right: settings.override(for: "run_action"))
        commands.openAppLink = { _ in }
        commands.lastAppLink = nil
        settings.mode = .auto
        settings.setOverride(.always, for: "run_action")
        defer {
            commands.openAppLink = saved.link
            settings.mode = saved.mode
            settings.setOverride(saved.right, for: "run_action")
        }
        guard await focusTestWindow() else { return }
        let copy = await skilliCall("run_action", #"{"id":"cleanshot.capture-area","variant":"copy"}"#)
        let opened = await waitUntil(timeout: 2) { commands.lastAppLink?.absoluteString == "cleanshot://capture-area?action=copy" } != nil
        commands.lastAppLink = nil
        let wrong = await skilliCall("run_action", #"{"id":"cleanshot.capture-area","variant":"autoscroll"}"#)
        await pause(300)
        let wrongOpenedNothing = commands.lastAppLink == nil
        async let upload = skilliCall("run_action", #"{"id":"cleanshot.capture-area","variant":"upload"}"#)
        let asked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let declined = await upload
        await pause(300)
        let uploadOpenedNothing = commands.lastAppLink == nil
        // The same upload as CleanShot's own link through open_url: asked
        // too. Its opening is stubbed: nothing leaves even if it was not.
        var openedURLs: [URL] = []
        let savedOpen = context.tools.tools.openURL
        context.tools.tools.openURL = { openedURLs.append($0) }
        defer { context.tools.tools.openURL = savedOpen }
        _ = await waitUntil(timeout: 2) { !popover.isVisible }
        async let viaURL = skilliCall("open_url", #"{"url":"cleanshot://capture-area?action=upload"}"#)
        let askedURL = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let declinedURL = await viaURL
        // run_action asked in the card and allowed there: the upload still
        // asks on its own (that Allow does not answer for it).
        settings.setOverride(nil, for: "run_action")
        commands.lastAppLink = nil
        _ = await waitUntil(timeout: 2) { !popover.isVisible }
        async let afterAllow = skilliCall("run_action", #"{"id":"cleanshot.capture-area","variant":"upload"}"#)
        let toolAsked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        let toolTitle = popover.shownTitle
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        _ = await waitUntil(timeout: 2) { !popover.isVisible || popover.shownTitle != toolTitle }
        let uploadAsked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let declinedAfterAllow = await afterAllow
        await pause(300)
        let passed = copy.status == 0 && opened && wrong.status == 1 && wrong.output.contains("copy, save") && wrongOpenedNothing
            && asked && declined.status == 1 && declined.output.contains("declined") && uploadOpenedNothing
            && askedURL && declinedURL.status == 1 && openedURLs.isEmpty
            && toolAsked && uploadAsked && declinedAfterAllow.status == 1 && commands.lastAppLink == nil
        record(name, passed,
               "copy: exit \(copy.status), opened \(opened); wrong variant: exit \(wrong.status) “\(wrong.output.prefix(80))”, opened nothing: \(wrongOpenedNothing); upload asked: \(asked), esc → exit \(declined.status) “\(declined.output.prefix(40))”, opened nothing: \(uploadOpenedNothing); open_url upload asked: \(askedURL), esc → exit \(declinedURL.status), opened \(openedURLs.count); run_action allowed in the card (\(toolAsked)), upload still asked: \(uploadAsked), esc → exit \(declinedAfterAllow.status), link \(commands.lastAppLink?.absoluteString ?? "none")",
               nil)
    }

    /// Files into CleanShot X (docs/apps.md, Order 4), on scratch files:
    /// ⌘K on a file row lists what CleanShot opens for its type (a PNG all
    /// three, an MP4 only Quick Access, a text file none); an image in the
    /// clipboard history, through real keys (✦C, ⌘K, "pin in", ↩), pins
    /// the history's own file; a skillie's `run_action file=` opens it,
    /// says what does not fit and opens nothing then. Then the Finder
    /// selection (`cleanShotOpensFinderSelection`). Dry run: the links are
    /// read, CleanShot opens nothing.
    private func cleanShotOpensFiles() async {
        let name = "Files into CleanShot X: ⌘K on a file by its type (PNG: Annotate, Pin, Quick Access; MP4: Quick Access; text: none); a clipboard image pinned from ⌘K by keys; `run_action file=` opens it, or says why not and opens nothing"
        guard let commands = context.aiActions.systemCommands else {
            record(name, false, "no SystemCommands", nil)
            return
        }
        let manager = FileManager.default
        let folder = manager.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/cleanshot-files", isDirectory: true)
        let png = folder.appendingPathComponent("Selftest Shot.png")
        let mp4 = folder.appendingPathComponent("Selftest Demo.mp4")
        let text = folder.appendingPathComponent("Selftest Notes.txt")
        let picture = NSImage(size: NSSize(width: 120, height: 80), flipped: false) { rect in
            NSColor.systemTeal.setFill()
            rect.fill()
            return true
        }
        guard let tiff = picture.tiffRepresentation, let pngData = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]),
              (try? manager.createDirectory(at: folder, withIntermediateDirectories: true)) != nil,
              (try? pngData.write(to: png)) != nil, (try? Data("not a video".utf8).write(to: mp4)) != nil,
              (try? Data("notes".utf8).write(to: text)) != nil else {
            record(name, false, "could not write the scratch files", nil)
            return
        }
        defer { try? manager.removeItem(at: folder) }
        let launcher = context.launcher
        func row(_ url: URL) -> LauncherItem {
            .file(FileSearch.File(url: url, name: url.lastPathComponent, kind: "", modified: .now, used: nil))
        }
        func inCleanShot(_ url: URL) -> [String] {
            launcher.actions(for: row(url)).map(\.title).filter { $0.contains("CleanShot") }
        }
        guard let installed = LinkedApps.installed("cleanshot") else {
            // Not installed: no file row offers it.
            let none = [png, mp4].allSatisfy { inCleanShot($0).isEmpty }
            record(name, none, "CleanShot X is not installed here: ⌘K on a PNG and an MP4 offers it nowhere: \(none)", nil)
            return
        }
        let saved = commands.openAppLink
        commands.openAppLink = { _ in }
        commands.lastAppLink = nil
        defer { commands.openAppLink = saved }

        // ⌘K on a file row, by its type and CleanShot's version: Quick
        // Access and Capture Text on a file came with 3.8.1, Pin before.
        func runs(_ id: String) -> Bool { LinkedApp.command(id: id)?.runs(onVersion: installed.version) == true }
        let (quickRuns, textRuns) = (runs("cleanshot.quick-access"), runs("cleanshot.capture-text"))
        let expected = (png: LinkedApp.cleanShot.fileActions(opening: png.path, version: installed.version).map(\.action.title),
                        mp4: LinkedApp.cleanShot.fileActions(opening: mp4.path, version: installed.version).map(\.action.title))
        let byType = inCleanShot(png) == expected.png && inCleanShot(mp4) == expected.mp4 && inCleanShot(text).isEmpty
            && expected.png.contains("Pin in CleanShot") && expected.mp4 == (quickRuns ? ["Add to CleanShot Quick Access"] : [])
        launcher.actions(for: row(mp4)).first { $0.title == "Add to CleanShot Quick Access" }?.run()
        let mp4Added = quickRuns ? Self.opened(commands.lastAppLink, "add-quick-access-overlay", mp4) : commands.lastAppLink == nil

        // An image in the clipboard history: ✦C, found by its words, ⌘K,
        // "pin in" filters, ↩ pins the history's own file.
        var clipDetail = "no clipboard store"
        var clipPinned = false
        if let store = context.clipboard.store {
            let marker = "cleanshot selftest \(Int.random(in: 1000...9999))"
            if let added = try? store.add(.init(kind: .image, text: "", imageData: pngData, size: "120×80", app: "com.apple.Preview",
                                                appName: "Preview", hash: ClipboardHistory.hash("image", Data(marker.utf8)))),
               let kept = store.imageURL(added.item) {
                defer { try? store.delete(added.item.id) }
                try? store.setOCR(marker, for: added.item.id)
                commands.lastAppLink = nil
                if await focusTestWindow() {
                    _ = await hyperChord(["c"], trigger: Self.ownTriggerKeyCode)
                    _ = await waitUntil(timeout: 1) { launcher.isVisible && launcher.isInClipboard }
                    for character in marker { await pressKey(character) }
                    // ⌘K and ↩ only on the test's own copy and action: another
                    // would paste or run for real.
                    let found = await waitUntil(timeout: 2) { launcher.selectedResultTitle?.contains(marker) == true } != nil
                    var listed: [String] = []
                    var filtered = false
                    var ran = false
                    if found {
                        await pressKey("k", flags: .maskCommand)
                        _ = await waitUntil(timeout: 1) { launcher.isShowingActions }
                        listed = launcher.shownActions.map(\.title)
                        for character in "pin in" { await pressKey(character) }
                        filtered = await waitUntil(timeout: 1) { launcher.shownActions.first?.title == "Pin in CleanShot" } != nil
                    }
                    if filtered {
                        await pressKey(nil, code: CGKeyCode(kVK_Return))
                        ran = await waitUntil(timeout: 2) { commands.lastAppLink != nil } != nil
                    }
                    clipPinned = found && expected.png.allSatisfy(listed.contains) && filtered && ran
                        && Self.opened(commands.lastAppLink, "pin", kept) && !launcher.isVisible
                    clipDetail = "found: \(found), ⌘K: \(listed.joined(separator: ", ")); “pin in” → \(filtered); opened \(commands.lastAppLink?.absoluteString ?? "nothing")"
                    await closeLauncher()
                } else {
                    clipDetail = "the test window lost focus"
                }
            } else {
                clipDetail = "could not add an image to the history"
            }
        }
        guard await focusTestWindow() else { return }

        // A skillie: `run_action file=`.
        let settings = context.tools.settings
        let savedRights = (mode: settings.mode, right: settings.override(for: "run_action"))
        settings.mode = .auto
        settings.setOverride(.always, for: "run_action")
        defer {
            settings.mode = savedRights.mode
            settings.setOverride(savedRights.right, for: "run_action")
        }
        func arguments(_ id: String, _ file: String) -> String {
            let data = (try? JSONSerialization.data(withJSONObject: ["id": id, "file": file])) ?? Data()
            return String(decoding: data, as: UTF8.self)
        }
        commands.lastAppLink = nil
        let pinCall = await skilliCall("run_action", arguments("cleanshot.pin", png.path))
        let pinOpened = Self.opened(commands.lastAppLink, "pin", png)
        commands.lastAppLink = nil
        let wrongType = await skilliCall("run_action", arguments("cleanshot.pin", mp4.path))
        let noFile = await skilliCall("run_action", arguments("cleanshot.capture-area", png.path))
        let relative = await skilliCall("run_action", arguments("cleanshot.pin", png.lastPathComponent))
        let gone = await skilliCall("run_action", arguments("cleanshot.pin", folder.appendingPathComponent("Gone.png").path))
        // An empty `file` (a skillie's "$1" left out): refused, not the
        // Finder selection.
        let empty = await skilliCall("run_action", arguments("cleanshot.pin-selected-image", ""))
        let refusedOpenedNothing = commands.lastAppLink == nil
        let quickCall = await skilliCall("run_action", arguments("cleanshot.quick-access", mp4.path))
        let quickOpened = Self.opened(commands.lastAppLink, "add-quick-access-overlay", mp4)
        // Capture Text on a file, its variant kept.
        commands.lastAppLink = nil
        let textData = (try? JSONSerialization.data(withJSONObject: ["id": "cleanshot.capture-text", "variant": "nolinebreaks", "file": png.path])) ?? Data()
        let textCall = await skilliCall("run_action", String(decoding: textData, as: UTF8.self))
        let textOpened = Self.opened(commands.lastAppLink, "capture-text", png)
            && commands.lastAppLink?.query()?.hasPrefix("linebreaks=false&") == true
        let skillies = pinCall.status == 0 && pinOpened && wrongType.status == 1 && wrongType.output.contains(CleanShot.images.said)
            && noFile.status == 1 && noFile.output.contains("takes no file") && relative.status == 1 && relative.output.contains("full path")
            && gone.status == 1 && empty.status == 1 && empty.output.contains("empty") && refusedOpenedNothing
            && (quickRuns ? quickCall.status == 0 && quickOpened : quickCall.status == 1)
            && (textRuns ? textCall.status == 0 && textOpened : textCall.status == 1)
        record(name, byType && mp4Added && clipPinned && skillies,
               "⌘K, PNG: \(inCleanShot(png).joined(separator: ", ")); MP4: \(inCleanShot(mp4).joined(separator: ", ")); text: \(inCleanShot(text).count) (by type: \(byType)), MP4 → Quick Access: \(mp4Added); clipboard image pinned: \(clipPinned) (\(clipDetail)); run_action pin: exit \(pinCall.status) opened \(pinOpened), an MP4 to Pin: exit \(wrongType.status) “\(wrongType.output.prefix(70))”, Capture Area with a file: exit \(noFile.status), a relative path: exit \(relative.status), a file gone: exit \(gone.status) “\(gone.output.prefix(60))”, an empty file: exit \(empty.status), opened nothing: \(refusedOpenedNothing); Quick Access an MP4: exit \(quickCall.status) opened \(quickOpened); Capture Text one line on the PNG: exit \(textCall.status) opened \(textOpened) (dry run, CleanShot X \(installed.version ?? "?"))",
               nil)
        await cleanShotOpensFinderSelection(png: png, mp4: mp4, commands: commands)
    }

    /// The Finder selection into CleanShot X: Finder in front with the
    /// scratch PNG selected, Pin Selected Image from the launcher's row
    /// pins it; an MP4 selected, Pin says what it opens and Add Selected
    /// File to Quick Access adds it. Read through Finder's scripting, which
    /// macOS asks for once: not allowed yet for this build, Finder's answer
    /// is stood in for (the file the test selected) rather than left
    /// waiting on macOS's question; Finder in front, the row and the link
    /// are real either way. Dry run.
    private func cleanShotOpensFinderSelection(png: URL, mp4: URL, commands: SystemCommands) async {
        let name = "Files into CleanShot X from Finder: Pin Selected Image from the launcher over Finder pins the file selected; an MP4 selected is refused for Pin and added to Quick Access"
        guard let pin = LinkedApp.command(id: "cleanshot.pin-selected-image"), let quickAccess = LinkedApp.command(id: "cleanshot.quick-access") else {
            record(name, false, "no Finder selection commands", nil)
            return
        }
        let finder = AutomationAccess.targets.filter { $0.bundleID == FinderSelection.bundleID }
        let automation = await AutomationAccess.states(of: finder)[FinderSelection.bundleID]
        let asksFinder = automation != .notAsked && automation != .denied
        /// What the test selected last, for the stand-in.
        final class Selected { var url: URL? }
        let selected = Selected()
        let saved = (link: commands.openAppLink, selection: commands.finderSelection)
        commands.openAppLink = { _ in }
        if !asksFinder {
            commands.finderSelection = { try FinderSelection.file(selected: { selected.url.map { [$0] } ?? [] }) }
        }
        defer {
            commands.openAppLink = saved.link
            commands.finderSelection = saved.selection
        }
        let launcher = context.launcher
        func selectInFinder(_ url: URL) async -> Bool {
            selected.url = url
            NSWorkspace.shared.activateFileViewerSelecting([url])
            let front = await waitUntil(timeout: 3) { NSWorkspace.shared.frontmostApplication?.bundleIdentifier == FinderSelection.bundleID } != nil
            // Finder selects it once its window is drawn.
            await pause(500)
            return front
        }
        commands.lastAppLink = nil
        var fromRow = false
        var rowDetail = "Finder did not come to the front"
        if await selectInFinder(png) {
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            // Typed only with the launcher open: never into Finder.
            if await waitUntil(timeout: 1, { launcher.isVisible }) != nil {
                for character in "pin selected" { await pressKey(character) }
                // ↩ only on that row: another one would run for real.
                let selected = await waitUntil(timeout: 1) { launcher.selectedResultTitle == pin.title } != nil
                if selected {
                    await pressKey(nil, code: CGKeyCode(kVK_Return))
                    _ = await waitUntil(timeout: 3) { commands.lastAppLink != nil }
                }
                fromRow = selected && Self.opened(commands.lastAppLink, "pin", png)
                rowDetail = "row selected: \(selected) (\(launcher.selectedResultTitle ?? "none")), opened \(commands.lastAppLink?.absoluteString ?? "nothing")"
                if launcher.isVisible { await closeLauncher() }
            } else {
                rowDetail = "the launcher did not open over Finder"
            }
        }
        commands.lastAppLink = nil
        // Quick Access came with CleanShot 3.8.1: refused before.
        let quickRuns = quickAccess.runs(onVersion: LinkedApps.installed("cleanshot")?.version)
        var refused = "not run"
        var quick = false
        if await selectInFinder(mp4) {
            do {
                try await commands.run(.appLink(pin, variant: nil))
                refused = "opened \(commands.lastAppLink?.absoluteString ?? "nothing")"
            } catch {
                refused = error.localizedDescription
            }
            _ = try? await commands.run(.appLink(quickAccess, variant: nil))
            quick = quickRuns ? Self.opened(commands.lastAppLink, "add-quick-access-overlay", mp4) : commands.lastAppLink == nil
        }
        closeFinderWindow(named: png.deletingLastPathComponent().lastPathComponent)
        _ = await focusTestWindow()
        record(name, fromRow && refused.contains(CleanShot.images.said) && quick,
               "Pin Selected Image from the launcher over Finder: \(rowDetail); an MP4 to Pin: “\(refused)”; to Quick Access: \(quick); Finder's selection \(asksFinder ? "read from Finder" : "stood in for: Automation → Finder is \(automation == .denied ? "refused" : "not asked yet") for this build") (dry run)", nil)
    }

    /// `link` is CleanShot's `host` on `file` (as `filepath`), whichever
    /// way its folder is written (/var is /private/var).
    private static func opened(_ link: URL?, _ host: String, _ file: URL) -> Bool {
        guard let link, link.host() == host,
              let path = URLComponents(url: link, resolvingAgainstBaseURL: false)?.queryItems?.first(where: { $0.name == "filepath" })?.value
        else { return false }
        return URL(fileURLWithPath: path).resolvingSymlinksInPath().path == file.resolvingSymlinksInPath().path
    }

    /// Closes the Finder window showing `folder` (the one the test opened),
    /// through Accessibility: its close button pressed.
    private func closeFinderWindow(named folder: String) {
        guard let finder = NSRunningApplication.runningApplications(withBundleIdentifier: FinderSelection.bundleID).first else { return }
        let app = AXUIElementCreateApplication(finder.processIdentifier)
        AXUIElementSetMessagingTimeout(app, 0.5)
        var windows: CFTypeRef?
        AXUIElementCopyAttributeValue(app, kAXWindowsAttribute as CFString, &windows)
        for window in (windows as? [AXUIElement]) ?? [] {
            var title: CFTypeRef?
            AXUIElementCopyAttributeValue(window, kAXTitleAttribute as CFString, &title)
            guard (title as? String) == folder else { continue }
            var button: CFTypeRef?
            AXUIElementCopyAttributeValue(window, kAXCloseButtonAttribute as CFString, &button)
            if let button, CFGetTypeID(button) == AXUIElementGetTypeID() {
                AXUIElementPerformAction(unsafeDowncast(button, to: AXUIElement.self), kAXPressAction as CFString)
            }
        }
    }

    /// App files (docs/apps.md, "App files"), dry run, in the self-test's
    /// own Apps folder: a test app's file (TextEdit's bundle id, a scheme
    /// of its own, its links made up), a file that is not one and one that
    /// names CleanShot X's id. The test app is read, the two others left
    /// out with why; its commands are launcher rows (↩ opens its link), ⌘K
    /// lists its variant, the Catalog lists them, `run_action` runs them (a
    /// variant too) and what asks first asks (esc: nothing opened), its
    /// link runs and the asking one asks, Ask runs one and asks for the
    /// other; Settings → Apps lists it and the two files left out, its page
    /// (Documentation, Show File); an import link shows an app whole, Add
    /// writes its file; `create_app_link` refuses a scheme the app does not
    /// open and adds Notes' links. Links read, nothing opened.
    private func appFilesFromFiles() async {
        let name = "App files: a test app read, a broken file and a clash left out with why; its rows (↩), ⌘K variant, Catalog, run_action (variant; asks first, esc), its links (one asks), Ask (one asks); Settings → Apps lists it and the files left out, its page; an import link shows it whole, Add writes it; create_app_link refuses a scheme the app does not open, adds Notes' links"
        guard let commands = context.aiActions.systemCommands, let folder = LinkedApps.folder else {
            record(name, false, "no SystemCommands or no Apps folder", nil)
            return
        }
        let manager = FileManager.default
        let launcher = context.launcher
        let popover = context.aiActions.popover
        let toolSettings = context.tools.settings
        func write(_ object: [String: Any], as file: String) -> Bool {
            guard let text = try? LinkedAppFile.text(object) else { return false }
            return (try? text.write(to: folder.appendingPathComponent(file), atomically: true, encoding: .utf8)) != nil
        }
        let app: [String: Any] = [
            "id": "selftest-notes", "name": "Selftest Notes", "shortName": "Selftest", "bundleID": "com.apple.TextEdit", "scheme": "x-skilli-selftest",
            "documentation": "https://example.com/selftest-notes/links", "note": "Its links are made up for the self-test: nothing opens them.",
            "commands": [
                ["id": "today", "path": "show/today", "title": "Selftest Today", "description": "Shows today's selftest notes",
                 "words": ["zebrafish", "aujourd'hui"], "symbol": "sun.max", "group": "Show"],
                ["id": "new-note", "path": "x-callback-url/create", "title": "New Selftest Note", "description": "Opens a new selftest note",
                 "symbol": "square.and.pencil", "query": [["name": "open_note", "value": "yes"]],
                 "variants": [["id": "pinned", "title": "New Pinned Selftest Note", "label": "Pinned", "symbol": "pin",
                               "query": [["name": "pin", "value": "yes"]]]], "group": "Write"],
                ["id": "share", "path": "/share/all", "title": "Share Selftest Notes", "description": "Sends every selftest note away",
                 "symbol": "square.and.arrow.up", "asksFirst": true, "group": "Write"]
            ]
        ]
        var broken = app
        broken["id"] = "selftest-broken"
        broken["commands"] = [["id": "open", "path": "open", "description": "Opens it"]]
        var clash = app
        clash["id"] = "cleanshot"
        try? manager.createDirectory(at: folder, withIntermediateDirectories: true)
        guard write(app, as: "Selftest Notes.json"), write(broken, as: "Broken.json"), write(clash, as: "Clash.json") else {
            record(name, false, "could not write the test files in \(folder.path)", nil)
            return
        }
        let saved = (link: commands.openAppLink, mode: toolSettings.mode, action: toolSettings.override(for: "run_action"),
                     create: toolSettings.override(for: "create_app_link"))
        commands.openAppLink = { _ in }
        commands.lastAppLink = nil
        toolSettings.mode = .auto
        toolSettings.setOverride(.always, for: "run_action")
        toolSettings.setOverride(.always, for: "create_app_link")
        defer {
            commands.openAppLink = saved.link
            toolSettings.mode = saved.mode
            toolSettings.setOverride(saved.action, for: "run_action")
            toolSettings.setOverride(saved.create, for: "create_app_link")
            context.aiActions.decisionOverride = nil
            for file in (try? manager.contentsOfDirectory(atPath: folder.path)) ?? [] {
                try? manager.removeItem(at: folder.appendingPathComponent(file))
            }
            LinkedApps.readFiles(force: true)
            LinkedApps.read()
            launcher.reloadSources()
        }
        LinkedApps.read()
        launcher.reloadSources()
        var details: [String] = []
        let read = LinkedApps.installed("selftest-notes") != nil
        let problems = LinkedApps.problems.sorted { $0.file < $1.file }
        let leftOut = problems.map(\.file) == ["Broken.json", "Clash.json"]
            && problems.first?.message.contains("“title” is missing") == true && problems.last?.message.contains("CleanShot X's already") == true
        details.append("read: \(read); left out: " + problems.map { "\($0.file) “\($0.message)”" }.joined(separator: ", "))
        let today = "x-skilli-selftest://show/today"
        let pinned = "x-skilli-selftest://x-callback-url/create?open_note=yes&pin=yes"

        // A launcher row: found by its title, ↩ opens its link.
        var rowRan = false
        var accessory = ""
        if await focusTestWindow(), await openLauncher() {
            for character in "selftest today" { await pressKey(character) }
            if await waitUntil(timeout: 1, { launcher.topResultName == "Selftest Today" }) != nil {
                accessory = launcher.resultAccessories.first ?? ""
                await pressKey(nil, code: CGKeyCode(kVK_Return))
                rowRan = await waitUntil(timeout: 2) { commands.lastAppLink?.absoluteString == today } != nil
            } else {
                details.append("top row “\(launcher.topResultName ?? "none")”")
                await closeLauncher()
            }
        }
        details.append("its row ↩: \(rowRan) (\(accessory))")

        // ⌘K on a row lists its variant, which opens the variant's link.
        var variantRan = false
        var listed: [String] = []
        if let note = LinkedApp.command(id: "selftest-notes.new-note") {
            let actions = launcher.actions(for: .system(.appLink(note, variant: nil), title: note.title))
            listed = actions.map(\.title)
            commands.lastAppLink = nil
            actions.first { $0.title == "New Pinned Selftest Note" }?.run()
            variantRan = await waitUntil(timeout: 2) { commands.lastAppLink?.absoluteString == pinned } != nil
        }
        details.append("⌘K: \(listed.prefix(4).joined(separator: ", ")), the variant ran: \(variantRan)")

        // The Catalog.
        let entries = FeatureCatalog.entries(context.settings.freshContext().catalogInput())
        let inCatalog = entries.contains { $0.id == "system:link:selftest-notes.today" && $0.group == .apps }
        details.append("in the Catalog: \(inCatalog)")

        // Agents and skillies: a variant; what asks first asks, esc opens nothing.
        commands.lastAppLink = nil
        let call = await skilliCall("run_action", #"{"id":"selftest-notes.new-note","variant":"pinned"}"#)
        let called = await waitUntil(timeout: 2) { commands.lastAppLink?.absoluteString == pinned } != nil && call.status == 0
        commands.lastAppLink = nil
        _ = await waitUntil(timeout: 2) { !popover.isVisible }
        async let share = skilliCall("run_action", #"{"id":"selftest-notes.share"}"#)
        let callAsked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        let callTitle = popover.shownTitle
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let declined = await share
        await pause(300)
        let callOpenedNothing = commands.lastAppLink == nil && declined.status == 1
        details.append("run_action variant: \(called); share asked: \(callAsked) “\(callTitle)”, esc → exit \(declined.status), opened nothing \(callOpenedNothing)")

        // Its links: one runs at once, the one that asks first asks.
        var linkRan = false
        var linkAsked = false
        if let links = context.links {
            _ = await waitUntil(timeout: 2) { !popover.isVisible }
            commands.lastAppLink = nil
            await links.openNow(SkilliLink.run("system:link:selftest-notes.today").url)
            linkRan = await waitUntil(timeout: 2) { commands.lastAppLink?.absoluteString == today } != nil
            commands.lastAppLink = nil
            let opening = Task { await links.openNow(SkilliLink.run("system:link:selftest-notes.share").url) }
            linkAsked = await waitUntil(timeout: 2) { links.log.last == "asked system:link:selftest-notes.share" } != nil
            await pause(300)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            await opening.value
            linkAsked = linkAsked && links.log.last == "declined system:link:selftest-notes.share" && commands.lastAppLink == nil
        }
        details.append("link runs: \(linkRan), the asking one asked and declined: \(linkAsked)")

        // Ask: one runs, the one that asks first asks in the card.
        var askRan = false
        var askAsked = false
        if let todayCommand = LinkedApp.command(id: "selftest-notes.today"), let shareCommand = LinkedApp.command(id: "selftest-notes.share") {
            for (command, expectRun) in [(todayCommand, true), (shareCommand, false)] {
                let action = MacAction.appLink(command, variant: nil)
                context.aiActions.decisionOverride = AskRouter.Decision(route: .command, confidence: 0.95, menu: [], routes: [(.command, 0.95)],
                                                                        command: (action, 0.95), commands: [(action, 0.95)], label: "Test")
                commands.lastAppLink = nil
                _ = await waitUntil(timeout: 2) { !popover.isVisible }
                guard await focusTestWindow(), await openAsk() else { continue }
                for character in "selftest" { await pressKey(character) }
                await pressKey(nil, code: CGKeyCode(kVK_Return))
                if expectRun {
                    askRan = await waitUntil(timeout: 4) { commands.lastAppLink?.absoluteString == today } != nil
                } else {
                    askAsked = await waitUntil(timeout: 4) { popover.isVisible && popover.shownQuestion?.text.contains("Share Selftest Notes") == true } != nil
                    await pressKey(nil, code: CGKeyCode(kVK_Escape))
                    await pause(400)
                    askAsked = askAsked && commands.lastAppLink == nil
                }
            }
            context.aiActions.decisionOverride = nil
        }
        details.append("Ask runs: \(askRan), asks first: \(askAsked)")

        // Settings → Apps: the list with it and the files left out, its page.
        let settings = context.settings
        let model = settings.apps
        model.page = nil
        settings.show(pane: .apps)
        _ = await waitUntil(timeout: 2) { settings.isVisible }
        await pause(600)
        let listOverflow = settings.paneOverflow()
        let rowShown = !Self.axElements(roles: [kAXButtonRole], where: { $0 == "Selftest Notes" }).isEmpty
        let leftOutShown = !Self.axElements(roles: [kAXStaticTextRole], where: { $0 == "Broken.json" }).isEmpty
        await captureSettingsBothWays(as: "settings-apps-files-list")
        if settings.scrollPaneToBottom() {
            await pause(300)
            await captureSettingsBothWays(as: "settings-apps-files-list-bottom")
        }
        model.page = .linked("selftest-notes")
        await pause(600)
        let pageOverflow = settings.paneOverflow()
        let pageRows = ["Selftest Today", "New Selftest Note", "Share Selftest Notes"].allSatisfy { title in
            !Self.axElements(roles: [kAXStaticTextRole], where: { $0 == title }).isEmpty
        }
        let pageButtons = ["Documentation", "Show File", "Open Selftest"].allSatisfy { title in
            !Self.axElements(roles: [kAXButtonRole], where: { $0 == title }).isEmpty
        }
        await captureSettingsBothWays(as: "settings-apps-file-page")
        // skil.li's own app files, as shipped: each installed one's page.
        var shippedOverflow: CGFloat = 0
        var shipped: [String] = []
        for installed in LinkedApps.installed() where installed.app.file == nil && installed.app.id != LinkedApp.cleanShot.id {
            model.page = .linked(installed.app.id)
            await pause(500)
            shippedOverflow = max(shippedOverflow, settings.paneOverflow())
            shipped.append(installed.app.name)
            await captureSettingsBothWays(as: "settings-apps-\(installed.app.id)")
        }
        model.page = nil
        await pause(300)
        details.append("Settings: its row \(rowShown), files left out \(leftOutShown), its page's rows \(pageRows), buttons \(pageButtons); skil.li's own: \(shipped.joined(separator: ", ")); past the window: list \(Int(listOverflow)), page \(Int(pageOverflow)), shipped \(Int(shippedOverflow)) pt")

        // An import link: the app whole before Add; Add writes its file.
        var imported: [String: Any] = app
        imported["id"] = "selftest-import"
        imported["name"] = "Selftest Import"
        imported["shortName"] = "Import"
        imported["bundleID"] = "com.apple.Notes"
        imported["scheme"] = "notes"
        var sheet = false
        var pressed = false
        var added = false
        if let text = try? LinkedAppFile.text(imported), let request = AppFileLink.parse(AppFileLink.importLink(for: [text])) {
            await model.receive(request)
            sheet = await waitUntil(timeout: 2) { NSApp.windows.contains { $0.isVisible && $0.isSheet } } != nil && model.pendingImport.count == 1
            await pause(500)
            await captureSettingsBothWays(as: "settings-apps-import")
            pressed = Self.pressLastButton(labelled: "Add App")
            added = await waitUntil(timeout: 2) { LinkedApp.app(id: "selftest-import") != nil } != nil
                && manager.fileExists(atPath: folder.appendingPathComponent("selftest-import.json").path)
            _ = await waitUntil(timeout: 2) { !NSApp.windows.contains { $0.isVisible && $0.isSheet } }
        }
        await closeSettings()
        details.append("import: sheet \(sheet), Add pressed \(pressed), written and read \(added) \(model.importErrors.joined(separator: " "))")
        try? manager.removeItem(at: folder.appendingPathComponent("selftest-import.json"))
        LinkedApps.readFiles(force: true)

        // create_app_link: a scheme Notes does not open is refused; Notes' own is added.
        let commandsJSON = #"[{\"id\":\"open\",\"path\":\"showNote\",\"title\":\"Selftest Agent Note\",\"description\":\"Opens a note\"}]"#
        let refused = await skilliCall("create_app_link",
                                       #"{"app":"Notes","scheme":"x-not-notes","documentation":"https://example.com/notes-links","id":"selftest-agent","commands":"\#(commandsJSON)"}"#)
        let refusedRight = refused.status == 1 && refused.output.contains("does not open") && LinkedApp.app(id: "selftest-agent") == nil
        let created = await skilliCall("create_app_link",
                                       #"{"app":"Notes","scheme":"notes","documentation":"https://example.com/notes-links","id":"selftest-agent","commands":"\#(commandsJSON)"}"#)
        let createdRight = created.status == 0 && LinkedApp.command(id: "selftest-agent.open") != nil
            && manager.fileExists(atPath: folder.appendingPathComponent("selftest-agent.json").path)
        details.append("create_app_link: refused \(refusedRight) “\(refused.output.prefix(70))”, added \(createdRight) “\(created.output.prefix(70))”")
        // Its approval card: every command and variant with the very link it
        // opens; an app too long to show whole is refused, never cut.
        var cardRight = false
        var tooLongRefused = false
        if let definition = SkilliTools.definition("create_app_link") {
            let variantJSON = #"[{"id":"open","path":"showNote","title":"Selftest Card Note","description":"Opens a note","variants":[{"id":"pinned","title":"Selftest Card Pinned","label":"Pinned","query":[{"name":"pin","value":"yes"}]}]}]"#
            let card = SkilliTools.summary(of: definition, arguments: ["app": "Notes", "scheme": "notes", "documentation": "https://example.com/notes-links",
                                                                      "id": "selftest-card", "commands": variantJSON])
            cardRight = card.contains("Selftest Card Note: notes://showNote") && card.contains("Selftest Card Pinned: notes://showNote?pin=yes")
            let many = (1...40).map { #"{"id":"c\#($0)","path":"show/page-\#($0)","title":"Selftest Long Command \#($0)","description":"Opens page \#($0) of the long selftest app"}"# }
            let manyJSON = "[" + many.joined(separator: ",") + "]"
            let long = await skilliCall("create_app_link", String(decoding: (try? JSONSerialization.data(withJSONObject: [
                "app": "Calendar", "scheme": "x-selftest-long", "documentation": "https://example.com/long-links", "id": "selftest-long", "commands": manyJSON
            ])) ?? Data(), as: UTF8.self))
            tooLongRefused = long.status == 1 && long.output.contains("Too many links") && LinkedApp.app(id: "selftest-long") == nil
            details.append("its card: full links \(cardRight); too long refused \(tooLongRefused) “\(long.output.prefix(60))”")
        }

        let passed = read && leftOut && rowRan && accessory == "Selftest Notes" && variantRan && listed.contains("New Pinned Selftest Note") && inCatalog
            && called && callAsked && callOpenedNothing && linkRan && linkAsked && askRan && askAsked
            && rowShown && leftOutShown && pageRows && pageButtons && listOverflow <= 1 && pageOverflow <= 1 && shippedOverflow <= 1
            && sheet && pressed && added && refusedRight && createdRight && cardRight && tooLongRefused
        record(name, passed, details.joined(separator: "; "), nil)
    }

    /// Settings → Apps (docs/apps.md), as the user goes through it: the
    /// list (CleanShot X, Shortcuts), a click on CleanShot X's row pushes its
    /// page (its header, Line breaks in Capture Text, the commands by group);
    /// keys on a command and on a variant (shown under it); the pointer
    /// over a row shows its ⋯, a click opens its menu (Add Shortcut, Add a
    /// Shortcut for, Hide from Search); a hidden command dimmed and out of
    /// the launcher's results; recording in a row, stopped by ⎋ and by
    /// going back, nothing left behind; Settings' search opens the page at
    /// a row; "‹ Apps" goes back; Capture Text's line breaks in its link
    /// (dry run); Shortcuts' page. Light and dark, top and bottom, nothing
    /// past the window. Not installed: none of CleanShot's rows.
    private func appsPaneShown() async {
        let name = "Settings → Apps: the list, CleanShot X's page from its row (header, Line breaks in Capture Text, commands by group, keys, a variant's keys), ⋯ on hover and its menu, Hidden from search, recording stopped by ⎋ and going back, search opens a page's row, ‹ Apps, Shortcuts' page; light and dark, within the window"
        let settings = context.settings
        let preferences = context.preferences
        let store = context.shortcuts
        let model = settings.apps
        model.page = nil
        settings.show(pane: .apps)
        guard await waitUntil(timeout: 2, { settings.isVisible }) != nil else {
            record(name, false, "Settings did not open", nil)
            return
        }
        await pause(600)
        let listOverflow = settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-apps-list")
        guard let installed = LinkedApps.installed("cleanshot") else {
            // Not installed: none of its rows is drawn; Shortcuts' page all the same.
            let rows = CleanShot.commands.filter { settings.search.frames[SettingsSearch.entryAnchor(FeatureCatalog.appLinkEntryID($0.id))] != nil }
            let shortcuts = await appsShortcutsPage()
            model.page = nil
            await closeSettings()
            record(name, listOverflow <= 1 && rows.isEmpty && shortcuts.works,
                   "CleanShot X is not installed here: its rows drawn \(rows.count); past the window \(Int(listOverflow)) pt; \(shortcuts.said)", nil)
            return
        }
        guard let commands = context.aiActions.systemCommands else {
            await closeSettings()
            record(name, false, "no SystemCommands", nil)
            return
        }
        let savedOff = preferences.catalogOff
        let savedLines = preferences.cleanShotTextLineBreaks
        let savedLink = commands.openAppLink
        var added: [String] = []
        defer {
            preferences.catalogOff = savedOff
            preferences.cleanShotTextLineBreaks = savedLines
            commands.openAppLink = savedLink
            for id in added { store.remove(id) }
            model.page = nil
        }
        let cleanShotPage = AppsPage.linked(LinkedApp.cleanShot.id)

        // The list's row, pressed as a click does: CleanShot X's page.
        var pushed = false
        if let row = Self.axElements(roles: [kAXButtonRole], where: { $0 == LinkedApp.cleanShot.name }).first {
            AXUIElementPerformAction(row, kAXPressAction as CFString)
            pushed = await waitUntil(timeout: 2) { model.page == cleanShotPage } != nil
        }
        if !pushed { model.page = cleanShotPage }
        await pause(600)
        let pageOverflow = settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-apps-cleanshot")
        if settings.scrollPaneToBottom() {
            await pause(300)
            await captureSettingsBothWays(as: "settings-apps-cleanshot-bottom")
        }
        settings.scrollPaneToTop()
        await pause(300)

        // Keys on a command and on a variant: Capture Window on ✦K W,
        // Capture and Copy on ✦K X, the variant's row under its command.
        let window = LinkedApp.command(id: "cleanshot.capture-window")
        let area = LinkedApp.command(id: "cleanshot.capture-area")
        var keysShown = false
        var keysProblem = ""
        if let window, let area, let commandKeys = try? [Chord(parsing: "hyper+k"), Chord(parsing: "w")],
           let variantKeys = try? [Chord(parsing: "hyper+k"), Chord(parsing: "x")] {
            let commandID = store.add(.mac(.appLink(window, variant: nil)))
            let variantID = store.add(.mac(.appLink(area, variant: "copy")))
            added += [commandID, variantID]
            do {
                try store.setKeys(commandKeys, for: commandID)
                try store.setKeys(variantKeys, for: variantID)
                keysShown = true
            } catch {
                keysProblem = " (\(error.localizedDescription))"
            }
            await pause(400)
            await captureSettingsBothWays(as: "settings-apps-keys")
        }

        // The pointer over a row: its ⋯ shows; a click opens its menu.
        var hoverMenu: [String] = []
        var moreShown = false
        let source = CGEventSource(stateID: .hidSystemState)
        if let window, let title = Self.axElements(roles: [kAXStaticTextRole], where: { $0 == window.title }).first,
           let titleFrame = Self.axFrame(title) {
            let over = CGPoint(x: titleFrame.maxX + 120, y: titleFrame.midY)
            CGEvent(mouseEventSource: source, mouseType: .mouseMoved, mouseCursorPosition: over, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(500)
            let label = "\(window.title) Options"
            let more = Self.axElements(roles: [kAXMenuButtonRole, kAXPopUpButtonRole, kAXButtonRole], where: { $0 == label }).first
            moreShown = more != nil
            if let directory = context.snapshotDirectory, let png = await settings.snapshotPNG() {
                try? png.write(to: directory.appendingPathComponent("settings-apps-hover.png"))
            }
            if let more, let frame = Self.axFrame(more) {
                let point = CGPoint(x: frame.midX, y: frame.midY)
                for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
                    CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
                    await pause(60)
                }
                await pause(600)
                // Its items only, not the menu bar's.
                let ours = ["Shortcut", "Search", window.title]
                hoverMenu = Self.axElements(roles: [kAXMenuItemRole], where: { title in ours.contains { title.contains($0) } }).compactMap(Self.axTitle)
                if let directory = context.snapshotDirectory, let png = await settings.snapshotPNG(withMenu: true) {
                    try? png.write(to: directory.appendingPathComponent("settings-apps-menu.png"))
                }
                for down in [true, false] {
                    CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
                }
                await pause(400)
            }
        }
        let menuWorks = moreShown && ["Change Shortcut", "Remove Shortcut", "Add a Shortcut for", "Hide from Search"].allSatisfy(hoverMenu.contains)

        // Hidden from search: the row dims; the launcher no longer lists it.
        let restore = LinkedApp.command(id: "cleanshot.restore-recently-closed")
        let restoreEntry = FeatureCatalog.appLinkEntryID("cleanshot.restore-recently-closed")
        var hiddenWorks = false
        if let restore {
            func listed() async -> Bool {
                guard await focusTestWindow(), await openLauncher() else { return false }
                for character in "restore recently" { await pressKey(character) }
                await pause(300)
                let rows = context.launcher.resultTitles
                await closeLauncher()
                return rows.contains(restore.title)
            }
            preferences.catalogOff.insert(restoreEntry)
            settings.show(pane: .apps)
            model.page = cleanShotPage
            await pause(400)
            if settings.scrollPaneToBottom() { await pause(300) }
            await captureSettingsBothWays(as: "settings-apps-hidden")
            let hidden = !(await listed())
            preferences.catalogOff.remove(restoreEntry)
            let back = await listed()
            hiddenWorks = hidden && back
        }

        // Recording in a row (what Add Shortcut calls): ⎋ stops it; going
        // back to the list stops it too; nothing is left behind either way.
        var recorded = false
        var leftBehind = true
        settings.show(pane: .apps)
        model.page = cleanShotPage
        await pause(400)
        if let restore {
            let action = SkilliAction.mac(.appLink(restore, variant: nil))
            model.newShortcut.record(action, store)
            await pause(300)
            recorded = store.recordingID != nil
            if settings.scrollPaneToBottom() { await pause(300) }
            await captureSettingsBothWays(as: "settings-apps-recording")
            store.cancelRecording()
            await pause(300)
            leftBehind = store.entryID(for: action) != nil
            model.newShortcut.record(action, store)
            await pause(300)
            recorded = recorded && store.recordingID != nil
            model.page = nil
            await pause(400)
            leftBehind = leftBehind || store.recordingID != nil || store.entryID(for: action) != nil
        }

        // Settings' search, from another pane: the page, at the row, in sight.
        let anchor = SettingsSearch.entryAnchor(restoreEntry)
        settings.show(pane: .general)
        await pause(300)
        settings.search.reveal(anchor, in: .apps)
        let landed = await waitUntil(timeout: 2) { settings.search.landed == anchor } != nil && model.page == cleanShotPage
        let inSight = await waitUntil(timeout: 1) { settings.anchorVisibility(anchor) > 0.95 } != nil

        // ‹ Apps, atop the page: the list again.
        settings.scrollPaneToTop()
        await pause(300)
        var back = false
        if let button = Self.axElements(roles: [kAXButtonRole], where: { $0 == "Apps" }).first {
            AXUIElementPerformAction(button, kAXPressAction as CFString)
            back = await waitUntil(timeout: 2) { model.page == nil } != nil
        }

        // Capture Text's line breaks, in the link it opens (nothing captured).
        commands.openAppLink = { _ in }
        var links: [String] = []
        if let text = LinkedApp.command(id: "cleanshot.capture-text"), text.runs(onVersion: installed.version) {
            for option in CleanShot.TextLineBreaks.allCases {
                preferences.cleanShotTextLineBreaks = option
                commands.lastAppLink = nil
                _ = try? await commands.run(.appLink(text, variant: nil))
                links.append(commands.lastAppLink?.absoluteString ?? "nothing")
            }
        }
        let linesWork = links == ["cleanshot://capture-text", "cleanshot://capture-text?linebreaks=true", "cleanshot://capture-text?linebreaks=false"]

        let shortcuts = await appsShortcutsPage()

        settings.scrollPaneToTop()
        await closeSettings()
        let fits = listOverflow <= 1 && pageOverflow <= 1
        record(name, fits && pushed && keysShown && menuWorks && hiddenWorks && recorded && !leftBehind && landed && inSight && back && linesWork
                   && shortcuts.works,
               "CleanShot X \(installed.version ?? "?"); past the window: list \(Int(listOverflow)), page \(Int(pageOverflow)) pt; "
                   + "its row pushes its page: \(pushed); keys on a command and a variant: \(keysShown)\(keysProblem); ⋯ on hover: \(moreShown), its menu: \(hoverMenu.joined(separator: ", ")); "
                   + "hidden leaves the results and comes back: \(hiddenWorks); recording: \(recorded), ⎋ or going back left one: \(leftBehind); "
                   + "search lands on the page's row: \(landed), in sight \(inSight); ‹ Apps: \(back); Capture Text's links: \(links.joined(separator: ", ")); "
                   + shortcuts.said,
               nil)
    }

    /// Settings → Apps → Shortcuts: every shortcut as read now drawn as a
    /// row, nothing past the window; captured light and dark, top and bottom.
    private func appsShortcutsPage() async -> (works: Bool, said: String) {
        let settings = context.settings
        let model = settings.apps
        model.page = .shortcuts
        let read = await waitUntil(timeout: 5) { !model.readingShortcuts } != nil
        await pause(500)
        let overflow = settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-apps-shortcuts")
        if settings.scrollPaneToBottom() {
            await pause(300)
            await captureSettingsBothWays(as: "settings-apps-shortcuts-bottom")
        }
        let rows = model.shortcuts.filter { settings.search.frames[SettingsSearch.entryAnchor(FeatureCatalog.shortcutEntryID($0.id))] != nil }.count
        return (read && overflow <= 1 && rows == model.shortcuts.count,
                "Shortcuts' page: read \(read ? "" : "not ")in 5 s, \(model.shortcuts.count) shortcuts, \(rows) rows drawn, past the window \(Int(overflow)) pt")
    }

    // MARK: - Ask's calendar and reminders

    /// Ask's Calendar and Reminders route (or `route`) with the values the
    /// model would read (`AskValues.plan`, `AskValues.contact`; real ones
    /// in `selftest decide`); `nil` puts the model back.
    /// `unsure`: answers the model is unsure of (40 %).
    private func plansRead(_ values: [String: String]?, route: AskRoute = .plans, unsure: Set<String> = []) {
        guard let values else {
            context.aiActions.decisionOverride = nil
            context.aiActions.valuesOverride = nil
            return
        }
        context.aiActions.decisionOverride = AskRouter.Decision(route: route, confidence: 0.95, menu: [], routes: [(route, 0.95)], label: "Test")
        context.aiActions.valuesOverride = Dictionary(uniqueKeysWithValues: values.map { name, choice in
            (name, AskValues.Answer(choice: choice, confidence: unsure.contains(name) ? 0.4 : 0.95))
        })
    }

    /// A span of `sentence`'s words as the model picks it: `<prefix>_start`
    /// and `<prefix>_end` at the first and the last word given.
    private func words(_ sentence: String, _ prefix: String, from first: String, to last: String) -> [String: String] {
        let words = AskValues.words(of: sentence)
        let start = words.firstIndex(of: first) ?? 0
        let end = words.lastIndex(of: last) ?? start
        return ["\(prefix)_start": "word \(start)", "\(prefix)_end": "word \(end)"]
    }

    /// A phrase of `sentence` as the model picks it whole (`<name>`).
    private func phrase(_ sentence: String, _ name: String, _ text: String, longest: Int = 6) -> [String: String] {
        let phrases = AskValues.phrases(of: AskValues.words(of: sentence), longest: longest)
        return [name: phrases.firstIndex(of: text).map { "phrase \($0)" } ?? "none"]
    }

    // MARK: - Shortcuts and learning

    private func keys(_ id: String) -> String? {
        context.shortcuts.config.shortcuts.first { $0.id == id }?.keys
    }

    /// Records ✦J for the launcher the way a user would, then checks ✦J
    /// opens it and ✦Space no longer does.
    private func recordLauncherShortcut() async {
        guard await focusRecorder() else { return }
        let store = context.shortcuts
        store.beginRecording("launcher")
        _ = await hyperChord(["j"], trigger: Self.ownTriggerKeyCode)
        let committed = await waitUntil(timeout: 2.5) { store.recordingID == nil }

        guard await focusRecorder() else { return }
        _ = await hyperChord(["j"], trigger: Self.ownTriggerKeyCode)
        let opensWithNew = await waitUntil(timeout: 1) { self.context.launcher.isVisible } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !self.context.launcher.isVisible }

        guard await focusRecorder() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        await pause(300)
        let opensWithOld = context.launcher.isVisible
        if opensWithOld { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        record(
            "Record a new launcher shortcut: ✦J replaces ✦Space",
            committed != nil && keys("launcher") == "hyper+j" && opensWithNew && !opensWithOld,
            "saved keys: \(keys("launcher") ?? "none"), opens with ✦J: \(opensWithNew), still opens with ✦Space: \(opensWithOld)",
            nil
        )
    }

    private func recordingRejectsConflicts() async {
        guard await focusRecorder() else { return }
        let store = context.shortcuts
        store.beginRecording("uppercase")
        _ = await hyperChord(["j"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 2.5) { store.recordingID == nil }
        let message = store.lastError?.message ?? ""
        record(
            "Recording a used shortcut is refused",
            message.contains(ShortcutStore.launcherTitle) && keys("uppercase") == "hyper+u",
            "error: \(message.isEmpty ? "none" : message), keys kept: \(keys("uppercase") ?? "none")",
            nil
        )
    }

    /// About's health lines from this Mac: one per feature, Accessibility
    /// allowed and the shortcuts working here; the diagnostics carry the
    /// lines only.
    private func aboutSaysWhatWorks() {
        let name = "About: one health line per feature, what works and where to fix it; diagnostics hold the lines only; the build says its number, commit and time"
        let lines = Health.lines(AboutPane.facts(preferences: context.preferences, context: context.settings.freshContext()))
        let byFeature = Dictionary(uniqueKeysWithValues: lines.map { ($0.feature, $0) })
        let text = Health.diagnostics(lines, version: "test", system: "test")
        let fixable = lines.filter { $0.pane != nil }.allSatisfy { line in SettingsPane.allCases.contains { $0.title == line.pane } }
        // The build says which it is: the commit count, the commit, its time.
        let info = Bundle.main.infoDictionary
        let build = info?["CFBundleVersion"] as? String ?? ""
        let stamped = (Int(build) ?? 0) > 1 && (info?["SkilliCommit"] as? String)?.isEmpty == false && info?["SkilliBuildDate"] != nil
        let passed = lines.count == 10 && byFeature["Accessibility"]?.state == .ok && byFeature["Shortcuts"]?.state == .ok
            && text.split(separator: "\n").count == 11 && fixable && stamped
        record(name, passed, lines.map { "\($0.feature) \($0.state.rawValue): \($0.detail)" }.joined(separator: "; ") + "; panes exist: \(fixable)"
                   + "; build \(build) \(info?["SkilliCommit"] as? String ?? "no commit") \(info?["SkilliBuildDate"] as? String ?? "no date")", nil)
    }

    /// A window layout deleted from ⌘K goes at once, its shortcut with
    /// it; ⌘Z while the card shows puts both back (no question first).
    private func layoutDeleteUndoes() async {
        let name = "Window layouts: Delete goes at once with its shortcut; the card offers Undo ⌘Z, ↩ reaches the app, ⌘Z puts both back"
        let arranger = context.arranger
        let store = context.shortcuts
        let layout = arranger.capture("Selftest Undo \(getpid())")
        do { try arranger.store(layout) } catch {
            record(name, false, "could not save a layout: \(error.localizedDescription)", nil)
            return
        }
        let shortcut = store.add(.windowLayout(layout.id))
        defer {
            arranger.delete(layout.id)
            store.remove(shortcut)
        }
        let undo = await undoCardPutsBack("Layout Deleted", named: layout.name) {
            self.context.launcher.onDeleteLayout?(layout)
        } isGone: {
            !arranger.layouts().contains { $0.id == layout.id } && !store.config.shortcuts.contains { $0.id == shortcut }
        } isBack: {
            arranger.layouts().contains { $0.id == layout.id } && store.config.shortcuts.contains { $0.id == shortcut }
        }
        record(name, undo.passed, undo.detail, nil)
    }

    // MARK: - Undo (rule 2)

    /// Every delete of the user's data, each one as its pane or the
    /// launcher does it (`UndoableDeletes`): `selftest undo`, and each in
    /// its feature's scope.
    private func undoChecks() async {
        let steps: [@MainActor () async -> Void] = [
            clipboardForgetUndoes, trashUndoes, layoutDeleteUndoes, reminderDeleteUndoes, eventDeleteUndoes,
            snippetDeleteUndoes, commandDeleteUndoes, quicklinkDeleteUndoes, formDetailsUndo, keyRemovalUndoes,
            serverRemovalUndoes, ruleRemovalUndoes, scheduledAskDeleteUndoes, placeForgetUndoes, aliasRemovalUndoes,
            emojiWordsForgetUndoes, relayTokenRemovalUndoes, shortcutRemovalUndoes
        ]
        for step in steps where !aborted {
            await step()
        }
    }

    /// Rule 2's card for one delete, the test window's recorder standing in
    /// for the app the user is in: gone at once; the card says `title` and
    /// names it (`named`), with Undo ⌘Z and Close esc only; ↩ while it shows
    /// reaches the app and undoes nothing; ⌘Z puts it back, stays in the
    /// card and closes it.
    private func undoCardPutsBack(_ title: String, named: String? = nil, delete: @MainActor () async -> Void,
                                  isGone: @escaping @MainActor () -> Bool, isBack: @escaping @MainActor () -> Bool) async -> (passed: Bool, detail: String) {
        let popover = context.aiActions.popover
        guard await focusRecorder() else { return (false, "the test window lost focus") }
        await delete()
        let gone = await waitUntil(timeout: 2) { isGone() } != nil
        let offered = await waitUntil(timeout: 2) {
            popover.isVisible && popover.shownTitle == title && popover.hintTitles == ["Undo", "Close"] && popover.hintKeys == ["⌘Z", "esc"]
        } != nil
        let shown = "“\(popover.shownTitle)” \(popover.shownText.replacingOccurrences(of: "\n", with: " · ").prefix(70))"
        let says = named.map { popover.shownText.contains(UndoDelete.shortened($0)) } ?? true
        guard await focusRecorder() else { return (false, "the test window lost focus after the delete") }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        await pause(200)
        let returnToApp = recorder.events.contains { $0.keyCode == UInt16(kVK_Return) } && !isBack() && popover.isVisible && popover.shownTitle == title
        await pressKey("z", flags: .maskCommand)
        let back = await waitUntil(timeout: 2) { isBack() } != nil
        let closed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        let zKept = !recorder.events.contains { $0.characters == "z" }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        return (gone && offered && says && returnToApp && back && closed && zKept,
                "gone at once: \(gone); card \(shown), Undo ⌘Z · Close esc: \(offered), names it: \(says); ↩ to the app, nothing undone: \(returnToApp); ⌘Z put it back: \(back), card closed: \(closed), ⌘Z kept from the app: \(zKept)")
    }

    /// ⌘⌫ in the clipboard history, the launcher open: the copy goes, the
    /// card shows under the launcher (never over its rows) and ⌘Z there
    /// brings the row back in it; forgotten again and the launcher closed,
    /// ↩ reaches the app and ⌘Z still brings it back.
    private func clipboardForgetUndoes() async {
        let name = "Clipboard: ⌘⌫ forgets a copy at once; the card under the open launcher takes ⌘Z there (the row comes back); closed, ↩ reaches the app, ⌘Z brings it back"
        guard let store = context.clipboard.store else {
            record(name, false, "no clipboard store", nil)
            return
        }
        let marker = "Undo skilli \(Int.random(in: 1000...9999))"
        guard (try? store.add(.init(kind: .text, text: marker, app: "com.apple.TextEdit", appName: "TextEdit",
                                    hash: ClipboardHistory.hash("text", Data(marker.utf8))))) != nil else {
            record(name, false, "could not add a row", nil)
            return
        }
        defer { for item in store.search(marker) { try? store.delete(item.id) } }
        let launcher = context.launcher
        let popover = context.aiActions.popover
        func kept() -> Bool { store.search(marker).contains { $0.text == marker } }
        func openOnIt() async -> Bool {
            guard await focusTestWindow() else { return false }
            _ = await hyperChord(["c"], trigger: Self.ownTriggerKeyCode)
            _ = await waitUntil(timeout: 1) { launcher.isVisible && launcher.isInClipboard }
            for character in "undo skilli" { await pressKey(character) }
            return await waitUntil(timeout: 1) { launcher.resultTitles.first == marker } != nil
        }

        // The launcher open: the card under it, ⌘Z there.
        let found = await openOnIt()
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let forgot = await waitUntil(timeout: 1) { !kept() && launcher.resultTitles.first != marker } != nil
        let offered = await waitUntil(timeout: 2) { popover.isVisible && popover.shownTitle == "Copy Forgotten" && popover.hintKeys == ["⌘Z", "esc"] } != nil
        let cardGlass = popover.window.frame.insetBy(dx: Theme.glassMargin, dy: Theme.glassMargin)
        let under = launcher.isVisible && !cardGlass.intersects(launcher.glassFrame)
        // Both on the test window, so nothing of the user's shows through.
        let original = window.frame
        window.setFrame(original.union(launcher.window.frame.insetBy(dx: -24, dy: -24)).union(popover.window.frame.insetBy(dx: -24, dy: -24)),
                        display: true)
        await pause(200)
        await saveScreenshot(of: launcher.window, as: "launcher-clipboard-forgotten.png")
        await saveScreenshot(of: popover.window, as: "card-copy-forgotten.png")
        window.setFrame(original, display: true)
        await pressKey("z", flags: .maskCommand)
        let backInLauncher = await waitUntil(timeout: 2) { kept() && launcher.isVisible && launcher.resultTitles.first == marker && !popover.isVisible } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !launcher.isVisible }

        // Closed: ↩ is the app's, ⌘Z the card's.
        let undo = await undoCardPutsBack("Copy Forgotten", named: marker) {
            guard await openOnIt() else { return }
            await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
            _ = await waitUntil(timeout: 1) { !kept() }
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !launcher.isVisible }
        } isGone: {
            !kept()
        } isBack: {
            kept()
        }
        record(name, found && forgot && offered && under && backInLauncher && undo.passed,
               "found: \(found), forgotten: \(forgot), card: \(offered), under the launcher: \(under), ⌘Z in the launcher brought the row back: \(backInLauncher); launcher closed: \(undo.detail); launcher-clipboard-forgotten.png, card-copy-forgotten.png", nil)
    }

    /// ⌘K → Move to Trash on a file: in the Trash at once, ⌘Z moves it back
    /// where it was, as it was.
    private func trashUndoes() async {
        let name = "Files: ⌘K → Move to Trash goes at once; the card offers Undo ⌘Z, ↩ reaches the app, ⌘Z moves it back where it was"
        let manager = FileManager.default
        let folder = manager.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/trash", isDirectory: true)
        let file = folder.appendingPathComponent("Selftest Trash \(Int.random(in: 1000...9999)).txt")
        let content = "skil.li self-test \(UUID().uuidString)"
        do {
            try manager.createDirectory(at: folder, withIntermediateDirectories: true)
            try content.write(to: file, atomically: true, encoding: .utf8)
        } catch {
            record(name, false, "could not write a file: \(error.localizedDescription)", nil)
            return
        }
        final class Moved { var to: URL? }
        let moved = Moved()
        let launcher = context.launcher
        let hook = launcher.onMovedToTrash
        launcher.onMovedToTrash = { original, trashed in
            moved.to = trashed
            hook?(original, trashed)
        }
        defer {
            launcher.onMovedToTrash = hook
            try? manager.removeItem(at: folder)
            if let trashed = moved.to, manager.fileExists(atPath: trashed.path) { try? manager.removeItem(at: trashed) }
        }
        let item = LauncherItem.file(FileSearch.File(url: file, name: file.lastPathComponent, kind: "Plain Text", modified: .now, used: nil))
        guard let action = launcher.actions(for: item).first(where: { $0.title == "Move to Trash" }) else {
            record(name, false, "no Move to Trash in ⌘K: \(launcher.actions(for: item).map(\.title))", nil)
            return
        }
        let undo = await undoCardPutsBack("Moved to Trash", named: file.lastPathComponent) {
            action.run()
        } isGone: {
            !manager.fileExists(atPath: file.path) && moved.to.map { manager.fileExists(atPath: $0.path) } == true
        } isBack: {
            (try? String(contentsOf: file, encoding: .utf8)) == content
        }
        let inTrash = moved.to?.path.contains("/.Trash") == true
        record(name, undo.passed && inTrash, undo.detail + "; it was in the Trash: \(inTrash)", nil)
    }

    /// ⌘⌫ on a reminder (the Reminders mode): deleted at once, nothing
    /// asked; ⌘Z makes it again with its fields, in memory here.
    private func reminderDeleteUndoes() async {
        let name = "Reminders: ⌘⌫ deletes at once, nothing asked; the card offers Undo ⌘Z, ↩ reaches the app, ⌘Z makes it again with its fields"
        guard let book = context.launcher.reminders else {
            record(name, false, "no reminders", nil)
            return
        }
        let due = Calendar.current.date(byAdding: .day, value: 2, to: Calendar.current.startOfDay(for: .now)) ?? .now
        let item = ReminderItem(id: "st-undo", title: "Selftest undo reminder", due: due, list: "Courses", priority: 5, notes: "kept")
        book.testItems = [ReminderItem(id: "st-other", title: "Another"), item]
        defer { book.testItems = nil }
        let undo = await undoCardPutsBack("Reminder Deleted", named: item.title) {
            self.context.launcher.onDeleteReminder?(item)
        } isGone: {
            book.testItems?.contains { $0.id == item.id } == false
        } isBack: {
            book.testItems?.last == item
        }
        record(name, undo.passed, undo.detail, nil)
    }

    /// ⌘⌫ on an event nobody else is invited to: deleted at once, ⌘Z makes
    /// it again; one with invitees still asks (deleting it can tell them).
    private func eventDeleteUndoes() async {
        let name = "Agenda: ⌘⌫ deletes an event without invitees at once (Undo ⌘Z, ↩ to the app, ⌘Z makes it again); with invitees it still asks, esc keeps it"
        guard let book = context.launcher.calendar else {
            record(name, false, "no calendar", nil)
            return
        }
        let start = Calendar.current.date(byAdding: .day, value: 2, to: Calendar.current.startOfDay(for: .now))?.addingTimeInterval(10 * 3_600) ?? .now
        let solo = AgendaEvent(id: "st-solo", title: "Selftest focus time", start: start, end: start.addingTimeInterval(3_600), calendar: "Work",
                               location: "Bureau", notes: "kept")
        let board = AgendaEvent(id: "st-board", title: "Selftest board review", start: start.addingTimeInterval(4 * 3_600),
                                end: start.addingTimeInterval(5 * 3_600), calendar: "Work",
                                attendees: [.init(name: "Paul Martin", email: "paul@example.com")])
        book.testEvents = [solo, board]
        defer { book.testEvents = nil }
        let undo = await undoCardPutsBack("Event Deleted", named: solo.title) {
            self.context.launcher.onDeleteEvent?(solo)
        } isGone: {
            book.testEvents?.contains { $0.id == solo.id } == false
        } isBack: {
            book.testEvents?.first == solo
        }
        let popover = context.aiActions.popover
        guard await focusRecorder() else { return record(name, false, undo.detail + "; the test window lost focus before the event with invitees", nil) }
        context.launcher.onDeleteEvent?(board)
        let asked = await waitUntil(timeout: 2) {
            popover.shownTitle == "Delete Event?" && popover.shownText.contains(board.title) && popover.hintTitles == ["Delete", "Keep"]
        } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let kept = await waitUntil(timeout: 1) { !popover.isVisible } != nil && book.testEvents?.contains { $0.id == board.id } == true
        record(name, undo.passed && asked && kept, undo.detail + "; with invitees: asked \(asked), esc kept it \(kept)", nil)
    }

    /// Settings → Snippets → Delete: the file and its shortcut go; ⌘Z puts
    /// both back.
    private func snippetDeleteUndoes() async {
        let name = "Snippets: Delete goes at once with its shortcut; the card offers Undo ⌘Z, ↩ reaches the app, ⌘Z writes it back as it was"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let library = context.snippets
        let shortcuts = context.shortcuts
        let snippet = library.save(Snippet(id: "", name: "Selftest Undo Snippet", keyword: ";stundo", text: "Kept as written {date}"))
        let shortcut = shortcuts.add(.snippet(snippet.id))
        defer {
            library.delete(snippet.id)
            shortcuts.remove(shortcut)
        }
        let undo = await undoCardPutsBack("Snippet Deleted", named: snippet.name) {
            deletes.snippet(snippet, in: library, shortcuts: shortcuts)
        } isGone: {
            library.snippet(snippet.id) == nil && shortcuts.entryID(for: .snippet(snippet.id)) == nil
        } isBack: {
            library.snippet(snippet.id) == snippet && shortcuts.entryID(for: .snippet(snippet.id)) == shortcut
        }
        record(name, undo.passed, undo.detail, nil)
    }

    /// Settings → Commands → Delete on one of the user's: the command and
    /// its shortcut go; ⌘Z puts both back.
    private func commandDeleteUndoes() async {
        let name = "Commands: Delete goes at once with its shortcut; the card offers Undo ⌘Z, ↩ reaches the app, ⌘Z puts both back"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let model = context.aiCommands
        let command = scratchCommand(prompt: "Selftest undo: shorten {selection}")
        defer { model.delete(command.id) }
        let entries = context.shortcuts.config.shortcuts.filter { $0.action == .aiPrompt(command.id) }.map(\.id)
        let undo = await undoCardPutsBack("Command Deleted", named: command.title) {
            deletes.command(command.id, in: model)
        } isGone: {
            model.library.command(command.id) == nil && !model.commands.contains { $0.id == command.id }
                && !self.context.shortcuts.config.shortcuts.contains { entries.contains($0.id) }
        } isBack: {
            model.library.command(command.id)?.prompt == command.prompt && model.commands.contains { $0.id == command.id }
                && entries.allSatisfy { id in self.context.shortcuts.config.shortcuts.contains { $0.id == id } }
        }
        record(name, undo.passed && !entries.isEmpty, undo.detail + "; shortcut rows: \(entries.count)", nil)
    }

    /// Settings → Catalog → Quicklinks → Delete: the quicklink and its
    /// shortcut go; ⌘Z puts both back.
    private func quicklinkDeleteUndoes() async {
        let name = "Quicklinks: Delete goes at once with its shortcut; the card offers Undo ⌘Z, ↩ reaches the app, ⌘Z puts it back in its place"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let store = context.settings.freshContext().quicklinks
        let shortcuts = context.shortcuts
        let link = Quicklink(name: "Selftest Undo Link", keyword: "stundo", url: "https://example.com/?q={query}")
        store.save(link)
        let shortcut = shortcuts.add(.quicklink(link.id))
        defer {
            store.delete(link.id)
            shortcuts.remove(shortcut)
        }
        let index = store.links.firstIndex(of: link)
        let undo = await undoCardPutsBack("Quicklink Deleted", named: link.name) {
            deletes.quicklink(link, in: store, shortcuts: shortcuts)
        } isGone: {
            !store.links.contains(link) && shortcuts.entryID(for: .quicklink(link.id)) == nil
        } isBack: {
            store.links.firstIndex(of: link) == index && shortcuts.entryID(for: .quicklink(link.id)) == shortcut
        }
        record(name, undo.passed, undo.detail, nil)
    }

    /// Settings → Your Details: an IBAN kept in the Keychain, a field of a
    /// person, a person with theirs; each gone at once with its Keychain
    /// value, back with ⌘Z.
    private func formDetailsUndo() async {
        let name = "Your Details: an IBAN (in the Keychain), a person's field and a person forgotten at once; Undo ⌘Z, ↩ to the app, ⌘Z puts each back with its value"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let preferences = context.preferences
        let saved = preferences.formProfiles
        let iban = FormExtra(label: "IBAN", isSensitive: true)
        let siret = FormExtra(label: "SIRET", isSensitive: false, value: "123 456 789 00012")
        let secret = FormExtra(label: "Social security number", isSensitive: true)
        var person = FormPerson(name: "Selftest Margot", extras: [siret, secret])
        defer {
            for extra in [iban, siret, secret] { FormSecrets.forget(extra) }
            preferences.formProfiles = saved
        }
        preferences.formProfiles.mine.append(iban)
        preferences.formProfiles.others.append(person)
        FormSecrets.save("FR76 3000 6000 0112 3456 7890 189", for: iban)
        FormSecrets.save("1 84 12 75 123 456 78", for: secret)
        var details: [String] = []
        var passed = true

        let mine = await undoCardPutsBack("Field Forgotten", named: "IBAN") {
            deletes.myDetail(iban, in: preferences)
        } isGone: {
            !preferences.formProfiles.mine.contains { $0.id == iban.id } && FormSecrets.value(of: iban) == nil
        } isBack: {
            preferences.formProfiles.mine.last == iban && FormSecrets.value(of: iban) == "FR76 3000 6000 0112 3456 7890 189"
        }
        passed = passed && mine.passed
        details.append("IBAN: \(mine.detail)")

        let field = await undoCardPutsBack("Field Forgotten", named: "SIRET") {
            deletes.detail(siret, of: person.id, in: preferences)
        } isGone: {
            preferences.formProfiles.others.first { $0.id == person.id }?.extras.contains { $0.id == siret.id } == false
        } isBack: {
            preferences.formProfiles.others.first { $0.id == person.id }?.extras.first == siret
        }
        passed = passed && field.passed
        details.append("a person's field: \(field.detail)")

        person = preferences.formProfiles.others.first { $0.id == person.id } ?? person
        let whole = await undoCardPutsBack("Removed from Your Details", named: person.name) {
            deletes.person(person, in: preferences)
        } isGone: {
            !preferences.formProfiles.others.contains { $0.id == person.id } && FormSecrets.value(of: secret) == nil
        } isBack: {
            preferences.formProfiles.others.last == person && FormSecrets.value(of: secret) == "1 84 12 75 123 456 78"
        }
        passed = passed && whole.passed
        details.append("the person: \(whole.detail)")
        record(name, passed, details.joined(separator: " | "), nil)
    }

    /// Settings → SI Accounts → Remove: the Claude API key and a deciding
    /// key (the self-test's own Keychain items), saved again by ⌘Z.
    private func keyRemovalUndoes() async {
        let name = "SI Accounts: Remove takes a key out of the Keychain at once; Undo ⌘Z, ↩ to the app, ⌘Z saves it again (Claude API key, OpenAI key)"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let ai = context.ai
        let before = (claude: ai.removeAPIKey(), openAI: ai.removeDecisionKey(for: .openAI))
        defer {
            ai.removeAPIKey()
            ai.removeDecisionKey(for: .openAI)
            if let key = before.claude { try? ai.saveAPIKey(key) }
            if let key = before.openAI { try? ai.saveDecisionKey(key, for: .openAI) }
        }
        try? ai.saveAPIKey("sk-ant-selftest-undo-0000")
        try? ai.saveDecisionKey("sk-selftest-undo-1111", for: .openAI)
        let claude = await undoCardPutsBack("Key Removed", named: "Claude API key") {
            deletes.apiKey(in: ai)
        } isGone: {
            !ai.hasAPIKey && Keychain.read(account: "selftest-anthropic-api-key") == nil
        } isBack: {
            ai.hasAPIKey && Keychain.read(account: "selftest-anthropic-api-key") == "sk-ant-selftest-undo-0000"
        }
        let openAI = await undoCardPutsBack("Key Removed", named: "OpenAI API key") {
            deletes.decisionKey(.openAI, in: ai)
        } isGone: {
            !ai.hasOpenAIKey && ai.decisionKey(for: .openAI) == nil
        } isBack: {
            ai.hasOpenAIKey && ai.decisionKey(for: .openAI) == "sk-selftest-undo-1111"
        }
        record(name, claude.passed && openAI.passed, "Claude: \(claude.detail) | OpenAI: \(openAI.detail)", nil)
    }

    /// Settings → Tools: a connected server (its token, its tools' rights
    /// and list) and one of the user's tools (its token), back with ⌘Z.
    private func serverRemovalUndoes() async {
        let name = "Tools: a server (token, rights, tools) and one of your tools removed at once; Undo ⌘Z, ↩ to the app, ⌘Z puts all back"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let settings = context.tools.settings
        let server = MCPServerConfig(name: "selftest-undo", url: "https://example.com/mcp", auth: .token)
        let tool = CustomTool(name: "selftest-undo-hook", instructions: "Self-test only", url: "https://example.com/hook")
        settings.saveServer(server)
        settings.auth.setToken("selftest-undo-token", for: server.name)
        settings.setServerToolsForSelfTest([MCPToolInfo(name: "list_things", readOnly: true)], for: server.name)
        settings.setOverride(.never, for: "mcp__selftest-undo__list_things")
        settings.saveCustomTool(tool, token: "selftest-undo-hook-token")
        settings.setOverride(.always, for: tool.name)
        defer {
            settings.removeServer(named: server.name)
            settings.removeCustomTool(named: tool.name)
        }
        let removed = await undoCardPutsBack("Server Removed", named: server.name) {
            deletes.server(server.name, in: settings)
        } isGone: {
            settings.server(named: server.name) == nil && settings.auth.token(for: server.name) == nil
                && settings.override(for: "mcp__selftest-undo__list_things") == nil && settings.serverTools[server.name] == nil
        } isBack: {
            settings.server(named: server.name) == server && settings.auth.token(for: server.name) == "selftest-undo-token"
                && settings.override(for: "mcp__selftest-undo__list_things") == .never && settings.serverTools[server.name]?.count == 1
        }
        let yours = await undoCardPutsBack("Tool Removed", named: tool.name) {
            deletes.customTool(tool.name, in: settings)
        } isGone: {
            settings.customTool(named: tool.name) == nil && settings.token(for: tool.name) == nil
        } isBack: {
            settings.customTool(named: tool.name) == tool && settings.token(for: tool.name) == "selftest-undo-hook-token"
                && settings.override(for: tool.name) == .always
        }
        record(name, removed.passed && yours.passed, "server: \(removed.detail) | your tool: \(yours.detail)", nil)
    }

