    /// An alias removed in Settings → Catalog, and with ⌘K → Remove Alias
    /// in the launcher (it stays open; ⌘Z there gives it back).
    private func aliasRemovalUndoes() async {
        let name = "Aliases: removed in Settings → Catalog and with ⌘K → Remove Alias at once; Undo ⌘Z, ↩ to the app, ⌘Z gives it back"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let preferences = context.preferences
        let saved = preferences.launcherAliases
        defer { preferences.launcherAliases = saved }
        let alias = LauncherAlias(id: "app:/System/Applications/Chess.app", alias: "stzq", title: "Chess")
        preferences.launcherAliases = saved.filter { $0.id != alias.id && $0.alias != alias.alias } + [alias]
        let pane = await undoCardPutsBack("Alias Removed", named: alias.alias) {
            deletes.alias(of: alias.id, in: preferences)
        } isGone: {
            !preferences.launcherAliases.contains(alias)
        } isBack: {
            preferences.launcherAliases.contains(alias)
        }
        // ⌘K → Remove Alias on Chess's row, the launcher open.
        let launcher = context.launcher
        let popover = context.aiActions.popover
        guard await focusTestWindow() else { return record(name, false, "Settings: \(pane.detail) | the test window lost focus before ⌘K", nil) }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "chess" { await pressKey(character) }
        let row = await waitUntil(timeout: 2) { launcher.resultTitles.first == "Chess" } != nil
        let chess = LauncherAlias(id: launcher.results.first?.learningID ?? alias.id, alias: alias.alias, title: "Chess")
        preferences.launcherAliases = saved.filter { $0.id != chess.id && $0.alias != chess.alias } + [chess]
        await pressKey("k", flags: .maskCommand)
        _ = await waitUntil(timeout: 1) { launcher.shownActions.contains { $0.title == "Remove Alias" } }
        for character in "remove al" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let removed = await waitUntil(timeout: 2) { !preferences.launcherAliases.contains(chess) && popover.shownTitle == "Alias Removed" } != nil
        await pressKey("z", flags: .maskCommand)
        let back = await waitUntil(timeout: 2) { preferences.launcherAliases.contains(chess) && !popover.isVisible } != nil
        let stillOpen = launcher.isVisible
        if launcher.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, pane.passed && row && removed && back && stillOpen,
               "Settings: \(pane.detail) | ⌘K: Chess found \(row), removed with the card \(removed), ⌘Z in the launcher gave it back \(back), launcher still open \(stillOpen)", nil)
    }

