    /// A shortcut's ⓧ (an extra one goes with its row) and Keys' Delete:
    /// the keys back with ⌘Z.
    private func shortcutRemovalUndoes() async {
        let name = "Shortcuts: ⓧ and Delete remove a shortcut at once; Undo ⌘Z, ↩ to the app, ⌘Z gives its keys back"
        guard let deletes = context.deletes else { return record(name, false, "no deletes", nil) }
        let store = context.shortcuts
        let first = store.add(.openSettings)
        let extra = store.add(.openSettings)
        defer {
            store.remove(first)
            store.remove(extra)
        }
        guard let chords = try? Chord.sequence("hyper+8"), (try? store.setKeys(chords, for: extra)) != nil else {
            return record(name, false, "could not record ✦8: \(store.lastError?.message ?? "?")", nil)
        }
        func keys(_ id: String) -> [Chord]? { store.config.shortcuts.first { $0.id == id }?.chords }
        let cleared = await undoCardPutsBack("Shortcut Removed", named: chords.map { $0.keycaps.joined() }.joined()) {
            deletes.shortcut(extra, in: store)
        } isGone: {
            !store.config.shortcuts.contains { $0.id == extra }
        } isBack: {
            keys(extra) == chords
        }
        let deleted = await undoCardPutsBack("Shortcut Removed") {
            deletes.shortcut(extra, in: store, deleting: true)
        } isGone: {
            !store.config.shortcuts.contains { $0.id == extra }
        } isBack: {
            keys(extra) == chords
        }
        record(name, cleared.passed && deleted.passed, "ⓧ: \(cleared.detail) | Delete: \(deleted.detail)", nil)
    }

    /// Records ✦K then X for Settings, uses it, then removes it with ⌫.
    private func recordSequenceAndRemove() async {
        guard await focusRecorder() else { return }
        let store = context.shortcuts
        store.beginRecording("settings")
        _ = await hyperChord(["k"], trigger: Self.ownTriggerKeyCode)
        await pressKey("x")
        let committed = await waitUntil(timeout: 2.5) { store.recordingID == nil }
        let saved = keys("settings")
        let recordError = store.lastError?.message ?? "none"

        guard await focusRecorder() else { return }
        _ = await hyperChord(["k"], trigger: Self.ownTriggerKeyCode)
        await pressKey("x")
        let opened = await waitUntil(timeout: 2) { self.context.settings.isVisible && self.context.settings.isKey }
        await closeSettings()

        guard await focusRecorder() else { return }
        store.beginRecording("settings")
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        _ = await waitUntil(timeout: 1) { store.recordingID == nil }
        let removed = keys("settings") == nil

        record(
            "Record a sequence (✦K › X opens Settings), ⌫ removes it",
            committed != nil && saved == "hyper+k x" && opened != nil && removed,
            "saved: \(saved ?? "none"), recording error: \(recordError), opened Settings: \(opened != nil), removed: \(removed)",
            nil
        )
    }

    /// The way people type a chain: Caps Lock held for both keys. The
    /// recorder must save what the engine matches (Hyper only on the first
    /// chord). A direct ✦Y on a second entry runs the same command.
    private func recordChainHoldingHyper() async {
        let name = "Record a chain holding Hyper (✦K then ✦Y) and a direct ✦Y for the same command; both run it"
        let store = context.shortcuts
        guard await focusRecorder() else { return }
        store.beginRecording("settings")
        _ = await hyperChord(["k", "y"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let chain = keys("settings")
        guard await focusRecorder() else { return }
        _ = await hyperChord(["k", "y"], trigger: Self.ownTriggerKeyCode)
        let chainRuns = await waitUntil(timeout: 2) { self.context.settings.isVisible && self.context.settings.isKey } != nil
        await closeSettings()

        let directID = store.add(.openSettings)
        defer {
            store.remove(directID)
            try? store.setKeys(nil, for: "settings")
        }
        guard await focusRecorder() else { return }
        store.beginRecording(directID)
        _ = await hyperChord(["y"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let direct = keys(directID)
        guard await focusRecorder() else { return }
        _ = await hyperChord(["y"], trigger: Self.ownTriggerKeyCode)
        let directRuns = await waitUntil(timeout: 2) { self.context.settings.isVisible && self.context.settings.isKey } != nil
        await closeSettings()

        record(
            name,
            chain == "hyper+k y" && chainRuns && direct == "hyper+y" && directRuns,
            "chain saved: \(chain ?? "none"), runs: \(chainRuns); direct saved: \(direct ?? "none"), runs: \(directRuns)",
            nil
        )
    }

    /// Which comes first for a shortcut macOS owns (System Settings →
    /// Keyboard Shortcuts): its own action or skil.li's event tap. ⌥⌘Space
    /// (Show Finder search window, in Spotlight's section) stands in for
    /// ⌘Space: same owner, same mechanism, and on by default (the mini has
    /// Spotlight's ⌘Space off; macOS's settings are never changed here).
    /// Three presses: nothing of skil.li's on it, skil.li recording, then
    /// skil.li bound to it. Each says what got the key.
    private func macOSShortcutAgainstTheTap() async {
        let name = "A macOS shortcut (⌥⌘Space, Show Finder search window) against skil.li's tap: free, recorded, bound"
        let hotKeys = UserDefaults(suiteName: "com.apple.symbolichotkeys")?.dictionary(forKey: "AppleSymbolicHotKeys")
        let standard = SymbolicHotKey(keyCode: 49, modifiers: 1_572_864)
        guard SymbolicHotKey.read("65", in: hotKeys, standard: standard) == standard else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "Show Finder search window is off or not ⌥⌘Space on this Mac", latencyMs: nil))
            return
        }
        let store = context.shortcuts
        let flags: CGEventFlags = [.maskCommand, .maskAlternate]

        // 1. Free: macOS's alone, unless the tap or the window sees it.
        guard await focusRecorder() else { return }
        var before = Self.finderWindows()
        var axBefore = Self.finderAXWindows()
        await pressHolding(flags, keys: [CGKeyCode(kVK_Space)])
        let freeOpened = await waitUntil(timeout: 2) { !Self.finderWindows().subtracting(before).isEmpty } != nil
        let freeWindowGot = recorder.events.contains { $0.keyCode == UInt16(kVK_Space) }
        await closeFinderWindows(except: before, axBefore: axBefore)

        // 2. Recording: does the tap see it before macOS acts? It does, so
        // the recorder refuses it, naming macOS's and where to free it.
        let scratch = store.add(.openSettings)
        defer { store.remove(scratch) }
        guard await focusRecorder() else { return }
        before = Self.finderWindows()
        axBefore = Self.finderAXWindows()
        store.beginRecording(scratch)
        await pressHolding(flags, keys: [CGKeyCode(kVK_Space)])
        let recordedChord = store.recordedChords.first.map(\.spec)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let recordingOpened = !Self.finderWindows().subtracting(before).isEmpty
        let recordError = store.lastError?.message
        let refused = recordError?.hasPrefix("Used by macOS: Show Finder search window.") == true
            && store.lastError?.keyboardSection == "Spotlight" && keys(scratch) == nil
        await closeFinderWindows(except: before, axBefore: axBefore)

        // 3. Bound (straight in the file's terms, whatever the recorder
        // said): does swallowing it in the tap keep macOS's from acting?
        var config = store.config
        if let index = config.shortcuts.firstIndex(where: { $0.id == scratch }) {
            config.shortcuts[index].keys = "opt+cmd+space"
        }
        store.replaceForSelfTest(config)
        guard await focusRecorder() else { return }
        before = Self.finderWindows()
        axBefore = Self.finderAXWindows()
        await pressHolding(flags, keys: [CGKeyCode(kVK_Space)])
        let boundRan = await waitUntil(timeout: 2) { self.context.settings.isVisible } != nil
        let boundOpened = await waitUntil(timeout: 1) { !Self.finderWindows().subtracting(before).isEmpty } != nil
        let warned = store.warnings[scratch]?.message.hasPrefix("macOS's Show Finder search window has these keys too") == true
        await closeSettings()
        await closeFinderWindows(except: before, axBefore: axBefore)

        record(
            name,
            freeOpened && recordedChord == "opt+cmd+space" && !recordingOpened && refused && boundRan && !boundOpened && warned,
            "free: Finder search opened \(freeOpened), test window got it \(freeWindowGot); recording: tap recorded \(recordedChord ?? "nothing"), Finder search opened \(recordingOpened), refused: \(recordError ?? "no"); hand-edited: skil.li's action ran \(boundRan), Finder search opened \(boundOpened), Settings says it: \(store.warnings[scratch]?.message ?? "nothing")",
            nil
        )
    }

    /// ⌃⌘Space, macOS's Emoji & Symbols key, opens skil.li's emoji picker
    /// instead, by default, as Raycast takes it. Free, macOS has it (what
    /// a text view does with it is said); recorded for any other action it
    /// is refused; recorded for Search Emoji it is kept, with "Replaces
    /// macOS's Emoji & Symbols."; pressed, the picker opens, "red heart" ↩
    /// types ❤️ and no window of macOS's opens; pressed again it closes.
    private func emojiKeyReplacesMacOS() async {
        let name = "⌃⌘Space opens skil.li's emoji picker instead of macOS's Emoji & Symbols; refused for anything else"
        let store = context.shortcuts
        let launcher = context.launcher
        let flags: CGEventFlags = [.maskControl, .maskCommand]
        let space = [CGKeyCode(kVK_Space)]
        guard let entry = store.config.shortcuts.first(where: { $0.action == .searchEmoji }), entry.keys == "ctrl+cmd+space" else {
            record(name, false, "Search Emoji is not ⌃⌘Space in the defaults", nil)
            return
        }
        defer { store.reset(entry.id) }
        func opened(since before: [CGWindowID: String]) -> [String] {
            Self.foreignWindows().filter { before[$0.key] == nil }.values.sorted()
        }

        // 1. Free: macOS's, through the app in front's Edit menu.
        try? store.setKeys(nil, for: entry.id)
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        var before = Self.foreignWindows()
        await pressHolding(flags, keys: space)
        _ = await waitUntil(timeout: 2) { !opened(since: before).isEmpty }
        let freeOpened = opened(since: before)
        if !freeOpened.isEmpty {
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 2) { opened(since: before).isEmpty }
        }

        // 2. Recorded for another action: refused, macOS's named.
        let scratch = store.add(.openSettings)
        guard await focusRecorder() else { store.remove(scratch); return }
        store.beginRecording(scratch)
        await pressHolding(flags, keys: space)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let otherRefusal = store.lastError?.message
        let refused = otherRefusal == "Used by macOS: Emoji & Symbols, which cannot be turned off." && keys(scratch) == nil
        store.remove(scratch)

        // 3. Recorded for Search Emoji: kept, said plainly.
        guard await focusRecorder() else { return }
        store.beginRecording(entry.id)
        await pressHolding(flags, keys: space)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let kept = keys(entry.id) == "ctrl+cmd+space" && store.lastError == nil
        let note = store.warnings[entry.id]
        let said = note?.message == "Replaces macOS's Emoji & Symbols." && note?.isNote == true

        // 4. Pressed: skil.li's picker, an emoji typed, nothing of macOS's.
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        before = Self.foreignWindows()
        await pressHolding(flags, keys: space)
        let picker = await waitUntil(timeout: 1) { launcher.isVisible && launcher.isInEmoji } != nil
        for character in "red heart" { await pressKey(character) }
        let heart = await waitUntil(timeout: 1) {
            let title = launcher.selectedResultTitle?.lowercased() ?? ""
            return title.contains("heart") || title.contains("cœur")
        } != nil
        if heart { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let typed = await waitUntil(timeout: 2) { self.textView.string == "❤️" } != nil
        let boundOpened = opened(since: before)

        // 5. Again closes it.
        guard await focusTestWindow() else { return }
        await pressHolding(flags, keys: space)
        let again = await waitUntil(timeout: 1) { launcher.isVisible && launcher.isInEmoji } != nil
        await pressHolding(flags, keys: space)
        let closed = await waitUntil(timeout: 1) { !launcher.isVisible } != nil
        await closeLauncher()

        // Its row in Keys, with the note under it.
        let settings = context.settings
        let anchor = SettingsSearch.shortcutAnchor(entry.id)
        settings.show(pane: .keys)
        settings.search.reveal(anchor, in: .keys)
        _ = await waitUntil(timeout: 2) { settings.search.landed == anchor }
        _ = await waitUntil(timeout: 1) { settings.anchorVisibility(anchor) > 0.95 }
        // The glow gone (about a second).
        await pause(1_600)
        await captureSettingsBothWays(as: "settings-keys-emoji")
        await closeSettings()

        record(
            name,
            refused && kept && said && picker && heart && typed && boundOpened.isEmpty && again && closed,
            "free: opened \(freeOpened.isEmpty ? "nothing in the test window" : freeOpened.joined(separator: ", ")); another action: \(otherRefusal ?? "kept"); Search Emoji: kept \(kept), says \(note?.message ?? "nothing"); pressed: picker \(picker), heart \(heart), typed “\(textView.string)”, other windows \(boundOpened.isEmpty ? "none" : boundOpened.joined(separator: ", ")); again: open \(again), closed \(closed)",
            nil
        )
    }

    /// On-screen windows of other apps, by number, with their app's name.
    private static func foreignWindows() -> [CGWindowID: String] {
        guard let list = CGWindowListCopyWindowInfo([.optionOnScreenOnly, .excludeDesktopElements], kCGNullWindowID) as? [[String: Any]] else { return [:] }
        let own = ProcessInfo.processInfo.processIdentifier
        var windows: [CGWindowID: String] = [:]
        for info in list {
            guard (info[kCGWindowOwnerPID as String] as? pid_t) != own, let number = info[kCGWindowNumber as String] as? CGWindowID else { continue }
            windows[number] = info[kCGWindowOwnerName as String] as? String ?? "?"
        }
        return windows
    }

    /// The same key twice in a chain, as asked: ⌘Space then
    /// Space, recorded with ⌘ kept down and with ⌘ let go before the second
    /// Space; each saved the same way and run whichever way it is typed.
    /// ⌘Space must be free on this Mac (Spotlight's off on the mini).
    private func sameKeyTwiceInAChain() async {
        let name = "The same key twice in a chain: ⌘Space Space recorded and run with ⌘ held and with ⌘ let go"
        let hotKeys = UserDefaults(suiteName: "com.apple.symbolichotkeys")?.dictionary(forKey: "AppleSymbolicHotKeys")
        if SymbolicHotKey.read("64", in: hotKeys, standard: SymbolicHotKey(keyCode: 49, modifiers: 1_048_576)) != nil {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "Spotlight has ⌘Space on this Mac: skil.li refuses it", latencyMs: nil))
            return
        }
        let store = context.shortcuts
        let space = CGKeyCode(kVK_Space)
        defer { try? store.setKeys(nil, for: "settings") }

        func type(holding: Bool) async {
            if holding {
                await pressHolding(.maskCommand, keys: [space, space])
            } else {
                await pressHolding(.maskCommand, keys: [space])
                await pressKey(nil, code: space)
            }
        }
        func recorded(holding: Bool) async -> String? {
            guard await focusRecorder() else { return nil }
            store.beginRecording("settings")
            await type(holding: holding)
            _ = await waitUntil(timeout: 3) { store.recordingID == nil }
            return keys("settings") ?? store.lastError.map { "refused: \($0.message)" }
        }
        func runs(holding: Bool) async -> Bool {
            guard await focusRecorder() else { return false }
            await type(holding: holding)
            let opened = await waitUntil(timeout: 2) { self.context.settings.isVisible } != nil
            await closeSettings()
            return opened
        }

        let held = await recorded(holding: true)
        let heldRuns = (await runs(holding: true), await runs(holding: false))
        let letGo = await recorded(holding: false)
        let letGoRuns = (await runs(holding: true), await runs(holding: false))
        record(
            name,
            held == "cmd+space space" && letGo == "cmd+space space" && heldRuns == (true, true) && letGoRuns == (true, true),
            "⌘ held: saved \(held ?? "nothing"), runs typed held \(heldRuns.0) / let go \(heldRuns.1); ⌘ let go: saved \(letGo ?? "nothing"), runs typed held \(letGoRuns.0) / let go \(letGoRuns.1)",
            nil
        )
    }

    /// Spotlight's ⌘Space on (the reader swapped: macOS's settings are
    /// never changed here): recording ⌘Space, or ⌘Space Space, for the
    /// launcher is refused, naming Spotlight and where to turn it off, a
    /// button to its settings under the row; turned off, the same keys
    /// record at once; on again, General says the launcher shares them.
    private func macOSShortcutsRefusedThenFreed() async {
        let name = "macOS's shortcuts refused: ⌘Space while Spotlight has it (and ⌘Space Space), recorded once turned off, said when on again"
        let store = context.shortcuts
        guard let launcher = store.launcherEntry?.id else {
            record(name, false, "no launcher entry", nil)
            return
        }
        let spotlightOn: [String: Any] = ["64": ["enabled": true, "value": ["parameters": [32, 49, 1_048_576], "type": "standard"]]]
        let spotlightOff: [String: Any] = ["64": ["enabled": false, "value": ["parameters": [32, 49, 1_048_576], "type": "standard"]]]
        let saved = store.readSystemHotKeys
        defer {
            store.readSystemHotKeys = saved
            store.resetAll()
            context.settings.setAppearance(nil)
        }
        let space = CGKeyCode(kVK_Space)
        func recorded(chain: Bool) async -> (keys: String?, refusal: ShortcutStore.Refusal?) {
            guard await focusRecorder() else { return (nil, nil) }
            store.beginRecording(launcher)
            await pressHolding(.maskCommand, keys: chain ? [space, space] : [space])
            _ = await waitUntil(timeout: 3) { store.recordingID == nil }
            return (keys(launcher), store.lastError)
        }

        store.readSystemHotKeys = { spotlightOn }
        let single = await recorded(chain: false)
        let chained = await recorded(chain: true)
        let message = "Used by macOS: Show Spotlight search. Turn it off in System Settings → Keyboard → Keyboard Shortcuts… → Spotlight."
        let refused = single.refusal?.message == message && single.refusal?.keyboardSection == "Spotlight"
            && chained.refusal?.message == message && single.keys == "hyper+space" && chained.keys == "hyper+space"
        // Settings → Keys says it under the launcher's row, the way out beside.
        context.settings.show(pane: .keys)
        await pause(500)
        let buttons = Self.axElements(roles: [kAXButtonRole, "AXLink"], where: { $0 == "Open Keyboard Settings" })
        let button = !buttons.isEmpty
        await captureSettingsBothWays(as: "settings-keys-refused-by-macos")
        // Pressed: System Settings on Keyboard (its name in the Mac's
        // language), closed again unless it was open.
        let settingsID = "com.apple.systempreferences"
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).isEmpty
        let keyboard = SystemSettingsPanes.pane(id: "com.apple.Keyboard-Settings.extension").map { Set([$0.name] + $0.otherNames) } ?? []
        var keyboardOpened = false
        if let first = buttons.first {
            AXUIElementPerformAction(first, kAXPressAction as CFString)
            keyboardOpened = await waitUntil(timeout: 5) {
                guard let app = NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).first else { return false }
                return Self.focusedWindowTitle(pid: app.processIdentifier).map(keyboard.contains) == true
            } != nil
            if !wasRunning {
                NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).forEach { $0.terminate() }
            }
        }
        await closeSettings()

        store.readSystemHotKeys = { spotlightOff }
        let freed = await recorded(chain: false)
        guard await focusRecorder() else { return }
        await pressHolding(.maskCommand, keys: [space])
        let opens = await waitUntil(timeout: 1) { self.context.launcher.isVisible } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !self.context.launcher.isVisible }

        // Turned on again in System Settings: Settings says it as it opens.
        store.readSystemHotKeys = { spotlightOn }
        context.settings.show(pane: .general)
        await pause(500)
        let warning = store.warnings[launcher]
        await captureSettingsBothWays(as: "settings-general-shares-with-macos")
        await closeSettings()

        record(
            name,
            refused && button && keyboardOpened && freed.keys == "cmd+space" && freed.refusal == nil && opens
                && warning?.message.hasPrefix("macOS's Show Spotlight search has these keys too") == true && warning?.keyboardSection == "Spotlight",
            "on: ⌘Space refused (\(single.refusal?.message ?? "not refused")), ⌘Space Space refused \(chained.refusal != nil), keys kept \(single.keys ?? "none"), Open Keyboard Settings shown \(button), opens Keyboard \(keyboardOpened); off: saved \(freed.keys ?? "none"), opens the launcher \(opens); on again: \(warning?.message ?? "nothing said")",
            nil
        )
    }

    /// The launcher's own keys are refused for global shortcuts (⌘K is its
    /// Actions), and its Open Settings key is checked against them and
    /// against the shortcuts; a hand-edited global ⌘K is said in Settings.
    private func launcherKeysRefused() async {
        let name = "The launcher's keys: ⌘K refused for a shortcut (Actions); Open Settings refused on a shortcut's key and on ⌘K; a hand-edited ⌘K said"
        let store = context.shortcuts
        defer { store.resetAll() }
        guard let k = keyCode("k") else { return }
        func recorded(_ id: String, _ press: () async -> Void) async -> String? {
            guard await focusRecorder() else { return nil }
            store.beginRecording(id)
            await press()
            _ = await waitUntil(timeout: 3) { store.recordingID == nil }
            return store.lastError?.message
        }
        let global = await recorded("settings") { await self.pressHolding(.maskCommand, keys: [k]) }
        let globalKept = keys("settings") == nil
        let openSettingsOnShortcut = await recorded(ShortcutStore.launcherOpenSettingsID) { _ = await self.hyperChord(["u"], trigger: Self.ownTriggerKeyCode) }
        let openSettingsOnActions = await recorded(ShortcutStore.launcherOpenSettingsID) { await self.pressHolding(.maskCommand, keys: [k]) }
        // A file edited by hand: a global ⌘K and ⌘, (the launcher's).
        var config = store.config
        if let index = config.shortcuts.firstIndex(where: { $0.id == "settings" }) { config.shortcuts[index].keys = "cmd+k" }
        if let index = config.shortcuts.firstIndex(where: { $0.id == "clipboard" }) { config.shortcuts[index].keys = "cmd+," }
        store.replaceForSelfTest(config)
        let warnedK = store.warnings["settings"]?.message
        let warnedComma = store.warnings[ShortcutStore.launcherOpenSettingsID]?.message
        record(
            name,
            global == "Used by the launcher: Actions." && globalKept
                && openSettingsOnShortcut?.hasPrefix("Already used by") == true
                && openSettingsOnActions == "Used by the launcher: Actions." && store.config.launcherOpenSettings == "cmd+,"
                && warnedK?.hasPrefix("The launcher's Actions has these keys too") == true && warnedComma?.contains("runs instead, even in the launcher") == true,
            "⌘K for Settings: \(global ?? "accepted"); Open Settings on ✦U: \(openSettingsOnShortcut ?? "accepted"), on ⌘K: \(openSettingsOnActions ?? "accepted"); hand-edited ⌘K: \(warnedK ?? "nothing said"); ⌘, taken by a shortcut: \(warnedComma ?? "nothing said")",
            nil
        )
    }

    /// 2026-10-16: "The launcher is the most important command. It
    /// should not be buried." Its keys are General's first row and the
    /// first of Keys' shortcuts list, under its name, once (asked: not a second
    /// block above the Hyper Key): one setting, recorded in General and
    /// shown in Keys. The status menu says
    /// its real keys, a chain too, nothing without keys; light and dark.
    private func launcherNotBuried() async {
        let name = "The launcher not buried: General's first row, the first of Keys' shortcuts (once, under the Hyper Key), the status menu with its real keys"
        let store = context.shortcuts
        defer {
            store.resetAll()
            context.settings.setAppearance(nil)
        }
        guard let launcher = store.launcherEntry?.id else {
            record(name, false, "no launcher entry", nil)
            return
        }
        func top(_ title: String, roles: [String] = [kAXStaticTextRole]) -> CGFloat? {
            Self.axElements(roles: roles, where: { $0 == title }).compactMap { Self.axFrame($0)?.minY }.min()
        }

        // General: the launcher above Open skil.li at login; recorded there.
        context.settings.show(pane: .general)
        await pause(600)
        let generalRow = top(ShortcutStore.launcherTitle)
        let login = top("Open skil.li at login", roles: [kAXCheckBoxRole, kAXStaticTextRole])
        let generalFirst = generalRow != nil && login != nil && generalRow! < login!
        await captureSettingsBothWays(as: "settings-general")
        guard await focusRecorder() else { return }
        store.beginRecording(launcher)
        _ = await hyperChord(["j"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let recorded = keys(launcher)

        // Keys: once, the first of the shortcuts, under the Hyper Key.
        context.settings.show(pane: .keys)
        await pause(600)
        let keysRow = Self.axElements(roles: [kAXStaticTextRole], where: { $0 == ShortcutStore.launcherTitle }).compactMap { Self.axFrame($0)?.minY }
        // The Hyper Key's section: its header, else its Caps Lock row; the
        // next shortcut of the defaults: Ask's.
        let superKey = top("Hyper Key", roles: [kAXStaticTextRole, "AXHeading"]) ?? top("Caps Lock")
        let askRow = top(store.config.shortcuts.first { $0.id == "ai.ask" }.map { store.title(of: $0) } ?? "")
        let keysFirst = keysRow.count == 1 && superKey != nil && keysRow[0] > superKey! && askRow.map { keysRow[0] < $0 } == true
        let notInList = Self.axElements(roles: [kAXStaticTextRole], where: { $0 == SkilliAction.toggleLauncher.title }).isEmpty
        await captureSettingsBothWays(as: "settings-keys")
        // Launcher: the same row; nothing of macOS's said on the defaults
        // (⌘, is not Minimize on a French layout, where key code 46 types ",").
        context.settings.show(pane: .launcher)
        await pause(600)
        let launcherRow = top(ShortcutStore.launcherTitle) != nil
        // Only the note of the key replaced on purpose (⌃⌘Space).
        let defaultsClean = store.warnings.values.allSatisfy(\.isNote)
        await captureSettingsBothWays(as: "settings-launcher")
        await closeSettings()

        // The status menu: its real keys, read when they change.
        func openTitle() -> String? {
            context.statusMenu()?.items.first { $0.identifier == StatusMenuKeys.open }?.attributedTitle?.string
        }
        let afterRecording = openTitle()
        var captured: [String] = []
        if context.statusItemFrame() != nil {
            for (suffix, appearance) in GlassCheck.appearances {
                context.statusMenu()?.appearance = appearance
                if await openStatusMenu(capture: "status-menu-\(suffix)", highlight: "status-menu-highlighted-\(suffix)") { captured.append(suffix) }
            }
        }
        try? store.setKeys(Chord.sequence("cmd+space space"), for: launcher)
        let chain = openTitle()
        if context.statusItemFrame() != nil {
            context.statusMenu()?.appearance = NSAppearance(named: .aqua)
            _ = await openStatusMenu(capture: "status-menu-chain-light", highlight: nil)
        }
        context.statusMenu()?.appearance = nil
        try? store.setKeys(nil, for: launcher)
        let none = openTitle()

        record(
            name,
            generalFirst && recorded == "hyper+j" && keysFirst && notInList && launcherRow && defaultsClean
                && afterRecording == "\(ShortcutStore.launcherTitle)\t✦ J" && chain == "\(ShortcutStore.launcherTitle)\t⌘ Space › Space"
                && none == ShortcutStore.launcherTitle && (context.statusItemFrame() == nil || captured.count == 2),
            "General: first \(generalFirst), recorded there \(recorded ?? "none"); Keys: first of the shortcuts under the Hyper Key \(keysFirst) (\(keysRow.count) row), not in the list \(notInList); Launcher: its row \(launcherRow), nothing shared on the defaults \(defaultsClean ? "true" : "false: \(store.warnings)"); status menu: \(afterRecording ?? "no item") | \(chain ?? "no item") | without keys \(none ?? "no item"); captured \(context.statusItemFrame() == nil ? "no menu bar icon" : captured.joined(separator: ", "))",
            nil
        )
    }

    /// Opens skil.li's status menu with a real click on its icon, captures
    /// it, then with the pointer on Open skil.li (`highlight`), and leaves
    /// with Escape. Whether it opened.
    private func openStatusMenu(capture: String, highlight: String?) async -> Bool {
        guard let frame = context.statusItemFrame(), let primary = NSScreen.screens.first else { return false }
        let source = CGEventSource(stateID: .hidSystemState)
        let point = CGPoint(x: frame.midX, y: primary.frame.maxY - frame.midY)
        // Never left open: Escape from another thread if the menu holds on.
        let guardTimer = DispatchWorkItem {
            for down in [true, false] {
                CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
            }
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + 10, execute: guardTimer)
        defer { guardTimer.cancel() }
        for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(60)
        }
        await pause(700)
        var opened = false
        if let image = await WindowCapture.openMenuImage() {
            opened = true
            if let directory = context.snapshotDirectory, let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("\(capture).png"))
            }
        }
        if opened, let highlight,
           let item = Self.axElements(roles: [kAXMenuItemRole], where: { $0.hasPrefix(ShortcutStore.launcherTitle) }).first,
           let itemFrame = Self.axFrame(item) {
            CGEvent(mouseEventSource: source, mouseType: .mouseMoved, mouseCursorPosition: CGPoint(x: itemFrame.midX, y: itemFrame.midY), mouseButton: .left)?
                .post(tap: .cghidEventTap)
            await pause(300)
            if let directory = context.snapshotDirectory, let image = await WindowCapture.openMenuImage(),
               let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("\(highlight).png"))
            }
        }
        for down in [true, false] {
            CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
        }
        await pause(300)
        return opened
    }

    /// Finder's windows on screen (window ids; no titles needed).
    private static func finderWindows() -> Set<CGWindowID> {
        guard let finder = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.finder").first,
              let list = CGWindowListCopyWindowInfo([.optionOnScreenOnly, .excludeDesktopElements], kCGNullWindowID) as? [[String: Any]]
        else { return [] }
        return Set(list.compactMap { info -> CGWindowID? in
            guard (info[kCGWindowOwnerPID as String] as? pid_t) == finder.processIdentifier,
                  (info[kCGWindowLayer as String] as? Int) == 0
            else { return nil }
            return info[kCGWindowNumber as String] as? CGWindowID
        })
    }

    /// Finder's windows as Accessibility lists them, to close only the
    /// ones a press opened.
    private static func finderAXWindows() -> [AXUIElement] {
        guard let finder = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.finder").first else { return [] }
        let app = AXUIElementCreateApplication(finder.processIdentifier)
        AXUIElementSetMessagingTimeout(app, 1)
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(app, kAXWindowsAttribute as CFString, &value) == .success else { return [] }
        return (value as? [AXUIElement]) ?? []
    }

    /// Closes the Finder windows a press opened (their close buttons,
    /// through Accessibility), never one open before it.
    private func closeFinderWindows(except before: Set<CGWindowID>, axBefore: [AXUIElement]) async {
        _ = await waitUntil(timeout: 0.5) { Self.finderAXWindows().count > axBefore.count }
        for window in Self.finderAXWindows() where !axBefore.contains(where: { CFEqual($0, window) }) {
            var button: CFTypeRef?
            guard AXUIElementCopyAttributeValue(window, kAXCloseButtonAttribute as CFString, &button) == .success,
                  let button, CFGetTypeID(button) == AXUIElementGetTypeID()
            else { continue }
            AXUIElementPerformAction(unsafeDowncast(button, to: AXUIElement.self), kAXPressAction as CFString)
        }
        _ = await waitUntil(timeout: 1) { Self.finderWindows().subtracting(before).isEmpty }
    }

    /// Keys → Restore Defaults, pressed as a click (2026-10-17: one
    /// click erased every custom shortcut): it asks first, naming what
    /// goes; Cancel keeps every shortcut; Restore Defaults puts them back
    /// (✦Space opens the launcher again), then the button is off.
    /// `settings-keys-restore-*.png` (the dialog), `settings-keys-restored-*.png`.
    private func restoreDefaultShortcuts() async {
        let name = "Restore Defaults asks first and says what goes; Cancel keeps them; Restore brings ✦Space back, then it is off"
        let store = context.shortcuts
        let settings = context.settings
        // Something to take back: a shortcut of the user's, a changed key.
        let custom = store.add(.openURL("https://example.com/skilli-selftest"))
        try? store.setKeys(Chord.sequence("hyper+k z"), for: custom)
        try? store.setKeys(Chord.sequence("hyper+k y"), for: "uppercase")
        let changes = store.changesFromDefaults
        let message = store.restoreDefaultsMessage
        let before = store.config
        settings.show(pane: .general)
        await pause(200)
        settings.show(pane: .keys)
        await pause(500)
        // Restore Defaults closes the pane, after every shortcut.
        _ = settings.scrollPaneToBottom()
        await pause(400)
        func sheet() -> AXUIElement? { Self.axElements(role: kAXSheetRole).last }
        let pressed = Self.pressButton("Restore Defaults")
        let asked = await waitUntil(timeout: 2) { sheet() != nil } != nil
        let texts = sheet().map(Self.axTexts) ?? []
        let said = texts.contains(RestoreDefaults.title) && message.map { texts.contains($0) } == true
        await captureSettingsBothWays(as: "settings-keys-restore")
        let cancelled = sheet().map { Self.pressButton("Cancel", under: $0) } ?? false
        _ = await waitUntil(timeout: 2) { sheet() == nil }
        let kept = store.config == before
        _ = Self.pressButton("Restore Defaults")
        _ = await waitUntil(timeout: 2) { sheet() != nil }
        // Judged by what it did: the press can report an error while the
        // dialog it closes goes away under it.
        let confirm = sheet().flatMap { Self.axElements(roles: [kAXButtonRole], under: $0, where: { $0 == "Restore Defaults" }).last }
        let pressError = confirm.map { AXUIElementPerformAction($0, kAXPressAction as CFString).rawValue }
        let restored = await waitUntil(timeout: 2) { store.config == .defaults && sheet() == nil } != nil
        await pause(300)
        let buttons = Self.axElements(roles: [kAXButtonRole], where: { $0 == "Restore Defaults" })
        let off = !buttons.isEmpty && !buttons.contains(where: Self.axEnabled) && store.restoreDefaultsMessage == nil
        await captureSettingsBothWays(as: "settings-keys-restored")
        await closeSettings()
        if store.config != .defaults { store.resetAll() }

        guard await focusRecorder() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        let opens = await waitUntil(timeout: 1) { self.context.launcher.isVisible } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !self.context.launcher.isVisible }
        record(
            name,
            changes.custom >= 1 && changes.changed >= 1 && pressed && asked && said && cancelled && kept && confirm != nil && restored
                && opens && off,
            "to take back: \(changes.custom) custom, \(changes.changed) changed; pressed: \(pressed), asked: \(asked), said \(texts) (expected “\(message ?? "nothing")”): \(said); Cancel pressed: \(cancelled), kept: \(kept); the dialog's Restore Defaults pressed: \(confirm != nil) (AX \(pressError.map(String.init) ?? "none")), back to the defaults: \(restored); button off after: \(off) (\(buttons.count) found); opens with ✦Space: \(opens)",
            nil
        )
    }

    /// Picks "skil.li Settings" twice after typing "sett"; "s" alone must
    /// then rank it first.
    private func launcherLearnsPicks() async {
        func openLauncherAndType(_ text: String) async -> Bool {
            guard await focusRecorder() else { return false }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            guard await waitUntil(timeout: 1, { self.context.launcher.isVisible }) != nil else { return false }
            for character in text {
                await pressKey(character)
            }
            await pause(150)
            return true
        }

        guard await openLauncherAndType("s") else {
            record("Launcher learns picks", false, "launcher did not open", nil)
            return
        }
        let before = context.launcher.topResultName ?? "none"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        for _ in 0..<2 {
            guard await openLauncherAndType("sett"),
                  await waitUntil(timeout: 1, { self.context.launcher.topResultName == "skil.li Settings" }) != nil
            else {
                await pressKey(nil, code: CGKeyCode(kVK_Escape))
                record("Launcher learns picks", false, "“sett” did not list skil.li Settings first", nil)
                return
            }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            _ = await waitUntil(timeout: 2) { self.context.settings.isVisible }
            await closeSettings()
        }

        guard await openLauncherAndType("s") else { return }
        let after = context.launcher.topResultName ?? "none"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(
            "Launcher learns picks: after choosing it for “sett”, “s” finds skil.li Settings first",
            before != "skil.li Settings" && after == "skil.li Settings",
            "top for “s” before: \(before), after: \(after)",
            nil
        )
    }

    /// A real drag on the launcher's glass, where no control takes the
    /// click, moves it; it opens there again, a plain click neither moves
    /// nor closes it, "Reset Launcher Position" puts it back. Near the
    /// screen's middle it is pulled centered with a guide showing while the
    /// mouse is down; onto its standard place, it follows the standard again.
    private func launcherStaysWhereDragged() async {
        let name = "Launcher: dragged by its glass, pulled onto guides, opens there again; Reset Launcher Position puts it back"
        let preferences = context.preferences
        let launcher = context.launcher
        let original = preferences.launcherPlace
        defer { preferences.launcherPlace = original }
        preferences.launcherPlace = nil
        let height = NSScreen.screens.first?.frame.height ?? 0
        let source = CGEventSource(stateID: .hidSystemState)
        func mouse(_ type: CGEventType, _ point: NSPoint) async {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: CGPoint(x: point.x, y: height - point.y), mouseButton: .left)?
                .post(tap: .cghidEventTap)
            await pause(type == .leftMouseDragged ? 16 : 60)
        }
        /// Grabs the search bar left of the glass S (nothing there takes the
        /// click), drags by `offset`, and returns the guides shown just
        /// before letting go (saved as `capture` with the screen around them).
        func drag(by offset: CGVector, capture: String? = nil) async -> [LauncherGuide] {
            let glass = launcher.glassFrame
            let grab = NSPoint(x: glass.minX + 12, y: glass.maxY - 30)
            await mouse(.mouseMoved, grab)
            await mouse(.leftMouseDown, grab)
            for step in 1...12 {
                let done = CGFloat(step) / 12
                await mouse(.leftMouseDragged, NSPoint(x: grab.x + offset.dx * done, y: grab.y + offset.dy * done))
            }
            await pause(150)
            let guides = launcher.shownGuides
            if let capture, let directory = context.snapshotDirectory, let visible = launcher.window.screen?.visibleFrame {
                // The glass and the screen above and below it: the guide as seen.
                let glass = launcher.glassFrame
                let around = NSRect(x: glass.minX - 120, y: visible.minY, width: glass.width + 240, height: visible.height)
                if let image = await GlassCheck.screenshot(of: around),
                   let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                    try? png.write(to: directory.appendingPathComponent(capture))
                }
            }
            await mouse(.leftMouseUp, NSPoint(x: grab.x + offset.dx, y: grab.y + offset.dy))
            await pause(100)
            return guides
        }
        func open() async -> Bool {
            guard await focusRecorder() else { return false }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            guard await waitUntil(timeout: 1, { launcher.isVisible }) != nil else { return false }
            await pause(250)
            return true
        }
        func close() async {
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !launcher.isVisible }
        }

        guard await open() else {
            record(name, false, "launcher did not open", nil)
            return
        }
        let start = launcher.glassFrame
        _ = await drag(by: CGVector(dx: 160, dy: -120))
        let target = start.offsetBy(dx: 160, dy: -120)
        let moved = abs(launcher.glassFrame.minX - target.minX) <= 2 && abs(launcher.glassFrame.minY - target.minY) <= 2
        let saved = preferences.launcherPlace != nil
        let dragged = launcher.glassFrame
        let place = preferences.launcherPlace

        let end = NSPoint(x: dragged.minX + 12, y: dragged.maxY - 30)
        await mouse(.leftMouseDown, end)
        await mouse(.leftMouseUp, end)
        await pause(200)
        let clickKept = launcher.isVisible && launcher.glassFrame == dragged && preferences.launcherPlace == place

        await close()
        guard await open() else { return }
        let reopened = launcher.glassFrame
        let there = abs(reopened.minX - dragged.minX) <= 1 && abs(reopened.maxY - dragged.maxY) <= 1

        for character in "reset launcher" {
            await pressKey(character)
        }
        let listed = await waitUntil(timeout: 1) { launcher.topResultName == "Reset Launcher Position" } != nil
        // Never press Return on something else: it would launch it.
        await pressKey(nil, code: CGKeyCode(listed ? kVK_Return : kVK_Escape))
        let reset = await waitUntil(timeout: 1) { preferences.launcherPlace == nil } != nil
        _ = await waitUntil(timeout: 1) { !launcher.isVisible }
        let back = launcher.restingGlassFrame()
        let middle = abs(back.minX - start.minX) <= 1 && abs(back.maxY - start.maxY) <= 1

        // 5 pt right of the middle and well below: pulled centered across,
        // its guide on screen while the mouse is down, gone after.
        guard await open() else { return }
        let middleX = launcher.window.screen?.visibleFrame.midX ?? 0
        let duringCenter = await drag(by: CGVector(dx: 5, dy: -120), capture: "launcher-guides.png")
        let centered = abs(launcher.glassFrame.midX - middleX) <= 0.5
        let guideGone = launcher.shownGuides.isEmpty
        let savedCentered = preferences.launcherPlace?.across == 0.5
        // Back up to 3 pt below its standard place: pulled onto it, and it
        // follows the standard again (no place kept).
        let duringStandard = await drag(by: CGVector(dx: 0, dy: start.maxY - 3 - launcher.glassFrame.maxY), capture: "launcher-guides-standard.png")
        let onStandard = abs(launcher.glassFrame.minX - start.minX) <= 1 && abs(launcher.glassFrame.maxY - start.maxY) <= 1
        let standardAgain = preferences.launcherPlace == nil
        await close()

        let pulled = duringCenter.contains(.centerX) && centered && guideGone && savedCentered
            && duringStandard.contains(.standardTop) && onStandard && standardAgain
        record(
            name,
            moved && saved && clickKept && there && listed && reset && middle && pulled,
            "dragged by (160, -120): \(moved) (glass from \(Int(start.minX)),\(Int(start.minY)) to \(Int(dragged.minX)),\(Int(dragged.minY))), "
                + "saved: \(saved), plain click kept it open and in place: \(clickKept), reopened there: \(there) "
                + "(\(Int(reopened.minX)),\(Int(reopened.minY))), Reset listed: \(listed), reset: \(reset), back in the middle: \(middle); "
                + "5 pt off the middle: guides while held \(duringCenter), centered: \(centered), guide gone after: \(guideGone), "
                + "kept centered: \(savedCentered); 3 pt off its standard place: guides \(duringStandard), on it: \(onStandard), "
                + "follows the standard again: \(standardAgain)",
            nil
        )
    }

    // MARK: - Root search (↑ recent, pins, Opens on, Starts again empty)

    /// The launcher from the test window (✦Space), closed first if open.
    private func openLauncher() async -> Bool {
        if context.launcher.isVisible { await closeLauncher() }
        guard await focusTestWindow() else { return false }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        return await waitUntil(timeout: 1) { self.context.launcher.isVisible } != nil
    }

    /// esc until the launcher is closed: ⌘K's list goes first, then a
    /// mode goes back to the root search, then it closes.
    private func closeLauncher() async {
        let launcher = context.launcher
        for _ in 0..<4 where launcher.isVisible {
            let (mode, actions) = (launcher.mode, launcher.isShowingActions)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !launcher.isVisible || launcher.mode != mode || launcher.isShowingActions != actions }
        }
    }

    /// Two calculations acted on (↩ pastes them in the test window), one
    /// search only typed: ↑ in the empty field puts
    /// back the newest, ↑ the one before, ↑ stays on the oldest, ↓ comes
    /// forward, ↓ empties the field. ↓ then ↑ move the rows; ↑ on the first
    /// row recalls; typing ends the walk; with words typed ↑ moves rows.
    private func recentSearchesComeBack() async {
        let name = "Root search: ↑ in the empty field brings back the searches acted on (↑↑ the one before, ↓ forward, then empty); ↑ with rows still moves the selection"
        let launcher = context.launcher
        let preferences = context.preferences
        let (savedReset, savedPins) = (preferences.launcherReset, preferences.launcherPins)
        preferences.launcherReset = .immediately
        preferences.launcherPins = []
        defer {
            preferences.launcherReset = savedReset
            preferences.launcherPins = savedPins
        }
        launcher.recentSearches.forgetAll()
        let searches = ["12 * 4", "3 * 7"]
        var acted = true
        for search in searches {
            guard let expected = Calculator.evaluate(search), await openLauncher() else {
                acted = false
                break
            }
            for character in search { await pressKey(character) }
            guard await waitUntil(timeout: 1, { launcher.resultTitles.first == expected.display }) != nil else {
                acted = false
                break
            }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            _ = await waitUntil(timeout: 1) { !launcher.isVisible }
            await pause(300)
        }
        // Only typed, never acted on: not kept.
        if await openLauncher() {
            for character in "zqx" { await pressKey(character) }
            await pause(100)
            await closeLauncher()
        }
        let kept = launcher.recentSearches.entries
        guard await openLauncher() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        func up() async {
            await pressKey(nil, code: CGKeyCode(kVK_UpArrow))
            await pause(80)
        }
        func down() async {
            await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
            await pause(80)
        }
        await up()
        let last = launcher.query
        let header = launcher.headerText
        await captureLauncherBothWays(as: "launcher-recent")
        await up()
        let before = launcher.query
        await up()
        let oldestStays = launcher.query
        await down()
        let forward = launcher.query
        await down()
        let emptyAgain = launcher.query
        await down()
        let secondRow = launcher.query.isEmpty && launcher.selectedResultTitle != nil
            && launcher.selectedResultTitle == launcher.resultTitles.dropFirst().first
        await up()
        let firstRowStill = launcher.query.isEmpty && launcher.selectedResultTitle == launcher.resultTitles.first
        await up()
        let recalledFromFirst = launcher.query == searches[1]
        await pressKey("0")
        await pause(80)
        await up()
        let typedStays = launcher.query == searches[1] + "0"
        await closeLauncher()
        var rowsMove = false
        if await openLauncher() {
            await pressKey("s")
            _ = await waitUntil(timeout: 1) { launcher.resultTitles.count > 3 }
            await down()
            await down()
            let third = launcher.selectedResultTitle
            await up()
            rowsMove = third != nil && third == launcher.resultTitles.dropFirst(2).first
                && launcher.selectedResultTitle == launcher.resultTitles.dropFirst().first && launcher.query == "s"
            await closeLauncher()
        }
        let passed = acted && kept == [searches[1], searches[0]] && last == searches[1] && header == "Recent search · 1 of 2" && before == searches[0]
            && oldestStays == searches[0]
            && forward == searches[1] && emptyAgain.isEmpty && secondRow && firstRowStill && recalledFromFirst && typedStays && rowsMove
        record(name, passed,
               "acted on both: \(acted), kept \(kept) (“zqx” only typed); ↑ “\(last)” (header “\(header)”), ↑ “\(before)”, ↑ at the oldest “\(oldestStays)”, ↓ “\(forward)”, ↓ “\(emptyAgain)”; "
                   + "↓ to row 2, field empty: \(secondRow), ↑ back to row 1, field still empty: \(firstRowStill), ↑ again recalls: \(recalledFromFirst); "
                   + "typed after, ↑ leaves the field: \(typedStays); “s”: ↑ moves the rows: \(rowsMove); launcher-recent-light/-dark.png", nil)
    }

    /// The keys of any Mac text field, pressed as a keyboard does (the
    /// modifiers' own key-downs, arrows with the keypad and fn flags), one
    /// after the other from the end of "hello world again": the caret and
    /// the selection after each, in the launcher over another app, Settings'
    /// search field and a SwiftUI field there, and the Ask card's answer
    /// line (← held repeats there too). ↑↓ still move the launcher's rows;
    /// ⌘↓ moves only the caret.
    private func caretKeysEditEverywhere() async {
        guard !aborted else { return }
        let name = "Caret keys as in any Mac text field (⌘← ⌘→ ⌥← ⌥→, ⇧ selects, ⌘↑ ⌘↓, ⌃A ⌃E, ⌥⌫ ⌘⌫, typing over a selection)"
        let text = "hello world again"
        let left = kVK_LeftArrow, right = kVK_RightArrow, up = kVK_UpArrow, downArrow = kVK_DownArrow
        let after = "hello world x"
        /// Keys (nil: type "x"), then the text and the selection they leave.
        let steps: [(keys: String, flags: CGEventFlags, code: Int?, text: String, selection: NSRange)] = [
            ("⌘←", .maskCommand, left, text, NSRange(location: 0, length: 0)),
            ("⌥→", .maskAlternate, right, text, NSRange(location: 5, length: 0)),
            ("⌥→", .maskAlternate, right, text, NSRange(location: 11, length: 0)),
            ("⌥←", .maskAlternate, left, text, NSRange(location: 6, length: 0)),
            ("→", [], right, text, NSRange(location: 7, length: 0)),
            ("←", [], left, text, NSRange(location: 6, length: 0)),
            ("⇧⌥→", [.maskShift, .maskAlternate], right, text, NSRange(location: 6, length: 5)),
            ("⌘→", .maskCommand, right, text, NSRange(location: 17, length: 0)),
            ("⇧⌘←", [.maskShift, .maskCommand], left, text, NSRange(location: 0, length: 17)),
            ("→", [], right, text, NSRange(location: 17, length: 0)),
            ("⌃A", .maskControl, keyCode("a").map(Int.init), text, NSRange(location: 0, length: 0)),
            ("⌃E", .maskControl, keyCode("e").map(Int.init), text, NSRange(location: 17, length: 0)),
            ("⌘↑", .maskCommand, up, text, NSRange(location: 0, length: 0)),
            ("⌘↓", .maskCommand, downArrow, text, NSRange(location: 17, length: 0)),
            ("⇧⌥←", [.maskShift, .maskAlternate], left, text, NSRange(location: 12, length: 5)),
            ("x", [], nil, after, NSRange(location: 13, length: 0)),
            ("⌥⌫", .maskAlternate, kVK_Delete, "hello world ", NSRange(location: 12, length: 0)),
            ("⌘⌫", .maskCommand, kVK_Delete, "", NSRange(location: 0, length: 0))
        ]
        func press(_ flags: CGEventFlags, _ code: Int) async {
            let held = Self.modifierKeys.filter { flags.contains($0.flag) }
            var down: CGEventFlags = []
            for modifier in held {
                down.insert(modifier.flag)
                postKey(modifier.code, down: true, flags: down)
                await pause(10)
            }
            let arrow = [left, right, up, downArrow].contains(code)
            let keyFlags = arrow ? down.union([.maskNumericPad, .maskSecondaryFn]) : down
            postKey(CGKeyCode(code), down: true, flags: keyFlags)
            await pause(12)
            postKey(CGKeyCode(code), down: false, flags: keyFlags)
            await pause(12)
            for modifier in held.reversed() {
                down.remove(modifier.flag)
                postKey(modifier.code, down: false, flags: down)
                await pause(10)
            }
        }
        /// The steps in one input; nil when all went as in a text field,
        /// else where it went wrong.
        func walk(_ read: () -> (text: String, selection: NSRange)?, still: () -> Bool) async -> String? {
            for step in steps {
                guard still() else { return "\(step.keys): the input went away" }
                if let code = step.code { await press(step.flags, code) } else { await pressKey("x") }
                let done = await waitUntil(timeout: 0.5) {
                    guard let seen = read() else { return false }
                    return seen.text == step.text && seen.selection == step.selection
                } != nil
                if !done {
                    let seen = read().map { "“\($0.text)” \($0.selection.location),\($0.selection.length)" } ?? "nothing"
                    return "\(step.keys): \(seen), not “\(step.text)” \(step.selection.location),\(step.selection.length)"
                }
            }
            return nil
        }
        func type(_ typed: String) async {
            for character in typed { await pressKey(character) }
        }

        // The launcher over TextEdit: skil.li not the app in front.
        let launcher = context.launcher
        let bundleID = "com.apple.TextEdit"
        var launcherResult = "TextEdit missing"
        var rows = "not tried"
        var rowsMove = false
        if let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) {
            let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
            let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-caret-\(getpid()).txt")
            try? "caret".write(to: file, atomically: true, encoding: .utf8)
            defer { try? FileManager.default.removeItem(at: file) }
            let configuration = NSWorkspace.OpenConfiguration()
            configuration.activates = true
            if let pid = (try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration))?.processIdentifier {
                Self.makeFrontmost(pid: pid)
                if await waitUntil(timeout: 4, { NSWorkspace.shared.frontmostApplication?.processIdentifier == pid }) != nil {
                    _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
                    if await waitUntil(timeout: 1, { launcher.isVisible }) != nil {
                        await type(text)
                        _ = await waitUntil(timeout: 1) { launcher.query == text }
                        launcherResult = await walk({ launcher.fieldSelection.map { (launcher.query, $0) } }, still: { launcher.isVisible }) ?? "ok"
                        // ↓ and ↑ still move the rows; ⌘↓ only the caret.
                        await pressKey("s")
                        _ = await waitUntil(timeout: 1) { launcher.resultTitles.count > 3 }
                        let titles = launcher.resultTitles
                        await press([], downArrow)
                        let second = launcher.selectedResultTitle
                        await press(.maskCommand, downArrow)
                        let still = launcher.selectedResultTitle
                        await press([], up)
                        let first = launcher.selectedResultTitle
                        rowsMove = titles.count > 3 && second == titles[1] && still == titles[1] && first == titles[0]
                        rows = "↓ → \(second ?? "none"), ⌘↓ → \(still ?? "none"), ↑ → \(first ?? "none") (rows \(titles.prefix(2)))"
                        await pressKey(nil, code: CGKeyCode(kVK_Escape))
                        _ = await waitUntil(timeout: 1) { !launcher.isVisible }
                        if launcher.isVisible { await closeLauncher() }
                    } else {
                        launcherResult = "the launcher did not open over TextEdit"
                    }
                    Self.makeFrontmost(pid: pid)
                    _ = await waitUntil(timeout: 2) { NSWorkspace.shared.frontmostApplication?.processIdentifier == pid }
                } else {
                    launcherResult = "TextEdit never came to front"
                }
                await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            } else {
                launcherResult = "could not open TextEdit"
            }
        }
        record("\(name): the launcher over another app; ↑↓ still move its rows", launcherResult == "ok" && rowsMove,
               "keys: \(launcherResult); rows: \(rows)", nil)

        // Settings: the search field, then a SwiftUI field (Ask → On a Schedule's new ask).
        guard !aborted else { return }
        let settings = context.settings
        var searchResult = "Settings did not come forward"
        var fieldResult = "not tried"
        settings.show(pane: .general)
        if await waitUntil(timeout: 2, { settings.isVisible && settings.isKey }) != nil {
            await pause(400)
            await pressKey("f", flags: .maskCommand)
            if await waitUntil(timeout: 1, { settings.searchFieldFocused }) != nil {
                await type(text)
                _ = await waitUntil(timeout: 1) { settings.editedText?.string == text }
                searchResult = await walk({ settings.editedText.map { ($0.string, $0.selectedRange()) } }, still: { settings.isKey }) ?? "ok"
                settings.search.clear()
            } else {
                searchResult = "⌘F did not reach the search field"
            }
            settings.show(pane: .ask)
            await pause(600)
            if settings.focusField(placeholder: "every Monday") {
                await pause(200)
                await type(text)
                _ = await waitUntil(timeout: 1) { settings.editedText?.string == text }
                fieldResult = await walk({ settings.editedText.map { ($0.string, $0.selectedRange()) } }, still: { settings.isKey }) ?? "ok"
            } else {
                fieldResult = "no field for a new scheduled ask"
            }
            await closeSettings()
        }
        record("\(name): Settings' search field and a SwiftUI field", searchResult == "ok" && fieldResult == "ok",
               "search: \(searchResult); Ask → On a Schedule: \(fieldResult)", nil)

        // The Ask card's answer line (✦A), drawn by skil.li: its keys come from the tap.
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: ["ok"], delay: .milliseconds(5))
        defer {
            context.ai.testEngine = nil
            textView.string = ""
        }
        var cardResult = "the test window did not take the focus"
        var caretAt = ""
        if await focusTestWindow() {
            window.makeFirstResponder(textView)
            textView.string = "Bonjour"
            textView.selectAll(nil)
            await pause(60)
            _ = await hyperChord(["a"], trigger: Self.ownTriggerKeyCode)
            if await waitUntil(timeout: 2, { popover.isVisible && popover.phase == .asking }) != nil {
                await type(text)
                _ = await waitUntil(timeout: 1) { popover.shownQuestion?.typed == text }
                cardResult = await walk({
                    guard popover.isVisible, let typed = popover.shownQuestion?.typed else { return nil }
                    return (typed, popover.shownAnswerSelection ?? NSRange(location: (typed as NSString).length, length: 0))
                }, still: { popover.isVisible && popover.phase == .asking }) ?? "ok"
                // The caret drawn where it is: after "hello" once ⌥→ moved it there.
                if cardResult == "ok" {
                    await type("hello world")
                    await press(.maskCommand, left)
                    await press(.maskAlternate, right)
                    let caret = popover.answerCaret
                    let afterHello = popover.shownAnswerSelection == NSRange(location: 5, length: 0) && caret.caret < caret.textEnd - 20
                    caretAt = afterHello ? "" : "; caret at \(Int(caret.caret)) for a text ending at \(Int(caret.textEnd))"
                    if !afterHello { cardResult = "the caret is not drawn after “hello”" }
                    // ← held: its repeats move on, 5 → 2.
                    let arrowFlags: CGEventFlags = [.maskNumericPad, .maskSecondaryFn]
                    postKey(CGKeyCode(left), down: true, flags: arrowFlags)
                    for _ in 0..<2 {
                        await pause(40)
                        let source = CGEventSource(stateID: .hidSystemState)
                        if let repeated = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(left), keyDown: true) {
                            repeated.flags = arrowFlags
                            repeated.setIntegerValueField(.keyboardEventAutorepeat, value: 1)
                            repeated.post(tap: .cghidEventTap)
                        }
                    }
                    await pause(40)
                    postKey(CGKeyCode(left), down: false, flags: arrowFlags)
                    let held = await waitUntil(timeout: 0.5) { popover.shownAnswerSelection == NSRange(location: 2, length: 0) } != nil
                    if afterHello, !held {
                        cardResult = "← held stopped at \(popover.shownAnswerSelection.map { "\($0.location)" } ?? "the end"), not 2"
                    }
                }
                await pressKey(nil, code: CGKeyCode(kVK_Escape))
                _ = await waitUntil(timeout: 1) { !popover.isVisible }
            } else {
                cardResult = "no question in the card (phase \(popover.phase))"
                await pressKey(nil, code: CGKeyCode(kVK_Escape))
            }
        }
        record("\(name): the Ask card's answer line", cardResult == "ok", "\(cardResult)\(caretAt)", nil)
    }

    /// ⌃N and ⌃P move like ↓ and ↑: in the rows, in ⌘K's list, and ⌃P
    /// in the empty field brings back the newest search acted on. In ⌘K's
    /// list a press past an end goes round to the other; held, it stops.
    private func controlKeysMoveLikeArrows() async {
        let name = "Keyboard: ⌃N / ⌃P move like ↓ / ↑ in the results and in ⌘K's list, whose ends go round (not when held); ⌃P in the empty field brings back the last search"
        let launcher = context.launcher
        let preferences = context.preferences
        let (savedReset, savedPins) = (preferences.launcherReset, preferences.launcherPins)
        preferences.launcherReset = .immediately
        preferences.launcherPins = []
        defer {
            preferences.launcherReset = savedReset
            preferences.launcherPins = savedPins
        }
        launcher.recentSearches.forgetAll()
        launcher.recentSearches.record("7 * 6")
        guard await openLauncher() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        func control(_ key: Character) async {
            await pressKey(key, flags: .maskControl)
            await pause(80)
        }
        await pressKey("s")
        _ = await waitUntil(timeout: 1) { launcher.resultTitles.count > 3 }
        let titles = launcher.resultTitles
        await control("n")
        await control("n")
        let third = launcher.selectedResultTitle
        await control("p")
        let second = launcher.selectedResultTitle
        let rows = third != nil && third == titles.dropFirst(2).first && second == titles.dropFirst().first && launcher.query == "s"
        await pressKey("k", flags: .maskCommand)
        _ = await waitUntil(timeout: 1) { launcher.isShowingActions }
        let listed = launcher.shownActions.map(\.title)
        let first = launcher.selectedActionTitle
        await control("n")
        let next = launcher.selectedActionTitle
        await control("p")
        let back = launcher.selectedActionTitle
        let inActions = listed.count > 1 && first == listed.first && next == listed[1] && back == listed.first && launcher.isShowingActions
        // Past an end, round to the other; held (a repeat), the key stops there.
        func arrow(_ code: Int, held: Bool = false) async {
            if held {
                let source = CGEventSource(stateID: .hidSystemState)
                if let repeated = CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(code), keyDown: true) {
                    repeated.flags = []
                    repeated.setIntegerValueField(.keyboardEventAutorepeat, value: 1)
                    repeated.post(tap: .cghidEventTap)
                }
                await pause(12)
                postKey(CGKeyCode(code), down: false)
            } else {
                await pressKey(nil, code: CGKeyCode(code))
            }
            await pause(80)
        }
        await arrow(kVK_UpArrow, held: true)
        let heldAtTop = launcher.selectedActionTitle
        await arrow(kVK_UpArrow)
        let roundToLast = launcher.selectedActionTitle
        await arrow(kVK_DownArrow)
        let roundToFirst = launcher.selectedActionTitle
        let wraps = listed.count > 1 && heldAtTop == listed.first && roundToLast == listed.last && roundToFirst == listed.first
            && launcher.isShowingActions
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await closeLauncher()
        var recalled = false
        if await openLauncher() {
            await control("p")
            recalled = await waitUntil(timeout: 1) { launcher.query == "7 * 6" } != nil
            await closeLauncher()
        }
        launcher.recentSearches.forgetAll()
        record(name, rows && inActions && wraps && recalled,
               "“s”: ⌃N ⌃N → \(third ?? "none") (row 3 \(titles.dropFirst(2).first ?? "none")), ⌃P → \(second ?? "none"): \(rows); "
                   + "⌘K \(listed.prefix(3)): ⌃N → \(next ?? "none"), ⌃P → \(back ?? "none"): \(inActions); "
                   + "↑ held on the first → \(heldAtTop ?? "none"), ↑ → \(roundToLast ?? "none") (last \(listed.last ?? "none")), ↓ → \(roundToFirst ?? "none"): \(wraps); "
                   + "⌃P in the empty field → “7 * 6”: \(recalled)", nil)
    }

    /// Text selected where the launcher opens is a quicklink's query when
    /// none is typed: Wikipedia picked by name searches it at once, its row
    /// says so; words typed win; nothing selected, the keyword goes in the
    /// field as before. Addresses recorded, not opened.
    private func quicklinkTakesTheSelection() async {
        let name = "Quicklinks: the selected text is the query when none is typed (Wikipedia ↩ searches it); words typed win; nothing selected, its keyword goes in the field"
        let launcher = context.launcher
        let actions = context.actions
        let dryRun = actions.dryRunURLs
        actions.dryRunURLs = true
        defer {
            actions.dryRunURLs = dryRun
            textView.string = ""
        }
        /// The test window's text, all selected, then the launcher on `typed`
        /// with the row `title` selected.
        func open(selecting text: String, typing typed: String, row title: String) async -> (seen: Bool, selected: Bool) {
            guard await focusTestWindow() else { return (false, false) }
            window.makeFirstResponder(textView)
            textView.string = text
            textView.setSelectedRange(NSRange(location: 0, length: text.isEmpty ? 0 : (text as NSString).length))
            guard await openLauncher() else { return (false, false) }
            let seen = text.isEmpty ? launcher.shownSelection == nil : await waitUntil(timeout: 1) { launcher.shownSelection == text } != nil
            for character in typed { await pressKey(character) }
            var index: Int?
            _ = await waitUntil(timeout: 2) {
                index = launcher.resultTitles.firstIndex(of: title)
                return index != nil
            }
            guard let index else { return (seen, false) }
            for _ in 0..<index { await pressKey(nil, code: CGKeyCode(kVK_DownArrow)) }
            return (seen, await waitUntil(timeout: 1) { launcher.selectedResultTitle == title } != nil)
        }
        // openLauncher focuses the test window first: its text view keeps
        // the selection.
        let byName = await open(selecting: "Tour Eiffel", typing: "wikipedia", row: "Wikipedia")
        if byName.selected { await captureLauncherBothWays(as: "launcher-quicklink-selection") }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let searched = await waitUntil(timeout: 1) { actions.lastURL == "https://fr.wikipedia.org/w/index.php?search=Tour%20Eiffel" } != nil
        await closeLauncher()

        let typed = await open(selecting: "Tour Eiffel", typing: "wiki louvre", row: "Wikipedia · louvre")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let typedWins = await waitUntil(timeout: 1) { actions.lastURL == "https://fr.wikipedia.org/w/index.php?search=louvre" } != nil
        await closeLauncher()

        let nothing = await open(selecting: "", typing: "wikipedia", row: "Wikipedia")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let keyword = await waitUntil(timeout: 1) { launcher.query == "wiki " } != nil
        await closeLauncher()

        record(name, byName.seen && byName.selected && searched && typed.selected && typedWins && nothing.selected && keyword,
               "selection seen: \(byName.seen), Wikipedia row: \(byName.selected), ↩ searched “Tour Eiffel”: \(searched) (\(actions.lastURL ?? "nothing")); "
                   + "“wiki louvre” wins: \(typedWins); nothing selected, “wiki ” in the field: \(keyword); launcher-quicklink-selection-light/-dark.png", nil)
    }

    /// Type in English while open: with an English layout turned on, the
    /// launcher types with it and the user's comes back as it closes,
    /// bindings keep the user's layout meanwhile and ⌘K still opens the
    /// actions. With none (the mini: French only, never changed here):
    /// nothing is switched, and Settings → Launcher says so.
    private func typesInEnglishWhileOpen() async {
        let name = "Type in English while open: the English layout while the launcher is open (bindings and ⌘K on the user's layout), theirs back after; none turned on: nothing changes and the pane says so"
        guard let typing = context.englishTyping else {
            record(name, false, "no EnglishTyping", nil)
            return
        }
        let launcher = context.launcher
        let preferences = context.preferences
        let saved = preferences.launcherEnglishInput
        preferences.launcherEnglishInput = true
        defer { preferences.launcherEnglishInput = saved }
        let before = EnglishTyping.current().info
        let english = EnglishTyping.english()?.info
        let switches = EnglishInput.switches(from: before, to: english)
        let keyA = context.layout.keyCode(for: .character("a"))
        guard await openLauncher() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        _ = await waitUntil(timeout: 1) { !switches || typing.isSwitched }
        let during = EnglishTyping.current().info
        let held = context.layout.isHeld
        let keyADuring = context.layout.keyCode(for: .character("a"))
        await pressKey("s")
        await pressKey("k", flags: .maskCommand)
        let commandK = await waitUntil(timeout: 1) { launcher.isShowingActions } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await closeLauncher()
        _ = await waitUntil(timeout: 1) { EnglishTyping.current().info.id == before.id }
        let after = EnglishTyping.current().info
        let passed: Bool
        let detail: String
        if let english, switches {
            passed = during.id == english.id && held && keyADuring == keyA && commandK && after.id == before.id && !context.layout.isHeld
            detail = "\(before.name) → \(during.name) while open (English: \(english.name)), bindings held: \(held), “a” on the same key: \(keyADuring == keyA), ⌘K: \(commandK), back to \(after.name)"
        } else {
            passed = during.id == before.id && after.id == before.id && !typing.isSwitched && !held && commandK
            detail = "no English layout turned on besides \(before.name) (\(EnglishTyping.enabledSources().map(\.info.name))): nothing switched (\(during.name) while open), ⌘K: \(commandK)"
        }
        // The pane, Advanced open: the switch and what it says here.
        Advanced.startsOpen = true
        defer { Advanced.startsOpen = false }
        context.settings.show(pane: .launcher)
        await pause(600)
        let overflow = context.settings.paneOverflow()
        // Advanced is last: the pane's end in sight.
        _ = context.settings.scrollPaneToBottom()
        await pause(300)
        await captureSettingsBothWays(as: "settings-launcher-english")
        context.settings.scrollPaneToTop()
        await closeSettings()
        record(name, passed && overflow <= 1, "\(detail); pane overflow \(Int(overflow)) pt; settings-launcher-english-light/-dark.png", nil)
    }

    /// ⌘K → Pin on Chess, then on Calculator: both first in the empty
    /// field, in that order, each with its pin; ⌘K → Unpin on Chess; the
    /// pinned Calculator ranks as high or higher for "cal"; a pin whose app
    /// is gone is not shown and dropped; the Catalog's ⌘K offers Pin.
    private func pinsComeFirst() async {
        let name = "Root search: ⌘K → Pin puts apps first in the empty launcher with a pin, in the order pinned; boosted when typed; Unpin; pins of apps gone dropped; Pin in the Catalog's ⌘K"
        let launcher = context.launcher
        let preferences = context.preferences
        let (savedPins, savedReset) = (preferences.launcherPins, preferences.launcherReset)
        preferences.launcherPins = []
        preferences.launcherReset = .immediately
        defer {
            preferences.launcherPins = savedPins
            preferences.launcherReset = savedReset
        }
        // "Échecs", "Calculette" on a French Mac.
        func appTitle(_ bundleID: String) -> String? {
            guard let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else { return nil }
            var title = FileManager.default.displayName(atPath: url.path)
            if title.hasSuffix(".app") { title.removeLast(4) }
            return title
        }
        guard let chess = appTitle("com.apple.Chess"), let calculator = appTitle("com.apple.calculator") else {
            record(name, false, "Chess or Calculator not found", nil)
            return
        }
        func row(of title: String) async -> Int? {
            var index: Int?
            _ = await waitUntil(timeout: 2) {
                index = launcher.resultTitles.firstIndex(of: title)
                return index != nil
            }
            return index
        }
        /// The launcher on `typed`, the row `title` selected (↓ to it).
        func select(_ title: String, typing typed: String) async -> Bool {
            guard await openLauncher() else { return false }
            for character in typed { await pressKey(character) }
            guard let index = await row(of: title) else { return false }
            for _ in 0..<index { await pressKey(nil, code: CGKeyCode(kVK_DownArrow)) }
            return await waitUntil(timeout: 1) { launcher.selectedResultTitle == title } != nil
        }
        /// ⌘K on the selected row, `action` typed, ↩; the actions offered.
        func run(_ action: String, capture: String? = nil) async -> [String] {
            await pressKey("k", flags: .maskCommand)
            _ = await waitUntil(timeout: 1) { launcher.isShowingActions }
            let offered = launcher.shownActions.map(\.title)
            if let capture { await captureLauncherBothWays(as: capture) }
            for character in action { await pressKey(character) }
            await pause(80)
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            _ = await waitUntil(timeout: 1) { !launcher.isShowingActions }
            return offered
        }

        var rankBefore: Int?
        if await openLauncher() {
            for character in "cal" { await pressKey(character) }
            rankBefore = await row(of: calculator)
        }
        var chessID: String?
        var offered: [String] = []
        var pinnedWhileTyped = false
        if await select(chess, typing: "chess") {
            chessID = launcher.selectedResultID
            offered = await run("pin", capture: "launcher-pin-action")
            pinnedWhileTyped = await waitUntil(timeout: 1) {
                launcher.resultTitles.firstIndex(of: chess).map { launcher.shownPinned.indices.contains($0) && launcher.shownPinned[$0] } ?? false
            } != nil
        }
        var calculatorID: String?
        if await select(calculator, typing: "calc") {
            calculatorID = launcher.selectedResultID
            _ = await run("pin")
        }
        await closeLauncher()
        let pinsSaved = preferences.launcherPins
        var firstTwo: [String] = []
        var drawn: [Bool] = []
        var unpinOffered: [String] = []
        var unpinned = false
        if await openLauncher() {
            _ = await waitUntil(timeout: 1) { Array(launcher.resultTitles.prefix(2)) == [chess, calculator] }
            firstTwo = Array(launcher.resultTitles.prefix(2))
            drawn = Array(launcher.shownPinned.prefix(3))
            await captureLauncherBothWays(as: "launcher-pinned")
            unpinOffered = await run("unpin", capture: "launcher-unpin-action")
            unpinned = await waitUntil(timeout: 1) {
                preferences.launcherPins == [calculatorID ?? "?"] && launcher.resultTitles.first == calculator
            } != nil
        }
        var rankAfter: Int?
        var pinnedRowTyped = false
        if await openLauncher() {
            for character in "cal" { await pressKey(character) }
            rankAfter = await row(of: calculator)
            pinnedRowTyped = rankAfter.map { launcher.shownPinned.indices.contains($0) && launcher.shownPinned[$0] } ?? false
        }
        let boosted = rankBefore != nil && rankAfter != nil && rankAfter! <= rankBefore!
        // A pin whose app is gone: not shown, then dropped from the pins.
        let gone = "app:/Applications/Skilli Selftest Gone \(getpid()).app"
        preferences.launcherPins = [gone] + preferences.launcherPins
        var goneDropped = false
        if await openLauncher() {
            goneDropped = await waitUntil(timeout: 2) {
                preferences.launcherPins == [calculatorID ?? "?"] && launcher.resultTitles.first == calculator
            } != nil
        }
        var catalogPin = false
        if await openLauncher(), await typeCharacter("?") {
            _ = await waitUntil(timeout: 1) { launcher.isInCatalog }
            for character in "clipboard" { await pressKey(character) }
            _ = await waitUntil(timeout: 1) { launcher.selectedResultTitle == "Clipboard History" }
            await pressKey("k", flags: .maskCommand)
            catalogPin = await waitUntil(timeout: 1) { launcher.shownActions.map(\.title).contains("Pin") } != nil
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
        }
        await closeLauncher()
        let passed = offered.contains("Pin") && pinnedWhileTyped && chessID != nil && calculatorID != nil && pinsSaved == [chessID ?? "", calculatorID ?? ""]
            && firstTwo == [chess, calculator] && drawn == [true, true, false] && unpinOffered.contains("Unpin") && unpinned && boosted && pinnedRowTyped
            && goneDropped && catalogPin
        record(name, passed,
               "⌘K on \(chess): \(offered), pin shown at once: \(pinnedWhileTyped); pins \(pinsSaved.map { $0.split(separator: "/").last.map(String.init) ?? $0 }); "
                   + "empty field \(firstTwo), pins drawn \(drawn); ⌘K \(unpinOffered) → Unpin: \(unpinned); “cal”: \(calculator) row \(rankBefore.map(String.init) ?? "none") → "
                   + "\(rankAfter.map(String.init) ?? "none") pinned, its pin drawn: \(pinnedRowTyped); pin of an app gone dropped: \(goneDropped); Catalog ⌘K offers Pin: \(catalogPin); "
                   + "launcher-pin-action, launcher-pinned, launcher-unpin-action -light/-dark.png", nil)
    }

    /// Right away (as before): empty. After 1 minute: the words and the row
    /// back, a mode too; empty once a minute went by (a test hook ages the
    /// close). After 5 minutes, at 4:59 and 5:01. Never: back after hours.
    private func startsAgainAfterAWhile() async {
        let name = "Root search: Starts again empty right away (as before), after 1 or 5 minutes (words, mode and row kept until then), or never"
        let launcher = context.launcher
        let preferences = context.preferences
        let saved = preferences.launcherReset
        defer { preferences.launcherReset = saved }
        func typeAndClose(_ text: String, down: Int = 0) async -> String? {
            guard await openLauncher() else { return nil }
            for character in text { await pressKey(character) }
            await pause(200)
            for _ in 0..<down { await pressKey(nil, code: CGKeyCode(kVK_DownArrow)) }
            await pause(80)
            let selected = launcher.selectedResultTitle
            // ⌘W closes from where it is (esc in a mode would first go back
            // to the root search).
            await pressKey("w", flags: .maskCommand)
            _ = await waitUntil(timeout: 1) { !launcher.isVisible }
            await closeLauncher()
            return selected
        }
        func reopened() async -> (query: String, selected: String?, emoji: Bool, showMs: Double, wordsSelected: Bool) {
            guard await openLauncher() else { return ("(not open)", nil, false, 0, false) }
            await pause(200)
            let seen = (launcher.query, launcher.selectedResultTitle, launcher.isInEmoji, launcher.lastShowDuration?.milliseconds ?? 0,
                        launcher.fieldTextSelected)
            await closeLauncher()
            return seen
        }
        preferences.launcherReset = .immediately
        _ = await typeAndClose("calc")
        let rightAway = await reopened()
        preferences.launcherReset = .afterOneMinute
        let selected = await typeAndClose("calc", down: 1)
        let within = await reopened()
        launcher.pretendClosed(for: .seconds(61))
        let afterMinute = await reopened()
        _ = await typeAndClose("emoji smile")
        let mode = await reopened()
        preferences.launcherReset = .afterFiveMinutes
        _ = await typeAndClose("calc")
        launcher.pretendClosed(for: .seconds(299))
        let fourMinutes = await reopened()
        launcher.pretendClosed(for: .seconds(301))
        let fiveMinutes = await reopened()
        preferences.launcherReset = .never
        _ = await typeAndClose("calc")
        launcher.pretendClosed(for: .seconds(36_000))
        let never = await reopened()
        preferences.launcherReset = .immediately
        let passed = rightAway.query.isEmpty && selected != nil && within.query == "calc" && within.selected == selected && within.wordsSelected && afterMinute.query.isEmpty
            && mode.emoji && mode.query == "smile" && fourMinutes.query == "calc" && fiveMinutes.query.isEmpty && never.query == "calc"
        record(name, passed,
               "right away: “\(rightAway.query)” (shown in \(String(format: "%.1f", rightAway.showMs)) ms); 1 min: “\(within.query)”, row \(within.selected ?? "none") "
                   + "(was \(selected ?? "none"); words selected: \(within.wordsSelected); shown in \(String(format: "%.1f", within.showMs)) ms), after 61 s “\(afterMinute.query)”; Emoji “smile” kept: \(mode.emoji) “\(mode.query)”; "
                   + "5 min: at 4:59 “\(fourMinutes.query)”, at 5:01 “\(fiveMinutes.query)”; never, 10 h later: “\(never.query)”", nil)
    }

    /// Each choice opens the launcher on the screen it says; the window in
    /// front is read from the window server. With one display there is
    /// nothing to tell apart: that part is skipped, said why.
    private func opensOnTheChosenScreen() async {
        let name = "Root search: Opens on the pointer's screen, the window in front's or the main display; the window in front read from the window server"
        let launcher = context.launcher
        let preferences = context.preferences
        let saved = preferences.launcherScreen
        let screens = NSScreen.screens
        let mouseBefore = NSEvent.mouseLocation
        let mainHeight = screens.first?.frame.height ?? 0
        defer {
            preferences.launcherScreen = saved
            CGWarpMouseCursorPosition(CGPoint(x: mouseBefore.x, y: mainHeight - mouseBefore.y))
        }
        guard await focusTestWindow() else { return }
        // Two displays or more: the pointer on one the test window is not on.
        let testScreen = LauncherScreen.holding(window.frame, in: screens.map(\.frame))
        if screens.count > 1, let other = screens.indices.first(where: { $0 != testScreen }) {
            let frame = screens[other].frame
            CGWarpMouseCursorPosition(CGPoint(x: frame.midX, y: mainHeight - frame.midY))
            await pause(100)
        }
        let front = LauncherController.frontWindowFrame()
        let frontRead = front.map {
            abs($0.minX - window.frame.minX) <= 1 && abs($0.maxY - window.frame.maxY) <= 1 && abs($0.width - window.frame.width) <= 1
        } ?? false
        var passed = frontRead
        var details: [String] = []
        var opened: Set<Int> = []
        for choice in LauncherScreen.allCases {
            preferences.launcherScreen = choice
            guard await openLauncher() else {
                passed = false
                details.append("\(choice.rawValue): did not open")
                continue
            }
            let glass = launcher.glassFrame
            let on = screens.firstIndex { $0.frame.contains(NSPoint(x: glass.midX, y: glass.midY)) }
            let mouse = NSEvent.mouseLocation
            let pointer = screens.firstIndex { NSMouseInRect(mouse, $0.frame, false) }
            let expected = choice.pick(screens: screens.map(\.frame), pointerScreen: pointer, frontWindow: window.frame)
            passed = passed && on != nil && on == expected
            if let on { opened.insert(on) }
            details.append("\(choice.rawValue): display \(on.map(String.init) ?? "none") (expected \(expected.map(String.init) ?? "none"))")
            await closeLauncher()
        }
        let frontText = front.map { "\(Int($0.minX)),\(Int($0.minY)) \(Int($0.width))×\(Int($0.height))" } ?? "none"
        record(name, passed, "window in front read: \(frontRead) (\(frontText); test window \(Int(window.frame.minX)),\(Int(window.frame.minY))); "
               + details.joined(separator: ", ") + "; \(screens.count) display\(screens.count == 1 ? "" : "s")", nil)
        if screens.count < 2 {
            checks.append(Check(name: "Root search: Opens on tells displays apart", passed: true, skipped: true,
                                detail: "one display on this Mac: every choice is that display", latencyMs: nil))
        } else {
            record("Root search: Opens on tells displays apart", passed && opened.count > 1, "displays opened on: \(opened.sorted())", nil)
        }
    }

    /// Settings → Launcher with Opens on and Starts again empty, light and
    /// dark, within the window.
    private func launcherSettingsShown() async {
        let name = "Settings → Launcher: Opens on and Starts again empty, within the window"
        context.settings.show(pane: .launcher)
        await pause(500)
        let overflow = context.settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-launcher")
        await closeSettings()
        record(name, overflow <= 1, "overflow \(Int(overflow)) pt; settings-launcher-light/-dark.png", nil)
    }

    // MARK: - Settings

    private func settingsFromLauncherSearch() async {
        guard await focusRecorder() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "settings" {
            await pressKey(character)
        }
        let listed = await waitUntil(timeout: 1) { self.context.launcher.topResultName == "skil.li Settings" }
        guard listed != nil else {
            // Never press Return on something else: it would launch that app.
            let query = context.launcher.query
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            record("Launcher: type “settings”, Enter opens Settings", false, "launcher got \"\(query)\", top result \"\(context.launcher.topResultName ?? "none")\"", nil)
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let opened = await waitUntil(timeout: 2) { self.context.settings.isVisible && self.context.settings.isKey }
        let launcherClosed = !context.launcher.isVisible
        await snapshotSettingsTabs()
        await closeSettings()
        record(
            "Launcher: type “settings”, Enter opens Settings",
            listed != nil && opened != nil && launcherClosed,
            "top result \"\(context.launcher.topResultName ?? "none")\", settings key: \(opened != nil), launcher closed: \(launcherClosed)",
            opened?.milliseconds
        )
    }

    private func settingsFromCommandComma() async {
        guard await focusRecorder() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        guard await waitUntil(timeout: 1, { self.context.launcher.isVisible }) != nil else {
            record("Launcher: ⌘, opens Settings", false, "launcher did not open", nil)
            return
        }
        await pause(300)
        await pressKey(",", flags: .maskCommand)
        let opened = await waitUntil(timeout: 2) { self.context.settings.isVisible && self.context.settings.isKey }
        let launcherClosed = !context.launcher.isVisible
        await closeSettings()
        record("Launcher: ⌘, opens Settings", opened != nil && launcherClosed, "settings key: \(opened != nil), launcher closed: \(launcherClosed)", opened?.milliseconds)
    }

    private func settingsFromStatusMenu() async {
        guard await focusRecorder() else { return }
        let found = context.performStatusMenuSettings()
        let opened = await waitUntil(timeout: 2) { self.context.settings.isVisible && self.context.settings.isKey }
        // ⌘W closes it like any window.
        await pressKey("w", flags: .maskCommand)
        let closedByCommandW = await waitUntil(timeout: 1) { !self.context.settings.isVisible }
        await closeSettings()
        record(
            "Status menu “Settings…” opens Settings, ⌘W closes it",
            found && opened != nil && closedByCommandW != nil,
            "menu item found: \(found), opened: \(opened != nil), ⌘W closed: \(closedByCommandW != nil)",
            opened?.milliseconds
        )
    }

    private func glassPreferenceAppliesLive() async {
        let original = context.preferences.glassStyle
        defer { context.preferences.glassStyle = original }
        context.preferences.glassStyle = .clear
        let clear = context.launcher.glassStyles.allSatisfy { $0 == .clear }
        context.preferences.glassStyle = .regular
        let regular = context.launcher.glassStyles.allSatisfy { $0 == .regular }
        record("Glass preference applies to the launcher live", clear && regular, "clear: \(clear), regular: \(regular)", nil)
    }

    /// Liquid Glass draws a soft shadow past its shape. A window cut to the
    /// shape clips it into square corners and dark bands, so nothing may
    /// reach a glass window's outer edge.
    private func glassShadowFitsWindows() async {
        let limit = 0.02
        context.launcher.show(triggeredAt: .now)
        await pause(250)
        let launcher = (await WindowCapture.image(of: context.launcher.window)).map(WindowCapture.edgeAlpha)
        context.launcher.hide()

        var leader: Double?
        var engine = context.shortcuts.makeEngine()
        if case .pending(let prefix, let title, let hints) = engine.handle(Chord(.character("k"), .hyper), at: .now) {
            context.overlay.show(prefix: prefix, title: title, hints: hints.map(LeaderOverlay.Row.init))
            await pause(250)
            leader = (await WindowCapture.image(of: context.overlay.window)).map(WindowCapture.edgeAlpha)
            context.overlay.hide()
        }
        record(
            "Glass shadows fit their windows (no square edges)",
            (launcher ?? 1) <= limit && (leader ?? 1) <= limit,
            String(format: "edge opacity: launcher %.3f, leader %.3f (max %.2f)", launcher ?? -1, leader ?? -1, limit),
            nil
        )
    }

    /// The launcher and the leader overlay as the user sees them: screen
    /// captures over dark, light and photo backdrops in both appearances.
    /// No straight edge may show where a window clips its glass.
    private func glassAsSeen() async {
        if let error = await GlassCheck.accessError() {
            GlassCheck.requestAccess()
            record(
                "Glass as seen on screen (launcher, leader)",
                false,
                "Screen Recording not granted (\(error)): enable skil.li in System Settings › Privacy & Security › Screen & System Audio Recording, then run again",
                nil
            )
            return
        }
        let launcher = context.launcher
        let launcherMeasures = await GlassCheck.measure(
            window: launcher.window,
            name: "glass-launcher",
            show: {
                launcher.show(triggeredAt: .now)
                _ = launcher.simulateTyping("sa")
            },
            hide: { launcher.hide() },
            into: context.snapshotDirectory
        )
        reportGlass("Launcher glass as seen on screen: no square edges", launcherMeasures)

        var engine = context.shortcuts.makeEngine()
        guard case .pending(let prefix, let title, let hints) = engine.handle(Chord(.character("k"), .hyper), at: .now) else {
            record("Leader overlay glass as seen on screen: no square edges", false, "✦K is not a group", nil)
            return
        }
        let overlay = context.overlay
        let rows = hints.map(LeaderOverlay.Row.init)
        let leaderMeasures = await GlassCheck.measure(
            window: overlay.window,
            name: "glass-leader",
            show: { overlay.show(prefix: prefix, title: title, hints: rows) },
            hide: { overlay.hide() },
            into: context.snapshotDirectory
        )
        reportGlass("Leader overlay glass as seen on screen: no square edges", leaderMeasures)
    }

