    /// A shortcuts.json written before the AI actions gets them, without
    /// taking keys the user already uses. No file is touched.
    private func newDefaultsReachExistingShortcuts() {
        var older = ShortcutConfig.defaults
        older.shortcuts.removeAll { $0.id.hasPrefix("leader.ai.") }
        older.shortcuts.append(.init(id: "custom.mine", action: .openURL("https://example.com"), keys: "hyper+k e", label: "Mine"))
        let merged = older.addingMissingDefaults()
        let fix = merged.shortcuts.first { $0.id == "leader.ai.fix" }
        let english = merged.shortcuts.first { $0.id == "leader.ai.english" }
        let mine = merged.shortcuts.first { $0.id == "custom.mine" }
        let passed = fix?.keys == "hyper+k g" && english != nil && english?.keys == nil && mine?.keys == "hyper+k e"
            && ShortcutConfig.defaults.addingMissingDefaults() == ShortcutConfig.defaults
        record(
            "Shortcuts: new built-ins reach an existing shortcuts.json",
            passed,
            "fix: \(fix?.keys ?? "missing"), english: \(english.map { $0.keys ?? "no keys (✦K E taken)" } ?? "missing"), user's ✦K E kept: \(mine?.keys == "hyper+k e")",
            nil
        )
    }

    // MARK: - Commands

    /// Create, edit, duplicate, delete, reset and About You all land in the
    /// prompt files (the self-test's own folder).
    /// A fix.md left as an earlier version wrote it (what is on the user's
    /// Mac, byte for byte) becomes the current Fix; an edited one stays.
    private func builtInPromptsUpgrade() {
        let name = "Built-in prompts: an untouched earlier Fix is upgraded, an edited one is kept"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-prompts-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let earlier = "---\ntitle: Fix Spelling & Grammar\n---\nFix spelling, grammar, conjugation and punctuation mistakes. Change only what is wrong; keep the tone, language and formatting.\n\n{selection}\n"
        let edited = "---\ntitle: Improve Writing\n---\nMake it shorter.\n\n{selection}\n"
        try? earlier.write(to: folder.appendingPathComponent("fix.md"), atomically: true, encoding: .utf8)
        try? edited.write(to: folder.appendingPathComponent("improve.md"), atomically: true, encoding: .utf8)
        let library = PromptLibrary(folder: folder)
        library.reload()
        let fix = library.command("fix")?.prompt ?? ""
        let file = (try? String(contentsOf: folder.appendingPathComponent("fix.md"), encoding: .utf8)) ?? ""
        let improve = library.command("improve")?.prompt ?? ""
        let upgraded = fix.contains("on/ont") && file.contains("on/ont")
        let kept = improve.hasPrefix("Make it shorter.")
        record(name, upgraded && kept, "Fix upgraded in memory and on disk: \(upgraded); edited Improve kept: \(kept)", nil)
    }

    private func siCommandsEditedAsFiles() {
        let name = "Commands: edits are saved as files"
        let model = context.aiCommands
        model.refresh()
        guard let folder = model.library.folder else {
            record(name, false, "no prompt folder", nil)
            return
        }
        func file(_ id: String) -> String? { try? String(contentsOf: folder.appendingPathComponent("\(id).md"), encoding: .utf8) }

        var command = model.newCommand()
        let created = file(command.id) != nil && model.shortcutEntry(for: command.id) != nil
        command.title = "Reply as Me"
        command.prompt = "Reply to {selection} in {language}."
        command.includeProfile = true
        command.model = .claude("sonnet")
        model.save(command)
        model.refresh()
        let saved = model.library.command(command.id) == command
            && file(command.id)?.contains("profile: true") == true && file(command.id)?.contains("model: sonnet") == true
        // A draft until its editor saves it.
        let copy = model.duplicate(command)
        let duplicated = copy.id != command.id && copy.prompt == command.prompt && copy.model == command.model
            && file(copy.id) == nil && model.shortcutEntry(for: copy.id) == nil
        model.save(copy)
        model.delete(copy.id)
        model.delete(command.id)
        let deleted = file(command.id) == nil && file(copy.id) == nil && model.shortcutEntry(for: command.id) == nil

        var fix = model.library.command("fix")!
        fix.prompt = "Changed {selection}"
        model.save(fix)
        let modified = model.isModified("fix")
        model.reset("fix")
        let reset = !model.isModified("fix") && file("fix")?.contains("{selection}") == true && file("fix")?.contains("Changed") == false

        let originalProfile = model.profile
        model.profile = "I am Camille, I write short."
        model.saveProfile()
        let profileSaved = (try? String(contentsOf: folder.appendingPathComponent(PromptLibrary.profileFileName), encoding: .utf8))?.contains("I am Camille") == true
        model.profile = originalProfile
        model.saveProfile()

        record(
            name,
            created && saved && duplicated && deleted && modified && reset && profileSaved,
            "created: \(created), saved: \(saved), duplicated: \(duplicated), deleted: \(deleted), built-in modified then reset: \(modified && reset), About You saved: \(profileSaved)",
            nil
        )
    }

    /// The editor records a chain and a direct shortcut for one command,
    /// typed the way people do (Caps Lock held); both run it from an app.
    private func siCommandShortcutsRecordedInEditor() async {
        let name = "Commands editor: record a chain (✦K then ✦J) and a direct ✦J for one command; both run it"
        let model = context.aiCommands
        let store = context.shortcuts
        context.ai.testEngine = FakeTextEngine(chunks: ["ok"], delay: .milliseconds(20))
        let command = model.newCommand()
        defer {
            context.ai.testEngine = nil
            model.delete(command.id)
        }
        context.settings.show(pane: .commands)
        await pause(400)
        model.activeEditor = nil
        model.editing = command
        _ = await waitUntil(timeout: 2) { model.activeEditor != nil }
        await pause(300)
        guard let first = model.shortcutEntry(for: command.id), let k = keyCode("k"), let j = keyCode("j") else {
            record(name, false, "no shortcut entry for the new command", nil)
            await closeSettings()
            return
        }

        // Chain, Caps Lock held for both keys; capture while it waits.
        store.beginRecording(first.id)
        await pause(150)
        postKey(Self.ownTriggerKeyCode, down: true)
        await pause(15)
        postKey(k, down: true); await pause(12); postKey(k, down: false)
        await pause(350)
        await saveSheet(as: "command-recording-chain.png")
        postKey(j, down: true); await pause(12); postKey(j, down: false)
        postKey(Self.ownTriggerKeyCode, down: false)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }

        // A second, direct shortcut, from the editor's own button. It shows
        // once every row has keys, drawn by SwiftUI after the store ended
        // the recording: wait for the button itself, not the store.
        let anotherAtOnce = Self.axButton("Add Another Shortcut") != nil
        let anotherDrawn = await waitUntil(timeout: 2) { Self.axButton("Add Another Shortcut") != nil }
        let another = Self.axButton("Add Another Shortcut")
        let anotherNamed = another.map { "title “\(Self.axString($0, kAXTitleAttribute))”, description “\(Self.axString($0, kAXDescriptionAttribute))”" } ?? "not found"
        let added = Self.pressButton("Add Another Shortcut")
        _ = await waitUntil(timeout: 1) { store.recordingID != nil }
        let second = store.recordingID ?? ""
        await pause(150)
        _ = await hyperChord(["j"], trigger: Self.ownTriggerKeyCode)
        await pause(300)
        await saveSheet(as: "command-recording-direct.png")
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        await pause(300)
        await saveSheet(as: "command-shortcuts.png")
        // Shown in the editor, written only by Save.
        let shown = model.editorShortcuts(for: command.id).map { $0.keys ?? "none" }
        let unsaved = keys(first.id) == nil && keys(second) == nil
        let saved = Self.pressLastButton(labelled: "Save")
        _ = await waitUntil(timeout: 2) { model.editing == nil }
        let chain = keys(first.id)
        let direct = keys(second)
        await closeSettings()

        var runs: [String] = []
        for chord in [["k", "j"], ["j"]] as [[Character]] {
            guard await focusTestWindow() else { return }
            window.makeFirstResponder(textView)
            textView.string = "some text"
            textView.selectAll(nil)
            await pause(60)
            _ = await hyperChord(chord, trigger: Self.ownTriggerKeyCode)
            if await waitUntil(timeout: 2, { self.context.aiActions.popover.isVisible }) != nil {
                runs.append(chord.map(String.init).joined(separator: " then "))
            }
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !self.context.aiActions.popover.isVisible }
        }
        record(
            name,
            added && shown == ["hyper+k j", "hyper+j"] && unsaved && saved && chain == "hyper+k j" && direct == "hyper+j" && runs.count == 2,
            "Add Another Shortcut there as the recording ended: \(anotherAtOnce), found in \(anotherDrawn.map { "\(Int($0.milliseconds)) ms" } ?? "never (2 s)"), \(anotherNamed), pressed: \(added), in the editor: \(shown), nothing written before Save: \(unsaved), Save pressed: \(saved), chain saved: \(chain ?? "none"), direct saved: \(direct ?? "none"), ran with: \(runs)",
            nil
        )
    }

    /// The ⓧ next to each shortcut, pressed like a click (Accessibility):
    /// the extra shortcut goes with its row, the last one is emptied; both
    /// written only by Save.
    private func siCommandShortcutsRemovedInEditor() async {
        let name = "Shortcuts: ⓧ removes an extra shortcut, then empties the last one; Save writes it"
        let model = context.aiCommands
        let store = context.shortcuts
        let command = model.newCommand()
        defer { model.delete(command.id) }
        guard let first = model.shortcutEntry(for: command.id),
              let chain = try? Chord.sequence("hyper+k j"), let direct = try? Chord.sequence("hyper+j")
        else {
            record(name, false, "could not set up the command's shortcuts", nil)
            return
        }
        try? store.setKeys(chain, for: first.id)
        let second = store.add(.aiPrompt(command.id))
        try? store.setKeys(direct, for: second)

        context.settings.show(pane: .commands)
        await pause(400)
        model.activeEditor = nil
        model.editing = command
        _ = await waitUntil(timeout: 2) { model.activeEditor != nil }
        await pause(400)
        let before = model.editorShortcuts(for: command.id).count
        let pressedExtra = Self.pressLastButton(labelled: "Remove Shortcut")
        _ = await waitUntil(timeout: 1) { model.editorShortcuts(for: command.id).count == 1 }
        let afterExtra = model.editorShortcuts(for: command.id)
        await pause(300)
        let pressedLast = Self.pressLastButton(labelled: "Remove Shortcut")
        _ = await waitUntil(timeout: 1) { model.editorShortcuts(for: command.id).first?.keys == nil }
        let afterLast = model.editorShortcuts(for: command.id)
        await pause(300)
        await saveSheet(as: "command-shortcuts-removed.png")
        // Still both saved until Save.
        let unsaved = model.shortcutEntries(for: command.id).compactMap(\.keys) == ["hyper+k j", "hyper+j"]
        let saved = Self.pressLastButton(labelled: "Save")
        _ = await waitUntil(timeout: 2) { model.editing == nil }
        let written = model.shortcutEntries(for: command.id)
        await closeSettings()
        // A draft's ⓧ offers no undo card (Cancel takes it back); one left
        // up would be closed here for the next check.
        let undoOffered = context.aiActions.popover.isVisible && context.aiActions.popover.shownTitle == "Shortcut Removed"
        context.aiActions.cancel()

        let extraGone = afterExtra.count == 1 && afterExtra.first?.keys == "hyper+k j"
        let lastEmptied = afterLast.count == 1 && afterLast.first?.keys == nil
        let savedEmpty = written.count == 1 && written.first?.keys == nil
        record(
            name,
            before == 2 && pressedExtra && pressedLast && extraGone && lastEmptied && unsaved && saved && savedEmpty && !undoOffered,
            "shortcuts before: \(before), after ⓧ: \(afterExtra.map { $0.keys ?? "none" }), after ⓧ again: \(afterLast.map { $0.keys ?? "none" }); saved untouched until Save: \(unsaved), Save pressed: \(saved), then \(written.map { $0.keys ?? "none" }); no undo card for a draft: \(!undoOffered)",
            nil
        )
    }

    /// Presses the last enabled button with this accessibility label in
    /// skil.li's own windows, as a click would.
    private static func pressLastButton(labelled label: String) -> Bool {
        var found: [AXUIElement] = []
        walkAX(from: AXUIElementCreateApplication(getpid())) { element in
            var role: CFTypeRef?
            var description: CFTypeRef?
            var enabled: CFTypeRef?
            AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &role)
            AXUIElementCopyAttributeValue(element, kAXDescriptionAttribute as CFString, &description)
            AXUIElementCopyAttributeValue(element, kAXEnabledAttribute as CFString, &enabled)
            if role as? String == kAXButtonRole, description as? String == label, enabled as? Bool != false {
                found.append(element)
            }
            return true
        }
        guard let target = found.last else { return false }
        return AXUIElementPerformAction(target, kAXPressAction as CFString) == .success
    }

    /// Presses the last enabled button whose title, value or description
    /// is `title`, under `root` (skil.li's windows by default), as a click
    /// would: SwiftUI's buttons say it in their description, a dialog's
    /// in their title.
    private static func pressButton(_ title: String, under root: AXUIElement? = nil) -> Bool {
        guard let target = axButton(title, under: root) else { return false }
        return AXUIElementPerformAction(target, kAXPressAction as CFString) == .success
    }

    /// The last enabled button named `title` (title, value or description).
    private static func axButton(_ title: String, under root: AXUIElement? = nil) -> AXUIElement? {
        axElements(roles: [kAXButtonRole], under: root, where: { $0 == title }).filter(axEnabled).last
    }

    private static func axString(_ element: AXUIElement, _ attribute: String) -> String {
        var value: CFTypeRef?
        AXUIElementCopyAttributeValue(element, attribute as CFString, &value)
        return value as? String ?? ""
    }

    private static func axEnabled(_ element: AXUIElement) -> Bool {
        var enabled: CFTypeRef?
        AXUIElementCopyAttributeValue(element, kAXEnabledAttribute as CFString, &enabled)
        return enabled as? Bool != false
    }

    /// skil.li's elements with `role`, named or not (a sheet, a stepper).
    private static func axElements(role: String, under root: AXUIElement? = nil) -> [AXUIElement] {
        var found: [AXUIElement] = []
        walkAX(from: root ?? AXUIElementCreateApplication(getpid())) { element in
            var value: CFTypeRef?
            AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &value)
            if value as? String == role { found.append(element) }
            return true
        }
        return found
    }

    /// The words a dialog (a sheet) shows: its title and message.
    private static func axTexts(under root: AXUIElement) -> [String] {
        axElements(roles: [kAXStaticTextRole], under: root, where: { _ in true }).compactMap(axTitle)
    }

    private func saveScreenshot(ofKeyWindowAs name: String) async {
        guard let window = NSApp.keyWindow else { return }
        await saveScreenshot(of: window, as: name)
    }

    /// The sheet in front (an editor), alone, as it shows.
    private func saveSheet(as name: String) async {
        guard let sheet = NSApp.windows.first(where: { $0.isSheet && $0.isVisible }) else { return }
        await saveWindow(sheet, as: name)
    }

    /// The message sent holds the variables' values and About You.
    private func siCommandFillsVariables() async {
        let name = "Commands: variables and About You reach Claude"
        let model = context.aiCommands
        let engine = FakeTextEngine(chunks: ["ok"], delay: .milliseconds(20))
        context.ai.testEngine = engine
        let originalProfile = model.profile
        var command = model.newCommand()
        defer {
            context.ai.testEngine = nil
            model.delete(command.id)
            model.profile = originalProfile
            model.saveProfile()
        }
        command.prompt = "App {app}, on {day}, clipboard [{clipboard}]: {selection}"
        command.includeProfile = true
        model.save(command)
        model.profile = "I am Camille."
        model.saveProfile()
        setClipboard("clip-sentinel")

        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "hello there"
        textView.selectAll(nil)
        await pause(60)
        context.aiActions.run(command.id, triggeredAt: .now)
        _ = await waitUntil(timeout: 3) { self.context.aiActions.popover.isVisible && self.context.aiActions.popover.phase == .done }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let message = context.aiActions.lastMessage ?? ""
        let weekday = { let f = DateFormatter(); f.locale = .current; f.setLocalizedDateFormatFromTemplate("EEEE"); return f.string(from: .now) }()
        let app = NSRunningApplication.current.localizedName ?? "?"
        let checks = [
            ("About You first", message.hasPrefix("About me: I am Camille.")),
            ("app", message.contains("App \(app)")),
            ("day", message.contains(weekday)),
            ("clipboard, quoted", message.contains("[\"\"\"\nclip-sentinel\n\"\"\"]")),
            ("selection, quoted", message.hasSuffix("\"\"\"\nhello there\n\"\"\""))
        ]
        let missing = checks.filter { !$0.1 }.map(\.0)
        record(name, missing.isEmpty, missing.isEmpty ? "message: \(message.replacingOccurrences(of: "\n", with: " ⏎ "))" : "missing \(missing.joined(separator: ", ")) in: \(message)", nil)
    }

    /// A command started from the launcher answers in the launcher's place:
    /// the card's top and width are the launcher's, and it does not move
    /// while a long answer streams in (it only grows down). Started on a
    /// selection, it goes under it and stays put too.
    /// Nothing selected, an app that says no caret (Codex's web area on a
    /// second screen): the card goes beside a field or a compose box, never
    /// beside a whole document; then it takes the launcher's place. Read
    /// through Accessibility on a focusable view of the test window, as
    /// the card is placed.
    private func cardBesideAFieldNotADocument() async {
        let name = "AI card, nothing selected and no caret said: beside a field (≤ 320 pt tall), the launcher's place beside a whole document"
        final class Focusable: NSView {
            override var acceptsFirstResponder: Bool { true }
            override func isAccessibilityElement() -> Bool { true }
            override func accessibilityRole() -> NSAccessibility.Role? { .group }
        }
        guard await focusTestWindow(), let content = window.contentView else { return }
        let view = Focusable(frame: NSRect(x: 40, y: 40, width: 600, height: 520))
        content.addSubview(view)
        defer { view.removeFromSuperview() }
        window.makeFirstResponder(view)
        await pause(150)
        let document = AIActionController.selectionAnchor()
        view.frame = NSRect(x: 40, y: 40, width: 400, height: 28)
        await pause(150)
        let field = AIActionController.selectionAnchor()
        window.makeFirstResponder(textView)
        record(name, document == nil && field.map { abs($0.height - 28) < 1 } == true,
               "a 600 × 520 view: \(document.map { "\($0)" } ?? "no anchor (the launcher's place)"); a 400 × 28 one: \(field.map { "\($0)" } ?? "no anchor")", nil)
    }

    private func cardTakesLauncherPlace() async {
        let name = "AI card: from the launcher it takes the launcher's place (same top, same width) and stays put while it grows; on a selection it stays put under it"
        let words = (1...90).map { "word\($0) " }
        context.ai.testEngine = FakeTextEngine(chunks: words, delay: .milliseconds(12))
        let command = scratchCommand(prompt: "Write a long answer about {selection}.", output: .card)
        defer {
            context.ai.testEngine = nil
            context.aiCommands.delete(command.id)
        }
        let popover = context.aiActions.popover
        let margin = Theme.glassMargin
        // Before its first layout the panel is smaller than its margins.
        func cardFrame() -> NSRect {
            let frame = popover.window.frame.insetBy(dx: margin, dy: margin)
            return frame.isNull || frame.isInfinite ? .zero : frame
        }

        // From the launcher.
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "the sea"
        textView.selectAll(nil)
        await pause(60)
        let launcher = context.launcher.restingGlassFrame()
        context.aiActions.run(command.id, triggeredAt: .now, fromLauncher: launcher)
        _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .streaming }
        var tops: Set<Int> = []
        var heights: Set<Int> = []
        var lefts: Set<Int> = []
        let deadline = ContinuousClock.now + .seconds(5)
        while ContinuousClock.now < deadline, popover.phase != .done {
            if popover.isVisible, cardFrame().width > 0 {
                tops.insert(Int(cardFrame().maxY.rounded()))
                lefts.insert(Int(cardFrame().minX.rounded()))
                heights.insert(Int(cardFrame().height.rounded()))
            }
            try? await Task.sleep(for: .milliseconds(15))
        }
        let frame = cardFrame()
        let samePlace = abs(frame.maxY - launcher.maxY) < 1 && abs(frame.minX - launcher.minX) < 1 && abs(frame.width - launcher.width) < 1
        let stillFromLauncher = tops.count == 1 && lefts.count == 1 && heights.count > 1
        let launcherDetail = "\(tops.count) top, \(lefts.count) left over \(heights.count) heights"
        await pause(150)
        await captureLauncherPlaceCard(frame: frame, as: "ai-card-launcher-place.png")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !popover.isVisible }

        // On a selection (the test window's text): under it, still.
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "the mountains"
        textView.selectAll(nil)
        await pause(60)
        context.aiActions.run(command.id, triggeredAt: .now)
        _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .streaming }
        tops = []
        var bottoms: Set<Int> = []
        heights = []
        let selectionDeadline = ContinuousClock.now + .seconds(5)
        while ContinuousClock.now < selectionDeadline, popover.phase != .done {
            if popover.isVisible, cardFrame().width > 0 {
                tops.insert(Int(cardFrame().maxY.rounded()))
                bottoms.insert(Int(cardFrame().minY.rounded()))
                heights.insert(Int(cardFrame().height.rounded()))
            }
            try? await Task.sleep(for: .milliseconds(15))
        }
        let selectionWidth = Int(cardFrame().width.rounded())
        // Growing down keeps its top; growing up (no room below) its bottom.
        let stillOnSelection = (tops.count == 1 || bottoms.count == 1) && heights.count > 1
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, samePlace && stillFromLauncher && stillOnSelection && selectionWidth == 460,
               "from the launcher: top \(Int(frame.maxY)) vs \(Int(launcher.maxY)), left \(Int(frame.minX)) vs \(Int(launcher.minX)), width \(Int(frame.width)) vs \(Int(launcher.width)); positions while growing: \(launcherDetail); on a selection: \(tops.count) top / \(bottoms.count) bottom over \(heights.count) heights, width \(selectionWidth)", nil)
    }

    /// A card that shows up while the launcher is open (a late "copied"
    /// note): typing and Esc still go to the launcher; Esc again closes the
    /// card. (Opening the launcher over a card closes the card: the user
    /// moved on.)
    private func launcherKeysOverCard() async {
        let name = "Launcher with a card showing up: keys and Esc go to the launcher, not to the card"
        let popover = context.aiActions.popover
        let launcher = context.launcher
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        let opened = await waitUntil(timeout: 1) { launcher.isVisible } != nil
        context.aiActions.notify("Selftest note", caller: "Test", run: nil, seconds: 6)
        let shown = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText == "Selftest note" } != nil
        for character in "abc" { await pressKey(character) }
        let typed = await waitUntil(timeout: 1) { launcher.query == "abc" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let launcherClosed = await waitUntil(timeout: 1) { !launcher.isVisible } != nil
        let cardKept = popover.isVisible && popover.shownText == "Selftest note"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let cardClosed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        record(name, opened && shown && typed && launcherClosed && cardKept && cardClosed,
               "launcher opened: \(opened), card shown over it: \(shown), typed in the launcher: \(typed), Esc closed the launcher: \(launcherClosed), card kept: \(cardKept), Esc again closed the card: \(cardClosed)", nil)
    }

    /// After an answer the card offers "In Claude Code ⌘↩"; ⌘↩ hands the
    /// request and the answer to a new session (recorded here) and closes.
    private func handoffFromCard() async {
        let name = "Continue a conversation: the card offers it after an answer, ⌘↩ hands over the request and the answer"
        // The app finds Claude Code at launch; the self-test when it needs it.
        await context.ai.refresh()
        guard let handoff = context.aiActions.handoff, !handoff.targets.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "neither Claude Code nor Codex on this Mac", latencyMs: nil))
            return
        }
        context.ai.testEngine = FakeTextEngine(chunks: ["La mer ", "est salée."], delay: .milliseconds(15))
        let command = scratchCommand(prompt: "Explain {selection}.", output: .card)
        var handed: [(Handoff.Target, String)] = []
        handoff.opened = { handed.append(($0, $1)) }
        defer {
            context.ai.testEngine = nil
            context.aiCommands.delete(command.id)
            handoff.opened = nil
        }
        let popover = context.aiActions.popover
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "the sea"
        textView.selectAll(nil)
        await pause(60)
        context.aiActions.run(command.id, triggeredAt: .now, fromLauncher: context.launcher.restingGlassFrame())
        let done = await waitUntil(timeout: 4) { popover.isVisible && popover.phase == .done } != nil
        let expected = handoff.targets.contains(context.preferences.handoffTarget) ? context.preferences.handoffTarget : handoff.targets[0]
        let offered = popover.hintTitles.contains("In \(expected.title)")
        await pause(150)
        await captureLauncherPlaceCard(frame: popover.window.frame.insetBy(dx: Theme.glassMargin, dy: Theme.glassMargin), as: "ai-card-continue.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
        let sent = await waitUntil(timeout: 1) { !handed.isEmpty } != nil
        let closed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        let conversation = handed.first?.1 ?? ""
        let complete = handed.first?.0 == expected && conversation.contains("Explain") && conversation.contains("the sea")
            && conversation.contains("You answered:\nLa mer est salée.")
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, done && offered && sent && closed && complete,
               "answered: \(done), hints \(popover.hintTitles), handed to \(handed.first?.0.title ?? "nothing"): \(complete), card closed: \(closed)", nil)
    }

    /// The real launch with a stand-in CLI that writes down its arguments:
    /// Terminal for Claude Code, Ghostty for Codex when it is installed. The
    /// conversation arrives whole (quotes, $(…) not run) and nothing of it
    /// stays on disk.
    private func handoffLaunchesTerminal() async {
        let name = "Continue a conversation: Terminal and Ghostty open the CLI with the conversation whole; nothing stays on disk"
        guard let handoff = context.aiActions.handoff else {
            record(name, false, "no handoff", nil)
            return
        }
        let base = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-handoff", isDirectory: true)
        try? FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: base) }
        let conversation = "User:\nit's \"quoted\" and $(echo not run) `nor this`\n\nYou answered:\nok"
        var details: [String] = []
        var passed = true
        for terminal in HandoffLauncher.terminals {
            let target: Handoff.Target = terminal == .terminal ? .claude : .codex
            let output = base.appendingPathComponent("\(terminal.rawValue).txt")
            let fake = base.appendingPathComponent("fake-\(terminal.rawValue)")
            try? "#!/bin/zsh\nfor argument in \"$@\"; do printf '%s\\0' \"$argument\"; done > \(Handoff.quotedForTest(output.path))\n"
                .write(to: fake, atomically: true, encoding: .utf8)
            try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: fake.path)
            let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: terminal.bundleID).isEmpty
            let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-handoff", isDirectory: true)
            let before = Set((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? [])
            do {
                try handoff.launch(target, in: terminal, conversation: conversation, binaryOverride: fake)
            } catch {
                passed = false
                details.append("\(terminal.title): \(error.localizedDescription)")
                continue
            }
            let ran = await waitUntil(timeout: 10) { FileManager.default.fileExists(atPath: output.path) } != nil
            await pause(300)
            let arguments = ((try? String(contentsOf: output, encoding: .utf8)) ?? "").split(separator: "\0", omittingEmptySubsequences: false).map(String.init).dropLast()
            let expected = target == .claude ? ["--append-system-prompt", conversation] : [conversation]
            let whole = Array(arguments) == expected
            let after = Set((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? [])
            let cleaned = after.subtracting(before).isEmpty
            passed = passed && ran && whole && cleaned
            details.append("\(terminal.title) → \(target.title): ran \(ran), conversation whole \(whole), files gone \(cleaned)")
            if !wasRunning {
                for app in NSRunningApplication.runningApplications(withBundleIdentifier: terminal.bundleID) { app.terminate() }
                await pause(500)
            }
        }
        record(name, passed && !details.isEmpty, details.joined(separator: "; "), nil)
    }

    /// Tools settings read back by two launches in a row: the first
    /// used to write the file before reading it, the second found it empty.
    private func toolSettingsSurviveRelaunches() {
        let name = "Tools settings survive two launches: approval mode, server, a tool's choice, your tool"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-persist", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        let file = folder.appendingPathComponent("tools.json")
        let first = ToolSettings(fileURL: file, keychainPrefix: "selftest-")
        first.mode = .ask
        first.saveServer(MCPServerConfig(name: "selftest-kept", url: "https://example.com/mcp", auth: .oauth))
        first.setOverride(.always, for: "set_clipboard")
        first.saveCustomTool(CustomTool(name: "selftest-kept-hook", instructions: "Send to the test hook.", url: "https://example.com/hook"))
        _ = ToolSettings(fileURL: file, keychainPrefix: "selftest-")
        let third = ToolSettings(fileURL: file, keychainPrefix: "selftest-")
        let kept = third.mode == .ask && third.server(named: "selftest-kept")?.auth == .oauth
            && third.override(for: "set_clipboard") == .always && third.customTool(named: "selftest-kept-hook") != nil
        record(name, kept, "mode \(third.mode.rawValue), servers \(third.servers.map(\.name)), set_clipboard \(third.override(for: "set_clipboard")?.rawValue ?? "default"), your tools \(third.customTools.map(\.name))", nil)
    }

    /// Signing in to an MCP server, against a stand-in on 127.0.0.1 that
    /// speaks the MCP authorization spec: 401 with its metadata, the
    /// authorization server's metadata, client registration, /authorize
    /// that checks PKCE and redirects back, /token with a short-lived token
    /// then its renewal. A pasted token becomes the right header too.
    private func mcpServerSignIn() async {
        let name = "MCP sign-in: OAuth against a stand-in server (discovery, registration, PKCE, return, tokens, renewal); a pasted token as Bearer or its own header"
        let auth = context.tools.settings.auth
        let book = OAuthBook()
        guard let fake = LoopbackServer(handler: { request in Self.standInOAuth(request, book: book) }), let port = await fake.port() else {
            record(name, false, "no stand-in server", nil)
            return
        }
        defer { fake.stop() }
        let base = "http://127.0.0.1:\(port)"
        let oauthServer = MCPServerConfig(name: "selftest-oauth", url: base + "/mcp", auth: .oauth)
        let tokenServer = MCPServerConfig(name: "selftest-token", url: base + "/mcp", auth: .token)
        let keyServer = MCPServerConfig(name: "selftest-key", url: base + "/mcp", auth: .token, header: "X-Api-Key")
        let opener = auth.openBrowser
        defer {
            auth.openBrowser = opener
            for server in [oauthServer, tokenServer, keyServer] { auth.forget(server.name) }
        }
        // The "browser": follows /authorize's redirect back to skil.li.
        auth.openBrowser = { url in Task { _ = try? await URLSession.shared.data(from: url) } }

        var details: [String] = []
        var signedIn = false
        do {
            try await auth.signIn(oauthServer)
            signedIn = auth.session(for: oauthServer.name) != nil
        } catch {
            details.append("sign-in failed: \(error.localizedDescription)")
        }
        let checks = book.read
        // The first token lasts 30 s: the run's headers renew it at once.
        let headers = (try? await auth.headers(for: oauthServer)) ?? [:]
        let renewed = headers["Authorization"] == "Bearer AT2" && book.read.refreshes == 1
        var accepted = false
        if let url = URL(string: base + "/mcp") {
            var call = URLRequest(url: url)
            call.httpMethod = "POST"
            headers.forEach { call.setValue($1, forHTTPHeaderField: $0) }
            accepted = ((try? await URLSession.shared.data(for: call))?.1 as? HTTPURLResponse)?.statusCode == 200
        }
        let config = oauthServer.claudeConfig(headers: headers)
        let inConfig = (config["headers"] as? [String: String])?["Authorization"] == "Bearer AT2"
        details.append("signed in: \(signedIn) (registered \(checks.registered), PKCE checked \(checks.pkce), resource \(checks.resource), scope \(checks.scope ?? "none")); renewed: \(renewed); the server took the token: \(accepted); in the run's config: \(inConfig)")

        auth.setToken("abc", for: tokenServer.name)
        auth.setToken("abc", for: keyServer.name)
        let bearer = (try? await auth.headers(for: tokenServer)) == ["Authorization": "Bearer abc"]
        let custom = (try? await auth.headers(for: keyServer)) == ["X-Api-Key": "abc"]
        let missing = (try? await auth.headers(for: MCPServerConfig(name: "selftest-none", url: base + "/mcp", auth: .oauth))) == nil
        // The address edited to another host: the session is not sent there.
        let moved = MCPServerConfig(name: oauthServer.name, url: "http://localhost:\(port)/mcp", auth: .oauth)
        let notFollowed = (try? await auth.headers(for: moved)) == nil && auth.session(for: oauthServer.name) == nil
        details.append("token as Bearer: \(bearer), own header: \(custom), not signed in refused: \(missing), not sent to another host: \(notFollowed)")
        record(name, signedIn && checks.registered && checks.pkce && checks.resource && checks.scope == "test.read" && renewed && accepted
               && inConfig && bearer && custom && missing && notFollowed, details.joined(separator: "; "), nil)
    }

    /// Servers set up in Claude Code, Claude for Mac, Codex and Cursor
    /// (scratch copies of their files): skil.li itself and an SSE server
    /// left out, a token moved to the Keychain (not in tools.json), a name
    /// taken renamed, a server answering 401 set to sign in with OAuth, a
    /// command server's tools listed.
    private func serversImportedFromOtherApps() async {
        let name = "Import From Other Apps: Claude Code, Claude for Mac, Codex, Cursor; token to the Keychain, OAuth found by its 401, tools listed"
        let settings = context.tools.settings
        let book = ToolListBook()
        guard let fake = LoopbackServer(handler: { request in
            request.target == "/oauth" ? LoopbackServer.Response(status: 401, headers: ["WWW-Authenticate": "Bearer"]) : Self.standInTools(request, book: book)
        }), let port = await fake.port(), let executable = Bundle.main.executablePath, let socket = context.tools.socketPath else {
            record(name, false, "no stand-in server", nil)
            return
        }
        defer { fake.stop() }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-import", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        let base = "http://127.0.0.1:\(port)"
        let claude = #"{"oauthAccount": {"emailAddress": "x"}, "mcpServers": {"selftest-web": {"type": "http", "url": "\#(base)/mcp", "headers": {"Authorization": "Bearer abc"}}, "selftest-signin": {"type": "http", "url": "\#(base)/oauth"}, "skilli": {"command": "\#(executable)", "args": ["mcp"]}, "selftest-old": {"type": "sse", "url": "\#(base)/sse"}}}"#
        let desktop = #"{"mcpServers": {"selftest-web": {"url": "\#(base)/other", "headers": {"Authorization": "Bearer zzz"}}}}"#
        // skil.li's bridge through env: a command server that is not skil.li itself.
        let codex = "[mcp_servers.selftest-bridge]\ncommand = \"/usr/bin/env\"\nargs = [\"\(executable)\", \"mcp\", \"--socket\", \"\(socket)\"]\n"
        let files: [(MCPImport.Source, String, String)] = [(.claudeCode, "claude.json", claude), (.claudeDesktop, "desktop.json", desktop),
                                                           (.codex, "config.toml", codex), (.cursor, "missing.json", "")]
        var locations: [MCPServerImporter.Location] = []
        for (source, file, text) in files {
            let url = folder.appendingPathComponent(file)
            if !text.isEmpty { try? text.write(to: url, atomically: true, encoding: .utf8) }
            locations.append(MCPServerImporter.Location(source: source, file: url))
        }
        let found = MCPServerImporter.find(in: locations)
        let names = found.map { "\($0.source.rawValue):\($0.name)" }
        let added = await MCPServerImporter.add(found, to: settings)
        defer { for server in added { settings.removeServer(named: server) } }

        let web = settings.server(named: "selftest-web")
        let renamed = settings.server(named: "selftest-web-claude-mac")
        let tokenKept = web?.auth == .token && settings.auth.token(for: "selftest-web") == "Bearer abc"
            && settings.auth.token(for: "selftest-web-claude-mac") == "Bearer zzz"
        let fileText = (try? String(contentsOf: ToolSettings.fileURLForSelfTest(settings), encoding: .utf8)) ?? ""
        let notInFile = !fileText.isEmpty && !fileText.contains("Bearer abc") && !fileText.contains("Bearer zzz")
        let oauth = settings.server(named: "selftest-signin")?.auth == .oauth
        let listed = settings.serverTools["selftest-web"]?.count == 3 && (settings.serverTools["selftest-bridge"]?.isEmpty == false)
        let leftOut = !names.contains { $0.hasSuffix(":skilli") } && found.first { $0.name == "selftest-old" }?.problem != nil
            && !added.contains("selftest-old")
        record(name, tokenKept && notInFile && renamed?.url == base + "/other" && oauth && listed && leftOut && added.count == 4,
               "found \(names); added \(added); token in the Keychain: \(tokenKept), not in tools.json: \(notInFile); 401 → OAuth: \(oauth); tools listed: \(listed); skil.li and SSE left out: \(leftOut)", nil)
    }

    /// A web server's tools, read with the user's token: its session id,
    /// two pages (the second as Server-Sent Events), the hints; kept on
    /// disk. A command server's: skil.li's own bridge over stdio.
    private func serverToolsListed() async {
        let name = "Servers' tools: listed over HTTP (token, session, pages, SSE) and stdio (the bridge); hints kept"
        let settings = context.tools.settings
        let book = ToolListBook()
        guard let fake = LoopbackServer(handler: { request in Self.standInTools(request, book: book) }), let port = await fake.port(),
              let executable = Bundle.main.executablePath, let socket = context.tools.socketPath else {
            record(name, false, "no stand-in server", nil)
            return
        }
        defer { fake.stop() }
        let web = MCPServerConfig(name: "selftest-web", url: "http://127.0.0.1:\(port)/mcp", auth: .token)
        let anonymous = MCPServerConfig(name: "selftest-anonymous", url: "http://127.0.0.1:\(port)/mcp")
        let bridge = MCPServerConfig(name: "selftest-bridge", command: executable, args: ["mcp", "--socket", socket])
        settings.setOverride(.never, for: "get_frontmost_app")
        defer {
            settings.setOverride(nil, for: "get_frontmost_app")
            for server in [web, anonymous, bridge] { settings.removeServer(named: server.name) }
        }
        settings.auth.setToken("abc", for: web.name)

        var details: [String] = []
        let start = ContinuousClock.now
        let listed = (try? await settings.refreshTools(of: web)) ?? []
        let latency = ContinuousClock.now - start
        let seen = book.read
        let kinds = listed.map(\.kind)
        let webOK = listed.map(\.name) == ["list_zones", "delete_zone", "purge_cache"] && kinds == [.reads, .destroys, .unknown]
            && seen.sessionEchoed && seen.versionSent && seen.initialized && seen.pages == 2
        details.append("web: \(listed.map(\.name)) \(kinds.map(\.rawValue)), session echoed \(seen.sessionEchoed), version \(seen.versionSent), initialized \(seen.initialized), pages \(seen.pages), \(Int(latency.milliseconds)) ms")

        var refusal = ""
        do { try await settings.refreshTools(of: anonymous) } catch { refusal = error.localizedDescription }
        let refused = refusal.contains("Sign in") && settings.serverTools[anonymous.name] == nil

        let stdioStart = ContinuousClock.now
        let own = (try? await settings.refreshTools(of: bridge)) ?? []
        let stdioLatency = ContinuousClock.now - stdioStart
        // Outside a run: skil.li's tools, the user's, the rights tools; one blocked.
        let expected = SkilliTools.definitions.count + settings.customTools.count + ToolRightsTools.definitions.count - 1
        let stdioOK = own.count == expected && own.contains { $0.name == "get_selection" && $0.kind == .reads }
            && own.contains { $0.name == "replace_selection" && $0.kind == .destroys }
            && !own.contains { $0.name == "get_frontmost_app" || $0.name == SkilliTools.approve }
        details.append("stdio: \(own.count) tools (expected \(expected), blocked one hidden: \(!own.contains { $0.name == "get_frontmost_app" })), \(Int(stdioLatency.milliseconds)) ms; no sign-in refused: \(refused)")

        let file = context.tools.settings.serverToolsFileForSelfTest
        let kept = file.flatMap { try? Data(contentsOf: $0) }.flatMap { try? JSONDecoder().decode([String: [MCPToolInfo]].self, from: $0) }
        let saved = kept?[web.name]?.count == 3
        details.append("kept on disk: \(saved)")
        record(name, webOK && refused && stdioOK && saved, details.joined(separator: "; "), latency.milliseconds)
    }

    /// Rights in an agent run: a read-only tool of another server runs in
    /// "Ask Before Changes", a blocked one is refused without a card and
    /// hidden from Claude Code; a blocked skil.li tool is refused.
    private func toolRightsDecide() async {
        let name = "Tool rights: read-only runs, blocked refused without a card (and hidden), the rest asks"
        let settings = context.tools.settings
        let popover = context.aiActions.popover
        let server = MCPServerConfig(name: "selftest-rights", url: "https://example.com/mcp")
        let mode = settings.mode
        settings.mode = .auto
        let run = AgentContext(title: "Self-test", groups: [], read: nil, targetPID: nil)
        context.tools.register(run)
        let read = MCPToolInfo.fullName(server: server.name, tool: "list_zones")
        let destroy = MCPToolInfo.fullName(server: server.name, tool: "delete_zone")
        let unknown = MCPToolInfo.fullName(server: server.name, tool: "purge_cache")
        defer {
            settings.mode = mode
            context.tools.unregister(run)
            settings.setOverride(nil, for: "get_clipboard")
            settings.removeServer(named: server.name)
        }
        settings.setServerToolsForSelfTest([MCPToolInfo(name: "list_zones", readOnly: true), MCPToolInfo(name: "delete_zone", readOnly: false, destructive: true),
                                            MCPToolInfo(name: "purge_cache")], for: server.name)
        settings.setOverride(.never, for: destroy)
        settings.setOverride(.never, for: "get_clipboard")

        let readAnswer = await skilliCall(SkilliTools.approve, #"{"tool_name":"\#(read)","input":{"zone":"a"}}"#, run: run.id)
        let blockedAnswer = await skilliCall(SkilliTools.approve, #"{"tool_name":"\#(destroy)","input":{}}"#, run: run.id)
        let noCard = !popover.isVisible
        let ownBlocked = await skilliCall("get_clipboard")
        let readRuns = readAnswer.status == 0 && readAnswer.output.contains(#""behavior":"allow""#)
        let blockedRefused = blockedAnswer.output.contains(#""behavior":"deny""#) && blockedAnswer.output.contains("blocked")
        let hidden = settings.blockedTools(on: [server]) == [destroy]
        let othersAsk = settings.decision(unknown, risk: settings.risk(ofServerTool: unknown)) == .ask
            && settings.decision(read, risk: settings.risk(ofServerTool: read)) == .run
        let ownRefused = ownBlocked.status != 0 && ownBlocked.output.contains("blocked")
        record(name, readRuns && blockedRefused && noCard && hidden && othersAsk && ownRefused,
               "read-only: \(readAnswer.output.prefix(60)); blocked: \(blockedAnswer.output.prefix(80)); no card: \(noCard); hidden from the run: \(hidden); no hints asks: \(othersAsk); skil.li tool blocked: “\(ownBlocked.output.prefix(60))”", nil)
    }

    /// The user's own decision keys, read only (the self-test's prefixed
    /// ones are rarely set): TypeSafe first.
    private static var usersDecisionKeys: [DecisionProvider: String] {
        Dictionary(uniqueKeysWithValues: DecisionProvider.allCases.compactMap { provider in
            Keychain.read(account: provider.keychainAccount).map { (provider, $0) }
        })
    }

    /// Your rules (Settings → Ask), checked on the user's own decision key
    /// in a run: an Allow rule lets get_clipboard run without a card in Ask
    /// Every Time, said under its step; Ask First makes a send tool ask in
    /// Always Allow, the card naming the rule, no Always (without the rule,
    /// no card); a Never rule refuses a delete without a card; a settings
    /// change still asks with an Allow rule and is never put to the rules.
    private func approvalRulesDecide() async {
        let allowName = "Your rules: an Allow rule lets get_clipboard run without a card in Ask Every Time (said under its step); a Never rule refuses a delete without a card"
        let askName = "Your rules: Ask First makes a send tool ask in Always Allow, the card names the rule (no Always), none without it; a settings change still asks with an Allow rule, never put to the rules"
        let keys = Self.usersDecisionKeys
        guard let judge = context.tools.judge, !keys.isEmpty else {
            for name in [allowName, askName] {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no TypeSafe or OpenAI key saved in Settings", latencyMs: nil))
            }
            return
        }
        let settings = context.tools.settings
        let popover = context.aiActions.popover
        let actions = context.aiActions
        let savedKeys = judge.keys
        let mode = settings.mode
        let rules = settings.rules
        judge.keys = { keys }
        let server = MCPServerConfig(name: "selftest-rules", url: "https://example.com/mcp")
        settings.setServerToolsForSelfTest([
            MCPToolInfo(name: "send_email", description: "Sends an email from the user's mailbox to someone.", readOnly: false, destructive: false),
            MCPToolInfo(name: "delete_file", description: "Deletes a file from the user's drive.", readOnly: false, destructive: true)
        ], for: server.name)
        let run = AgentContext(title: "Self-test", groups: Set(ToolGroup.allCases), read: nil, targetPID: nil)
        context.tools.register(run)
        defer {
            judge.keys = savedKeys
            settings.mode = mode
            settings.setRulesForSelfTest(rules)
            context.tools.unregister(run)
            settings.removeServer(named: server.name)
        }
        guard await focusTestWindow() else { return }
        /// A card left waiting would hold the call: Esc it, and say so.
        func cardOrLine(_ line: String, timeout: Double = 8) async -> Bool {
            _ = await waitUntil(timeout: timeout) { popover.isVisible && popover.phase == .approving || actions.lastRuleLine == line }
            guard popover.isVisible, popover.phase == .approving else { return false }
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return true
        }

        // Allow: Ask Every Time would ask; the rule lets it run.
        settings.mode = .ask
        settings.setRulesForSelfTest([ApprovalRule(text: "Reading my clipboard is fine", effect: .allow)])
        let allowed = "Allowed by your rule: Reading my clipboard is fine"
        let start = ContinuousClock.now
        async let read = skilliCall("get_clipboard", run: run.id)
        let readCard = await cardOrLine(allowed)
        let readResult = await read
        let readLatency = ContinuousClock.now - start
        let readLine = actions.lastRuleLine ?? ""
        let readOK = !readCard && readResult.status == 0 && readLine == allowed

        // Never: refused at once, no card, in Always Allow too.
        settings.mode = .always
        settings.setRulesForSelfTest([ApprovalRule(text: "Never delete files", effect: .never)])
        let refusedLine = "Refused by your rule: Never delete files"
        let delete = MCPToolInfo.fullName(server: server.name, tool: "delete_file")
        async let refusal = skilliCall(SkilliTools.approve, #"{"tool_name":"\#(delete)","input":{"path":"/Users/me/Documents/old-report.txt"}}"#, run: run.id)
        let deleteCard = await cardOrLine(refusedLine)
        let refused = await refusal
        let neverOK = !deleteCard && refused.output.contains(#""behavior":"deny""#) && refused.output.contains("Never delete files")
            && actions.lastRuleLine == refusedLine
        record(allowName, readOK && neverOK,
               "get_clipboard: card \(readCard), status \(readResult.status), “\(readLine)”, \(Int(readLatency.milliseconds)) ms; "
                   + "delete_file: card \(deleteCard), “\(refused.output.prefix(110))”; by \(judge.last?.label ?? "?")", readLatency.milliseconds)

        // Ask First, Always Allow: without the rule it runs, no card.
        let send = MCPToolInfo.fullName(server: server.name, tool: "send_email")
        let input = #"{"tool_name":"\#(send)","input":{"to":"paul@example.com","subject":"Retard","body":"J'ai 5 minutes de retard"}}"#
        settings.setRulesForSelfTest([])
        async let free = skilliCall(SkilliTools.approve, input, run: run.id)
        let freeCard = await cardOrLine("—", timeout: 1.5)
        let freeResult = await free
        let withoutRule = !freeCard && freeResult.output.contains(#""behavior":"allow""#)
        settings.setRulesForSelfTest([ApprovalRule(text: "Ask before anything that sends a message", effect: .ask)])
        // The card under the test window's text, so its capture shows it alone.
        popover.hide()
        popover.present(title: "Self-test", at: .selection(window.convertToScreen(textView.convert(textView.bounds, to: nil))))
        async let sent = skilliCall(SkilliTools.approve, input, run: run.id)
        let asked = await waitUntil(timeout: 8) { popover.isVisible && popover.phase == .approving } != nil
        await pause(250)
        let shown = popover.shownText
        let hints = popover.hintTitles
        await saveScreenshot(of: popover.window, as: "ai-card-rule-asks.png")
        if asked { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let sentResult = await sent
        let askOK = asked && shown.contains("Asked because of your rule: Ask before anything that sends a message") && hints == ["Allow", "Deny"]
            && sentResult.output.contains(#""behavior":"allow""#)
        popover.hide()

        // A settings change: asks, whatever an Allow rule says, unjudged.
        var settingsOK = false
        var settingsDetail = "no settings tools"
        if let settingTools = context.tools.settingTools, let defaults = UserDefaults(suiteName: "skilli-selftest-rules-\(getpid())") {
            let scratch = Preferences(defaults: defaults)
            let savedPreferences = settingTools.preferences
            settingTools.preferences = scratch
            defer {
                settingTools.preferences = savedPreferences
                UserDefaults.standard.removePersistentDomain(forName: "skilli-selftest-rules-\(getpid())")
            }
            scratch.backupSchedule = .daily
            settings.setRulesForSelfTest([ApprovalRule(text: "Changing my skil.li settings is fine", effect: .allow)])
            let requests = judge.requests
            async let change = skilliCall(SettingsTable.Tool.setSetting, #"{"pane":"Backup","setting":"How often","value":"weekly"}"#, run: run.id)
            let changeAsked = await waitUntil(timeout: 4) { popover.isVisible && popover.phase == .approving } != nil
            await pause(200)
            let changeShown = popover.shownText
            let changeHints = popover.hintTitles
            if changeAsked { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            let changeResult = await change
            settingsOK = changeAsked && !changeShown.contains("rule") && changeHints == ["Allow", "Deny"] && judge.requests == requests
                && scratch.backupSchedule == .daily && changeResult.output.contains("declined")
            settingsDetail = "asked \(changeAsked), hints \(changeHints), judged \(judge.requests - requests) times, “\(changeResult.output.prefix(60))”"
        }
        record(askName, withoutRule && askOK && settingsOK,
               "without the rule: card \(freeCard), “\(freeResult.output.prefix(40))”; with it: card \(asked), hints \(hints), says the rule "
                   + "\(shown.contains("Asked because of your rule")); settings change: \(settingsDetail)", nil)
    }

    /// The user's AI reads the rights and proposes a change: the card shows
    /// it by right, Return applies it (unknown tools left out), Esc changes
    /// nothing. Not offered to a command's agent.
    private func rightsToolsForYourAI() async {
        let name = "Rights with your AI: list_tool_rights reads them, set_tool_rights waits in the card (Return applies, Esc does not)"
        let settings = context.tools.settings
        let popover = context.aiActions.popover
        let server = MCPServerConfig(name: "selftest-rights-ai", url: "https://example.com/mcp")
        settings.saveServer(server)
        settings.setServerToolsForSelfTest([MCPToolInfo(name: "list_zones", description: "Lists zones.", readOnly: true),
                                            MCPToolInfo(name: "delete_zone", description: "Deletes a zone.", readOnly: false, destructive: true),
                                            MCPToolInfo(name: "purge_cache", description: "Purges the cache.")], for: server.name)
        let run = AgentContext(title: "Self-test", groups: Set(ToolGroup.allCases), read: nil, targetPID: nil)
        context.tools.register(run)
        defer {
            context.tools.unregister(run)
            settings.removeServer(named: server.name)
            settings.setOverride(nil, for: "set_clipboard")
        }
        guard await focusTestWindow() else { return }

        let overview = await skilliCall(ToolRightsTools.list)
        let listed = await skilliCall(ToolRightsTools.list, #"{"server":"\#(server.name)","search":"delete"}"#)
        let own = await skilliCall(ToolRightsTools.list, #"{"server":"skilli","search":"clipboard"}"#)
        let light = await skilliCall(ToolRightsTools.list, #"{"server":"skilli","search":"open a link"}"#)
        let inRun = await skilliCall(ToolRightsTools.list, run: run.id)
        let readOK = overview.status == 0 && overview.output.contains("\(server.name) (https://example.com/mcp): 3 tools")
            && listed.output.contains("- delete_zone [destroys] default (asks)") && !listed.output.contains("list_zones")
            && own.output.contains("- set_clipboard [changes] default") && light.output.contains("- open_url [light change] default")
            && inRun.status != 0 && inRun.output.contains("Unknown tool")

        // Allowed: applied, the unknown tool and the bad entry left out.
        async let applied = skilliCall(ToolRightsTools.set, #"{"server":"\#(server.name)","rights":["list_zones=allow","delete_zone=block","nope=allow","bad"]}"#)
        let asked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        await pause(250)
        let hints = popover.hintTitles
        await saveScreenshot(of: popover.window, as: "ai-card-tool-rights.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let result = await applied
        let read = MCPToolInfo.fullName(server: server.name, tool: "list_zones")
        let destroy = MCPToolInfo.fullName(server: server.name, tool: "delete_zone")
        let set = settings.override(for: read) == .always && settings.override(for: destroy) == .never
            && result.output.contains("1 allow, 1 block") && result.output.contains("nope") && result.output.contains("bad")

        // Declined: nothing changes; skil.li's own tools by their names.
        async let declined = skilliCall(ToolRightsTools.set, #"{"server":"skilli","rights":["set_clipboard=allow"]}"#)
        _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let refusal = await declined
        let unchanged = settings.override(for: "set_clipboard") == nil && refusal.status != 0 && refusal.output.contains("declined")
        let closed = await waitUntil(timeout: 1) { !popover.isVisible } != nil

        record(name, readOK && asked && hints == ["Allow", "Deny"] && set && unchanged && closed,
               "read: \(readOK) (in a run: “\(inRun.output.prefix(40))”); card: \(asked), hints \(hints); applied: \(set) “\(result.output.prefix(120))”; declined: \(unchanged); closed: \(closed)", nil)
    }

    /// Set Rights With …: the terminal opens the CLI with skil.li as its
    /// only MCP server, the rights tools allowed, the skill and the request;
    /// nothing stays on disk.
    private func rightsSessionLaunches() async {
        let name = "Set Rights With Claude Code / Codex: the terminal opens the CLI with skil.li's server, the skill and the request"
        guard let handoff = context.aiActions.handoff, let executable = Bundle.main.executablePath else {
            record(name, false, "no handoff", nil)
            return
        }
        let base = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-rights", isDirectory: true)
        try? FileManager.default.createDirectory(at: base, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: base) }
        var details: [String] = []
        var passed = true
        for terminal in HandoffLauncher.terminals {
            let target: Handoff.Target = terminal == .terminal ? .claude : .codex
            let output = base.appendingPathComponent("\(terminal.rawValue).txt")
            let fake = base.appendingPathComponent("fake-\(terminal.rawValue)")
            try? "#!/bin/zsh\nfor argument in \"$@\"; do printf '%s\\0' \"$argument\"; done > \(Handoff.quotedForTest(output.path))\n"
                .write(to: fake, atomically: true, encoding: .utf8)
            try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: fake.path)
            let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: terminal.bundleID).isEmpty
            let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-handoff", isDirectory: true)
            let before = Set((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? [])
            do {
                try handoff.launchRights(target, in: terminal, server: "cloudflare", binaryOverride: fake)
            } catch {
                passed = false
                details.append("\(terminal.title): \(error.localizedDescription)")
                continue
            }
            let ran = await waitUntil(timeout: 10) { FileManager.default.fileExists(atPath: output.path) } != nil
            await pause(300)
            let arguments = Array(((try? String(contentsOf: output, encoding: .utf8)) ?? "").split(separator: "\0", omittingEmptySubsequences: false).map(String.init).dropLast())
            let request = ToolRights.request(server: "cloudflare")
            let skill = ToolRights.skill(language: HandoffLauncher.languageName)
            let expected: [String]
            switch target {
            case .claude:
                let config = (try? JSONSerialization.data(withJSONObject: ["mcpServers": ["skilli": ["command": executable, "args": ["mcp"]]]],
                                                          options: [.sortedKeys, .withoutEscapingSlashes])).map { String(decoding: $0, as: UTF8.self) } ?? ""
                expected = ["--strict-mcp-config", "--mcp-config", config, "--allowedTools", "mcp__skilli__list_tool_rights,mcp__skilli__set_tool_rights",
                            "--append-system-prompt", skill, request]
            case .codex:
                expected = ["-c", "mcp_servers.skilli.command=\"\(executable)\"", "-c", #"mcp_servers.skilli.args=["mcp"]"#,
                            "-c", #"mcp_servers.skilli.enabled_tools=["list_tool_rights","set_tool_rights"]"#,
                            "-c", #"mcp_servers.skilli.default_tools_approval_mode="approve""#, "-c", "mcp_servers.skilli.tool_timeout_sec=600",
                            Handoff.skillContext(skill, request: request, for: .codex)]
            }
            let whole = arguments == expected
            let after = Set((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? [])
            let cleaned = after.subtracting(before).isEmpty
            passed = passed && ran && whole && cleaned
            details.append("\(terminal.title) → \(target.title): ran \(ran), arguments as expected \(whole)\(whole ? "" : " (got \(arguments.map { String($0.prefix(60)) }))"), files gone \(cleaned)")
            if !wasRunning {
                for app in NSRunningApplication.runningApplications(withBundleIdentifier: terminal.bundleID) { app.terminate() }
                await pause(500)
            }
        }
        record(name, passed && !details.isEmpty, details.joined(separator: "; ") + "; language \(HandoffLauncher.languageName)", nil)
    }

    /// Tools → Help Me Choose with Claude Code and Codex both here: the
    /// pane offers both beside Set Rights… and what the button calls opens
    /// the one chosen (Ask → Continue in), recorded instead of a terminal.
    /// The menu itself: snapshot settings-tools-helper.png.
    private func rightsHelperChoice() async {
        let name = "Tools: both AIs offered beside Set Rights…, which opens the one chosen (the same choice as Continue in)"
        guard let handoff = context.aiActions.handoff else {
            record(name, false, "no handoff", nil)
            return
        }
        // The self-test's Claude Code may be missing: a stand-in counts as
        // installed (nothing runs, the session is only recorded).
        let claudeBinary = handoff.claudeBinary
        if claudeBinary() == nil { handoff.claudeBinary = { URL(fileURLWithPath: "/usr/bin/true") } }
        defer { handoff.claudeBinary = claudeBinary }
        let panes = context.settings.makeContext()
        let offered = panes.rightsHelpers()
        guard offered.count > 1 else {
            checks.append(Check(name: name, passed: true, skipped: true,
                                detail: "only \(offered.map(\.title).joined(separator: ", ")) here: no choice to show", latencyMs: nil))
            return
        }
        let preferences = context.preferences
        let saved = preferences.handoffTarget
        var opened: [String] = []
        handoff.openedRights = { target, server in opened.append("\(target.title) on \(server ?? "all")") }
        defer {
            handoff.openedRights = nil
            preferences.handoffTarget = saved
        }
        preferences.handoffTarget = .codex
        context.settings.show(pane: .tools)
        await pause(600)
        if let directory = context.snapshotDirectory, let png = await context.settings.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("settings-tools-helper.png"))
        }
        let shownCodex = ToolsPane.chosen(preferences.handoffTarget, among: offered) == .codex
        try? panes.openRightsHelper(nil)
        let opensCodex = opened.last == "Codex on all"
        // As choosing Claude Code in the menu (or in the server window's).
        preferences.handoffTarget = .claude
        let shownClaude = ToolsPane.chosen(preferences.handoffTarget, among: offered) == .claude
        try? panes.openRightsHelper("cloudflare")
        let opensClaude = opened.last == "Claude Code on cloudflare"
        await closeSettings()
        record(name, offered == [.claude, .codex] && shownCodex && opensCodex && shownClaude && opensClaude,
               "offered \(offered.map(\.title)); Codex chosen: shown \(shownCodex), opens it \(opensCodex); Claude Code chosen: shown \(shownClaude), "
                   + "opens it \(opensClaude); opened \(opened)", nil)
    }

    /// GitHub against a stand-in, never the user's account: signing in with
    /// a code (device flow), the pull requests by group and the
    /// notifications in one answer each, the notifications not read again
    /// for nothing (304), the strip under the search field, the GitHub mode
    /// (Return opens), ⇥ → merge asked twice, ⌘⌫ marks read, the agents'
    /// tools.
    private func githubInbox() async {
        let name = "GitHub: sign in with a code; pull requests by group, notifications (304 after); the strip; pr; ⇥ merge asks twice; ⌘⌫ read; tools"
        let stand = GitHubStandIn()
        guard let server = LoopbackServer(handler: { stand.answer($0) }), let port = await server.port() else {
            record(name, false, "no stand-in server", nil)
            return
        }
        defer { server.stop() }
        let base = URL(string: "http://127.0.0.1:\(port)")!
        stand.setBase(base.absoluteString)
        let book = GitHubBook(endpoints: GitHubEndpoints(api: base, web: base), keychainPrefix: "selftest-gh-", clientID: { "selftest-client" })
        var opened: [String] = []
        book.openURL = { opened.append($0.absoluteString) }
        defer { book.signOut() }

        // Signing in: the code shown and copied, the page opened, then in.
        book.signIn()
        let code = await waitUntil(timeout: 3) { book.signInCode?.userCode == "WDJB-MJHT" } != nil
        let page = await waitUntil(timeout: 1) { opened.first == base.absoluteString + "/login/device" } != nil
        let signedIn = await waitUntil(timeout: 10) { book.isSignedIn && book.lastRefresh != nil } != nil
        let grouped = book.pullRequests.map { "#\($0.number) \($0.group.rawValue)" }
        let read = grouped == ["#1 ready", "#3 blocked", "#2 testing"] && book.unreadNotifications.map(\.id) == ["22", "21"]
        // Read again: the notifications come back 304, kept.
        book.refresh(force: true)
        let notModified = await waitUntil(timeout: 3) { stand.notModified == 1 } != nil && book.unreadNotifications.count == 2

        // The launcher with this GitHub.
        let launcher = context.launcher
        let popover = context.aiActions.popover
        let tools = context.tools.tools
        let saved = (launcher.github, launcher.showsGitHubStrip, context.aiActions.github, tools.github, launcher.onGitHubSettings)
        // Signed out: no strip, the mode says where to sign in, Return goes there.
        var settingsAsked = false
        launcher.onGitHubSettings = { settingsAsked = true }
        launcher.github = GitHubBook(endpoints: GitHubEndpoints(api: base, web: base), keychainPrefix: "selftest-gh-out-", clientID: { "" })
        launcher.showsGitHubStrip = { true }
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        let noStripSignedOut = launcher.gitHubStripText == nil
        for character in "pr " { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.resultTitles.isEmpty }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let toSettings = await waitUntil(timeout: 1) { settingsAsked } != nil && !launcher.isVisible
        launcher.github = book
        launcher.showsGitHubStrip = { true }
        context.aiActions.github = book
        tools.github = book
        book.onChange = { [weak launcher] in launcher?.updateGitHubStrip() }
        defer {
            launcher.github = saved.0
            launcher.showsGitHubStrip = saved.1
            context.aiActions.github = saved.2
            tools.github = saved.3
            launcher.onGitHubSettings = saved.4
        }
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        let strip = await waitUntil(timeout: 2) { launcher.gitHubStripText == "1 Ready · 1 Blocked · 1 Testing — 2 unread" } != nil
        let stripText = launcher.gitHubStripText ?? "hidden"
        if let directory = context.snapshotDirectory, let png = launcher.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("launcher-github-strip.png"))
            // As the compositor shows it, glass included: the glass S on it.
            if let glass = await WindowCapture.png(of: launcher.window) {
                try? glass.write(to: directory.appendingPathComponent("launcher-glass.png"))
            }
        }
        for character in "pr " { await pressKey(character) }
        let titles = ["Add the GitHub strip", "Fix the build", "Faster history", "Review the new API", "CI failed on main"]
        let listed = await waitUntil(timeout: 2) { launcher.resultTitles == titles } != nil
        let shown = launcher.resultTitles
        if let directory = context.snapshotDirectory, let png = launcher.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("launcher-github-mode.png"))
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let openedPR = await waitUntil(timeout: 1) { opened.last == "https://github.com/nomdelasociete/skilli/pull/1" } != nil

        // ⇥ on the ready one: ⌘K's list; "merge" ↩ is asked again in the
        // card; Return merges.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "pr strip" { await pressKey(character) }
        _ = await waitUntil(timeout: 2) { launcher.resultTitles.first == "Add the GitHub strip" }
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let offered = await waitUntil(timeout: 2) { launcher.shownActions.map(\.title) == ["Open", "Squash and Merge…", "Checks", "Copy Link"] } != nil
        let options = launcher.shownActions.map(\.title)
        for character in "merge" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let askedAgain = await waitUntil(timeout: 2) { popover.shownOptions == ["Squash and Merge", "Cancel"] } != nil
        let notYet = stand.merged.isEmpty
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let merged = await waitUntil(timeout: 3) { stand.merged == ["nomdelasociete/skilli#1 squash abc1"] } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // ⌘⌫ on a notification: read, gone from the list.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "pr main" { await pressKey(character) }
        _ = await waitUntil(timeout: 2) { launcher.resultTitles == ["CI failed on main"] }
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let markedRead = await waitUntil(timeout: 3) { stand.read == ["21"] && launcher.resultTitles.isEmpty } != nil
        await closeLauncher()

        let blocked = (try? await tools.call("list_pull_requests", arguments: ["group": "blocked"], run: nil)) ?? ""
        let notes = (try? await tools.call("list_github_notifications", arguments: [:], run: nil)) ?? ""
        // Settings → GitHub as it stands (the app's own GitHub: signed out).
        context.settings.show(pane: .github)
        await pause(500)
        if let directory = context.snapshotDirectory, let png = await context.settings.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("settings-github.png"))
        }
        await closeSettings()
        await githubPaneSignedIn(book)
        let toolsOK = blocked.hasPrefix("blocked — nomdelasociete/skilli#3 “Fix the build” — lint failed")
            && notes.hasPrefix("22 — Review requested — nimbus-hq/nimbus “Review the new API”") && !notes.contains("CI failed on main")
        record(name, code && page && signedIn && read && notModified && noStripSignedOut && toSettings && strip && listed && openedPR && offered && askedAgain
                   && notYet && merged && markedRead && toolsOK,
               "code \(code), page \(page), signed in \(signedIn); read \(read) (\(grouped)); 304 kept \(notModified); "
                   + "signed out: no strip \(noStripSignedOut), Return → Settings \(toSettings); strip \(strip) (“\(stripText)”); "
                   + "pr \(listed) (\(shown)); Return opens \(openedPR); ⇥ \(offered) (\(options)), asked again \(askedAgain), not before \(notYet), merged \(merged); "
                   + "⌘⌫ read \(markedRead); tools \(toolsOK) (“\(blocked.prefix(80))”, “\(notes.prefix(60))”)",
               nil)
    }

    /// Settings → GitHub as a signed-in user sees it, on the stand-in GitHub,
