    /// Display options show what they do beside them: the meeting in the
    /// menu bar at its moments (drawn by `MeetingWatch` itself), today's
    /// reminders, the GitHub strip. Snapshots; the options put back.
    private func settingsPreviews() async {
        let name = "Settings previews: the meeting in the menu bar at its moments, the card as a meeting starts, today's reminders, the GitHub strip"
        let preferences = context.preferences
        let saved = (preferences.agendaMenuBar, preferences.agendaCountdown, preferences.agendaNextDuringMeeting, preferences.agendaHideAfter,
                     preferences.remindersMenuBar, preferences.githubUnderSearch, preferences.agendaMenuBarCallsOnly)
        defer {
            preferences.agendaMenuBar = saved.0
            preferences.agendaCountdown = saved.1
            preferences.agendaNextDuringMeeting = saved.2
            preferences.agendaHideAfter = saved.3
            preferences.remindersMenuBar = saved.4
            preferences.githubUnderSearch = saved.5
            preferences.agendaMenuBarCallsOnly = saved.6
        }
        // What the preview draws, checked: the same plan and look as the bar.
        let today = Calendar.current.startOfDay(for: .now)
        let sync = AgendaEvent(id: "a", title: "Weekly sync", start: today.addingTimeInterval(14 * 3_600), end: today.addingTimeInterval(14.5 * 3_600),
                               notes: "https://meet.google.com/abc-defg-hij")
        let standup = AgendaEvent(id: "b", title: "Standup", start: sync.end, end: sync.end.addingTimeInterval(15 * 60), notes: "https://meet.google.com/xyz-abcd-efg")
        let options = MeetingBar.Options(lead: 10, callsOnly: true, countdown: true, hideAfter: 10, nextDuringMeeting: true)
        let at = sync.end.addingTimeInterval(-6 * 60)
        let plan = MeetingBar.plan([sync, standup], now: at, options: options, presence: MeetingBar.Presence(joined: [MeetingBar.key(sync)], microphone: .idle))
        let look = plan.shown.flatMap { shown in plan.state.map { MeetingWatch.appearance(of: shown, state: $0, next: plan.next) } }
        let drawn = look?.title == " 6 min left · then Standup \(MeetingBar.clock(standup.start))"
        var shots: [String] = []
        func snap(_ pane: SettingsPane, _ file: String) async {
            context.settings.show(pane: pane)
            await pause(500)
            if let directory = context.snapshotDirectory, let png = await context.settings.snapshotPNG() {
                try? png.write(to: directory.appendingPathComponent(file))
                shots.append(file)
            }
        }
        preferences.agendaMenuBar = .tenBefore
        preferences.agendaMenuBarCallsOnly = true
        preferences.agendaCountdown = true
        preferences.agendaNextDuringMeeting = true
        await snap(.calendar, "settings-agenda-preview.png")
        preferences.agendaCountdown = false
        preferences.agendaHideAfter = 10
        await snap(.calendar, "settings-agenda-preview-no-countdown.png")
        preferences.remindersMenuBar = .countAndNext
        await snap(.reminders, "settings-reminders-preview.png")
        preferences.githubUnderSearch = true
        await snap(.github, "settings-github-preview.png")
        await closeSettings()
        // The alert card, drawn by its own view (Settings' preview): Join
        // for a call, Got It for an event without one.
        let cardView = MeetingCardView(frame: .zero)
        cardView.show(MeetingCardView.sample(startingIn: 299), now: .now)
        let callAction = cardView.actionTitle, callEyebrow = cardView.eyebrowText
        cardView.frame = NSRect(x: 0, y: 0, width: MeetingCardView.width, height: cardView.fittingHeight)
        if let directory = context.snapshotDirectory, let bitmap = cardView.bitmapImageRepForCachingDisplay(in: cardView.bounds) {
            cardView.cacheDisplay(in: cardView.bounds, to: bitmap)
            if let png = bitmap.representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("settings-agenda-start-preview.png"))
                shots.append("settings-agenda-start-preview.png")
            }
        }
        cardView.show(AgendaEvent(id: "c", title: "Lunch", start: sync.start, end: sync.end, location: "Le Comptoir"), now: .now)
        let callKeys = [callAction, callEyebrow], plainKeys = [cardView.actionTitle]
        let keys = callAction == "Join" && callEyebrow.hasPrefix("STARTS IN 4:") && cardView.actionTitle == "Got It"
        record(name, drawn && keys && (context.snapshotDirectory == nil || shots.count == 5),
               "6 min before the next: “\(look?.title ?? "nothing")” \(drawn); the card's keys \(callKeys) / \(plainKeys); snapshots \(shots)", nil)
    }

    /// Settings → General: the glass S turns toward the pointer anywhere over
    /// the pane, its rows too, and lies flat again once the pointer leaves.
    /// Snapshot settings-general-tilt.png; the pointer put back.
    private func generalMarkFollowsPointer() async {
        let name = "Settings → General: the glass S turns toward the pointer, flat once it leaves"
        context.settings.show(pane: .general)
        await pause(400)
        guard let frame = context.settings.frame else {
            record(name, false, "Settings did not open", nil)
            return
        }
        let tilt = context.settings.markTilt
        let height = NSScreen.screens.first?.frame.height ?? 0
        let source = CGEventSource(stateID: .hidSystemState)
        let saved = NSEvent.mouseLocation
        func move(to point: NSPoint) async {
            for step in 0..<2 {
                let at = CGPoint(x: point.x + CGFloat(step) * 2, y: height - point.y)
                CGEvent(mouseEventSource: source, mouseType: .mouseMoved, mouseCursorPosition: at, mouseButton: .left)?.post(tap: .cghidEventTap)
                await pause(40)
            }
        }
        // Low in the pane, below the mark, over the rows: left, then right.
        let sidebar: CGFloat = 196
        await move(to: NSPoint(x: frame.minX + sidebar + 60, y: frame.minY + 120))
        let left = await waitUntil(timeout: 1) { tilt.offset.width < -0.2 && tilt.offset.height > 0.2 } != nil
        let leftOffset = tilt.offset
        // Where the pointer is and what the pane told the mark, for a failure.
        let under = NSWindow.windowNumber(at: NSEvent.mouseLocation, belowWindowWithWindowNumber: 0)
        let seen = "pointer over Settings: \(under == context.settings.windowNumber), key: \(context.settings.isKey), "
            + "pane \(Int(tilt.paneSize.width))×\(Int(tilt.paneSize.height)), mark at \(Int(tilt.center.x)),\(Int(tilt.center.y))"
        await pause(700)
        if let directory = context.snapshotDirectory, let png = await context.settings.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("settings-general-tilt.png"))
        }
        await move(to: NSPoint(x: frame.maxX - 60, y: frame.minY + 120))
        let right = await waitUntil(timeout: 1) { tilt.offset.width > 0.2 && tilt.offset.height > 0.2 } != nil
        let rightOffset = tilt.offset
        // Onto the sidebar: out of the pane, still in skil.li's window.
        await move(to: NSPoint(x: frame.minX + 60, y: frame.midY))
        let flat = await waitUntil(timeout: 1) { tilt.offset == .zero } != nil
        CGEvent(mouseEventSource: source, mouseType: .mouseMoved, mouseCursorPosition: CGPoint(x: saved.x, y: height - saved.y),
                mouseButton: .left)?.post(tap: .cghidEventTap)
        func format(_ offset: CGSize) -> String { String(format: "(%.2f, %.2f)", offset.width, offset.height) }
        record(name, left && right && flat,
               "low left \(format(leftOffset)) \(left), low right \(format(rightOffset)) \(right), over the sidebar flat \(flat)"
                   + (left && right ? "" : "; \(seen)"), nil)
    }

    /// The stand-in server that lists tools: needs the token, gives a
    /// session, two pages of tools, the second as Server-Sent Events.
    nonisolated private static func standInTools(_ request: LoopbackServer.Request, book: ToolListBook) -> LoopbackServer.Response {
        guard request.method == "POST", request.target == "/mcp" else { return LoopbackServer.Response(status: 404) }
        guard request.headers["authorization"] == "Bearer abc" else {
            return LoopbackServer.Response(status: 401, headers: ["WWW-Authenticate": "Bearer"])
        }
        let message = (try? JSONSerialization.jsonObject(with: request.body)) as? [String: Any] ?? [:]
        let id = message["id"] ?? NSNull()
        switch message["method"] as? String {
        case "initialize":
            var response = LoopbackServer.Response.json(["jsonrpc": "2.0", "id": id,
                                                         "result": ["protocolVersion": "2025-06-18", "capabilities": ["tools": [:]], "serverInfo": ["name": "stand-in", "version": "1"]]])
            response.headers["Mcp-Session-Id"] = "S1"
            return response
        case "notifications/initialized":
            book.update { $0.initialized = request.headers["mcp-session-id"] == "S1" }
            return LoopbackServer.Response(status: 202)
        case "tools/list":
            book.update {
                $0.sessionEchoed = request.headers["mcp-session-id"] == "S1"
                $0.versionSent = request.headers["mcp-protocol-version"] == "2025-06-18"
                $0.pages += 1
            }
            let cursor = (message["params"] as? [String: Any])?["cursor"] as? String
            if cursor == nil {
                return .json(["jsonrpc": "2.0", "id": id, "result": [
                    "tools": [["name": "list_zones", "description": "Lists zones.", "annotations": ["readOnlyHint": true]],
                              ["name": "delete_zone", "description": "Deletes a zone.", "annotations": ["readOnlyHint": false, "destructiveHint": true]]],
                    "nextCursor": "p2"]])
            }
            let page: [String: Any] = ["jsonrpc": "2.0", "id": id, "result": ["tools": [["name": "purge_cache", "description": "Purges the cache."]]]]
            let data = (try? JSONSerialization.data(withJSONObject: page)) ?? Data()
            return LoopbackServer.Response(headers: ["Content-Type": "text/event-stream"],
                                           body: Data("event: message\ndata: ".utf8) + data + Data("\n\n".utf8))
        default:
            return .json(["jsonrpc": "2.0", "id": id, "error": ["code": -32601, "message": "Method not found"]])
        }
    }

    /// The stand-in OAuth MCP server's answers.
    nonisolated private static func standInOAuth(_ request: LoopbackServer.Request, book: OAuthBook) -> LoopbackServer.Response {
        let host = request.headers["host"] ?? "127.0.0.1"
        let base = "http://\(host)"
        let path = request.target.split(separator: "?").first.map(String.init) ?? request.target
        let query = URLComponents(string: base + request.target)?.queryItems ?? []
        func item(_ name: String) -> String? { query.first { $0.name == name }?.value }
        switch (request.method, path) {
        case ("POST", "/mcp"):
            if request.headers["authorization"] == "Bearer AT2" { return .json(["jsonrpc": "2.0", "id": 1, "result": [:]]) }
            return LoopbackServer.Response(status: 401, headers: ["WWW-Authenticate": #"Bearer error="invalid_token", scope="test.read", resource_metadata="\#(base)/.well-known/oauth-protected-resource/mcp""#])
        case ("GET", "/.well-known/oauth-protected-resource/mcp"):
            return .json(["resource": base + "/mcp", "authorization_servers": [base], "scopes_supported": ["test.read"]])
        case ("GET", "/.well-known/oauth-authorization-server"):
            return .json(["issuer": base, "authorization_endpoint": base + "/authorize", "token_endpoint": base + "/token",
                          "registration_endpoint": base + "/register", "code_challenge_methods_supported": ["S256"]])
        case ("POST", "/register"):
            let body = (try? JSONSerialization.jsonObject(with: request.body)) as? [String: Any]
            book.update { $0.registered = (body?["redirect_uris"] as? [String])?.first?.hasPrefix("http://127.0.0.1:") == true }
            return .json(["client_id": "selftest-client"], status: 201)
        case ("GET", "/authorize"):
            book.update {
                $0.challenge = item("code_challenge")
                $0.resource = item("resource") == base + "/mcp" && item("client_id") == "selftest-client" && item("code_challenge_method") == "S256"
                $0.scope = item("scope")
            }
            guard let redirect = item("redirect_uri"), let state = item("state") else { return LoopbackServer.Response(status: 400) }
            return LoopbackServer.Response(status: 302, headers: ["Location": "\(redirect)?code=CODE1&state=\(state)"])
        case ("POST", "/token"):
            let form = URLComponents(string: "x:/?" + String(decoding: request.body, as: UTF8.self))?.queryItems ?? []
            func field(_ name: String) -> String? { form.first { $0.name == name }?.value }
            if field("grant_type") == "authorization_code", field("code") == "CODE1", let verifier = field("code_verifier") {
                let ok = MCPOAuth.challenge(for: verifier) == book.read.challenge
                book.update { $0.pkce = ok }
                return ok ? .json(["access_token": "AT1", "refresh_token": "RT1", "expires_in": 30, "token_type": "Bearer"])
                    : .json(["error": "invalid_grant"], status: 400)
            }
            if field("grant_type") == "refresh_token", field("refresh_token") == "RT1" {
                book.update { $0.refreshes += 1 }
                return .json(["access_token": "AT2", "refresh_token": "RT2", "expires_in": 3600, "token_type": "Bearer"])
            }
            return .json(["error": "invalid_grant"], status: 400)
        default:
            return LoopbackServer.Response(status: 404)
        }
    }

    /// The card in the launcher's place, with what is around it.
    private func captureLauncherPlaceCard(frame: NSRect, as name: String) async {
        guard let directory = context.snapshotDirectory else { return }
        let original = window.frame
        window.setFrame(original.union(frame.insetBy(dx: -48, dy: -48)), display: true)
        await pause(200)
        if let image = await GlassCheck.screenshot(of: frame.insetBy(dx: -40, dy: -40)),
           let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
            try? png.write(to: directory.appendingPathComponent(name))
        }
        window.setFrame(original, display: true)
    }

    /// Without {selection} and with nothing selected, the answer goes in at
    /// the cursor.
    private func siCommandWithoutSelectionInserts() async {
        let name = "Commands: without a selection the answer is inserted at the cursor"
        let model = context.aiCommands
        context.ai.testEngine = FakeTextEngine(chunks: [" — signed, Camille"], delay: .milliseconds(20))
        var command = model.newCommand()
        defer {
            context.ai.testEngine = nil
            model.delete(command.id)
        }
        command.prompt = "Write a short signature for {name}."
        model.save(command)

        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "Thanks"
        textView.setSelectedRange(NSRange(location: 6, length: 0))
        await pause(60)
        context.aiActions.run(command.id, triggeredAt: .now)
        let done = await waitUntil(timeout: 3) { self.context.aiActions.popover.isVisible && self.context.aiActions.popover.phase == .done } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let inserted = await waitUntil(timeout: 2) { self.textView.string == "Thanks— signed, Camille" || self.textView.string == "Thanks — signed, Camille" } != nil
        let message = context.aiActions.lastMessage ?? ""
        record(name, done && inserted && !message.contains("\"\"\""), "text now “\(textView.string)”, message “\(message)”", nil)
    }

    /// The editor: `{` then letters opens the variable list, Return inserts
    /// the variable; Cancel keeps the file as it was.
    private func siCommandEditorCompletesVariables() async {
        let name = "Commands editor: typing {da offers {date}, Return inserts it"
        let model = context.aiCommands
        model.refresh()
        guard let fix = model.library.command("fix") else { return }
        context.settings.show(pane: .commands)
        await pause(500)
        if let directory = context.snapshotDirectory, let window = NSApp.windows.first(where: { $0.isVisible && $0.title == SettingsPane.commands.title }),
           let image = await GlassCheck.screenshot(around: window, padding: 0),
           let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
            try? png.write(to: directory.appendingPathComponent("commands-pane.png"))
        }
        model.editing = fix
        guard await waitUntil(timeout: 2, { model.activeEditor != nil }) != nil, let editor = model.activeEditor else {
            record(name, false, "the editor did not open", nil)
            await closeSettings()
            return
        }
        await pause(400)
        editor.focus()
        editor.insert(" {")
        await pause(150)
        await pressKey("d")
        await pressKey("a")
        _ = await waitUntil(timeout: 2) { editor.text.hasSuffix("{da") && editor.completionItems.count == 3 }
        await pause(200)
        if let directory = context.snapshotDirectory, let window = NSApp.keyWindow,
           let image = await GlassCheck.screenshot(around: window, padding: 0),
           let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
            try? png.write(to: directory.appendingPathComponent("command-editor.png"))
        }
        let offered = editor.completionItems.map(\.token)
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        await pause(200)
        let completed = editor.text.hasSuffix("{date}") && offered == ["{date}", "{datetime}", "{day}"]
        let typed = editor.text
        // Cancel: nothing saved.
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { model.editing == nil }
        model.refresh()
        let unchanged = model.library.command("fix") == fix
        await closeSettings()
        let instances = editor.instances
        record(name, completed && unchanged, "offered \(offered), prompt ends “\(typed.suffix(24))”, cancel left the file unchanged: \(unchanged), editors \(instances.total) (\(instances.inWindow) on screen)", nil)
    }

    /// 2026-10-16: in the command editor ⌘S saves, the name stays on
    /// top while the form scrolls, and tools are the ones added, each with
    /// what it does, then Add Tool.
    private func commandEditorSavesAndListsTools() async {
        let name = "Commands editor: ⌘S saves; the name stays on top as the form scrolls; tools listed with what they do, then Add Tool"
        let model = context.aiCommands
        model.refresh()
        var command = model.newCommand()
        command.tools = [ToolGroup.calendar.rawValue, ToolGroup.selection.rawValue]
        model.save(command)
        defer { model.delete(command.id) }
        context.settings.show(pane: .commands)
        await pause(400)
        model.activeEditor = nil
        model.editing = command
        guard await waitUntil(timeout: 2, { model.activeEditor != nil }) != nil, let editor = model.activeEditor else {
            record(name, false, "the editor did not open", nil)
            await closeSettings()
            return
        }
        await pause(400)
        guard let sheet = NSApp.keyWindow else {
            record(name, false, "no editor window", nil)
            await closeSettings()
            return
        }
        // The name field: the first text field, outside the scrolling form.
        func fields(_ view: NSView) -> [NSTextField] {
            (view as? NSTextField).map { [$0] } ?? [] + view.subviews.flatMap(fields)
        }
        let nameField = fields(sheet.contentView ?? NSView()).first { $0.isEditable && $0.stringValue == command.title }
        let nameTop = nameField.map { $0.convert($0.bounds, to: nil).maxY }
        func capture(_ file: String) async {
            if let directory = context.snapshotDirectory, let png = await WindowCapture.png(of: sheet) {
                try? png.write(to: directory.appendingPathComponent(file))
            }
        }
        await capture("command-editor-tools.png")
        // Scrolled to its end: the name has not moved.
        func scrollViews(_ view: NSView) -> [NSScrollView] {
            (view as? NSScrollView).map { [$0] } ?? [] + view.subviews.flatMap(scrollViews)
        }
        if let form = scrollViews(sheet.contentView ?? NSView()).max(by: { $0.frame.height < $1.frame.height }), let document = form.documentView {
            let bottom = document.isFlipped ? document.frame.height - form.contentView.bounds.height : 0
            form.contentView.scroll(to: NSPoint(x: 0, y: max(0, bottom)))
            form.reflectScrolledClipView(form.contentView)
        }
        await pause(300)
        let nameTopScrolled = nameField.map { $0.convert($0.bounds, to: nil).maxY }
        await capture("command-editor-tools-bottom.png")
        let pinned = nameTop != nil && nameTop == nameTopScrolled && nameField?.window == sheet
        // ⌘S: saved, the editor closes.
        let marker = "selftest-saved-\(UUID().uuidString.prefix(6))"
        editor.focus()
        editor.insert(" \(marker)")
        await pause(200)
        await pressKey("s", flags: .maskCommand)
        let closed = await waitUntil(timeout: 2) { model.editing == nil } != nil
        model.refresh()
        let saved = model.library.command(command.id)?.prompt.contains(marker) == true
        let tools = model.library.command(command.id)?.tools ?? []
        await closeSettings()
        record(name, pinned && closed && saved && tools == command.tools,
               "name on top: \(pinned) (\(nameTop.map { "\(Int($0))" } ?? "?") → \(nameTopScrolled.map { "\(Int($0))" } ?? "?")), ⌘S closed: \(closed), saved: \(saved), tools kept: \(tools)", nil)
    }

    /// 2026-10-17: the command editor writes nothing until Save, its
    /// buttons pressed as clicks. New Command opens a draft: Cancel leaves
    /// no file and no shortcut. On a command, a shortcut recorded and the
    /// prompt changed stay in the editor; Duplicate opens a draft copy of
    /// it, esc there leaves the original as saved. On a built-in, Reset to
    /// Default changes the draft only; Save writes it.
    /// `command-editor-new.png`, `-duplicate.png`, `-reset.png`.
    private func commandEditorChangesNothingUntilSave() async {
        let name = "Commands editor: nothing written until Save (New Command, a shortcut and the prompt, Duplicate, Reset to Default); Cancel and esc leave everything as it was"
        let model = context.aiCommands
        let store = context.shortcuts
        model.refresh()
        guard let folder = model.library.folder else {
            record(name, false, "no prompt folder", nil)
            return
        }
        func files() -> Set<String> { Set((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []) }
        func file(_ id: String) -> String? { try? String(contentsOf: folder.appendingPathComponent("\(id).md"), encoding: .utf8) }
        func opened() async -> Bool { await waitUntil(timeout: 3) { model.activeEditor != nil && model.editing != nil } != nil }
        func closed() async -> Bool { await waitUntil(timeout: 2) { model.editing == nil } != nil }
        context.settings.show(pane: .commands)
        await pause(400)

        // New Command, then Cancel.
        let filesBefore = files()
        let shortcutsBefore = store.config
        model.activeEditor = nil
        let pressedNew = Self.pressButton("New Command")
        let newOpened = await opened()
        let draftID = model.editing?.id ?? ""
        await pause(300)
        let draftUnsaved = !draftID.isEmpty && !model.isSaved(draftID) && files() == filesBefore && store.config == shortcutsBefore
        let draftRow = model.editorShortcuts(for: draftID).count == 1
        await saveSheet(as: "command-editor-new.png")
        let cancelled = Self.pressButton("Cancel")
        let newClosed = await closed()
        // The sheet's views go after its animation.
        _ = await waitUntil(timeout: 2) { store.staged == nil }
        model.refresh()
        let newLeft = [files() == filesBefore ? nil : "files \(files().subtracting(filesBefore))",
                       store.config == shortcutsBefore ? nil : "shortcuts changed",
                       store.staged == nil ? nil : "still staged",
                       model.library.command(draftID) == nil ? nil : "saved"].compactMap { $0 }
        let newLeftNothing = newLeft.isEmpty

        // A saved command: ✦J and the prompt changed, Duplicate, esc.
        var command = model.newCommand()
        command.prompt = "Original {selection}"
        model.save(command)
        defer { model.delete(command.id) }
        let savedText = file(command.id)
        let savedShortcuts = store.config
        model.activeEditor = nil
        model.editing = command
        _ = await opened()
        await pause(300)
        var recorded = false
        if let entry = model.editorShortcuts(for: command.id).first {
            model.activeEditor?.insert(" changed")
            store.beginRecording(entry.id)
            await pause(150)
            _ = await hyperChord(["j"], trigger: Self.ownTriggerKeyCode)
            _ = await waitUntil(timeout: 3) { store.recordingID == nil }
            recorded = model.editorShortcuts(for: command.id).first?.keys == "hyper+j"
        }
        let notYet = store.config == savedShortcuts && file(command.id) == savedText
        model.activeEditor = nil
        let pressedDuplicate = Self.pressButton("Duplicate")
        let copyOpened = await waitUntil(timeout: 3) { model.editing.map { $0.id != command.id } == true && model.activeEditor != nil } != nil
        let copy = model.editing
        await pause(300)
        let copyText = model.activeEditor?.text ?? ""
        let copyIsDraft = copy.map { !model.isSaved($0.id) && $0.title == command.title + " Copy" } == true && copyText.contains("changed")
        await saveSheet(as: "command-editor-duplicate.png")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let copyClosed = await closed()
        _ = await waitUntil(timeout: 2) { store.staged == nil }
        model.refresh()
        let originalKept = file(command.id) == savedText && store.config == savedShortcuts && store.staged == nil
            && copy.map { model.library.command($0.id) == nil } == true

        // A built-in: Reset to Default in the draft, Cancel; again, Save.
        guard let fix = model.library.command("fix"), let shipped = model.builtIn("fix") else {
            record(name, false, "no Fix command", nil)
            await closeSettings()
            return
        }
        defer { model.save(fix) }
        var changedFix = fix
        changedFix.prompt = "Changed by the self-test {selection}"
        model.save(changedFix)
        let changedText = file("fix")
        model.activeEditor = nil
        model.editing = changedFix
        _ = await opened()
        await pause(300)
        let pressedReset = Self.pressButton("Reset to Default")
        _ = await waitUntil(timeout: 1) { model.activeEditor?.text == shipped.prompt }
        let draftReset = model.activeEditor?.text == shipped.prompt && file("fix") == changedText
        await saveSheet(as: "command-editor-reset.png")
        _ = Self.pressButton("Cancel")
        _ = await closed()
        _ = await waitUntil(timeout: 2) { store.staged == nil }
        model.refresh()
        let resetCancelled = file("fix") == changedText
        model.activeEditor = nil
        model.editing = model.library.command("fix")
        _ = await opened()
        await pause(300)
        _ = Self.pressButton("Reset to Default")
        await pause(200)
        let pressedSave = Self.pressButton("Save")
        _ = await closed()
        model.refresh()
        let resetSaved = !model.isModified("fix")
        await closeSettings()

        record(
            name,
            pressedNew && newOpened && draftUnsaved && draftRow && cancelled && newClosed && newLeftNothing
                && recorded && notYet && pressedDuplicate && copyOpened && copyIsDraft && copyClosed && originalKept
                && pressedReset && draftReset && resetCancelled && pressedSave && resetSaved,
            "New Command: pressed \(pressedNew), opened \(newOpened), unsaved \(draftUnsaved) with a shortcut row \(draftRow), Cancel \(cancelled && newClosed), nothing left \(newLeftNothing ? "true" : "false: \(newLeft)"); a command: ✦J in the editor \(recorded), nothing written yet \(notYet), Duplicate \(pressedDuplicate) opened \(copyOpened) a draft copy \(copyIsDraft) (“\(copy?.title ?? "none")”, saved \(copy.map { model.isSaved($0.id) } ?? false), prompt “\(copyText.suffix(30))”), esc \(copyClosed), original as saved \(originalKept); Fix: Reset to Default \(pressedReset) in the draft only \(draftReset), Cancel kept the file \(resetCancelled), Save \(pressedSave) wrote it \(resetSaved)",
            nil
        )
    }

    // MARK: - Transform+ (questions, output, import)

    /// A command saved for one check, deleted after it.
    private func scratchCommand(prompt: String, output: OutputMode? = nil, questions: [PromptQuestion] = []) -> AICommand {
        var command = context.aiCommands.newCommand()
        command.prompt = prompt
        command.output = output
        command.questions = questions
        context.aiCommands.save(command)
        return command
    }

    /// Puts `text` in the test window (selected, or the cursor at its end)
    /// and runs `command`.
    private func run(_ command: AICommand, on text: String, selected: Bool = true) async -> Bool {
        guard await focusTestWindow() else { return false }
        window.makeFirstResponder(textView)
        textView.string = text
        textView.undoManager?.removeAllActions()
        if selected {
            textView.selectAll(nil)
        } else {
            textView.setSelectedRange(NSRange(location: (text as NSString).length, length: 0))
        }
        await pause(60)
        context.aiActions.run(command.id, triggeredAt: .now)
        return await waitUntil(timeout: 2, { self.context.aiActions.popover.isVisible }) != nil
    }

    /// Options as keycaps: the default is selected, → moves, a digit picks
    /// and runs (⇧ and a digit too: AZERTY's digits); a click on an option
    /// picks it, the app keeping its focus; Return alone takes the default.
    private func siCommandAsksWithKeycaps() async {
        let name = "Commands: a question shows options as keycaps; → moves, 3 picks, ⇧2 picks, a click picks (focus kept), Return takes the default"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: ["Bonjour"], delay: .milliseconds(20))
        let tone = PromptQuestion(id: "tone", question: "Which tone?", options: ["Friendly", "Formal", "Short"], defaultValue: "Formal")
        let command = scratchCommand(prompt: "Reply in a {ask.tone} tone.\n\n{selection}", questions: [tone])
        defer {
            context.ai.testEngine = nil
            context.aiCommands.delete(command.id)
        }
        guard await run(command, on: "Salut"), await waitUntil(timeout: 2, { popover.phase == .asking }) != nil else {
            record(name, false, "no question in the card (phase \(popover.phase))", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        await pause(250)
        await saveScreenshot(of: popover.window, as: "ai-card-question.png")
        let preselected = popover.shownQuestion?.selected
        await pressKey(nil, code: CGKeyCode(kVK_RightArrow))
        let moved = popover.shownQuestion?.selected
        await pressKey(nil, code: CGKeyCode(kVK_ANSI_3))
        let picked = await waitUntil(timeout: 2) { popover.phase == .done } != nil
        let pickedMessage = context.aiActions.lastMessage ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        guard await run(command, on: "Salut"), await waitUntil(timeout: 2, { popover.phase == .asking }) != nil else {
            record(name, false, "no question the second time", nil)
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let defaulted = await waitUntil(timeout: 2) { popover.phase == .done } != nil
        let defaultMessage = context.aiActions.lastMessage ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // ⇧2: the second, as AZERTY types its digits.
        var shiftMessage = ""
        if await run(command, on: "Salut"), await waitUntil(timeout: 2, { popover.phase == .asking }) != nil {
            await pressKey(nil, code: CGKeyCode(kVK_ANSI_2), flags: .maskShift)
            if await waitUntil(timeout: 2, { popover.phase == .done }) != nil { shiftMessage = context.aiActions.lastMessage ?? "" }
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
        }
        // A click on the first: picked, the card never takes the focus.
        var clickMessage = ""
        var focusKept = false
        if await run(command, on: "Salut"), await waitUntil(timeout: 2, { popover.phase == .asking }) != nil {
            await pause(200)
            if let chip = popover.optionFrameOnScreen(0) {
                let height = NSScreen.screens.first?.frame.height ?? 0
                let point = CGPoint(x: chip.midX, y: height - chip.midY)
                let source = CGEventSource(stateID: .hidSystemState)
                for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
                    CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
                    await pause(60)
                }
            }
            if await waitUntil(timeout: 2, { popover.phase == .done }) != nil { clickMessage = context.aiActions.lastMessage ?? "" }
            focusKept = window.isKeyWindow && window.firstResponder === textView
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
        }
        let passed = preselected == 1 && moved == 2 && picked && pickedMessage.hasPrefix("Reply in a Short tone.")
            && defaulted && defaultMessage.hasPrefix("Reply in a Formal tone.") && textView.string == "Salut"
            && shiftMessage.hasPrefix("Reply in a Formal tone.") && clickMessage.hasPrefix("Reply in a Friendly tone.") && focusKept
        record(name, passed, "default selected: \(preselected.map(String.init) ?? "none"), after →: \(moved.map(String.init) ?? "none"), 3 sent “\(pickedMessage.prefix(22))”, Return sent “\(defaultMessage.prefix(23))”, ⇧2 sent “\(shiftMessage.prefix(23))”, a click sent “\(clickMessage.prefix(25))”, focus kept: \(focusKept)", nil)
    }

    /// No options: typing fills the answer (⌫ erases), modifiers apply,
    /// the card output keeps the text untouched and Return copies.
    private func siCommandAsksForTypedAnswer() async {
        let name = "Commands: a typed answer (⌫ works) fills {ask.city | upper}; card output, Return copies"
        let popover = context.aiActions.popover
        let clipboard = PasteboardSnapshot(NSPasteboard.general)
        context.ai.testEngine = FakeTextEngine(chunks: ["Sunny ", "and mild."], delay: .milliseconds(20))
        let city = PromptQuestion(id: "city", question: "Which city?", defaultValue: "Paris")
        let command = scratchCommand(prompt: "Weather in {ask.city | upper} today.", output: .card, questions: [city])
        defer {
            context.ai.testEngine = nil
            context.aiCommands.delete(command.id)
            clipboard.restore(to: NSPasteboard.general)
        }
        guard await run(command, on: "Notes", selected: false), await waitUntil(timeout: 2, { popover.phase == .asking }) != nil else {
            record(name, false, "no question in the card", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        for character in "lyonx" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        await pause(150)
        await saveScreenshot(of: popover.window, as: "ai-card-typed-answer.png")
        let typed = popover.shownQuestion?.typed ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let done = await waitUntil(timeout: 2) { popover.phase == .done } != nil
        let message = context.aiActions.lastMessage ?? ""
        await pause(200)
        await saveScreenshot(of: popover.window, as: "ai-card-output-card.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let copied = await waitUntil(timeout: 1) { NSPasteboard.general.string(forType: .string) == "Sunny and mild." } != nil
        let closed = !popover.isVisible
        record(name, typed == "lyon" && done && message == "Weather in LYON today." && copied && closed && textView.string == "Notes",
               "typed “\(typed)”, message “\(message)”, copied: \(copied), closed: \(closed), text “\(textView.string)”", nil)
    }

    /// Insert After keeps the selection and adds the answer below it; Copy
    /// puts the answer on the clipboard as soon as it is written.
    private func siCommandOutputModes() async {
        let name = "Commands: Insert After keeps the selection; Copy fills the clipboard at once"
        let popover = context.aiActions.popover
        let clipboard = PasteboardSnapshot(NSPasteboard.general)
        context.ai.testEngine = FakeTextEngine(chunks: ["Added line"], delay: .milliseconds(20))
        let insert = scratchCommand(prompt: "Add a line after this.\n\n{selection}", output: .insert)
        let copy = scratchCommand(prompt: "Summarize.\n\n{selection}", output: .copy)
        defer {
            context.ai.testEngine = nil
            context.aiCommands.delete(insert.id)
            context.aiCommands.delete(copy.id)
            clipboard.restore(to: NSPasteboard.general)
        }
        var inserted = false
        if await run(insert, on: "Note"), await waitUntil(timeout: 2, { popover.phase == .done }) != nil {
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            inserted = await waitUntil(timeout: 2) { self.textView.string == "Note\n\nAdded line" } != nil
        }
        let afterInsert = textView.string
        var copiedAtOnce = false
        var untouched = false
        if await run(copy, on: "Long text"), await waitUntil(timeout: 2, { popover.phase == .done }) != nil {
            copiedAtOnce = NSPasteboard.general.string(forType: .string) == "Added line"
            await pause(200)
            await saveScreenshot(of: popover.window, as: "ai-card-output-copy.png")
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            untouched = await waitUntil(timeout: 1) { !popover.isVisible } != nil && textView.string == "Long text"
        }
        record(name, inserted && copiedAtOnce && untouched,
               "insert: “\(afterInsert.replacingOccurrences(of: "\n", with: "⏎"))”, copied when done: \(copiedAtOnce), copy left the text: \(untouched)", nil)
    }

    /// Text that cannot be edited (a web page): Return puts the answer on
    /// the clipboard and the card says so.
    private func aiActionReadOnlyFallsBackToClipboard() async {
        let name = "AI action on read-only text: the answer goes to the clipboard, the card says so"
        let popover = context.aiActions.popover
        let clipboard = PasteboardSnapshot(NSPasteboard.general)
        context.ai.testEngine = FakeTextEngine(chunks: [Self.aiFixed], delay: .milliseconds(20))
        context.selection.pasteTargetOverride = .readOnly
        defer {
            context.ai.testEngine = nil
            context.selection.pasteTargetOverride = nil
            clipboard.restore(to: NSPasteboard.general)
        }
        guard await triggerFixAction(on: Self.aiOriginal), await waitUntil(timeout: 3, { popover.phase == .done }) != nil else {
            record(name, false, "no answer", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let said = await waitUntil(timeout: 1) { popover.isVisible && popover.shownText.contains("clipboard") } != nil
        await pause(200)
        await saveScreenshot(of: popover.window, as: "ai-card-read-only.png")
        let copied = NSPasteboard.general.string(forType: .string) == Self.aiFixed
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let closed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        record(name, said && copied && closed && textView.string == Self.aiOriginal,
               "card “\(popover.shownText)”, clipboard holds the answer: \(copied), closed: \(closed)", nil)
    }

    /// A `skilli://commands/import` link shows the whole command first;
    /// Add keeps its output, questions and model, and gives it a shortcut row.
    private func siCommandImportLink() async {
        let name = "Commands: an import link shows the command, Add keeps output, questions and model"
        let model = context.aiCommands
        let shared = PromptFile(
            title: "Reply to This Email",
            instruction: "Answer in a {ask.tone} tone, as me.\n\n{selection}",
            includeProfile: true,
            model: AIModel.allCases.last?.rawValue,
            output: .insert,
            questions: [PromptQuestion(id: "tone", question: "Which tone?", options: ["Friendly", "Formal & polite", "Short"], defaultValue: "Friendly")]
        )
        let link = CommandLink.importLink(for: [shared.text])
        guard let request = CommandLink.parse(link) else {
            record(name, false, "the link did not parse: \(link.absoluteString.prefix(80))", nil)
            return
        }
        context.settings.show(pane: .commands)
        await pause(400)
        await model.receive(request)
        let sheet = await waitUntil(timeout: 2) { NSApp.windows.contains { $0.isVisible && $0.isSheet } } != nil
        await pause(500)
        if let directory = context.snapshotDirectory, let window = NSApp.windows.first(where: { $0.isVisible && $0.title == SettingsPane.commands.title }),
           let image = await GlassCheck.screenshot(around: window, padding: 0),
           let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
            try? png.write(to: directory.appendingPathComponent("commands-import-sheet.png"))
        }
        let before = Set(model.library.all.map(\.id))
        let pressed = Self.pressLastButton(labelled: "Add Command")
        let added = await waitUntil(timeout: 2) { model.library.all.count == before.count + 1 } != nil
        let command = model.library.all.first { !before.contains($0.id) }
        defer { if let command { model.delete(command.id) } }
        let kept = command.map { AICommand(id: $0.id, file: shared) == $0 } ?? false
        let hasShortcutRow = command.map { !model.shortcutEntries(for: $0.id).isEmpty } ?? false

        // The editor shows the questions.
        if let command {
            model.editing = command
            _ = await waitUntil(timeout: 2) { model.activeEditor != nil }
            await pause(600)
            await saveScreenshot(ofKeyWindowAs: "command-editor-questions.png")
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { model.editing == nil }
        }
        await closeSettings()
        record(name, sheet && pressed && added && kept && hasShortcutRow,
               "sheet: \(sheet), Add pressed: \(pressed), added “\(command?.title ?? "nothing")” (\(command?.id ?? "")), all kept: \(kept), shortcut row: \(hasShortcutRow)", nil)
    }

    // MARK: - Tools (MCP server, approvals, Act)

    /// `Skilli call …` against the self-test's tool server, off the main
    /// thread (the server answers on it).
    private func skilliCall(_ tool: String, _ arguments: String = "{}", run: String? = nil) async -> (status: Int32, output: String) {
        guard let executable = Bundle.main.executablePath, let socket = context.tools.socketPath else { return (-1, "no server") }
        return await withCheckedContinuation { continuation in
            DispatchQueue.global().async {
                let process = Process()
                process.executableURL = URL(fileURLWithPath: executable)
                process.arguments = ["call", tool, arguments, "--socket", socket] + (run.map { ["--run", $0] } ?? [])
                let output = Pipe()
                process.standardOutput = output
                process.standardError = output
                do {
                    try process.run()
                } catch {
                    continuation.resume(returning: (-1, error.localizedDescription))
                    return
                }
                let data = output.fileHandleForReading.readDataToEndOfFile()
                process.waitUntilExit()
                continuation.resume(returning: (process.terminationStatus, String(decoding: data, as: UTF8.self).trimmingCharacters(in: .whitespacesAndNewlines)))
            }
        }
    }

    /// The bridge reaches the server; a read-only tool answers at once.
    private func toolsServerSpeaksMCP() async {
        let name = "Tools: `Skilli call` reaches skil.li's MCP server; reading the app in front needs no OK"
        guard await focusTestWindow() else {
            record(name, false, "no test window", nil)
            return
        }
        let start = ContinuousClock.now
        let (status, output) = await skilliCall("get_frontmost_app")
        let latency = ContinuousClock.now - start
        let socketPrivate = (try? FileManager.default.attributesOfItem(atPath: context.tools.socketPath ?? ""))?[.posixPermissions] as? Int == 0o700
            || (try? FileManager.default.attributesOfItem(atPath: context.tools.socketPath ?? ""))?[.posixPermissions] as? Int == 0o600
        record(name, status == 0 && output.contains("com.nomdelasociete.Skilli") && socketPrivate && !context.aiActions.popover.isVisible,
               "exit \(status), “\(output)”, socket private: \(socketPrivate), \(Int(latency.milliseconds)) ms", latency.milliseconds)
    }

    /// A tool that changes text waits in the card: Return allows, ⌘Return
    /// allows for good, Esc denies.
    private func toolsApprovalAllowAlwaysDeny() async {
        let name = "Tools: changes wait in the card — Return allows, ⌘Return always, Esc denies"
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let clipboard = PasteboardSnapshot(NSPasteboard.general)
        let mode = settings.mode
        settings.mode = .auto
        defer {
            settings.mode = mode
            settings.setOverride(nil, for: "set_clipboard")
            clipboard.restore(to: NSPasteboard.general)
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "old words"
        textView.selectAll(nil)
        await pause(60)

        // Allow.
        async let replaced = skilliCall("replace_selection", #"{"text":"Approved text"}"#)
        let asked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        await pause(250)
        await saveScreenshot(of: popover.window, as: "ai-card-approval.png")
        let header = popover.shownTitle
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let allowed = await replaced
        let pasted = await waitUntil(timeout: 2) { self.textView.string == "Approved text" } != nil

        // Always: asked once, then never.
        async let first = skilliCall("set_clipboard", #"{"text":"first"}"#)
        let askedAgain = await waitUntil(timeout: 3) { popover.phase == .approving && popover.isVisible } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
        let firstResult = await first
        let remembered = settings.override(for: "set_clipboard") == .always
        let second = await skilliCall("set_clipboard", #"{"text":"second"}"#)
        let noCard = !popover.isVisible
        let clipboardNow = NSPasteboard.general.string(forType: .string)

        // Deny.
        textView.selectAll(nil)
        async let denied = skilliCall("replace_selection", #"{"text":"Never"}"#)
        _ = await waitUntil(timeout: 3) { popover.phase == .approving && popover.isVisible }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let deniedResult = await denied
        await pause(200)
        let untouched = textView.string == "Approved text"

        let passed = asked && header == "Terminal" && allowed.status == 0 && pasted
            && askedAgain && firstResult.status == 0 && remembered && second.status == 0 && noCard && clipboardNow == "second"
            && deniedResult.status != 0 && deniedResult.output.contains("declined") && untouched
        record(name, passed, "asked: \(asked) (card says “\(header)”), allow → “\(textView.string)”, always remembered: \(remembered), 2nd call without card: \(noCard && second.status == 0), deny → “\(deniedResult.output.prefix(40))”", nil)
    }

