    /// Menus come from Accessibility (Finder: always running, read only).
    private func toolsReadMenus() {
        let name = "Tools: menus are read through Accessibility (Finder's File menu)"
        guard let finder = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.finder").first else {
            record(name, false, "Finder is not running", nil)
            return
        }
        let start = ContinuousClock.now
        let items = MenuReader.items(pid: finder.processIdentifier)
        let latency = ContinuousClock.now - start
        let file = items.filter { $0.path.hasPrefix("File > ") || $0.path.hasPrefix("Fichier > ") }
        record(name, file.count >= 5, "\(items.count) items, File menu: \(file.prefix(3).map(\.path)), \(Int(latency.milliseconds)) ms", latency.milliseconds)
    }

    /// One of the user's tools: a webhook on this Mac gets the text, the
    /// token as Bearer, and its reply reaches the agent.
    private func toolsCallYourWebhook() async {
        let name = "Your Tools: a webhook gets the text and the token; its reply comes back"
        let settings = context.tools.settings
        guard let hook = LocalHook(reply: "received") else {
            record(name, false, "no local listener", nil)
            return
        }
        defer {
            hook.stop()
            settings.removeCustomTool(named: "test-hook")
        }
        guard await waitUntil(timeout: 2, { hook.port != nil }) != nil, let port = hook.port else {
            record(name, false, "the local listener did not start", nil)
            return
        }
        let refused = settings.saveCustomTool(CustomTool(name: "test-hook", instructions: "x", url: "http://example.com/hook"))
        settings.saveCustomTool(CustomTool(name: "Test Hook", instructions: "Send text to the test hook.", url: "http://127.0.0.1:\(port)/hook"), token: "secret")
        settings.setOverride(.always, for: "test-hook")
        let result = await skilliCall("test-hook", #"{"text":"hello from skil.li"}"#)
        let request = hook.lastRequest ?? ""
        let passed = refused != nil && result.status == 0 && result.output == "received"
            && request.contains("hello from skil.li") && request.lowercased().contains("authorization: bearer secret")
        record(name, passed, "plain http elsewhere refused: \(refused != nil), exit \(result.status), reply “\(result.output)”, got text: \(request.contains("hello from skil.li")), token: \(request.lowercased().contains("bearer secret"))", nil)
    }

