    /// card and sent with the conversation so far; ⌘↩ hands Claude Code or
    /// Codex the whole conversation.
    /// 3200 contacts for the speed checks, in memory (never the Mac's own).
    private static let manyContacts: [ContactRecord] = {
        let companies = ["Lumière", "Horizon", "Michelin", "Nimbus", "Renault", "Airbus", "Schneider", "Danone"]
        let given = ["Jean", "Marie", "Paul", "François", "Lucie", "Hugo", "Emma", "Louis"]
        return (0..<3_200).map { index in
            var record = ContactRecord(id: "speed-\(index)")
            record.givenName = given[index % given.count]
            record.familyName = "Nom\(index)"
            record.organization = companies[index % companies.count]
            record.jobTitle = index % 3 == 0 ? "Directeur technique" : "Acheteur"
            record.emails = [.init("work", "contact\(index)@example\(index % 50).com")]
            record.phones = [.init("mobile", "+33 6 \(10 + index % 89) \(10 + index % 77) 56 78")]
            return record
        }
    }()

    /// Every keystroke in the launcher, results found and the list drawn,
    /// over what this Mac has (apps, Mac commands, sounds, projects) and
    /// 3200 contacts. Under 8 ms at the 95th percentile in Release.
    /// `off`: entries turned off in Settings → Catalog, left out once per
    /// show: typing must not slow down.
    private func launcherTypesFast(off: Set<String> = []) async {
        let name = off.isEmpty ? "Typing speed: the launcher keeps up, key by key (results found and drawn)"
            : "Typing speed with \(off.count) Catalog entries Off: the launcher keeps up, key by key"
        let book = context.launcher.contacts
        book?.testRecords = Self.manyContacts
        let savedOff = context.preferences.catalogOff
        context.preferences.catalogOff = off
        defer {
            book?.testRecords = nil
            context.preferences.catalogOff = savedOff
        }
        let sentences = ["safari", "met la chanson suivante", "lock screen", "marie horizon", "12,5 * 4", "awake 1 hour",
                         "qui est jean-françois de chez lumière"]
        var durations: [Duration] = []
        var slowest = (took: Duration.zero, typed: "", laps: "")
        var steps: [String: Duration] = [:]
        var firstKeys: [Duration] = []
        var firstSteps: [String: Duration] = [:]
        for _ in 0..<3 {
            for sentence in sentences {
                // Each in a launcher just opened, as when used.
                guard await focusTestWindow() else { return }
                _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
                guard await waitUntil(timeout: 1, { self.context.launcher.isVisible }) != nil else {
                    record(name, false, "the launcher did not open", nil)
                    return
                }
                await pause(30)
                var typed = ""
                for character in sentence {
                    typed.append(character)
                    let took = context.launcher.simulateTyping(typed)
                    durations.append(took)
                    if typed.count == 1 {
                        firstKeys.append(took)
                        for step in context.launcher.lastSearchLaps.steps { firstSteps[step.name, default: .zero] += step.took }
                    }
                    if took > slowest.took { slowest = (took, typed, context.launcher.lastSearchLaps.summary) }
                    for step in context.launcher.lastSearchLaps.steps { steps[step.name, default: .zero] += step.took }
                    await pause(2)
                }
                await pressKey(nil, code: CGKeyCode(kVK_Escape))
                _ = await waitUntil(timeout: 1) { !self.context.launcher.isVisible }
            }
        }
        let sorted = durations.sorted()
        let median = sorted[sorted.count / 2], p95 = sorted[sorted.count * 95 / 100]
        #if DEBUG
        let bound = Duration.milliseconds(40)
        #else
        let bound = Duration.milliseconds(8)
        #endif
        let firstAverage = firstSteps.sorted { $0.value > $1.value }.prefix(4).map { "\($0.key) \(($0.value / max(firstKeys.count, 1)).compact)" }
            .joined(separator: " · ")
        let average = steps.sorted { $0.value > $1.value }.prefix(5).map { "\($0.key) \(($0.value / durations.count).compact)" }.joined(separator: " · ")
        record(name, p95 <= bound,
               "\(durations.count) keys: median \(median.compact), p95 \(p95.compact) (bound \(bound.compact)); first key after opening: median \(firstKeys.sorted()[firstKeys.count / 2].compact), worst \((firstKeys.max() ?? .zero).compact) (\(firstAverage)); on average \(average); slowest \(slowest.took.compact) at “\(slowest.typed)”: \(slowest.laps)",
               p95.milliseconds)
    }

    /// Keys typed in the card's answer line, here a follow-up under a long
    /// answer: handled inside the event tap in well under 2 ms (Release),
    /// the caret right after the last letter.
    private func cardTypesFast() async {
        let name = "Typing speed: keys in the card's answer line, caret right after the text"
        let popover = context.aiActions.popover
        let answer = (1...12).map { "- **Point \($0)** : une ligne de réponse assez longue pour remplir la carte, avec `du code` et un [lien](https://skil.li)." }
            .joined(separator: "\n")
        context.ai.testEngine = FakeTextEngine(chunks: ["## Réponse\n", answer], delay: .milliseconds(5))
        context.aiActions.routeOverride = .answer
        defer {
            context.ai.testEngine = nil
            context.aiActions.routeOverride = nil
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "Bonjour"
        textView.selectAll(nil)
        await pause(60)
        _ = await hyperChord(["a"], trigger: Self.ownTriggerKeyCode)
        guard await waitUntil(timeout: 2, { popover.isVisible && popover.phase == .asking }) != nil else {
            record(name, false, "no question in the card (phase \(popover.phase))", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        for character in "explique" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        _ = await waitUntil(timeout: 3) { popover.phase == .done }
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        guard await waitUntil(timeout: 2, { popover.phase == .asking }) != nil else {
            record(name, false, "no follow-up question (phase \(popover.phase))", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        let sentence = "traduis tout ceci en anglais avec soin et garde la mise en forme de chaque point"
        var durations: [Duration] = []
        var worstGap: CGFloat = 0
        for character in sentence {
            await pressKey(character)
            durations.append(context.aiActions.lastAnswerKeyDuration ?? .seconds(1))
            let caret = popover.answerCaret
            if abs(caret.caret - caret.textEnd) > abs(worstGap) { worstGap = caret.caret - caret.textEnd }
        }
        let typed = popover.shownQuestion?.typed ?? ""
        // The system's caret is on screen and blinks: captures 0.15 s apart.
        var seen = 0, captured = 0
        if let caret = popover.answerCaretOnScreen {
            let area = NSRect(x: caret.minX, y: caret.minY, width: caret.width + 6, height: caret.height)
            for _ in 0..<12 {
                if let image = await GlassCheck.screenshot(of: area) {
                    captured += 1
                    if Self.caretShows(in: image) { seen += 1 }
                }
                await pause(150)
            }
        }
        await saveScreenshot(of: popover.window, as: "ai-card-typing-speed.png")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !popover.isVisible }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let sorted = durations.sorted()
        let median = sorted[sorted.count / 2], p95 = sorted[sorted.count * 95 / 100]
        #if DEBUG
        let bound = Duration.milliseconds(4)
        #else
        let bound = Duration.milliseconds(2)
        #endif
        let caretOK = worstGap >= -0.5 && worstGap <= 1.5 && seen > 0
        record(name, typed == sentence && p95 <= bound && caretOK,
               "\(durations.count) keys: median \(median.compact), p95 \(p95.compact) (bound \(bound.compact)); caret off the text by \(worstGap) pt at worst, seen in \(seen) of \(captured) captures; typed “\(typed.suffix(30))”",
               p95.milliseconds)
    }

    /// Whether the caret's columns (the left ones) stand out from the
    /// empty field right of it.
    private static func caretShows(in image: CGImage) -> Bool {
        let width = image.width, height = image.height
        guard width >= 6, height > 0 else { return false }
        var pixels = [UInt8](repeating: 0, count: width * height * 4)
        guard let context = CGContext(data: &pixels, width: width, height: height, bitsPerComponent: 8, bytesPerRow: width * 4,
                                      space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)
        else { return false }
        context.draw(image, in: CGRect(x: 0, y: 0, width: width, height: height))
        func column(_ x: Int) -> (Double, Double, Double) {
            var sum = (0.0, 0.0, 0.0)
            for y in 0..<height {
                let index = (y * width + x) * 4
                sum.0 += Double(pixels[index]); sum.1 += Double(pixels[index + 1]); sum.2 += Double(pixels[index + 2])
            }
            return (sum.0 / Double(height), sum.1 / Double(height), sum.2 / Double(height))
        }
        let background = column(width - 2)
        let strongest = (0..<min(4, width)).map { x -> Double in
            let c = column(x)
            return abs(c.0 - background.0) + abs(c.1 - background.1) + abs(c.2 - background.2)
        }.max() ?? 0
        return strongest > 60
    }

    private func askFollowsUpInTheCard() async {
        let name = "Ask follow-ups: ⇥ after an answer, the next question in the card, sent with the conversation; ⌘↩ hands it all over"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: ["C'est une salutation."], delay: .milliseconds(20))
        context.aiActions.routeOverride = .answer
        var handed: [String] = []
        let handoff = context.aiActions.handoff
        handoff?.opened = { handed.append($1) }
        defer {
            context.ai.testEngine = nil
            context.aiActions.routeOverride = nil
            handoff?.opened = nil
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "Bonjour"
        textView.selectAll(nil)
        await pause(60)
        _ = await hyperChord(["a"], trigger: Self.ownTriggerKeyCode)
        guard await waitUntil(timeout: 2, { popover.isVisible && popover.phase == .asking }) != nil else {
            record(name, false, "no question in the card (phase \(popover.phase))", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        for character in "explique" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let answered = await waitUntil(timeout: 3) { popover.phase == .done } != nil
        await pause(200)
        let hints = popover.hintTitles
        await saveScreenshot(of: popover.window, as: "ai-card-follow-up-offered.png")

        // First follow-up.
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let asked = await waitUntil(timeout: 2) { popover.phase == .asking } != nil
        let question = popover.shownQuestion?.text ?? ""
        for character in "anglais" { await pressKey(character) }
        await pause(100)
        await saveScreenshot(of: popover.window, as: "ai-card-follow-up-typed.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let second = await waitUntil(timeout: 3) { popover.phase == .done } != nil
        let firstFollowUp = context.aiActions.lastMessage ?? ""

        // Second follow-up: both earlier turns go with it.
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        _ = await waitUntil(timeout: 2) { popover.phase == .asking }
        for character in "espagnol" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let third = await waitUntil(timeout: 3) { popover.phase == .done } != nil
        await pause(200)
        await saveScreenshot(of: popover.window, as: "ai-card-follow-up-answer.png")
        let secondFollowUp = context.aiActions.lastMessage ?? ""

        let carried = firstFollowUp.contains("User:\n") && firstFollowUp.contains("explique") && firstFollowUp.contains("Bonjour")
            && firstFollowUp.contains("You answered:\nC'est une salutation.") && firstFollowUp.contains("The user now asks:\nanglais")
            && secondFollowUp.contains("User:\nanglais") && secondFollowUp.contains("The user now asks:\nespagnol")
        var handedOver = true
        if handoff?.targets.isEmpty == false {
            await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
            _ = await waitUntil(timeout: 2) { !handed.isEmpty }
            let text = handed.last ?? ""
            handedOver = text.contains("explique") && text.contains("User:\nanglais") && text.contains("User:\nespagnol")
        } else {
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
        }
        _ = await waitUntil(timeout: 1) { !popover.isVisible }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, answered && hints.contains("Follow up") && asked && question == "Your follow-up" && second && third && carried && handedOver
               && textView.string == "Bonjour",
               "hints \(hints); asked “\(question)”; turns answered: \(answered), \(second), \(third); conversation carried: \(carried); handed over whole: \(handedOver)", nil)
    }

    /// A text changed in place (Fix Spelling, a translation) followed up
    /// with ⇥: what the user wants different, read with the exchange; the
    /// latest version shows, ↩ puts it in place of the selection.
    private func rewriteFollowsUp() async {
        let name = "Commands: a changed text follows up with ⇥ (Follow up), the model told what to change; ↩ replaces with the latest"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(rounds: [["Bonjour à tous."], ["Madame, Monsieur, bonjour."]], delay: .milliseconds(20))
        let command = scratchCommand(prompt: "Corrige ce texte, réponds avec le texte seul :\n\n{selection}", output: .replace)
        defer {
            context.ai.testEngine = nil
            context.aiCommands.delete(command.id)
        }
        guard await run(command, on: "bonjour a tous"), await waitUntil(timeout: 3, { popover.phase == .done }) != nil else {
            record(name, false, "no answer in the card (phase \(popover.phase))", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        let hints = popover.hintTitles
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let asked = await waitUntil(timeout: 2) { popover.phase == .asking && popover.shownQuestion?.text == "Your follow-up" } != nil
        for character in "plus formel" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let refined = await waitUntil(timeout: 3) { popover.phase == .done && popover.result == "Madame, Monsieur, bonjour." } != nil
        let message = context.aiActions.lastMessage ?? ""
        let told = message.contains("bonjour a tous") && message.contains("You answered:\nBonjour à tous.")
            && message.contains("They want it changed again:\nplus formel") && message.contains("Reply with the new text only")
        await pause(150)
        await saveScreenshot(of: popover.window, as: "ai-card-rewrite-follow-up.png")
        let refinedHints = popover.hintTitles
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 3) { self.textView.string == "Madame, Monsieur, bonjour." } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, hints.contains("Follow up") && asked && refined && told && refinedHints.first == "Replace" && replaced,
               "hints \(hints); asked: \(asked); refined: \(refined) (“\(popover.result.prefix(40))”); told what to change: \(told); then \(refinedHints); ↩ replaced: \(replaced) (“\(textView.string.prefix(40))”)", nil)
    }

    /// A connected service named in the request while the decision goes
    /// elsewhere ("answer", 56 %): the card puts the choice to the user,
    /// "Use <service>" first.
    private func askOffersANamedService() async {
        let name = "Ask: a connected service named, another route chosen: “Use selftest-nimbus” offered first"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: ["Une réponse."], delay: .milliseconds(20))
        await context.ai.refresh()
        context.aiActions.decisionOverride = AskRouter.Decision(route: .answer, confidence: 0.56, menu: [],
                                                                routes: [(.answer, 0.56), (.act, 0.3), (.find, 0.1)],
                                                                label: "Test", services: ["selftest-nimbus"])
        defer {
            context.ai.testEngine = nil
            context.aiActions.decisionOverride = nil
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        guard await openAsk() else {
            record(name, false, "no question in the card", nil)
            return
        }
        for character in "taches" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let offered = await waitUntil(timeout: 2) { popover.shownQuestion?.text == "What should I do?" } != nil
        await pause(150)
        let options = popover.shownOptions
        await saveScreenshot(of: popover.window, as: "ai-card-ask-named-service.png")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, offered && options.first == "Use selftest-nimbus" && options.contains(AskRoute.answer.choice),
               "offered: \(offered), options \(options)", nil)
    }

    /// "musique suivante" typed in Ask: the next-track key at once, no
    /// decision asked, nothing opened.
    private func askSendsMediaKeys() async {
        let name = "Ask: the media command the model picks (“musique suivante”, “coupe le son”) is sent at once, nothing opened"
        guard let commands = context.tools.tools.systemCommands else {
            record(name, false, "no system commands", nil)
            return
        }
        defer { context.aiActions.decisionOverride = nil }
        var sent: [String] = []
        for (typed, expected) in [("musique suivante", SystemCommand.nextTrack), ("coupe le son", .mute), ("coupe le son", .mute)] {
            guard await focusTestWindow() else { return }
            window.makeFirstResponder(textView)
            textView.string = ""
            // The model's pick (real ones in `selftest decide`).
            context.aiActions.decisionOverride = AskRouter.Decision(route: .command, confidence: 0.95, menu: [], routes: [(.command, 0.95)],
                                                                    command: (.system(expected), 0.95), commands: [(.system(expected), 0.95)],
                                                                    label: "Test")
            guard await openAsk() else {
                record(name, false, "no question in the card", nil)
                return
            }
            for character in typed { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let ran = await waitUntil(timeout: 2) { commands.lastCommand == expected } != nil
            sent.append("“\(typed)” → \(ran ? expected.rawValue : String(describing: commands.lastCommand))")
            await pause(200)
            if context.aiActions.popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        }
        let frontmost = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? ""
        record(name, sent.allSatisfy { !$0.contains("Optional") && !$0.contains("nil") } && context.aiActions.lastRoute == .command
               && frontmost == Bundle.main.bundleIdentifier, "\(sent.joined(separator: "; ")); app in front: \(frontmost)", nil)
    }

    /// An answer in Markdown: the card shows it styled (bold, bullets, a
    /// heading), never the markers; Return copies rich text and plain text
    /// without them.
    private func askShowsMarkdown() async {
        let name = "Answers in Markdown: styled in the card (no ** or ##), copied as rich text and as plain text without markers"
        let popover = context.aiActions.popover
        let answer = "## Deux tâches en cours\n- **SAFR-123** « Développer le lot 3 » : *échéance dépassée*\n- **ALPIN-17** : pas démarrée, voir `listTasks`"
        context.ai.testEngine = FakeTextEngine(chunks: [answer], delay: .milliseconds(20))
        context.aiActions.routeOverride = .answer
        let clipboard = PasteboardSnapshot(NSPasteboard.general)
        defer {
            context.ai.testEngine = nil
            context.aiActions.routeOverride = nil
            clipboard.restore(to: NSPasteboard.general)
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        guard await openAsk() else {
            record(name, false, "no question in the card", nil)
            return
        }
        for character in "resume mes taches nimbus" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let done = await waitUntil(timeout: 3) { popover.phase == .done } != nil
        await pause(200)
        await saveScreenshot(of: popover.window, as: "ai-card-markdown.png")
        let shown = popover.shownBody
        let text = shown.string
        let markersGone = !text.contains("**") && !text.contains("## ") && !text.contains("`")
        let bulleted = text.contains("•  SAFR-123") && text.contains("•  ALPIN-17")
        let range = (text as NSString).range(of: "SAFR-123")
        let font = range.location == NSNotFound ? nil : shown.attribute(.font, at: range.location, effectiveRange: nil) as? NSFont
        let bold = font?.fontDescriptor.symbolicTraits.contains(.bold) == true
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        await pause(200)
        let plain = NSPasteboard.general.string(forType: .string) ?? ""
        let rich = NSPasteboard.general.data(forType: .rtf) != nil
        let plainClean = plain.hasPrefix("Deux tâches en cours\n• SAFR-123") && !plain.contains("**")
        record(name, done && markersGone && bulleted && bold && rich && plainClean,
               "shown “\(text.prefix(80).replacingOccurrences(of: "\n", with: " ⏎ "))”, bold: \(bold); copied plain “\(plain.prefix(60).replacingOccurrences(of: "\n", with: " ⏎ "))”, rich text: \(rich)", nil)
    }

    /// Contacts kept in memory for the test (never the Mac's own, never a
    /// permission asked): found by a company in the launcher's Contacts
    /// mode, shown in the card, written to; the best one in a plain search;
    /// search_contacts and compose_email for agents.
    private func contactsFoundAndWritten() async {
        let name = "Contacts: “@lumiere” finds both, “@jean francois lumiere” first, ↩ shows the card, ↩ writes a mail; “horizon” in any search; search_contacts and compose_email"
        guard let book = context.launcher.contacts else {
            record(name, false, "no contacts", nil)
            return
        }
        func person(_ id: String, _ given: String, _ family: String, _ company: String, _ job: String, _ email: String) -> ContactRecord {
            var record = ContactRecord(id: id)
            record.givenName = given
            record.familyName = family
            record.organization = company
            record.jobTitle = job
            record.emails = [.init("work", email)]
            return record
        }
        book.testRecords = [person("st-1", "Jean-François", "Martin", "Lumière", "Directeur technique", "jf.martin@lumiere.example"),
                            person("st-2", "Jean", "Dupont", "Lumière", "", "jean.dupont@lumiere.example"),
                            person("st-3", "François", "Leroy", "Horizon", "Acheteur", "francois.leroy@horizon.example")]
        var opened: [URL] = []
        context.aiActions.openURL = { opened.append($0) }
        context.tools.tools.openURL = { opened.append($0) }
        defer {
            book.testRecords = nil
            context.aiActions.openURL = { NSWorkspace.shared.open($0) }
            context.tools.tools.openURL = { NSWorkspace.shared.open($0) }
        }
        let popover = context.aiActions.popover
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "@lumiere" { await pressKey(character) }
        let both = await waitUntil(timeout: 2) { Set(self.context.launcher.resultTitles) == ["Jean-François Martin", "Jean Dupont"] } != nil
        for character in " jean francois" { await pressKey(character) }
        let listed = await waitUntil(timeout: 2) { self.context.launcher.resultTitles.first == "Jean-François Martin" } != nil && both
        let titles = context.launcher.resultTitles
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let card = await waitUntil(timeout: 2) {
            popover.isVisible && popover.shownContent != nil && self.context.aiActions.shownContact?.jobTitle == "Directeur technique"
        } != nil
        await pause(200)
        await captureLauncherPlaceCard(frame: popover.window.frame, as: "ai-card-contact.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let mailed = await waitUntil(timeout: 2) { opened.contains { $0.absoluteString == "mailto:jf.martin@lumiere.example" } } != nil

        // Any search: the best contact among the rest.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "horizon" { await pressKey(character) }
        let inSearch = await waitUntil(timeout: 2) { self.context.launcher.resultTitles.contains("François Leroy") } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        let found = await skilliCall("search_contacts", #"{"query":"françois de chez horizon"}"#)
        let composed = await skilliCall("compose_email", #"{"to":["francois.leroy@horizon.example"],"subject":"Rendez-vous","body":"Bonjour François"}"#)
        let draft = opened.last?.absoluteString ?? ""
        let body = opened.last.flatMap { URLComponents(url: $0, resolvingAgainstBaseURL: false)?.queryItems?.first { $0.name == "body" }?.value }
        let agents = found.output.hasPrefix("**François Leroy**") && composed.status == 0
            && draft.hasPrefix("mailto:francois.leroy@horizon.example?subject=Rendez-vous&body=") && body == "Bonjour François".precomposedStringWithCanonicalMapping
        record(name, listed && card && mailed && inSearch && agents,
               "@lumiere → \(titles.prefix(3)); card: \(card); ↩ mailto: \(mailed); “horizon” in any search: \(inSearch); search_contacts “\(found.output.prefix(40))”; compose_email → \(draft)", nil)
    }

    /// A contact's card as Contacts shows one (light and dark captures):
    /// ↩ messages the mobile, ⌘K opens the launcher's list less Show
    /// Contact, typing filters, ↓ ↩ copies the second number, esc goes back
    /// to the card, esc again closes it. Nothing sent: links recorded.
    private func contactCardActs() async {
        let name = "Contact card: as Contacts shows one; ↩ messages, ⌘K the launcher's actions (less Show Contact), typing filters, ↩ copies, esc back to the card, esc closes"
        var person = ContactRecord(id: "st-card")
        person.givenName = "Jean-François"
        person.familyName = "Martin"
        person.jobTitle = "Directeur technique"
        person.organization = "Lumière"
        person.phones = [.init("work", "+33 1 23 45 67 89"), .init("mobile", "+33 6 12 34 56 78")]
        person.emails = [.init("work", "jf.martin@lumiere.example")]
        person.addresses = [.init("work", "3 rue du Port, 69001 Lyon, France")]
        person.postal = [.init(label: "work", street: "3 rue du Port", postalCode: "69001", city: "Lyon", country: "France")]
        person.birthday = "12 March"
        var opened: [URL] = []
        context.aiActions.openURL = { opened.append($0) }
        let clipboard = PasteboardSnapshot(NSPasteboard.general)
        let popover = context.aiActions.popover
        defer {
            context.aiActions.openURL = { NSWorkspace.shared.open($0) }
            clipboard.restore(to: NSPasteboard.general)
            popover.window.appearance = nil
            window.appearance = nil
        }
        guard await focusTestWindow() else { return }
        for dark in [true, false] {
            popover.window.appearance = NSAppearance(named: dark ? .darkAqua : .aqua)
            window.appearance = NSAppearance(named: dark ? .darkAqua : .aqua)
            context.aiActions.showContact(person)
            _ = await waitUntil(timeout: 2) { popover.isVisible && popover.shownContent != nil }
            await pause(700)
            await captureLauncherPlaceCard(frame: popover.window.frame, as: "contact-card-\(dark ? "dark" : "light").png")
        }
        let hints = popover.hintTitles
        let actions = context.aiActions.shownContactActions.map(\.title)
        let expected = ["Message Jean-François", "Call Jean-François", "Email Jean-François", "Open in Contacts", "Send Contact Card…",
                        "Copy Name", "Copy Phone (mobile)", "Copy Phone (work)", "Copy Email (work)", "Copy Address"]
        let keys = context.aiActions.shownContactActions.filter { $0.key != nil }.map { "\($0.title) \($0.key ?? "")" }

        // ⌘K: the list; "co ph" keeps the numbers; ↓ ↩ copies the second.
        await pressKey(Character("k"), flags: .maskCommand)
        let listed = await waitUntil(timeout: 1) { self.context.aiActions.shownContactList == expected } != nil
        await pause(200)
        await captureLauncherPlaceCard(frame: popover.window.frame, as: "contact-card-actions.png")
        for character in "co ph" { await pressKey(character) }
        let filtered = await waitUntil(timeout: 1) {
            self.context.aiActions.shownContactList == ["Copy Phone (mobile)", "Copy Phone (work)"]
        } != nil
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let copied = await waitUntil(timeout: 1) { NSPasteboard.general.string(forType: .string) == "+33 1 23 45 67 89" } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = await waitUntil(timeout: 2) { !popover.isVisible }

        // ↩ on the card: a message to the mobile.
        context.aiActions.showContact(person)
        _ = await waitUntil(timeout: 2) { popover.isVisible && popover.shownContent != nil }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let messaged = await waitUntil(timeout: 1) { opened.last?.absoluteString == "sms:+33612345678" } != nil && !popover.isVisible

        // esc in the list: back to the card; esc again: closed.
        context.aiActions.showContact(person)
        _ = await waitUntil(timeout: 2) { popover.isVisible && popover.shownContent != nil }
        await pressKey(Character("k"), flags: .maskCommand)
        _ = await waitUntil(timeout: 1) { self.context.aiActions.shownContactList != nil }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let back = await waitUntil(timeout: 1) {
            popover.isVisible && self.context.aiActions.shownContactList == nil && self.context.aiActions.shownContact != nil
        } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let closed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        record(name, hints == ["Message", "Contacts", "Actions", "Close"] && actions == expected && listed && filtered && copied && messaged && back && closed,
               "hints \(hints); actions \(actions == expected ? "as the launcher's" : "\(actions)"); keys \(keys); ⌘K listed: \(listed), “co ph”: \(filtered), ↓ ↩ copied the work number: \(copied); ↩ messaged the mobile: \(messaged) (\(opened.last?.absoluteString ?? "nothing")); esc back: \(back), esc closed: \(closed)", nil)
    }

    /// ⌘K on a contact kept in memory: its actions in order with their
    /// keys; "co ph" filters, ↓ ↩ copies the second number; "call" ↩ dials
    /// the mobile (kept, not called); esc goes back to the results, esc
    /// again closes. Without the list: ⇧⌘C copies the mobile, ⌘C the name,
    /// and ⌘C with the field's text selected copies that text.
    private func actionsForTheSelectedRow() async {
        let name = "⌘K (and ⇥ in a mode): a contact's actions with their keys, filtered by typing, ↩ runs; the footer; ⌘C / ⇧⌘C copy without it, ⌘C a title where nothing else; esc goes back, then closes"
        guard let book = context.launcher.contacts else {
            record(name, false, "no contacts", nil)
            return
        }
        var paul = ContactRecord(id: "st-paul")
        paul.givenName = "Paul"
        paul.familyName = "Martin"
        paul.phones = [.init("work", "01 23 45 67 89"), .init("mobile", "+33 6 12 34 56 78")]
        paul.emails = [.init("work", "paul@example.com")]
        book.testRecords = [paul]
        let launcher = context.launcher
        var opened: [URL] = []
        launcher.openURL = { opened.append($0) }
        defer {
            book.testRecords = nil
            launcher.openURL = { NSWorkspace.shared.open($0) }
        }
        func open() async -> Bool {
            guard await focusTestWindow() else { return false }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "@paul" { await pressKey(character) }
            return await waitUntil(timeout: 2) { launcher.resultTitles.first == "Paul Martin" } != nil
        }
        func pasted() -> String { NSPasteboard.general.string(forType: .string) ?? "" }

        guard await open() else {
            record(name, false, "Paul Martin not listed: \(launcher.resultTitles)", nil)
            return
        }
        // The footer: the row's own ↩, then ⌘K (⇥ in a mode does what ⌘K does).
        let footer = launcher.shownFooter
        await pressKey("k", flags: .maskCommand)
        let expected: [(String, String?)] = [("Show Contact", "↩"), ("Open in Contacts", "⌘↩"), ("Message Paul", nil), ("Call Paul", nil),
                                             ("Email Paul", nil), ("Send Contact Card…", nil), ("Copy Name", "⌘C"),
                                             ("Copy Phone (mobile)", "⇧⌘C"), ("Copy Phone (work)", nil), ("Copy Email (work)", nil)]
        let listed = await waitUntil(timeout: 2) {
            launcher.isShowingActions && launcher.shownActions.map { "\($0.title)|\($0.key ?? "")" } == expected.map { "\($0.0)|\($0.1 ?? "")" }
        } != nil
        let shown = launcher.shownActions.map(\.title)
        if let directory = context.snapshotDirectory, let png = await WindowCapture.png(of: launcher.window) {
            try? png.write(to: directory.appendingPathComponent("launcher-actions-contact.png"))
        }
        for character in "co ph" { await pressKey(character) }
        let filtered = await waitUntil(timeout: 1) { launcher.shownActions.map(\.title) == ["Copy Phone (mobile)", "Copy Phone (work)"] } != nil
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let copiedWork = await waitUntil(timeout: 1) { !launcher.isVisible && pasted() == "01 23 45 67 89" } != nil

        // ⇥ in the Contacts mode: the same list (never Ask); a key with no
        // action there says so in the list. "call" ↩: the mobile, as the
        // Phone app takes it.
        _ = await open()
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let tabList = await waitUntil(timeout: 1) { launcher.isShowingActions && launcher.shownActions.first?.title == "Show Contact" } != nil
            && !context.aiActions.popover.isVisible
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let saidInList = await waitUntil(timeout: 1) { launcher.shownActionsNote?.hasPrefix("Nothing on ⌘⌫") == true } != nil
        for character in "call" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let called = await waitUntil(timeout: 1) { opened.map(\.absoluteString) == ["tel:+33612345678"] } != nil

        // esc: back to the results, the launcher still open; esc again closes.
        _ = await open()
        await pressKey("k", flags: .maskCommand)
        _ = await waitUntil(timeout: 1) { launcher.isShowingActions }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let back = await waitUntil(timeout: 1) { !launcher.isShowingActions && launcher.isVisible && launcher.resultTitles.first == "Paul Martin" } != nil
        // Without the list: ⇧⌘C the mobile, ⌘C the name.
        await pressKey("c", flags: [.maskCommand, .maskShift])
        let mobile = await waitUntil(timeout: 1) { pasted() == "+33 6 12 34 56 78" } != nil
        _ = await open()
        await pressKey("c", flags: .maskCommand)
        let copiedName = await waitUntil(timeout: 1) { pasted() == "Paul Martin" } != nil
        // The field's text selected: ⌘C copies it, the launcher stays.
        _ = await open()
        await pressKey("a", flags: .maskCommand)
        await pressKey("c", flags: .maskCommand)
        let copiedText = await waitUntil(timeout: 1) { pasted() == "paul" && launcher.isVisible } != nil
        // esc in the Contacts mode: back to the launcher as it was before
        // "@" (empty), still open; esc again closes.
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let backToRoot = await waitUntil(timeout: 1) { launcher.isVisible && launcher.mode == nil && launcher.query.isEmpty } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let closedAfter = await waitUntil(timeout: 1) { !launcher.isVisible } != nil
        await closeLauncher()
        // ⌘C on a row with nothing of its own to copy: its title, never its
        // skilli:// link, nothing said.
        var copiedTitle = false
        if await openLauncher() {
            for character in "reset launcher position" { await pressKey(character) }
            if await waitUntil(timeout: 1, { launcher.resultTitles.first == "Reset Launcher Position" }) != nil {
                await pressKey("c", flags: .maskCommand)
                copiedTitle = await waitUntil(timeout: 1) { pasted() == "Reset Launcher Position" && !launcher.isVisible } != nil
                    && !context.aiActions.popover.isVisible
            }
            await closeLauncher()
        }
        record(name, footer == ["Show Contact ↩", "Actions ⌘K"] && listed && filtered && copiedWork && tabList && saidInList && called && back && mobile
                   && copiedName && copiedText && backToRoot && closedAfter && copiedTitle,
               "footer \(footer); listed: \(listed) \(shown); “co ph”: \(filtered), ↓↩ work number: \(copiedWork); ⇥ the list: \(tabList), ⌘⌫ there said: \(saidInList); call: \(called) \(opened); esc back: \(back); "
                   + "⇧⌘C mobile: \(mobile), ⌘C name: \(copiedName), ⌘C selected text: \(copiedText) (“\(pasted())”); esc back to the empty launcher: \(backToRoot), esc closed: \(closedAfter); "
                   + "⌘C on Reset Launcher Position copied its title: \(copiedTitle)", nil)
    }

    /// Chess, opened for it: its row says it runs; ⌘K Quit, then Force
    /// Quit, go through Kill Process's card (it confirms even if the user
    /// chose Always, then says done); once it quit, neither is offered.
    /// Opened again after if it was running.
    private func appRowQuitsARunningApp() async {
        let name = "App rows: “running” when it runs; ⌘K Quit at once, Force Quit asked (↩ Force Quit, esc Cancel), then done; neither once it quit; ⌘K Set Shortcut… records its keys"
        let bundleID = "com.apple.Chess"
        guard let url = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "Chess not found", nil)
            return
        }
        // "Échecs" on a French Mac.
        var title = FileManager.default.displayName(atPath: url.path)
        if title.hasSuffix(".app") { title.removeLast(4) }
        func running() -> Bool { !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty }
        func start() async -> Bool {
            let configuration = NSWorkspace.OpenConfiguration()
            configuration.activates = false
            // Hidden: Chess comes to the front even when told not to, and
            // the launcher closes as it loses the focus.
            configuration.hides = true
            guard let app = try? await NSWorkspace.shared.openApplication(at: url, configuration: configuration) else { return false }
            return await waitUntil(timeout: 5) { app.isFinishedLaunching } != nil
        }
        let wasRunning = running()
        let launcher = context.launcher
        let popover = context.aiActions.popover

        /// The launcher on "chess", the row drawn as `runs` says.
        func open(runs: Bool) async -> Bool {
            guard await focusTestWindow() else { return false }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "chess" { await pressKey(character) }
            return await waitUntil(timeout: 3) {
                launcher.isVisible && launcher.resultTitles.first == title && launcher.resultAccessories.first?.hasSuffix(" · running") == runs
            } != nil
        }
        /// ⌘K, the action's name typed, ↩; a question in the card is
        /// answered with ↩ (its words kept).
        func quit(_ typed: String) async -> (asked: Bool, card: String, said: String, gone: Bool) {
            await pressKey("k", flags: .maskCommand)
            guard await waitUntil(timeout: 1, { launcher.isShowingActions }) != nil else { return (false, "", "no ⌘K list", !running()) }
            for character in typed { await pressKey(character) }
            _ = await waitUntil(timeout: 1) { launcher.shownActions.first?.title.lowercased() == typed }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let asked = await waitUntil(timeout: 2) { !launcher.isVisible && popover.isVisible && popover.phase == .approving } != nil
            let card = asked ? "\(popover.shownText.split(separator: "\n").first ?? "") \(popover.hintTitles)" : ""
            if asked { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
            // Gone is the answer: the card goes, nothing said.
            let gone = await waitUntil(timeout: 5) { !running() } != nil
            _ = await waitUntil(timeout: 2) { !popover.isVisible }
            let said = popover.isVisible ? popover.shownText : ""
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            return (asked, card, said, gone)
        }

        guard await start() else {
            record(name, false, "Chess did not open", nil)
            return
        }
        let shownRunning = await open(runs: true)
        // Outside the modes: its ↩, ⇥ Ask on what is typed, ⌘K.
        let appFooter = launcher.shownFooter
        let footerSays = appFooter == (launcher.lastResultTitle?.hasPrefix("Ask") == true ? ["Open ↩", "Ask ⇥", "Actions ⌘K"] : ["Open ↩", "Actions ⌘K"])
        await pressKey("k", flags: .maskCommand)
        // Chess is macOS's own: no Uninstall….
        let expected: [(String, String?)] = [("Open", "↩"), ("Show in Finder", nil), ("Quit", nil), ("Force Quit", nil), ("Set Shortcut…", nil),
                                             ("Set Alias…", nil), ("Pin", nil), ("Copy Name", "⌘C"), ("Copy Path", "⇧⌘C")]
        let listed = await waitUntil(timeout: 2) {
            launcher.isShowingActions && launcher.shownActions.map { "\($0.title)|\($0.key ?? "")" } == expected.map { "\($0.0)|\($0.1 ?? "")" }
        } != nil
        let shown = launcher.shownActions.map(\.title)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let quitted = await quit("quit")

        // Chess again, its row "running" before ⌘K (it takes a moment to
        // come back after the quit; the launcher may close as it does).
        _ = await start()
        _ = await waitUntil(timeout: 5) { running() }
        if !(await open(runs: true)) {
            if launcher.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await open(runs: true)
        }
        let forced = await quit("force quit")

        // Quit: the row says nothing more, ⌘K offers neither.
        let shownStopped = await open(runs: false)
        await pressKey("k", flags: .maskCommand)
        let stoppedList = await waitUntil(timeout: 2) {
            launcher.isShowingActions && launcher.shownActions.map(\.title) == ["Open", "Show in Finder", "Set Shortcut…", "Set Alias…", "Pin", "Copy Name", "Copy Path"]
        } != nil
        // Set Shortcut…: the card asks for the keys, the next ones are it.
        let store = context.shortcuts
        let openChess = SkilliAction.openApp(url.path)
        let hadShortcut = store.entryID(for: openChess) != nil
        for character in "set shortcut" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.shownActions.first?.title == "Set Shortcut…" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let askedKeys = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.hasPrefix("Press the keys for") } != nil
        await pressKey("9", flags: [.maskCommand, .maskAlternate, .maskShift])
        let saidKeys = await waitUntil(timeout: 2) { popover.shownText.hasSuffix("opens \(title).") } != nil
        let recorded = store.entryID(for: openChess).flatMap { id in store.config.shortcuts.first { $0.id == id }?.chords } != nil
        let said = popover.shownText
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        if !hadShortcut, let id = store.entryID(for: openChess) { store.remove(id) }
        await closeLauncher()
        if wasRunning { _ = await start() }
        let forcedWords = forced.card == "Force Quit \(title)? [\"Force Quit\", \"Cancel\"]"
        record(name, shownRunning && footerSays && listed && !quitted.asked && quitted.gone && quitted.said.isEmpty
                   && forced.asked && forcedWords && forced.gone && forced.said.isEmpty && shownStopped && stoppedList && askedKeys && saidKeys && recorded,
               "“\(title)” running: \(shownRunning) \(launcher.resultAccessories.prefix(1)), footer \(appFooter); ⌘K: \(listed) \(shown); "
                   + "Quit at once: \(!quitted.asked), “\(quitted.said)”, gone: \(quitted.gone); Force Quit asked: \(forced.asked) “\(forced.card)” \(forcedWords), “\(forced.said)”, gone: \(forced.gone); "
                   + "stopped row: \(shownStopped), its ⌘K without them: \(stoppedList); Set Shortcut… asked: \(askedKeys), said: \(saidKeys) “\(said)”, recorded: \(recorded)", nil)
    }

    /// Ask about a person, contacts kept in memory, no decision key: who
    /// they are (the card), a mail (empty, or written by the AI first),
    /// and the user picking between two close ones.
    /// Events kept in memory for the test (never the Mac's own, no
    /// permission asked): the meeting about to start first in the launcher
    /// and ↩ joins it; "reunion" finds it and ⌘↩ shows it in Calendar; the
    /// Agenda mode in order, filtered, ⇥ details; Ask's next meeting (⇧↩
    /// writes to whoever is invited), join, a day and free time without a
    /// model; list_events for agents.
    private func agendaFoundAndJoined() async {
        let name = "Agenda: next meeting first (↩ joins), “reunion” finds it, Agenda mode (⇥ details), Ask: next, join, a day, free time; list_events"
        guard let book = context.launcher.calendar else {
            record(name, false, "no calendar", nil)
            return
        }
        let now = Date.now
        let clock = Calendar.current
        let tomorrow = clock.date(byAdding: .day, value: 1, to: clock.startOfDay(for: now)) ?? now
        let sync = AgendaEvent(id: "st-sync", title: "Weekly sync", start: now.addingTimeInterval(5 * 60), end: now.addingTimeInterval(35 * 60),
                               calendar: "Work", notes: "Join with Google Meet: https://meet.google.com/abc-defg-hij",
                               attendees: [.init(name: "Paul Martin", email: "paul@example.com")])
        let dentist = AgendaEvent(id: "st-dentist", title: "Dentiste", start: tomorrow.addingTimeInterval(9 * 3_600),
                                  end: tomorrow.addingTimeInterval(9.5 * 3_600), calendar: "Perso", location: "Paris")
        let holiday = AgendaEvent(id: "st-holiday", title: "Holiday", start: tomorrow,
                                  end: clock.date(byAdding: .day, value: 1, to: tomorrow) ?? tomorrow, isAllDay: true, calendar: "Perso")
        book.testEvents = [dentist, holiday, sync]
        var opened: [URL] = []
        var shown: [String] = []
        book.openURL = { opened.append($0) }
        book.shownInCalendar = { shown.append($0.id) }
        context.aiActions.decisionKeysOverride = [:]
        defer {
            book.testEvents = nil
            book.openURL = { NSWorkspace.shared.open($0) }
            book.shownInCalendar = nil
            context.aiActions.decisionKeysOverride = nil
        }
        let meet = "https://meet.google.com/abc-defg-hij"
        let launcher = context.launcher
        let popover = context.aiActions.popover

        // Nothing typed: the meeting in five minutes first; ↩ joins.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        let first = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Weekly sync" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let joined = await waitUntil(timeout: 1) { opened.last?.absoluteString == meet } != nil

        // "reunion": the next meeting first; ⌘↩ shows it in Calendar.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "reunion" { await pressKey(character) }
        let typed = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Weekly sync" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
        let inCalendar = await waitUntil(timeout: 1) { shown.last == "st-sync" } != nil

        // "cal ": every event in the agenda's order; "dent" narrows; ⇥ details.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "cal " { await pressKey(character) }
        let expected = Agenda.sections(book.testEvents ?? [], now: .now).flatMap(\.events).map(\.title)
        let listed = await waitUntil(timeout: 2) { launcher.resultTitles == expected } != nil
        let order = launcher.resultTitles
        for character in "dent" { await pressKey(character) }
        let filtered = await waitUntil(timeout: 1) { launcher.resultTitles == ["Dentiste"] } != nil
        // No call: ↩ shows it in Calendar; ⇥ its details.
        let agendaFooter = launcher.shownFooter
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let details = await waitUntil(timeout: 2) {
            popover.isVisible && popover.shownTitle == "Event" && popover.shownText.contains("Dentiste") && popover.hintTitles.contains("Open in Calendar")
        } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let dentistShown = await waitUntil(timeout: 1) { shown.last == "st-dentist" } != nil

        // Ask, with what the model reads (`plansRead`).
        func ask(_ text: String, _ plan: [String: String]) async -> Bool {
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            textView.string = ""
            guard await openAsk() else { return false }
            plansRead(plan)
            for character in text { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return true
        }
        _ = await ask("quand est ma prochaine reunion", ["plan": "next"])
        let next = await waitUntil(timeout: 2) {
            popover.shownTitle == "Next Meeting" && popover.shownText.contains("Weekly sync") && popover.hintTitles.contains("Join")
        } != nil
        await saveScreenshot(of: popover.window, as: "agenda-next-meeting.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskShift)
        let mailed = await waitUntil(timeout: 1) { opened.last?.absoluteString.hasPrefix("mailto:paul@example.com") == true } != nil

        _ = await ask("rejoins la reunion", ["plan": "join"])
        let askJoined = await waitUntil(timeout: 2) { opened.last?.absoluteString == meet && !popover.isVisible } != nil

        _ = await ask("mon agenda demain", ["plan": "day", "when": "at", "day": "tomorrow", "hour": "none", "part_of_day": "none"])
        let day = await waitUntil(timeout: 2) {
            popover.shownTitle == "Calendar" && popover.shownText.contains("Dentiste") && popover.shownText.contains("Holiday")
        } != nil
        await saveScreenshot(of: popover.window, as: "agenda-day.png")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        _ = await ask("mes dispos", ["plan": "availability"])
        let free = await waitUntil(timeout: 2) { popover.shownTitle == "Availability" && popover.hintTitles.contains("Copy") } != nil
        setClipboard("skilli-selftest")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let copied = await waitUntil(timeout: 1) { NSPasteboard.general.string(forType: .string)?.contains("–") == true } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        plansRead(nil)
        let found = await skilliCall("list_events", #"{"query":"dentiste"}"#)
        let agents = found.output.contains("Dentiste") && found.output.contains("at Paris") && !found.output.contains("Weekly sync")
        let footerSays = agendaFooter == ["Open in Calendar ↩", "Details ⇥", "Actions ⌘K"]
        record(name, first && joined && typed && inCalendar && listed && filtered && footerSays && details && dentistShown && next && mailed && askJoined
               && day && free && copied && agents,
               "launcher first: \(first), joined: \(joined); typed: \(typed), ⌘↩ Calendar: \(inCalendar); agenda \(order) (\(listed)), filtered: \(filtered), footer \(agendaFooter), ⇥ details: \(details), ↩ Calendar: \(dentistShown); Ask next: \(next), ⇧↩ mail: \(mailed), join: \(askJoined), day: \(day), free: \(free) copied \(copied); list_events: \(agents) “\(found.output.prefix(80))”",
               nil)
    }

    /// The Mac's own calendars, read only, when skil.li may read them:
    /// counts only, never a title. Skipped otherwise (never a prompt in a
    /// test).
    private func calendarReadsThisMac() {
        let name = "Agenda: this Mac's calendars read through EventKit (read only, counts only)"
        guard let book = context.launcher.calendar, book.testEvents == nil else { return }
        // Only here are the Mac's own calendars read: counts, never a title.
        book.readsTheMac = true
        defer { book.readsTheMac = false }
        guard book.isAllowed else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "Calendar not allowed on this Mac", latencyMs: nil))
            return
        }
        let start = ContinuousClock.now
        let now = Date.now
        let events = book.events(from: Calendar.current.startOfDay(for: now), to: now.addingTimeInterval(30 * 86_400))
        let took = ContinuousClock.now - start
        let calls = events.filter { $0.meeting != nil }.count
        let next = book.nextMeeting(now: now) != nil
        record(name, true, "\(events.count) events in 30 days, \(calls) with a call link, a next meeting: \(next); read in \(took.compact)",
               took.milliseconds)
    }

    /// Events said, in memory (never the Mac's own calendars): the
    /// launcher offers "rdv demain 14h point budget" first, ↩ adds it, ⌘Z
    /// takes it back; Ask blocks time, says whether the user is free; ⌘⌫ in
    /// the Agenda deletes an event nobody else is invited to at once (Undo
    /// ⌘Z); create, update and delete for agents.
    private func agendaEventsAdded() async {
        let name = "Agenda: events said and added (↩, ⌘Z takes back), time blocked, free or busy, ⌘⌫ deletes at once (Undo ⌘Z); create/update/delete_event"
        guard let book = context.launcher.calendar else {
            record(name, false, "no calendar", nil)
            return
        }
        let clock = Calendar.current
        let tomorrow = clock.date(byAdding: .day, value: 1, to: clock.startOfDay(for: .now)) ?? .now
        let sync = AgendaEvent(id: "st-sync", title: "Weekly sync", start: tomorrow.addingTimeInterval(15 * 3_600),
                               end: tomorrow.addingTimeInterval(15.5 * 3_600), calendar: "Work")
        book.testEvents = [sync]
        context.aiActions.decisionKeysOverride = [:]
        defer {
            book.testEvents = nil
            context.aiActions.decisionKeysOverride = nil
        }
        let launcher = context.launcher
        let popover = context.aiActions.popover

        // Said in the launcher: offered first, ↩ adds, ⌘Z takes back.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "rdv demain 14h point budget" { await pressKey(character) }
        let offered = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Add “Point budget”" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let added = await waitUntil(timeout: 2) { popover.shownTitle == "Added to Work" && popover.hintTitles.contains("Undo") } != nil
        let request = book.createdForTest.last
        let rightTime = request?.start == tomorrow.addingTimeInterval(14 * 3_600) && request?.end == tomorrow.addingTimeInterval(15 * 3_600)
        await saveScreenshot(of: popover.window, as: "agenda-event-added.png")
        await pressKey(Character("z"), flags: .maskCommand)
        let takenBack = await waitUntil(timeout: 1) { book.testEvents?.contains { $0.title == "Point budget" } == false } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // Ask, with what the model reads (`plansRead`).
        func ask(_ text: String, _ plan: [String: String]) async -> Bool {
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            textView.string = ""
            guard await openAsk() else { return false }
            plansRead(plan)
            for character in text { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return true
        }
        // Time blocked from Ask.
        let blockSaid = "bloque 2h demain matin pour ecrire"
        _ = await ask(blockSaid, words(blockSaid, "title", from: "ecrire", to: "ecrire").merging(
            ["plan": "event", "when": "at", "day": "tomorrow", "hour": "none", "part_of_day": "morning", "ends": "length", "lasts": "2 h"]) { $1 })
        let blocked = await waitUntil(timeout: 2) { popover.shownTitle == "Added to Work" } != nil
        let block = book.createdForTest.last
        let blockTime = block?.title == "Ecrire" && block?.start == tomorrow.addingTimeInterval(9 * 3_600) && block?.end == tomorrow.addingTimeInterval(11 * 3_600)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // Free or busy then.
        _ = await ask("suis-je libre demain apres-midi", ["plan": "free", "when": "at", "day": "tomorrow", "hour": "none", "part_of_day": "afternoon"])
        plansRead(nil)
        let busy = await waitUntil(timeout: 2) {
            popover.shownTitle == "Calendar" && popover.shownText.contains("Busy") && popover.shownText.contains("Weekly sync")
                && popover.shownText.contains("15:30–18:00")
        } != nil
        let freeText = popover.shownText
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // ⌘⌫ in the Agenda: nobody else invited, deleted at once; the undo
        // card says so (⌘Z, ↩ and invitees in `eventDeleteUndoes`).
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "cal weekly" { await pressKey(character) }
        _ = await waitUntil(timeout: 2) { launcher.resultTitles.first == "Weekly sync" }
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let deleted = await waitUntil(timeout: 1) { book.testEvents?.contains { $0.id == "st-sync" } == false } != nil
        let asked = await waitUntil(timeout: 2) {
            popover.shownTitle == "Event Deleted" && popover.shownText.contains("Weekly sync") && popover.hintKeys == ["⌘Z", "esc"]
        } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        // For agents: each change waits for Return in the card.
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .auto
        defer { settings.mode = mode }
        func approved(_ tool: String, _ arguments: String) async -> (status: Int32, output: String) {
            async let call = skilliCall(tool, arguments)
            _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
            await pause(150)
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return await call
        }
        let day = DateFormatter()
        day.locale = Locale(identifier: "en_US_POSIX")
        day.dateFormat = "yyyy-MM-dd"
        let created = await approved("create_event", #"{"title":"Revue","start":"\#(day.string(from: tomorrow))T10:00","calendar":"Work"}"#)
        let id = created.output.range(of: #"id (created-[^)]+)"#, options: .regularExpression)
            .map { String(created.output[$0].dropFirst(3)) } ?? ""
        let updated = await approved("update_event", #"{"id":"\#(id)","title":"Revue budget"}"#)
        let removed = await approved("delete_event", #"{"id":"\#(id)"}"#)
        let agents = created.output.hasPrefix("Added (id created-") && updated.output.contains("Revue budget") && removed.output == "Deleted “Revue budget”."
        record(name, offered && added && rightTime && takenBack && blocked && blockTime && busy && asked && deleted && agents,
               "offered: \(offered), added: \(added) at the right time: \(rightTime), ⌘Z: \(takenBack); blocked: \(blocked) \(blockTime); free or busy: \(busy) “\(freeText.prefix(60))”; ⌘⌫ deleted at once: \(deleted), undo card: \(asked); agents: \(agents) (\(created.output.prefix(40)) / \(removed.output))",
               nil)
    }

    /// Settings → Agenda at work, on events in memory: the meeting in five
    /// minutes shows in the menu bar and the one timer waits for its start;
    /// one starting in two seconds offers itself in the card as it starts
    /// (the real timer); one 15 minutes in has left the menu bar.
    /// Alerts (Settings → Agenda): the card in the middle of the screen at
    /// its minute, the time counting down, every screen dark around it when
    /// set so, both gone with esc; On time says "Starting now"; an event
    /// without a call offers Open. Each look is captured, the whole screen,
    /// to judge the design. Scratch events.
    private func meetingAlertsBefore() async {
        let name = "Agenda alerts: the card mid-screen at its minute, counting down, screens dark when set so, gone with esc; dark while typing takes the keyboard, ↩ joins; On time; without a call"
        guard let book = context.launcher.calendar else {
            record(name, false, "no calendar", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.agendaAlerts, preferences.agendaAutoJoin, preferences.agendaAlertWithoutCall)
        let watch = context.meetingWatch
        let card = context.meetingCard
        defer {
            card.dismiss()
            book.testEvents = nil
            preferences.agendaAlerts = saved.0
            preferences.agendaAutoJoin = saved.1
            preferences.agendaAlertWithoutCall = saved.2
            watch.resetForTest()
            watch.refresh()
        }
        let people = ["Paul Martin", "Anna Lefèvre", "Claire Dubois", "Marc Petit", "Sophie Bernard"].map { AgendaEvent.Attendee(name: $0, email: nil) }
        func meeting(_ id: String, _ title: String, in seconds: TimeInterval, call: Bool = true, attendees: [AgendaEvent.Attendee] = []) -> AgendaEvent {
            AgendaEvent(id: id, title: title, start: Date.now.addingTimeInterval(seconds), end: Date.now.addingTimeInterval(seconds + 1800),
                        calendar: "Work", location: call ? "" : "Le Comptoir, 12 rue de la Paix",
                        notes: call ? "https://meet.google.com/abc-defg-hij" : "", attendees: attendees)
        }
        func alert(_ alerts: [MeetingAlert], _ event: AgendaEvent, withoutCall: Bool = false) {
            card.dismiss()
            watch.resetForTest()
            preferences.agendaAlerts = alerts
            preferences.agendaAlertWithoutCall = withoutCall
            book.testEvents = [event]
            watch.refresh()
        }
        func capture(_ file: String) async {
            guard let directory = context.snapshotDirectory, let screen = card.window?.screen ?? NSScreen.main,
                  let content = try? await SCShareableContent.current,
                  let display = content.displays.first(where: { $0.displayID == (screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? CGDirectDisplayID) })
            else { return }
            let filter = SCContentFilter(display: display, excludingWindows: [])
            let configuration = SCStreamConfiguration()
            configuration.width = Int(CGFloat(display.width) * screen.backingScaleFactor)
            configuration.height = Int(CGFloat(display.height) * screen.backingScaleFactor)
            configuration.showsCursor = false
            guard let image = try? await SCScreenshotManager.captureImage(contentFilter: filter, configuration: configuration),
                  let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) else { return }
            try? png.write(to: directory.appendingPathComponent(file))
        }
        preferences.agendaAutoJoin = .off

        // Five minutes before, screens dark: two seconds from now.
        alert([MeetingAlert(minutes: 5, style: .dark)], meeting("st-alert-dark", "Weekly design review", in: 5 * 60 + 2, attendees: people))
        let dark = await waitUntil(timeout: 6) {
            card.isVisible && card.screensDark && card.shownTitle == "Weekly design review" && card.shownEyebrow.hasPrefix("STARTS IN 4:") && card.shownAction == "Join"
        } != nil
        let firstEyebrow = card.shownEyebrow
        await pause(1300)
        let counting = card.shownEyebrow != firstEyebrow
        await capture("meeting-card-dark.png")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let darkGone = await waitUntil(timeout: 2) { !card.isVisible && !card.screensDark } != nil

        // Typing in an app as the dark alert comes (2026-10-16): the card
        // takes the keyboard, the keys on their way do nothing, then ↩ joins
        // and nothing reached the app.
        var opened: [URL] = []
        book.openURL = { opened.append($0) }
        _ = await focusTestWindow()
        window.makeFirstResponder(textView)
        textView.string = ""
        alert([MeetingAlert(minutes: 5, style: .dark)], meeting("st-alert-typing", "Standup", in: 5 * 60 + 2))
        var typed = 0
        while !card.isVisible, typed < 40 {
            await pressKey("a")
            typed += 1
            await pause(120)
        }
        let shownTyping = card.isVisible && card.screensDark
        let keysAtShow = textView.string.count
        await pressKey("b")
        await pause(700)
        let taken = card.window?.isKeyWindow == true
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let joined = await waitUntil(timeout: 2) { opened.contains { $0.absoluteString.contains("meet.google.com") } && !card.isVisible } != nil
        let leaked = textView.string.count != keysAtShow || textView.string.contains("\n")
        book.openURL = { NSWorkspace.shared.open($0) }

        // The card alone, a long name, one person.
        alert([MeetingAlert(minutes: 2, style: .card)],
              meeting("st-alert-card", "Quarterly planning with the product, design and engineering leads", in: 2 * 60 + 2,
                      attendees: [AgendaEvent.Attendee(name: "Anna Lefèvre", email: nil)]))
        let cardOnly = await waitUntil(timeout: 6) { card.isVisible && card.shownEyebrow.hasPrefix("STARTS IN 1:") } != nil && !card.screensDark
        await pause(400)
        await capture("meeting-card.png")
        card.dismiss()

        // On time, without a call (asked for): Got It, no one listed.
        alert([MeetingAlert(minutes: 0, style: .card)], meeting("st-alert-now", "Lunch with Paul", in: 2, call: false), withoutCall: true)
        let onTime = await waitUntil(timeout: 6) {
            card.isVisible && card.shownEyebrow == "STARTING NOW" && card.shownTitle == "Lunch with Paul" && card.shownAction == "Got It"
        } != nil
        await pause(400)
        await capture("meeting-card-now.png")
        card.dismiss()

        record(name, dark && counting && darkGone && shownTyping && taken && joined && !leaked && cardOnly && onTime,
               "5 min, dark: \(dark), counting down: \(counting) (“\(firstEyebrow)” → “\(card.shownEyebrow)”), gone with esc: \(darkGone); "
                   + "dark while typing: shown \(shownTyping), keyboard taken \(taken), ↩ joined \(joined), keys reached the app after it showed: \(leaked); "
                   + "2 min, card only: \(cardOnly); On time without a call, Got It: \(onTime)", nil)
    }

    /// No alert and no Join at once for a call the user is in already, as
    /// the menu bar tells it, from stand-in events and a stand-in
    /// microphone (never the user's calendars or calls): joined from the
    /// menu bar's Join before its start, no card On time; another app on the
    /// microphone since just before it (the menu bar off), no screens dark;
    /// a call on it since long before (the meeting before running over), or
    /// begun during the meeting before (back to back), the alert still
    /// comes, the menu bar red. A card up with the screens dark, then the menu
    /// bar's Join: the card goes, the screens come back; a card up, then the
    /// microphone taken: it goes. Join at once opens a call not joined, and
    /// neither one joined already nor one on the microphone.
    private func meetingAlertsNotWhenJoined() async {
        let name = "Meeting alerts: none for a call joined already (Join, the microphone since just before), still for the call of the meeting before "
            + "(back to back), a card up goes as it is joined (screens back); Join at once skips a call joined already"
        guard let book = context.launcher.calendar else {
            record(name, false, "no calendar", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.agendaMenuBar, preferences.agendaMenuBarCallsOnly, preferences.agendaAlerts, preferences.agendaAutoJoin,
                     preferences.agendaAlertWithoutCall)
        let watch = context.meetingWatch
        let card = context.meetingCard
        var opened: [URL] = []
        defer {
            card.dismiss()
            book.testEvents = nil
            book.openURL = { NSWorkspace.shared.open($0) }
            preferences.agendaMenuBar = saved.0
            preferences.agendaMenuBarCallsOnly = saved.1
            preferences.agendaAlerts = saved.2
            preferences.agendaAutoJoin = saved.3
            preferences.agendaAlertWithoutCall = saved.4
            watch.microphone.standIn = nil
            watch.resetForTest()
            watch.refresh()
        }
        book.openURL = { opened.append($0) }
        preferences.agendaMenuBar = .tenBefore
        preferences.agendaMenuBarCallsOnly = true
        preferences.agendaAlertWithoutCall = false
        preferences.agendaAutoJoin = .off
        var details: [String] = []
        var passed = true
        func check(_ label: String, _ ok: Bool) {
            passed = passed && ok
            details.append("\(label): \(ok)")
        }
        /// A call starting in `seconds`, alone (or after `before`), `alerts`
        /// set, the microphone as said; nothing alerted, joined or opened
        /// before. The events first: no refresh below sees the last check's
        /// again.
        func meeting(_ id: String, in seconds: TimeInterval, alerts: [MeetingAlert], microphone: MeetingBar.Presence.Microphone,
                     before: AgendaEvent? = nil) {
            let start = Date.now.addingTimeInterval(seconds)
            book.testEvents = [before, AgendaEvent(id: id, title: "Weekly sync", start: start, end: start.addingTimeInterval(30 * 60), calendar: "Work",
                                                   notes: "https://meet.google.com/abc-defg-hij")].compactMap { $0 }
            card.dismiss()
            watch.resetForTest()
            opened = []
            preferences.agendaAlerts = alerts
            watch.microphone.standIn = microphone
            watch.refresh()
        }
        /// The menu bar's Join, as clicked.
        func joinFromMenuBar() -> Bool {
            guard let menu = watch.itemMenu, let join = menu.items.firstIndex(where: { $0.title == "Join Google Meet" }) else { return false }
            menu.performActionForItem(at: join)
            return true
        }
        func calls() -> Int { opened.filter { $0.absoluteString.contains("meet.google.com") }.count }

        // Joined from the menu bar's Join before its start: no card On time.
        meeting("st-in-joined", in: 3, alerts: [MeetingAlert(minutes: 0, style: .card)], microphone: .idle)
        let joinedEarly = joinFromMenuBar() && calls() == 1
        let quietJoined = await waitUntil(timeout: 5) { card.isVisible } == nil
        check("joined from the menu bar before it, no card On time", joinedEarly && quietJoined)

        // Another app on the microphone since just before it, the menu bar
        // off: no screens dark.
        preferences.agendaMenuBar = .never
        meeting("st-in-microphone", in: 3, alerts: [MeetingAlert(minutes: 0, style: .dark)], microphone: .inUse(since: Date.now))
        let quietMicrophone = await waitUntil(timeout: 5) { card.isVisible || card.screensDark } == nil
        check("on the microphone since just before, the menu bar off, no screens dark", quietMicrophone)
        preferences.agendaMenuBar = .tenBefore

        // A call on the microphone since long before (the meeting before,
        // running over): the alert still comes.
        meeting("st-in-before", in: 3, alerts: [MeetingAlert(minutes: 0, style: .card)], microphone: .inUse(since: Date.now.addingTimeInterval(-40 * 60)))
        let stillAlerted = await waitUntil(timeout: 6) { card.isVisible && card.shownEyebrow == "STARTING NOW" } != nil
        check("a call on the microphone from before, the alert comes", stillAlerted)

        // Back to back: the meeting before's call, begun on the microphone
        // during it and in this one's 10 minutes (joined late), is that
        // one's: the alert still comes, and the menu bar is red.
        let previous = AgendaEvent(id: "st-in-previous", title: "Design review", start: Date.now.addingTimeInterval(-5 * 60), end: Date.now.addingTimeInterval(3),
                                   calendar: "Work", notes: "https://meet.google.com/bef-oreb-efo")
        meeting("st-in-next", in: 3, alerts: [MeetingAlert(minutes: 0, style: .card)], microphone: .inUse(since: Date.now.addingTimeInterval(-2 * 60)),
                before: previous)
        let backToBack = await waitUntil(timeout: 6) { card.isVisible && card.shownTitle == "Weekly sync" && card.shownEyebrow == "STARTING NOW" } != nil
        await pause(300)
        let backToBackRed = watch.shownTitle?.contains("Weekly sync") == true && watch.shownUrgent
        check("back to back, the call of the meeting before, the alert comes \(backToBack), the menu bar red \(backToBackRed)", backToBack && backToBackRed)

        // A card up, the screens dark, 5 min before: the menu bar's Join
        // takes it away, the screens come back.
        meeting("st-in-dark", in: 5 * 60 + 2, alerts: [MeetingAlert(minutes: 5, style: .dark)], microphone: .idle)
        let darkUp = await waitUntil(timeout: 6) { card.isVisible && card.screensDark } != nil
        let joinedDark = joinFromMenuBar()
        let darkGone = await waitUntil(timeout: 2) { !card.isVisible && !card.screensDark } != nil
        check("screens dark, then the menu bar's Join, gone and the screens back", darkUp && joinedDark && darkGone && calls() == 1)

        // A card up, then another app takes the microphone (the call joined
        // from its own app): it goes.
        meeting("st-in-card", in: 2 * 60 + 2, alerts: [MeetingAlert(minutes: 2, style: .card)], microphone: .idle)
        let cardUp = await waitUntil(timeout: 6) { card.isVisible } != nil
        watch.microphone.standIn = .inUse(since: Date.now)
        let cardGone = await waitUntil(timeout: 2) { !card.isVisible } != nil
        check("a card, then the microphone taken, gone", cardUp && cardGone)

        // Join at once: a call not joined opens as it starts; one joined
        // from the menu bar before, or on the microphone since just before,
        // does not open again.
        preferences.agendaAutoJoin = .join
        meeting("st-in-auto", in: 2, alerts: [], microphone: .idle)
        let autoJoined = await waitUntil(timeout: 5) { calls() == 1 } != nil
        meeting("st-in-auto-joined", in: 3, alerts: [], microphone: .idle)
        let joinedBefore = joinFromMenuBar()
        await pause(5000)
        let notAgain = joinedBefore && calls() == 1
        meeting("st-in-auto-microphone", in: 2, alerts: [], microphone: .inUse(since: Date.now))
        await pause(4000)
        let notOnMicrophone = calls() == 0
        preferences.agendaAutoJoin = .off
        check("Join at once opens a call not joined \(autoJoined), not one joined from the menu bar \(notAgain), not one on the microphone \(notOnMicrophone)",
              autoJoined && notAgain && notOnMicrophone)

        record(name, passed, details.joined(separator: "; "), nil)
    }

    /// The meeting card's Check Camera & Mic: offered for a call (⇥),
    /// opened with the devices this Mac has (the mini has no camera: the
    /// line says so), closed again with ⇥, gone with the card; the layout
    /// with a camera drawn on a still image, light and dark.
    private func meetingCardChecksCameraAndMic() async {
        let name = "Meeting card: Check Camera & Mic offered for a call (⇥), the devices said in one line, ⇥ closes it, stopped with the card; captured with a still image"
        let card = context.meetingCard
        defer { card.dismiss() }
        let start = Date.now.addingTimeInterval(4 * 60 + 30)
        let people = ["Paul Martin", "Anna Lefèvre", "Claire Dubois", "Marc Petit"].map { AgendaEvent.Attendee(name: $0, email: nil) }
        let event = AgendaEvent(id: "st-check", title: "Weekly design review", start: start, end: start.addingTimeInterval(1800), calendar: "Work",
                                notes: "https://meet.google.com/abc-defg-hij", attendees: people)
        await pause(1100)
        card.show(event, dark: false)
        let offered = await waitUntil(timeout: 2) { card.isVisible && card.offersCheck } != nil
        let closedHeight = card.window?.frame.height ?? 0
        let top = card.window?.frame.maxY ?? 0
        await pause(1100)
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let opened = await waitUntil(timeout: 4) { card.isChecking } != nil
        await pause(500)
        let line = card.checkLine
        let grew = (card.window?.frame.height ?? 0) > closedHeight
        let topKept = abs((card.window?.frame.maxY ?? 0) - top) < 1
        if let directory = context.snapshotDirectory, let window = card.window,
           let image = await GlassCheck.screenshot(around: window, padding: 0),
           let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
            try? png.write(to: directory.appendingPathComponent("meeting-card-check-live.png"))
        }
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let closed = await waitUntil(timeout: 2) { !card.isChecking } != nil
        let backHeight = abs((card.window?.frame.height ?? 0) - closedHeight) < 1

        // The layout with a camera: a still image in the box (macOS's own
        // landscape when there is one), light and dark.
        let pictures = ["Big Sur Coastline", "Big Sur Aerial", "Catalina Coast", "Sonoma Horizon"]
            .flatMap { ["/System/Library/Desktop Pictures/\($0).heic", "/System/Library/Desktop Pictures/.thumbnails/\($0).heic"] }
        let still = pictures.lazy.compactMap { NSImage(contentsOfFile: $0) }.first ?? NSImage(size: NSSize(width: 16, height: 9), flipped: false) { rect in
            NSColor.systemTeal.setFill()
            rect.fill()
            return true
        }
        for dark in [false, true] {
            card.dismiss()
            NSApp.appearance = NSAppearance(named: dark ? .darkAqua : .aqua)
            // The panel fades out, then in: captured once it is all there.
            await pause(700)
            card.show(event, dark: false)
            await pause(400)
            card.showSampleCheck(image: still)
            await pause(1000)
            if let directory = context.snapshotDirectory, let window = card.window,
               let image = await GlassCheck.screenshot(around: window, padding: 0),
               let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("meeting-card-check-\(dark ? "dark" : "light").png"))
            }
        }
        NSApp.appearance = nil
        card.dismiss()
        let stopped = !card.isChecking
        record(name, offered && opened && grew && topKept && closed && backHeight && stopped,
               "offered: \(offered); ⇥ opened: \(opened) (“\(line)”), grew down, top kept: \(grew) \(topKept); ⇥ closed: \(closed), height back: \(backHeight); stopped with the card: \(stopped)", nil)
    }

    private func meetingInMenuBarAndOffered() async {
        let name = "Agenda: next meeting in the menu bar, one timer for its next minute, the card offers to join as it starts; gone 10 min after; "
            + "counts down to its end (timer each minute), the next one beside it, short; an event without a call announced only when asked"
        guard let book = context.launcher.calendar else {
            record(name, false, "no calendar", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.agendaMenuBar, preferences.agendaMenuBarCallsOnly, preferences.agendaHideAfter, preferences.agendaAutoJoin,
                     preferences.agendaCountdown, preferences.agendaNextDuringMeeting, preferences.agendaAlertWithoutCall, preferences.agendaAlerts)
        let watch = context.meetingWatch
        let card = context.meetingCard
        defer {
            book.testEvents = nil
            preferences.agendaMenuBar = saved.0
            preferences.agendaMenuBarCallsOnly = saved.1
            preferences.agendaHideAfter = saved.2
            preferences.agendaAutoJoin = saved.3
            preferences.agendaCountdown = saved.4
            preferences.agendaNextDuringMeeting = saved.5
            preferences.agendaAlertWithoutCall = saved.6
            preferences.agendaAlerts = saved.7
            card.dismiss()
            watch.microphone.standIn = nil
            watch.resetForTest()
            watch.refresh()
        }
        watch.resetForTest()
        // No call on this Mac (a stand-in, whatever its microphone does).
        watch.microphone.standIn = .idle
        let now = Date.now
        let soon = AgendaEvent(id: "st-soon", title: "Weekly sync", start: now.addingTimeInterval(5 * 60), end: now.addingTimeInterval(35 * 60),
                               notes: "https://meet.google.com/abc-defg-hij")
        book.testEvents = [soon]
        preferences.agendaMenuBar = .tenBefore
        preferences.agendaMenuBarCallsOnly = true
        preferences.agendaHideAfter = 10
        preferences.agendaAutoJoin = .off
        preferences.agendaAlerts = [MeetingAlert(minutes: 0, style: .card)]
        preferences.agendaCountdown = false
        preferences.agendaNextDuringMeeting = false
        preferences.agendaAlertWithoutCall = false
        watch.refresh()
        let inMenuBar = watch.shownTitle?.contains("Weekly sync") == true
        // "in 5 min" goes down each minute: the one timer at the next one.
        let timerAtStart = watch.nextChange.map { abs($0.timeIntervalSince(soon.start.addingTimeInterval(-4 * 60))) < 1 } ?? false

        // Starting in two seconds: the card offers it by itself.
        let starting = AgendaEvent(id: "st-starting", title: "Standup", start: Date.now.addingTimeInterval(2), end: Date.now.addingTimeInterval(15 * 60),
                                   notes: "https://meet.google.com/xyz-abcd-efg")
        book.testEvents = [starting, soon]
        watch.refresh()
        let offered = await waitUntil(timeout: 5) {
            card.isVisible && card.shownEyebrow == "STARTING NOW" && card.shownTitle == "Standup" && card.shownAction == "Join"
        } != nil
        let nowInMenuBar = watch.shownTitle?.contains("Standup · starting now") == true && watch.shownUrgent
        card.dismiss()

        // Without a call: nothing by default; announced (no Join) when asked,
        // even with "Join at once".
        let lunch = AgendaEvent(id: "st-lunch", title: "Lunch with Paul", start: Date.now.addingTimeInterval(2), end: Date.now.addingTimeInterval(60 * 60),
                                location: "Le Comptoir")
        book.testEvents = [lunch]
        watch.refresh()
        card.dismiss()
        let quietWithout = await waitUntil(timeout: 3.5) { card.isVisible } == nil
        // The settings change refreshes the watch: the lunch gone first.
        let dinner = AgendaEvent(id: "st-dinner", title: "Dinner with Anna", start: Date.now.addingTimeInterval(2), end: Date.now.addingTimeInterval(60 * 60))
        book.testEvents = [dinner]
        watch.resetForTest()
        preferences.agendaAlertWithoutCall = true
        preferences.agendaAutoJoin = .join
        watch.refresh()
        let announced = await waitUntil(timeout: 5) {
            card.isVisible && card.shownEyebrow == "STARTING NOW" && card.shownTitle == "Dinner with Anna" && card.shownAction == "Got It"
        } != nil
        let announcedCard = "\(card.isVisible) “\(card.shownEyebrow)” “\(card.shownTitle)” \(card.shownAction)"
        card.dismiss()
        preferences.agendaAutoJoin = .off

        // Started 15 minutes ago: left the menu bar after 10.
        let old = AgendaEvent(id: "st-old", title: "Old call", start: Date.now.addingTimeInterval(-15 * 60), end: Date.now.addingTimeInterval(15 * 60),
                              notes: "https://meet.google.com/old-call-xyz")
        book.testEvents = [old]
        watch.refresh()
        let gone = watch.shownTitle == nil

        // Counting down: on until its end, the time left, a timer each minute.
        preferences.agendaAutoJoin = .off
        preferences.agendaCountdown = true
        let reference = Date.now
        let deep = AgendaEvent(id: "st-deep", title: "Deep work review", start: reference.addingTimeInterval(-15 * 60),
                               end: reference.addingTimeInterval(25 * 60 - 20), notes: "https://meet.google.com/dee-pwor-kre")
        book.testEvents = [deep]
        watch.refresh(now: reference)
        let counting = watch.shownTitle == " Deep work review · 25 min left"
        let minuteTimer = watch.nextChange.map { abs($0.timeIntervalSince(deep.end.addingTimeInterval(-24 * 60))) < 1 } ?? false
        // The next one beside it once that close (10 min before), short.
        preferences.agendaNextDuringMeeting = true
        let standup = AgendaEvent(id: "st-next", title: "Standup", start: reference.addingTimeInterval(8 * 60), end: reference.addingTimeInterval(23 * 60),
                                  notes: "https://meet.google.com/sta-ndup-xyz")
        book.testEvents = [deep, standup]
        watch.refresh(now: reference)
        let at = DateFormatter.localizedString(from: standup.start, dateStyle: .none, timeStyle: .short)
        let both = watch.shownTitle == " 25 min left · then Standup \(at)"
        let menu = watch.shownMenu
        let nextInMenu = menu.contains("Next: Standup · \(at)") && menu.filter { $0 == "Join Google Meet" }.count == 2
        preferences.agendaNextDuringMeeting = false
        watch.refresh(now: reference)
        let alone = watch.shownTitle == " Deep work review · 25 min left"
        if let directory = context.snapshotDirectory {
            // The alert's preview shows (an alert On time is set), events
            // without a call too.
            preferences.agendaAutoJoin = .off
            preferences.agendaAlertWithoutCall = true
            context.settings.show(pane: .calendar)
            await pause(500)
            if let png = await context.settings.snapshotPNG() { try? png.write(to: directory.appendingPathComponent("settings-agenda.png")) }
            await closeSettings()
        }
        record(name, inMenuBar && timerAtStart && offered && nowInMenuBar && quietWithout && announced && gone && counting && minuteTimer && both && nextInMenu && alone,
               "in the menu bar: \(inMenuBar) (“\(watch.shownTitle ?? "")”), timer at its next minute: \(timerAtStart); offered as it starts: \(offered), menu bar “starting now”, red: \(nowInMenuBar); "
                   + "without a call: quiet by default \(quietWithout), announced when asked \(announced) (\(announcedCard)); gone after 10 min: \(gone); "
                   + "countdown: \(counting), timer at the next minute: \(minuteTimer); with the next: \(both), its menu: \(nextInMenu) (\(menu)); next off: \(alone)",
               nil)
    }

    /// The meeting in the menu bar at each of its moments, from stand-in
    /// events and a stand-in microphone (never the user's calendars): coming
    /// (a calendar, "in 10 min"), an hour away ("at 15:30"), started and not
    /// joined (the camera in red, "started 3 min ago", a timer at the next
    /// minute), on a Mac without a microphone (the camera, not red), joined
    /// from its menu's Join (the ring, "27 min left"), joined by a call begun
    /// on this Mac and kept when the microphone stops, a call begun long
    /// before (the meeting before running over: red), the next one beside
    /// it ("6 min left · then Standup 14:30"), without the countdown ("now").
    /// Each captured where this Mac's menu bar shows it, and alone over a
    /// light and a dark menu bar. What the real microphone reads is said.
    private func meetingBarStates() async {
        let name = "Meeting in the menu bar: coming (calendar, in N min / at a time), started and not joined (red camera, each minute), "
            + "no microphone (not red), joined from its Join or by a call (ring, N min left; kept), a call from before (red), "
            + "the next beside it (… left · then …), without the countdown (now); captured light and dark"
        guard let book = context.launcher.calendar else {
            record(name, false, "no calendar", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.agendaMenuBar, preferences.agendaMenuBarCallsOnly, preferences.agendaHideAfter, preferences.agendaAutoJoin,
                     preferences.agendaCountdown, preferences.agendaNextDuringMeeting, preferences.agendaAlerts)
        let watch = context.meetingWatch
        var opened: [URL] = []
        defer {
            book.testEvents = nil
            book.openURL = { NSWorkspace.shared.open($0) }
            preferences.agendaMenuBar = saved.0
            preferences.agendaMenuBarCallsOnly = saved.1
            preferences.agendaHideAfter = saved.2
            preferences.agendaAutoJoin = saved.3
            preferences.agendaCountdown = saved.4
            preferences.agendaNextDuringMeeting = saved.5
            preferences.agendaAlerts = saved.6
            watch.microphone.standIn = nil
            watch.resetForTest()
            watch.refresh()
        }
        // What this Mac's microphone says, read for real (CoreAudio).
        let real = MicrophoneUse.read()
        let realSaid = !real.hasInput ? "no microphone: cannot tell" : real.inUse == nil ? "CoreAudio could not say"
            : real.inUse == true ? "another app on the microphone" : "no app on the microphone"
        book.openURL = { opened.append($0) }
        preferences.agendaMenuBar = .tenBefore
        preferences.agendaMenuBarCallsOnly = true
        preferences.agendaHideAfter = 10
        preferences.agendaAutoJoin = .off
        preferences.agendaAlerts = []
        preferences.agendaCountdown = true
        preferences.agendaNextDuringMeeting = true
        watch.resetForTest()

        var details: [String] = []
        var passed = true
        /// A call starting `minutes` from now (negative: started), 30 min long.
        func call(_ id: String, _ title: String, in minutes: Double, length: Double = 30) -> AgendaEvent {
            let start = Date.now.addingTimeInterval(minutes * 60)
            return AgendaEvent(id: id, title: title, start: start, end: start.addingTimeInterval(length * 60), calendar: "Work",
                               notes: "https://meet.google.com/abc-defg-hij")
        }
        func show(_ label: String, _ events: [AgendaEvent], microphone: MeetingBar.Presence.Microphone, expect title: String, red: Bool,
                  capture: String?) async {
            book.testEvents = events
            watch.microphone.standIn = microphone
            watch.refresh()
            await pause(300)
            let ok = watch.shownTitle == title && watch.shownUrgent == red
            passed = passed && ok
            details.append("\(label): “\(watch.shownTitle ?? "nothing")”\(watch.shownUrgent ? " red" : "")\(ok ? "" : " ✗ (expected “\(title)”\(red ? " red" : ""))")")
            if let capture { await captureMeetingItem(capture) }
        }

        // Coming: a calendar, the minutes; an hour away, its time.
        await show("coming", [call("st-bar-soon", "Weekly sync", in: 9.5)], microphone: .idle, expect: " Weekly sync · in 10 min", red: false,
                   capture: "meetingbar-coming")
        preferences.agendaMenuBar = .always
        let far = call("st-bar-far", "Weekly sync", in: 95)
        await show("an hour away", [far], microphone: .idle, expect: " Weekly sync · at \(MeetingBar.clock(far.start))", red: false, capture: nil)
        preferences.agendaMenuBar = .tenBefore

        // Started, not joined: red, the minutes since, a timer at the next one.
        let late = call("st-bar-late", "Weekly sync", in: -3.5)
        await show("started, not joined", [late], microphone: .idle, expect: " Weekly sync · started 3 min ago", red: true, capture: "meetingbar-late")
        let minuteTimer = watch.nextChange.map { abs($0.timeIntervalSince(late.start.addingTimeInterval(4 * 60))) < 1 } ?? false
        let lateHelp = watch.shownHelp?.contains("you have not joined it from this Mac") == true
        passed = passed && minuteTimer && lateHelp
        details.append("its timer at the next minute: \(minuteTimer), help: \(lateHelp)")

        // A Mac without a microphone cannot tell: said, not red.
        await show("no microphone", [late], microphone: .unknown, expect: " Weekly sync · started 3 min ago", red: false,
                   capture: "meetingbar-started-unknown")
        let unknownHelp = watch.shownHelp?.contains("cannot tell") == true
        passed = passed && unknownHelp

        // Joined from its menu: the ring and the time left, at once.
        await show("before Join", [late], microphone: .idle, expect: " Weekly sync · started 3 min ago", red: true, capture: nil)
        if let menu = watch.itemMenu, let join = menu.items.firstIndex(where: { $0.title == "Join Google Meet" }) {
            menu.performActionForItem(at: join)
        }
        let joinedAtOnce = await waitUntil(timeout: 2) { watch.shownTitle == " Weekly sync · 27 min left" && !watch.shownUrgent } != nil
        let joinOpened = opened.contains { $0.absoluteString.contains("meet.google.com") }
        passed = passed && joinedAtOnce && joinOpened
        details.append("Join from its menu: “\(watch.shownTitle ?? "nothing")” \(joinedAtOnce), the call opened \(joinOpened)")
        // The item narrows: captured once the menu bar has moved it.
        await pause(400)
        await captureMeetingItem("meetingbar-on")

        // Joined by a call begun on this Mac around its start, kept when the
        // microphone stops a moment; a call begun long before is another
        // one (red).
        let review = call("st-bar-review", "Design review", in: -2.5)
        await show("a call begun as it started", [review], microphone: .inUse(since: Date.now.addingTimeInterval(-90)),
                   expect: " Design review · 28 min left", red: false, capture: nil)
        await show("the microphone stopped", [review], microphone: .idle, expect: " Design review · 28 min left", red: false, capture: nil)
        await show("a call from before", [call("st-bar-other", "Design review", in: -2.5)], microphone: .inUse(since: Date.now.addingTimeInterval(-40 * 60)),
                   expect: " Design review · started 2 min ago", red: true, capture: nil)

        // The next one beside the time left: "then", its time.
        let current = call("st-bar-current", "Weekly sync", in: -24.5)
        let next = AgendaEvent(id: "st-bar-next", title: "Standup", start: current.end, end: current.end.addingTimeInterval(15 * 60),
                               calendar: "Work", notes: "https://meet.google.com/xyz-abcd-efg")
        await show("the next beside it", [current, next], microphone: .inUse(since: current.start.addingTimeInterval(30)),
                   expect: " 6 min left · then Standup \(MeetingBar.clock(next.start))", red: false, capture: "meetingbar-next")

        // Without the countdown, joined: now.
        preferences.agendaCountdown = false
        let quiet = call("st-bar-quiet", "Weekly sync", in: -3.5)
        await show("without the countdown", [quiet], microphone: .inUse(since: quiet.start), expect: " Weekly sync · now", red: false, capture: nil)
        preferences.agendaCountdown = true

        // The calls near now started the real watch (CoreAudio's listeners
        // on their queue, the reading back on the main actor).
        let delivered = await waitUntil(timeout: 2) { watch.microphone.reading.inUse != nil || !watch.microphone.reading.hasInput } != nil
        let listening = watch.microphone.isStarted && delivered
        passed = passed && listening
        record(name, passed, "this Mac's microphone: \(realSaid); watched around a call's start: \(listening); " + details.joined(separator: "; "), nil)
    }

    /// The meeting's menu bar item: where this Mac's menu bar shows it (a
    /// slice of the display the size of the item: Screen Recording), and
    /// its own window alone over a light and a dark menu bar, its
    /// appearance set to each. Only skil.li's item.
    private func captureMeetingItem(_ file: String) async {
        guard let button = context.meetingWatch.itemButton else { return }
        await captureStatusItem(button, file)
    }

    /// A menu bar item as the menu bar shows it, then drawn alone over a
    /// light and a dark menu bar.
    private func captureStatusItem(_ button: NSStatusBarButton, _ file: String) async {
        guard let directory = context.snapshotDirectory, let window = button.window,
              let screen = window.screen ?? NSScreen.main else { return }
        let scale = screen.backingScaleFactor
        func bar(_ name: String) async {
            guard let content = try? await SCShareableContent.current,
                  let display = content.displays.first(where: { $0.displayID == (screen.deviceDescription[NSDeviceDescriptionKey("NSScreenNumber")] as? CGDirectDisplayID) })
            else { return }
            let filter = SCContentFilter(display: display, excludingWindows: [])
            let configuration = SCStreamConfiguration()
            let frame = window.frame
            let rect = CGRect(x: frame.minX - screen.frame.minX, y: screen.frame.maxY - frame.maxY, width: frame.width, height: frame.height)
            configuration.sourceRect = rect
            configuration.width = Int(rect.width * scale)
            configuration.height = Int(rect.height * scale)
            configuration.showsCursor = false
            if let image = try? await SCScreenshotManager.captureImage(contentFilter: filter, configuration: configuration),
               let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("\(name).png"))
            }
        }
        await bar(file)
        // In each appearance: on this Mac's menu bar (the item's appearance
        // set), and drawn alone over a light and a dark menu bar (its window
        // is the menu bar's, out of a window capture's reach).
        for (suffix, appearance) in GlassCheck.appearances {
            button.appearance = appearance
            button.needsDisplay = true
            await pause(200)
            await bar("\(file)-bar-\(suffix)")
            let bounds = button.bounds
            guard let drawn = button.bitmapImageRepForCachingDisplay(in: bounds) else { continue }
            button.cacheDisplay(in: bounds, to: drawn)
            let item = NSImage(size: bounds.size)
            item.addRepresentation(drawn)
            let size = NSSize(width: bounds.width + 24, height: max(bounds.height, 24) + 8)
            guard let sheet = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: Int(size.width * scale), pixelsHigh: Int(size.height * scale),
                                               bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB,
                                               bytesPerRow: 0, bitsPerPixel: 0) else { continue }
            sheet.size = size
            NSGraphicsContext.saveGraphicsState()
            NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: sheet)
            (suffix == "dark" ? NSColor(white: 0.15, alpha: 1) : NSColor(white: 0.93, alpha: 1)).setFill()
            NSRect(origin: .zero, size: size).fill()
            item.draw(in: NSRect(x: 12, y: (size.height - bounds.height) / 2, width: bounds.width, height: bounds.height))
            NSGraphicsContext.restoreGraphicsState()
            if let data = sheet.representation(using: .png, properties: [:]) {
                try? data.write(to: directory.appendingPathComponent("\(file)-\(suffix).png"))
            }
        }
        button.appearance = nil
    }

    /// Settings → Calendar: the menu bar's preview at each moment (drawn by
    /// `MeetingWatch.appearance` itself), light and dark, with the
    /// countdown and without.
    private func meetingBarPreviewInSettings() async {
        let name = "Settings → Calendar: the menu bar's preview shows each moment (coming, started and not joined in red, joined, the next), light and dark"
        let preferences = context.preferences
        let saved = (preferences.agendaMenuBar, preferences.agendaCountdown, preferences.agendaNextDuringMeeting, preferences.agendaMenuBarCallsOnly,
                     preferences.agendaHideAfter)
        defer {
            preferences.agendaMenuBar = saved.0
            preferences.agendaCountdown = saved.1
            preferences.agendaNextDuringMeeting = saved.2
            preferences.agendaMenuBarCallsOnly = saved.3
            preferences.agendaHideAfter = saved.4
        }
        preferences.agendaMenuBar = .tenBefore
        preferences.agendaMenuBarCallsOnly = true
        preferences.agendaCountdown = true
        preferences.agendaNextDuringMeeting = true
        preferences.agendaHideAfter = 10
        context.settings.show(pane: .calendar)
        await pause(600)
        let texts = Self.axElements(roles: [kAXStaticTextRole], where: { _ in true }).compactMap(Self.axTitle)
        await captureSettingsBothWays(as: "settings-calendar-menubar")
        preferences.agendaCountdown = false
        await pause(300)
        await captureSettingsBothWays(as: "settings-calendar-menubar-no-countdown")
        await closeSettings()
        let moments = ["10 min before", "Started, not joined", "Joined", "6 min before the next"]
        let shown = moments.filter { moment in texts.contains { $0.contains(moment) } }
        record(name, context.snapshotDirectory == nil || shown.count == moments.count || texts.isEmpty,
               "moments read in the pane: \(shown)\(texts.isEmpty ? " (its text not readable: captures only)" : "")", nil)
    }

    /// "Do it here" in another app, for real: `Skilli testform` (a second
    /// process with an AppKit form) in front, the user's decision key. A
    /// French goal fills both fields from its quotes, ticks the box and
    /// saves; "supprime le compte" asks first, and Stop leaves it; "Archive",
    /// which only the screen shows, is read and clicked with the mouse (with
    /// Screen Recording).
    private func controlDoesItInAnotherApp() async {
        let name = "Do it here: a French goal fills a form in another app (quotes), ticks, saves; delete asked first; a drawn button read on screen and clicked"
        // The user's own decision keys, as the live decision checks use them.
        var keys: [DecisionProvider: String] = [:]
        for provider in DecisionProvider.allCases { keys[provider] = Keychain.read(account: provider.keychainAccount) }
        guard !keys.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no decision key saved in Settings", latencyMs: nil))
            return
        }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-testform-\(UUID().uuidString)")
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let stateFile = folder.appendingPathComponent("state.json")
        let process = Process()
        process.executableURL = Bundle.main.executableURL
        process.arguments = ["testform", stateFile.path]
        defer {
            process.terminate()
            try? FileManager.default.removeItem(at: folder)
        }
        do { try process.run() } catch {
            record(name, false, "the form did not start: \(error.localizedDescription)", nil)
            return
        }
        func state() -> [String: Any] {
            (try? Data(contentsOf: stateFile)).flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Any] } ?? [:]
        }
        let pid = process.processIdentifier
        guard await waitUntil(timeout: 5, { state()["pid"] as? Int == Int(pid) }) != nil else {
            record(name, false, "the form did not show", nil)
            return
        }
        func bringForward() async -> Bool {
            await waitUntil(timeout: 3) {
                Self.makeFrontmost(pid: pid)
                return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid
            } != nil
        }
        guard await bringForward() else {
            record(name, false, "the form did not come forward", nil)
            return
        }
        var confirmations: [String] = []
        var choices: [String] = []
        func control() -> ComputerControl {
            let control = ComputerControl(keys: keys, selection: context.selection)
            control.confirm = { question in
                confirmations.append(question)
                return false
            }
            control.choose = { question, options in
                choices.append("\(question) \(options)")
                return 0
            }
            control.askText = { _ in nil }
            return control
        }

        let fill = control()
        let start = ContinuousClock.now
        let filled = await fill.run(goal: "Mets « Jean Dupont » dans le nom et « jean@example.com » dans l'email, coche l'abonnement à la newsletter puis enregistre",
                                    pid: pid)
        let fillTime = ContinuousClock.now - start
        _ = await waitUntil(timeout: 1) { (state()["saved"] as? Int ?? 0) >= 1 }
        let form = state()
        let formRight = form["name"] as? String == "Jean Dupont" && form["email"] as? String == "jean@example.com"
            && form["subscribe"] as? Bool == true && (form["saved"] as? Int ?? 0) >= 1 && form["deleted"] as? Int == 0
        let fillDone = filled == .done && formRight

        // Through Ask, as the user does it: routed by the decision model,
        // done in the form; the card goes once done (nothing said).
        _ = await bringForward()
        context.aiActions.decisionKeysOverride = keys
        let popover = context.aiActions.popover
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "décoche la case newsletter"])
        let viaAsk = await waitUntil(timeout: 12) {
            state()["subscribe"] as? Bool == false && !popover.isVisible
        } != nil
        let askCard = "\(popover.shownStatus) — \(popover.shownText.prefix(120)); route \(context.aiActions.lastControl?.history ?? [])"
        context.aiActions.decisionKeysOverride = nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        // A form from a card, through Ask: the user's own ("mes infos"),
        // then Margot's ("pour Margot"); no value ever sent to the model.
        var cardFill = "no contacts book"
        var cardsOK = false
        if let book = context.aiActions.contacts {
            var me = ContactRecord(id: "st-me")
            me.givenName = "Jean"
            me.familyName = "Dupont"
            me.emails = [.init("home", "jean.card@example.com")]
            var margot = ContactRecord(id: "st-margot")
            margot.givenName = "Margot"
            margot.familyName = "Martin"
            margot.emails = [.init("home", "margot@example.com")]
            book.testRecords = [me, margot]
            book.testMeID = me.id
            // Fields kept in skil.li: mine (a SIRET, a sensitive IBAN in the
            // self-test's Keychain items), Margot's SIRET.
            let savedProfiles = context.preferences.formProfiles
            // Two sensitive ones, typed together: asked once.
            let siret = FormExtra(label: "SIRET", isSensitive: true)
            let iban = FormExtra(label: "IBAN", isSensitive: true)
            let margotSiret = FormExtra(label: "SIRET", isSensitive: false, value: "987 654 321 00098")
            context.preferences.formProfiles = FormProfiles(mine: [siret, iban], others: [FormPerson(name: "Margot Martin", extras: [margotSiret])])
            FormSecrets.save("FR76 3000 6000 0112 3456 7890 189", for: iban)
            FormSecrets.save("123 456 789 00012", for: siret)
            context.aiActions.decisionKeysOverride = keys
            var asked: [String] = []
            func fill(_ request: String, expected: [String: String]) async -> (Bool, [String]) {
                _ = await bringForward()
                context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": request])
                let done = await waitUntil(timeout: 40) {
                    // A sensitive value waits for ↩ in the card: the user says yes.
                    if let question = popover.shownQuestion?.text, question.hasPrefix("Type"), !asked.contains(question) {
                        asked.append(question)
                        Task { await self.pressKey(nil, code: CGKeyCode(kVK_Return)) }
                        return false
                    }
                    return expected.allSatisfy { state()[$0.key] as? String == $0.value } && !popover.isVisible
                } != nil
                let sent = context.aiActions.lastControl?.sentStates ?? []
                if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
                return (done, sent)
            }
            let (mine, mineSent) = await fill("remplis le formulaire avec mes infos",
                                              expected: ["name": "Jean Dupont", "email": "jean.card@example.com", "siret": "123 456 789 00012",
                                                         "iban": "FR76 3000 6000 0112 3456 7890 189"])
            let (hers, hersSent) = await fill("remplis le formulaire pour Margot",
                                              expected: ["name": "Margot Martin", "email": "margot@example.com", "siret": "987 654 321 00098"])
            // Each run's own values never in what it sent.
            let mineValues = ["jean.card@example.com", "123 456 789 00012", "FR76 3000 6000 0112 3456 7890 189"]
            let leaked = mineSent.filter { state in mineValues.contains { state.contains($0) } }.count
                + hersSent.filter { $0.contains("margot@example.com") || $0.contains("987 654 321 00098") }.count
            let ibanAsked = asked.contains { $0.contains("IBAN") } && asked.contains { $0.contains("SIRET") }
            // Filled in one go, both in one question; step by step, one each.
            let together = asked.contains { $0.contains("SIRET") && $0.contains("IBAN") }
            cardsOK = mine && hers && leaked == 0 && !mineSent.isEmpty && ibanAsked
            cardFill = "mine: \(mine), Margot's: \(hers), SIRET and IBAN asked first: \(ibanAsked) (in one question: \(together)) \(asked), states with a value: \(leaked) of \(mineSent.count + hersSent.count), form \(state())"
            book.testRecords = nil
            book.testMeID = nil
            FormSecrets.forget(iban)
            FormSecrets.forget(siret)
            context.preferences.formProfiles = savedProfiles
            context.aiActions.decisionKeysOverride = nil
        }

        // Deleting the account: asked first; Stop leaves it.
        _ = await bringForward()
        let delete = control()
        let deleted = await delete.run(goal: "supprime le compte", pid: pid)
        let askedFirst = confirmations.contains { $0.contains("Delete Account") } && state()["deleted"] as? Int == 0
            && { if case .stopped = deleted { true } else { false } }()

        // A button only the screen shows: read there, clicked with the mouse.
        var archived = false
        let screen = ScreenSight.isAllowed
        if screen {
            _ = await bringForward()
            let archive = control()
            let outcome = await archive.run(goal: "clique sur Archive", pid: pid)
            archived = await waitUntil(timeout: 1) { state()["archived"] as? Int == 1 } != nil && outcome == .done
        }
        record(name, fillDone && viaAsk && cardsOK && askedFirst && (archived || !screen),
               "fill: \(filled) in \(fillTime.compact) (\(fill.decider)), steps \(fill.history), pictures \(fill.pictures.map(\.need.rawValue)), form \(form); via Ask: \(viaAsk) (\(askCard)); cards: \(cardFill); "
                   + "delete: \(deleted), confirmations \(confirmations); archive: \(screen ? "\(archived)" : "no Screen Recording, not tried"); choices \(choices)",
               Double(fillTime.components.seconds * 1_000))
    }

    // MARK: - Do it here, seeing the window

    /// One goal run by "do it here": in words only (before), with the
    /// window's picture (after), or with its items without words outlined
    /// with their id (measured, off); what changed, what was asked, what
    /// it cost.
    private struct VisionRun: Codable {
        let app: String
        let goal: String
        /// "words", "picture" (as shipped) or "outlined" (items without
        /// words outlined with their id in it).
        let mode: String
        let outcome: String
        /// The goal's item pressed, and nothing else.
        let right: Bool
        /// Something else pressed.
        let wrong: Bool
        /// "Which one?" asked on the way (the user picks the right one
        /// when it is offered).
        let whichAsked: Int
        let asked: [String]
        let steps: [String]
        /// Each decision: [1 with a picture else 0, input tokens, ms].
        let decisions: [[Int]]
        /// Each picture: "wordless 1024×914 56 KB 6 outlined, 4,136 tokens, 275 ms, made in 41 ms".
        let pictures: [String]
    }

    private func visionRun(app: String, goal: String, expected: String, mode: String, pid: pid_t, keys: [DecisionProvider: String],
                           counts: @MainActor () -> [String: Int], names: @escaping (String) -> Bool) async -> (run: VisionRun, control: ComputerControl) {
        _ = await waitUntil(timeout: 3) {
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid
        }
        let before = counts()
        let control = ComputerControl(keys: keys, selection: context.selection)
        control.picturesAllowed = mode != "words"
        control.marksInPicture = mode == "outlined"
        var asked: [String] = []
        var which = 0
        control.confirm = { question in
            asked.append(question)
            return false
        }
        // Unsure, "Which one?": the user picks the goal's item when it is
        // offered, else cancels.
        control.choose = { question, options in
            asked.append("\(question) \(options)")
            which += 1
            return options.firstIndex(where: names)
        }
        control.askText = { _ in nil }
        let outcome = await control.run(goal: goal, pid: pid)
        _ = await waitUntil(timeout: 1) { counts() != before }
        let after = counts()
        let changed = Set(after.keys.filter { after[$0] != before[$0] })
        let run = VisionRun(app: app, goal: goal, mode: mode, outcome: "\(outcome)", right: changed == [expected],
                            wrong: !changed.subtracting([expected]).isEmpty, whichAsked: which,
                            asked: asked, steps: control.history,
                            decisions: control.costs.map { [$0.picture ? 1 : 0, $0.tokens, $0.milliseconds] },
                            pictures: control.pictures.map {
                                "\($0.need.rawValue) \($0.width)×\($0.height) \($0.bytes / 1024) KB \($0.marks) outlined, \($0.tokens) tokens, \($0.milliseconds) ms, made in \($0.captureMilliseconds) ms"
                            })
        Log.actions.notice("SELFTEST vision \(app, privacy: .public) “\(goal, privacy: .public)” \(run.mode, privacy: .public): right \(run.right, privacy: .public), \(run.outcome, privacy: .public), steps \(run.steps, privacy: .public), asked \(asked, privacy: .public), changed \(changed.sorted(), privacy: .public)")
        return (run, control)
    }

    /// Per mode: right alone, right after "Which one?", wrong, tokens and
    /// time a step.
    private static func visionSummary(_ runs: [VisionRun]) -> String {
        func median(_ values: [Int]) -> Int { values.isEmpty ? 0 : values.sorted()[values.count / 2] }
        return ["words", "picture", "outlined"].compactMap { mode -> String? in
            let these = runs.filter { $0.mode == mode }
            guard !these.isEmpty else { return nil }
            let decisions = these.flatMap(\.decisions)
            let plain = decisions.filter { $0[0] == 0 }, seen = decisions.filter { $0[0] == 1 }
            let title = ["words": "before (words)", "picture": "after (picture)", "outlined": "picture with outlined ids"][mode] ?? mode
            var text = "\(title): \(these.filter { $0.right && $0.whichAsked == 0 }.count)/\(these.count) right alone"
                + ", \(these.filter { $0.right && $0.whichAsked > 0 }.count) after “Which one?”"
                + ", \(these.filter(\.wrong).count) wrong"
            if !plain.isEmpty { text += ", in words ~\(median(plain.map { $0[1] })) tokens, median \(median(plain.map { $0[2] })) ms a step" }
            if !seen.isEmpty { text += ", with a picture ~\(median(seen.map { $0[1] })) tokens, median \(median(seen.map { $0[2] })) ms a step" }
            return text
        }.joined(separator: "; ")
    }

    private func saveVisionReport(_ runs: [VisionRun], as file: String) {
        guard let directory = context.snapshotDirectory else { return }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        try? encoder.encode(runs).write(to: directory.appendingPathComponent(file))
    }

    /// "Do it here" where only a picture tells the items apart: `Skilli
    /// testform <state> photos`, a photo and six icon-only buttons with no
    /// words for Accessibility. Four goals, each in words only (before) and
    /// with Jev's picture of the window (after); then "jette-la à la
    /// corbeille" rings the trash and asks first; then one goal through
    /// Ask, the card captured while Jev looks. The picture, the window
    /// before and after, and a report land in dist (doit-vision-*).
    private func controlSeesWhatOnlyThePictureTells() async {
        let name = "Do it here sees the window: icon-only buttons told apart by Jev's picture (before/after), the trash ringed and asked first, through Ask"
        guard let key = Keychain.read(account: DecisionProvider.typeSafe.keychainAccount), !key.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no TypeSafe key saved in Settings", latencyMs: nil))
            return
        }
        guard ScreenSight.isAllowed else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no Screen Recording for skil.li on this Mac", latencyMs: nil))
            return
        }
        // Jev alone: OpenAI never sees pictures, and the measure is Jev's.
        let keys: [DecisionProvider: String] = [.typeSafe: key]
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-photos-\(UUID().uuidString)")
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let stateFile = folder.appendingPathComponent("state.json")
        let process = Process()
        process.executableURL = Bundle.main.executableURL
        process.arguments = ["testform", stateFile.path, "photos"]
        defer {
            process.terminate()
            try? FileManager.default.removeItem(at: folder)
            context.aiActions.decisionKeysOverride = nil
        }
        do { try process.run() } catch {
            record(name, false, "the photos did not start: \(error.localizedDescription)", nil)
            return
        }
        func state() -> [String: Int] {
            ((try? Data(contentsOf: stateFile)).flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Int] } ?? [:])
                .filter { $0.key != "pid" }
        }
        let pid = process.processIdentifier
        guard await waitUntil(timeout: 5, {
            (try? Data(contentsOf: stateFile)).flatMap { try? JSONSerialization.jsonObject(with: $0) as? [String: Int] }?["pid"] == Int(pid)
        }) != nil else {
            record(name, false, "the photos did not show", nil)
            return
        }
        _ = await waitUntil(timeout: 3) {
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid
        }
        await pause(300)
        // Only the picture tells them apart: Accessibility has no words for them.
        let icons = UIReader.snapshot(pid: pid).elements.filter { $0.role == "button" && $0.frame != nil }
        let wordless = icons.filter { $0.label.isEmpty && ($0.value ?? "").isEmpty }
        guard wordless.count >= 6 else {
            record(name, false, "Accessibility tells the icons apart already: \(icons.map(\.line))", nil)
            return
        }
        await captureWindow(of: pid, as: "doit-vision-before-light.png")

        let goals = [("mets cette photo en favori", "starred"), ("imprime la photo", "printed"),
                     ("zoome sur la photo avec la loupe", "zoomed"), ("modifie la photo avec le crayon", "edited")]
        // "button, 3rd of 6 in a row": the icon by its place.
        let order = TestForm.photoIcons
        func names(_ expected: String) -> (String) -> Bool {
            let place = (order.firstIndex(of: expected) ?? 0) + 1
            return { $0.contains("\(ScreenControl.ordinal(place)) of \(order.count) in a row") }
        }
        var runs: [VisionRun] = []
        var lastPicture: Data?
        for mode in ["words", "picture", "outlined"] {
            for (goal, expected) in goals {
                let (run, control) = await visionRun(app: "Photos form", goal: goal, expected: expected, mode: mode, pid: pid, keys: keys,
                                                     counts: state, names: names(expected))
                runs.append(run)
                if mode == "picture", let picture = control.lastPicture { lastPicture = picture }
            }
        }
        if let directory = context.snapshotDirectory, let lastPicture {
            try? lastPicture.write(to: directory.appendingPathComponent("doit-vision-picture.jpg"))
        }

        // The trash, for a goal that cannot be taken back: ringed, asked first.
        let (trash, _) = await visionRun(app: "Photos form", goal: "jette cette photo à la corbeille", expected: "trashed", mode: "picture", pid: pid,
                                         keys: keys, counts: state, names: names("trashed"))
        let trashAsked = trash.asked.contains { $0.contains("ringed") } && state()["trashed"] == 0
        runs.append(trash)

        // Through Ask, as the user does it: the card says it looks at the
        // window (captured then), then goes once done. Light, then dark
        // (the card's window and the photos', through a flag file).
        context.aiActions.decisionKeysOverride = keys
        let popover = context.aiActions.popover
        var viaAsk = true
        var askTook = Duration.zero
        var askSteps: [String] = []
        var cardShots: [String] = []
        for (dark, request) in [(false, "ajoute cette photo aux favoris"), (true, "mets cette photo en favori")] {
            let expected = "starred"
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 3) { !popover.isVisible }
            await pause(1000)
            if dark { try? Data().write(to: folder.appendingPathComponent("dark")) }
            // The earlier runs made it a favorite: it is not one any more.
            try? Data().write(to: folder.appendingPathComponent("unstar"))
            _ = await waitUntil(timeout: 2) { !FileManager.default.fileExists(atPath: folder.appendingPathComponent("unstar").path) }
            popover.window.appearance = NSAppearance(named: dark ? .darkAqua : .aqua)
            await pause(300)
            _ = await waitUntil(timeout: 3) {
                Self.makeFrontmost(pid: pid)
                return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid
            }
            let before = state()[expected] ?? 0
            let start = ContinuousClock.now
            context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": request])
            let file = "doit-vision-card-looking-\(dark ? "dark" : "light").png"
            if await waitUntil(timeout: 10, { popover.isVisible && popover.shownStatus == "Looking at the window…" }) != nil {
                cardShots.append(await captureCard(popover.window, over: pid, as: file))
            } else {
                cardShots.append("\(file): not seen (\(popover.shownStatus))")
            }
            // Unsure, the card asks: "What should I do?" (the user picks
            // doing it in this app) or "Which one?" (the star by its place),
            // as one would.
            var picked = false
            var routed = false
            let done = await waitUntil(timeout: 20) {
                if !routed, popover.shownQuestion?.text == "What should I do?",
                   let index = popover.shownOptions.firstIndex(of: AskRoute.control.choice), index < 9 {
                    routed = true
                    Task { await self.pressKey(Character(String(index + 1))) }
                }
                if !picked, popover.shownQuestion?.text == "Which one?",
                   let index = popover.shownOptions.firstIndex(where: names(expected)), index < 9 {
                    picked = true
                    Task { await self.pressKey(Character(String(index + 1))) }
                }
                return (state()[expected] ?? 0) > before && !popover.isVisible
            } != nil
            if !dark { askTook = ContinuousClock.now - start }
            viaAsk = viaAsk && done
            askSteps.append((dark ? "dark: " : "light: ") + (routed ? "picked “\(AskRoute.control.choice)”, " : "") + (picked ? "picked in “Which one?”, " : "")
                + (context.aiActions.lastControl.map { "\($0.history) (\($0.decider), pictures \($0.pictures.map(\.need.rawValue)), \($0.costs.count) decisions, last: \($0.lastDecision))" } ?? "no control")
                + (done ? "" : " — card “\(popover.shownTitle)” \(popover.shownStatus): \(popover.shownText.prefix(200)) \(popover.shownQuestion?.text ?? "")"))
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            await pause(300)
            await captureWindow(of: pid, as: "doit-vision-after-\(dark ? "dark" : "light").png")
        }
        popover.window.appearance = nil
        saveVisionReport(runs, as: "doit-vision-report.json")

        // After: the goal's icon pressed, alone or once the user picked it
        // among those offered; never another; more often alone than before.
        let after = runs.filter { $0.mode == "picture" && $0.goal != trash.goal }
        let before = runs.filter { $0.mode == "words" }
        let pictured = after.flatMap(\.pictures)
        let better = after.filter { $0.right && $0.whichAsked == 0 }.count > before.filter { $0.right && $0.whichAsked == 0 }.count
        record(name, after.allSatisfy { $0.right && !$0.wrong } && better && trashAsked && viaAsk,
               Self.visionSummary(runs.filter { $0.goal != trash.goal })
                   + "; wrong after: \(after.filter { !$0.right }.map { "\($0.goal) → \($0.steps) \($0.outcome)" })"
                   + "; pictures \(pictured.prefix(2))"
                   + "; trash ringed and asked first: \(trashAsked) (\(trash.asked))"
                   + "; through Ask: \(viaAsk) in \(askTook.compact), \(askSteps), card while it looks: \(cardShots)",
               Double(askTook.components.seconds * 1_000))
    }

    /// A web page in Safari that tells Accessibility little: four icon-only
    /// buttons (no label) and two buttons drawn in a canvas ("Archive",
    /// "Snooze": only words on screen). Each goal in words only, then with
    /// the picture. What was pressed is in the page's title.
    private func controlSeesAWebPage() async {
        let name = "Do it here in Safari: icon-only buttons and a canvas, in words then with Jev's picture (before/after)"
        let bundleID = "com.apple.Safari"
        guard let key = Keychain.read(account: DecisionProvider.typeSafe.keychainAccount), !key.isEmpty, ScreenSight.isAllowed,
              let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no TypeSafe key, no Screen Recording or no Safari", latencyMs: nil))
            return
        }
        let keys: [DecisionProvider: String] = [.typeSafe: key]
        func icon(_ id: String, _ path: String) -> String {
            "<button id=\"\(id)\"><svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#333\" stroke-width=\"2\" stroke-linejoin=\"round\" stroke-linecap=\"round\" aria-hidden=\"true\">\(path)</svg></button>"
        }
        let html = """
        <!doctype html><html><head><meta charset="utf-8"><title>Inbox</title>
        <style>body{font:15px -apple-system,sans-serif;margin:28px;color:#222}.bar{display:flex;gap:10px;margin:18px 0}
        button{width:48px;height:40px;border:1px solid #ccc;border-radius:9px;background:#fafafa}canvas{border:1px solid #ddd;border-radius:10px}</style></head>
        <body><h2>Inbox — Weekly report from Paul</h2><p>Here are the numbers for this week. Let me know what you think.</p>
        <div class="bar">
        \(icon("star", "<polygon points=\"12,2 15,9 22,9.3 16.6,14 18.5,21 12,17 5.5,21 7.4,14 2,9.3 9,9\"/>"))
        \(icon("bell", "<path d=\"M6 16V11a6 6 0 0 1 12 0v5l2 2H4z\"/><path d=\"M10 21a2 2 0 0 0 4 0\"/>"))
        \(icon("flag", "<path d=\"M5 22V3\"/><path d=\"M5 4h12l-2.5 4L17 12H5\"/>"))
        \(icon("heart", "<path d=\"M12 21s-8-5.2-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 5.8-8 11-8 11z\"/>"))
        </div>
        <canvas id="c" width="440" height="90"></canvas>
        <script>
        const counts={star:0,bell:0,flag:0,heart:0,archive:0,snooze:0};
        const show=()=>{document.title='Inbox · '+Object.entries(counts).map(([k,v])=>k+'='+v).join(' ');};
        for (const id of ['star','bell','flag','heart']) document.getElementById(id).onclick=()=>{counts[id]++;show();};
        const c=document.getElementById('c'),x=c.getContext('2d');
        const drawn=[['Archive',20],['Snooze',230]];
        for (const [word,left] of drawn){x.fillStyle='#e8f0fe';x.beginPath();x.roundRect(left,20,190,50,10);x.fill();
        x.fillStyle='#1a56c4';x.font='600 22px -apple-system,sans-serif';x.fillText(word,left+50,53);}
        c.onclick=e=>{const r=c.getBoundingClientRect();counts[(e.clientX-r.left)<220?'archive':'snooze']++;show();};
        show();
        </script></body></html>
        """
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-vision-\(getpid()).html")
        try? html.write(to: file, atomically: true, encoding: .utf8)
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        defer { try? FileManager.default.removeItem(at: file) }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let opened = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration) else {
            record(name, false, "Safari did not open the page", nil)
            return
        }
        let pid = opened.processIdentifier
        // The front window's title only: a whole read of the page is slow.
        func counts() -> [String: Int] {
            let app = AXUIElementCreateApplication(pid)
            AXUIElementSetMessagingTimeout(app, 0.5)
            var window: CFTypeRef?, value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &window) == .success, let window,
                  CFGetTypeID(window) == AXUIElementGetTypeID(),
                  AXUIElementCopyAttributeValue(window as! AXUIElement, kAXTitleAttribute as CFString, &value) == .success,
                  let title = value as? String, title.hasPrefix("Inbox · ") else { return [:] }
            return title.dropFirst("Inbox · ".count).split(separator: " ").reduce(into: [:]) { result, pair in
                let parts = pair.split(separator: "=")
                if parts.count == 2, let value = Int(parts[1]) { result[String(parts[0])] = value }
            }
        }
        guard await waitUntil(timeout: 10, {
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && !counts().isEmpty
        }) != nil else {
            record(name, false, "the page did not come forward (title “\(UIReader.snapshot(pid: pid).window)”)", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        await pause(500)
        let buttons = UIReader.snapshot(pid: pid).elements.filter { $0.role == "button" }
        let wordless = buttons.filter { $0.label.isEmpty && ($0.value ?? "").isEmpty && $0.frame != nil }.count
        await captureWindow(of: pid, as: "doit-vision-safari-before.png")
        let goals = [("mets une étoile à ce mail", "star"), ("clique sur la cloche", "bell"), ("signale ce mail avec le drapeau", "flag"),
                     ("clique sur Snooze", "snooze")]
        let icons = ["star", "bell", "flag", "heart"]
        func names(_ expected: String) -> (String) -> Bool {
            guard let index = icons.firstIndex(of: expected) else { return { $0.localizedCaseInsensitiveContains(expected) } }
            return { $0.contains("\(ScreenControl.ordinal(index + 1)) of \(icons.count) in a row") }
        }
        var runs: [VisionRun] = []
        var lastPicture: Data?
        for mode in ["words", "picture", "outlined"] {
            for (goal, expected) in goals {
                let (run, control) = await visionRun(app: "Safari page", goal: goal, expected: expected, mode: mode, pid: pid, keys: keys,
                                                     counts: counts, names: names(expected))
                runs.append(run)
                if mode == "picture", let picture = control.lastPicture { lastPicture = picture }
            }
        }
        if let directory = context.snapshotDirectory, let lastPicture {
            try? lastPicture.write(to: directory.appendingPathComponent("doit-vision-safari-picture.jpg"))
        }
        await captureWindow(of: pid, as: "doit-vision-safari-after.png")
        saveVisionReport(runs, as: "doit-vision-safari-report.json")
        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
        let after = runs.filter { $0.mode == "picture" }
        let before = runs.filter { $0.mode == "words" }
        // After: every goal's item pressed (alone or once picked among
        // those offered), never another, more often than before.
        record(name, after.allSatisfy { $0.right && !$0.wrong } && after.filter(\.right).count > before.filter(\.right).count,
               "\(wordless) of \(buttons.count) buttons without words; " + Self.visionSummary(runs)
                   + "; wrong after: \(after.filter { !$0.right }.map { "\($0.goal) → \($0.steps) \($0.outcome)" })"
                   + "; pictures \(after.flatMap(\.pictures).prefix(2))", nil)
    }

    // MARK: - Chess, "do it here" in any app

    /// What `/tmp/skilli-chess.json` asks the chess scope for; without it,
    /// the spot picks and two-move demos through Ask, recorded: the board
    /// as Chess tells it, then hidden from skil.li.
    private struct ChessConfig: Decodable {
        var probe = false
        /// "jev-ax", "jev-picture", "claude-ax:sonnet", "claude-picture:opus"…
        var modes: [String] = []
        var moves = 6
        var spots = true
        /// How spots are found: "box", "grid".
        var spotWays = ["box"]
        /// Each recorded on its own (dist/chess-demo-<mode>.mov).
        var demos = ["claude-ax:opus", "claude-picture:opus"]
        var demoMoves = 2
        var record = true
        /// Replays of each request "do it here" sent, asked other ways
        /// (`chessGrounding`); 0: none.
        var grounding = 0
        /// Looks cut short after 15 elements once a move's first square was
        /// pressed, as Chess answered in the real run of 2026-10-18 (`modes`);
        /// 0: read whole.
        var slowLooks = 0
        /// The square a plan's second line clicks never read once its
        /// first was pressed (`modes`): nothing else may be clicked.
        var hideTarget = false
        /// Rounds of the white bishop picked up after 1. e4, the window
        /// read every 500 ms after (`chessSlowProbe`); 0: none.
        var slowProbe = 0

        enum CodingKeys: String, CodingKey {
            case probe, modes, moves, spots, spotWays, demos, demoMoves, record, grounding, slowLooks, hideTarget, slowProbe
        }

        init() {}

        init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            probe = try container.decodeIfPresent(Bool.self, forKey: .probe) ?? false
            modes = try container.decodeIfPresent([String].self, forKey: .modes) ?? []
            moves = try container.decodeIfPresent(Int.self, forKey: .moves) ?? 6
            spots = try container.decodeIfPresent(Bool.self, forKey: .spots) ?? true
            spotWays = try container.decodeIfPresent([String].self, forKey: .spotWays) ?? ["box"]
            demos = try container.decodeIfPresent([String].self, forKey: .demos) ?? ["claude-ax:opus", "claude-picture:opus"]
            demoMoves = try container.decodeIfPresent(Int.self, forKey: .demoMoves) ?? 2
            record = try container.decodeIfPresent(Bool.self, forKey: .record) ?? true
            grounding = try container.decodeIfPresent(Int.self, forKey: .grounding) ?? 0
            slowLooks = try container.decodeIfPresent(Int.self, forKey: .slowLooks) ?? 0
            hideTarget = try container.decodeIfPresent(Bool.self, forKey: .hideTarget) ?? false
            slowProbe = try container.decodeIfPresent(Int.self, forKey: .slowProbe) ?? 0
        }
    }

    /// One try at a move: what "do it here" did and whether Chess took it.
    private struct ChessTry: Codable {
        let outcome: String
        let legal: Bool
        let seconds: Double
        let steps: [String]
        let plans: [[String]]
        /// "cell 53 71% → 12 40% at (431, 860) = e2 for “Click the white pawn on e2”, 812 ms, 9100 tokens"
        let spots: [String]
        /// Each decision: [1 with a picture else 0, input tokens, ms].
        let decisions: [[Int]]
        let lastDecision: String
        /// Looks read again for a plan's line whose item was not read.
        let rereads: Int
    }

    private struct ChessMove: Codable {
        let mode: String
        let number: Int
        let legal: Bool
        let seconds: Double
        /// What the Game Log says was played ("pawn E 2 to E 4").
        let played: String?
        /// Moves of ours played past the one asked (the run went on).
        let extra: Int
        let tries: [ChessTry]
    }

    private struct ChessSpot: Codable {
        let goal: String
        let expected: String
        let way: String
        let fine: Bool
        let hit: String
        let right: Bool
        let detail: String
    }

    /// Chess.app as the showcase of "do it here" in any app: its board is
    /// in Accessibility (64 buttons, "pion blanc, e2"), but drawn in 3D
    /// with its frames upside down; hidden from skil.li it is a canvas, its
    /// Accessibility kept as the ground truth that scores each click. The
    /// spots and games are measures (in the detail and dist/remote); the
    /// check passes when every demo move is played through Ask.
    private func chessChecks() async {
        let config = (try? Data(contentsOf: URL(fileURLWithPath: "/tmp/skilli-chess.json")))
            .flatMap { try? JSONDecoder().decode(ChessConfig.self, from: $0) } ?? ChessConfig()
        if config.probe {
            await chessProbe()
            return
        }
        if config.grounding > 0 {
            await chessGrounding(times: config.grounding)
            return
        }
        if config.slowProbe > 0 {
            await chessSlowProbe(rounds: config.slowProbe)
            return
        }
        let name = "Chess: spots on its board seen as a picture, moves by Jev or planned by Claude, the demo through Ask"
        let bundleID = "com.apple.Chess"
        guard let key = Keychain.read(account: DecisionProvider.typeSafe.keychainAccount), !key.isEmpty, ScreenSight.isAllowed,
              let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no TypeSafe key, no Screen Recording or no Chess", latencyMs: nil))
            return
        }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let app = try? await NSWorkspace.shared.openApplication(at: appURL, configuration: configuration) else {
            record(name, false, "Chess did not open", nil)
            return
        }
        let pid = app.processIdentifier
        if context.ai.writer(for: .claude("sonnet")) == nil { await context.ai.refresh() }
        var summary: [String] = []
        var passed = true

        // Spots alone: named squares, the board hidden, each pick scored
        // against where Chess draws that square.
        if config.spots {
            guard await chessNewGame(pid: pid) else {
                record(name, false, "no new game in Chess", nil)
                return
            }
            var picks: [ChessSpot] = []
            let goals = [("clique sur la case e4", "e4"), ("clique sur le cavalier blanc en g1", "g1"), ("clique sur le pion noir en d7", "d7"),
                         ("clique sur la tour noire en a8", "a8"), ("clique sur la case c3", "c3"), ("clique sur la dame blanche", "d1"),
                         ("clique sur la case h5", "h5"), ("clique sur le fou noir en f8", "f8")]
            for way in config.spotWays.compactMap(ComputerControl.SpotWay.init(rawValue:)) {
                for fine in [true, false] {
                    for (goal, expected) in goals {
                        Self.makeFrontmost(pid: pid)
                        await pause(300)
                        let board = Self.chessBoard(pid: pid)
                        let control = ComputerControl(keys: [.typeSafe: key], selection: context.selection)
                        control.hides = { Self.isChessSquare($0) }
                        control.fineSpot = fine
                        control.spotWay = way
                        let point = await control.locate(goal: goal, pid: pid)
                        let hit = point.map { Self.square(at: $0, on: board) } ?? "none"
                        let detail = control.spots.last.map(Self.describe) ?? "no pick"
                        picks.append(ChessSpot(goal: goal, expected: expected, way: way.rawValue, fine: fine, hit: hit, right: hit == expected, detail: detail))
                        Log.actions.notice("SELFTEST chess spot \(way.rawValue, privacy: .public) “\(goal, privacy: .public)” fine \(fine, privacy: .public): \(hit, privacy: .public) (\(detail, privacy: .public))")
                    }
                    let these = picks.filter { $0.way == way.rawValue && $0.fine == fine }
                    summary.append("spots \(way.rawValue)\(fine ? " + close-up" : " alone"): \(these.filter(\.right).count)/\(goals.count), wrong \(these.filter { !$0.right }.map { "\($0.expected)→\($0.hit)" })")
                }
            }
            saveChess(picks, as: "chess-spots.json")
        }

        // Moves against the computer at its lowest strength, per mode.
        var moves: [ChessMove] = []
        for mode in config.modes {
            guard await chessNewGame(pid: pid) else {
                summary.append("\(mode): no new game")
                continue
            }
            var played: [ChessMove] = []
            for number in 1...max(1, config.moves) {
                guard await chessWhiteToMove(pid: pid) else { break }
                let move = await chessMove(mode: mode, number: number, pid: pid, key: key, slowLooks: config.slowLooks,
                                           hideTarget: config.hideTarget)
                played.append(move)
                Log.actions.notice("SELFTEST chess \(mode, privacy: .public) move \(number): legal \(move.legal, privacy: .public) \(move.played ?? "-", privacy: .public) in \(move.seconds, privacy: .public) s, \(move.tries.count) tries")
                guard move.legal else { break }
            }
            moves += played
            let log = Self.chessLog(pid: pid)
            saveChess(log, as: "chess-log-\(mode.replacingOccurrences(of: ":", with: "-")).json")
            let legal = played.filter(\.legal)
            let firstTry = played.filter { $0.legal && $0.tries.count == 1 }.count
            summary.append("\(mode): \(legal.count)/\(played.count) legal, \(firstTry) first try, "
                + "\(legal.isEmpty ? "-" : String(format: "%.1f", legal.map(\.seconds).reduce(0, +) / Double(legal.count))) s a move"
                + (config.slowLooks > 0 ? ", looks cut short after the first press: read again \(played.map { $0.tries.map(\.rereads) }), "
                    + "steps \(played.map { $0.tries.first.map { "\($0.steps) for \($0.plans.last ?? [])" } ?? "-" })" : ""))
            // Cut short, every move is still the planned one, first try.
            if config.slowLooks > 0 { passed = passed && !played.isEmpty && firstTry == played.count }
            // Its square never read: no item pressed that no plan's line
            // named (a click in the picture for a line aside).
            if config.hideTarget {
                let strays = played.flatMap(\.tries).flatMap { attempt in
                    attempt.steps.filter { step in
                        ["Clicked button", "Chose", "Typed"].contains(where: step.hasPrefix)
                            && !attempt.plans.joined().contains { $0.contains(step.replacingOccurrences(of: "Clicked button ", with: "")) }
                    }
                }
                summary.append("square hidden: outcomes \(played.flatMap(\.tries).map(\.outcome)), plans \(played.flatMap(\.tries).map(\.plans)), "
                    + "steps \(played.flatMap(\.tries).map(\.steps)), clicked outside the plans \(strays)")
                passed = passed && !played.isEmpty && strays.isEmpty
            }
        }
        if !moves.isEmpty { saveChess(moves, as: "chess-moves.json") }

        // The demo, as the user does it: Ask, "joue le prochain coup".
        for demo in config.demos {
            let (line, ok) = await chessDemo(mode: demo, moves: config.demoMoves, pid: pid, key: key, recording: config.record)
            summary.append(line)
            passed = passed && ok
        }
        record(name, passed, summary.joined(separator: "; "), nil)
    }

    /// One move for `mode`: "do it here" with "joue le prochain coup",
    /// tried up to three times until Chess takes a move.
    private func chessMove(mode: String, number: Int, pid: pid_t, key: String, slowLooks: Int = 0, hideTarget: Bool = false) async -> ChessMove {
        let start = ContinuousClock.now
        var tries: [ChessTry] = []
        let firstNew = Self.chessLog(pid: pid).count
        let parts = mode.split(separator: ":").map(String.init)
        let picture = parts[0].hasSuffix("picture")
        let writer = parts[0].hasPrefix("claude") ? context.ai.writer(for: .claude(parts.count > 1 ? parts[1] : "sonnet")) : nil
        for _ in 0..<3 {
            Self.makeFrontmost(pid: pid)
            await pause(300)
            let before = Self.chessLog(pid: pid).count
            let board = Self.chessBoard(pid: pid)
            let control = ComputerControl(keys: [.typeSafe: key], selection: context.selection)
            if picture { control.hides = { Self.isChessSquare($0) } }
            if let writer {
                control.plan = { goal, state, image in
                    await AIActionController.planSteps(writer.engine, model: writer.choice, goal: goal, state: state, picture: image)
                }
            }
            // "claude-picture:sonnet:grid": how the spot is found.
            if parts.count > 2, let way = ComputerControl.SpotWay(rawValue: parts[2]) { control.spotWay = way }
            control.confirm = { _ in true }
            control.choose = { _, _ in 0 }
            control.askText = { _ in nil }
            if slowLooks > 0 {
                // As Chess answered once its first square was pressed in
                // the real run: 15 elements (rank 1, most of rank 2), cut short.
                var cut = 0
                control.cutsLook = { history in
                    guard history.count == 1, cut < slowLooks else { return nil }
                    cut += 1
                    return 15
                }
            }
            if hideTarget {
                // The first plan's second square, never read once its first
                // was pressed.
                control.hides = { [weak control] item in
                    guard let control, control.history.count >= 1, let first = control.plans.first, first.count > 1 else { return false }
                    return ScreenControl.clickedWords(in: first[1]).contains { $0 == item.label || item.label.hasSuffix(", " + $0) }
                }
            }
            let tryStart = ContinuousClock.now
            let outcome = await control.run(goal: "joue le prochain coup", pid: pid)
            let legal = await waitUntil(timeout: 3) { Self.chessLog(pid: pid).count > before } != nil
            let seconds = Double((ContinuousClock.now - tryStart).components.seconds) + Double((ContinuousClock.now - tryStart).components.attoseconds) / 1e18
            tries.append(ChessTry(outcome: "\(outcome)", legal: legal, seconds: seconds, steps: control.history, plans: control.plans,
                                  spots: control.spots.map { Self.describe($0) + " = " + Self.square(at: $0.point, on: board) },
                                  decisions: control.costs.map { [$0.picture ? 1 : 0, $0.tokens, $0.milliseconds] }, lastDecision: control.lastDecision,
                                  rereads: control.rereads))
            if legal { break }
            // A piece left picked up: put down before the next try.
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
        }
        let total = ContinuousClock.now - start
        let log = Self.chessLog(pid: pid)
        return ChessMove(mode: mode, number: number, legal: tries.last?.legal == true,
                         seconds: Double(total.components.seconds) + Double(total.components.attoseconds) / 1e18,
                         played: tries.last?.legal == true && log.indices.contains(firstNew) ? log[firstNew] : nil,
                         extra: max(0, log.count - firstNew - 2), tries: tries)
    }

    /// Ask, as the user does it, in Chess for `moves` moves, the screen
    /// recorded (dist/chess-demo-<mode>.mov).
    private func chessDemo(mode: String, moves: Int, pid: pid_t, key: String, recording: Bool) async -> (String, Bool) {
        guard await chessNewGame(pid: pid) else { return ("demo: no new game", false) }
        let parts = mode.split(separator: ":").map(String.init)
        context.aiActions.decisionKeysOverride = [.typeSafe: key]
        context.aiActions.planModelOverride = .claude(parts.count > 1 ? parts[1] : "sonnet")
        if parts[0].hasSuffix("picture") { context.aiActions.controlHides = { Self.isChessSquare($0) } }
        defer {
            context.aiActions.decisionKeysOverride = nil
            context.aiActions.planModelOverride = nil
            context.aiActions.controlHides = nil
        }
        // The demo alone on screen: the other apps hidden (shown again
        // after), Chess's window large and centred.
        let hidden = NSWorkspace.shared.runningApplications.filter {
            $0.activationPolicy == .regular && $0.processIdentifier != pid && $0.processIdentifier != getpid() && !$0.isHidden
        }
        for app in hidden { app.hide() }
        defer { for app in hidden { app.unhide() } }
        Self.placeChessWindow(pid: pid)
        await pause(800)
        let recorder = ScreenRecorder()
        if recording, let directory = context.snapshotDirectory {
            // Chess and skil.li's card only, cut to Chess's window: never
            // the desktop or another app.
            await recorder.start(to: directory.appendingPathComponent("chess-demo-\(mode.replacingOccurrences(of: ":", with: "-")).mov"),
                                 apps: [pid, getpid()], area: UIReader.snapshot(pid: pid).frame)
        }
        let popover = context.aiActions.popover
        var lines: [String] = []
        var legalCount = 0
        for number in 1...max(1, moves) {
            guard await chessWhiteToMove(pid: pid) else { break }
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 3) { !popover.isVisible }
            _ = await waitUntil(timeout: 3) {
                Self.makeFrontmost(pid: pid)
                return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid
            }
            await pause(1200)
            let before = Self.chessLog(pid: pid).count
            let start = ContinuousClock.now
            // Typed in Ask's card, as the user does.
            context.aiActions.run(PromptLibrary.askID, triggeredAt: .now)
            guard await waitUntil(timeout: 3, { popover.phase == .asking }) != nil else {
                lines.append("move \(number): Ask's card did not ask")
                break
            }
            for character in "joue le prochain coup" {
                await pressKey(character)
                await pause(45)
            }
            await pause(400)
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            var routed = false
            let done = await waitUntil(timeout: 120) {
                if !routed, popover.shownQuestion?.text == "What should I do?",
                   let index = popover.shownOptions.firstIndex(of: AskRoute.control.choice), index < 9 {
                    routed = true
                    Task { await self.pressKey(Character(String(index + 1))) }
                }
                return Self.chessLog(pid: pid).count > before && !popover.isVisible
            } != nil
            let took = ContinuousClock.now - start
            if done { legalCount += 1 }
            let control = context.aiActions.lastControl
            lines.append("move \(number) \(done ? "played" : "not played") in \(took.compact)" + (routed ? " (picked do it here)" : "")
                + ": \(Self.chessLog(pid: pid).last ?? "-"); \(control.map { "\($0.history), plans \($0.plans), \($0.spots.count) spots" } ?? "no control")"
                + (done ? "" : " — card “\(popover.shownTitle)” \(popover.shownStatus) \(popover.shownText.prefix(160))"))
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            guard done else { break }
            // The computer's answer, in the recording too.
            _ = await chessWhiteToMove(pid: pid)
            await pause(800)
        }
        if recording { await recorder.stop() }
        await captureWindow(of: pid, as: "chess-demo-\(mode.replacingOccurrences(of: ":", with: "-"))-end.png")
        return ("demo \(mode): \(legalCount)/\(moves) through Ask, \(lines)" + (recorder.failure.map { " — recording: \($0)" } ?? ""), legalCount == moves)
    }

    /// Chess's game window large and centred on the main screen, under
    /// the menu bar.
    private static func placeChessWindow(pid: pid_t) {
        guard let screen = NSScreen.main?.visibleFrame, let full = NSScreen.screens.first?.frame else { return }
        let app = AXUIElementCreateApplication(pid)
        var window: CFTypeRef?
        guard AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &window) == .success, let window,
              CFGetTypeID(window) == AXUIElementGetTypeID() else { return }
        let element = unsafeDowncast(window, to: AXUIElement.self)
        let size = CGSize(width: min(1320, screen.width - 80), height: min(1000, screen.height - 60))
        // Accessibility's top-left origin.
        var origin = CGPoint(x: screen.midX - size.width / 2, y: full.maxY - screen.maxY + (screen.height - size.height) / 2 + 30)
        var extent = size
        if let position = AXValueCreate(.cgPoint, &origin) { AXUIElementSetAttributeValue(element, kAXPositionAttribute as CFString, position) }
        if let value = AXValueCreate(.cgSize, &extent) { AXUIElementSetAttributeValue(element, kAXSizeAttribute as CFString, value) }
    }

    private func saveChess<T: Encodable>(_ value: T, as file: String) {
        guard let directory = context.snapshotDirectory else { return }
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        try? encoder.encode(value).write(to: directory.appendingPathComponent(file))
    }

    /// "cell 53 71% → 12 40% at (431, 860) for “…”, 812 ms, 9100 tokens".
    private static func describe(_ spot: ComputerControl.SpotPick) -> String {
        spot.first + (spot.second.map { " → \($0)" } ?? "")
            + " at (\(Int(spot.point.x)), \(Int(spot.point.y)))" + (spot.meant.map { " for “\($0)”" } ?? "")
            + ", \(spot.milliseconds) ms, \(spot.tokens) tokens"
    }

    /// A square of Chess's board, as "do it here" reads it ("pion blanc,
    /// e2", "e4"): what the picture-only runs hide.
    nonisolated private static func isChessSquare(_ item: ScreenItem) -> Bool {
        item.source == .element && item.role == "button"
            && item.label.range(of: #"(^|, )[a-h][1-8]$"#, options: .regularExpression) != nil
    }

    /// Chess's board squares where they are drawn: their frames come
    /// upside down inside the board's view, flipped back here.
    private static func chessBoard(pid: pid_t) -> [(square: String, label: String, rect: CGRect, element: AXUIElement)] {
        let app = AXUIElementCreateApplication(pid)
        AXUIElementSetMessagingTimeout(app, 0.5)
        func attribute<T>(_ element: AXUIElement, _ name: String) -> T? {
            var value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success else { return nil }
            return value as? T
        }
        func frame(_ element: AXUIElement) -> CGRect? {
            guard let position: AXValue = attribute(element, kAXPositionAttribute), let size: AXValue = attribute(element, kAXSizeAttribute) else { return nil }
            var point = CGPoint.zero, extent = CGSize.zero
            AXValueGetValue(position, .cgPoint, &point)
            AXValueGetValue(size, .cgSize, &extent)
            return CGRect(origin: point, size: extent)
        }
        guard let window: AXUIElement = attribute(app, kAXFocusedWindowAttribute) ?? attribute(app, kAXMainWindowAttribute),
              let groups: [AXUIElement] = attribute(window, kAXChildrenAttribute) else { return [] }
        var squares: [(String, String, CGRect, AXUIElement)] = []
        for group in groups {
            guard let buttons: [AXUIElement] = attribute(group, kAXChildrenAttribute), let view = frame(group) else { continue }
            for button in buttons {
                guard let title: String = attribute(button, kAXTitleAttribute),
                      let range = title.range(of: #"[a-h][1-8]$"#, options: .regularExpression), let box = frame(button) else { continue }
                let y = view.minY + view.height - (box.minY - view.minY) - box.height
                squares.append((String(title[range]), title, CGRect(x: box.minX, y: y, width: box.width, height: box.height), button))
            }
        }
        return squares
    }

    /// The square drawn under `point`: the nearest middle among those
    /// whose frame holds it; "off the board" else.
    private static func square(at point: CGPoint, on board: [(square: String, label: String, rect: CGRect, element: AXUIElement)]) -> String {
        func distance(_ rect: CGRect) -> CGFloat { hypot(rect.midX - point.x, rect.midY - point.y) }
        let holding = board.filter { $0.rect.contains(point) }
        if let square = holding.min(by: { distance($0.rect) < distance($1.rect) }) { return square.square }
        // In the thin gaps between the frames: the nearest, within its own size.
        guard let nearest = board.min(by: { distance($0.rect) < distance($1.rect) }),
              distance(nearest.rect) < max(nearest.rect.width, nearest.rect.height) * 0.75 else { return "off the board" }
        return nearest.square
    }

    /// The moves in Chess's Game Log, one a half-move ("pawn E 2 to E
    /// 4"), read through Accessibility (Déplacements › Historique de la
    /// partie, shown).
    private static func chessLog(pid: pid_t) -> [String] {
        let app = AXUIElementCreateApplication(pid)
        AXUIElementSetMessagingTimeout(app, 0.5)
        func attribute<T>(_ element: AXUIElement, _ name: String) -> T? {
            var value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success else { return nil }
            return value as? T
        }
        guard let window: AXUIElement = attribute(app, kAXFocusedWindowAttribute) ?? attribute(app, kAXMainWindowAttribute) else { return [] }
        var texts: [String] = []
        var stack: [(AXUIElement, Int)] = [(window, 0)]
        while let (node, depth) = stack.popLast(), depth < 8 {
            let role: String = attribute(node, kAXRoleAttribute) ?? ""
            if role == "AXStaticText", let title: String = attribute(node, kAXTitleAttribute), title.hasPrefix("Coup ") || title.hasPrefix("Move ") {
                texts.append(title)
            }
            if let children: [AXUIElement] = attribute(node, kAXChildrenAttribute) {
                stack += children.reversed().map { ($0, depth + 1) }
            }
        }
        return texts.flatMap { text in
            text.components(separatedBy: "\n").map { $0.trimmingCharacters(in: .whitespaces) }
                .filter { $0.hasSuffix("..") }.map { String($0.dropLast(2)) }
        }
    }

    /// White to move: the Game Log holds an even number of half-moves and
    /// stays so a moment (the computer done); false after 90 s or when the
    /// title says the game is over.
    private func chessWhiteToMove(pid: pid_t) async -> Bool {
        var evenSince: ContinuousClock.Instant?
        let ok = await waitUntil(timeout: 90) {
            let title = UIReader.snapshot(pid: pid).window.lowercased()
            if ["mat", "pat ", "nulle", "checkmate", "stalemate", "draw"].contains(where: title.contains) { return true }
            guard Self.chessLog(pid: pid).count % 2 == 0 else {
                evenSince = nil
                return false
            }
            if evenSince == nil { evenSince = .now }
            return ContinuousClock.now - (evenSince ?? .now) >= .milliseconds(1_200)
        } != nil
        let title = UIReader.snapshot(pid: pid).window.lowercased()
        return ok && !["mat", "pat ", "nulle", "checkmate", "stalemate", "draw"].contains(where: title.contains)
    }

    /// A new game, human (white) against the computer at its lowest
    /// strength: Partie › Nouvelle…, its sheet's slider at its least,
    /// Commencer; the other games' windows closed unsaved first.
    private func chessNewGame(pid: pid_t) async -> Bool {
        let app = AXUIElementCreateApplication(pid)
        AXUIElementSetMessagingTimeout(app, 1)
        func attribute<T>(_ element: AXUIElement, _ name: String) -> T? {
            var value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success else { return nil }
            return value as? T
        }
        func children(_ element: AXUIElement) -> [AXUIElement] { attribute(element, kAXChildrenAttribute) ?? [] }
        func role(_ element: AXUIElement) -> String { attribute(element, kAXRoleAttribute) ?? "" }
        func title(_ element: AXUIElement) -> String { attribute(element, kAXTitleAttribute) ?? "" }
        func windows() -> [AXUIElement] { attribute(app, kAXWindowsAttribute) ?? [] }
        func sheet() -> AXUIElement? { windows().flatMap(children).first { role($0) == "AXSheet" } }
        // A save sheet holds its buttons deeper than its first children.
        func press(_ titles: [String], in element: AXUIElement) -> Bool {
            var stack = [(element, 0)]
            while let (node, depth) = stack.popLast() {
                if role(node) == "AXButton", titles.contains(title(node)) {
                    // A sheet closing as it is pressed may not answer in time.
                    let result = AXUIElementPerformAction(node, kAXPressAction as CFString)
                    return result == .success || result == .cannotComplete
                }
                if depth < 8 { stack += children(node).map { ($0, depth + 1) } }
            }
            return false
        }
        Self.makeFrontmost(pid: pid)
        await pause(300)
        func sheet(of window: AXUIElement) -> AXUIElement? { children(window).first { role($0) == "AXSheet" } }
        // New-game sheets left open (earlier runs): cancelled, gone before
        // the new one is looked for.
        for window in windows() {
            if let open = sheet(of: window), press(["Annuler", "Cancel"], in: open) { await pause(800) }
        }
        // The other games, closed without saving.
        for window in windows() {
            guard let close: AXUIElement = attribute(window, kAXCloseButtonAttribute) else { continue }
            AXUIElementPerformAction(close, kAXPressAction as CFString)
            await pause(600)
            if let ask = sheet(of: window) {
                if !press(["Supprimer", "Ne pas enregistrer", "Delete", "Don’t Save", "Don't Save"], in: ask) {
                    Log.actions.error("SELFTEST chess: closing “\(title(window), privacy: .public)” asks \(children(ask).map { role($0) + " " + title($0) }, privacy: .public)")
                    _ = press(["Annuler", "Cancel"], in: ask)
                }
                await pause(400)
            }
        }
        if let left = windows().first(where: { sheet(of: $0) != nil }) {
            Log.actions.error("SELFTEST chess: a sheet is still open on “\(title(left), privacy: .public)”")
        }
        var newGame: MenuReader.Item?
        _ = await waitUntil(timeout: 5) {
            Self.makeFrontmost(pid: pid)
            newGame = MenuReader.items(pid: pid).first { $0.path.hasPrefix("Partie > Nouvelle") || $0.path.hasPrefix("Game > New") }
            return newGame != nil
        }
        guard let item = newGame else {
            let menus = MenuReader.items(pid: pid)
            Log.actions.error("SELFTEST chess: no New Game menu item among \(menus.count): \(menus.prefix(30).map(\.path), privacy: .public); windows \(windows().map(title), privacy: .public), front \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "-", privacy: .public)")
            await captureWindow(of: pid, as: "chess-no-new-game.png")
            return false
        }
        AXUIElementPerformAction(item.element, kAXPressAction as CFString)
        // The new game's sheet: the one with Commencer.
        func hasStart(_ element: AXUIElement) -> Bool {
            var stack = [(element, 0)]
            while let (node, depth) = stack.popLast() {
                if role(node) == "AXButton", ["Commencer", "Start"].contains(title(node)) { return true }
                if depth < 6 { stack += children(node).map { ($0, depth + 1) } }
            }
            return false
        }
        // A sheet cancelled a moment ago may still be closing: found again
        // and pressed until Commencer takes.
        var started = false
        for _ in 0..<3 where !started {
            var found: AXUIElement?
            guard await waitUntil(timeout: 5, {
                found = windows().compactMap(sheet(of:)).last(where: hasStart)
                return found != nil
            }) != nil, let newSheet = found else { continue }
            // The computer at its weakest ("réfléchit 1 coup à l'avance").
            var stack = children(newSheet)
            while let node = stack.popLast() {
                if role(node) == "AXSlider", let least: NSNumber = attribute(node, kAXMinValueAttribute) {
                    AXUIElementSetAttributeValue(node, kAXValueAttribute as CFString, least)
                }
                stack += children(node)
            }
            started = press(["Commencer", "Start"], in: newSheet)
            if !started { await pause(700) }
        }
        // Pressed and answered late: the new game is there all the same.
        if !started, windows().compactMap(sheet(of:)).first(where: hasStart) == nil, Self.chessBoard(pid: pid).count == 64,
           Self.chessLog(pid: pid).isEmpty {
            started = true
        }
        guard started else {
            Log.actions.error("SELFTEST chess: no new game sheet took Commencer")
            await captureWindow(of: pid, as: "chess-no-new-game.png")
            return false
        }
        let board = await waitUntil(timeout: 5) {
            Self.chessBoard(pid: pid).count == 64 && (attribute(app, kAXFocusedWindowAttribute) as AXUIElement?).flatMap(sheet(of:)) == nil
        } != nil
        if !board {
            Log.actions.error("SELFTEST chess: after Commencer, \(Self.chessBoard(pid: pid).count) squares, sheet \(sheet() != nil), windows \(windows().map(title), privacy: .public)")
            await captureWindow(of: pid, as: "chess-no-board.png")
        }
        if board { Self.showChessLog(pid: pid) }
        await pause(1_000)
        return board
    }

    /// The Game Log shown: the moves are read there.
    private static func showChessLog(pid: pid_t) {
        let app = AXUIElementCreateApplication(pid)
        AXUIElementSetMessagingTimeout(app, 1)
        func attribute<T>(_ element: AXUIElement, _ name: String) -> T? {
            var value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success else { return nil }
            return value as? T
        }
        func children(_ element: AXUIElement) -> [AXUIElement] { attribute(element, kAXChildrenAttribute) ?? [] }
        let windows: [AXUIElement] = attribute(app, kAXWindowsAttribute) ?? []
        if chessLog(pid: pid).isEmpty, !windows.flatMap(children).flatMap(children).contains(where: {
            (attribute($0, kAXDescriptionAttribute) as String?) == "Historique de la partie"
        }), let log = MenuReader.items(pid: pid).first(where: { $0.path.contains("Historique de la partie") || $0.path.contains("Game Log") }) {
            AXUIElementPerformAction(log.element, kAXPressAction as CFString)
        }
    }

    // MARK: Grounding, replayed

    /// What one way of asking the target question answered.
    private struct GroundingAnswer: Codable {
        /// The item the plan's line names by its words, in percent.
        let named: Int?
        let top: String
        let topPercent: Int
        /// What "do it here" would act on: the likeliest it may act on.
        let picked: String?
        let pickedPercent: Int
        /// Under 40 % with others close: the user would pick.
        let asks: Bool
        /// The items it may not act on for the goal (send, share), summed.
        let outbound: Int
        /// "None of these items".
        let none: Int
        let tokens: Int
    }

    private struct GroundingReplay: Codable {
        let app: String
        let goal: String
        let step: Int
        let planLine: String?
        let named: String?
        let menuItems: Int
        let outboundOffered: [String]
        let ways: [String: [GroundingAnswer]]
        /// The state as sent, and the target question's options.
        let state: String
        let options: [String]
    }

    /// Ways of asking the target question, on the same requests: about
    /// the goal with its guide (send and share, save and export: before),
    /// about the goal alone, about the plan's line (after), and that with
    /// "none" said. A first run also left the items "do it here" may not
    /// act on out of the options: the guide alone kept the planned square
    /// at 21–38 % (docs/click-what-you-see.md).
    /// One read of Chess's window in the slow probe: when (ms after the
    /// bishop was pressed), what it gave, in how long.
    private struct ChessRead: Codable {
        let at: Int
        let elements: Int
        let milliseconds: Int
        let cutShort: Bool
    }

    private struct ChessSlowRound: Codable {
        let round: Int
        let menusRead: Bool
        /// The look before the press, as "do it here" takes it.
        let look: String
        let reads: [ChessRead]
    }

    /// Whether Chess answers Accessibility slowly once a piece is picked
    /// up, as in the real run of 2026-10-18 (after “fou blanc, f1” was pressed:
    /// 15 of its 73 elements in 2 s, for about 12 s). Chess opened as the
    /// user opens it (its first game: once it has a move, Partie ›
    /// Partager is enabled, as in the real game), 1. e4 played, then `rounds`
    /// times: a look as "do it here" takes it (the window, the menus every
    /// other round, the words on screen), the bishop pressed 3.5 s later
    /// as after a plan, the window read every 500 ms for 12 s, the bishop
    /// put down. A measure; report: dist/chess-slow.json.
    private func chessSlowProbe(rounds: Int) async {
        let name = "Chess: its window read after a piece is picked up (a slow real run)"
        let bundleID = "com.apple.Chess"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no Chess", latencyMs: nil))
            return
        }
        for running in NSRunningApplication.runningApplications(withBundleIdentifier: bundleID) { running.forceTerminate() }
        _ = await waitUntil(timeout: 5) { NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        configuration.arguments = ["-ApplePersistenceIgnoreState", "YES"]
        guard let app = try? await NSWorkspace.shared.openApplication(at: appURL, configuration: configuration) else {
            record(name, false, "Chess did not open", nil)
            return
        }
        let pid = app.processIdentifier
        guard await waitUntil(timeout: 15, {
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && UIReader.snapshot(pid: pid).frame != nil
        }) != nil else {
            record(name, false, "Chess's window did not show", nil)
            return
        }
        await pause(1_500)
        Self.showChessLog(pid: pid)
        await pause(1_000)
        func press(_ square: String) -> Bool {
            guard let element = Self.chessBoard(pid: pid).first(where: { $0.square == square })?.element else { return false }
            let result = AXUIElementPerformAction(element, kAXPressAction as CFString)
            return result == .success || result == .cannotComplete
        }
        func milliseconds(_ duration: Duration) -> Int {
            Int(duration.components.seconds * 1_000 + duration.components.attoseconds / 1_000_000_000_000_000)
        }
        // 1. e4 and the computer's answer: the bishop free to move.
        guard await chessWhiteToMove(pid: pid), press("e2") else {
            record(name, false, "white's e2 pawn could not be picked up", nil)
            return
        }
        await pause(400)
        _ = press("e4")
        guard await chessWhiteToMove(pid: pid), Self.chessLog(pid: pid).count == 2 else {
            record(name, false, "1. e4 not played or not answered: \(Self.chessLog(pid: pid))", nil)
            return
        }
        var results: [ChessSlowRound] = []
        for round in 1...rounds {
            Self.makeFrontmost(pid: pid)
            await pause(1_000)
            let menusRead = round % 2 == 1
            let start = ContinuousClock.now
            let snapshot = await ComputerControl.within(.seconds(3)) { UIReader.snapshot(pid: pid) }
            let read = ContinuousClock.now
            let menus = menusRead ? await ComputerControl.within(.milliseconds(2_500)) { MenuReader.shareableItems(pid: pid) } ?? [] : []
            if let window = snapshot?.frame {
                _ = await ComputerControl.within(.seconds(3)) { await ScreenSight.lines(pid: pid, window: window).lines.count }
            }
            let look = "\(snapshot?.elements.count ?? 0) elements in \(milliseconds(read - start)) ms, \(menus.count) menu items, all in \(milliseconds(ContinuousClock.now - start)) ms"
            await pause(3_500)
            guard press("f1") else {
                record(name, false, "the bishop on f1 could not be picked up", nil)
                return
            }
            let pressed = ContinuousClock.now
            var reads: [ChessRead] = []
            while ContinuousClock.now - pressed < .seconds(12) {
                await pause(500)
                let begun = ContinuousClock.now
                let again = await ComputerControl.within(.seconds(3)) { UIReader.snapshot(pid: pid) }
                reads.append(ChessRead(at: milliseconds(begun - pressed), elements: again?.elements.count ?? -1,
                                       milliseconds: milliseconds(ContinuousClock.now - begun), cutShort: again?.cutShort ?? true))
            }
            // Put down.
            Self.makeFrontmost(pid: pid)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            await pause(1_000)
            results.append(ChessSlowRound(round: round, menusRead: menusRead, look: look, reads: reads))
            Log.actions.notice("SELFTEST chess slow round \(round): look \(look, privacy: .public); reads \(reads.map { "\($0.elements)/\($0.milliseconds)" }, privacy: .public)")
        }
        saveChess(results, as: "chess-slow.json")
        let slow = results.filter { $0.reads.contains { $0.cutShort || $0.milliseconds > 500 } }
        record(name, !results.isEmpty, "\(slow.count)/\(results.count) rounds slow once the bishop was picked up: " + results.map { round in
            "round \(round.round) (menus \(round.menusRead ? "read" : "not read")): before, \(round.look); after, the slowest read "
                + "\(round.reads.map(\.milliseconds).max() ?? 0) ms, the fewest elements \(round.reads.map(\.elements).min() ?? 0)"
        }.joined(separator: "; "), nil)
    }

    private static let groundingWays = ["goal + guide", "goal", "plan line", "plan line, none"]
    private static let planNoneQuestion = ComputerControl.planTargetQuestion + " None when no item shown is the one it names."

    /// Measures for docs/click-what-you-see.md's "Grounding a plan's line"
    /// (`"grounding": N`): Chess opened as the user opens it (its first
    /// game; its second move reads 31 menu items, "Partager › Mail"
    /// among them, as in the retest), three moves through Ask; then
    /// "exporte en PDF dans mes documents" in TextEdit and Word through
    /// Ask (their own checks). Every request "do it here" sent is kept;
    /// those for a plan's line (Chess) and the first four (export) are
    /// replayed N times each way (`groundingWays`). Report:
    /// dist/chess-grounding.json.
    private func chessGrounding(times: Int) async {
        let name = "Grounding: the target question replayed as sent, then asked other ways (Chess's plan lines, TextEdit's and Word's export)"
        let bundleID = "com.apple.Chess"
        guard let key = Keychain.read(account: DecisionProvider.typeSafe.keychainAccount), !key.isEmpty, ScreenSight.isAllowed,
              let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no TypeSafe key, no Screen Recording or no Chess", latencyMs: nil))
            return
        }
        for running in NSRunningApplication.runningApplications(withBundleIdentifier: bundleID) { running.forceTerminate() }
        _ = await waitUntil(timeout: 5) { NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        // Its first game, not the windows of the last run.
        configuration.arguments = ["-ApplePersistenceIgnoreState", "YES"]
        guard let app = try? await NSWorkspace.shared.openApplication(at: appURL, configuration: configuration) else {
            record(name, false, "Chess did not open", nil)
            return
        }
        let pid = app.processIdentifier
        guard await waitUntil(timeout: 15, {
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && UIReader.snapshot(pid: pid).frame != nil
        }) != nil else {
            await captureWindow(of: pid, as: "chess-grounding-no-window.png")
            record(name, false, "Chess's window did not show", nil)
            return
        }
        await pause(1_500)
        Self.showChessLog(pid: pid)
        await pause(1_000)
        var lines = ["first game: \(Self.chessBoard(pid: pid).count) squares, \(UIReader.snapshot(pid: pid).elements.count) elements"]
        if context.ai.writer(for: .claude("opus")) == nil { await context.ai.refresh() }
        context.aiActions.decisionKeysOverride = [.typeSafe: key]
        context.aiActions.planModelOverride = .claude("opus")
        context.aiActions.controlKeepsRequests = true
        defer {
            context.aiActions.decisionKeysOverride = nil
            context.aiActions.planModelOverride = nil
            context.aiActions.controlKeepsRequests = false
        }
        let goal = "joue le prochain coup"
        let popover = context.aiActions.popover
        var kept: [(app: String, goal: String, requests: [ComputerControl.SentRequest])] = []
        for number in 1...3 {
            guard await chessWhiteToMove(pid: pid) else { break }
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 3) { !popover.isVisible }
            _ = await waitUntil(timeout: 3) {
                Self.makeFrontmost(pid: pid)
                return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid
            }
            await pause(800)
            let before = Self.chessLog(pid: pid).count
            context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": goal])
            var routed = false
            let played = await waitUntil(timeout: 120) {
                if !routed, popover.shownQuestion?.text == "What should I do?",
                   let index = popover.shownOptions.firstIndex(of: AskRoute.control.choice), index < 9 {
                    routed = true
                    Task { await self.pressKey(Character(String(index + 1))) }
                }
                return Self.chessLog(pid: pid).count > before && !popover.isVisible
            } != nil
            let control = context.aiActions.lastControl
            lines.append("move \(number) \(played ? "played" : "not played"): \(Self.chessLog(pid: pid).last ?? "-"), \(control?.history ?? [])")
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            if let control { kept.append(("Chess", goal, control.requests)) }
            guard played else { break }
        }
        for (path, id, title) in [("/System/Applications/TextEdit.app", "com.apple.TextEdit", "TextEdit"),
                                  ("/Applications/Microsoft Word.app", "com.microsoft.Word", "Word")] {
            let previous = context.aiActions.lastControl
            await controlExports(in: URL(fileURLWithPath: path), bundleID: id, name: title)
            if let control = context.aiActions.lastControl, control !== previous {
                kept.append((title, "exporte en PDF dans mes documents", control.requests))
            }
        }
        var replays: [GroundingReplay] = []
        for (app, goal, requests) in kept {
            let chosen = app.hasPrefix("Chess") ? requests.filter { $0.planLine != nil } : Array(requests.prefix(4))
            for (index, request) in chosen.enumerated() {
                replays.append(await replay(request, app: app, goal: goal, step: index + 1, times: times, key: key))
            }
        }
        saveChess(replays, as: "chess-grounding.json")
        func mean(_ values: [Int]) -> Int { values.isEmpty ? -1 : values.reduce(0, +) / values.count }
        let summary = replays.map { replay in
            "\(replay.app) \(replay.step) “\(replay.planLine ?? "-")” (\(replay.menuItems) menu items, outbound offered \(replay.outboundOffered)): "
                + Self.groundingWays.compactMap { way in
                    guard let answers = replay.ways[way], !answers.isEmpty else { return nil }
                    let tops = Dictionary(grouping: answers.map(\.top), by: { $0 }).map { "\($0.key) ×\($0.value.count)" }.sorted()
                    return "\(way): named \(mean(answers.compactMap(\.named)))%, top \(tops) \(mean(answers.map(\.topPercent)))%, "
                        + "picked \(Set(answers.compactMap(\.picked)).sorted()) \(mean(answers.map(\.pickedPercent)))%, asks \(answers.filter(\.asks).count)/\(answers.count)"
                }.joined(separator: "; ")
        }
        record(name, !replays.isEmpty, (lines + summary).joined(separator: " | "), nil)
    }

    /// `request` sent again `times` times each way: the target question's
    /// words or options changed, every other question and the state as
    /// they went.
    private func replay(_ request: ComputerControl.SentRequest, app: String, goal: String, step: Int, times: Int, key: String) async -> GroundingReplay {
        let named = request.planLine.flatMap { ScreenControl.named(by: $0, among: request.candidates) }
        let items = Dictionary(request.candidates.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
        func allowed(_ id: String) -> Bool { items[id].map { ScreenControl.mayAct(on: $0, goal: goal) } ?? true }
        func label(_ id: String) -> String { items[id]?.label ?? id }
        var ways: [String: [GroundingAnswer]] = [:]
        // What follows the question in its instructions: how the picture
        // shows the window.
        let sent = request.questions.first { $0.name == "target" }?.instructions ?? ""
        let looks = [ComputerControl.targetQuestion + ComputerControl.targetGuide, ComputerControl.planTargetQuestion]
            .first(where: sent.hasPrefix).map { String(sent.dropFirst($0.count)) } ?? ""
        let asked: [String: String] = ["goal + guide": ComputerControl.targetQuestion + ComputerControl.targetGuide, "goal": ComputerControl.targetQuestion,
                                       "plan line": ComputerControl.planTargetQuestion, "plan line, none": Self.planNoneQuestion]
        for way in Self.groundingWays where request.planLine != nil || !way.hasPrefix("plan line") {
            let questions = request.questions.map { question -> DecisionQuestion in
                guard question.name == "target", let words = asked[way] else { return question }
                return DecisionQuestion(name: question.name, instructions: words + looks, options: question.options)
            }
            var answers: [GroundingAnswer] = []
            for _ in 0..<times {
                guard let reply = try? await DecisionClient.reply(questions, input: request.state, picture: request.picture, provider: .typeSafe, key: key) else { continue }
                let probabilities = reply.answers["target"]?.probabilities ?? [:]
                let ranked = probabilities.filter { $0.key != "none" && $0.value > 0 }.sorted { $0.value > $1.value }
                let typing = reply.answers["next"]?.choice == "type"
                let fitting = ranked.filter { allowed($0.key) && (!typing || items[$0.key]?.isField == true) }
                let best = fitting.first
                let close = fitting.prefix(3).filter { $0.value >= (best?.value ?? 0) / 3 }
                answers.append(GroundingAnswer(
                    named: named.map { Int((probabilities[$0.id] ?? 0) * 100) },
                    top: ranked.first.map { label($0.key) } ?? "-", topPercent: Int((ranked.first?.value ?? 0) * 100),
                    picked: best.map { label($0.key) }, pickedPercent: Int((best?.value ?? 0) * 100),
                    asks: (best?.value ?? 1) < 0.4 && close.count > 1,
                    outbound: Int(ranked.filter { !allowed($0.key) }.map(\.value).reduce(0, +) * 100),
                    none: Int((probabilities["none"] ?? 0) * 100), tokens: reply.inputTokens))
            }
            ways[way] = answers
            Log.actions.notice("SELFTEST grounding \(app, privacy: .public) \(step) \(way, privacy: .public): \(answers.map { "\($0.named.map { "\($0)%" } ?? "-") top \($0.top) \($0.topPercent)%" }, privacy: .public)")
        }
        return GroundingReplay(app: app, goal: goal, step: step, planLine: request.planLine, named: named?.label,
                               menuItems: request.candidates.filter { $0.source == .menu }.count,
                               outboundOffered: request.candidates.filter { !ScreenControl.mayAct(on: $0, goal: goal) }.map(\.label), ways: ways,
                               state: request.state,
                               options: request.questions.first { $0.name == "target" }?.options.map { "\($0.value): \($0.description)" } ?? [])
    }

    /// The probe behind docs/click-what-you-see.md's facts (`"probe":
    /// true`): Chess.app as skil.li sees it. Its whole Accessibility tree,
    /// what "do it here" reads, the window captured and its words, its
    /// menus; then the steps of `/tmp/skilli-chess-probe.json` if there is
    /// one (`click`/`drag` at fractions of the window, `press`, `clicksquare`
    /// and `dragsquares` on board squares, `menu` by words, `key`, `wait`,
    /// `dump`, `capture`). Report: dist/chess-probe.json.
    private func chessProbe() async {
        let name = "Chess probe: Accessibility, capture, words, menus, scripted steps"
        let bundleID = "com.apple.Chess"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID), ScreenSight.isAllowed else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no Chess or no Screen Recording", latencyMs: nil))
            return
        }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let app = try? await NSWorkspace.shared.openApplication(at: appURL, configuration: configuration) else {
            record(name, false, "Chess did not open", nil)
            return
        }
        let pid = app.processIdentifier
        guard await waitUntil(timeout: 10, {
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && UIReader.snapshot(pid: pid).frame != nil
        }) != nil else {
            record(name, false, "Chess's window did not show", nil)
            return
        }
        await pause(1500)
        var report: [String: Any] = [:]
        var log: [String] = []
        func dump(_ key: String) {
            var lines: [String] = []
            Self.axTree(AXUIElementCreateApplication(pid), depth: 0, into: &lines)
            report[key] = lines
        }
        func snapshot(_ key: String) async {
            let snap = UIReader.snapshot(pid: pid)
            report[key + "-window"] = "\(snap.window) \(snap.frame.map { "\($0)" } ?? "-")"
            report[key + "-read"] = snap.elements.map { "\($0.line) \($0.frame.map { "\($0)" } ?? "")" }
            guard let frame = snap.frame, let capture = await ScreenSight.capture(pid: pid, window: frame) else { return }
            if let directory = context.snapshotDirectory,
               let png = NSBitmapImageRep(cgImage: capture.image).representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("chess-\(key).png"))
            }
            report[key + "-capture"] = "\(capture.image.width)×\(capture.image.height) px of \(capture.frame)"
            report[key + "-words"] = await ScreenSight.lines(in: capture).map { "\($0.text) \($0.frame)" }
        }
        dump("ax")
        await snapshot("start")
        report["menus"] = MenuReader.items(pid: pid).map { $0.path + ($0.isEnabled ? "" : " (disabled)") + ($0.shortcut.map { " " + $0 } ?? "") }

        // Scripted steps, written on the mini between runs.
        let script = (try? Data(contentsOf: URL(fileURLWithPath: "/tmp/skilli-chess-probe.json")))
            .flatMap { try? JSONSerialization.jsonObject(with: $0) as? [[String: Any]] } ?? []
        for (index, step) in script.enumerated() {
            Self.makeFrontmost(pid: pid)
            await pause(200)
            let frame = UIReader.snapshot(pid: pid).frame ?? .zero
            func point(_ values: [Double], _ offset: Int) -> CGPoint {
                CGPoint(x: frame.minX + frame.width * values[offset], y: frame.minY + frame.height * values[offset + 1])
            }
            if let values = step["click"] as? [Double], values.count == 2 {
                await mouseClick(at: point(values, 0))
                log.append("\(index) click \(values) → \(point(values, 0))")
            } else if let values = step["drag"] as? [Double], values.count == 4 {
                await mouseDrag(from: point(values, 0), to: point(values, 2))
                log.append("\(index) drag \(values)")
            } else if let words = step["menu"] as? String {
                let item = MenuReader.items(pid: pid).first { $0.path.localizedCaseInsensitiveContains(words) }
                if let item { AXUIElementPerformAction(item.element, kAXPressAction as CFString) }
                log.append("\(index) menu \(words) → \(item?.path ?? "not found")")
            } else if let key = step["key"] as? String, let code = Int(key) {
                await pressKey(nil, code: CGKeyCode(code))
                log.append("\(index) key \(code)")
            } else if let square = step["press"] as? String {
                let button = Self.chessBoard(pid: pid).first { $0.square == square }
                let result = button.map { AXUIElementPerformAction($0.element, kAXPressAction as CFString).rawValue }
                log.append("\(index) press \(square) → \(result.map(String.init) ?? "not found")")
            } else if let square = step["clicksquare"] as? String, let rect = Self.chessBoard(pid: pid).first(where: { $0.square == square })?.rect {
                await mouseClick(at: CGPoint(x: rect.midX, y: rect.midY))
                log.append("\(index) clicksquare \(square) → \(rect)")
            } else if let squares = (step["dragsquares"] as? String)?.split(separator: ">").map(String.init), squares.count == 2,
                      let from = Self.chessBoard(pid: pid).first(where: { $0.square == squares[0] })?.rect,
                      let to = Self.chessBoard(pid: pid).first(where: { $0.square == squares[1] })?.rect {
                await mouseDrag(from: CGPoint(x: from.midX, y: from.midY), to: CGPoint(x: to.midX, y: to.midY))
                log.append("\(index) dragsquares \(squares)")
            }
            if let milliseconds = step["wait"] as? Int {
                await pause(milliseconds)
                log.append("\(index) wait \(milliseconds)")
            }
            if step["dump"] != nil {
                dump("ax-\(index)")
                log.append("\(index) dump")
            }
            if let file = step["capture"] as? String {
                await pause(600)
                await snapshot(file)
                log.append("\(index) captured \(file)")
            }
        }
        report["log"] = log
        if let directory = context.snapshotDirectory,
           let data = try? JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys]) {
            try? data.write(to: directory.appendingPathComponent("chess-probe.json"))
        }
        record(name, true, "\((report["ax"] as? [String])?.count ?? 0) Accessibility nodes, \((report["start-read"] as? [String])?.count ?? 0) read by do it here, \((report["start-words"] as? [String])?.count ?? 0) lines of words; \(log)", nil)
    }

    /// Every node under `element`: role, subrole, title, description,
    /// value, identifier, frame, actions; 3,000 nodes at most.
    private static func axTree(_ element: AXUIElement, depth: Int, into lines: inout [String]) {
        guard lines.count < 3_000, depth < 16 else { return }
        AXUIElementSetMessagingTimeout(element, 0.5)
        func string(_ attribute: String) -> String? {
            var value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(element, attribute as CFString, &value) == .success, let value else { return nil }
            if let text = value as? String { return text.isEmpty ? nil : String(text.prefix(120)) }
            if let number = value as? NSNumber { return number.stringValue }
            if CFGetTypeID(value) == AXValueGetTypeID() {
                let axValue = unsafeDowncast(value, to: AXValue.self)
                var point = CGPoint.zero, size = CGSize.zero
                if AXValueGetValue(axValue, .cgPoint, &point) { return "\(Int(point.x)),\(Int(point.y))" }
                if AXValueGetValue(axValue, .cgSize, &size) { return "\(Int(size.width))×\(Int(size.height))" }
            }
            return nil
        }
        var actions: CFArray?
        AXUIElementCopyActionNames(element, &actions)
        var line = String(repeating: "  ", count: depth) + (string(kAXRoleAttribute) ?? "?")
        for (label, attribute) in [("sub", kAXSubroleAttribute), ("title", kAXTitleAttribute), ("desc", kAXDescriptionAttribute),
                                   ("value", kAXValueAttribute), ("help", kAXHelpAttribute), ("id", kAXIdentifierAttribute),
                                   ("at", kAXPositionAttribute), ("size", kAXSizeAttribute)] {
            if let text = string(attribute) { line += " \(label)=\(text)" }
        }
        if let names = actions as? [String], !names.isEmpty { line += " actions=\(names.joined(separator: ","))" }
        lines.append(line)
        var children: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &children) == .success,
              let list = children as? [AXUIElement] else { return }
        for child in list { axTree(child, depth: depth + 1, into: &lines) }
    }

    /// A real click at `point` (screen points, top-left origin).
    private func mouseClick(at point: CGPoint) async {
        let source = CGEventSource(stateID: .hidSystemState)
        for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(type == .mouseMoved ? 60 : 40)
        }
    }

    /// Press at `from`, move there in steps, release at `to`.
    private func mouseDrag(from: CGPoint, to: CGPoint) async {
        let source = CGEventSource(stateID: .hidSystemState)
        CGEvent(mouseEventSource: source, mouseType: .mouseMoved, mouseCursorPosition: from, mouseButton: .left)?.post(tap: .cghidEventTap)
        await pause(60)
        CGEvent(mouseEventSource: source, mouseType: .leftMouseDown, mouseCursorPosition: from, mouseButton: .left)?.post(tap: .cghidEventTap)
        await pause(80)
        for step in 1...12 {
            let t = CGFloat(step) / 12
            let point = CGPoint(x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t)
            CGEvent(mouseEventSource: source, mouseType: .leftMouseDragged, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(16)
        }
        CGEvent(mouseEventSource: source, mouseType: .leftMouseUp, mouseCursorPosition: to, mouseButton: .left)?.post(tap: .cghidEventTap)
        await pause(60)
    }

    /// The card where it shows, captured only over the self-test's own
    /// window `pid` (never the user's windows).
    private func captureCard(_ card: NSWindow, over pid: pid_t, as file: String) async -> String {
        guard let window = UIReader.snapshot(pid: pid).frame, let screen = NSScreen.screens.first else { return "no window" }
        // Accessibility's frame (top-left origin) in AppKit's coordinates.
        let frame = NSRect(x: window.minX, y: screen.frame.maxY - window.maxY, width: window.width, height: window.height)
        guard frame.contains(card.frame) else { return "not over the photos (card \(card.frame), window \(frame))" }
        guard let directory = context.snapshotDirectory, let image = await GlassCheck.screenshot(around: card, padding: 0),
              let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) else { return "no capture" }
        try? png.write(to: directory.appendingPathComponent(file))
        return file
    }

    /// "Exporte en PDF dans mes documents" in TextEdit and, where the Mac
    /// has it activated, Microsoft Word, through Ask with the user's
    /// decision key: routed to "do it here", which goes through the app's
    /// export or save dialog (its pop-ups, Documents) and saves. A scratch
    /// document; its PDF is removed after, and the app quits.
    private func controlExportsFromWord() async {
        await controlExports(in: URL(fileURLWithPath: "/System/Applications/TextEdit.app"), bundleID: "com.apple.TextEdit", name: "TextEdit")
        await controlExports(in: URL(fileURLWithPath: "/Applications/Microsoft Word.app"), bundleID: "com.microsoft.Word", name: "Word")
    }

    private func controlExports(in appURL: URL, bundleID: String, name app: String) async {
        let name = "Do it here in \(app): “exporte en PDF dans mes documents” through Ask puts the PDF in Documents"
        var keys: [DecisionProvider: String] = [:]
        for provider in DecisionProvider.allCases { keys[provider] = Keychain.read(account: provider.keychainAccount) }
        guard FileManager.default.fileExists(atPath: appURL.path), !keys.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: keys.isEmpty ? "no decision key saved in Settings" : "no \(app)", latencyMs: nil))
            return
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let stem = "skilli-test-\(UUID().uuidString.prefix(8))"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent(stem)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let source = folder.appendingPathComponent(stem + ".rtf")
        try? Data("{\\rtf1\\ansi Bonjour, ceci est un document de test de skil.li.}".utf8).write(to: source)
        let pdf = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Documents/\(stem).pdf")
        let popover = context.aiActions.popover
        defer {
            context.aiActions.decisionKeysOverride = nil
            try? FileManager.default.removeItem(at: folder)
            try? FileManager.default.removeItem(at: pdf)
            if !wasRunning { NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).forEach { $0.forceTerminate() } }
        }
        guard (try? await NSWorkspace.shared.open([source], withApplicationAt: appURL, configuration: NSWorkspace.OpenConfiguration())) != nil else {
            record(name, false, "\(app) did not open the document", nil)
            return
        }
        // The app up, the document's window in front.
        var pid: pid_t = 0
        let opened = await waitUntil(timeout: 40) {
            guard let running = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).first else { return false }
            pid = running.processIdentifier
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && UIReader.snapshot(pid: pid).window.contains(stem)
        } != nil
        guard opened else {
            await captureWindow(of: pid, as: "control-\(app.lowercased())-open.png")
            record(name, false, "\(app)'s window for the document did not come forward", nil)
            return
        }
        // Word without a licence opens documents read-only: nothing to export.
        let shown = UIReader.snapshot(pid: pid).elements.map(\.label).joined(separator: " ")
        if shown.contains("Activer Microsoft 365") || shown.contains("Activate Microsoft 365") {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "\(app) is not activated on this Mac: read-only", latencyMs: nil))
            return
        }
        context.aiActions.decisionKeysOverride = keys
        let start = ContinuousClock.now
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "exporte en PDF dans mes documents"])
        let exported = await waitUntil(timeout: 90) { FileManager.default.fileExists(atPath: pdf.path) } != nil
        let took = ContinuousClock.now - start
        _ = await waitUntil(timeout: 8) { !popover.isVisible }
        let control = context.aiActions.lastControl
        let card = "\(popover.shownTitle) · \(popover.shownStatus) — \(popover.shownText.prefix(400))"
        if !exported { await captureWindow(of: pid, as: "control-\(app.lowercased()).png") }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, exported,
               "PDF in Documents: \(exported) after \(took.compact); steps \(control?.history ?? []) (\(control?.decider ?? "no control")); "
                   + "pictures \(control?.pictures.map { "\($0.need.rawValue) \($0.tokens) tokens \($0.milliseconds) ms" } ?? []); card \(card)",
               Double(took.components.seconds * 1_000))
    }

    /// Self-test capture of another app's front window (Screen Recording).
    private func captureWindow(of pid: pid_t, as file: String) async {
        guard let directory = context.snapshotDirectory, ScreenSight.isAllowed,
              let content = try? await SCShareableContent.excludingDesktopWindows(true, onScreenWindowsOnly: true) else { return }
        let windows: [SCWindow] = content.windows.filter { $0.owningApplication?.processID == pid && $0.windowLayer == 0 }
        func area(_ window: SCWindow) -> CGFloat { window.frame.width * window.frame.height }
        guard let window = windows.max(by: { area($0) < area($1) }) else { return }
        let filter = SCContentFilter(desktopIndependentWindow: window)
        let configuration = SCStreamConfiguration()
        configuration.width = Int(filter.contentRect.width * CGFloat(filter.pointPixelScale))
        configuration.height = Int(filter.contentRect.height * CGFloat(filter.pointPixelScale))
        configuration.showsCursor = false
        guard let image = try? await SCScreenshotManager.captureImage(contentFilter: filter, configuration: configuration),
              let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) else { return }
        try? png.write(to: directory.appendingPathComponent(file))
    }

    /// Keep Awake as skil.li finds it at its next launch (an update, a
    /// crash): taken again until the same time, or until turned off; not
    /// when it ended meanwhile. Scratch defaults, never the user's.
    private func keepAwakeSurvivesARestart() async {
        let name = "Keep Awake taken again after skil.li restarts (timed and untimed), not once it ended"
        let suite = "skilli-selftest-awake-restart-\(getpid())"
        guard let defaults = UserDefaults(suiteName: suite) else {
            record(name, false, "no scratch defaults", nil)
            return
        }
        defer { defaults.removePersistentDomain(forName: suite) }
        // Timed: "awake 10 min", then a new launch.
        let before = SystemCommands(defaults: defaults)
        _ = before.keepAwake(.awake(seconds: 600))
        let until = before.awakeUntil
        let after = SystemCommands(defaults: defaults)
        after.restoreAwake()
        // Saved as seconds: the same end within a millisecond.
        let timed = after.isKeepingAwake && until.flatMap { until in after.awakeUntil.map { abs($0.timeIntervalSince(until)) < 0.001 } } == true
        _ = after.keepAwake(.allowSleep)
        _ = before.keepAwake(.allowSleep)
        let cleared = defaults.object(forKey: "SystemCommands.keepAwake") == nil
        // Untimed: Keep Awake on, then a new launch.
        let first = SystemCommands(defaults: defaults)
        _ = try? await first.run(.keepAwake)
        let second = SystemCommands(defaults: defaults)
        second.restoreAwake()
        let untimed = second.isKeepingAwake && second.awakeUntil == nil
        _ = second.keepAwake(.allowSleep)
        _ = first.keepAwake(.allowSleep)
        // Ended while skil.li was not running.
        defaults.set(Date.now.addingTimeInterval(-5).timeIntervalSince1970, forKey: "SystemCommands.keepAwake")
        let third = SystemCommands(defaults: defaults)
        third.restoreAwake()
        let ended = !third.isKeepingAwake && defaults.object(forKey: "SystemCommands.keepAwake") == nil
        record(name, timed && cleared && untimed && ended,
               "timed taken again until the same end: \(timed); cleared when sleep allowed: \(cleared); untimed taken again: \(untimed); ended meanwhile, left: \(ended)", nil)
    }

    /// Reminders kept in memory (never the Mac's own): said in the launcher
    /// and added (⌘Z takes back); the Reminders mode in Raycast's order, ↩
    /// checks one off where it is, ⇥ → Tomorrow moves one in place, ⌘⌫
    /// deletes; Ask adds one and lists today's; the four tools for agents.
    private func remindersSaidAndDone() async {
        let name = "Reminders: said and added (⌘Z takes back), the Reminders mode in order, ↩ done, ⇥ Tomorrow in place (⌘Z back), ⌘⌫ deletes at once (Undo ⌘Z); Ask adds and lists; tools"
        guard let book = context.launcher.reminders else {
            record(name, false, "no reminders", nil)
            return
        }
        let clock = Calendar.current
        let today = clock.startOfDay(for: .now)
        let tomorrow = clock.date(byAdding: .day, value: 1, to: today) ?? today
        let soon = Date.now.addingTimeInterval(2 * 3_600)
        book.testItems = [
            ReminderItem(id: "st-bill", title: "Payer la facture", due: clock.date(byAdding: .day, value: -1, to: today)),
            ReminderItem(id: "st-call", title: "Appeler Paul", due: soon, hasTime: true, priority: 1),
            ReminderItem(id: "st-bread", title: "Acheter du pain", list: "Courses")
        ]
        var opened = 0
        book.openedReminders = { opened += 1 }
        context.aiActions.decisionKeysOverride = [:]
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .auto
        defer {
            book.testItems = nil
            book.openedReminders = nil
            context.aiActions.decisionKeysOverride = nil
            settings.mode = mode
        }
        let launcher = context.launcher
        let popover = context.aiActions.popover

        // Said in the launcher, added, taken back.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "rappelle-moi d'arroser les plantes demain 9h" { await pressKey(character) }
        let offered = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Remind Me: Arroser les plantes" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let added = await waitUntil(timeout: 2) { popover.shownTitle == "Added to Reminders" && popover.hintTitles.contains("Undo") } != nil
        let addedDue = book.addedForTest.last?.due == tomorrow.addingTimeInterval(9 * 3_600)
        await pressKey(Character("z"), flags: .maskCommand)
        let takenBack = await waitUntil(timeout: 1) { book.testItems?.contains { $0.title == "Arroser les plantes" } == false } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // The mode: overdue, today, no date; ↩ checks the first off.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "todo " { await pressKey(character) }
        let ordered = await waitUntil(timeout: 2) { launcher.resultTitles == ["Payer la facture", "Appeler Paul", "Acheter du pain"] } != nil
        let order = launcher.resultTitles
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let checked = await waitUntil(timeout: 1) {
            book.testItems?.first { $0.id == "st-bill" }?.isCompleted == true && launcher.resultTitles.first == "Payer la facture"
        } != nil
        // The footer follows the row: Not Done on the one just checked off,
        // Done on the next once ↓ selects it.
        let checkedFooter = launcher.shownFooter.first ?? ""
        // ⇥ on the second: ⌘K's list, "tom" ↩: Tomorrow, same time.
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        let footerFollows = await waitUntil(timeout: 1) { launcher.shownFooter.first == "Done ↩" } != nil && checkedFooter == "Not Done ↩"
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let actions = await waitUntil(timeout: 2) { launcher.shownActions.contains { $0.title == "Tomorrow" } } != nil
        // Its day before the move, for ⌘Z.
        let callBefore = book.testItems?.first(where: { $0.id == "st-call" })?.due
        for character in "tom" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let expected = clock.date(byAdding: .day, value: 1, to: soon).map { clock.date(bySetting: .second, value: 0, of: $0) } ?? nil
        let moved = await waitUntil(timeout: 2) {
            guard let due = book.testItems?.first(where: { $0.id == "st-call" })?.due, let expected else { return false }
            return abs(due.timeIntervalSince(expected)) < 61 && clock.isDate(due, inSameDayAs: expected)
        } != nil
        // Where it is: the launcher stays, the row selected, no card.
        let inPlace = launcher.isVisible && !launcher.isShowingActions && launcher.selectedResultTitle == "Appeler Paul" && !popover.isVisible
        // ⌘Z puts it back on its day.
        await pressKey(Character("z"), flags: .maskCommand)
        let movedBack = await waitUntil(timeout: 1) { book.testItems?.first(where: { $0.id == "st-call" })?.due == callBefore } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        // ⌘⌫ deletes at once, nothing asked: the undo card says so (⌘Z
        // and ↩ in `reminderDeleteUndoes`).
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "todo pain" { await pressKey(character) }
        _ = await waitUntil(timeout: 2) { launcher.resultTitles.first == "Acheter du pain" }
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let deleted = await waitUntil(timeout: 1) { book.testItems?.contains { $0.id == "st-bread" } == false } != nil
        let offeredUndo = await waitUntil(timeout: 2) {
            popover.shownTitle == "Reminder Deleted" && popover.shownText.contains("Acheter du pain") && popover.hintKeys == ["⌘Z", "esc"]
        } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        // Ask: added at once, then today's list.
        // Ask, with what the model reads (`plansRead`).
        func ask(_ text: String, _ plan: [String: String]) async -> Bool {
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            textView.string = ""
            guard await openAsk() else { return false }
            plansRead(plan)
            for character in text { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return true
        }
        let binsSaid = "rappelle-moi de sortir les poubelles ce soir"
        _ = await ask(binsSaid, words(binsSaid, "title", from: "sortir", to: "poubelles").merging(
            ["plan": "remind", "when": "at", "day": "today", "hour": "none", "part_of_day": "evening"]) { $1 })
        let askAdded = await waitUntil(timeout: 2) { popover.shownTitle == "Added to Reminders" } != nil
            && book.addedForTest.last?.title == "Sortir les poubelles"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        // Unsure when: what it understood, added with ↩ only.
        // Typed in lowercase: the test's keys type no capitals.
        let callSaid = "rappelle-moi d'appeler paul demain à 9h"
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        guard await openAsk() else { return }
        plansRead(words(callSaid, "title", from: "appeler", to: "paul")
            .merging(["plan": "remind", "when": "at", "day": "tomorrow", "hour": "9", "minute": "0"]) { $1 }, unsure: ["hour"])
        for character in callSaid { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let countBefore = book.addedForTest.count
        let checkedFirst = await waitUntil(timeout: 2) {
            popover.shownTitle == "Add This Reminder?" && popover.shownText.contains("Appeler paul") && popover.hintTitles == ["Add", "Cancel"]
        } != nil && book.addedForTest.count == countBefore
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let addedAfterReturn = await waitUntil(timeout: 2) { book.addedForTest.last?.title == "Appeler paul" } != nil
        // What the card just showed is not said again: it goes.
        let notSaidTwice = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = await ask("mes rappels", ["plan": "todo"])
        plansRead(nil)
        let listed = await waitUntil(timeout: 2) { popover.shownTitle == "Reminders" && popover.shownText.contains("Sortir les poubelles") } != nil
        await saveScreenshot(of: popover.window, as: "reminders-today.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let openedApp = await waitUntil(timeout: 1) { opened > 0 } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        // For agents: changes wait for Return in the card.
        func approved(_ tool: String, _ arguments: String) async -> (status: Int32, output: String) {
            async let call = skilliCall(tool, arguments)
            _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
            await pause(150)
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return await call
        }
        let created = await skilliCall("create_reminder", #"{"title":"Renouveler le passeport","priority":"high","list":"Reminders"}"#)
        let id = created.output.range(of: #"id (added-[^)]+)"#, options: .regularExpression).map { String(created.output[$0].dropFirst(3)) } ?? ""
        let found = await skilliCall("list_reminders", #"{"query":"passeport"}"#)
        let updated = await approved("update_reminder", #"{"id":"\#(id)","done":"true"}"#)
        let removed = await approved("delete_reminder", #"{"id":"\#(id)"}"#)
        let agents = created.output.hasPrefix("Added “Renouveler le passeport”") && found.output.contains("priority !!!")
            && updated.output.contains("done") && removed.output == "Deleted “Renouveler le passeport”."
        record(name, offered && added && addedDue && takenBack && ordered && checked && footerFollows && actions && moved && deleted && offeredUndo && askAdded
               && inPlace && movedBack && checkedFirst && addedAfterReturn && notSaidTwice && listed
               && openedApp && agents,
               "offered: \(offered), added: \(added) due right: \(addedDue), ⌘Z: \(takenBack); order \(order) (\(ordered)), ↩ done: \(checked), footer follows the row: \(footerFollows) (“\(checkedFooter)” then Done ↩), ⇥ \(actions) → tomorrow: \(moved) in place \(inPlace), ⌘Z back \(movedBack), ⌘⌫ deleted at once: \(deleted), undo card: \(offeredUndo); Ask added: \(askAdded), unsure asked first: \(checkedFirst), ↩ added: \(addedAfterReturn), not said twice: \(notSaidTwice), listed: \(listed), ↩ Reminders: \(openedApp); agents: \(agents) (\(found.output.suffix(90)))",
               nil)
    }

    /// Settings → Reminders at work, in memory: today's count and the next
    /// one in the menu bar; "en partant du bureau" rings at the saved place,
    /// an unknown place says where to add it; "ce mail" takes the message
    /// selected in Mail (a stand-in) and its link back.
    private func remindersInMenuBarPlacesAndMail() async {
        let name = "Reminders: today's in the menu bar, at a saved place (arriving or leaving), home from the card when none is saved, the message in Mail and its link"
        guard let book = context.launcher.reminders else {
            record(name, false, "no reminders", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.remindersMenuBar, preferences.reminderPlaces)
        let clock = Calendar.current
        let today = clock.startOfDay(for: .now)
        book.testItems = [
            ReminderItem(id: "st-late", title: "Payer la facture", due: clock.date(byAdding: .day, value: -1, to: today)),
            ReminderItem(id: "st-today", title: "Appeler Paul", due: today, hasTime: false),
            ReminderItem(id: "st-later", title: "Plus tard", due: clock.date(byAdding: .day, value: 3, to: today))
        ]
        context.aiActions.decisionKeysOverride = [:]
        context.aiActions.mailSelection = { ("Devis Lumière", URL(string: "message://%3Cabc123@lumiere.example%3E")!) }
        defer {
            book.testItems = nil
            preferences.remindersMenuBar = saved.0
            preferences.reminderPlaces = saved.1
            context.aiActions.decisionKeysOverride = nil
            context.aiActions.mailSelection = { MailSelection.selected() }
            context.reminderWatch.refresh()
        }
        preferences.remindersMenuBar = .countAndNext
        preferences.reminderPlaces = [SavedPlace(name: "Bureau", address: "1 rue du Test, Paris", latitude: 48.86, longitude: 2.35)]
        let watch = context.reminderWatch
        watch.refresh()
        let inMenuBar = await waitUntil(timeout: 2) { watch.shownTitle == " 2 · Payer la facture" } != nil
        let menuTitle = watch.shownTitle ?? ""

        let popover = context.aiActions.popover
        // Ask, with what the model reads (`plansRead`).
        func ask(_ text: String, _ plan: [String: String]) async -> Bool {
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            textView.string = ""
            guard await openAsk() else { return false }
            plansRead(plan)
            for character in text { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return true
        }
        let breadSaid = "rappelle-moi d'acheter du pain en partant du bureau"
        _ = await ask(breadSaid, words(breadSaid, "title", from: "acheter", to: "pain")
            .merging(phrase(breadSaid, "place", "bureau", longest: 4)) { $1 }
            .merging(["plan": "remind", "when": "none", "place_when": "leaving"]) { $1 })
        let atPlace = await waitUntil(timeout: 2) { popover.shownTitle == "Added to Reminders" } != nil
            && book.addedForTest.last?.place == ReminderPlace(name: "bureau", arriving: false)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let bagSaid = "rappelle-moi de prendre mon sac en arrivant au gymnase"
        _ = await ask(bagSaid, words(bagSaid, "title", from: "prendre", to: "sac")
            .merging(phrase(bagSaid, "place", "gymnase", longest: 4)) { $1 }
            .merging(["plan": "remind", "when": "none", "place_when": "arriving"]) { $1 })
        let unknown = await waitUntil(timeout: 2) { popover.phase == .failed && popover.shownText.contains("Settings → Reminders") } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        // No place saved as "maison": the card's Home address, found on the
        // map (a stand-in here), as Apple's Reminders does.
        var cardHome = false
        var cardDetail = "no contacts book"
        if let contacts = context.aiActions.contacts, let tools = context.tools.settingTools {
            let savedGeocode = tools.geocode
            contacts.testMeAddresses = [.home: "12 rue des Lilas, 75011 Paris, France"]
            tools.geocode = { address in address.hasPrefix("12 rue des Lilas") ? (48.8566, 2.3522) : nil }
            let plantsSaid = "rappelle-moi d'arroser les plantes en arrivant à la maison"
            _ = await ask(plantsSaid, words(plantsSaid, "title", from: "arroser", to: "plantes")
                .merging(phrase(plantsSaid, "place", "maison", longest: 4)) { $1 }
                .merging(["plan": "remind", "when": "none", "place_when": "arriving"]) { $1 })
            let added = await waitUntil(timeout: 3) { popover.shownTitle == "Added to Reminders" } != nil
            let place = book.lastPlace
            cardHome = added && place?.place.name == "Home" && place?.place.address.hasPrefix("12 rue des Lilas") == true
                && place?.arriving == true && abs((place?.place.latitude ?? 0) - 48.8566) < 0.001
            cardDetail = "\(added), \(place.map { "\($0.place.name) \($0.place.address) arriving \($0.arriving)" } ?? "no place")"
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            contacts.testMeAddresses = nil
            tools.geocode = savedGeocode
        }
        let mailSaid = "rappelle-moi de repondre a ce mail demain"
        _ = await ask(mailSaid, words(mailSaid, "title", from: "repondre", to: "mail")
            .merging(["plan": "remind", "when": "at", "day": "tomorrow", "hour": "none", "part_of_day": "none", "with": "mail"]) { $1 })
        plansRead(nil)
        let mailed = await waitUntil(timeout: 2) { popover.shownTitle == "Added to Reminders" } != nil
            && book.addedForTest.last?.url == "message://%3Cabc123@lumiere.example%3E" && book.addedForTest.last?.notes == "Devis Lumière"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, inMenuBar && atPlace && unknown && cardHome && mailed,
               "menu bar “\(menuTitle)”: \(inMenuBar); leaving the office: \(atPlace); unknown place said so: \(unknown); "
                   + "home from the card: \(cardHome) (\(cardDetail)); this email linked: \(mailed)", nil)
    }

    /// A real EventKit fetch that finds nothing (reminders done a day from
    /// now): its answer comes on EventKit's own queue, which stopped the app
    /// when the block was main-actor isolated. Nothing of the user's read.
    private func eventKitAnswersOffTheMainActor() async {
        let name = "Reminders: EventKit's answer on its own queue keeps the app running (a fetch that finds nothing)"
        guard let book = context.launcher.reminders else { return }
        let found = await book.fetchNothing()
        record(name, found == 0, "fetched \(found) (none expected), the app still runs", nil)
    }

    /// Ask by Voice on the real microphone for two seconds, then stopped:
    /// its tap runs on AVFoundation's audio queue (it stopped the app on
    /// the developer's Mac every time). Only how much was heard is kept, never the
    /// words. Skipped without a microphone.
    private func microphoneHeardForReal() async {
        let name = "Ask by Voice: the real microphone for 2 s (its audio queue), stopped cleanly"
        guard AVCaptureDevice.default(for: .audio) != nil, AVCaptureDevice.authorizationStatus(for: .audio) == .authorized else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no microphone allowed on this Mac", latencyMs: nil))
            return
        }
        let input = VoiceInput()
        input.language = "fr"
        do {
            try await input.start(status: { _ in })
        } catch {
            record(name, false, "did not start: \(error.localizedDescription)", nil)
            return
        }
        await pause(2_000)
        let heard = await input.stop()
        record(name, true, "listened 2 s and stopped; \(heard.count) characters heard (not kept)", nil)
    }

    private func askFindsContacts() async {
        let name = "Ask × Contacts: “qui est …” shows the card, “un mail à …” opens one (written when it says what), two close ones asked"
        guard let book = context.aiActions.contacts else {
            record(name, false, "no contacts", nil)
            return
        }
        func person(_ id: String, _ given: String, _ family: String, _ company: String, _ job: String, _ email: String) -> ContactRecord {
            var record = ContactRecord(id: id)
            record.givenName = given
            record.familyName = family
            record.organization = company
            record.jobTitle = job
            record.emails = [.init("work", email)]
            return record
        }
        book.testRecords = [person("st-1", "Jean-François", "Martin", "Lumière", "Directeur technique", "jf.martin@lumiere.example"),
                            person("st-2", "Jean", "Dupont", "Lumière", "", "jean.dupont@lumiere.example"),
                            person("st-3", "François", "Leroy", "Horizon", "Acheteur", "francois.leroy@horizon.example")]
        var opened: [URL] = []
        context.aiActions.openURL = { opened.append($0) }
        context.aiActions.decisionKeysOverride = [:]
        // French typography: a no-break space before the colon.
        context.ai.testEngine = FakeTextEngine(chunks: ["Objet\u{00A0}: Commande\n\nBonjour François,\nLa commande arrive lundi.\nCamille"], delay: .milliseconds(20))
        defer {
            book.testRecords = nil
            context.aiActions.openURL = { NSWorkspace.shared.open($0) }
            context.aiActions.decisionKeysOverride = nil
            context.ai.testEngine = nil
        }
        let popover = context.aiActions.popover
        // Ask, with what the model reads (`plansRead`): who, which words
        // name them, whether it says what to write.
        func ask(_ text: String, _ kind: String, person: String, says: Bool = false) async -> Bool {
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            textView.string = ""
            guard await openAsk() else { return false }
            plansRead(phrase(text, "person", person).merging(["contact": kind, "says": says ? "yes" : "no"]) { $1 }, route: .contact)
            for character in text { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return true
        }
        guard await ask("qui est le contact jean francois qui travaille chez lumiere", "who", person: "jean francois qui travaille chez lumiere") else {
            record(name, false, "no question in the card", nil)
            return
        }
        let who = await waitUntil(timeout: 2) {
            popover.shownTitle == "Contact" && popover.shownContent != nil && self.context.aiActions.shownContact?.organization == "Lumière"
                && self.context.aiActions.shownContact?.jobTitle == "Directeur technique"
        } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        _ = await ask("cree un mail a francois de chez horizon", "mail", person: "francois de chez horizon")
        let empty = await waitUntil(timeout: 2) { opened.last?.absoluteString == "mailto:francois.leroy@horizon.example" } != nil

        _ = await ask("ecris a francois de chez horizon pour lui dire que la commande arrive lundi", "mail", person: "francois de chez horizon", says: true)
        let written = await waitUntil(timeout: 4) { opened.last?.absoluteString.contains("subject=Commande") == true } != nil
        let body = opened.last.flatMap { URLComponents(url: $0, resolvingAgainstBaseURL: false)?.queryItems?.first { $0.name == "body" }?.value } ?? ""
        // The subject said ("l'objet c'est…"): written too, never an empty mail.
        let before = opened.count
        _ = await ask("Écris un nouveau mail pour François de chez Horizon, l'objet c'est un nouveau contrat.", "mail", person: "François de chez Horizon", says: true)
        let subjectSaid = await waitUntil(timeout: 4) {
            opened.count > before && opened.last?.absoluteString.hasPrefix("mailto:francois.leroy@horizon.example?subject=Commande") == true
        } != nil

        _ = await ask("le numero de jean de chez lumiere", "who", person: "jean de chez lumiere")
        let asked = await waitUntil(timeout: 2) { popover.shownQuestion?.text == "Which one?" } != nil
        let options = popover.shownOptions
        await pressKey(nil, code: CGKeyCode(kVK_ANSI_2))
        let second = await waitUntil(timeout: 2) {
            popover.shownTitle == "Contact" && self.context.aiActions.shownContact?.name == (options.count > 1 ? String(options[1].split(separator: " · ").first ?? "") : "?")
        } != nil
        await pause(150)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        plansRead(nil)
        record(name, who && empty && written && body.hasPrefix("Bonjour François") && subjectSaid && asked && options.count == 2 && second,
               "who: \(who); empty mail: \(empty); written: \(written) (body “\(body.prefix(30))”); subject said → written: \(subjectSaid) "
                   + "(\(opened.last?.absoluteString.prefix(70) ?? "")); two close: \(asked) \(options), 2 picked: \(second)", nil)
    }

    /// Ask, routed to "rewrite": Return replaces the selection.
    private func askRewritesTheSelection() async {
        let name = "Ask: “corrige” rewrites the selection; Return replaces it"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: [Self.aiFixed], delay: .milliseconds(20))
        context.aiActions.routeOverride = .rewrite
        defer {
            context.ai.testEngine = nil
            context.aiActions.routeOverride = nil
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = Self.aiOriginal
        textView.selectAll(nil)
        await pause(60)
        _ = await hyperChord(["a"], trigger: Self.ownTriggerKeyCode)
        guard await waitUntil(timeout: 2, { popover.phase == .asking }) != nil else {
            record(name, false, "no question in the card", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        for character in "corrige" { await pressKey(character) }
