        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == Self.aiFixed } != nil
        record(name, done && replaced && context.aiActions.lastRoute == .rewrite, "text now “\(textView.string)”", nil)
    }

    /// A forgotten shortcut: the command is found by name in the launcher,
    /// and Enter runs it on the app that was in front.
    private func launcherFindsSICommands() async {
        let name = "Launcher: “spelling” finds Fix Spelling & Grammar, labelled SI Command (AI Command under the pointer); Enter runs it on the selection"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: [Self.aiFixed], delay: .milliseconds(20))
        defer { context.ai.testEngine = nil }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = Self.aiOriginal
        textView.selectAll(nil)
        await pause(60)
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        guard await waitUntil(timeout: 1, { self.context.launcher.isVisible }) != nil else {
            record(name, false, "launcher did not open", nil)
            return
        }
        for character in "spelling" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { self.context.launcher.topResultName == "Fix Spelling & Grammar" } != nil
        if let directory = context.snapshotDirectory, let png = context.launcher.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("launcher-command.png"))
        }
        guard listed else {
            let top = context.launcher.topResultName ?? "none"
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            record(name, false, "top result “\(top)”", nil)
            return
        }
        // SI, the brand's word, says AI under the pointer (website's si-label).
        let label = context.launcher.resultAccessories.first ?? ""
        var revealed = false
        if let frame = context.launcher.accessoryShown(row: 0)?.frame {
            let height = NSScreen.screens.first?.frame.height ?? 0
            let source = CGEventSource(stateID: .hidSystemState)
            let saved = NSEvent.mouseLocation
            func move(to point: NSPoint) {
                CGEvent(mouseEventSource: source, mouseType: .mouseMoved, mouseCursorPosition: CGPoint(x: point.x, y: height - point.y),
                        mouseButton: .left)?.post(tap: .cghidEventTap)
            }
            move(to: NSPoint(x: frame.maxX - 20, y: frame.midY))
            revealed = await waitUntil(timeout: 1) { self.context.launcher.accessoryShown(row: 0)?.text == "AI Command" } != nil
            await captureLauncher(as: "launcher-si-reveal.png")
            move(to: saved)
            _ = await waitUntil(timeout: 1) { self.context.launcher.accessoryShown(row: 0)?.text == "SI Command" }
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let done = await waitUntil(timeout: 3) { popover.phase == .done && popover.isVisible } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == Self.aiFixed } != nil
        record(name, label == "SI Command" && revealed && done && replaced,
               "row says “\(label)”, “AI Command” under the pointer: \(revealed); card done: \(done), text now “\(textView.string)”", nil)
    }

