    /// The user's decision keys, read only (skil.li's own Keychain items).
    private var userDecisionKeys: [DecisionProvider: String] {
        var keys: [DecisionProvider: String] = [:]
        for provider in DecisionProvider.allCases { keys[provider] = Keychain.read(account: provider.keychainAccount) }
        return keys
    }

    /// "Find" on a real app's menu (Finder), decided only — nothing is
    /// pressed. The Window menu and recent items are never sent.
    private func askFindsFinderMenus() async {
        guard let finder = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.finder").first else { return }
        let items = await Task.detached { MenuReader.shareableItems(pid: finder.processIdentifier) }.value
        let leaked = items.filter { !MenuCandidates.isShareable($0.components) }.count
        let cases: [(String, [String])] = [
            // macOS 26 says "Nouvelle fenêtre Finder", 27 "… de Finder".
            ("ouvre une nouvelle fenêtre du Finder", ["File > New Finder Window", "Fichier > Nouvelle fenêtre de Finder", "Fichier > Nouvelle fenêtre Finder"]),
            ("va dans le dossier Applications", ["Go > Applications", "Aller > Applications"])
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask finds Finder's menu items with \(provider.title) (decided only, nothing pressed)"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = leaked == 0 && !items.isEmpty
            var slowest: Duration = .zero
            for (instruction, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: items, keys: [provider: key])
                slowest = max(slowest, .now - start)
                let found = decision?.menu.first?.item.path ?? "nothing"
                passed = passed && (decision?.route == .find || decision?.route == .control) && expected.contains(found)
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed"), \(found) (\(Int((decision?.menu.first?.probability ?? 0) * 100))%)")
            }
            record(name, passed, "\(items.count) shareable items, \(leaked) private sent; " + details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// "Open": the user's own installed apps are the options; decided only,
    /// nothing is opened. The first case asked for: VectorCraft for "vector drawing".
    private func askOpensApps() async {
        let entries = await Task.detached { AppScanner.scan().map { ($0.name, $0.url) } }.value
        let apps = await Task.detached { AppCandidates.apps(entries) }.value
        var cases: [(String, Set<String>)] = [
            ("ouvre la calculatrice", ["Calculator", "Calculatrice"]),
            ("ouvre les réglages système", ["System Settings", "Réglages Système"])
        ]
        if apps.contains(where: { $0.name == "VectorCraft" }) {
            cases.insert(("lance mon app de dessin vectoriel", ["VectorCraft"]), at: 0)
        }
        for provider in DecisionProvider.allCases {
            let name = "Ask opens installed apps with \(provider.title) (decided only, nothing opened)"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = !apps.isEmpty
            var slowest: Duration = .zero
            for (instruction, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: apps,
                                                      settings: SystemSettingsPanes.all(), keys: [provider: key])
                slowest = max(slowest, .now - start)
                let picked = decision?.apps.first?.app.name ?? "nothing"
                passed = passed && decision?.route == .open && expected.contains(picked)
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed"), \(picked) (\(Int((decision?.apps.first?.probability ?? 0) * 100))%)")
            }
            record(name, passed, "\(apps.count) apps; " + details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// The card's side of "find", decided ahead: sure → chosen at once,
    /// its shortcut said once in a note; sure of an item that ends or
    /// deletes something (Delete) → the card, ↩ chooses it; unsure → the
    /// best three as keycaps, the one picked chosen at once; an item the
    /// app refuses → said in one line, never a beep.
    private func askFoundCardChooses() async {
        let name = "Ask “find”: sure, chosen at once (its shortcut said once); Delete waits for ↩; unsure, 1–3 keycaps, the pick chosen at once; refused, said in one line"
        let popover = context.aiActions.popover
        guard let element = Self.accessibilityButton(labelled: "Self-test Menu Item") else {
            record(name, false, "the stand-in button has no Accessibility element", nil)
            return
        }
        let sure = MenuReader.Item(path: "File > Export as PDF…", components: ["File", "Export as PDF…"], isEnabled: true, shortcut: "⇧⌘E", element: element)
        let other = MenuReader.Item(path: "File > Print…", components: ["File", "Print…"], isEnabled: true, shortcut: "⌘P", element: element)
        let delete = MenuReader.Item(path: "File > Delete", components: ["File", "Delete"], isEnabled: true, shortcut: "⌘⌫", element: element)
        defer { context.aiActions.decisionOverride = nil }
        func ask(_ text: String) async -> Bool {
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            textView.string = ""
            await pause(60)
            guard await openAsk() else { return false }
            for character in text { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            return true
        }
        func closeNote() async {
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
        }

        // Sure: chosen without ↩; the note teaches its shortcut.
        context.aiActions.decisionOverride = AskRouter.Decision(route: .find, confidence: 0.9, menu: [(sure, 0.93)], label: "Test")
        let before = menuStandInTarget.count
        guard await ask("export pdf") else {
            record(name, false, "no question in the card: phase \(popover.phase), visible \(popover.isVisible), card “\(popover.shownText)”", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        let atOnce = await waitUntil(timeout: 2) { self.menuStandInTarget.count == before + 1 } != nil
        let taught = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.contains("⇧⌘E") && popover.hintTitles == ["Close"] } != nil
        await pause(150)
        await saveScreenshot(of: popover.window, as: "ai-card-ask-found.png")
        let note = popover.shownText
        await closeNote()

        // Sure, but it deletes: the card says where, ↩ chooses it.
        context.aiActions.decisionOverride = AskRouter.Decision(route: .find, confidence: 0.9, menu: [(delete, 0.95)], label: "Test")
        _ = await ask("supprime le document")
        let held = await waitUntil(timeout: 2) { popover.phase == .done && popover.hintTitles == ["Choose", "Close"] } != nil
            && menuStandInTarget.count == before + 1
        let card = popover.shownText
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let chosen = await waitUntil(timeout: 2) { self.menuStandInTarget.count == before + 2 } != nil
        await closeNote()

        // Unsure: keycaps, 2 picks the second, chosen at once.
        context.aiActions.decisionOverride = AskRouter.Decision(route: .find, confidence: 0.4, menu: [(sure, 0.45), (other, 0.4)], label: "Test")
        _ = await ask("imprimer")
        let offered = await waitUntil(timeout: 2) { popover.shownQuestion?.text == "Which one?" } != nil
        await pause(150)
        await saveScreenshot(of: popover.window, as: "ai-card-ask-which.png")
        await pressKey(nil, code: CGKeyCode(kVK_ANSI_2))
        let picked = await waitUntil(timeout: 2) { self.menuStandInTarget.count == before + 3 } != nil
            && context.aiActions.lastMenuPath == "File > Print…"
        await closeNote()

        // Refused (an app gone): one line says so and what to do instead.
        let gone = Process()
        gone.executableURL = URL(fileURLWithPath: "/usr/bin/true")
        try? gone.run()
        gone.waitUntilExit()
        let deadElement = AXUIElementCreateApplication(gone.processIdentifier)
        AXUIElementSetMessagingTimeout(deadElement, 0.5)
        let refusedItem = MenuReader.Item(path: "File > Export as PDF…", components: ["File", "Export as PDF…"], isEnabled: true, shortcut: "⇧⌘E",
                                          element: deadElement)
        context.aiActions.decisionOverride = AskRouter.Decision(route: .find, confidence: 0.9, menu: [(refusedItem, 0.93)], label: "Test")
        _ = await ask("export pdf")
        let refused = await waitUntil(timeout: 3) {
            popover.isVisible && popover.shownText.contains("did not choose File › Export as PDF…") && popover.shownText.contains("⇧⌘E")
        } != nil
        let refusal = popover.shownText
        await closeNote()
        record(name, atOnce && taught && held && card.contains("File › Delete") && chosen && offered && picked && refused,
               "sure: chosen at once \(atOnce), note “\(note.replacingOccurrences(of: "\n", with: " ⏎ "))” \(taught); Delete held for ↩ \(held) “\(card.replacingOccurrences(of: "\n", with: " ⏎ "))”, ↩ chose it \(chosen); unsure offered three \(offered), 2 chose “\(context.aiActions.lastMenuPath ?? "none")” at once \(picked); refused: \(refused) “\(refusal)”", nil)
    }

    /// A value the request did not give, asked in the card with the
    /// model's readings given (`valuesOverride` for the request,
    /// `replyValuesOverride` for the answer): how long, which level, which
    /// app (and none of that name), how often, when, what about them; only
    /// the answer read, the rest kept; esc cancels; ↩ with nothing typed
    /// keeps Ask's question; a reading that failed says so with ↩.
    private func askAsksForWhatIsMissing() async {
        let name = "Ask asks in the card for what the request did not say (how long, which level, which app, how often, when, what about them), reads only that answer, keeps the rest; esc cancels; a failed reading offers ↩"
        let ai = context.aiActions
        let popover = ai.popover
        let timers = context.timers
        var details: [String] = []
        var passed = true
        defer {
            ai.decisionOverride = nil
            ai.valuesOverride = nil
            ai.replyValuesOverride = nil
        }
        func say(_ sentence: String, _ route: AskRoute, appAction: AskRouter.AppAction? = nil, command: MacAction? = nil,
                 values: [String: String]?, reply: [String: String]? = nil, sure: Double = 0.95) async {
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
            ai.decisionOverride = AskRouter.Decision(route: route, confidence: 0.95, menu: [], routes: [(route, 0.95)],
                                                     command: command.map { ($0, 0.93) }, commands: command.map { [($0, 0.93)] } ?? [],
                                                     appAction: appAction, label: "Test")
            ai.valuesOverride = values?.mapValues { AskValues.Answer(choice: $0, confidence: 0.95) } ?? [:]
            ai.replyValuesOverride = reply?.mapValues { AskValues.Answer(choice: $0, confidence: sure) }
            ai.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": sentence])
        }
        // Shown: a hidden card keeps its last question (the run before's).
        func asked(_ prefix: String) async -> Bool {
            await waitUntil(timeout: 3) {
                popover.isVisible && popover.phase == .asking && popover.shownQuestion?.text.hasPrefix(prefix) == true
            } != nil
        }
        func answer(_ text: String) async {
            for character in text { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
        }
        func check(_ what: String, _ ok: Bool, _ detail: String = "") {
            passed = passed && ok
            details.append("\(ok ? "✓" : "✗") \(what)" + (detail.isEmpty ? "" : " (\(detail))"))
        }
        func shown() -> String {
            "“\(popover.shownTitle)” \(popover.phase) “\(popover.shownQuestion?.text ?? popover.shownText.prefix(80).description)”, above “\(popover.shownContext ?? "")”"
        }
        guard await focusTestWindow() else { return }

        // A timer: how long, typed; only that answer read; what for kept.
        for timer in timers.timers { timers.cancel(timer.id) }
        let sentence = "mets un minuteur pour le test"
        let spans = AskValues.spans(of: sentence)
        let none = ["length": "none", "until_hour": "none", "until_minute": "none", "label": "phrase \(spans.firstIndex(of: "test") ?? 0)"]
        await say(sentence, .timer, values: none, reply: ["length": "10 min", "until_hour": "none", "until_minute": "none"])
        let lengthAsked = await asked("How long?")
        let aboveIt = popover.shownContext == "“\(sentence)”"
        await saveScreenshot(of: popover.window, as: "ai-card-ask-missing.png")
        await answer("dix minutes")
        let started = await waitUntil(timeout: 2) { timers.timers.contains { $0.seconds == 600 && $0.label == "Test" } } != nil
        let alone = ai.lastValuesRead == "dix minutes"
        let quiet = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        check("timer: how long asked under the request, “dix minutes” read alone, started 10 min for Test, nothing said",
              lengthAsked && aboveIt && started && alone && quiet, "read “\(ai.lastValuesRead ?? "")”, timers \(timers.timers.map { "\($0.label) \($0.seconds)" })")
        for timer in timers.timers where timer.seconds == 600 { timers.cancel(timer.id) }

        // Not read: asked again, saying so; esc cancels, no timer.
        await say(sentence, .timer, values: none, reply: ["length": "none", "until_hour": "none", "until_minute": "none"])
        _ = await asked("How long?")
        await answer("bientot")
        let again = await waitUntil(timeout: 2) { popover.phase == .asking && popover.shownContext == "Not read in “bientot”: say it another way." } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let cancelled = await waitUntil(timeout: 1) { !popover.isVisible } != nil && timers.timers.isEmpty
        check("not read: asked again saying so; esc cancels", again && cancelled, shown())

        // More than a day: asked, saying a timer lasts a day at most.
        await say("un minuteur de deux jours", .timer, values: ["length": "48 h", "until_hour": "none", "until_minute": "none", "label": "none"])
        let capped = await asked("How long?") && popover.shownContext == "A timer lasts a day at most."
        check("two days: asked, a day at most", capped, shown())

        // Nothing read at all: said, ↩ asks again.
        await say(sentence, .timer, values: nil)
        let failed = await waitUntil(timeout: 2) { popover.phase == .failed && popover.hintTitles == ["Ask Again", "Close"] } != nil
        check("no reading: said, ↩ asks again", failed, shown())

        // A level: typed, read alone; the volume put back.
        if let original = SystemCommands.volume {
            let target = original == 30 ? 35 : 30
            await say("mets le son", .command, command: .volume(AskRouter.levelToRead), values: ["level": "none"], reply: ["level": "\(target)"])
            let levelAsked = await asked("Which level?")
            await answer("trente")
            let set = await waitUntil(timeout: 2) { SystemCommands.volume == target } != nil
            _ = try? SystemCommands.setVolume(original)
            check("volume: which level asked, set from the answer", levelAsked && set && ai.lastValuesRead == "trente", shown())
        }

        // An app to uninstall: typed; none of that name, asked again, saying so.
        let typedApp = "zzz selftest"
        let appPhrase = AskValues.phrases(of: AskValues.words(of: typedApp), longest: 4).firstIndex(of: typedApp) ?? 0
        await say("désinstalle", .command, appAction: .uninstall, values: ["target": "none"], reply: ["target": "phrase \(appPhrase)"])
        let appAsked = await asked("Which app?")
        await answer(typedApp)
        let notHere = await waitUntil(timeout: 2) {
            popover.phase == .asking && popover.shownQuestion?.text.hasPrefix("Which app?") == true
                && popover.shownContext == "No app named “\(typedApp)” on this Mac."
        } != nil
        check("uninstall: which app asked; none of that name said above the same question", appAsked && notHere, shown())

        // How often: keycaps; 1 is every day, the hour kept.
        let scheduled = "résume mes PR à 9h"
        await say(scheduled, .schedule, values: ["schedule_repeat": "none", "every_n": "none", "hour": "9", "minute": "0", "is_reminder": "no"]
            .merging(phrase(scheduled, "ask", "résume mes PR", longest: 8)) { $1 })
        let often = await asked("How often?") && popover.shownOptions.first == "Every day" && popover.shownOptions.count == 5
        await pressKey(nil, code: CGKeyCode(kVK_ANSI_1))
        let kept = await waitUntil(timeout: 2) {
            popover.shownTitle == "On a Schedule" && popover.shownText.contains("Every day at 9") && popover.hintTitles == ["Keep", "Cancel"]
        } != nil
        check("schedule: how often as keycaps, 1 every day at 9:00, kept only on ↩", often && kept, shown())

        // A reminder: when, typed; an unsure reading of it waits for ↩.
        let remind = "rappelle-moi d'appeler Paul"
        await say(remind, .plans, values: ["plan": "remind", "when": "at", "day": "none", "hour": "none", "repeat": "none", "place_when": "none",
                                           "with": "none", "priority": "none", "list": "none"].merging(words(remind, "title", from: "appeler", to: "Paul")) { $1 },
                  reply: ["when": "at", "day": "tomorrow", "hour": "9", "minute": "0", "part_of_day": "none", "delay": "none"], sure: 0.4)
        let whenAsked = await asked("When?")
        await answer("demain neuf heures")
        let understood = await waitUntil(timeout: 2) {
            popover.shownTitle == "Add This Reminder?" && popover.shownText.contains("Appeler Paul") && popover.hintTitles == ["Add", "Cancel"]
        } != nil
        check("reminder: when asked, what it says kept, unsure so ↩ adds", whenAsked && understood, shown())

        // A contact: what about them, keycaps; 1 shows the card.
        if let book = context.launcher.contacts {
            var paul = ContactRecord(id: "st-missing-paul")
            paul.givenName = "Paul"
            paul.familyName = "Durand"
            paul.emails = [.init("work", "paul.durand@example.com")]
            book.testRecords = [paul]
            let named = "Paul Durand"
            await say(named, .contact, values: ["contact": "none", "says": "no"].merging(phrase(named, "person", named)) { $1 })
            let kind = await asked("What about them?") && popover.shownOptions == ["Who they are", "Write them a mail"]
            await pressKey(nil, code: CGKeyCode(kVK_ANSI_1))
            let card = await waitUntil(timeout: 2) { popover.shownContent != nil && ai.shownContact?.familyName == "Durand" } != nil
            check("contact: what about them as keycaps, 1 shows the card", kind && card, shown())
            book.testRecords = nil
        }

        // Ask itself: ↩ with nothing typed keeps the question.
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = await waitUntil(timeout: 1) { !popover.isVisible }
        ai.decisionOverride = nil
        ai.valuesOverride = nil
        if await focusTestWindow(), await openAsk() {
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let stays = await waitUntil(timeout: 1.5) {
                popover.phase == .asking && popover.shownContext == "Type what skil.li should do, then press ↩."
            } != nil
            check("Ask with nothing typed: the question stays", stays, shown())
        } else {
            check("Ask with nothing typed: the question stays", false, "no question in the card")
        }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = await waitUntil(timeout: 1) { !popover.isVisible }
        record(name, passed, details.joined(separator: "; "), nil)
    }

    /// Aliases: "zz" then a space opens the emoji picker (the alias set for
    /// it); "zz" alone puts Emoji first with its keycap; ⌘K → Change Alias…
    /// takes a new one, typed in the list, ↩. The user's aliases are put back.
    private func aliasesOpenWhatTheyName() async {
        let name = "Aliases: alias + space opens its mode (esc goes back to the alias typed), alone it comes first with its keycap, ⌘K → Change Alias… sets another"
        let launcher = context.launcher
        let saved = context.preferences.launcherAliases
        defer { context.preferences.launcherAliases = saved }
        context.preferences.launcherAliases = [LauncherAlias(id: "cmd:emoji", alias: "zz", title: "Emoji")]
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "zz " { await pressKey(character) }
        let opened = await waitUntil(timeout: 2) { launcher.mode == .emoji } != nil
        // esc: back to the launcher with “zz” as typed before the mode.
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let back = await waitUntil(timeout: 1) { launcher.isVisible && launcher.mode == nil && launcher.query == "zz" } != nil
        await closeLauncher()
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "zz" { await pressKey(character) }
        let first = await waitUntil(timeout: 2) { launcher.shownAliases.first == "zz" } != nil
        await pressKey("k", flags: .maskCommand)
        let offered = await waitUntil(timeout: 1) { launcher.shownActions.contains { $0.title == "Change Alias “zz”…" } } != nil
        for character in "change" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        for character in "ze" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let changed = await waitUntil(timeout: 1) { self.context.preferences.launcherAliases.map(\.alias) == ["ze"] } != nil
        await closeLauncher()
        record(name, opened && back && first && offered && changed,
               "zz + space → emoji: \(opened); esc back to “zz”: \(back); zz first with its keycap: \(first); ⌘K offers Change Alias: \(offered); changed to ze: \(changed) \(context.preferences.launcherAliases.map(\.alias))", nil)
    }

    /// The Catalog: "?" (typed with the keys that type it on this layout)
    /// lists what skil.li does under its six groups, arrows step over a
    /// group's name, the header follows the group at the top; "? kill"
    /// puts Kill a Process first and Return opens Kill; "help" finds What
    /// skil.li Can Do, whose Timer types "timer " on Return; Clipboard
    /// History shows its prefix, an alias set for it and ✦C as keycaps, ⌘K
    /// offers its alias and its shortcut; nothing found says so; ⌫ on the
    /// empty field leaves. Captured light and dark.
    private func catalogListsWhatSkilliDoes() async {
        let name = "Catalog: “?” lists what skil.li does by group; “? kill” puts Kill a Process first, ↩ opens Kill; prefix, alias and shortcut as keycaps; ⌘K"
        let launcher = context.launcher
        let saved = context.preferences.launcherAliases
        defer { context.preferences.launcherAliases = saved }
        context.preferences.launcherAliases = [LauncherAlias(id: "cmd:clipboardHistory", alias: "zc", title: "Clipboard History")]
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        guard await typeCharacter("?") else {
            await closeLauncher()
            record(name, false, "no key types “?” on this keyboard layout", nil)
            return
        }
        let opened = await waitUntil(timeout: 1) { launcher.isInCatalog } != nil
        let groups = launcher.shownCatalogGroups
        let grouped = groups == CatalogEntry.Group.allCases.map(\.title)
        let topHeader = launcher.headerText
        let rows = launcher.resultTitles.count
        let mismatches = launcher.catalogRowMismatches
        let misdrawnTop = launcher.catalogCellMismatches
        await captureLauncherBothWays(as: "launcher-catalog")
        // Down the list: over the next group's name to its first row, then
        // on until the header above the list names that group. Find's rows
        // counted, not written down: a feature added there moves Kill.
        let findRows = FeatureCatalog.entries().filter { $0.group == .find }.count
        for _ in 0..<findRows { await pressKey(nil, code: CGKeyCode(kVK_DownArrow)) }
        let overHeader = await waitUntil(timeout: 1) { launcher.selectedResultTitle == "Kill a Process" } != nil
        let misdrawn = launcher.catalogCellMismatches
        await captureLauncherBothWays(as: "launcher-catalog-group")
        for _ in 0..<9 { await pressKey(nil, code: CGKeyCode(kVK_DownArrow)) }
        let followed = await waitUntil(timeout: 1) { launcher.headerText == "Do" } != nil
        let skippedHeaders = !CatalogEntry.Group.allCases.map(\.title).contains(launcher.selectedResultTitle ?? "")
        await captureLauncherBothWays(as: "launcher-catalog-scrolled")

        for character in " kill" { await pressKey(character) }
        let killFirst = await waitUntil(timeout: 1) { launcher.selectedResultTitle == "Kill a Process" && launcher.resultTitles.first == "Kill a Process" } != nil
        let killKeys = launcher.shownCatalogKeys["Kill a Process"] ?? []
        let misdrawnKill = launcher.catalogCellMismatches
        await captureLauncherBothWays(as: "launcher-catalog-kill")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let killMode = await waitUntil(timeout: 1) { launcher.isKilling } != nil
        await closeLauncher()

        // Found by its name, the command opens it; a row that needs words
        // puts their start in the field.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        for character in "help" { await pressKey(character) }
        let command = await waitUntil(timeout: 1) { launcher.selectedResultTitle == "What skil.li Can Do" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let fromCommand = await waitUntil(timeout: 1) { launcher.isInCatalog } != nil
        for character in "timer" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.selectedResultTitle == "Timer" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let typed = await waitUntil(timeout: 1) { !launcher.isInCatalog && launcher.query == "timer " } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        _ = await typeCharacter("?")
        for character in "clipboard" { await pressKey(character) }
        var clipKeys: [[String]] = []
        let keycaps = await waitUntil(timeout: 1) {
            clipKeys = launcher.shownCatalogKeys["Clipboard History"] ?? []
            return clipKeys.count == 3 && clipKeys[0] == ["cb"] && clipKeys[1] == ["zc"] && clipKeys[2].first?.hasPrefix("✦") == true
        } != nil
        await captureLauncherBothWays(as: "launcher-catalog-keys")
        await pressKey("k", flags: .maskCommand)
        let actions = await waitUntil(timeout: 1) {
            let titles = launcher.shownActions.map(\.title)
            return titles.contains("Change Alias “zc”…") && titles.contains("Change Shortcut…")
        } != nil
        let shownActions = launcher.shownActions.map(\.title)
        await captureLauncherBothWays(as: "launcher-catalog-actions")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        for _ in 0..<"clipboard".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }
        // Nothing fits: the list says so, the footer has no key (⇥ never
        // asks in a mode); ⇥ does nothing, ⌘K says why in the footer's
        // place, the next key takes the line away.
        for character in "zqxj" { await pressKey(character) }
        let nothing = await waitUntil(timeout: 1) { launcher.resultTitles.isEmpty } != nil
        await captureLauncherBothWays(as: "launcher-catalog-nothing")
        let emptyFooter = launcher.shownFooter.isEmpty
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        await pause(300)
        let tabStayed = launcher.isVisible && launcher.isInCatalog && !context.aiActions.popover.isVisible
        await pressKey("k", flags: .maskCommand)
        let said = await waitUntil(timeout: 1) { launcher.shownNote?.hasPrefix("No row to act on") == true } != nil
        await captureLauncherBothWays(as: "launcher-note")
        for _ in 0..<"zqxj".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }
        let noteGone = launcher.shownNote == nil
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        let left = await waitUntil(timeout: 1) { !launcher.isInCatalog && launcher.isVisible } != nil
        await closeLauncher()

        let passed = opened && grouped && topHeader == "Find" && mismatches.isEmpty && misdrawnTop.isEmpty && overHeader && misdrawn.isEmpty && followed && skippedHeaders && killFirst && misdrawnKill.isEmpty && killKeys == [["kill"]]
            && killMode && command && fromCommand && typed && keycaps && actions && nothing && emptyFooter && tabStayed && said && noteGone && left
        record(name, passed,
               "opened: \(opened), \(rows) rows; groups \(groups); header “\(topHeader)”; rows that are not their launcher row: \(mismatches); drawn as another at the top: \(misdrawnTop); "
               + "↓ over the Do header to Kill a Process: \(overHeader), rows drawn as another: \(misdrawn), header followed to Do: \(followed), headers skipped: \(skippedHeaders); “? kill” first: \(killFirst), drawn as another: \(misdrawnKill), keys \(killKeys); ↩ → Kill: \(killMode); "
               + "“help” finds the command: \(command), ↩ opens the Catalog: \(fromCommand); Timer ↩ types “timer ”: \(typed); "
               + "Clipboard History keys \(clipKeys): \(keycaps); ⌘K \(shownActions): \(actions); “zqxj” lists nothing: \(nothing), footer empty: \(emptyFooter), ⇥ asked nothing: \(tabStayed), ⌘K said a line: \(said), gone with ⌫: \(noteGone); ⌫ left: \(left); launcher-note-light/-dark.png", nil)
    }

    /// Every launcher command, snippet and quicklink takes a shortcut: each
    /// "?" entry's action names it back through its id (a command's is its
    /// `shortcutID`), the ids shortcuts.json files hold (✦C's
    /// "clipboard.history") still load, Do It Here and Ask on a Schedule
    /// have none (theirs was Ask's), no two entries share one. With keys:
    /// "? search snippets", ⌘K → Set Shortcut… records ⌥⇧⌘9 in the card;
    /// pressed in the test window it opens the launcher in Snippets, again
    /// closes it. A snippet's shortcut types it there; a quicklink's opens
    /// the launcher with its keyword typed, again closes it.
    private func catalogShortcutsReachEverything() async {
        let name = "Catalog shortcuts: every launcher command, snippet and quicklink takes one; ⌘K → Set Shortcut… on Search Snippets records it, pressed it opens Snippets, again closes; a snippet's types it; a quicklink's types its keyword"
        let launcher = context.launcher
        let store = context.shortcuts
        let popover = context.aiActions.popover
        let library = context.snippets
        let snippet = library.save(Snippet(id: "", name: "Selftest Shortcut Snippet", keyword: "", text: "Typed by its shortcut"))
        guard let quicklink = launcher.quicklinks?().first(where: { $0.takesQuery && !$0.keyword.isEmpty }) else {
            library.delete(snippet.id)
            return record(name, false, "no quicklink with a keyword", nil)
        }
        let flags: CGEventFlags = [.maskCommand, .maskAlternate, .maskShift]
        let actions: [SkilliAction] = [.launcherCommand(.searchSnippets), .snippet(snippet.id), .quicklink(quicklink.id)]
        // A shortcut there before gets its keys back; one added goes.
        let had = actions.map { action in
            store.entryID(for: action).map { id in (id: id, chords: store.config.shortcuts.first { $0.id == id }?.chords) }
        }
        defer {
            for (action, had) in zip(actions, had) {
                if let had {
                    try? store.setKeys(had.chords, for: had.id)
                } else if let id = store.entryID(for: action) {
                    store.remove(id)
                }
            }
            library.delete(snippet.id)
            textView.string = ""
        }

        // Every entry, made things included: its action, and back from its id.
        let entries = FeatureCatalog.entries(FeatureCatalog.Input(snippets: [snippet], quicklinks: [quicklink]))
        var problems: [String] = []
        var owners: [String: String] = [:]
        for entry in entries {
            let action = entry.shortcutAction(skillies: [])
            switch entry.run {
            case .command(let command):
                if action?.id != command.shortcutID { problems.append("\(entry.title): \(action?.id ?? "none")") }
            case .snippet, .quicklink:
                if action == nil { problems.append("\(entry.title): none") }
            default:
                break
            }
            guard let action else { continue }
            if SkilliAction(id: action.id) != action { problems.append("\(entry.title): \(action.id) does not name it back") }
            if let owner = owners.updateValue(entry.title, forKey: action.id) { problems.append("\(entry.title) shares \(action.id) with \(owner)") }
        }
        for id in ["catalog.doItHere", "catalog.askSchedule"] where entries.first(where: { $0.id == id })?.shortcutAction(skillies: []) != nil {
            problems.append("\(id) records Ask's shortcut")
        }
        let saved: [String: SkilliAction] = ["clipboard.history": .clipboardHistory, "emoji.search": .searchEmoji, "settings.open": .openSettings,
                                             "menus.search": .searchMenus, "gifs.search": .searchGIFs, "clipboard.sequence": .pasteInSequence]
        for (id, action) in saved where SkilliAction(id: id) != action { problems.append("“\(id)” no longer loads") }
        if !SkilliAction.launcherCommand(.searchSnippets).runsInline || SkilliAction.launcherCommand(.quit).runsInline {
            problems.append("only what opens the launcher runs inline")
        }

        // ⌘K → Set Shortcut… on Search Snippets: the card asks, the next keys are it.
        guard await openLauncher(), await typeCharacter("?") else {
            await closeLauncher()
            return record(name, false, "no launcher, or no key types “?” here; \(problems)", nil)
        }
        for character in "search snippets" { await pressKey(character) }
        let selected = await waitUntil(timeout: 1) { launcher.selectedResultTitle == "Search Snippets" } != nil
        await pressKey("k", flags: .maskCommand)
        let offered = await waitUntil(timeout: 1) { launcher.shownActions.contains { $0.title == "Set Shortcut…" } } != nil
        for character in "set shortcut" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.shownActions.first?.title == "Set Shortcut…" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let asked = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.hasPrefix("Press the keys for Search Snippets") } != nil
        await pressKey("9", flags: flags)
        let said = await waitUntil(timeout: 3) { popover.shownText.hasSuffix("runs Search Snippets.") } != nil
        let saidText = popover.shownText
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        await closeLauncher()

        // Pressed where the user types: Snippets, then closed again.
        guard await focusTestWindow() else { return }
        await pressKey("9", flags: flags)
        let opened = await waitUntil(timeout: 2) { launcher.isVisible && launcher.isInSnippets } != nil
        if opened { await captureLauncherBothWays(as: "launcher-shortcut-snippets") }
        await pressKey("9", flags: flags)
        let closed = await waitUntil(timeout: 1) { !launcher.isVisible } != nil
        await closeLauncher()

        /// Records `keys` for `action` as the Keys pane does (its recorder).
        func recorded(_ action: SkilliAction, _ key: Character) async -> Bool {
            let id = store.entryID(for: action) ?? store.add(action)
            store.beginRecording(id)
            await pressKey(key, flags: flags)
            _ = await waitUntil(timeout: 3) { store.recordingID != id }
            if store.recordingID == id { store.cancelRecording() }
            return store.config.shortcuts.first { $0.id == id }?.chords != nil
        }
        // A snippet's: typed in the test window.
        let snippetKeys = await recorded(.snippet(snippet.id), "8")
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        await pressKey("8", flags: flags)
        let typed = await waitUntil(timeout: 2) { self.textView.string == snippet.text } != nil
        let typedText = textView.string
        // A quicklink's: its keyword in the launcher, then closed again.
        let linkKeys = await recorded(.quicklink(quicklink.id), "7")
        guard await focusTestWindow() else { return }
        textView.string = ""
        await pressKey("7", flags: flags)
        let keyword = await waitUntil(timeout: 2) { launcher.isVisible && launcher.mode == nil && launcher.query == quicklink.keyword + " " } != nil
        let shownQuery = launcher.query
        await pressKey("7", flags: flags)
        let linkClosed = await waitUntil(timeout: 1) { !launcher.isVisible } != nil
        await closeLauncher()

        record(name, problems.isEmpty && selected && offered && asked && said && opened && closed && snippetKeys && typed && linkKeys && keyword && linkClosed,
               "entries' actions: \(problems.isEmpty ? "all named back, none shared" : "\(problems)"); “? search snippets”: \(selected), ⌘K Set Shortcut…: \(offered), "
               + "card asked: \(asked), said: \(said) “\(saidText)”\(store.lastError.map { " refused: \($0.message)" } ?? ""); pressed: Snippets \(opened), again closed \(closed); "
               + "snippet's keys: \(snippetKeys), typed: \(typed) “\(typedText)”; \(quicklink.name)'s keys: \(linkKeys), launcher on “\(shownQuery)”: \(keyword), again closed: \(linkClosed); "
               + "launcher-shortcut-snippets-light/-dark.png", nil)
    }

    // MARK: - Links

    /// Every Catalog row has a `skilli://` link (⌘K → Copy Link): Clipboard
    /// History's from the "?", opened, opens the history; Left Half's runs
    /// at once; a quicklink's with its query opens its address; Lock
    /// Screen's (a command that takes the Mac away) asks in the card first,
    /// and esc runs nothing; a link skil.li does not know says so.
    private func linksRunWhatTheyName() async {
        let name = "Links: ⌘K → Copy Link on a Catalog row and a launcher row; opened, the link runs it (Clipboard History, Left Half, a quicklink's query); Lock Screen's asks first (esc: nothing runs); an unknown link says so"
        guard let links = context.links else {
            record(name, false, "no link runner", nil)
            return
        }
        let launcher = context.launcher
        let actions = context.actions
        let popover = context.aiActions.popover
        let (dryURLs, dryLinks) = (actions.dryRunURLs, links.dryRun)
        actions.dryRunURLs = true
        defer {
            actions.dryRunURLs = dryURLs
            links.dryRun = dryLinks
        }
        /// ⌘K on the selected row, Copy Link (or `action`) run; the pasteboard.
        func copyLink(_ action: String = "Copy Link", capture: String? = nil) async -> String? {
            NSPasteboard.general.clearContents()
            await pressKey("k", flags: .maskCommand)
            guard await waitUntil(timeout: 1, { launcher.shownActions.map(\.title).contains(action) }) != nil else {
                await closeLauncher()
                return nil
            }
            if let capture { await captureLauncherBothWays(as: capture) }
            // Its words up to the first sign ("copy skil"): "." takes ⇧ on AZERTY.
            for character in action.lowercased().prefix(while: { $0.isLetter || $0 == " " }) { await pressKey(character) }
            _ = await waitUntil(timeout: 1) { launcher.selectedActionTitle == action }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            var copied: String?
            _ = await waitUntil(timeout: 1) {
                copied = NSPasteboard.general.string(forType: .string)
                return copied != nil && !launcher.isVisible
            }
            return copied
        }
        /// The launcher on `typed`, the row `title` selected.
        func select(_ title: String, typing typed: String, catalog: Bool = false) async -> Bool {
            guard await openLauncher() else { return false }
            if catalog {
                guard await typeCharacter("?") else { return false }
                _ = await waitUntil(timeout: 1) { launcher.isInCatalog }
            }
            for character in typed { await pressKey(character) }
            var index: Int?
            _ = await waitUntil(timeout: 2) {
                index = launcher.resultTitles.firstIndex(of: title)
                return index != nil
            }
            guard let index else { return false }
            for _ in 0..<index { await pressKey(nil, code: CGKeyCode(kVK_DownArrow)) }
            return await waitUntil(timeout: 1) { launcher.selectedResultTitle == title } != nil
        }

        // A Catalog row's link, opened: it runs.
        var clipboardLink: String?
        if await select("Clipboard History", typing: "clipboard", catalog: true) {
            clipboardLink = await copyLink(capture: "launcher-copy-link")
        }
        var historyOpened = false
        if let clipboardLink, let url = URL(string: clipboardLink) {
            await links.openNow(url)
            historyOpened = await waitUntil(timeout: 2) { launcher.isVisible && launcher.isInClipboard } != nil
            await closeLauncher()
        }

        // A Mac command's row: Left Half runs at once (the test window moves).
        var leftLink: String?
        if await select("Left Half", typing: "left half") { leftLink = await copyLink() }
        guard await focusTestWindow() else { return }
        let frame = window.frame
        var placed = false
        if let leftLink, let url = URL(string: leftLink) {
            await links.openNow(url)
            placed = await waitUntil(timeout: 2) { self.window.frame != frame && links.log.last == "ran system:window.leftHalf" } != nil
        }
        window.setFrame(frame, display: true)

        // A quicklink's link, with what was typed for it.
        var quicklinkLink: String?
        if await select("Google · skilli links", typing: "g skilli links") { quicklinkLink = await copyLink("Copy skil.li Link") }
        var searched = false
        if let quicklinkLink, let url = URL(string: quicklinkLink) {
            await links.openNow(url)
            searched = await waitUntil(timeout: 1) { actions.lastURL == "https://www.google.com/search?q=skilli%20links" } != nil
        }

        // Lock Screen's link asks first; esc: nothing runs (and dry anyway).
        var lockLink: String?
        if await select("Lock Screen", typing: "lock screen") { lockLink = await copyLink() }
        links.dryRun = true
        var asked = false
        var declined = false
        guard await focusTestWindow() else { return }
        if let lockLink, let url = URL(string: lockLink) {
            let opening = Task { await links.openNow(url) }
            asked = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.contains("Lock Screen") && popover.shownText.contains("link") } != nil
            if asked {
                let testAppearance = window.appearance
                for (suffix, appearance) in GlassCheck.appearances {
                    popover.window.appearance = appearance
                    window.appearance = appearance
                    await pause(600)
                    await saveScreenshot(of: popover.window, as: "link-asks-\(suffix).png")
                }
                popover.window.appearance = nil
                window.appearance = testAppearance
            }
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            await opening.value
            declined = links.log.suffix(2) == ["asked system:lockScreen", "declined system:lockScreen"]
        }
        _ = await waitUntil(timeout: 1) { !popover.isVisible }

        // A link skil.li does not know.
        var unknown = false
        if let url = URL(string: "skilli://nothing/here") {
            await links.openNow(url)
            unknown = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.contains("does not know this link") } != nil
            if unknown { await saveScreenshot(of: popover.window, as: "link-unknown.png") }
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
        }

        let passed = clipboardLink == "skilli://run/cmd:clipboardHistory" && historyOpened && leftLink == "skilli://run/system:window.leftHalf" && placed
            && quicklinkLink == "skilli://quicklink/g?q=skilli%20links" && searched && lockLink == "skilli://run/system:lockScreen" && asked && declined
            && unknown
        record(name, passed,
               "“?” Clipboard History: \(clipboardLink ?? "nothing copied"), opened → history: \(historyOpened); Left Half: \(leftLink ?? "nothing copied"), ran at once: \(placed); "
                   + "“g skilli links”: \(quicklinkLink ?? "nothing copied"), opened Google: \(searched); Lock Screen: \(lockLink ?? "nothing copied"), asked: \(asked), esc declined: \(declined); "
                   + "unknown link said: \(unknown); log \(links.log.suffix(8)); launcher-copy-link-light/-dark.png, link-asks-light/-dark.png, link-unknown.png", nil)
    }

    /// D6: Always ⌘↩ in a link's card trusts that entry only: its next
    /// link runs at once, another entry's still asks. Settings → Catalog →
    /// Trusted Links lists it; − (what its button calls) asks again. What
    /// asks anyway is never trusted; Paste in Sequence's card offers no
    /// Always and ⌘↩ there allows once. Dry run: nothing runs.
    private func linksTrustedPerEntry() async {
        let name = "Links: Always ⌘↩ trusts that entry only (next link runs at once, Sleep still asks); listed in Settings → Catalog → Trusted Links, − asks again; Empty Trash… never trusted; Paste in Sequence asks without Always"
        guard let links = context.links else {
            record(name, false, "no link runner", nil)
            return
        }
        let popover = context.aiActions.popover
        let tools = context.tools.settings
        let saved = tools.linkTrust.links
        let dry = links.dryRun
        links.dryRun = true
        defer {
            links.dryRun = dry
            for link in tools.linkTrust.links where !saved.contains(link) { tools.removeTrustedLink(link) }
        }
        /// Opens `link`; whether the card asked, its keys, then `key` pressed
        /// (nil: none) and what the runner logged meanwhile.
        func open(_ link: String, press key: (code: Int, flags: CGEventFlags)?) async -> (asked: Bool, hints: [String], text: String, log: [String]) {
            guard let url = URL(string: link) else { return (false, [], "", []) }
            let before = links.log.count
            let opening = Task { await links.openNow(url) }
            let asked = await waitUntil(timeout: 1.5) { popover.isVisible && popover.phase == .approving } != nil
            let hints = asked ? popover.shownHints : []
            let text = asked ? popover.shownText : ""
            if asked, let key { await pressKey(nil, code: CGKeyCode(key.code), flags: key.flags) }
            if asked, key == nil { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            await opening.value
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
            return (asked, hints, text, Array(links.log.dropFirst(before)))
        }
        guard await focusTestWindow() else { return }
        let lock = "skilli://run/system:lockScreen"

        // First: asked with Always; ⌘↩ trusts it.
        let first = await open(lock, press: (kVK_Return, .maskCommand))
        let offered = first.hints == ["Allow", "Always", "Deny"] && first.text.contains("Always: links run it at once")
        let trusted = first.log == ["asked system:lockScreen", "always system:lockScreen", "ran system:lockScreen"]
            && tools.linkTrust.trusts("system:lockScreen")
        // Next: at once, no card.
        let again = await open(lock, press: nil)
        let atOnce = !again.asked && again.log == ["ran system:lockScreen"]
        // Another entry still asks.
        let sleep = await open("skilli://run/system:sleep", press: nil)
        let othersAsk = sleep.asked && sleep.log == ["asked system:sleep", "declined system:sleep"]
        // Paste in Sequence: no Always, ⌘↩ allows once, nothing kept.
        let paste = await open("skilli://run/cmd:pasteInSequence", press: (kVK_Return, .maskCommand))
        let pasteOnce = paste.asked && paste.hints == ["Allow", "Deny"] && !paste.text.contains("Always")
            && paste.log == ["asked cmd:pasteInSequence", "ran cmd:pasteInSequence"] && !tools.linkTrust.trusts("cmd:pasteInSequence")
        // What asks in its own card anyway: never kept.
        let anyway = SystemCommand.allCases.filter(\.asksAnyway)
        let refused = anyway.allSatisfy { !tools.trustLink(.system($0), entry: "system:\($0.rawValue)", title: $0.rawValue) }
            && !tools.trustLink(.settings("general"), entry: "settings:general", title: "General")

        // Settings → Catalog lists it, at the pane's end.
        let listed = tools.linkTrust.byTitle.map(\.title)
        let settings = context.settings
        settings.show(pane: .catalog)
        await pause(800)
        settings.show(pane: .catalog, section: "quicklinks")
        let atEnd = await waitUntil(timeout: 3) { settings.paneAtEnd } != nil || settings.scrollPaneToBottom()
        await pause(300)
        await captureSettingsBothWays(as: "settings-catalog-trusted-links")
        settings.scrollPaneToTop()
        await closeSettings()
        // − asks again.
        if let link = tools.linkTrust.links.first(where: { $0.entry == "system:lockScreen" }) { tools.removeTrustedLink(link) }
        guard await focusTestWindow() else { return }
        let removed = await open(lock, press: nil)
        let asksAgain = removed.asked && removed.log == ["asked system:lockScreen", "declined system:lockScreen"]

        record(name, offered && trusted && atOnce && othersAsk && pasteOnce && refused && listed == ["Lock Screen"] && asksAgain,
               "first: \(first.hints), Always said: \(offered), log \(first.log); next at once: \(atOnce) \(again.log); Sleep asks: \(othersAsk); "
                   + "Paste in Sequence: \(paste.hints) \(paste.log), kept: \(tools.linkTrust.trusts("cmd:pasteInSequence")); asks-anyway refused: \(refused); "
                   + "listed \(listed), at the pane's end: \(atEnd); after −: \(removed.log); settings-catalog-trusted-links-light/-dark.png", nil)
    }

    // MARK: - Do it here from anywhere

    /// `skilli://do` (docs/do-it-here-from-anywhere.md), dry (nothing is
    /// done): asked first, naming the goal and a link; esc declines; a link
    /// that came meanwhile is dropped once the one before was declined,
    /// never asked; Always ⌘↩ trusts that goal in that app (the next runs
    /// at once, the same goal in another app asks); an empty goal says so.
    private func doLinksAskTrustAndChain() async {
        let name = "Do links: asked first (the goal, “link”), esc declines; one that came meanwhile dropped, never asked; Always ⌘↩ trusts that goal in that app only; no goal or too long a goal said"
        guard let links = context.links else {
            record(name, false, "no link runner", nil)
            return
        }
        let popover = context.aiActions.popover
        let tools = context.tools.settings
        let saved = tools.linkTrust.links
        let dry = links.dryRun
        links.dryRun = true
        defer {
            links.dryRun = dry
            for link in tools.linkTrust.links where !saved.contains(link) { tools.removeTrustedLink(link) }
        }
        func url(_ goal: String, app: String? = nil) -> URL { SkilliLink.doHere(goal: goal, app: app).url }
        /// Opens `urls` back to back; once the card asks, `key` (nil: esc);
        /// whether it asked, its text and keys, what the runner logged.
        func open(_ urls: [URL], press key: (code: Int, flags: CGEventFlags)?, capture: String? = nil) async -> (asked: Bool, text: String, hints: [String], log: [String]) {
            let before = links.log.count
            let opening = urls.map { url in Task { await links.openNow(url) } }
            let asked = await waitUntil(timeout: 1.5) { popover.isVisible && popover.phase == .approving } != nil
            let text = asked ? popover.shownText : ""
            let hints = asked ? popover.shownHints : []
            if asked, let capture {
                let testAppearance = window.appearance
                for (suffix, appearance) in GlassCheck.appearances {
                    popover.window.appearance = appearance
                    window.appearance = appearance
                    await pause(600)
                    await saveScreenshot(of: popover.window, as: "\(capture)-\(suffix).png")
                }
                popover.window.appearance = nil
                window.appearance = testAppearance
            }
            if asked { await pressKey(nil, code: CGKeyCode(key?.code ?? kVK_Escape), flags: key?.flags ?? []) }
            for task in opening { await task.value }
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
            return (asked, text, hints, Array(links.log.dropFirst(before)))
        }
        guard await focusTestWindow() else { return }
        let export = "exporte en PDF dans mes documents"
        // Asked, esc: declined.
        let first = await open([url(export, app: "TextEdit")], press: nil, capture: "do-link-asks")
        let askedRight = first.asked && first.text.contains("“\(export)”") && first.text.contains("TextEdit") && first.text.contains("link")
            && first.hints == ["Allow", "Always", "Deny"]
        let declined = first.log == ["asked do \(export)", "declined do \(export)"]
        // A chain: the second link waits, then is dropped, never asked.
        guard await focusTestWindow() else { return }
        let reveal = "ouvre le dossier Documents depuis le menu Aller"
        let chain = await open([url(export, app: "TextEdit"), url(reveal, app: "Finder")], press: nil)
        let dropped = chain.log == ["asked do \(export)", "declined do \(export)", "dropped do \(reveal)"]
        // Always: that goal in that app, at once from then on.
        guard await focusTestWindow() else { return }
        let always = await open([url(export, app: "TextEdit")], press: (kVK_Return, .maskCommand))
        let trusted = always.log == ["asked do \(export)", "always do \(export)", "did do \(export)"]
            && tools.linkTrust.askDo(goal: export, app: "TextEdit") == .runs
        let again = await open([url(export, app: "TextEdit")], press: nil)
        let atOnce = !again.asked && again.log == ["did do \(export)"]
        guard await focusTestWindow() else { return }
        let elsewhere = await open([url(export, app: "Pages")], press: nil)
        let othersAsk = elsewhere.asked && elsewhere.log == ["asked do \(export)", "declined do \(export)"]
        let listed = tools.linkTrust.byTitle.map(\.shown).contains("Do It Here · “\(export)”, “TextEdit”")
        // No goal.
        let before = links.log.count
        await links.openNow(URL(string: "skilli://do?goal=")!)
        let empty = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.contains("says nothing to do") } != nil
            && Array(links.log.dropFirst(before)) == ["empty do"]
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !popover.isVisible }
        // Too long to show whole: not run, not asked.
        let long = links.log.count
        await links.openNow(url(String(repeating: "exporte en PDF ", count: 25)))
        let tooLong = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.contains("too long to show") } != nil
            && Array(links.log.dropFirst(long)) == ["long do"]
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !popover.isVisible }
        record(name, askedRight && declined && dropped && trusted && atOnce && othersAsk && listed && empty && tooLong,
               "asked: \(askedRight) “\(first.text.prefix(160))” \(first.hints), esc: \(first.log); chain: \(chain.log); Always: \(always.log), next: \(again.log); "
                   + "in Pages: \(elsewhere.log); listed: \(listed); no goal: \(empty); too long: \(tooLong); do-link-asks-light/-dark.png", nil)
    }

    /// The measure (docs/do-it-here-from-anywhere.md): a skillie whose two
    /// lines open `skilli://do` links through macOS, as any script would:
    /// TextEdit exports its document to Documents as a PDF, then Finder
    /// opens Documents, one after the other. The two goals trusted first
    /// (their card is `doLinksAskTrustAndChain`'s); the user's decision
    /// keys and writer. A scratch document; its PDF is removed after.
    private func doLinksChainTwoApps() async {
        let name = "Do links from a skillie: two `open skilli://do` lines through macOS — TextEdit exports to Documents as a PDF, then Finder opens Documents"
        guard let links = context.links else {
            record(name, false, "no link runner", nil)
            return
        }
        let keys = userDecisionKeys
        let textEdit = URL(fileURLWithPath: "/System/Applications/TextEdit.app")
        guard !keys.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no decision key saved in Settings", latencyMs: nil))
            return
        }
        let export = "exporte en PDF dans mes documents"
        let reveal = "ouvre le dossier Documents depuis le menu Aller"
        let tools = context.tools.settings
        let saved = tools.linkTrust.links
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").isEmpty
        let stem = "skilli-test-\(UUID().uuidString.prefix(8))"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent(stem)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let source = folder.appendingPathComponent(stem + ".rtf")
        try? Data("{\\rtf1\\ansi Bonjour, ceci est un document de test de skil.li.}".utf8).write(to: source)
        let pdf = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Documents/\(stem).pdf")
        let skillie = folder.appendingPathComponent("export-and-show.sh")
        try? """
        #!/bin/bash
        # @skilli.schemaVersion 1
        # @skilli.title Export and Show
        # @skilli.mode silent
        open "\(SkilliLink.doHere(goal: export, app: "TextEdit").url.absoluteString)"
        open "\(SkilliLink.doHere(goal: reveal, app: "Finder").url.absoluteString)"
        """.write(to: skillie, atomically: true, encoding: .utf8)
        let popover = context.aiActions.popover
        var cameForward = 0
        let observer = NSWorkspace.shared.notificationCenter.addObserver(forName: NSWorkspace.didActivateApplicationNotification, object: nil, queue: .main) { note in
            guard (note.userInfo?[NSWorkspace.applicationUserInfoKey] as? NSRunningApplication)?.processIdentifier == getpid() else { return }
            MainActor.assumeIsolated { cameForward += 1 }
        }
        // As in the normal app: a link that brought skil.li forward hands
        // the focus back to the app a step acts in.
        let handsBack = links.handsFocusBack
        links.handsFocusBack = true
        defer {
            NSWorkspace.shared.notificationCenter.removeObserver(observer)
            links.handsFocusBack = handsBack
            links.opensFromMacOS = false
            context.aiActions.decisionKeysOverride = nil
            for link in tools.linkTrust.links where !saved.contains(link) { tools.removeTrustedLink(link) }
            try? FileManager.default.removeItem(at: folder)
            try? FileManager.default.removeItem(at: pdf)
            if !wasRunning { NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").forEach { $0.forceTerminate() } }
        }
        guard (try? await NSWorkspace.shared.open([source], withApplicationAt: textEdit, configuration: NSWorkspace.OpenConfiguration())) != nil else {
            record(name, false, "TextEdit did not open the document", nil)
            return
        }
        var pid: pid_t = 0
        guard await waitUntil(timeout: 30, {
            guard let running = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").first else { return false }
            pid = running.processIdentifier
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && UIReader.snapshot(pid: pid).window.contains(stem)
        }) != nil else {
            record(name, false, "TextEdit's window for the document did not come forward", nil)
            return
        }
        tools.trustDoLink(goal: export, app: "TextEdit", title: "Do It Here")
        tools.trustDoLink(goal: reveal, app: "Finder", title: "Do It Here")
        context.aiActions.decisionKeysOverride = keys
        links.opensFromMacOS = true
        let finder = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.finder").first
        // Documents already in front: the step would have nothing to do.
        if let finder, Self.isDocuments(AIActionController.focusedWindowTitle(pid: finder.processIdentifier)) {
            Self.closeFrontWindow(pid: finder.processIdentifier)
        }
        let before = links.log.count
        let start = ContinuousClock.now
        let ran = try? await ChildProcess.run(URL(fileURLWithPath: "/bin/bash"), [skillie.path], timeout: 10)
        let skillieTook = ContinuousClock.now - start
        // Each "do it here" as it goes, and when each step's sign showed.
        var controls: [ComputerControl] = []
        var exportedAt: Duration?
        var shownAt: Duration?
        _ = await waitUntil(timeout: 150) {
            if let control = context.aiActions.lastControl, !controls.contains(where: { $0 === control }) { controls.append(control) }
            if exportedAt == nil, FileManager.default.fileExists(atPath: pdf.path) { exportedAt = .now - start }
            if shownAt == nil, exportedAt != nil, let finder, NSWorkspace.shared.frontmostApplication?.processIdentifier == finder.processIdentifier,
               Self.isDocuments(AIActionController.focusedWindowTitle(pid: finder.processIdentifier)) {
                shownAt = .now - start
            }
            let log = links.log.dropFirst(before)
            return shownAt != nil && !popover.isVisible || log.contains { $0.hasPrefix("dropped") || $0.hasPrefix("missing") }
        }
        let log = Array(links.log.dropFirst(before))
        let card = popover.isVisible ? "\(popover.shownStatus) — \(popover.shownText.prefix(300))" : "gone"
        // TextEdit's scratch document only: Finder would show the Mac's own files.
        if exportedAt == nil { await captureWindow(of: pid, as: "do-chain.png") }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let finderTitle = finder.flatMap { AIActionController.focusedWindowTitle(pid: $0.processIdentifier) } ?? "none"
        // Documents' window closed again.
        if let finder, shownAt != nil { Self.closeFrontWindow(pid: finder.processIdentifier) }
        let steps = controls.map { "\($0.history) (\($0.decider))" }
        record(name, exportedAt != nil && shownAt != nil,
               "skillie ran in \(skillieTook.compact) (exit \(ran?.status ?? -1)); PDF in Documents after \(exportedAt.map { "\(Int($0.milliseconds)) ms" } ?? "never"), "
                   + "Finder on Documents after \(shownAt.map { "\(Int($0.milliseconds)) ms" } ?? "never") (“\(finderTitle)”); runs \(steps); log \(log); skil.li came forward \(cameForward)×; card \(card)",
               shownAt?.milliseconds)
    }

    /// `do_in_app` (docs/do-it-here-from-anywhere.md): an app not installed
    /// refused with list_apps; `Skilli call do_in_app` from a terminal, as
    /// an agent outside skil.li (the card asks, Return allows, the card is
    /// taken for the steps then free); a real Act agent (Claude Code, Haiku,
    /// Screen Controls) told to export TextEdit's document hands the goal
    /// to do_in_app. A scratch document; its PDF removed after each.
    private func doInAppForAgents() async {
        let name = "do_in_app: unknown app refused; `Skilli call do_in_app` from a terminal exports TextEdit's document to Documents; a real Act agent (Haiku) does it through do_in_app"
        let keys = userDecisionKeys
        guard !keys.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no decision key saved in Settings", latencyMs: nil))
            return
        }
        // Not installed: refused, said how to find one.
        var refused = ""
        do {
            refused = try await context.tools.tools.call("do_in_app", arguments: ["goal": "exporte en PDF", "app": "Nopeapp Xyz"], run: nil)
        } catch {
            refused = error.localizedDescription
        }
        let refusedRight = refused.contains("No app called “Nopeapp Xyz”") && refused.contains("list_apps")

        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").isEmpty
        let stem = "skilli-test-\(UUID().uuidString.prefix(8))"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent(stem)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let source = folder.appendingPathComponent(stem + ".rtf")
        try? Data("{\\rtf1\\ansi Bonjour, ceci est un document de test de skil.li.}".utf8).write(to: source)
        let pdf = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Documents/\(stem).pdf")
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .auto
        context.aiActions.decisionKeysOverride = keys
        await context.ai.refresh()
        defer {
            settings.mode = mode
            context.aiActions.decisionKeysOverride = nil
            try? FileManager.default.removeItem(at: folder)
            try? FileManager.default.removeItem(at: pdf)
            if !wasRunning { NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").forEach { $0.forceTerminate() } }
        }
        guard (try? await NSWorkspace.shared.open([source], withApplicationAt: URL(fileURLWithPath: "/System/Applications/TextEdit.app"),
                                                  configuration: NSWorkspace.OpenConfiguration())) != nil else {
            record(name, false, "TextEdit did not open the document", nil)
            return
        }
        var pid: pid_t = 0
        func textEditInFront() async -> Bool {
            await waitUntil(timeout: 30) {
                guard let running = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").first else { return false }
                pid = running.processIdentifier
                Self.makeFrontmost(pid: pid)
                return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && UIReader.snapshot(pid: pid).window.contains(stem)
            } != nil
        }
        /// Allows what the card asks (↩) until `done`, `limit` seconds at most.
        func allowing(until done: @escaping @MainActor () -> Bool, limit: Double) async -> Int {
            var approvals = 0
            var pressed: ContinuousClock.Instant?
            _ = await waitUntil(timeout: limit) {
                // One ↩ a card: the next only once that one had time to land.
                if popover.isVisible, popover.phase == .approving, approvals < 4, pressed.map({ .now - $0 > .milliseconds(1_000) }) ?? true {
                    approvals += 1
                    pressed = .now
                    Task { await self.pressKey(nil, code: CGKeyCode(kVK_Return)) }
                }
                return done()
            }
            return approvals
        }

        // From a terminal: `Skilli call`, an agent outside skil.li.
        var terminal = "not run"
        var terminalDone = false
        var terminalFreed = false
        if await textEditInFront(), let socket = context.tools.socketPath, let binary = Bundle.main.executableURL {
            let arguments = #"{"goal": "exporte en PDF dans mes documents", "app": "TextEdit"}"#
            let start = ContinuousClock.now
            let call = Task { try? await ChildProcess.run(binary, ["call", "do_in_app", arguments, "--socket", socket], timeout: 120) }
            let approvals = await allowing(until: { FileManager.default.fileExists(atPath: pdf.path) && !popover.isVisible }, limit: 125)
            // The answer comes when the process ends.
            let answer = await call.value
            let took = ContinuousClock.now - start
            terminalDone = answer?.status == 0 && FileManager.default.fileExists(atPath: pdf.path) && answer?.output.hasPrefix("Done in TextEdit") == true
            terminalFreed = await waitUntil(timeout: 3) { !popover.isVisible } != nil
            terminal = "exit \(answer?.status ?? -1) in \(Int(took.milliseconds)) ms, approvals \(approvals), “\(answer?.output.trimmingCharacters(in: .whitespacesAndNewlines).prefix(400) ?? "")”, card free after: \(terminalFreed)"
            try? FileManager.default.removeItem(at: pdf)
        }

        // A real Act agent, started in TextEdit as the user would.
        var agent = "not run"
        var agentDone = false
        if context.ai.subscription.binary == nil {
            agent = "no Claude Code on this Mac"
        } else if await textEditInFront() {
            let command = scratchCommand(prompt: "Exporte le document ouvert dans TextEdit en PDF dans mes documents. Puis réponds seulement : Fait.", output: .card)
            var act = command
            act.tools = ["screen"]
            act.model = .claude("haiku")
            context.aiCommands.save(act)
            defer { context.aiCommands.delete(command.id) }
            let start = ContinuousClock.now
            context.aiActions.run(act.id, triggeredAt: .now)
            let approvals = await allowing(until: { popover.phase == .done || popover.phase == .failed }, limit: 180)
            let took = ContinuousClock.now - start
            let steps = context.aiActions.lastSteps.map(\.title)
            let exported = FileManager.default.fileExists(atPath: pdf.path)
            agentDone = exported && popover.phase == .done && steps.contains("Do it in an app")
            agent = "PDF: \(exported) in \(Int(took.milliseconds / 1_000)) s, approvals \(approvals), steps \(steps), do it here \(context.aiActions.lastControl?.history ?? []), card \(popover.phase) “\(popover.shownText.prefix(200))”"
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        }
        record(name, refusedRight && terminalDone && terminalFreed && (agentDone || context.ai.subscription.binary == nil),
               "unknown app: \(refusedRight) “\(refused.prefix(160))”; terminal: \(terminal); agent: \(agent)", nil)
    }

    /// Skillies that wait for their step (docs/do-it-here-from-anywhere.md,
    /// 5): two skillies run as from the launcher, each calling
    /// `"$SKILLI_CLI" call do_in_app` and branching on its exit. The first's
    /// step asked in the skillie's own card, allowed (↩), done: its next
    /// branch taken, the PDF in Documents, its last line in the card. The
    /// second's declined (esc): the card goes back to the skillie, its other
    /// branch taken, nothing exported. Ask Before Changes, `do_in_app` not
    /// made Always. A scratch document; its PDF removed after.
    private func skilliesWaitForTheirStep() async {
        let name = "Skillies wait for their step: `$SKILLI_CLI call do_in_app` asked in the skillie's card; done → its next branch, declined → its other branch"
        let keys = userDecisionKeys
        guard !keys.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no decision key saved in Settings", latencyMs: nil))
            return
        }
        guard let socket = context.tools.socketPath else {
            record(name, false, "no tool server", nil)
            return
        }
        let export = "exporte en PDF dans mes documents"
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").isEmpty
        let stem = "skilli-test-\(UUID().uuidString.prefix(8))"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent(stem)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let source = folder.appendingPathComponent(stem + ".rtf")
        try? Data("{\\rtf1\\ansi Bonjour, ceci est un document de test de skil.li.}".utf8).write(to: source)
        let pdf = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Documents/\(stem).pdf")
        let branch = folder.appendingPathComponent("branch.txt")
        let told = folder.appendingPathComponent("told.txt")
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        let right = settings.override(for: SkilliTools.doInApp)
        settings.mode = .auto
        settings.setOverride(nil, for: SkilliTools.doInApp)
        context.aiActions.decisionKeysOverride = keys
        await context.ai.refresh()
        defer {
            settings.mode = mode
            settings.setOverride(right, for: SkilliTools.doInApp)
            context.aiActions.decisionKeysOverride = nil
            try? FileManager.default.removeItem(at: folder)
            try? FileManager.default.removeItem(at: pdf)
            if !wasRunning { NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").forEach { $0.forceTerminate() } }
        }
        guard (try? await NSWorkspace.shared.open([source], withApplicationAt: URL(fileURLWithPath: "/System/Applications/TextEdit.app"),
                                                  configuration: NSWorkspace.OpenConfiguration())) != nil else {
            record(name, false, "TextEdit did not open the document", nil)
            return
        }
        func textEditInFront() async -> Bool {
            await waitUntil(timeout: 30) {
                guard let running = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.TextEdit").first else { return false }
                Self.makeFrontmost(pid: running.processIdentifier)
                return NSWorkspace.shared.frontmostApplication?.processIdentifier == running.processIdentifier
                    && UIReader.snapshot(pid: running.processIdentifier).window.contains(stem)
            } != nil
        }
        // A skillie as a contributor writes it: the step, then a branch on its exit.
        func skillie(_ title: String) -> ScriptCommand? {
            let file = folder.appendingPathComponent(title.lowercased().replacingOccurrences(of: " ", with: "-") + ".sh")
            let text = """
            #!/bin/bash
            # @skilli.schemaVersion 1
            # @skilli.title \(title)
            # @skilli.mode compact
            printf '%s\\n' "$SKILLI_CLI" "$SKILLI_SOCKET" "$SKILLI_SKILLIE" > '\(told.path)'
            if said=$("$SKILLI_CLI" call do_in_app app=TextEdit goal="\(export)" 2>&1); then
              echo next > '\(branch.path)'
              echo "Exported: ${said%%$'\\n'*}"
            else
              echo other > '\(branch.path)'
              echo "Not exported: ${said%%$'\\n'*}"
            fi
            """
            try? text.write(to: file, atomically: true, encoding: .utf8)
            try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: file.path)
            return ScriptCommand.parse(text, path: file.path)
        }
        struct Run {
            var asked = "never"
            var branch = "none"
            var card = ""
            var title = ""
            var steps: [String] = []
        }
        /// Runs it as the launcher does, answers its step's card with `key`
        /// once (after the half second an unprompted card leaves to the
        /// app), then waits for its last line in the card.
        func run(_ command: ScriptCommand, answering key: Int, line: String) async -> Run {
            var result = Run()
            try? FileManager.default.removeItem(at: branch)
            guard await textEditInFront() else {
                result.card = "TextEdit's window did not come forward"
                return result
            }
            context.aiActions.runScript?(command, false)
            var seen: ContinuousClock.Instant?
            var answered = false
            _ = await waitUntil(timeout: 100) {
                if !answered, popover.isVisible, popover.phase == .approving {
                    if seen == nil {
                        seen = .now
                        result.asked = "“\(popover.shownTitle)”: \(popover.shownText.prefix(160))"
                    } else if let seen, .now - seen > .milliseconds(900) {
                        answered = true
                        Task { await self.pressKey(nil, code: CGKeyCode(key)) }
                    }
                }
                return FileManager.default.fileExists(atPath: branch.path) && popover.isVisible && popover.shownText.hasPrefix(line)
            }
            result.branch = (try? String(contentsOf: branch, encoding: .utf8))?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "none"
            result.card = popover.isVisible ? "\(popover.shownStatus) — \(popover.shownText.prefix(300))" : "gone"
            result.title = popover.shownTitle
            result.steps = context.aiActions.lastControl?.history ?? []
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 3) { !popover.isVisible }
            return result
        }

        guard let allowed = skillie("Export Then Say"), let declined = skillie("Decline Then Say") else {
            record(name, false, "the skillies could not be read", nil)
            return
        }
        let start = ContinuousClock.now
        let done = await run(allowed, answering: kVK_Return, line: "Exported: Done in TextEdit")
        let took = ContinuousClock.now - start
        let exported = FileManager.default.fileExists(atPath: pdf.path)
        let variables = ((try? String(contentsOf: told, encoding: .utf8)) ?? "").split(separator: "\n").map(String.init)
        try? FileManager.default.removeItem(at: pdf)
        let stopped = await run(declined, answering: kVK_Escape, line: "Not exported: The user declined")
        let notExported = !FileManager.default.fileExists(atPath: pdf.path)
        // Told the binary running it and its own tool server, never another.
        let toldRight = variables.count == 3 && variables[0] == Bundle.main.executablePath && variables[1] == socket && !variables[2].isEmpty
        let doneRight = done.branch == "next" && exported && done.asked.hasPrefix("“Export Then Say”") && done.title == "Export Then Say"
        let stoppedRight = stopped.branch == "other" && notExported && stopped.asked.hasPrefix("“Decline Then Say”") && stopped.title == "Decline Then Say"
        record(name, toldRight && doneRight && stoppedRight,
               "told: \(toldRight) \(variables.map { $0.prefix(80) }); done in \(Int(took.milliseconds)) ms: asked \(done.asked), branch \(done.branch), PDF \(exported), "
                   + "steps \(done.steps), card \(done.card); declined: asked \(stopped.asked), branch \(stopped.branch), nothing exported \(notExported), card \(stopped.card)",
               took.milliseconds)
    }

    /// A skillie stopped at its time limit stops the step it waits for
    /// (docs/do-it-here-from-anywhere.md, 5): its `do_in_app` left
    /// unanswered in its card, the limit (6 s here) ends the script and its
    /// `Skilli call` together (their process group), the approval goes and
    /// the card says the skillie failed. Then a script that ends at once,
    /// leaving behind a process that holds its output and ignores SIGTERM:
    /// killed at its limit (2 s) and 3 s more. Nothing gets past the
    /// approval: no decision key needed, no app touched.
    private func skillieStopsWithItsStep() async {
        let name = "A skillie stopped at its time limit stops its step: its `Skilli call` ends with it, the unanswered approval goes, the card says it failed (showsRunning false too)"
        guard let library = context.tools.tools.scripts else {
            record(name, false, "no skillies", nil)
            return
        }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-test-\(UUID().uuidString.prefix(8))")
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let file = folder.appendingPathComponent("wait-forever.sh")
        let callPID = folder.appendingPathComponent("call.pid")
        let text = """
        #!/bin/bash
        # @skilli.schemaVersion 1
        # @skilli.title Wait Forever
        # @skilli.mode compact
        "$SKILLI_CLI" call do_in_app app=TextEdit goal="exporte en PDF dans mes documents" &
        echo $! > '\(callPID.path)'
        wait
        echo "Never here."
        """
        try? text.write(to: file, atomically: true, encoding: .utf8)
        try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: file.path)
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        let right = settings.override(for: SkilliTools.doInApp)
        let limit = library.timeout
        settings.mode = .auto
        settings.setOverride(nil, for: SkilliTools.doInApp)
        library.timeout = 6
        defer {
            settings.mode = mode
            settings.setOverride(right, for: SkilliTools.doInApp)
            library.timeout = limit
            try? FileManager.default.removeItem(at: folder)
        }
        guard let command = ScriptCommand.parse(text, path: file.path) else {
            record(name, false, "the skillie could not be read", nil)
            return
        }
        let start = ContinuousClock.now
        context.aiActions.runScript?(command, false)
        let asked = await waitUntil(timeout: 10) { popover.isVisible && popover.phase == .approving } != nil
        let askedText = popover.shownText.prefix(120)
        let ended = await waitUntil(timeout: 25) {
            popover.isVisible && popover.phase != .approving && popover.shownText.hasPrefix("“Wait Forever” failed")
        }
        let took = ContinuousClock.now - start
        let card = popover.isVisible ? "\(popover.shownTitle) — \(popover.shownText.prefix(200))" : "gone"
        let pid = (try? String(contentsOf: callPID, encoding: .utf8)).flatMap { pid_t($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
        // Gone with its script, not left waiting for an answer (the signal
        // may still be on its way when the card says it failed).
        var callGone = false
        if let pid { callGone = await waitUntil(timeout: 3) { kill(pid, 0) != 0 } != nil }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = await waitUntil(timeout: 3) { !popover.isVisible }

        // The same with `showsRunning false`: no card of its own, its call
        // takes the card as an agent's; at the limit that approval goes all
        // the same and the card says it failed.
        let quietText = text.replacingOccurrences(of: "Wait Forever", with: "Wait Forever Quietly")
            .replacingOccurrences(of: "# @skilli.mode compact", with: "# @skilli.mode compact\n# @skilli.showsRunning false")
        let quietFile = folder.appendingPathComponent("wait-forever-quietly.sh")
        try? quietText.write(to: quietFile, atomically: true, encoding: .utf8)
        try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: quietFile.path)
        var quietAsked = false
        var quietEnded = false
        if let quiet = ScriptCommand.parse(quietText, path: quietFile.path), !quiet.showsRunning {
            context.aiActions.runScript?(quiet, false)
            quietAsked = await waitUntil(timeout: 10) { popover.isVisible && popover.phase == .approving } != nil
            quietEnded = await waitUntil(timeout: 25) {
                popover.isVisible && popover.phase != .approving && popover.shownText.hasPrefix("“Wait Forever Quietly” failed")
            } != nil
        }
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = await waitUntil(timeout: 3) { !popover.isVisible }

        // A script that ended at once, leaving behind what holds its output
        // and ignores SIGTERM: stopped at the limit all the same, killed 3 s on.
        let stubborn = folder.appendingPathComponent("leave-behind.sh")
        let leftPID = folder.appendingPathComponent("left.pid")
        let leaving = """
        #!/bin/bash
        # @skilli.schemaVersion 1
        # @skilli.title Leave Behind
        # @skilli.mode compact
        trap '' TERM
        sleep 60 &
        echo $! > '\(leftPID.path)'
        """
        try? leaving.write(to: stubborn, atomically: true, encoding: .utf8)
        try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: stubborn.path)
        var leftTook = Duration.zero
        var leftGone = false
        if let left = ScriptCommand.parse(leaving, path: stubborn.path) {
            let leftStart = ContinuousClock.now
            _ = try? await library.run(left, arguments: [], timeout: 2)
            leftTook = ContinuousClock.now - leftStart
            let leftover = (try? String(contentsOf: leftPID, encoding: .utf8)).flatMap { pid_t($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
            if let leftover { leftGone = await waitUntil(timeout: 3) { kill(leftover, 0) != 0 } != nil }
        }
        record(name, asked && ended != nil && callGone && took < .seconds(15) && quietAsked && quietEnded && leftGone && leftTook < .seconds(10),
               "asked: \(asked) “\(askedText)”; ended after \(Int(took.milliseconds)) ms (limit 6 s); call \(pid.map(String.init) ?? "none") gone: \(callGone); card \(card); "
                   + "showsRunning false: asked \(quietAsked), approval gone and failure said \(quietEnded); "
                   + "left behind, ignoring SIGTERM: run returned after \(Int(leftTook.milliseconds)) ms (limit 2 s), gone: \(leftGone)",
               took.milliseconds)
    }

    /// Finder's window on Documents: "⁨Documents⁩ — Local" on macOS 27
    /// (the name between direction isolates; iCloud Drive may hold another).
    private static func isDocuments(_ title: String?) -> Bool {
        title?.replacingOccurrences(of: "\u{2068}", with: "").replacingOccurrences(of: "\u{2069}", with: "").hasPrefix("Documents") == true
    }

    /// Closes the front window of `pid` through its close button.
    private static func closeFrontWindow(pid: pid_t) {
        let app = AXUIElementCreateApplication(pid)
        var window: CFTypeRef?
        guard AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &window) == .success, let window,
              CFGetTypeID(window) == AXUIElementGetTypeID() else { return }
        var button: CFTypeRef?
        guard AXUIElementCopyAttributeValue(unsafeDowncast(window, to: AXUIElement.self), kAXCloseButtonAttribute as CFString, &button) == .success,
              let button, CFGetTypeID(button) == AXUIElementGetTypeID() else { return }
        AXUIElementPerformAction(unsafeDowncast(button, to: AXUIElement.self), kAXPressAction as CFString)
    }

    /// Settings → Catalog → Quicklinks: Reuse an open tab first (off), the
    /// list, Add from Library… beside Add Quicklink; within the window.
    private func quicklinksSectionShown() async {
        let name = "Settings → Catalog → Quicklinks: Reuse an open tab (off by default), the list, Add from Library…; the pane fits"
        let settings = context.settings
        let reuseOff = !context.preferences.quicklinkReuseTab
        settings.show(pane: .catalog)
        await pause(800)
        settings.show(pane: .catalog, section: "quicklinks")
        let byItself = await waitUntil(timeout: 3) { settings.paneAtEnd } != nil
        if !byItself { _ = settings.scrollPaneToBottom() }
        let atEnd = await waitUntil(timeout: 1) { settings.paneAtEnd } != nil
        await pause(300)
        let overflow = settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-catalog-quicklinks")
        settings.scrollPaneToTop()
        await closeSettings()
        record(name, reuseOff && atEnd && overflow <= 1, "reuse off by default: \(reuseOff), opened at the quicklinks by itself: \(byItself), at the end: \(atEnd), overflow \(Int(overflow)) pt; settings-catalog-quicklinks-light/-dark.png", nil)
    }

    /// New Snippet, New Quicklink and New Command, typed in the launcher
    /// with keys: ↩ opens their pane with its editor on a new one, Settings
    /// closed or open on another pane; esc cancels it and nothing is added.
    /// Asked with an editor open, the new one waits until it closes; Settings
    /// closed with a command's editor open drops its draft.
    private func newFromLauncherOpensEditors() async {
        let name = "New Snippet, New Quicklink, New Command: typed in the launcher, ↩ opens their pane with the editor on a new one (Settings closed or on General); esc adds nothing; an editor open stays until it closes"
        let launcher = context.launcher
        let settings = context.settings
        let commands = context.aiCommands
        func counts() -> [Int] {
            commands.refresh()
            return [context.snippets.all.count, settings.freshContext().quicklinks.links.count, commands.commands.count]
        }
        let before = counts()
        var lines: [String] = []
        var passed = true
        for (typed, title, pane, capture, settingsOpen) in [
            ("new snippet", "New Snippet", SettingsPane.snippets, "settings-new-snippet", false),
            ("new quicklink", "New Quicklink", SettingsPane.catalog, "settings-new-quicklink", true),
            ("nouvelle commande", "New Command", SettingsPane.commands, "settings-new-command", false)
        ] {
            if settingsOpen {
                settings.show(pane: .general)
                await pause(400)
            }
            guard await focusTestWindow() else { return }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            _ = await waitUntil(timeout: 1) { launcher.isVisible }
            for character in typed { await pressKey(character) }
            let first = await waitUntil(timeout: 1) { launcher.resultTitles.first == title } != nil
            let shown = launcher.resultTitles.prefix(3)
            guard first else {
                await closeLauncher()
                await closeSettings()
                lines.append("“\(typed)” → \(Array(shown)), not \(title) first")
                passed = false
                continue
            }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let opened = await waitUntil(timeout: 3) { settings.isVisible && settings.pane == pane && settings.sheetShown } != nil
            let key = await waitUntil(timeout: 1) { settings.sheetIsKey } != nil
            if opened { await captureSettingsBothWays(as: capture) }
            // esc only where it lands in the editor: its Cancel.
            var cancelled = false
            if opened, key {
                await pressKey(nil, code: CGKeyCode(kVK_Escape))
                cancelled = await waitUntil(timeout: 2) { !settings.sheetShown } != nil
            }
            await closeSettings()
            lines.append("“\(typed)” first: \(first); \(pane.title) with its editor\(settingsOpen ? " (from General)" : ""): \(opened), keys in it: \(key), esc closed it: \(cancelled); \(capture)-light/-dark.png")
            passed = passed && opened && key && cancelled
        }

        // New Command asked with a snippet's editor open: that one stays,
        // its pane too; the command's opens once esc closed it.
        settings.showNew(.snippet)
        let snippetOpen = await waitUntil(timeout: 3) { settings.pane == .snippets && settings.sheetShown } != nil
        var kept = false, waited = false
        if snippetOpen, await focusTestWindow() {
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            _ = await waitUntil(timeout: 1) { launcher.isVisible }
            for character in "new command" { await pressKey(character) }
            if await waitUntil(timeout: 1) { launcher.resultTitles.first == "New Command" } != nil {
                await pressKey(nil, code: CGKeyCode(kVK_Return))
                await pause(800)
                kept = settings.pane == .snippets && settings.sheetShown
                if kept, await waitUntil(timeout: 1) { settings.sheetIsKey } != nil {
                    await pressKey(nil, code: CGKeyCode(kVK_Escape))
                    waited = await waitUntil(timeout: 3) { settings.pane == .commands && settings.sheetShown } != nil
                }
            } else {
                await closeLauncher()
            }
        }
        // Settings closed with that editor open: its draft goes, as on
        // Cancel, and the next New Command opens a blank one.
        await closeSettings()
        let dropped = commands.editing == nil
        settings.showNew(.command)
        let blank = await waitUntil(timeout: 3) { settings.pane == .commands && settings.sheetShown } != nil
            && commands.editing.map { !commands.isSaved($0.id) } == true
        await closeSettings()
        lines.append("New Command with a snippet's editor open: it stays \(kept), the command's after esc \(waited); Settings closed with it open: draft dropped \(dropped), next New Command blank \(blank)")
        passed = passed && snippetOpen && kept && waited && dropped && blank
        let after = counts()
        record(name, passed && after == before, lines.joined(separator: "; ") + "; snippets, quicklinks, commands before \(before), after \(after)", nil)
    }

    // MARK: - Settings → Catalog

    /// Settings as it shows now, light then dark: `<name>-light.png`,
    /// `<name>-dark.png`.
    private func captureSettingsBothWays(as name: String) async {
        defer { context.settings.setAppearance(nil) }
        for (suffix, appearance) in GlassCheck.appearances {
            context.settings.setAppearance(appearance)
            await pause(450)
            if let directory = context.snapshotDirectory, let png = await context.settings.snapshotPNG() {
                try? png.write(to: directory.appendingPathComponent("\(name)-\(suffix).png"))
            }
        }
    }

    /// Settings → Catalog: every entry by group, drawn fast and within the
    /// window, read-only rows; the search filters as the "?" does; a row's
    /// popover with its alias, shortcut and switch, recording there; the
    /// quicklinks and the other aliases at its end, where the "?"'s
    /// Quicklinks row opens it. Light and dark.
    private func catalogPaneShowsEverything() async {
        let name = "Settings → Catalog: every entry by group, fast, within the window; search; a row's popover (alias, shortcut, switch); quicklinks and other aliases last"
        let settings = context.settings
        let model = settings.catalog
        let preferences = context.preferences
        let store = context.shortcuts
        let savedAliases = preferences.launcherAliases
        defer {
            preferences.launcherAliases = savedAliases
            model.search = ""
            model.dismissed(preferences, store)
        }
        // One alias the rows do not hold: an app's, for the list at the end;
        // one a row holds, drawn as its keycap.
        preferences.launcherAliases = LauncherAliases.setting("calc", id: "app:/System/Applications/Calculator.app", title: "Calculator",
                                                              in: LauncherAliases.setting("zc", id: "cmd:clipboardHistory", title: "Clipboard History",
                                                                                          in: savedAliases))
        settings.show(pane: .general)
        await pause(300)
        // As a click in the sidebar: the first group drawn, then all;
        // Keys (its ~35 shortcut rows) to compare.
        func open(_ pane: SettingsPane) async -> (first: Duration, whole: Duration) {
            _ = settings.showAndDraw(.general)
            await pause(300)
            let start = ContinuousClock.now
            let first = settings.showAndDraw(pane)
            if pane == .catalog { _ = await waitUntil(timeout: 2) { model.allRowsShown } }
            settings.drawNow()
            let whole = ContinuousClock.now - start
            await pause(300)
            return (first, whole)
        }
        let keysDrawn = await open(.keys).whole
        let opened = await open(.catalog)
        let again = await open(.catalog)
        let entries = model.entries.count
        let groups = FeatureCatalog.sections(model.shown).map(\.group.title)
        let grouped = groups == CatalogEntry.Group.allCases.map(\.title)
        let overflow = settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-catalog")

        model.search = "clip"
        await pause(300)
        let found = model.shown.first?.id == "cmd:clipboardHistory"
        let filteredOverflow = settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-catalog-search")

        // A click on the row: its popover, anchored to it.
        var popover = false
        if let clipboard = model.entry("cmd:clipboardHistory") {
            model.open(clipboard, preferences)
            popover = await waitUntil(timeout: 2) { settings.popoverShown } != nil && model.aliasDraft == "zc"
            await pause(300)
            await captureSettingsBothWays(as: "settings-catalog-popover")
            model.done(preferences, store)
            _ = await waitUntil(timeout: 1) { !settings.popoverShown }
        }
        // Recording in a popover, on a row without a shortcut; ⎋ leaves no
        // empty one behind.
        var recording = false
        if let lock = model.entry("system:lockScreen") {
            model.search = "lock"
            await pause(300)
            model.open(lock, preferences)
            _ = await waitUntil(timeout: 2) { settings.popoverShown }
            await pause(300)
            model.recordShortcut(lock, store)
            await pause(300)
            recording = store.recordingID != nil
            await captureSettingsBothWays(as: "settings-catalog-recording")
            store.cancelRecording()
            await pause(200)
            model.done(preferences, store)
            _ = await waitUntil(timeout: 1) { !settings.popoverShown }
        }
        let leftBehind = store.config.shortcuts.contains { $0.action == .mac(.system(.lockScreen)) }
        // Nothing to change (the rows that point to where the first one is
        // made): no chevron, no popover.
        let readOnlyIDs = model.entries.filter { !model.isEditable($0) }.map(\.id)
        // The "make your first" rows, Auto Quit, set in its own pane, and
        // Do It Here and Ask on a Schedule: their shortcut was Ask's (#12).
        let readOnly = Set(readOnlyIDs).isSubset(of: ["catalog.snippets", "catalog.skillies", "catalog.quicklinks", "catalog.autoQuit",
                                                      "catalog.doItHere", "catalog.askSchedule"])

        // The end: quicklinks, then the aliases the rows do not hold.
        model.search = ""
        await pause(300)
        let listsLast = settings.scrollPaneToBottom()
        await pause(300)
        await captureSettingsBothWays(as: "settings-catalog-bottom")
        settings.show(pane: .general)
        await pause(300)
        // The "?"'s Quicklinks row, with none yet: the Catalog at its end.
        settings.show(pane: .catalog, section: "quicklinks")
        let atQuicklinks = await waitUntil(timeout: 2) { settings.paneAtEnd } != nil
        settings.scrollPaneToTop()
        await closeSettings()

        // Every row drawn: 250 ms for the ~144 entries it was set on, 1.75 ms
        // an entry past them, since how many there are depends on the
        // apps installed (CleanShot X's 25, an app file's).
        let wholeBudget = max(Duration.milliseconds(250), .microseconds(1_750 * entries))
        let fast = opened.first < .milliseconds(120) && opened.whole < wholeBudget && again.whole < wholeBudget
        record(name, entries > 80 && grouped && overflow <= 1 && found && filteredOverflow <= 1 && popover && recording && !leftBehind && readOnly
                   && listsLast && atQuicklinks && fast,
               "\(entries) entries in \(groups); pane drawn in \(Int(opened.first.milliseconds)) ms, every row in \(Int(opened.whole.milliseconds)) ms (budget \(Int(wholeBudget.milliseconds))) "
                   + "(again \(Int(again.first.milliseconds)) / \(Int(again.whole.milliseconds)) ms; Keys \(Int(keysDrawn.milliseconds)) ms; entries read in "
                   + "\(Int((model.lastLoad ?? .zero).milliseconds * 1_000)) µs); past the window: \(Int(overflow)) pt, searched \(Int(filteredOverflow)) pt; "
                   + "“clip” finds Clipboard History first: \(found); its popover with its alias: \(popover); recording in a popover: \(recording), "
                   + "⎋ left an empty shortcut: \(leftBehind); rows with nothing to set \(readOnlyIDs): \(readOnly); quicklinks and aliases at the end: \(listsLast); "
                   + "opened at the quicklinks: \(atQuicklinks)",
               opened.whole.milliseconds)
    }

    /// "Show in search" off in an entry's popover: Kill a Process and the
    /// calculator leave the launcher's results; "kill " still opens Kill;
    /// the "?" lists it dimmed, "Off", and ↩ still runs it there.
    private func catalogOffLeavesResults() async {
        let name = "Catalog Off: Show in search off in their popovers takes Kill a Process and the calculator out of the results; “kill ” still opens Kill; “?” dims it, ↩ runs it"
        let launcher = context.launcher
        let preferences = context.preferences
        let settings = context.settings
        let model = settings.catalog
        let store = context.shortcuts
        let saved = preferences.catalogOff
        defer {
            preferences.catalogOff = saved
            model.search = ""
        }
        preferences.catalogOff = []
        let calculation = Calculator.evaluate("10 km en miles")?.display ?? "?"

        func search(_ text: String) async -> [String] {
            guard await focusTestWindow() else { return [] }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            _ = await waitUntil(timeout: 1) { launcher.isVisible }
            for character in text { await pressKey(character) }
            await pause(250)
            let titles = launcher.resultTitles
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !launcher.isVisible }
            return titles
        }
        let killBefore = await search("kill").contains("Kill a Process")
        let calcBefore = await search("10 km en miles").first == calculation

        // Each one's popover, its switch off (what the switch calls).
        settings.show(pane: .catalog)
        var popovers = true
        for (id, typed) in [("catalog.calculator", "calculator"), ("cmd:killProcess", "kill")] {
            model.search = typed
            await pause(300)
            guard let entry = model.entry(id) else { continue }
            model.open(entry, preferences)
            popovers = await waitUntil(timeout: 2) { settings.popoverShown } != nil && popovers
            await pause(200)
            model.setOn(false, entry, preferences)
            await pause(300)
            if id == "cmd:killProcess" { await captureSettingsBothWays(as: "settings-catalog-off-popover") }
            model.done(preferences, store)
            _ = await waitUntil(timeout: 1) { !settings.popoverShown }
        }
        let saved2 = preferences.catalogOff
        // The row: dimmed, "Off".
        await pause(300)
        await captureSettingsBothWays(as: "settings-catalog-off")
        model.search = ""
        await closeSettings()
        let killAfter = await search("kill")
        let killGone = !killAfter.contains("Kill a Process")
        let calcAfter = await search("10 km en miles")
        let calcGone = !calcAfter.contains(calculation)

        // Its prefix still works.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        for character in "kill " { await pressKey(character) }
        let prefix = await waitUntil(timeout: 1) { launcher.isKilling } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await closeLauncher()

        // The "?": still there, dimmed; ↩ runs it.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        _ = await typeCharacter("?")
        for character in "kill" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Kill a Process" } != nil
        let dimmed = await waitUntil(timeout: 1) { launcher.shownCatalogOff.contains("Kill a Process") } != nil
        let dimmedRows = launcher.shownCatalogOff
        await captureLauncherBothWays(as: "launcher-catalog-off")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let runs = await waitUntil(timeout: 1) { launcher.isKilling } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await closeLauncher()

        record(name, killBefore && calcBefore && popovers && saved2 == ["cmd:killProcess", "catalog.calculator"] && killGone && calcGone && prefix && listed
                   && dimmed && runs,
               "on: “kill” lists it \(killBefore), “10 km en miles” → \(calculation) first \(calcBefore); popovers opened: \(popovers); off \(saved2.sorted()): "
                   + "“kill” → \(killAfter.prefix(4)) (gone: \(killGone)), “10 km en miles” → \(calcAfter.prefix(3)) (gone: \(calcGone)); "
                   + "“kill ” opens Kill: \(prefix); “? kill” first: \(listed), dimmed: \(dimmed) \(dimmedRows); ↩ runs it: \(runs)", nil)
    }

    /// An alias typed in an entry's popover, with the keyboard, then used
    /// in the launcher: "zk " opens Kill a Process.
    private func catalogAliasFromPane() async {
        let name = "Catalog alias: typed in Kill a Process's popover (keys, ↩ closes it), then “zk ” in the launcher opens Kill"
        let settings = context.settings
        let model = settings.catalog
        let preferences = context.preferences
        let store = context.shortcuts
        let launcher = context.launcher
        let saved = preferences.launcherAliases
        defer {
            preferences.launcherAliases = saved
            model.search = ""
            model.dismissed(preferences, store)
        }
        preferences.launcherAliases = saved.filter { $0.id != "cmd:killProcess" && $0.alias != "zk" }
        settings.show(pane: .catalog)
        model.search = "kill"
        await pause(400)
        guard let kill = model.entry("cmd:killProcess") else {
            record(name, false, "no Kill a Process entry", nil)
            return
        }
        model.open(kill, preferences)
        // The field takes the keys once the popover is up.
        let shown = await waitUntil(timeout: 2) { settings.popoverShown && NSApp.isActive } != nil
        await pause(500)
        for character in "zk" { await pressKey(character) }
        let typed = await waitUntil(timeout: 1) { model.aliasDraft == "zk" } != nil
        await captureSettingsBothWays(as: "settings-catalog-alias-typed")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let kept = await waitUntil(timeout: 1) {
            preferences.launcherAliases.contains { $0.id == "cmd:killProcess" && $0.alias == "zk" } && model.editing == nil
        } != nil
        let closed = await waitUntil(timeout: 1) { !settings.popoverShown } != nil
        await pause(300)
        await captureSettingsBothWays(as: "settings-catalog-alias-kept")
        await closeSettings()

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        for character in "zk " { await pressKey(character) }
        let opens = await waitUntil(timeout: 1) { launcher.isKilling } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await closeLauncher()
        record(name, shown && typed && kept && closed && opens,
               "popover shown: \(shown); typed in it: \(typed) (“\(model.aliasDraft)”); kept: \(kept) "
                   + "(\(preferences.launcherAliases.map { "\($0.alias)→\($0.id)" })), popover closed by ↩: \(closed); “zk ” opens Kill: \(opens)", nil)
    }

    /// A shortcut recorded in the popover of an entry that had none (Keep
    /// Awake), then pressed: Keep Awake runs.
    private func catalogShortcutFromPane() async {
        let name = "Catalog shortcut: recorded in Keep Awake's popover (✦B, it had none), then ✦B keeps the Mac awake"
        let settings = context.settings
        let model = settings.catalog
        let preferences = context.preferences
        let store = context.shortcuts
        guard let commands = context.tools.tools.systemCommands else {
            record(name, false, "no system commands", nil)
            return
        }
        let action = SkilliAction.mac(.system(.keepAwake))
        let wasAwake = commands.isKeepingAwake
        defer {
            model.search = ""
            model.dismissed(preferences, store)
            for entry in store.config.shortcuts where entry.action == action { store.remove(entry.id) }
        }
        settings.show(pane: .catalog)
        model.search = "keep awake"
        await pause(400)
        guard let entry = model.entry("system:keepAwake"), store.entryID(for: action) == nil else {
            record(name, false, "no Keep Awake entry, or it already has a shortcut", nil)
            return
        }
        model.open(entry, preferences)
        let shown = await waitUntil(timeout: 2) { settings.popoverShown } != nil
        await pause(300)
        // What a click on its shortcut field does; the keys come from the tap.
        model.recordShortcut(entry, store)
        let recording = store.recordingID != nil
        await hyperChord(["b"], trigger: Self.ownTriggerKeyCode)
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let id = store.entryID(for: action)
        let saved = id.flatMap(keys)
        await pause(300)
        await captureSettingsBothWays(as: "settings-catalog-shortcut")
        model.done(preferences, store)
        _ = await waitUntil(timeout: 1) { !settings.popoverShown }
        await closeSettings()

        guard await focusTestWindow() else { return }
        await hyperChord(["b"], trigger: Self.ownTriggerKeyCode)
        let ran = await waitUntil(timeout: 2) { commands.isKeepingAwake != wasAwake } != nil
        // Back as it was.
        if commands.isKeepingAwake != wasAwake { _ = try? await commands.run(.keepAwake) }
        record(name, shown && recording && saved == "hyper+b" && ran,
               "popover shown: \(shown); recording from it: \(recording); saved: \(saved ?? "none"); ✦B ran Keep Awake: \(ran) "
                   + "(awake before: \(wasAwake), after: \(commands.isKeepingAwake))", nil)
    }

    /// Light then dark, the test window behind it in the same appearance:
    /// `<name>-light.png`, `<name>-dark.png`.
    private func captureLauncherBothWays(as name: String) async {
        let launcherWindow = context.launcher.window
        let (launcherAppearance, testAppearance) = (launcherWindow.appearance, window.appearance)
        defer {
            launcherWindow.appearance = launcherAppearance
            window.appearance = testAppearance
        }
        for (suffix, appearance) in GlassCheck.appearances {
            launcherWindow.appearance = appearance
            window.appearance = appearance
            // The glass takes its new tint over a moment.
            await pause(900)
            await captureLauncher(as: "\(name)-\(suffix).png")
        }
    }

    /// Types `character` with the key (and Shift) that types it on this
    /// layout: "?" is ⇧, on AZERTY, ⇧/ on QWERTY. False when no key does.
    private func typeCharacter(_ character: Character) async -> Bool {
        if let code = keyCode(character) {
            await pressKey(nil, code: code)
            return true
        }
        for code in CGKeyCode(0)..<128 {
            var deadKeyState: UInt32 = 0
            guard context.layout.typedText(for: code, flags: .maskShift, deadKeyState: &deadKeyState) == String(character) else { continue }
            let source = CGEventSource(stateID: .hidSystemState)
            for down in [true, false] {
                guard let event = CGEvent(keyboardEventSource: source, virtualKey: code, keyDown: down) else { return false }
                event.flags = .maskShift
                let text = Array(String(character).utf16)
                event.keyboardSetUnicodeString(stringLength: text.count, unicodeString: text)
                event.post(tap: .cghidEventTap)
                await pause(12)
            }
            return true
        }
        return false
    }

    /// "kill skillitest" through Ask: two scratch processes (copies of
    /// /bin/sleep under a SkilliTest folder) are what it names; the decision
    /// model says so and both quit. Nothing else is touched.
    private func askQuitsWhatItNames() async {
        let name = "Ask “kill …”: what bears the name quits, the decision model sorts the rest; nothing announced"
        var keys: [DecisionProvider: String] = [:]
        for provider in DecisionProvider.allCases { keys[provider] = Keychain.read(account: provider.keychainAccount) }
        guard !keys.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no decision key saved in Settings", latencyMs: nil))
            return
        }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("Application Support/SkilliTest-\(getpid())")
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        var processes: [Process] = []
        for helper in ["skillitest-agent", "skillitest-sync"] {
            // A link, not a copy: macOS kills a system binary run from
            // anywhere else at launch; ps still shows the link's path.
            let binary = folder.appendingPathComponent(helper)
            try? FileManager.default.createSymbolicLink(at: binary, withDestinationURL: URL(fileURLWithPath: "/bin/sleep"))
            let process = Process()
            process.executableURL = binary
            process.arguments = ["300"]
            try? process.run()
            processes.append(process)
        }
        defer {
            processes.filter(\.isRunning).forEach { $0.terminate() }
            try? FileManager.default.removeItem(at: folder)
        }
        await pause(300)
        guard processes.allSatisfy(\.isRunning) else {
            record(name, false, "the scratch processes did not start", nil)
            return
        }
        let popover = context.aiActions.popover
        context.aiActions.decisionKeysOverride = keys
        defer { context.aiActions.decisionKeysOverride = nil }
        guard await focusTestWindow() else { return }
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "kill skillitest"])
        var answered = false
        let quit = await waitUntil(timeout: 20) {
            // An unsure one asked: 1, Quit It (↩ is Leave It, the default).
            if popover.shownQuestion?.text.hasPrefix("Also quit") == true, !answered {
                answered = true
                Task { await self.pressKey(nil, code: CGKeyCode(kVK_ANSI_1)) }
            }
            if popover.shownQuestion == nil { answered = false }
            return processes.allSatisfy { !$0.isRunning } && !popover.isVisible
        } != nil
        let card = "\(popover.shownStatus) — \(popover.shownText.prefix(200))"
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, quit, "both quit: \(quit); card \(card)", nil)
    }

    /// Uninstall: a scratch app (its own bundle id) and leftovers made for it
    /// in ~/Library are listed with their size; Move to Trash ↩ moves them
    /// all; the test then takes its own items out of the Trash.
    private func uninstallMovesAppAndLeftovers() async {
        let name = "Uninstall: an app and its leftovers in ~/Library listed with their size, moved to the Trash after ↩"
        let id = "com.nomdelasociete.selftest.uninstall\(getpid())"
        let base = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-uninstall-\(getpid())")
        let app = base.appendingPathComponent("SkilliUninstallTest.app")
        let contents = app.appendingPathComponent("Contents")
        try? FileManager.default.createDirectory(at: contents.appendingPathComponent("MacOS"), withIntermediateDirectories: true)
        let info: NSDictionary = ["CFBundleIdentifier": id, "CFBundleName": "SkilliUninstallTest", "CFBundlePackageType": "APPL", "CFBundleExecutable": "none"]
        info.write(to: contents.appendingPathComponent("Info.plist"), atomically: true)
        let library = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library")
        let leftovers = [library.appendingPathComponent("Application Support/\(id)"), library.appendingPathComponent("Caches/\(id)")]
        for folder in leftovers {
            try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            try? Data(repeating: 7, count: 20_000).write(to: folder.appendingPathComponent("data.bin"))
        }
        let preferences = library.appendingPathComponent("Preferences/\(id).plist")
        NSDictionary(dictionary: ["test": true]).write(to: preferences, atomically: true)
        let everything = [app] + leftovers + [preferences]
        defer {
            // Our items only, from where they are now: here, or the Trash.
            let trash = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(".Trash")
            let trashed = (try? FileManager.default.contentsOfDirectory(atPath: trash.path)) ?? []
            for item in trashed where item.hasPrefix(id) || item.hasPrefix("SkilliUninstallTest") {
                try? FileManager.default.removeItem(at: trash.appendingPathComponent(item))
            }
            everything.forEach { try? FileManager.default.removeItem(at: $0) }
            try? FileManager.default.removeItem(at: base)
        }
        let popover = context.aiActions.popover
        context.aiActions.runUninstall(app)
        let listed = await waitUntil(timeout: 10) {
            popover.shownQuestion?.text.hasPrefix("Uninstall SkilliUninstallTest?") == true && popover.shownOptions.first == "Move to Trash"
        } != nil
        let question = popover.shownQuestion?.text ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let moved = await waitUntil(timeout: 10) {
            everything.allSatisfy { !FileManager.default.fileExists(atPath: $0.path) } && popover.shownStatus.hasPrefix("Uninstalled")
        } != nil
        if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, listed && moved, "listed: \(listed) “\(question)”; moved to the Trash: \(moved)", nil)
    }

    /// A Mac command the route is sure of and its list is not ("monte le
    /// son": Volume Up 28 %): the likeliest as keycaps, nothing run; esc.
    private func askUnsureCommandOffersChoices() async {
        let name = "Ask “command”, unsure which: the likeliest commands as keycaps, nothing run first"
        let popover = context.aiActions.popover
        let up = MacAction.system(.volumeUp), down = MacAction.system(.volumeDown), mute = MacAction.system(.mute)
        context.aiActions.decisionOverride = AskRouter.Decision(route: .command, confidence: 0.94, menu: [], command: (up, 0.28),
                                                                commands: [(up, 0.28), (down, 0.17), (mute, 0.11)], label: "Test")
        defer { context.aiActions.decisionOverride = nil }
        guard await focusTestWindow(), await openAsk() else {
            record(name, false, "no question in the card", nil)
            return
        }
        // (Not "monte le son": media keys are understood before any model.)
        for character in "le volume comme il faut" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let offered = await waitUntil(timeout: 2) { popover.shownQuestion?.text == "Which one?" } != nil
        let options = popover.shownOptions
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, offered && options == [up.title, down.title, mute.title], "offered: \(offered) \(options)", nil)
    }

    // MARK: - Setup

    /// The setup window in three states, drawn off screen into PNGs.
    /// After System Settings quits skil.li: `Skilli relaunch` waits for the
    /// process to end (a scratch one here) and only then opens the app (a
    /// scratch app that leaves a mark). Who counts as System Settings: unit
    /// tests (`QuitSender`).
    private func reopenAfterSystemSettings() async {
        let name = "Reopen after System Settings: the watcher opens the app only once the process has ended"
        let base = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-reopen", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: base) }
        let app = base.appendingPathComponent("Probe.app")
        let macOS = app.appendingPathComponent("Contents/MacOS", isDirectory: true)
        let mark = base.appendingPathComponent("opened")
        try? FileManager.default.createDirectory(at: macOS, withIntermediateDirectories: true)
        let info: NSDictionary = ["CFBundleExecutable": "probe", "CFBundleIdentifier": "com.nomdelasociete.skilli.selftest-probe",
                                  "CFBundlePackageType": "APPL", "LSUIElement": true]
        info.write(to: app.appendingPathComponent("Contents/Info.plist"), atomically: true)
        let probe = macOS.appendingPathComponent("probe")
        try? "#!/bin/sh\ntouch \(Handoff.quotedForTest(mark.path))\n".write(to: probe, atomically: true, encoding: .utf8)
        try? FileManager.default.setAttributes([.posixPermissions: 0o755], ofItemAtPath: probe.path)
        guard let binary = Bundle.main.executableURL else {
            record(name, false, "no executable", nil)
            return
        }
        let quitting = Process()
        quitting.executableURL = URL(fileURLWithPath: "/bin/sleep")
        quitting.arguments = ["2"]
        let watcher = Process()
        watcher.executableURL = binary
        do {
            try quitting.run()
            watcher.arguments = ["relaunch", String(quitting.processIdentifier), app.path]
            try watcher.run()
        } catch {
            record(name, false, error.localizedDescription, nil)
            return
        }
        await pause(1200)
        let waited = !FileManager.default.fileExists(atPath: mark.path) && watcher.isRunning
        let opened = await waitUntil(timeout: 8) { FileManager.default.fileExists(atPath: mark.path) } != nil
        let gone = await waitUntil(timeout: 3) { !watcher.isRunning } != nil
        record(name, waited && opened && gone, "waited while the process ran: \(waited); app opened once it ended: \(opened); watcher gone: \(gone)", nil)
    }

    /// Every welcome step in each of its states, light and dark, as the
    /// window draws them (docs/onboarding.md): written for judging by eye.
    /// Permissions frozen: macOS is never asked.
    private func drawWelcome() async {
        let name = "Welcome: every step drawn in each state, light and dark, inside its window"
        let permissions = PermissionCenter()
        let others = Dictionary(uniqueKeysWithValues: Permission.allCases.map { ($0, PermissionCenter.State.notAsked) })
        permissions.frozenStates = others.merging([.accessibility: .granted]) { $1 }
        let setup = SetupWindowController(permissions: permissions, ai: context.ai, preferences: context.preferences)
        let model = setup.model
        model.advancesByItself = false
        // The self-test's own shortcuts; the launcher's keys put back after.
        model.shortcuts = context.shortcuts
        let launcherID = context.shortcuts.launcherEntry?.id ?? "launcher"
        let launcherKeys = context.shortcuts.launcherEntry?.keys
        model.keys = { [shortcuts = context.shortcuts] action in
            shortcuts.config.shortcuts.first { $0.action == action }?.chords.map { $0.map(\.keycaps) } ?? []
        }
        setup.show()
        defer {
            context.shortcuts.cancelRecording()
            try? context.shortcuts.setKeys(launcherKeys.flatMap { try? Chord.sequence($0) }, for: launcherID)
            setup.setAppearance(nil)
            setup.close()
        }
        typealias State = (file: String, step: WelcomeModel.Step, accessibility: PermissionCenter.State, apply: @MainActor (WelcomeModel) -> Void)
        let states: [State] = [
            ("welcome", .welcome, .granted, { _ in }),
            ("accessibility-first", .accessibility, .notAsked, { _ in }),
            ("accessibility-waiting", .accessibility, .waiting, { _ in }),
            ("accessibility-on", .accessibility, .granted, { _ in }),
            ("hyper-idle", .hyperKey, .granted, { $0.hyperKey = .own }),
            ("hyper-held", .hyperKey, .granted, { $0.hyperKey = .own; $0.freeze(hyperHeld: true, hyperFelt: true) }),
            ("hyper-shared", .hyperKey, .granted, { $0.hyperKey = .shared; $0.freeze(hyperFelt: true) }),
            ("hyper-custom", .hyperKey, .granted, { $0.hyperKey = .custom }),
            ("launcher-idle", .launcher, .granted, { $0.chooseLauncher("hyper+space") }),
            ("launcher-spotlight", .launcher, .granted, { $0.chooseLauncher("cmd+space") }),
            ("launcher-own", .launcher, .granted, { $0.chooseLauncher("opt+cmd+l") }),
            ("launcher-recording", .launcher, .granted, { $0.chooseLauncher("hyper+space"); $0.recordLauncher() }),
            // A key macOS always keeps (Switch apps): refused, and why.
            ("launcher-refused", .launcher, .granted, { $0.chooseLauncher("hyper+space"); $0.chooseLauncher("cmd+tab") }),
            ("launcher-open", .launcher, .granted, { $0.freeze(hyperHeld: true, launcherOpen: true) }),
            ("launcher-tried", .launcher, .granted, { $0.chooseLauncher("hyper+space"); $0.freeze(launcherTried: true) }),
            ("si", .intelligence, .granted, { _ in }),
            ("practice", .practice, .granted, { _ in }),
            ("practice-fixed", .practice, .granted, { $0.freeze(practice: .fixed("I wrote this sentence too quickly; it needs fixing.")) }),
            ("practice-undone", .practice, .granted, { $0.freeze(practice: .undone) }),
            ("ready", .ready, .granted, { _ in })
        ]
        var written: [String] = []
        for state in states {
            permissions.frozenStates = others.merging([.accessibility: state.accessibility]) { $1 }
            model.start(at: state.step)
            model.hyperKey = .own
            state.apply(model)
            defer { context.shortcuts.cancelRecording() }
            for (suffix, appearance) in GlassCheck.appearances {
                setup.setAppearance(appearance)
                // The step's slide and the providers' first read.
                await pause(state.step == .intelligence ? 1500 : 700)
                if let directory = context.snapshotDirectory, let png = await setup.snapshotPNG() {
                    let file = "welcome-\(state.file)-\(suffix).png"
                    try? png.write(to: directory.appendingPathComponent(file))
                    written.append(file)
                }
            }
        }
        let size = setup.shownWindow?.frame.size ?? .zero
        let fits = abs(size.height - WelcomeView.size.height) < 1 && abs(size.width - WelcomeView.size.width) < 1
        record(name, written.count == states.count * 2 && fits,
               "\(written.count) captures (\(states.count) states × light, dark); window \(Int(size.width))×\(Int(size.height)) pt", nil)
    }

    /// D7 (2026-10-17): the first launch asks only for Accessibility
    /// and the user's SI; every other permission where its feature first
    /// needs it (macOS's question there, or its list once refused; Full
    /// Disk Access through Settings → Privacy, it cannot be asked). Closed
    /// once, the window never opens by itself; Set Up skil.li… is offered
    /// while Accessibility or the key tap is missing.
    private func setupAsksOnlyForTwo() {
        let name = "Setup asks only for Accessibility and your SI; the rest where first needed; closed once, it never opens by itself"
        let inSetup = Permission.allCases.filter(\.showsInSetup)
        let elsewhere = Permission.allCases.filter { $0 != .accessibility }.map { "\($0.rawValue): \($0.askedFrom)" }
        let routed = Permission.accessibility.askedFrom == .setup && Permission.fullDiskAccess.askedFrom == .privacyPane
            && Permission.allCases.filter { ![.accessibility, .fullDiskAccess].contains($0) }.allSatisfy { $0.askedFrom == .inPlace }
        let byItself = (first: SetupWindowController.showsByItself(closedOnce: false), again: SetupWindowController.showsByItself(closedOnce: true))
        let offered = (missing: SetupWindowController.isOffered(tapRunning: false, ready: false),
                       noTap: SetupWindowController.isOffered(tapRunning: false, ready: true),
                       on: SetupWindowController.isOffered(tapRunning: true, ready: true))
        record(name, inSetup == [.accessibility] && routed && byItself.first && !byItself.again && offered.missing && offered.noTap && !offered.on,
               "in the window: \(inSetup.map(\.rawValue)) and your SI; elsewhere: \(elsewhere.joined(separator: ", ")); "
                   + "by itself at first launch \(byItself.first), after closing \(byItself.again); Set Up offered while missing \(offered.missing), "
                   + "no key tap \(offered.noTap), all on \(offered.on)", nil)
    }

    // MARK: - Voice

    /// A sentence spoken by macOS's own voice (`say`) into a file, in the
    /// first installed voice of `language`.
    private func spokenFile(_ sentence: String, language: String) async -> URL? {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-voice-\(getpid()).aiff")
        return await withCheckedContinuation { continuation in
            DispatchQueue.global().async {
                let list = Process()
                list.executableURL = URL(fileURLWithPath: "/usr/bin/say")
                list.arguments = ["-v", "?"]
                let pipe = Pipe()
                list.standardOutput = pipe
                try? list.run()
                let voices = String(decoding: pipe.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
                list.waitUntilExit()
                // "Thomas (French (France)) fr_FR    # Bonjour…": the name is
                // what comes before the locale. Thomas first: a natural voice.
                let names = voices.split(separator: "\n").compactMap { line -> String? in
                    let parts = line.components(separatedBy: " \(language)_")
                    return parts.count > 1 ? parts[0].trimmingCharacters(in: .whitespaces) : nil
                }
                let voice = names.first { $0.hasPrefix("Thomas") } ?? names.first
                let say = Process()
                say.executableURL = URL(fileURLWithPath: "/usr/bin/say")
                say.arguments = (voice.map { ["-v", $0] } ?? []) + ["-o", url.path, sentence]
                try? say.run()
                say.waitUntilExit()
                continuation.resume(returning: say.terminationStatus == 0 ? url : nil)
            }
        }
    }

    /// Under the Hardened Runtime, a missing entitlement makes macOS deny
    /// the microphone or Reminders silently: no prompt, no Privacy entry.
    private func signedForMicrophoneAndReminders() {
        let name = "Signed with the microphone and Reminders entitlements (else macOS denies them silently)"
        guard let task = SecTaskCreateFromSelf(nil) else {
            record(name, false, "no code signature to read", nil)
            return
        }
        let wanted = ["com.apple.security.device.audio-input", "com.apple.security.personal-information.calendars"]
        let missing = wanted.filter { SecTaskCopyValueForEntitlement(task, $0 as CFString, nil) as? Bool != true }
        record(name, missing.isEmpty, missing.isEmpty ? "both present" : "missing \(missing.joined(separator: ", "))", nil)
    }

    /// On-device speech to text, in French, from a spoken file.
    private func voiceTranscribesSpeech() async {
        let name = "Voice: French speech becomes text on this Mac"
        // All French: a French voice says "Finder" the French way ("Funder").
        guard let file = await spokenFile("ouvre une nouvelle fenêtre dans le dossier des téléchargements", language: "fr") else {
            record(name, false, "say could not write the sentence", nil)
            return
        }
        defer { try? FileManager.default.removeItem(at: file) }
        let input = VoiceInput()
        input.language = "fr-FR"
        let start = ContinuousClock.now
        do {
            let text = try await input.transcribe(file: file)
            let latency = ContinuousClock.now - start
            let heard = text.lowercased()
            record(name, heard.contains("nouvelle fenêtre") && heard.contains("téléchargements"), "heard “\(text)” in \(Int(latency.milliseconds)) ms", latency.milliseconds)
        } catch {
            record(name, false, error.localizedDescription, nil)
        }
    }

    /// ✦V: what is heard shows live in the card; Return runs Ask with it.
    private func voiceAsksByVoice() async {
        let name = "Ask by Voice (✦V): what is heard shows in the card, Return runs Ask with it"
        let popover = context.aiActions.popover
        guard let file = await spokenFile("explique ce mot", language: "fr") else {
            record(name, false, "say could not write the sentence", nil)
            return
        }
        context.ai.testEngine = FakeTextEngine(chunks: ["Un mot."], delay: .milliseconds(20))
        context.aiActions.routeOverride = .answer
        context.aiActions.voiceFileOverride = file
        let language = context.preferences.voiceLanguage
        context.preferences.voiceLanguage = "fr-FR"
        defer {
            context.ai.testEngine = nil
            context.aiActions.routeOverride = nil
            context.aiActions.voiceFileOverride = nil
            context.preferences.voiceLanguage = language
            try? FileManager.default.removeItem(at: file)
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "Bonjour"
        textView.selectAll(nil)
        await pause(60)
        var shown = false
        for _ in 0..<2 where !shown {
            _ = await hyperChord(["v"], trigger: Self.ownTriggerKeyCode)
            shown = await waitUntil(timeout: 1.5) { popover.phase == .asking && popover.isVisible } != nil
        }
        let heard = await waitUntil(timeout: 20) { (popover.shownQuestion?.typed ?? "").lowercased().contains("mot") } != nil
        await saveScreenshot(of: popover.window, as: "ai-card-voice.png")
        let typed = popover.shownQuestion?.typed ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let done = await waitUntil(timeout: 5) { popover.phase == .done } != nil
        let message = context.aiActions.lastMessage ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, shown && heard && done && message.lowercased().contains("mot") && message.contains("Bonjour"),
               "card shown: \(shown), heard “\(typed)”, Ask sent “\(message.replacingOccurrences(of: "\n", with: " ⏎ "))”", nil)
    }

