    /// Dictate's model (the system dictation's) told the names: the same
    /// spoken file heard without them, then with them. Alone it writes
    /// "Martin" (mini, 2026-10-20); told, "Martaing".
    private func dictationKnowsYourContacts() async {
        let name = "Dictate: a contact's name given to this Mac's recognizer comes out spelled as in Contacts"
        guard let file = await spokenFile("Envoie le devis à Jean-François Martaing, chez Nimbus, avant vendredi", language: "fr") else {
            record(name, false, "say could not write the sentence", nil)
            return
        }
        defer { try? FileManager.default.removeItem(at: file) }
        func heard(_ phrases: [String]) async throws -> String {
            let input = VoiceInput()
            input.use = .dictation
            input.language = "fr-FR"
            input.vocabulary = { phrases }
            return try await input.transcribe(file: file)
        }
        do {
            let start = ContinuousClock.now
            let without = try await heard([])
            let withNames = try await heard(DictationVocabulary(contacts: Self.dictationContacts).phrases)
            let latency = ContinuousClock.now - start
            record(name, withNames.contains("Martaing"), "without the names: “\(without)”; with them: “\(withNames)”", latency.milliseconds / 2)
        } catch {
            record(name, false, error.localizedDescription, nil)
        }
    }

    /// ✦D in a TextEdit document, the caret after "Bonjour Paul,": the card
    /// listens (a spoken file stands in for the microphone), Return types
    /// what was heard there, a space before it and lowercase after the
    /// comma; TextEdit's own ⌘Z takes it back.
    private func dictationTypesIntoTextEdit() async {
        let name = "Dictate (✦D) in TextEdit: what is heard is typed at the caret, joined to the text; TextEdit's ⌘Z takes it back"
        let bundleID = "com.apple.TextEdit"
        let original = "Bonjour Paul,"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "TextEdit not installed", nil)
            return
        }
        guard let spoken = await spokenFile("Je t'envoie le devis de Nimbus demain matin", language: "fr") else {
            record(name, false, "say could not write the sentence", nil)
            return
        }
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-dictation-\(getpid()).txt")
        try? original.write(to: file, atomically: true, encoding: .utf8)
        let book = context.launcher.contacts
        book?.testRecords = Self.dictationContacts
        context.aiActions.voiceFileOverride = spoken
        let language = context.preferences.voiceLanguage
        context.preferences.voiceLanguage = "fr-FR"
        defer {
            book?.testRecords = nil
            context.aiActions.voiceFileOverride = nil
            context.preferences.voiceLanguage = language
            try? FileManager.default.removeItem(at: file)
            try? FileManager.default.removeItem(at: spoken)
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        let opened = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration)
        if let pid = opened?.processIdentifier {
            await pause(300)
            Self.makeFrontmost(pid: pid)
        }
        guard await waitUntil(timeout: 5, {
            NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID && Self.focusedValue() == original
        }) != nil else {
            record(name, false, "the document never got focus (frontmost: \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"))", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        guard ensureFrontmost(bundleID, before: "the caret at the end") else { return }
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow), flags: .maskCommand)
        await pause(100)
        let popover = context.aiActions.popover
        var shown = false
        for _ in 0..<2 where !shown {
            guard ensureFrontmost(bundleID, before: "✦D") else { return }
            _ = await hyperChord(["d"], trigger: Self.ownTriggerKeyCode)
            shown = await waitUntil(timeout: 1.5) { popover.phase == .asking && popover.isVisible && popover.shownTitle == "Dictate" } != nil
        }
        let heard = await waitUntil(timeout: 20) { (popover.shownQuestion?.typed ?? "").lowercased().contains("devis") } != nil
        let typed = popover.shownQuestion?.typed ?? ""
        let hints = popover.hintTitles
        guard ensureFrontmost(bundleID, before: "↩") else { return }
        let start = ContinuousClock.now
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let inserted = await waitUntil(timeout: 5) {
            let value = Self.focusedValue() ?? ""
            return value.hasPrefix(original + " je ") && value.contains("devis")
        }
        let value = Self.focusedValue() ?? ""
        guard ensureFrontmost(bundleID, before: "⌘Z") else { return }
        await pressKey("z", flags: .maskCommand)
        let undone = await waitUntil(timeout: 2) { Self.focusedValue() == original } != nil
        let names = context.aiActions.lastDictationNames
        record(name, shown && heard && inserted != nil && undone && hints.first == "Insert" && names > 0,
               "card shown: \(shown) (\(hints.joined(separator: ", "))), heard “\(typed)”, TextEdit then “\(value)”, \(names) names known, ⌘Z: \(undone)",
               inserted.map { _ in (ContinuousClock.now - start).milliseconds })
        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
    }

