    /// Its one entry point besides ✦D: "? dictate" puts Dictate first,
    /// under Write, with its shortcut as keycaps; ↩ hides the launcher and
    /// the card listens for the window that was in front; esc drops it.
    private func dictationFromTheCatalog() async {
        let name = "Catalog: “? dictate” puts Dictate first, in Write, with ✦D; ↩ starts listening for the window in front, esc drops it"
        let launcher = context.launcher
        let popover = context.aiActions.popover
        guard let spoken = await spokenFile("Bonjour à tous", language: "fr") else {
            record(name, false, "say could not write the sentence", nil)
            return
        }
        context.aiActions.voiceFileOverride = spoken
        defer {
            context.aiActions.voiceFileOverride = nil
            try? FileManager.default.removeItem(at: spoken)
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        guard await typeCharacter("?") else {
            await closeLauncher()
            record(name, false, "no key types “?” on this keyboard layout", nil)
            return
        }
        for character in " dictate" { await pressKey(character) }
        let first = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Dictate" && launcher.selectedResultTitle == "Dictate" } != nil
        let keys = launcher.shownCatalogKeys["Dictate"] ?? []
        let header = launcher.headerText
        await captureLauncherBothWays(as: "launcher-catalog-dictate")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let listening = await waitUntil(timeout: 2) { popover.isVisible && popover.phase == .asking && popover.shownTitle == "Dictate" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let dropped = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        await pause(300)
        let untouched = textView.string.isEmpty
        record(name, first && header == "Write" && keys == [["✦ D"]] && listening && dropped && untouched,
               "first: \(first), header “\(header)”, keys \(keys); listening after ↩: \(listening), esc dropped it: \(dropped), nothing typed: \(untouched)", nil)
    }

    /// ✦A until Ask's question shows: a synthetic chord can be dropped.
    private func openAsk() async -> Bool {
        for _ in 0..<2 {
            _ = await hyperChord(["a"], trigger: Self.ownTriggerKeyCode)
            if await waitUntil(timeout: 1.5, { self.context.aiActions.popover.phase == .asking && self.context.aiActions.popover.isVisible }) != nil {
                return true
            }
        }
        return false
    }

    private static func accessibilityButton(labelled label: String) -> AXUIElement? {
        var found: AXUIElement?
        walkAX(from: AXUIElementCreateApplication(getpid()), depth: 30) { element in
            var role: CFTypeRef?
            var description: CFTypeRef?
            AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &role)
            AXUIElementCopyAttributeValue(element, kAXDescriptionAttribute as CFString, &description)
            if role as? String == kAXButtonRole, description as? String == label { found = element }
            return found == nil
        }
        return found
    }

    /// The launcher says what Tab will work on: the selection, read through
    /// Accessibility after the panel is up.
    private func launcherPreviewsTheSelection() async {
        let name = "Launcher shows the selection Tab will ask about"
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "Un passage à expliquer"
        textView.selectAll(nil)
        await pause(60)
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        let shown = await waitUntil(timeout: 1.5) { self.context.launcher.shownSelection == "Un passage à expliquer" } != nil
        let speed = context.launcher.lastShowDuration
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, shown, "preview “\(context.launcher.shownSelection ?? "none")”, launcher shown in \(speed.map { "\(Int($0.milliseconds)) ms" } ?? "?")", nil)
    }

    /// Unsure of the route: the routes that can work come as keycaps; 2
    /// picks the second.
    private func askOffersRoutesWhenUnsure() async {
        let name = "Ask unsure of the route offers the routes as keycaps; 2 rewrites"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: [Self.aiFixed], delay: .milliseconds(20))
        context.aiActions.decisionOverride = AskRouter.Decision(
            route: .answer, confidence: 0.3, menu: [], apps: [],
            routes: [(.answer, 0.4), (.rewrite, 0.35), (.act, 0.25)], label: "Test"
        )
        defer {
            context.ai.testEngine = nil
            context.aiActions.decisionOverride = nil
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = Self.aiOriginal
        textView.selectAll(nil)
        await pause(60)
        guard await openAsk() else {
            record(name, false, "no question in the card", nil)
            return
        }
        for character in "fais quelque chose" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let offered = await waitUntil(timeout: 2) { popover.shownQuestion?.text == "What should I do?" } != nil
        await pause(150)
        await saveScreenshot(of: popover.window, as: "ai-card-ask-routes.png")
        await pressKey(nil, code: CGKeyCode(kVK_ANSI_2))
        let done = await waitUntil(timeout: 3) { popover.phase == .done } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == Self.aiFixed } != nil
        record(name, offered && done && replaced && context.aiActions.lastRoute == .rewrite,
               "offered: \(offered), route \(context.aiActions.lastRoute?.rawValue ?? "none"), text now “\(textView.string)”", nil)
    }

    /// D7: ✕ on the setup window is "later", as Later and Done are: each
    /// ends in `onClose` (the app then never shows it by itself), and the
    /// window is gone. Accessibility frozen off: the window shows only it
    /// and the SI card. Never asks macOS.
    private func setupClosedMeansLater() async {
        let name = "Setup: ✕ means later (closed, recorded; it does not open by itself again); only Accessibility and your SI in it"
        let permissions = PermissionCenter()
        permissions.frozenStates = Dictionary(uniqueKeysWithValues: Permission.allCases.map { ($0, PermissionCenter.State.notAsked) })
        let setup = SetupWindowController(permissions: permissions, ai: context.ai, preferences: context.preferences)
        var closes: [Bool] = []
        setup.onClose = { closes.append($0) }
        defer { setup.close() }
        setup.show()
        guard let window = setup.shownWindow, await waitUntil(timeout: 2, { window.isVisible }) != nil else {
            record(name, false, "no setup window", nil)
            return
        }
        // The window's own close button, as a click on ✕.
        let closeButton = window.standardWindowButton(.closeButton)
        let size = window.frame.size
        if let closeButton { closeButton.performClick(nil) } else { window.performClose(nil) }
        let closed = await waitUntil(timeout: 2) { !window.isVisible } != nil
        let recorded = closes == [false]
        let staysClosed = !SetupWindowController.showsByItself(closedOnce: recorded)
        // Shown again on demand (Set Up skil.li…), then Later: recorded too.
        setup.show()
        _ = await waitUntil(timeout: 2) { window.isVisible }
        setup.close()
        let laterToo = await waitUntil(timeout: 2) { !window.isVisible && closes.count == 2 } != nil
        record(name, closeButton != nil && closed && recorded && staysClosed && laterToo && abs(size.height - WelcomeView.size.height) < 1,
               "✕ button: \(closeButton != nil), closed: \(closed), recorded: \(closes), by itself after: \(!staysClosed), Later recorded: \(laterToo), "
                   + "window \(Int(size.width))×\(Int(size.height)) pt", nil)
    }

    /// The welcome while Accessibility waits: behind System Settings at its
    /// usual level (the guide panel points at the switch); the switch on,
    /// back in front, and on to the next step by itself. States are frozen:
    /// System Settings is never opened.
    private func setupComesBackInFront() async {
        let name = "Welcome: waits behind System Settings; comes back in front and moves on when Accessibility turns on"
        let permissions = PermissionCenter()
        permissions.frozenStates = [.accessibility: .waiting, .microphone: .notAsked, .reminders: .notAsked]
        let setup = SetupWindowController(permissions: permissions, ai: context.ai, preferences: context.preferences)
        defer { setup.close() }
        setup.show(at: .accessibility)
        await pause(300)
        guard let setupWindow = setup.shownWindow else {
            record(name, false, "no welcome window", nil)
            return
        }
        // Something else takes the front, as System Settings does.
        guard await focusTestWindow() else { return }
        let wentBehind = !setupWindow.isKeyWindow
        let staysBehind = setupWindow.level == .normal
        permissions.frozenStates = [.accessibility: .granted, .microphone: .notAsked, .reminders: .notAsked]
        let cameBack = await waitUntil(timeout: 2) { setupWindow.isKeyWindow } != nil
        let movedOn = await waitUntil(timeout: 2) { setup.model.step == .hyperKey } != nil
        record(name, wentBehind && staysBehind && cameBack && movedOn,
               "went behind: \(wentBehind), normal level while waiting: \(staysBehind), came back: \(cameBack), "
                   + "on to the Hyper Key by itself: \(movedOn) (step \(setup.model.step))", nil)
    }

    /// The welcome's live steps, as the person does them, with the app's
    /// own welcome (its keys and launcher report to it): Caps Lock held
    /// ticks the Hyper Key; ✦Space then esc ticks the launcher and moves
    /// on; on the practice sentence, the command replaces it and ⌘Z brings
    /// it back. The writer is the self-test's (no tokens).
    private func welcomeLiveSteps() async {
        let name = "Welcome, live: Caps Lock held ticks the Hyper Key; ✦Space then esc ticks the launcher; ⌘Space chosen instead of Spotlight opens it; the practice command then ⌘Z"
        guard let setup = context.welcome(.hyperKey), let window = setup.shownWindow else {
            record(name, false, "no welcome", nil)
            return
        }
        let model = setup.model
        context.ai.testEngine = FakeTextEngine(chunks: ["I wrote this sentence too quickly; it needs fixing."], delay: .milliseconds(20))
        defer {
            context.ai.testEngine = nil
            setup.close()
        }
        _ = await waitUntil(timeout: 2) { window.isKeyWindow }
        guard model.step == .hyperKey else {
            record(name, false, "the Hyper Key step is not shown (Accessibility off?): step \(model.step)", nil)
            return
        }
        // Held past the tap threshold (400 ms): a tap sends Escape, which
        // would close the launcher opened next.
        postKey(Self.ownTriggerKeyCode, down: true)
        let felt = await waitUntil(timeout: 1) { model.hyperFelt && model.hyperHeld } != nil
        await pause(600)
        postKey(Self.ownTriggerKeyCode, down: false)
        let released = await waitUntil(timeout: 1) { !model.hyperHeld } != nil

        model.next()
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        let opened = await waitUntil(timeout: 2) { model.launcherOpen } != nil
        await pause(200)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let tried = await waitUntil(timeout: 2) { model.launcherTried } != nil
        let movedOn = await waitUntil(timeout: 2) { model.step == .intelligence } != nil

        // ⌘Space chosen instead of Spotlight: it opens skil.li, Settings →
        // Keys says it replaces Spotlight's; then the keys go back.
        let launcherKeys = context.shortcuts.config.shortcuts.first { $0.id == "launcher" }?.keys
        model.chooseLauncher("cmd+space")
        let chose = context.shortcuts.config.shortcuts.first { $0.id == "launcher" }?.keys == "cmd+space" && model.launcherError == nil
        context.shortcuts.refreshWarnings()
        // Said only where Spotlight's own ⌘Space is on (off on both test Macs).
        let spotlightOn = context.shortcuts.owners().contains { $0.name == "Show Spotlight search" }
        let note = context.shortcuts.warnings["launcher"]?.message
        let said = spotlightOn ? note == "Replaces macOS's Show Spotlight search." : note == nil
        await pause(200)
        postKey(CGKeyCode(kVK_Space), down: true, flags: .maskCommand)
        await pause(12)
        postKey(CGKeyCode(kVK_Space), down: false, flags: .maskCommand)
        let spotlightKeyOpens = await waitUntil(timeout: 2) { self.context.launcher.isVisible } != nil
        context.launcher.hide()
        try? context.shortcuts.setKeys(launcherKeys.flatMap { try? Chord.sequence($0) }, for: "launcher")

        setup.show(at: .practice)
        _ = await waitUntil(timeout: 2) { window.isKeyWindow }
        await pause(400)
        let selected = (window.firstResponder as? NSTextView)?.selectedRange().length == WelcomeModel.practiceSentence.utf16.count
        let usesFix = model.practiceAction == .aiPrompt("fix")
        if usesFix {
            _ = await hyperChord(["k"], trigger: Self.ownTriggerKeyCode)
            await pressKey("g")
            _ = await waitUntil(timeout: 4) { self.context.aiActions.popover.isVisible && self.context.aiActions.popover.phase == .done }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
        } else {
            _ = await hyperChord(["u"], trigger: Self.ownTriggerKeyCode)
        }
        let fixed = await waitUntil(timeout: 3) { if case .fixed = model.practice { true } else { false } } != nil
        await pause(300)
        await pressKey("z", flags: .maskCommand)
        let undone = await waitUntil(timeout: 2) { model.practice == .undone } != nil
        record(name, felt && released && opened && tried && movedOn && chose && said && spotlightKeyOpens && selected && fixed && undone,
               "held: \(felt), released: \(released); launcher opened: \(opened), closed: \(tried), moved on: \(movedOn); "
                   + "⌘Space chosen: \(chose), “Replaces Spotlight” said: \(said), ⌘Space opens it: \(spotlightKeyOpens); "
                   + "sentence selected: \(selected), \(usesFix ? "✦K G" : "✦U") replaced it: \(fixed), ⌘Z brought it back: \(undone) (\(model.practice))", nil)
    }

    /// The guide at System Settings' switch follows its window: under it
    /// when there is room, centred, never key. The self-test's window stands
    /// in for System Settings'.
    private func settingsGuideFollowsTheWindow() async {
        let name = "Welcome: the guide sits under System Settings' window, centred, follows it, never takes the keyboard"
        guard await focusTestWindow(), let screen = window.screen ?? NSScreen.main else { return }
        let saved = window.frame
        let guide = SettingsGuide()
        guide.followed = { getpid() }
        defer {
            guide.hide()
            window.setFrame(saved, display: true)
        }
        let visible = screen.visibleFrame
        // The largest of our windows, as System Settings' would be.
        func place(_ x: CGFloat) -> NSRect {
            let frame = NSRect(x: x, y: visible.midY - 120, width: 820, height: 520)
            window.setFrame(frame, display: true)
            return frame
        }
        func sits(under frame: NSRect) -> Bool {
            guard let panel = guide.shownPanel, panel.isVisible else { return false }
            let glass = panel.frame.insetBy(dx: Theme.glassMargin, dy: Theme.glassMargin)
            return abs(glass.midX - frame.midX) < 2 && glass.maxY <= frame.minY && frame.minY - glass.maxY < 20
        }
        let first = place(visible.minX + 60)
        guide.show(listName: AccessibilityStage.listName) { false }
        let placed = await waitUntil(timeout: 2) { sits(under: first) } != nil
        let second = place(visible.minX + 220)
        let followed = await waitUntil(timeout: 2) { sits(under: second) } != nil
        let neverKey = guide.shownPanel?.canBecomeKey == false && window.isKeyWindow
        record(name, placed && followed && neverKey,
               "under the window, centred: \(placed); followed it: \(followed); never key: \(neverKey); panel \(guide.shownPanel.map { NSStringFromRect($0.frame) } ?? "none")", nil)
    }

    /// Keep Awake holds a real power assertion until run again; the launcher
    /// finds it by "awake".
    private func keepAwakeHoldsTheMac() async {
        let name = "Keep Awake: “awake” finds it; it holds macOS awake until run again"
        guard let commands = context.tools.tools.systemCommands else {
            record(name, false, "no system commands", nil)
            return
        }
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "awake" { await pressKey(character) }
        let found = await waitUntil(timeout: 1) { self.context.launcher.topResultName == "Keep Awake" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        func assertions() async -> String {
            (try? await ClaudeCLI.run(URL(fileURLWithPath: "/usr/bin/pmset"), ["-g", "assertions"], timeout: 10)) ?? ""
        }
        _ = try? await commands.run(.keepAwake)
        let held = await assertions().contains("skil.li Keep Awake") && commands.isKeepingAwake
        _ = try? await commands.run(.keepAwake)
        let released = !(await assertions().contains("skil.li Keep Awake")) && !commands.isKeepingAwake
        record(name, found && held && released, "found by “awake”: \(found), held: \(held), released: \(released)", nil)
    }

    /// "awake 1 hour" in the launcher: Return keeps the Mac awake about an
    /// hour (a real power assertion, its end in the menu); "allow sleep"
    /// typed in Ask lets it sleep again, without a model.
    private func keepAwakeForAWhile() async {
        let name = "Keep Awake for a while: “awake 1 hour” in the launcher, “do not sleep 2” read as hours, the cup in the menu bar; Ask's values from the model (1 h 30, done with ⌘Z when unsure, off with no time)"
        guard let commands = context.tools.tools.systemCommands else {
            record(name, false, "no system commands", nil)
            return
        }
        func assertions() async -> String {
            (try? await ClaudeCLI.run(URL(fileURLWithPath: "/usr/bin/pmset"), ["-g", "assertions"], timeout: 10)) ?? ""
        }
        defer { if commands.isKeepingAwake { _ = commands.keepAwake(.allowSleep) } }
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "do not sleep 2" { await pressKey(character) }
        let hours = await waitUntil(timeout: 1) { (self.context.launcher.topResultName ?? "").hasPrefix("Keep Awake · 2 h") } != nil
        for _ in 0..<14 { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }
        for character in "awake 1 hour" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { (self.context.launcher.topResultName ?? "").hasPrefix("Keep Awake · 1 h (until ") } != nil
        let title = context.launcher.topResultName ?? ""
        if listed { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let heldNow = await waitUntil(timeout: 2) { commands.isKeepingAwake } != nil
        let asserted = await assertions()
        let held = heldNow && asserted.contains("skil.li Keep Awake")
        let left = commands.awakeUntil.map { $0.timeIntervalSinceNow } ?? 0
        let anHour = abs(left - 3_600) < 60
        // Seen to work: the cup in the menu bar with the time left.
        let cup = await waitUntil(timeout: 1) { ["60 min", "1 h"].contains(self.context.awakeIndicator.shown?.trimmingCharacters(in: .whitespaces) ?? "") } != nil
        let cupShown = context.awakeIndicator.shown ?? "none"
        // The cup as the menu bar draws it (a template image): full, not
        // an empty cup. ScreenCaptureKit does not answer for a menu bar
        // item's window: the image itself is saved.
        if let directory = context.snapshotDirectory {
            if let rep = AwakeIndicator.cup?.representations.compactMap({ $0 as? NSBitmapImageRep }).last,
               let png = rep.representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("menu-bar-cup-image.png"))
            }
        }
        // The cup says it: no card.
        await pause(300)
        let quiet = !context.aiActions.popover.isVisible
        if !quiet { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        // Ask, its model picking Keep Awake, the time said in words (asked
        // 2026-10-16: it stayed awake until stopped): awake that long.
        _ = commands.keepAwake(.allowSleep)
        context.aiActions.decisionOverride = AskRouter.Decision(route: .command, confidence: 0.91, menu: [], routes: [(.command, 0.91)],
                                                                command: (.system(.keepAwake), 0.91), commands: [(.system(.keepAwake), 0.91)],
                                                                label: "Test")
        // Its values as the model reads them (`AskValues`; real ones in
        // `selftest decide`): "une heure trente" is 1 h 30, never 1 h.
        context.aiActions.valuesOverride = ["length": .init(choice: "1 h 30", confidence: 0.93)]
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "garde mon ordi hors veille pendant une heure trente"])
        let saidAnHour = await waitUntil(timeout: 3) {
            commands.isKeepingAwake && abs((commands.awakeUntil?.timeIntervalSinceNow ?? 0) - 5_400) < 60
        } != nil
        await pause(300)
        if context.aiActions.popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        // Unsure of a part: done all the same, what it understood said
        // with ⌘Z, which lets the Mac sleep again; ↩ is not the card's.
        _ = commands.keepAwake(.allowSleep)
        context.aiActions.valuesOverride?["length"] = .init(choice: "1 h 30", confidence: 0.35)
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "garde mon ordi hors veille pendant une heure trente"])
        let checked = await waitUntil(timeout: 3) {
            let popover = self.context.aiActions.popover
            return popover.isVisible && popover.shownText.contains("1 h 30") && popover.hintTitles == ["Undo", "Close"] && commands.isKeepingAwake
        } != nil
        await pressKey("z", flags: .maskCommand)
        let keptAfterReturn = await waitUntil(timeout: 2) { !commands.isKeepingAwake && !self.context.aiActions.popover.isVisible } != nil
        // Kept awake again for what follows.
        _ = commands.keepAwake(.awake(seconds: 600))

        // "laisse-le dormir": Keep Awake again with no time said, the Mac
        // sleeps as usual again.
        context.aiActions.valuesOverride = ["length": .init(choice: "none", confidence: 0.95)]
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "laisse le mac dormir"])
        let releasedNow = await waitUntil(timeout: 2) { !commands.isKeepingAwake } != nil
        await pause(300)
        if context.aiActions.popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        // Nothing read (the model failed): said, Keep Awake left as it was.
        _ = commands.keepAwake(.awake(seconds: 600))
        context.aiActions.valuesOverride = [:]
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "garde le mac éveillé"])
        let unreadSaid = await waitUntil(timeout: 2) {
            self.context.aiActions.popover.isVisible && self.context.aiActions.popover.shownText.contains("could not read how long")
        } != nil
        let unreadKept = commands.isKeepingAwake
        if context.aiActions.popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = commands.keepAwake(.allowSleep)
        context.aiActions.decisionOverride = nil
        context.aiActions.valuesOverride = nil
        let after = await assertions()
        let released = releasedNow && !after.contains("skil.li Keep Awake")
        await pause(300)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let cupGone = context.awakeIndicator.shown == nil
        record(name, hours && listed && held && anHour && cup && quiet && saidAnHour && checked && keptAfterReturn && released && cupGone && commands.awakeUntil == nil
                   && unreadSaid && unreadKept,
               "“do not sleep 2” → 2 h: \(hours); listed “\(title)”: \(listed); held: \(held), \(Int(left)) s left; cup in the menu bar “\(cupShown)”: \(cup), no card: \(quiet); "
                   + "Ask “… une heure trente” → 1 h 30: \(saidAnHour); unsure, done at once with Undo: \(checked), ⌘Z let it sleep: \(keptAfterReturn); "
                   + "Keep Awake again with no time released it: \(released), cup gone: \(cupGone); nothing read: said \(unreadSaid), left on \(unreadKept)", nil)
    }

    /// Kept awake, seen in the launcher and turned off from it: the cup and
    /// the time left at the right of the empty field (gone at the first
    /// key, back on ⌫); under the real pointer it says "42 min · Turn Off"
    /// (its tooltip too) and a real click turns Keep Awake off at once, the
    /// launcher still open, no card. "awake" lists it running, "Keep Awake
    /// on · until 14:05 (42 min left)", Turn Off Keep Awake ↩ and, in ⌘K,
    /// Keep Awake 1 h Longer, which adds the hour; "awake 2h" lists the new
    /// length first; "turn off awake" ↩ turns it off. Untimed: the cup
    /// alone, "Turn Off" under the pointer, Turn Off in 1 h.
    private func keepAwakeSeenInTheLauncher() async {
        let name = "Keep Awake in the launcher: the cup and time left beside the empty field, “· Turn Off” under the pointer and a click turns it off; “awake” lists it running (Turn Off Keep Awake ↩, ⌘K 1 h Longer); untimed: the cup alone"
        guard let commands = context.tools.tools.systemCommands else {
            record(name, false, "no system commands", nil)
            return
        }
        let launcher = context.launcher
        let popover = context.aiActions.popover
        defer { if commands.isKeepingAwake { _ = commands.keepAwake(.allowSleep) } }
        func open() async -> Bool {
            if launcher.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = await waitUntil(timeout: 1) { !launcher.isVisible }
            guard await focusTestWindow() else { return false }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            return await waitUntil(timeout: 1) { launcher.isVisible && launcher.query.isEmpty } != nil
        }
        func clear() async {
            for _ in 0..<launcher.query.count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }
        }
        /// The real pointer over the chip (nil: no chip), or away from it.
        func chipPoint() -> CGPoint? {
            guard let frame = launcher.awakeChipScreenFrame, let height = NSScreen.screens.first?.frame.height else { return nil }
            return CGPoint(x: frame.midX, y: height - frame.midY)
        }
        func moveMouse(to point: CGPoint) async {
            CGEvent(mouseEventSource: CGEventSource(stateID: .hidSystemState), mouseType: .mouseMoved, mouseCursorPosition: point, mouseButton: .left)?
                .post(tap: .cghidEventTap)
            await pause(150)
        }
        func pointerAway() async {
            guard let height = NSScreen.screens.first?.frame.height else { return }
            let glass = launcher.glassFrame
            await moveMouse(to: CGPoint(x: glass.midX, y: height - glass.midY))
        }
        func turnOffRows() -> Int { launcher.resultTitles.filter { $0 == AwakeStatus.turnOff }.count }

        // Timed: 42 minutes left.
        _ = commands.keepAwake(.awake(seconds: 42 * 60))
        guard await open() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        await pointerAway()
        let chipShown = await waitUntil(timeout: 1) { launcher.awakeChipDrawn == "42 min" } != nil
        let chipSaid = launcher.awakeChipDrawn ?? "hidden"
        await captureLauncherBothWays(as: "launcher-awake-chip")
        await pressKey("a")
        let goneOnKey = await waitUntil(timeout: 1) { launcher.awakeChipText == nil } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        let backOnDelete = await waitUntil(timeout: 1) { launcher.awakeChipText == "42 min" } != nil

        // Under the real pointer: what a click does, and its tooltip.
        var hovered = false, tip = "", hoverSaid = ""
        if let point = chipPoint() {
            await moveMouse(to: point)
            hovered = await waitUntil(timeout: 1) { launcher.awakeChipDrawn == "42 min · Turn Off" } != nil
            hoverSaid = launcher.awakeChipDrawn ?? "hidden"
            tip = launcher.awakeChipTip ?? ""
            await captureLauncherBothWays(as: "launcher-awake-chip-hover")
        }
        let tipSays = tip == "Turn Off Keep Awake (42 min left)"
        // A real click: off at once, the chip gone, the launcher still
        // open, nothing said, the menu bar's cup gone.
        var turnedOff = false
        if let point = chipPoint() {
            await mouseClick(at: point)
            turnedOff = await waitUntil(timeout: 1) {
                !commands.isKeepingAwake && launcher.awakeChipText == nil && self.context.awakeIndicator.shown == nil
            } != nil
        }
        let stayedOpen = launcher.isVisible
        await pause(300)
        let quiet = !popover.isVisible
        await captureLauncherBothWays(as: "launcher-awake-turned-off")
        await pointerAway()

        // Typed: the running row first, its state and end said plainly.
        _ = commands.keepAwake(.awake(seconds: 42 * 60))
        _ = await open()
        for character in "awake" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) {
            let top = launcher.topResultName ?? ""
            return top.hasPrefix("Keep Awake on · until ") && top.hasSuffix(" (42 min left)")
        } != nil
        let rows = launcher.resultTitles.prefix(3).joined(separator: " | ")
        let footer = launcher.shownFooter
        let footerSays = footer.first == "Turn Off Keep Awake ↩"
        // Keep Awake's own row ("Turn Off Keep Awake" while awake) leaves for it.
        let noTwin = turnOffRows() == 0
        await captureLauncherBothWays(as: "launcher-awake-running")
        await pressKey("k", flags: .maskCommand)
        let offered = await waitUntil(timeout: 1) {
            launcher.shownActions.map(\.title).prefix(2) == ["Turn Off Keep Awake", "Keep Awake 1 h Longer"]
        } != nil
        let actions = launcher.shownActions.map(\.title).joined(separator: ", ")
        await captureLauncherBothWays(as: "launcher-awake-actions")
        // ↓ ↩ only on this row's own list: never another row's action.
        guard listed, offered else {
            for _ in 0..<3 { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            record(name, false, "chip “\(chipSaid)”: \(chipShown); hover “\(hoverSaid)”: \(hovered); click turned it off: \(turnedOff); rows “\(rows)”: \(listed); ⌘K “\(actions)”: \(offered); stopped before ↩", nil)
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let longer = await waitUntil(timeout: 1) {
            abs((commands.awakeUntil?.timeIntervalSinceNow ?? 0) - Double(102 * 60)) < 30 && !launcher.isVisible
        } != nil
        let quietLonger = !popover.isVisible

        // A length typed: the new one first, the running row next; then
        // "turn off awake" ↩ turns it off.
        _ = await open()
        for character in "awake 2h" { await pressKey(character) }
        let both = await waitUntil(timeout: 1) {
            let titles = launcher.resultTitles
            return titles.count > 1 && titles[0].hasPrefix("Keep Awake · 2 h") && titles[1].hasPrefix("Keep Awake on · until ")
                && titles[1].hasSuffix(" (1 h 42 left)")
        } != nil
        let bothRows = launcher.resultTitles.prefix(2).joined(separator: " | ")
        await clear()
        for character in "turn off awake" { await pressKey(character) }
        let offRow = await waitUntil(timeout: 1) { launcher.topResultName == AwakeStatus.turnOff && self.turnOffRowsCount(launcher) == 1 } != nil
        // ↩ only on the turn-off row: never Ask "turn off awake" or another row.
        guard offRow else {
            for _ in 0..<2 { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            record(name, false, "“turn off awake” did not list “\(AwakeStatus.turnOff)” first: “\(launcher.resultTitles.prefix(3).joined(separator: " | "))”; stopped before ↩", nil)
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let offTyped = await waitUntil(timeout: 1) { !commands.isKeepingAwake && self.context.awakeIndicator.shown == nil } != nil

        // Untimed: the cup alone, "Turn Off" under the pointer; ⌘K gives it
        // an end in an hour.
        _ = try? await commands.run(.keepAwake)
        _ = await open()
        await pointerAway()
        let cupAlone = await waitUntil(timeout: 1) { launcher.awakeChipDrawn == "" } != nil
        await captureLauncherBothWays(as: "launcher-awake-chip-untimed")
        var untimedHover = false
        if let point = chipPoint() {
            await moveMouse(to: point)
            untimedHover = await waitUntil(timeout: 1) { launcher.awakeChipDrawn == "Turn Off" } != nil
            await captureLauncherBothWays(as: "launcher-awake-chip-untimed-hover")
            await pointerAway()
        }
        for character in "keep awake" { await pressKey(character) }
        let untimedListed = await waitUntil(timeout: 1) { launcher.topResultName == "Keep Awake on · until you turn it off" } != nil
        await pressKey("k", flags: .maskCommand)
        let untimedOffered = await waitUntil(timeout: 1) { launcher.shownActions.map(\.title).contains("Turn Off in 1 h") } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = commands.keepAwake(.allowSleep)

        // Left open, it counts down: 61 s left reads "2 min", then "1 min"
        // at the next tick (20 s).
        _ = commands.keepAwake(.awake(seconds: 61))
        _ = await open()
        let twoLeft = await waitUntil(timeout: 1) { launcher.awakeChipText == "2 min" } != nil
        let oneLeft = await waitUntil(timeout: 26) { launcher.awakeChipText == "1 min" } != nil
        let counted = twoLeft && oneLeft
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = commands.keepAwake(.allowSleep)

        // Not kept awake: no chip, no running row.
        _ = await open()
        await pause(150)
        let noChip = launcher.awakeChipText == nil
        for character in "awake" { await pressKey(character) }
        await pause(150)
        let noRow = !(launcher.topResultName ?? "").hasPrefix("Keep Awake on")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        record(name, chipShown && goneOnKey && backOnDelete && hovered && tipSays && turnedOff && stayedOpen && quiet
                   && listed && footerSays && noTwin && offered && longer && quietLonger && both && offRow && offTyped
                   && cupAlone && untimedHover && untimedListed && untimedOffered && counted && noChip && noRow,
               "chip “\(chipSaid)”: \(chipShown), gone on a key: \(goneOnKey), back on ⌫: \(backOnDelete); hover “\(hoverSaid)”: \(hovered), tooltip “\(tip)”: \(tipSays); "
                   + "click turned it off: \(turnedOff), launcher still open: \(stayedOpen), no card: \(quiet); "
                   + "rows “\(rows)”: \(listed), footer \(footer): \(footerSays), no twin: \(noTwin); ⌘K “\(actions)”: \(offered), 1 h longer: \(longer), no card: \(quietLonger); "
                   + "“awake 2h” → “\(bothRows)”: \(both); “turn off awake” first: \(offRow), ↩ off and cup gone: \(offTyped); "
                   + "untimed: cup alone \(cupAlone), “Turn Off” under the pointer \(untimedHover), listed \(untimedListed), Turn Off in 1 h \(untimedOffered); "
                   + "counted down while open: \(counted); not awake: no chip \(noChip), no row \(noRow)", nil)
    }

    private func turnOffRowsCount(_ launcher: LauncherController) -> Int {
        launcher.resultTitles.filter { $0 == AwakeStatus.turnOff }.count
    }

    /// The Mac commands through macOS's own APIs, no keys pressed, no other
    /// app asked: the lock is found (not called: it would lock this Mac),
    /// a scratch disk image is mounted then ejected through NSWorkspace,
    /// the volume is read and set through CoreAudio and put back.
    /// Quit All Apps asks first, naming them (no: nothing quits); Hide
    /// Other Apps hides Chess, Show All Apps brings it back; the microphone
    /// muted and back, when this Mac has one.
    private func appsQuitHideAndMicrophone() async {
        let name = "Apps in one key: Quit All asks first naming them (no: nothing quits); Hide Other Apps, Show All Apps; the microphone muted and back"
        guard let commands = context.aiActions.systemCommands else {
            record(name, false, "no Mac commands", nil)
            return
        }
        let open = SystemCommands.openApps()
        let leftOut = !open.contains { $0.processIdentifier == getpid() || $0.bundleIdentifier == "com.apple.finder" }
        let confirm = commands.confirm
        var asked = ""
        commands.confirm = { title, detail, verb in
            asked = "\(title) \(detail) ↩ \(verb)"
            return false
        }
        let said = (try? await commands.run(.quitAllApps)) ?? ""
        commands.confirm = confirm
        let declined = said == "Not done: you declined." && open.allSatisfy { !$0.isTerminated }
            && asked.hasPrefix("Quit ") && asked.hasSuffix("↩ Quit") && open.compactMap(\.localizedName).contains { asked.contains($0) }

        // Chess, opened hidden (it comes forward otherwise).
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.Chess").isEmpty
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = false
        configuration.hides = true
        let chess = try? await NSWorkspace.shared.openApplication(at: URL(fileURLWithPath: "/System/Applications/Chess.app"), configuration: configuration)
        _ = await waitUntil(timeout: 5) { chess?.isFinishedLaunching == true }
        _ = try? await commands.run(.showAllApps)
        let shown = await waitUntil(timeout: 3) { chess?.isHidden == false } != nil
        _ = await focusTestWindow()
        _ = try? await commands.run(.hideOtherApps)
        let hidden = await waitUntil(timeout: 3) { chess?.isHidden == true } != nil
        _ = try? await commands.run(.showAllApps)
        if !wasRunning { chess?.terminate() }

        var mic = "no microphone on this Mac"
        var micOK = true
        if let before = AudioDevices.inputMuted {
            let first = try? AudioDevices.toggleInputMute()
            let second = try? AudioDevices.toggleInputMute()
            micOK = first == !before && second == before && AudioDevices.inputMuted == before
            mic = "muted \(first.map(String.init) ?? "failed"), then \(second.map(String.init) ?? "failed"), back as it was: \(AudioDevices.inputMuted == before)"
        }
        record(name, leftOut && declined && shown && hidden && micOK,
               "skil.li and Finder left out: \(leftOut); asked “\(asked.prefix(80))”, declined, nothing quit: \(declined); Show All: \(shown), Hide Others: \(hidden); \(mic)", nil)
    }

    private func macCommandsUseRealAPIs() async {
        let name = "Mac commands through macOS's APIs: lock found, a disk image ejected, the volume read and set (CoreAudio)"
        let lock = SystemCommands.canLockDirectly
        var details = ["lock: \(lock ? "SACLockScreenImmediate found" : "not found")"]

        // Eject: only when no disk of the user's could be ejected too.
        func ejectable() -> [String] {
            let keys: Set<URLResourceKey> = [.volumeIsEjectableKey, .volumeIsRemovableKey, .volumeIsLocalKey, .volumeIsRootFileSystemKey]
            return (FileManager.default.mountedVolumeURLs(includingResourceValuesForKeys: Array(keys), options: [.skipHiddenVolumes]) ?? [])
                .filter { url in
                    guard let values = try? url.resourceValues(forKeys: keys), values.volumeIsRootFileSystem != true else { return false }
                    return values.volumeIsEjectable == true || values.volumeIsRemovable == true || values.volumeIsLocal == false
                }
                .map(\.path)
        }
        var ejected = false
        let others = ejectable()
        if others.isEmpty {
            let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-eject", isDirectory: true)
            try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
            defer { try? FileManager.default.removeItem(at: folder) }
            let image = folder.appendingPathComponent("eject.dmg").path
            let hdiutil = URL(fileURLWithPath: "/usr/bin/hdiutil")
            _ = try? await ClaudeCLI.run(hdiutil, ["create", "-size", "2m", "-fs", "APFS", "-volname", "skilli-eject-test", image], timeout: 60)
            _ = try? await ClaudeCLI.run(hdiutil, ["attach", image], timeout: 60)
            let mounted = await waitUntil(timeout: 5) { ejectable().contains { $0.hasSuffix("/skilli-eject-test") } } != nil
            var said = "not mounted"
            if mounted {
                do { said = try await SystemCommands.ejectDisks() } catch { said = error.localizedDescription }
            }
            ejected = mounted && ejectable().isEmpty
            if !ejected { _ = try? await ClaudeCLI.run(hdiutil, ["detach", "/Volumes/skilli-eject-test", "-force"], timeout: 30) }
            details.append("disk image mounted: \(mounted), “\(said)”, gone: \(ejected)")
        } else {
            details.append("eject skipped: this Mac has disks of its own \(others)")
        }

        // Volume: CoreAudio, put back after.
        var volumeOK = false
        if let before = AudioDevices.outputVolume {
            let target = before > 50 ? before - 10 : before + 10
            let set = (try? SystemCommands.setVolume(target)) != nil
            let read = AudioDevices.outputVolume
            _ = try? SystemCommands.setVolume(before)
            volumeOK = set && read.map { abs($0 - target) <= 1 } == true && AudioDevices.outputVolume.map { abs($0 - before) <= 1 } == true
            details.append("volume \(before) → \(read.map(String.init) ?? "?") (asked \(target)) → back \(AudioDevices.outputVolume.map(String.init) ?? "?")")
        } else {
            details.append("volume: this output has none")
            volumeOK = true
        }
        record(name, lock && (ejected || !others.isEmpty) && volumeOK, details.joined(separator: "; "), nil)
    }

    /// Wi-Fi, Bluetooth and the volume at a level, on the Mac mini whose SSH
    /// rides on its Wi-Fi: Wi-Fi is read and only asked to be what it is
    /// (the call allowed, nothing changed), never turned off; Bluetooth
    /// devices are listed, their rows shown, Return said as a dry run
    /// (connecting AirPods here would take them from the user's Mac);
    /// "volume 30" sets the level from the launcher, put back after.
    private func wifiBluetoothAndVolumeLevel() async {
        let name = "Mac commands: Wi-Fi read, its switch allowed (never turned off here), its one row; Bluetooth devices listed with their rows (dry run); “volume 30” in the launcher sets the level"
        guard let commands = context.aiActions.systemCommands else {
            record(name, false, "no Mac commands", nil)
            return
        }
        commands.radiosDryRun = true
        defer { commands.radiosDryRun = false }
        var details: [String] = []
        var passed = true
        func launcherRows(_ typed: String) async -> [String] {
            guard await focusTestWindow() else { return [] }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            await pause(250)
            for character in typed { await pressKey(character) }
            await pause(300)
            let rows = context.launcher.resultTitles
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            await pause(150)
            return rows
        }

        // Wi-Fi: read, asked to be what it is, the one row that applies.
        if let on = WiFi.isOn() {
            var said = ""
            do { said = try await commands.run(on ? .wifiOn : .wifiOff) } catch { said = error.localizedDescription }
            let unchanged = WiFi.isOn() == on
            let other = (try? await commands.run(on ? .wifiOff : .wifiOn)) ?? "failed"
            let stillSame = WiFi.isOn() == on
            let info = SystemCommands.systemInfo().split(separator: "\n").first { $0.hasPrefix("Wi-Fi") }.map(String.init) ?? "no Wi-Fi line"
            let rows = await launcherRows("wifi")
            let oneRow = rows.contains(on ? "Turn Wi-Fi Off" : "Turn Wi-Fi On") && !rows.contains(on ? "Turn Wi-Fi On" : "Turn Wi-Fi Off")
            passed = passed && unchanged && stillSame && other.hasPrefix("Would turn") && info.hasPrefix("Wi-Fi") && oneRow
            details.append("Wi-Fi \(on ? "on" : "off"): asked so, “\(said)”, unchanged \(unchanged); the other way dry “\(other)”, unchanged \(stillSame); System Info “\(info)”; rows \(rows.prefix(3)) one way only: \(oneRow)")
        } else {
            details.append("no Wi-Fi on this Mac")
        }

        // Bluetooth: only when skil.li may (macOS would ask otherwise).
        switch BluetoothDevices.authorization {
        case .allowedAlways:
            let devices = BluetoothDevices.paired()
            let accessories = devices.filter(\.kind.isAccessory)
            details.append("Bluetooth: \(devices.count) paired (\(devices.prefix(6).map { "\($0.name) \($0.kind.rawValue)\($0.connected ? " connected" : "")" }.joined(separator: ", ")))")
            if let device = accessories.first {
                let rows = await launcherRows(device.name.lowercased())
                let title = BluetoothRoute.title(name: device.name, connect: !device.connected)
                let listed = rows.contains(title)
                let said = (try? await commands.run(.bluetooth(BluetoothTarget(device), connect: !device.connected))) ?? "failed"
                let dry = said.hasPrefix("Would ")
                let unchanged = BluetoothDevices.paired().first { $0.address == device.address }?.connected == device.connected
                passed = passed && listed && dry && unchanged
                details.append("row “\(title)”: \(listed) (\(rows.prefix(3))); Return, dry: “\(said)”; nothing changed: \(unchanged)")
            }
        case .notDetermined:
            let rows = await launcherRows("bluetooth")
            let allow = rows.first?.hasPrefix("Allow Bluetooth") == true
            passed = passed && allow
            details.append("Bluetooth not asked yet: the launcher offers to allow it first: \(allow) (\(rows.prefix(2))); not asked here (macOS would wait for a click)")
        default:
            details.append("Bluetooth not allowed for the self-test app: devices not listed")
        }

        // The volume at a level, from the launcher, put back.
        if let original = SystemCommands.volume {
            let target = original == 30 ? 40 : 30
            guard await focusTestWindow() else { return }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            await pause(250)
            for character in "volume \(target)" { await pressKey(character) }
            let offered = await waitUntil(timeout: 1) { self.context.launcher.topResultName == VolumeRequest.title(target) } != nil
            if offered { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            let set = await waitUntil(timeout: 2) { SystemCommands.volume == target } != nil
            // The level the user chose is heard, not said.
            await pause(300)
            let quiet = !context.aiActions.popover.isVisible
            if context.aiActions.popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            _ = try? SystemCommands.setVolume(original)
            passed = passed && offered && set && quiet
            details.append("“volume \(target)”: first row \(offered), set \(set), nothing said \(quiet); back to \(original)")
        } else {
            details.append("no output volume on this Mac: volume skipped")
        }
        record(name, passed, details.joined(separator: "; "), nil)
    }

    /// Auto Quit, decided only (nothing quit): Calculator, opened hidden
    /// and unused for two hours, is quit (or kept by Jev with a reason, when a
    /// deciding key is there); a window holding unsaved work (the test
    /// form, another process) keeps its app.
    private func autoQuitKeepsWhatIsInUse() async {
        let name = "Auto Quit: an app unused past the delay would go (dry run); a window with unsaved work keeps its app; the app in front and skil.li never"
        let quitter = context.autoQuitter
        let preferences = context.preferences
        let saved = (preferences.autoQuit, preferences.autoQuitMinutes, preferences.autoQuitNever)
        quitter.dryRun = true
        preferences.autoQuitMinutes = 60
        preferences.autoQuitNever = []
        defer {
            quitter.dryRun = false
            preferences.autoQuit = saved.0
            preferences.autoQuitMinutes = saved.1
            preferences.autoQuitNever = saved.2
        }
        // Calculator: one plain window, idle once open.
        let bundleID = "com.apple.calculator"
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = false
        configuration.hides = true
        let opened = try? await NSWorkspace.shared.openApplication(at: URL(fileURLWithPath: "/System/Applications/Calculator.app"), configuration: configuration)
        _ = await waitUntil(timeout: 5) { opened?.isFinishedLaunching == true }
        guard let app = opened else {
            record(name, false, "Calculator did not open", nil)
            return
        }
        // Just opened, it is busy drawing: idle a moment later.
        await pause(3000)
        let appName = app.localizedName ?? "Calculator"
        quitter.pretendUnused(app.processIdentifier, since: Date.now.addingTimeInterval(-2 * 3_600))
        _ = await focusTestWindow()
        await quitter.check()
        quitter.pretendUnused(app.processIdentifier, since: nil)
        let wouldQuit = quitter.lastQuit.contains(appName)
        let keptWhy = quitter.lastKept.first { $0.name == appName }?.why
        let decided = wouldQuit || keptWhy?.hasPrefix("Jev") == true
        let stillOpen = !app.isTerminated
        let selfKept = !quitter.lastQuit.contains { $0 == "skil.li" || $0 == "Finder" }
        let calculatorWindows = decided ? "" : " (" + Self.editedAttributes(app.processIdentifier) + ")"
        if !wasRunning { app.terminate() }

        // Unsaved work, read through Accessibility in another process.
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-autoquit-\(UUID().uuidString)")
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        let process = Process()
        process.executableURL = Bundle.main.executableURL
        process.arguments = ["testform", folder.appendingPathComponent("state.json").path, "edited"]
        var unsaved = "test form did not start"
        var keepsUnsaved = false
        if (try? process.run()) != nil {
            let pid = process.processIdentifier
            _ = await waitUntil(timeout: 5) {
                var value: CFTypeRef?
                return AXUIElementCopyAttributeValue(AXUIElementCreateApplication(pid), kAXWindowsAttribute as CFString, &value) == .success
                    && (value as? [AXUIElement])?.isEmpty == false
            }
            let state = await Task.detached { AutoQuitter.windows(of: pid) }.value
            keepsUnsaved = state.keeps?.contains("unsaved") == true
            unsaved = state.keeps ?? "nothing kept it (titles \(state.titles))"
            if !keepsUnsaved { unsaved += "; " + Self.editedAttributes(pid) }
            process.terminate()
        }
        _ = await focusTestWindow()
        record(name, decided && stillOpen && selfKept && keepsUnsaved,
               "\(appName) unused 2 h: would quit \(wouldQuit)\(keptWhy.map { ", kept: \($0)" } ?? "")\(calculatorWindows), still open (dry run) \(stillOpen); "
                   + "skil.li and Finder never: \(selfKept); quit \(quitter.lastQuit), kept \(quitter.lastKept.map { "\($0.name): \($0.why)" }); "
                   + "a window with unsaved work: “\(unsaved)”", nil)
    }

    /// What Accessibility says of a process's first window and its close
    /// button: their attributes, and AXEdited on each.
    nonisolated private static func editedAttributes(_ pid: pid_t) -> String {
        let app = AXUIElementCreateApplication(pid)
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(app, kAXWindowsAttribute as CFString, &value) == .success,
              let window = (value as? [AXUIElement])?.first else { return "no window" }
        func names(_ element: AXUIElement) -> [String] {
            var names: CFArray?
            AXUIElementCopyAttributeNames(element, &names)
            return (names as? [String]) ?? []
        }
        func edited(_ element: AXUIElement) -> String {
            var value: CFTypeRef?
            let status = AXUIElementCopyAttributeValue(element, kAXEditedAttribute as CFString, &value)
            return "\(status.rawValue) \(value.map { "\($0)" } ?? "nil")"
        }
        var close: CFTypeRef?
        AXUIElementCopyAttributeValue(window, kAXCloseButtonAttribute as CFString, &close)
        let button = close.flatMap { CFGetTypeID($0) == AXUIElementGetTypeID() ? ($0 as! AXUIElement) : nil }
        var subrole: CFTypeRef?
        AXUIElementCopyAttributeValue(window, kAXSubroleAttribute as CFString, &subrole)
        return "window \((subrole as? String) ?? "no subrole") \(names(window)) AXEdited \(edited(window)); close \(button.map(names) ?? []) AXEdited \(button.map(edited) ?? "no button")"
    }

    /// Show Desktop: the user's own shortcut (System Settings → Keyboard →
    /// Mission Control), pressed as a keyboard does; the test window moves
    /// aside, then back the second time.
    private func showDesktopMovesWindowsAside() async {
        let name = "Show Desktop: the user's own shortcut moves the windows aside, again brings them back"
        guard await focusTestWindow() else { return }
        func bounds() -> CGRect? {
            let list = CGWindowListCopyWindowInfo([.optionIncludingWindow], CGWindowID(window.windowNumber)) as? [[String: Any]]
            guard let info = list?.first, let rect = info[kCGWindowBounds as String] as? NSDictionary else { return nil }
            return CGRect(dictionaryRepresentation: rect)
        }
        func onScreen() -> Bool {
            let list = CGWindowListCopyWindowInfo([.optionOnScreenOnly], kCGNullWindowID) as? [[String: Any]] ?? []
            return list.contains { ($0[kCGWindowNumber as String] as? Int) == window.windowNumber }
        }
        let before = bounds()
        var said = "pressed"
        do { try SystemCommands.showDesktop() } catch { said = error.localizedDescription }
        let aside = await waitUntil(timeout: 2.5) { bounds() != before || !onScreen() } != nil
        let asideBounds = bounds()
        let asideOnScreen = onScreen()
        await pause(400)
        try? SystemCommands.showDesktop()
        let back = await waitUntil(timeout: 2.5) { bounds() == before && onScreen() } != nil
        if !back { _ = await focusTestWindow() }
        record(name, aside && back,
               "“\(said)”; aside: \(aside) (\(before.map { "\(Int($0.minX)),\(Int($0.minY))" } ?? "?") → \(asideBounds.map { "\(Int($0.minX)),\(Int($0.minY))" } ?? "?"), on screen \(asideOnScreen)); back: \(back)", nil)
    }

    /// Kill Process on throwaway processes: a `sleep` by name, an `nc`
    /// listening on a free port by its number. Return closes the launcher;
    /// the card confirms (even if the user chose Always), then goes: the
    /// process gone is the answer.
    private func killProcessByNameAndPort() async {
        let name = "Kill Process: “kill” becomes a chip; Return closes and quits at once, without a word; by name and by port; ⌫ leaves; ⇥ shows a row's actions, esc goes back then closes"
        func spawn(_ path: String, _ arguments: [String]) -> Process? {
            let process = Process()
            process.executableURL = URL(fileURLWithPath: path)
            process.arguments = arguments
            process.standardOutput = FileHandle.nullDevice
            process.standardError = FileHandle.nullDevice
            return (try? process.run()) == nil ? nil : process
        }
        let port = Int.random(in: 49_200...49_900)
        let otherPort = port + 1
        guard let sleeper = spawn("/bin/sleep", ["600"]), let listener = spawn("/usr/bin/nc", ["-l", "\(port)"]),
              let other = spawn("/usr/bin/nc", ["-l", "\(otherPort)"]) else {
            record(name, false, "could not start the test processes", nil)
            return
        }
        defer {
            sleeper.terminate()
            listener.terminate()
            other.terminate()
        }
        await pause(400)
        let popover = context.aiActions.popover
        // Return closes the launcher and quits at once (the app may ask to
        // save itself): no question in the card.
        func quitTopRow() async -> (asked: Bool, closed: Bool, said: String) {
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let closed = await waitUntil(timeout: 1) { !self.context.launcher.isVisible } != nil
            let asked = await waitUntil(timeout: 1) { popover.isVisible && popover.phase == .approving } != nil
            if asked { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
            _ = await waitUntil(timeout: 2) { !popover.isVisible }
            let said = popover.isVisible ? popover.shownText : ""
            if popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            return (asked, closed, said)
        }
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "kill sleep" { await pressKey(character) }
        let listedSleep = await waitUntil(timeout: 3) { self.context.launcher.resultTitles.first == "Quit sleep" } != nil
        // "kill" became the chip: the field holds only the name.
        let chip = context.launcher.isKilling && context.launcher.query == "sleep"
        if let directory = context.snapshotDirectory, let png = context.launcher.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("launcher-kill.png"))
        }
        var sleepQuit = (asked: false, closed: false, said: "")
        if listedSleep { sleepQuit = await quitTopRow() }
        let sleepStopped = await waitUntil(timeout: 3) { !sleeper.isRunning } != nil

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "kill \(port)" { await pressKey(character) }
        let listedPort = await waitUntil(timeout: 3) { self.context.launcher.resultTitles.first == "Quit nc" } != nil
        if listedPort { _ = await quitTopRow() }
        let portStopped = await waitUntil(timeout: 3) { !listener.isRunning } != nil

        // ⌫ on the empty field leaves Kill mode.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "kill " { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { self.context.launcher.isKilling }
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        let left = await waitUntil(timeout: 1) { !self.context.launcher.isKilling } != nil
        await closeLauncher()

        // A row of one process: the footer says Quit ↩ and ⌘K; ⇥ shows its
        // actions (never Ask on what is typed); esc closes them, esc again
        // goes back to the launcher as typed before the chip (“kill”), esc
        // again closes it. Nothing is quit.
        let launcher = context.launcher
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "kill \(otherPort)" { await pressKey(character) }
        let listedOther = await waitUntil(timeout: 3) { launcher.resultTitles.first == "Quit nc" } != nil
        let footer = launcher.shownFooter
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let tabActions = await waitUntil(timeout: 1) { launcher.isShowingActions && launcher.shownActions.first?.title == "Quit" } != nil
        let noAsk = launcher.isVisible && !popover.isVisible
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let listClosed = await waitUntil(timeout: 1) { !launcher.isShowingActions && launcher.isKilling } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let backToRoot = await waitUntil(timeout: 1) { launcher.isVisible && launcher.mode == nil && launcher.query == "kill" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let escClosed = await waitUntil(timeout: 1) { !launcher.isVisible } != nil
        await closeLauncher()
        let otherKept = other.isRunning
        let keys = listedOther && footer == ["Quit ↩", "Actions ⌘K"] && tabActions && noAsk && listClosed && backToRoot && escClosed && otherKept
        record(name, listedSleep && chip && !sleepQuit.asked && sleepQuit.closed && sleepStopped && sleepQuit.said.isEmpty && listedPort && portStopped && left && keys,
               "sleep listed: \(listedSleep), chip: \(chip), launcher closed: \(sleepQuit.closed), asked: \(sleepQuit.asked) (never), stopped: \(sleepStopped), then said “\(sleepQuit.said)” (nothing expected); port \(port) listed: \(listedPort), stopped: \(portStopped); ⌫ left the mode: \(left); "
                   + "port \(otherPort) listed: \(listedOther), footer \(footer), ⇥ its actions: \(tabActions), no Ask: \(noAsk), esc closed them: \(listClosed), esc back to “kill”: \(backToRoot) (“\(launcher.query)”), esc closed: \(escClosed), still running: \(otherKept)", nil)
    }

    // MARK: - Clipboard history

    /// On a scratch store and a private pasteboard (never the user's): a
    /// copy is kept and found without accents, copying it again moves it up
    /// instead of adding it, secrets and excluded apps are skipped, rich
    /// text pastes back with its formats (or plain), OCR finds the words of
    /// an image, old copies are pruned and deleting removes the image file.
    private func clipboardKeepsAndFinds() async {
        let name = "Clipboard history: keeps, finds without accents and in images (OCR), moves repeats up, skips secrets, pastes formats back, prunes"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-clipboard-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        guard let store = try? ClipboardStore(folder: folder) else {
            record(name, false, "could not open a scratch store", nil)
            return
        }
        let pasteboard = NSPasteboard(name: NSPasteboard.Name("skilli-selftest-\(UUID().uuidString)"))
        defer { pasteboard.releaseGlobally() }
        let history = ClipboardHistory(preferences: context.preferences, store: store, pasteboard: pasteboard)
        func copy(_ text: String, rtf: Bool = false, extraType: String? = nil) -> ClipboardStore.Item? {
            pasteboard.clearContents()
            let item = NSPasteboardItem()
            item.setString(text, forType: .string)
            if rtf, let data = NSAttributedString(string: text, attributes: [.font: NSFont.boldSystemFont(ofSize: 14)])
                .rtf(from: NSRange(location: 0, length: (text as NSString).length), documentAttributes: [:]) {
                item.setData(data, forType: .rtf)
            }
            if let extraType { item.setData(Data(), forType: NSPasteboard.PasteboardType(extraType)) }
            pasteboard.writeObjects([item])
            return history.capture()
        }

        let meeting = copy("Réunion budget jeudi", rtf: true)
        let found = store.search("reunion bud").first?.id == meeting?.id && meeting != nil
        _ = copy("Autre chose")
        _ = copy("Réunion budget jeudi", rtf: true)
        let movedUp = store.count == 2 && store.search("").first?.text == "Réunion budget jeudi" && store.search("").first?.copies == 2
        let secret = copy("hunter2", extraType: "org.nspasteboard.ConcealedType") == nil
        let excluded = ClipboardHistory.read(pasteboard, app: "com.1password.1password", appName: "1Password",
                                             excluded: Set(ClipboardPolicy.defaultExcludedApps)) == nil

        var richBack = false
        var plainBack = false
        if let meeting {
            history.write(meeting, plain: false)
            richBack = pasteboard.data(forType: .rtf) != nil && pasteboard.string(forType: .string) == meeting.text
            history.write(meeting, plain: true)
            plainBack = pasteboard.data(forType: .rtf) == nil && pasteboard.string(forType: .string) == meeting.text
        }

        // An image with words, read by Vision.
        let picture = NSImage(size: NSSize(width: 900, height: 220), flipped: false) { rect in
            NSColor.white.setFill()
            rect.fill()
            ("Facture 2026 Skilli" as NSString).draw(at: NSPoint(x: 40, y: 70), withAttributes: [
                .font: NSFont.systemFont(ofSize: 72, weight: .semibold),
                .foregroundColor: NSColor.black
            ])
            return true
        }
        var ocrFound = false
        var ocrMs: Double?
        var imageFileGone = false
        if let tiff = picture.tiffRepresentation, let png = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]) {
            pasteboard.clearContents()
            pasteboard.setData(png, forType: .png)
            if let image = history.capture(), image.kind == .image, let url = store.imageURL(image) {
                let start = ContinuousClock.now
                if let text = await ClipboardHistory.recognizeText(in: url) {
                    ocrMs = (ContinuousClock.now - start).milliseconds
                    try? store.setOCR(text, for: image.id)
                }
                ocrFound = store.search("facture 2026").first?.id == image.id
                try? store.delete(image.id)
                imageFileGone = !FileManager.default.fileExists(atPath: url.path)
            }
        }

        let old = try? store.add(.init(kind: .text, text: "Très vieux", hash: "selftest-old"), at: .now.addingTimeInterval(-40 * 86_400))
        let pruned = old != nil && (try? store.prune(before: ClipboardRetention.month.cutoff()!))?.count == 1 && store.search("vieux").isEmpty

        record(name, found && movedUp && secret && excluded && richBack && plainBack && ocrFound && imageFileGone && pruned,
               "found “reunion bud”: \(found); copied again moved up (2 rows, copied twice): \(movedUp); secret skipped: \(secret); 1Password skipped: \(excluded); rich text back: \(richBack), plain: \(plainBack); OCR found “facture 2026”: \(ocrFound) in \(ocrMs.map { String(format: "%.0f ms", $0) } ?? "—"); image file deleted: \(imageFileGone); 40-day-old copy pruned by “1 month”: \(pruned)",
               ocrMs)
    }

    /// A history from the first version (no copies column) opens, gains it,
    /// and counts from there.
    private func clipboardStoreMigrates() async {
        let name = "Clipboard history: a first-version file opens and counts copies from there"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-clipboard-old-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        try? FileManager.default.createDirectory(at: folder.appendingPathComponent("images"), withIntermediateDirectories: true)
        let sql = """
            CREATE TABLE items (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, text TEXT NOT NULL DEFAULT '', ocr TEXT, image TEXT,
                size TEXT, formats BLOB, app TEXT, app_name TEXT, hash TEXT NOT NULL UNIQUE, copied REAL NOT NULL);
            INSERT INTO items (kind, text, hash, copied) VALUES ('text', 'ancienne copie', 'old-hash', 1760000000);
            """
        await Self.run("/usr/bin/sqlite3", [folder.appendingPathComponent("history.sqlite").path, sql])
        guard let store = try? ClipboardStore(folder: folder) else {
            record(name, false, "the old file did not open", nil)
            return
        }
        let before = store.search("").first?.copies
        _ = try? store.add(.init(kind: .text, text: "ancienne copie", hash: "old-hash"))
        let after = store.search("").first?.copies
        // The old rows were never indexed by FTS: they still show in the list.
        record(name, before == 1 && after == 2, "copies before: \(before.map(String.init) ?? "nil"), after copying again: \(after.map(String.init) ?? "nil")", nil)
    }

    /// Copies a person would look for, among 25 others, found from how they
    /// would ask: decided only, on a scratch store, nothing pasted.
    private func clipboardFindsByMeaning() async {
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-clipboard-meaning-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        guard let store = try? ClipboardStore(folder: folder) else { return }
        let history = ClipboardHistory(preferences: context.preferences, store: store,
                                       pasteboard: NSPasteboard(name: NSPasteboard.Name("skilli-selftest-\(UUID().uuidString)")))
        let now = Date.now
        func ago(_ hours: Double) -> Date { now.addingTimeInterval(-hours * 3_600) }
        func add(_ kind: ClipboardStore.Item.Kind, _ text: String, _ app: String, _ hours: Double, ocr: String? = nil) -> Int64? {
            let item = try? store.add(.init(kind: kind, text: text, app: nil, appName: app, hash: "selftest-\(UUID().uuidString)"), at: ago(hours)).item
            if let item, let ocr { try? store.setOCR(ocr, for: item.id) }
            return item?.id
        }
        let filler: [(String, String)] = [
            ("OK pour moi, on fait comme ça", "Slack"), ("merci beaucoup !", "Messages"), ("https://github.com/nomdelasociete/skilli/pull/30", "Safari"),
            ("npm install --save-dev typescript", "Terminal"), ("06 12 34 56 78", "Contacts"), ("Réunion produit jeudi 10h salle Bleue", "Calendar"),
            ("let total = items.reduce(0, +)", "Xcode"), ("jean@example.com", "Mail"), ("Lorem ipsum dolor sit amet", "Pages"),
            ("FR76 3000 6000 0112 3456 7890 189", "Notes"), ("git rebase -i HEAD~3", "Terminal"), ("La réunion est décalée à 15h", "Slack"),
            ("Bon anniversaire Léa !", "Messages"), ("SELECT * FROM users WHERE id = 42;", "TablePlus"), ("https://www.figma.com/file/abc123", "Figma"),
            ("Paris, 11 octobre 2026", "Pages"), ("200 g de farine, 3 œufs, 50 cl de lait", "Notes"), ("tracking: 1Z999AA10123456784", "Mail"),
            ("Ne pas oublier les clés du local", "Reminders"), ("brew upgrade --cask", "Terminal"), ("Merci pour ton retour rapide", "Mail"),
            ("#3E8E7E", "Figma"), ("v2.4.1 release notes", "Safari"), ("ssh n1", "Terminal"), ("À demain !", "Messages")
        ]
        for (index, (text, app)) in filler.enumerated() { _ = add(.text, text, app, Double(index) * 5 + 1) }
        let bill = add(.text, "EDF — Facture d'octobre 2026 : 82,40 € à régler avant le 25/10. Référence client 4002 118 230", "Mail", 46)
        let ticket = add(.image, "", "CleanShot X", 20, ocr: "SNCF e-billet\nParis Gare de Lyon → Lyon Part-Dieu\nDépart 14:05 · Voiture 12 · Place 47")
        let address = add(.text, "c'est au 12 rue des Lilas, 75011 Paris, digicode 4B21, 3e étage gauche", "Messages", 70)
        let code = add(.text, "DispatchQueue.main.asyncAfter(deadline: .now() + 0.05) {\n    self.selection.press(\"v\", flags: .maskCommand)\n}", "Xcode", 3)
        // A screenshot from the watched folder: no app, its words read here.
        let screenshot = add(.image, "", "Screenshots", 30, ocr: "Stripe Dashboard\nPayout failed\nYour bank declined the transfer of 1 240,00 € on Oct 14")
        let cases: [(String, Int64?)] = [
            ("la facture d'électricité", bill),
            ("le billet de train que j'ai copié hier", ticket),
            ("l'adresse de l'appart avec le digicode", address),
            ("le bout de code swift avec le délai", code),
            ("the screenshot where the payout failed", screenshot)
        ]
        for provider in DecisionProvider.allCases {
            let name = "Clipboard by meaning with \(provider.title): bill, train ticket screenshot, address, code, a screenshot from the folder, among 30 copies"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var passed = true
            var details: [String] = []
            var slowest: Duration = .zero
            for (request, expected) in cases {
                let start = ContinuousClock.now
                let found = await history.searchByMeaning(request, keys: [provider: key])
                slowest = max(slowest, .now - start)
                let first = found?.items.first
                passed = passed && expected != nil && first?.id == expected
                details.append("“\(request)” → \(first.map { "\($0.kind.rawValue) from \($0.appName ?? "?")" } ?? "nothing")\(first?.id == expected ? "" : " (wrong)")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// Keep screenshots too: a new image in the watched folder joins the
    /// history and its words are found, read on this Mac; with Jev's
    /// folder switch off, nothing asks for the key (nothing sent).
    private func screenshotsJoinTheHistory() async {
        let name = "Screenshots: a new image in the watched folder joins the history, found by its words (read on this Mac); Jev not asked with its switch off"
        let files = FileManager.default
        let root = files.temporaryDirectory.appendingPathComponent("skilli-screenshots-\(UUID().uuidString)", isDirectory: true)
        let folder = root.appendingPathComponent("Screenshots", isDirectory: true)
        try? files.createDirectory(at: folder, withIntermediateDirectories: true)
        defer { try? files.removeItem(at: root) }
        guard let store = try? ClipboardStore(folder: root.appendingPathComponent("store", isDirectory: true)) else {
            record(name, false, "no scratch store", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.clipboardHistory, preferences.clipboardScreenshots, preferences.clipboardOCR, preferences.imageTagsFolder)
        defer {
            (preferences.clipboardHistory, preferences.clipboardScreenshots, preferences.clipboardOCR, preferences.imageTagsFolder) = saved
        }
        preferences.clipboardHistory = true
        preferences.clipboardScreenshots = true
        preferences.clipboardOCR = true
        preferences.imageTagsFolder = false
        let history = ClipboardHistory(preferences: preferences, store: store,
                                       pasteboard: NSPasteboard(name: NSPasteboard.Name("skilli-selftest-\(UUID().uuidString)")))
        var asked = 0
        history.imageKey = {
            asked += 1
            return nil
        }
        let watcher = ImageFolderWatcher()
        watcher.onImage = { url, date in history.keepImage(at: url, made: date, from: "Screenshots") }
        defer { watcher.stop() }
        guard watcher.watch(folder) else {
            record(name, false, "cannot watch the scratch folder", nil)
            return
        }
        let word = "Payout\(Int.random(in: 1000...9999))"
        let picture = NSImage(size: NSSize(width: 900, height: 260), flipped: false) { rect in
            NSColor.white.setFill()
            rect.fill()
            ("Stripe \(word) failed" as NSString).draw(at: NSPoint(x: 40, y: 100), withAttributes: [
                .font: NSFont.systemFont(ofSize: 64, weight: .semibold), .foregroundColor: NSColor.black
            ])
            return true
        }
        guard let tiff = picture.tiffRepresentation, let png = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]) else {
            record(name, false, "could not draw the screenshot", nil)
            return
        }
        try? png.write(to: folder.appendingPathComponent("Screenshot \(word).png"))
        let start = ContinuousClock.now
        // Vision's first reading loads its models: up to ~30 s once.
        let found = await waitUntil(timeout: 40) { store.search(word).first != nil }
        let row = store.search(word).first
        record(name, found != nil && row?.kind == .image && asked == 0,
               "kept and found by “\(word)”: \(found != nil) in \(Int((ContinuousClock.now - start).milliseconds)) ms (\(row?.kind.rawValue ?? "nothing") from \(row?.appName ?? "?")), Jev asked: \(asked)",
               found?.milliseconds)
    }

    /// Paste in Sequence on a scratch history and clipboard: the newest,
    /// then each older one; past the oldest it says so; a copy of the
    /// user's own starts again from it.
    private func pasteSequenceGoesOlder() {
        let name = "Paste in Sequence (no keys): the newest copy, then each older one, then “the oldest”; a new copy starts again"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-sequence-\(UUID().uuidString)", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        guard let store = try? ClipboardStore(folder: folder) else {
            record(name, false, "no scratch store", nil)
            return
        }
        let pasteboard = NSPasteboard(name: NSPasteboard.Name("skilli-selftest-\(UUID().uuidString)"))
        let preferences = context.preferences
        let wasOn = preferences.clipboardHistory
        preferences.clipboardHistory = true
        defer { preferences.clipboardHistory = wasOn }
        let history = ClipboardHistory(preferences: preferences, store: store, pasteboard: pasteboard)
        for (index, word) in ["un", "deux", "trois"].enumerated() {
            _ = try? store.add(.init(kind: .text, text: word, app: nil, appName: "Notes", hash: "sequence-\(word)"), at: .now.addingTimeInterval(Double(index - 10)))
        }
        var got: [String] = []
        for _ in 0..<3 where history.putNextInSequence() == nil {
            got.append(pasteboard.string(forType: .string) ?? "")
        }
        let end = history.putNextInSequence() ?? ""
        pasteboard.clearContents()
        pasteboard.setString("quatre", forType: .string)
        _ = try? store.add(.init(kind: .text, text: "quatre", app: nil, appName: "Notes", hash: "sequence-quatre"))
        let again = history.putNextInSequence() == nil ? pasteboard.string(forType: .string) ?? "" : ""
        record(name, got == ["trois", "deux", "un"] && end.hasPrefix("That was the oldest") && again == "quatre",
               "pasted \(got), then “\(end)”, after a new copy “\(again)”", nil)
    }

    /// ✦C, "facture": the image row shows its picture and what is known
    /// about it; then what a person remembers, ⇥, and Return pastes it.
    private func clipboardPreviewAndMeaning() async {
        let name = "Clipboard preview and ⇥: an image row shows the picture and its information; “mon billet de train” ⇥ finds the copy, Return pastes it"
        guard let store = context.clipboard.store else {
            record(name, false, "no clipboard store", nil)
            return
        }
        // A picture with words, and the train ticket as text.
        let picture = NSImage(size: NSSize(width: 900, height: 300), flipped: false) { rect in
            NSColor.white.setFill()
            rect.fill()
            ("Facture 2026 Skilli" as NSString).draw(at: NSPoint(x: 60, y: 110), withAttributes: [
                .font: NSFont.systemFont(ofSize: 72, weight: .semibold), .foregroundColor: NSColor.black
            ])
            return true
        }
        guard let tiff = picture.tiffRepresentation, let png = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]),
              let image = try? store.add(.init(kind: .image, text: "", imageData: png, size: "1800×600", app: "com.apple.Preview",
                                               appName: "Preview", hash: ClipboardHistory.hash("image", png))).item
        else {
            record(name, false, "could not add the picture", nil)
            return
        }
        try? store.setOCR("Facture 2026 Skilli", for: image.id)
        let ticketText = "Billet SNCF Paris Gare de Lyon → Lyon Part-Dieu, départ 14:05, voiture 12 place 47 \(Int.random(in: 100...999))"
        _ = try? store.add(.init(kind: .text, text: ticketText, app: "com.apple.mail", appName: "Mail",
                                 hash: ClipboardHistory.hash("text", Data(ticketText.utf8))), at: .now.addingTimeInterval(-26 * 3_600))

        // The self-test's own Keychain items hold no decision key: ⇥ uses
        // the user's here, as the other live checks do.
        let launcher = context.launcher
        let keys = userDecisionKeys
        let saved = (launcher.clipboardMeaningAvailable, launcher.clipboardMeaning)
        launcher.clipboardMeaningAvailable = { !keys.isEmpty }
        launcher.clipboardMeaning = { [history = context.clipboard] request in await history.searchByMeaning(request, keys: keys) }
        defer { (launcher.clipboardMeaningAvailable, launcher.clipboardMeaning) = saved }

        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord(["c"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { self.context.launcher.isInClipboard }
        for character in "facture skilli" { await pressKey(character) }
        let preview = context.launcher.clipboardPreview
        let pictureShown = await waitUntil(timeout: 2) { preview.shownKind == .image } != nil
        let info = preview.shownInfo.map { "\($0.0): \($0.1)" }.joined(separator: ", ")
        let informed = preview.shownInfo.contains { $0.0 == "From" && $0.1 == "Preview" }
            && preview.shownTextInImage == "Facture 2026 Skilli"
        await captureLauncher(as: "launcher-clipboard-preview.png")
        for _ in 0..<"facture skilli".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }

        var meaningDetail = "no decision key: skipped"
        var meaningPassed = true
        if !userDecisionKeys.isEmpty {
            for character in "mon billet de train d'hier" { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Tab))
            let start = ContinuousClock.now
            let found = await waitUntil(timeout: 6) {
                self.context.launcher.isShowingMeaning && self.context.launcher.resultTitles.first?.hasPrefix("Billet SNCF") == true
            } != nil
            let seconds = (ContinuousClock.now - start).milliseconds / 1_000
            await captureLauncher(as: "launcher-clipboard-meaning.png")
            if found { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
            let pasted = await waitUntil(timeout: 2) { self.textView.string == ticketText } != nil
            meaningPassed = found && pasted
            meaningDetail = "⇥ found the ticket: \(found) in \(String(format: "%.2f", seconds)) s (\(context.launcher.resultTitles.first ?? "nothing")), pasted: \(pasted)"
        }
        await closeLauncher()
        record(name, pictureShown && informed && meaningPassed,
               "picture shown: \(pictureShown), information: \(info); \(meaningDetail)", nil)
    }

    /// ✦C, then each kind of copy in the preview, newest first with ↓,
    /// each captured light and dark: a color, an image with what SI saw
    /// and its words, a file's Quick Look picture, an email address, a
    /// phone number, an address, code, then two links read from pages this
    /// test serves on 127.0.0.1 (no real website): nothing read before a
    /// link is shown nor while Show link previews is off; on, the card with
    /// the page's picture, icon and title, no cookie sent back; the
    /// preview's files go with the copy.
    private func clipboardPreviewsShowEachKind() async {
        let name = "Clipboard previews: color, image with SI's reading and its words, file, email, phone, address, code, links from a "
            + "local page (read only when shown, never while off, no cookies, removed with the copy); each shown at once"
        guard let store = context.clipboard.store else {
            record(name, false, "no clipboard store", nil)
            return
        }
        let preferences = context.preferences
        let wasOn = (preferences.clipboardHistory, preferences.clipboardLinkPreviews)
        preferences.clipboardHistory = true
        defer { (preferences.clipboardHistory, preferences.clipboardLinkPreviews) = wasOn }

        // The pages: one with a picture, one with words only.
        let card = Self.drawnPNG(width: 1200, height: 630) { rect in
            NSGradient(colors: [NSColor(srgbRed: 0.24, green: 0.56, blue: 0.49, alpha: 1),
                                NSColor(srgbRed: 0.07, green: 0.23, blue: 0.27, alpha: 1)])?.draw(in: rect, angle: -35)
            ("skil.li" as NSString).draw(at: NSPoint(x: 90, y: 300), withAttributes: [
                .font: NSFont.systemFont(ofSize: 150, weight: .bold), .foregroundColor: NSColor.white
            ])
            ("Link previews, read on your Mac" as NSString).draw(at: NSPoint(x: 96, y: 210), withAttributes: [
                .font: NSFont.systemFont(ofSize: 48, weight: .medium), .foregroundColor: NSColor.white.withAlphaComponent(0.8)
            ])
        }
        let icon = Self.drawnPNG(width: 128, height: 128) { rect in
            NSColor(srgbRed: 0.24, green: 0.56, blue: 0.49, alpha: 1).setFill()
            NSBezierPath(roundedRect: rect, xRadius: 28, yRadius: 28).fill()
            ("S" as NSString).draw(at: NSPoint(x: 34, y: 14), withAttributes: [
                .font: NSFont.systemFont(ofSize: 92, weight: .heavy), .foregroundColor: NSColor.white
            ])
        }
        let page = Self.fixturePage(title: "Link previews, read on your Mac", site: "skil.li",
                                    summary: "The page's own picture, title and description, read when you look at a copied link. "
                                        + "Nothing else leaves your Mac.", picture: true)
        let wordsPage = Self.fixturePage(title: "Release notes: the clipboard shows what you copied", site: "skil.li Journal",
                                         summary: "Links with their page's card, colors as swatches with their values, screenshots "
                                             + "with what SI saw in them and the words they hold, files with Quick Look, addresses "
                                             + "and numbers on a card, and code in its language.", picture: false)
        let served = ServedRequests()
        guard let server = LoopbackServer(handler: { request in
            served.add(request)
            switch request.target.split(separator: "?").first.map(String.init) ?? "" {
            case "/preview-page":
                var response = LoopbackServer.Response.html(page)
                response.headers["Set-Cookie"] = "skilli-selftest=1; Path=/"
                return response
            case "/words-page": return .html(wordsPage)
            case "/card.png": return .init(headers: ["Content-Type": "image/png"], body: card)
            case "/icon.png": return .init(headers: ["Content-Type": "image/png"], body: icon)
            default: return .init(status: 404)
            }
        }), let port = await server.port() else {
            record(name, false, "the local pages could not be served", nil)
            return
        }
        defer { server.stop() }

        // A picture of an invoice, and a chart saved as a file.
        let invoice = Self.drawnPNG(width: 1400, height: 900) { rect in
            NSColor.white.setFill()
            rect.fill()
            let ink: [NSAttributedString.Key: Any] = [.font: NSFont.systemFont(ofSize: 34), .foregroundColor: NSColor.darkGray]
            ("Facture" as NSString).draw(at: NSPoint(x: 100, y: 720), withAttributes: [
                .font: NSFont.systemFont(ofSize: 84, weight: .bold), .foregroundColor: NSColor.black
            ])
            ("N° 2026-118 · skil.li SAS · 16 octobre 2026" as NSString).draw(at: NSPoint(x: 104, y: 650), withAttributes: ink)
            for (index, line) in ["Abonnement annuel", "Assistance prioritaire", "Total"].enumerated() {
                let y = CGFloat(500 - index * 90)
                (line as NSString).draw(at: NSPoint(x: 104, y: y), withAttributes: ink)
                (["980,00 €", "260,00 €", "1 240,00 €"][index] as NSString).draw(at: NSPoint(x: 1050, y: y), withAttributes: ink)
                NSColor(white: 0.85, alpha: 1).setFill()
                NSRect(x: 100, y: y - 24, width: 1200, height: 2).fill()
            }
        }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/previews", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let chartFile = folder.appendingPathComponent("Quarterly Chart.png")
        let chart = Self.drawnPNG(width: 1200, height: 800) { rect in
            NSColor(white: 0.97, alpha: 1).setFill()
            rect.fill()
            for (index, value) in [0.35, 0.55, 0.48, 0.8].enumerated() {
                NSColor(srgbRed: 0.24, green: 0.56, blue: 0.49, alpha: 0.6 + 0.1 * Double(index)).setFill()
                NSBezierPath(roundedRect: NSRect(x: 160 + index * 240, y: 100, width: 160, height: Int(600 * value)), xRadius: 12, yRadius: 12).fill()
            }
        }
        try? chart.write(to: chartFile)
        let notesFile = folder.appendingPathComponent("Meeting Notes.txt")
        try? Data("Ship the clipboard previews.".utf8).write(to: notesFile)
        let paths = [chartFile.path, notesFile.path].joined(separator: "\n")
        let essay = String(repeating: "skil.li keeps what you copy on your Mac and shows each copy the way it reads best: a link with the "
            + "picture and title of its page, a color as a swatch with its values, a screenshot with what it shows and the words in it, "
            + "a file with its own picture. Nothing waits on the network while you type or move through the list; what a page says "
            + "arrives when it arrives. ", count: 7)
        let code = """
        import SwiftUI

        struct PreviewFixtureView: View {
            let name = "skil.li"
            var body: some View {
                Text("Hello, \\(name)")
                    .font(.title)
            }
        }
        """
        // Newest first, as the history lists them: ↓ walks them in order.
        let link = "http://127.0.0.1:\(port)/preview-page?skilli=preview"
        let words = "http://127.0.0.1:\(port)/words-page?skilli=preview"
        let seeds: [(ClipboardStore.NewItem, ClipboardPreviewView.Shown)] = [
            (.init(kind: .text, text: "#3E8E7E", app: "com.apple.Safari", appName: "Safari", hash: ClipboardHistory.hash("text", Data("#3E8E7E".utf8))), .color),
            (.init(kind: .image, text: "", imageData: invoice, size: "1400×900", app: "com.apple.Preview", appName: "Preview",
                   hash: ClipboardHistory.hash("image", invoice)), .image),
            (.init(kind: .files, text: chartFile.path, app: "com.apple.finder", appName: "Finder",
                   hash: ClipboardHistory.hash("files", Data(chartFile.path.utf8))), .file),
            (.init(kind: .files, text: paths, app: "com.apple.finder", appName: "Finder", hash: ClipboardHistory.hash("files", Data(paths.utf8))), .files),
            (.init(kind: .text, text: "zoe.martin@example.com", app: "com.apple.mail", appName: "Mail",
                   hash: ClipboardHistory.hash("text", Data("zoe.martin@example.com".utf8))), .email),
            (.init(kind: .text, text: "+33 6 12 34 56 78", app: "com.apple.MobileSMS", appName: "Messages",
                   hash: ClipboardHistory.hash("text", Data("+33 6 12 34 56 78".utf8))), .phone),
            (.init(kind: .text, text: "1 Infinite Loop, Cupertino, CA 95014", app: "com.apple.Maps", appName: "Maps",
                   hash: ClipboardHistory.hash("text", Data("1 Infinite Loop, Cupertino, CA 95014".utf8))), .address),
            (.init(kind: .text, text: code, app: "com.apple.dt.Xcode", appName: "Xcode", hash: ClipboardHistory.hash("text", Data(code.utf8))), .code),
            (.init(kind: .text, text: essay, app: "com.apple.Notes", appName: "Notes", hash: ClipboardHistory.hash("text", Data(essay.utf8))), .text),
            (.init(kind: .text, text: words, app: "com.apple.Safari", appName: "Safari", hash: ClipboardHistory.hash("text", Data(words.utf8))), .link),
            (.init(kind: .text, text: link, app: "com.apple.Safari", appName: "Safari", hash: ClipboardHistory.hash("text", Data(link.utf8))), .link)
        ]
        let top = Date.now.addingTimeInterval(600)
        var items: [ClipboardStore.Item] = []
        for (index, seed) in seeds.enumerated() {
            guard let item = try? store.add(seed.0, at: top.addingTimeInterval(-Double(index))).item else {
                record(name, false, "could not add the copies", nil)
                return
            }
            items.append(item)
        }
        try? store.setOCR("Facture\nN° 2026-118 · skil.li SAS · 16 octobre 2026\nAbonnement annuel 980,00 €\nTotal 1 240,00 €", for: items[1].id)
        let linkItem = items[items.count - 1]
        try? store.setTags(ImageTags(kind: .invoice, person: false).words, for: items[1].id)

        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        _ = await hyperChord(["c"], trigger: Self.ownTriggerKeyCode)
        guard await waitUntil(timeout: 1, { self.context.launcher.isInClipboard }) != nil else {
            record(name, false, "✦C did not open the history", nil)
            return
        }
        let preview = context.launcher.clipboardPreview
        var problems: [String] = []
        var slowest = Duration.zero
        var covering: Set<String> = []
        var times: [String] = []
        /// Waits for the row's view, then captures it both ways.
        func check(_ kind: ClipboardPreviewView.Shown, _ capture: String, timeout: Double = 2,
                   _ ready: @escaping @MainActor () -> Bool = { true }) async -> Bool {
            let shown = await waitUntil(timeout: timeout) { preview.shown == kind && ready() } != nil
            slowest = max(slowest, preview.lastShowTime)
            times.append("\(capture) \(preview.lastShowTime.compact) (\(preview.lastShowSteps))")
            if !shown { problems.append("\(kind.rawValue): showed \(preview.shown.rawValue) \(preview.shownTitle)") }
            covering.formUnion(Self.othersOver(context.launcher.window))
            await captureLauncherBothWays(as: "launcher-clipboard-preview-\(capture)")
            return shown
        }
        func down() async {
            await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        }
        func info(_ label: String) -> String {
            preview.shownInfo.first { $0.0 == label }?.1 ?? ""
        }

        _ = await check(.color, "color") { info("Hex") == "#3E8E7E" && info("RGB") == "rgb(62, 142, 126)" && info("HSL") == "hsl(168, 39%, 40%)" }
        await down()
        _ = await check(.image, "image") {
            preview.hasPicture && preview.shownReading == "SI sees an invoice, a receipt or a bill." && preview.shownTextInImage.hasPrefix("Facture")
                && info("File size") != "…"
        }
        await down()
        _ = await check(.file, "file", timeout: 6) { preview.hasPicture && info("Kind") != "…" && preview.shownTitle == "Quarterly Chart.png" }
        await down()
        _ = await check(.files, "files") { info("Content") == "2 Files" }
        await down()
        _ = await check(.email, "email") { preview.shownTitle == "zoe.martin@example.com" }
        await down()
        _ = await check(.phone, "phone") { preview.shownTitle == "+33 6 12 34 56 78" }
        await down()
        _ = await check(.address, "address") { preview.shownTitle.hasPrefix("1 Infinite Loop") }
        await down()
        _ = await check(.code, "code") { info("Content") == "Code · Swift" }
        await down()
        _ = await check(.text, "text") { info("Reading time") == "About 2 min" }
        let readBefore = served.paths

        // Show link previews off: the link as it is, nothing read.
        preferences.clipboardLinkPreviews = false
        await down()
        _ = await check(.link, "link-plain") { preview.shownTitle == "127.0.0.1" }
        await pause(600)
        let readWhileOff = served.paths
        // On: shown again, the page is read.
        preferences.clipboardLinkPreviews = true
        await pressKey(nil, code: CGKeyCode(kVK_UpArrow))
        await down()
        _ = await check(.link, "link-words", timeout: 4) { preview.shownTitle == "Release notes: the clipboard shows what you copied" }
        await down()
        let linkShown = await check(.link, "link", timeout: 4) {
            preview.shownTitle == "Link previews, read on your Mac" && preview.shownLinkHasPicture && preview.shownLinkHasIcon
        }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        let read = served.requests
        let cookies = read.filter { $0.headers["cookie"] != nil }.map(\.target)
        let agents = Set(read.compactMap { $0.headers["user-agent"] })
        let kept = FileManager.default.fileExists(atPath: store.previewsFolder.appendingPathComponent(LinkPreviewCache.imageName(linkItem.id)).path)
        context.clipboard.delete(linkItem)
        let removed = LinkPreviewCache.files(of: linkItem.id).allSatisfy {
            !FileManager.default.fileExists(atPath: store.previewsFolder.appendingPathComponent($0).path)
        }
        if !readBefore.isEmpty { problems.append("read before a link was shown: \(readBefore)") }
        if !readWhileOff.isEmpty { problems.append("read while previews were off: \(readWhileOff)") }
        if !cookies.isEmpty { problems.append("cookies sent to \(cookies)") }
        if read.contains(where: { $0.method != "GET" }) { problems.append("not only GETs") }
        if !agents.allSatisfy({ $0.contains("skil.li/") }) { problems.append("user agents \(agents)") }
        if linkShown, !kept { problems.append("the picture was not kept with the copy") }
        if !removed { problems.append("the preview's files stayed after the copy was forgotten") }
        // Measured on the mini: 0.3–1.3 ms a kind; half a frame is a regression.
        if slowest > .milliseconds(8) { problems.append("a preview took \(slowest.compact) to show") }
        for item in items.dropLast() { context.clipboard.delete(item) }
        try? FileManager.default.removeItem(at: folder)
        record(name, problems.isEmpty,
               (problems.isEmpty ? "every kind shown" : problems.joined(separator: "; "))
                   + (covering.isEmpty ? "" : "; other apps' windows over the launcher: \(covering.sorted())")
                   + "; requests: \(read.map(\.target).map { $0.split(separator: "?").first.map(String.init) ?? $0 }); shown in \(times.joined(separator: ", "))",
               slowest.milliseconds)
    }

    /// Other apps' windows over `window` on screen ("Owner 340×280"):
    /// what would show in its captures.
    private static func othersOver(_ window: NSWindow) -> [String] {
        guard window.windowNumber > 0,
              let list = CGWindowListCopyWindowInfo([.optionOnScreenAboveWindow], CGWindowID(window.windowNumber)) as? [[String: Any]],
              let screen = NSScreen.screens.first else { return [] }
        // Window server bounds are from the top left of the main screen.
        let frame = window.frame
        let mine = CGRect(x: frame.minX, y: screen.frame.maxY - frame.maxY, width: frame.width, height: frame.height)
        return list.compactMap { info in
            // The Dock keeps a clear window over the whole screen.
            guard (info[kCGWindowOwnerPID as String] as? Int32) != getpid(), info[kCGWindowOwnerName as String] as? String != "Dock",
                  let bounds = info[kCGWindowBounds as String] as? NSDictionary,
                  let rect = CGRect(dictionaryRepresentation: bounds), rect.intersects(mine), rect.width > 1, rect.height > 1 else { return nil }
            let owner = info[kCGWindowOwnerName as String] as? String ?? "?"
            return "\(owner) \(Int(rect.width))×\(Int(rect.height)) layer \(info[kCGWindowLayer as String] as? Int ?? 0)"
        }
    }

    /// A page with Open Graph tags, as a site would serve it.
    private static func fixturePage(title: String, site: String, summary: String, picture: Bool) -> String {
        """
        <!doctype html>
        <html lang="en"><head>
        <meta charset="utf-8">
        <title>\(title) | \(site)</title>
        <meta property="og:site_name" content="\(site)">
        <meta property="og:title" content="\(title)">
        <meta property="og:description" content="\(summary)">
        \(picture ? "<meta property=\"og:image\" content=\"/card.png\">" : "")
        <link rel="icon" href="/icon.png" sizes="128x128">
        <script>document.cookie = "seen=1";</script>
        </head><body><h1>\(title)</h1></body></html>
        """
    }

    /// A PNG of `width` × `height` pixels, drawn by `draw`.
    private static func drawnPNG(width: Int, height: Int, _ draw: (NSRect) -> Void) -> Data {
        guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: width, pixelsHigh: height, bitsPerSample: 8, samplesPerPixel: 4,
                                         hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)
        else { return Data() }
        // Points first: a context made before draws at the wrong scale.
        rep.size = NSSize(width: width, height: height)
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
        draw(NSRect(x: 0, y: 0, width: width, height: height))
        NSGraphicsContext.restoreGraphicsState()
        return rep.representation(using: .png, properties: [:]) ?? Data()
    }

    /// The launcher as the window server shows it, glass included: the test
    /// window grows behind it first, so nothing of the user's shows through.
    private func captureLauncher(as name: String) async {
        let original = window.frame
        window.setFrame(original.union(context.launcher.window.frame.insetBy(dx: -24, dy: -24)), display: true)
        await pause(200)
        await saveScreenshot(of: context.launcher.window, as: name)
        window.setFrame(original, display: true)
    }

    /// ✦C opens the launcher on the history with its chip; "reunion" finds
    /// "Réunion…"; Return closes it and pastes into the app in front (the
    /// test window); ⌘⌫ forgets the row; ⌫ on the empty field leaves.
    private func clipboardPastesFromLauncher() async {
        let name = "Clipboard: ✦C shows the history with its chip, “reunion” finds “Réunion…”, the footer says Paste ↩, Return pastes it here, ⌘⌫ forgets, ⌫ leaves; opened with ✦C, esc closes"
        guard let store = context.clipboard.store else {
            record(name, false, "no clipboard store", nil)
            return
        }
        let marker = "Réunion skilli \(Int.random(in: 1000...9999))"
        // The real hash: once the paste is copied back (when skil.li may read
        // the clipboard) it is this row again, not a second one.
        guard let seeded = try? store.add(.init(kind: .text, text: marker, app: "com.apple.TextEdit", appName: "TextEdit",
                                                hash: ClipboardHistory.hash("text", Data(marker.utf8)))).item else {
            record(name, false, "could not add a row", nil)
            return
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        let pressed = await hyperChord(["c"], trigger: Self.ownTriggerKeyCode)
        let shown = await waitUntil(timeout: 1) { self.context.launcher.isVisible && self.context.launcher.isInClipboard }
        let shownMs = shown.map { _ in (ContinuousClock.now - pressed).milliseconds }
        for character in "reunion skilli" { await pressKey(character) }
        let found = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == marker } != nil
        if let directory = context.snapshotDirectory, let png = context.launcher.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("launcher-clipboard.png"))
        }
        let footer = context.launcher.shownFooter
        let footerSays = footer.first == "Paste ↩" && footer.last == "Actions ⌘K"
        if found { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let closed = await waitUntil(timeout: 1) { !self.context.launcher.isVisible } != nil
        let pasted = await waitUntil(timeout: 2) { self.textView.string.contains(marker) } != nil

        guard await focusTestWindow() else { return }
        _ = await hyperChord(["c"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { self.context.launcher.isInClipboard }
        for character in "reunion skilli" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == marker }
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let forgot = await waitUntil(timeout: 1) { !store.search(marker).contains { $0.id == seeded.id } } != nil
        for _ in 0..<"reunion skilli".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }
        await pressKey(nil, code: CGKeyCode(kVK_Delete))
        let left = await waitUntil(timeout: 1) { !self.context.launcher.isInClipboard } != nil
        await closeLauncher()
        // Opened straight with ✦C: esc goes back to the app at once.
        guard await focusTestWindow() else { return }
        _ = await hyperChord(["c"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { self.context.launcher.isInClipboard }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let straightClosed = await waitUntil(timeout: 1) { !self.context.launcher.isVisible } != nil
        await closeLauncher()
        // The undo card stayed under the launcher (`clipboardForgetUndoes`):
        // closed, so the next check starts without it.
        if context.aiActions.popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        record(name, shown != nil && found && footerSays && closed && pasted && forgot && left && straightClosed,
               "shown in clipboard mode: \(shown != nil); found: \(found), footer \(footer); launcher closed: \(closed); pasted: \(pasted); ⌘⌫ forgot: \(forgot); ⌫ left: \(left); ✦C then esc closed at once: \(straightClosed)",
               shownMs)
    }

    // MARK: - Screen tools

    /// The tools straight, no model: list_ui sees the box and the field,
    /// find_ui finds "the box to stay signed in", press_ui ticks it,
    /// set_ui_value fills the field, press_keys selects and deletes.
    private func screenToolsReadAndAct() async {
        let name = "Screen tools: list_ui reads the window, find_ui finds by description, press_ui ticks, set_ui_value fills, press_keys"
        let tools = context.tools.tools
        rememberBox.state = .off
        emailField.stringValue = ""
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        let listing = (try? await tools.call("list_ui", arguments: [:], run: nil)) ?? ""
        let lines = listing.split(separator: "\n").map(String.init)
        let boxLine = lines.first { $0.contains("checkbox “Remember me”") }
        let fieldLine = lines.first { $0.contains("text field “Email”") }
        let read = boxLine?.hasSuffix("(off)") == true && fieldLine != nil
        func id(_ line: String?) -> String { line.map { String($0.prefix { $0 != " " }) } ?? "" }

        tools.decisionKeysOverride = userDecisionKeys
        defer { tools.decisionKeysOverride = nil }
        let found = (try? await tools.call("find_ui", arguments: ["description": userDecisionKeys.isEmpty ? "remember" : "the box to stay signed in"], run: nil)) ?? ""
        let foundBox = found.split(separator: "\n").first?.contains("Remember me") == true

        _ = try? await tools.call("press_ui", arguments: ["id": id(boxLine)], run: nil)
        let ticked = await waitUntil(timeout: 1) { self.rememberBox.state == .on } != nil
        _ = try? await tools.call("set_ui_value", arguments: ["id": id(fieldLine), "text": "camille@example.com"], run: nil)
        let filled = await waitUntil(timeout: 1) { self.emailField.stringValue == "camille@example.com" } != nil

        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "abc"
        _ = try? await tools.call("press_keys", arguments: ["keys": "cmd+a"], run: nil)
        await pause(150)
        _ = try? await tools.call("press_keys", arguments: ["keys": "delete"], run: nil)
        let keyed = await waitUntil(timeout: 1) { self.textView.string.isEmpty } != nil

        record(name, read && foundBox && ticked && filled && keyed,
               "read: \(read) (\(lines.count) lines; \(boxLine ?? "no box"); \(fieldLine ?? "no field")); find_ui: “\(found.split(separator: "\n").first ?? "")”; ticked: \(ticked); filled: \(filled); cmd+a, delete: \(keyed)",
               nil)
    }

    /// A real agent (Claude Code, Haiku) told to tick the box: it finds it
    /// with the screen tools, the card asks, Return allows, it is ticked.
    private func actTicksTheBox() async {
        let name = "Act with screen tools: “tick Remember me” → find_ui/press_ui, allowed in the card, the box is ticked"
        // The self-test finds Claude Code when a check needs it (the app does
        // at launch).
        await context.ai.refresh()
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .auto
        rememberBox.state = .off
        let command = scratchCommand(
            prompt: "In the window in front, tick the “Remember me” checkbox. Then reply with just: Done.",
            output: .card
        )
        var act = command
        act.tools = ["screen"]
        act.model = .claude("haiku")
        context.aiCommands.save(act)
        defer {
            settings.mode = mode
            context.aiCommands.delete(command.id)
        }
        let start = ContinuousClock.now
        guard await run(act, on: "") else {
            record(name, false, "the card did not show", nil)
            return
        }
        // Reading never asks; pressing does, once per change. The card
        // still shows the last run's end until this one starts: wait for
        // the first question itself.
        var approvals = 0
        var asking = await waitUntil(timeout: 60, { popover.phase == .approving }) != nil
        while asking, approvals < 3 {
            approvals += 1
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            await pause(500)
            let settled = await waitUntil(timeout: 30) { popover.phase == .approving || popover.phase == .done || popover.phase == .failed } != nil
            asking = settled && popover.phase == .approving
        }
        _ = await waitUntil(timeout: 45) { popover.phase == .done || popover.phase == .failed }
        let latency = ContinuousClock.now - start
        await pause(250)
        await saveScreenshot(of: popover.window, as: "ai-card-act-screen.png")
        let steps = context.aiActions.lastSteps.map(\.title)
        let ticked = rememberBox.state == .on
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, ticked && popover.phase != .failed,
               "steps \(steps), approvals \(approvals), ticked: \(ticked), \(Int(latency.milliseconds / 1_000)) s", latency.milliseconds)
    }

    /// "change default browser to google chrome" typed in Ask, as the user
    /// types it: routed to the agent, not the browser opened ("change
    /// default browser to arc" once opened Arc), and the agent changes it;
    /// then the first browser asked back the same way.
    private func askChangesTheDefaultBrowser() async {
        let name = "Ask: “change default browser to …” → the agent changes it (not the browser opened), then puts it back"
        func defaultBrowser() -> String? {
            URL(string: "https://example.com").flatMap { NSWorkspace.shared.urlForApplication(toOpen: $0) }
                .flatMap { Bundle(url: $0)?.bundleIdentifier?.lowercased() }
        }
        let installed = [("google chrome", "com.google.chrome"), ("arc", "company.thebrowser.browser"), ("safari", "com.apple.safari")]
            .filter { NSWorkspace.shared.urlForApplication(withBundleIdentifier: $0.1) != nil }
        guard !userDecisionKeys.isEmpty, let before = defaultBrowser(),
              let first = installed.first(where: { $0.1 == before }), let other = installed.first(where: { $0.1 != before }) else {
            checks.append(Check(name: name, passed: true, skipped: true,
                                detail: "needs a decision key and two of Chrome, Arc, Safari (default: \(defaultBrowser() ?? "none"))", latencyMs: nil))
            return
        }
        await context.ai.refresh()
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .auto
        defer { settings.mode = mode }
        // One request through Ask: typed, Return, each approval allowed,
        // until the card is done.
        func ask(_ request: String, capture: String) async -> String {
            guard await focusTestWindow() else { return "no test window" }
            window.makeFirstResponder(textView)
            textView.string = ""
            guard await openAsk() else { return "Ask did not open" }
            for character in request { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let start = ContinuousClock.now
            var approvals = 0
            while approvals < 12 {
                let settled = await waitUntil(timeout: 180) {
                    popover.phase == .approving || popover.phase == .done || popover.phase == .failed || !popover.isVisible
                } != nil
                guard settled, popover.phase == .approving else { break }
                approvals += 1
                await pressKey(nil, code: CGKeyCode(kVK_Return))
                await pause(500)
            }
            let took = Int((ContinuousClock.now - start).milliseconds / 1_000)
            await pause(250)
            if popover.isVisible { await saveScreenshot(of: popover.window, as: capture) }
            let route = context.aiActions.lastRoute?.rawValue ?? "none"
            let opened = context.aiActions.lastOpenedApp.map { ", opened \($0)" } ?? ""
            let steps = context.aiActions.lastSteps.map(\.title)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return "route \(route)\(opened), phase \(popover.phase), steps \(steps), approvals \(approvals), \(took) s"
        }
        let there = await ask("change default browser to \(other.0)", capture: "ask-default-browser-changed.png")
        let changed = defaultBrowser() == other.1
        var back = await ask("change default browser to \(first.0)", capture: "ask-default-browser-back.png")
        // Not back: asked once more, so the Mac is not left on another
        // browser.
        if defaultBrowser() != before {
            back += "; asked again: " + (await ask("change default browser to \(first.0)", capture: "ask-default-browser-back-again.png"))
        }
        let restored = defaultBrowser() == before
        record(name, changed && restored,
               "to \(other.0): \(changed ? "changed" : "not changed (\(defaultBrowser() ?? "none"))") — \(there); back to \(first.0): "
                   + "\(restored ? "changed" : "not changed (\(defaultBrowser() ?? "none"))") — \(back)", nil)
    }

    // MARK: - Emoji

    /// How a person would say it, the emoji they would type: decided only.
    private func emojiByFeelingLive() async {
        let library = EmojiLibrary(defaults: UserDefaults(suiteName: "skilli-selftest-emoji-live-\(getpid())") ?? .standard)
        let cases: [(String, Set<String>)] = [
            ("trop content", ["😄", "😁", "😆", "🥳", "😊", "😃", "🤩", "😀", "☺️", "🤗", "🙌", "😍"]),
            ("je suis crevé", ["😴", "🥱", "😩", "😫", "😪", "😮‍💨", "🫠", "😓"]),
            ("j'ai le cœur brisé", ["💔", "😢", "😭", "🥺", "😞", "😔"]),
            ("bravo à toute l'équipe", ["👏", "🎉", "🙌", "🥳", "🏆", "👍", "💪"]),
            // Not named in the instructions: how far it carries.
            ("je suis mort de rire", ["😂", "🤣", "😆", "💀", "😹"]),
            ("ça me saoule", ["😒", "🙄", "😤", "😩", "😑", "😠", "😫", "🤬"]),
            ("on a gagné !!", ["🏆", "🥳", "🎉", "🙌", "🥇", "👏", "🎊", "💪", "😁", "😄", "😃", "🤩"])
        ]
        for provider in DecisionProvider.allCases {
            let name = "Emoji by feeling with \(provider.title): content, tired, heartbroken, well done, laughing, annoyed, we won"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var passed = true
            var details: [String] = []
            var slowest: Duration = .zero
            for (request, fitting) in cases {
                let start = ContinuousClock.now
                let found = await library.searchByMeaning(request, keys: [provider: key])
                slowest = max(slowest, .now - start)
                let first = found?.emoji.first?.character ?? "nothing"
                passed = passed && fitting.contains(first)
                details.append("“\(request)” → \(found?.emoji.prefix(3).map(\.character).joined() ?? "nothing")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// ":" opens the picker; "red heart" by name, Return types ❤️; a feeling
    /// and ⇥, Return types what the model chose.
    private func launcherPicksEmoji() async {
        let name = "Emoji: “emoji ” opens the picker, “red heart” → ❤️ typed; “trop content” ⇥ → a happy emoji typed"
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        // ":" needs Shift on some layouts; "emoji " is letters everywhere.
        for character in "emoji " { await pressKey(character) }
        let opened = await waitUntil(timeout: 1) { self.context.launcher.isInEmoji } != nil
        for character in "red heart" { await pressKey(character) }
        let heart = await waitUntil(timeout: 1) { self.context.launcher.selectedResultTitle?.lowercased().contains("heart") == true || self.context.launcher.selectedResultTitle?.lowercased().contains("cœur") == true } != nil
        if heart { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let typedHeart = await waitUntil(timeout: 2) { self.textView.string == "❤️" } != nil

        var feelingDetail = "no decision key: skipped"
        var feelingPassed = true
        if !userDecisionKeys.isEmpty {
            let launcher = context.launcher
            let keys = userDecisionKeys
            let saved = (launcher.emojiByFeelingAvailable, launcher.emojiByFeeling)
            launcher.emojiByFeelingAvailable = { true }
            let library = EmojiLibrary(defaults: UserDefaults(suiteName: "skilli-selftest-emoji-ui-\(getpid())") ?? .standard)
            launcher.emojiByFeeling = { request in await library.searchByMeaning(request, keys: keys) }
            defer { (launcher.emojiByFeelingAvailable, launcher.emojiByFeeling) = saved }
            textView.string = ""
            guard await focusTestWindow() else { return }
            window.makeFirstResponder(textView)
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "emoji " { await pressKey(character) }
            _ = await waitUntil(timeout: 1) { self.context.launcher.isInEmoji }
            for character in "trop content" { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Tab))
            let found = await waitUntil(timeout: 4) { self.context.launcher.isShowingFeeling && !self.context.launcher.resultTitles.isEmpty } != nil
            await captureLauncher(as: "launcher-emoji-feeling.png")
            if found { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
            let happy: Set<String> = ["😄", "😁", "😆", "🥳", "😊", "😃", "🤩", "😀", "☺️", "🤗", "🙌", "😍"]
            let typed = await waitUntil(timeout: 2) { happy.contains(self.textView.string) } != nil
            feelingPassed = found && typed
            feelingDetail = "⇥ found: \(found), typed: “\(textView.string)”"
        }
        await closeLauncher()
        record(name, opened && heart && typedHeart && feelingPassed,
               "opened: \(opened), red heart selected: \(heart), typed ❤️: \(typedHeart); \(feelingDetail)", nil)
    }

    /// Search GIFs on a stand-in Klipy (127.0.0.1) and a GIF seeded in the
    /// home folder: "gif " opens the grid on Trending (one request), →
    /// selects and plays that tile alone, "cat" asks Klipy once typing
    /// pauses and shows its GIFs in its order, ↩ pastes one animated (the
    /// file and its GIF data) and Klipy counts the share with the words;
    /// opened again, Recently Used comes first, read back by its slug; this
    /// Mac's GIF found by name, ⌘↩ copies its bytes, nothing sent for it;
    /// closed, nothing kept; without a key, Klipy is never asked.
    private func gifsSearchPasteAndRecents() async {
        let name = "Search GIFs: Trending in one request, only the selected tile plays, one search after the pause in Klipy's order, ↩ pastes it animated and the share is counted, Recently Used by slug, this Mac's GIF copied, nothing asked without a key"
        let launcher = context.launcher
        guard let library = launcher.gifLibrary else {
            record(name, false, "no GIF library", nil)
            return
        }
        guard let gifData = Self.animatedGIF(frames: 3), let jpeg = Self.firstFrameJPEG(gifData) else {
            record(name, false, "could not make the test GIF", nil)
            return
        }
        let stand = KlipyStandIn(gif: gifData, jpeg: jpeg)
        guard let server = LoopbackServer(handler: { stand.answer($0) }), let port = await server.port(),
              let base = URL(string: "http://127.0.0.1:\(port)") else {
            record(name, false, "the stand-in Klipy did not start", nil)
            return
        }
        defer { server.stop() }
        stand.base = base.absoluteString
        let saved = (library.base, library.keyOverride, launcher.gifFolder)
        defer {
            (library.base, library.keyOverride, launcher.gifFolder) = saved
            library.forgetRecents()
        }
        library.base = base
        library.keyOverride = KlipyStandIn.key
        library.forgetRecents()

        // A GIF of this Mac, which Spotlight must index first.
        let marker = Int.random(in: 1000...9999)
        let fileName = "Skilli-selftest-dance-\(marker).gif"
        let folder = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent("skilli-selftest-gifs-\(getpid())", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: folder) }
        try? gifData.write(to: folder.appendingPathComponent(fileName))
        await Self.run("/usr/bin/mdimport", [folder.path])
        launcher.gifFolder = folder
        var indexed = false
        let deadline = ContinuousClock.now + .seconds(20)
        while !indexed, ContinuousClock.now < deadline {
            indexed = await FileSearch.gifs("dance \(marker)", in: folder).contains { $0.lastPathComponent == fileName }
            if !indexed { try? await Task.sleep(for: .milliseconds(500)) }
        }

        window.makeFirstResponder(textView)
        textView.string = ""
        let grid = launcher.gifGridView
        func open() async -> Bool {
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "gif " { await pressKey(character) }
            return await waitUntil(timeout: 3) { launcher.isInGIFs && launcher.isShowingGIFGrid && !launcher.isSearchingGIFs } != nil
        }
        let gifType = NSPasteboard.PasteboardType(UTType.gif.identifier)
        func pastedFrames() -> Int {
            guard let data = NSPasteboard.general.data(forType: gifType), let source = CGImageSourceCreateWithData(data as CFData, nil) else { return 0 }
            return CGImageSourceGetCount(source)
        }

        // 1. Trending, in one request; the stills come.
        let opened = await open()
        let trending = launcher.results.map(\.title) == (1...6).map { "Trending \($0)" } && grid.sectionNames == ["Trending on Klipy"]
        let trendingAsked = stand.paths.filter { $0.hasSuffix("/gifs/trending") }.count
        let stills = await waitUntil(timeout: 4) { grid.stillsLoaded >= 4 } != nil
        await captureLauncherBothWays(as: "launcher-gifs-trending")

        // 2. → selects the next tile; only that one plays.
        await pressKey(nil, code: CGKeyCode(kVK_RightArrow))
        let plays = await waitUntil(timeout: 2) { grid.selected == 1 && grid.playingIndex == 1 } != nil

        // 3. "cat": nothing asked while typing, one search once it pauses.
        let searchesBefore = stand.searches.count
        for character in "cat" { await pressKey(character) }
        let askedWhileTyping = stand.searches.count != searchesBefore
        let searched = await waitUntil(timeout: 3) { grid.sectionNames == ["Klipy"] && launcher.results.count == 4 } != nil
        let searches = Array(stand.searches.dropFirst(searchesBefore))
        let order = launcher.results.map(\.title) == (1...4).map { "Cat \($0)" }
        _ = await waitUntil(timeout: 3) { grid.stillsLoaded >= 4 }
        await captureLauncherBothWays(as: "launcher-gifs-search")

        // 4. ↩ pastes it animated; Klipy counts the share with the words.
        NSPasteboard.general.clearContents()
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let pasted = await waitUntil(timeout: 4) { pastedFrames() > 1 && NSPasteboard.general.string(forType: .fileURL) != nil } != nil
        let frames = pastedFrames()
        let shared = await waitUntil(timeout: 2) { stand.shares.contains { $0.slug == "cat-1" && $0.query == "cat" } } != nil
        // ⌘V landed in the test window (its file, as text or a picture).
        let landed = await waitUntil(timeout: 2) {
            self.textView.string.contains("Cat 1") || self.textView.textStorage?.containsAttachments == true
        } != nil
        textView.string = ""
        await closeLauncher()

        // 5. Opened again: Recently Used first, read back by its slug.
        let reopened = await open()
        let recent = grid.sectionNames.first == "Recently Used" && launcher.results.first?.title == "Cat 1"
        let readBack = stand.paths.contains { $0.hasSuffix("/gifs/items") } && stand.itemSlugs.last == ["cat-1"]

        // 6. This Mac's GIF by its name: ⌘↩ copies its bytes, nothing sent.
        let sharesBefore = stand.shares.count
        for character in "dance \(marker)" { await pressKey(character) }
        let local = await waitUntil(timeout: 4) {
            grid.sectionNames == ["On this Mac"] && launcher.results.first?.title == (fileName as NSString).deletingPathExtension
        } != nil
        await captureLauncherBothWays(as: "launcher-gifs-this-mac")
        NSPasteboard.general.clearContents()
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
        let copied = await waitUntil(timeout: 2) { NSPasteboard.general.data(forType: gifType) == gifData } != nil
        let noShare = stand.shares.count == sharesBefore
        await closeLauncher()
        let released = grid.stillsLoaded == 0 && grid.playingIndex == nil

        // 7. No key: Klipy never asked; this Mac's GIF still found.
        library.keyOverride = ""
        let asked = stand.requests.count
        let keyless = await open()
        for character in "dance \(marker)" { await pressKey(character) }
        let keylessLocal = await waitUntil(timeout: 4) { launcher.results.count == 1 && grid.sectionNames == ["On this Mac"] } != nil
        let silent = stand.requests.count == asked
        await captureLauncherBothWays(as: "launcher-gifs-no-key")
        await closeLauncher()

        let passed = indexed && opened && trending && trendingAsked == 1 && stills && plays && !askedWhileTyping && searched && searches == ["cat"]
            && order && pasted && shared && landed && reopened && recent && readBack && local && copied && noShare && released && keyless && keylessLocal && silent
        record(name, passed,
               "indexed \(indexed); opened \(opened), Trending \(trending) asked \(trendingAsked)×, stills \(stills) (\(grid.stillsLoaded)); → plays tile 1 alone \(plays); "
               + "asked while typing \(askedWhileTyping), searched \(searched) \(searches), Klipy's order \(order); ↩ pasted \(pasted) (\(frames) frames), share counted \(shared), landed in the window \(landed); "
               + "reopened \(reopened), Recently Used \(recent), read back by slug \(readBack); this Mac's \(local), ⌘↩ copied \(copied), nothing sent \(noShare); "
               + "released \(released); no key: opened \(keyless), found \(keylessLocal), Klipy not asked \(silent); launcher-gifs-*-light/-dark.png",
               nil)
    }

    /// Search GIFs as a user gets it: the build's own Klipy key, nothing set
    /// in Settings, the real Klipy. Trending, "bonjour", the selected GIF
    /// playing frame after frame, ↩ pasting it animated into a rich text
    /// window, Recently Used read back from Klipy by its slug. Fails when
    /// the build has no key: it must be built with SKILLI_KLIPY_KEY.
    private func gifsOnRealKlipy() async {
        let name = "Search GIFs on the real Klipy with the build's own key: Trending, “bonjour”, the selected GIF plays, ↩ pastes it animated, Recently Used read back"
        let launcher = context.launcher
        guard let library = launcher.gifLibrary else {
            record(name, false, "no GIF library", nil)
            return
        }
        guard library.keySource == .skilli, library.canSearchKlipy else {
            record(name, false, "this build has no Klipy key of its own: build it with SKILLI_KLIPY_KEY (key source: \(library.keySource))", nil)
            return
        }
        let rich = (textView.isRichText, textView.importsGraphics)
        defer {
            (textView.isRichText, textView.importsGraphics) = rich
            library.forgetRecents()
        }
        library.forgetRecents()
        textView.isRichText = true
        textView.importsGraphics = true
        window.makeFirstResponder(textView)
        textView.string = ""
        let grid = launcher.gifGridView
        func open() async -> Bool {
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "gif " { await pressKey(character) }
            return await waitUntil(timeout: 10) { launcher.isInGIFs && launcher.isShowingGIFGrid && !launcher.isSearchingGIFs } != nil
        }
        let gifType = NSPasteboard.PasteboardType(UTType.gif.identifier)
        func frames(_ data: Data?) -> Int {
            guard let data, let source = CGImageSourceCreateWithData(data as CFData, nil) else { return 0 }
            return CGImageSourceGetCount(source)
        }

        // 1. Trending on Klipy, the stills, the first tile playing.
        let start = ContinuousClock.now
        let opened = await open()
        let trendingIn = ContinuousClock.now - start
        let trending = grid.sectionNames == ["Trending on Klipy"] && launcher.results.count >= 8
        let stills = await waitUntil(timeout: 10) { grid.stillsLoaded >= 8 } != nil
        let plays = await waitUntil(timeout: 10) { grid.playingIndex == 0 && grid.framesShown >= 3 } != nil
        await captureLauncherBothWays(as: "launcher-gifs-live-trending")

        // 2. "bonjour": Klipy's GIFs for it.
        for character in "bonjour" { await pressKey(character) }
        let searched = await waitUntil(timeout: 10) { grid.sectionNames.first == "Klipy" && launcher.results.count >= 8 } != nil
        _ = await waitUntil(timeout: 10) { grid.stillsLoaded >= 16 }
        let searchPlays = await waitUntil(timeout: 10) { grid.playingIndex == 0 && grid.framesShown >= 3 } != nil
        let firstTitle = launcher.results.first?.title ?? ""
        await captureLauncherBothWays(as: "launcher-gifs-live-search")

        // 3. ↩: the GIF on the clipboard, then in the window, animated.
        NSPasteboard.general.clearContents()
        let pasteStart = ContinuousClock.now
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let onClipboard = await waitUntil(timeout: 15) { frames(NSPasteboard.general.data(forType: gifType)) > 1 } != nil
        let clipboardFrames = frames(NSPasteboard.general.data(forType: gifType))
        let landed = await waitUntil(timeout: 5) { self.textView.textStorage?.containsAttachments == true } != nil
        let pastedIn = ContinuousClock.now - pasteStart
        var landedFrames = 0
        if let storage = textView.textStorage {
            storage.enumerateAttribute(.attachment, in: NSRange(location: 0, length: storage.length)) { value, _, _ in
                guard let attachment = value as? NSTextAttachment else { return }
                landedFrames = max(landedFrames, frames(attachment.fileWrapper?.regularFileContents ?? attachment.contents))
            }
        }
        await pause(800)
        await captureWindow(of: getpid(), as: "gifs-live-pasted.png")
        textView.string = ""
        await closeLauncher()

        // 4. Recently Used: the GIF pasted, read back from Klipy by its slug.
        let reopened = await open()
        let recent = grid.sectionNames.first == "Recently Used" && launcher.results.first?.title == firstTitle && !firstTitle.isEmpty
        _ = await waitUntil(timeout: 8) { grid.stillsLoaded >= 4 }
        await captureLauncherBothWays(as: "launcher-gifs-live-recent")
        await closeLauncher()

        let passed = opened && trending && stills && plays && searched && searchPlays && onClipboard && landed && landedFrames > 1 && reopened && recent
        record(name, passed,
               "opened \(opened) in \(trendingIn.compact), Trending \(trending) (\(grid.sectionNames)), stills \(stills), first tile plays \(plays); "
               + "“bonjour” \(searched), plays \(searchPlays), first “\(firstTitle)”; ↩ on the clipboard \(onClipboard) (\(clipboardFrames) frames), "
               + "in the window \(landed) (\(landedFrames) frames) in \(pastedIn.compact); Recently Used \(recent); "
               + "launcher-gifs-live-*-light/-dark.png, gifs-live-pasted.png",
               nil)
    }

