    /// Three frames of different colours, looping: an animated GIF.
    nonisolated static func animatedGIF(frames: Int) -> Data? {
        let data = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(data as CFMutableData, UTType.gif.identifier as CFString, frames, nil) else { return nil }
        CGImageDestinationSetProperties(destination, [kCGImagePropertyGIFDictionary: [kCGImagePropertyGIFLoopCount: 0]] as CFDictionary)
        let colors: [(CGFloat, CGFloat, CGFloat)] = [(0.2, 0.75, 0.65), (0.95, 0.6, 0.2), (0.35, 0.4, 0.9)]
        for index in 0..<frames {
            guard let context = CGContext(data: nil, width: 160, height: 120, bitsPerComponent: 8, bytesPerRow: 0,
                                          space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
            let color = colors[index % colors.count]
            context.setFillColor(red: color.0, green: color.1, blue: color.2, alpha: 1)
            context.fill(CGRect(x: 0, y: 0, width: 160, height: 120))
            context.setFillColor(gray: 1, alpha: 0.9)
            context.fillEllipse(in: CGRect(x: 20 + index * 40, y: 35, width: 50, height: 50))
            guard let image = context.makeImage() else { return nil }
            CGImageDestinationAddImage(destination, image, [kCGImagePropertyGIFDictionary: [kCGImagePropertyGIFDelayTime: 0.2]] as CFDictionary)
        }
        return CGImageDestinationFinalize(destination) ? data as Data : nil
    }

    nonisolated static func firstFrameJPEG(_ gif: Data) -> Data? {
        guard let source = CGImageSourceCreateWithData(gif as CFData, nil), let image = CGImageSourceCreateImageAtIndex(source, 0, nil) else { return nil }
        return NSBitmapImageRep(cgImage: image).representation(using: .jpeg, properties: [:])
    }

    /// The picker as a grid (2026-10-16, after Raycast's): browsing
    /// shows Recently Used then Unicode's groups, every emoji; → selects
    /// the next tile, ↓ the one under it in the same column, ↑ back; a
    /// search ranks in the grid and ↩ types the one selected.
    private func emojiGridBrowsesAndMoves() async {
        let name = "Emoji grid: every emoji in Unicode's groups, ←→↑↓ move in two directions, a search, ↩ types the one selected"
        let launcher = context.launcher
        let grid = launcher.emojiGridView
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "emoji " { await pressKey(character) }
        let shown = await waitUntil(timeout: 1) { launcher.isInEmoji && launcher.isShowingEmojiGrid } != nil
        let groups = grid.groupNames
        let browsed = launcher.results.count
        let browsing = groups.contains("Smileys & Emotion") && groups.contains("Flags") && groups.last == SymbolTable.groupNames.last && browsed > 1500
        await pause(300)
        await captureLauncherBothWays(as: "launcher-emoji-grid")

        let start = grid.selected
        await pressKey(nil, code: CGKeyCode(kVK_RightArrow))
        let right = grid.selected == start + 1
        let before = grid.frame(of: grid.selected)
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        let after = grid.frame(of: grid.selected)
        let down = before.flatMap { above in after.map { $0.minY > above.minY && abs($0.midX - above.midX) < 1 } } ?? false
        await pressKey(nil, code: CGKeyCode(kVK_UpArrow))
        let up = grid.selected == start + 1

        for character in "cat" { await pressKey(character) }
        let searched = await waitUntil(timeout: 1) { !launcher.resultTitles.isEmpty && grid.groupNames.isEmpty && grid.selected == 0 } != nil
        await captureLauncherBothWays(as: "launcher-emoji-grid-search")
        var expected = ""
        if let first = launcher.results.first, case .emoji(let emoji) = first {
            expected = emoji.character(in: context.preferences.emojiSkinTone)
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let typed = await waitUntil(timeout: 2) { !expected.isEmpty && self.textView.string == expected } != nil
        await closeLauncher()

        record(
            name,
            shown && browsing && right && down && up && searched && typed,
            "grid shown: \(shown); groups \(groups.joined(separator: ", ")), \(browsed) emoji; → \(right), ↓ same column \(down), ↑ back \(up); “cat” searched \(searched), ↩ typed “\(textView.string)” (expected “\(expected)”); launcher-emoji-grid(-search)-light/-dark.png",
            nil
        )
    }

    /// Symbols in the picker (2026-10-19: the Apple logo found
    /// nothing): "apple logo" finds it first, its names and the keys that
    /// type it on this Mac's layout beside them, drawn in the text color
    /// in both appearances; ↩ types it.
    private func emojiPickerFindsSymbols() async {
        let name = "Emoji picker: “apple logo” finds the Apple logo, its keys said beside its name, ↩ types it"
        let launcher = context.launcher
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "emoji " { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.isInEmoji }
        for character in "apple logo" { await pressKey(character) }
        let logo = "\u{F8FF}"
        let found = await waitUntil(timeout: 1) {
            if let first = launcher.results.first, case .emoji(let emoji) = first { return emoji.character == logo }
            return false
        } != nil
        let keys = launcher.typingKeys?(logo)
        let label = launcher.emojiNameText
        let named = label.contains("Apple logo") && (keys.map(label.contains) ?? true)
        await pause(200)
        await captureLauncherBothWays(as: "launcher-emoji-symbols")
        if found { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
