    /// Settings → Emoji: Medium pressed as a user would, then
    /// "thumbs up" ↩ types 👍🏽. Found by meaning (a stand-in answer, no
    /// key needed) and picked, the same words then find it by name at
    /// once, first, without asking again.
    private func emojiToneAndSaidWords() async {
        let name = "Emoji: the skin tone picked in Settings → Emoji is typed (thumbs up → 👍🏽); words found by meaning find it again at once, counted there, forgotten"
        let preferences = context.preferences
        let launcher = context.launcher
        let settings = context.settings
        let savedTone = preferences.emojiSkinTone
        let savedFeeling = (launcher.emojiByFeelingAvailable, launcher.emojiByFeeling)
        defer {
            preferences.emojiSkinTone = savedTone
            (launcher.emojiByFeelingAvailable, launcher.emojiByFeeling) = savedFeeling
        }
        preferences.emojiSkinTone = .standard

        // 1. The tone, pressed in Settings.
        let anchor = "emojiSkinTone"
        let medium = EmojiSkinTone.medium
        func mediumButton() -> AXUIElement? {
            Self.axElements(roles: [kAXButtonRole], where: { $0 == medium.title || $0 == medium.apply(to: "🖐️") }).first
        }
        settings.show(pane: .emoji)
        settings.search.reveal(anchor, in: .emoji)
        _ = await waitUntil(timeout: 2) { settings.search.landed == anchor }
        _ = await waitUntil(timeout: 2) { mediumButton() != nil }
        if let button = mediumButton() { AXUIElementPerformAction(button, kAXPressAction as CFString) }
        let picked = await waitUntil(timeout: 1) { preferences.emojiSkinTone == medium } != nil
        // The glow gone (about a second).
        await pause(1_600)
        await captureSettingsBothWays(as: "settings-emoji")
        await closeSettings()

        func openPicker() async -> Bool {
            textView.string = ""
            guard await focusTestWindow() else { return false }
            window.makeFirstResponder(textView)
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "emoji " { await pressKey(character) }
            return await waitUntil(timeout: 1) { launcher.isInEmoji } != nil
        }

        // 2. Thumbs up, typed in that tone.
        guard await openPicker() else { return }
        for character in "thumbs up" { await pressKey(character) }
        let thumbs = await waitUntil(timeout: 1) {
            let title = launcher.selectedResultTitle?.lowercased() ?? ""
            // macOS's French name: "Pouce pointant vers le haut".
            return title.contains("thumbs up") || title.hasPrefix("pouce")
        } != nil
        await captureLauncher(as: "launcher-emoji-tone.png")
        if thumbs { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let toned = await waitUntil(timeout: 2) { self.textView.string == "👍🏽" } != nil
        let typedTone = textView.string

        // 3. By meaning, then by the same words.
        final class Count { var asked = 0 }
        let count = Count()
        let sleeping = Emoji(character: "😴", name: "sleeping face", english: "sleeping face")
        launcher.emojiByFeelingAvailable = { true }
        launcher.emojiByFeeling = { _ in
            count.asked += 1
            return ([sleeping], "stand-in")
        }
        let phrase = "lundi matin sans cafe"
        guard await openPicker() else { return }
        for character in phrase { await pressKey(character) }
        let byFeeling = await waitUntil(timeout: 3) { launcher.isShowingFeeling && !launcher.resultTitles.isEmpty } != nil
        if byFeeling { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let firstTyped = await waitUntil(timeout: 2) { self.textView.string == "😴" } != nil
        let askedFirst = count.asked

        guard await openPicker() else { return }
        for character in phrase { await pressKey(character) }
        let byName = await waitUntil(timeout: 1) { !launcher.resultTitles.isEmpty && !launcher.isShowingFeeling } != nil
        await pause(500)
        if byName { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let againTyped = await waitUntil(timeout: 2) { self.textView.string == "😴" } != nil
        let askedAgain = count.asked - askedFirst
        await closeLauncher()

        // 4. Settings → Emoji counts them; Forget empties them at once,
        // nothing asked; ⌘Z in the card brings them back.
        // The library the pane is given (the self-test's own store).
        let library = settings.freshContext().emoji
        let counted = library?.saidCount ?? 0
        settings.show(pane: .emoji)
        settings.search.reveal("section.wordsLearned", in: .emoji)
        _ = await waitUntil(timeout: 2) { settings.search.landed == "section.wordsLearned" }
        await pause(1_600)
        await captureSettingsBothWays(as: "settings-emoji-learned")
        // Forget, pressed as a user would: no dialog, the undo card.
        func button(_ title: String) -> AXUIElement? {
            Self.axElements(roles: [kAXButtonRole], where: { $0 == title }).first
        }
        let popover = context.aiActions.popover
        if let forget = button("Forget") { AXUIElementPerformAction(forget, kAXPressAction as CFString) }
        let forgotten = await waitUntil(timeout: 2) { library?.saidCount == 0 } != nil
        let offered = await waitUntil(timeout: 2) { popover.shownTitle == "Words Forgotten" && popover.hintKeys == ["⌘Z", "esc"] } != nil
        await pressKey("z", flags: .maskCommand)
        let back = await waitUntil(timeout: 2) { library?.saidCount == counted } != nil
        await closeSettings()

        record(
            name,
            picked && thumbs && toned && byFeeling && firstTyped && askedFirst == 1 && byName && againTyped && askedAgain == 0
                && counted >= 1 && forgotten && offered && back,
            "Medium pressed in Settings: \(picked); thumbs up: \(thumbs), typed “\(typedTone)”; by meaning: shown \(byFeeling), typed 😴 \(firstTyped), asked \(askedFirst); same words again: by name \(byName), typed 😴 \(againTyped), asked again \(askedAgain); Settings: \(counted) learned, forgotten at once \(forgotten), undo card \(offered), ⌘Z brought them back \(back); settings-emoji-*.png, settings-emoji-learned-*.png, launcher-emoji-tone.png",
            nil
        )
    }

    // MARK: - Quicklinks

    /// "g skilli launcher" opens Google's results; "youtube" picked by name
    /// puts "yt " in the field, then "lofi" opens YouTube; text that matches
    /// nothing offers a web search before Ask. URLs recorded, not opened.
    private func launcherOpensQuicklinks() async {
        let name = "Quicklinks: “g skilli launcher” opens Google; “youtube” fills “yt ”, then “lofi”; nothing found offers a web search"
        let actions = context.actions
        let dryRun = actions.dryRunURLs
        actions.dryRunURLs = true
        defer { actions.dryRunURLs = dryRun }
        var details: [String] = []

        guard await focusTestWindow() else { return }
        // Nothing selected: a selection would be YouTube's query.
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "g skilli launcher" { await pressKey(character) }
        let google = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "Google · skilli launcher" } != nil
        if google { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let openedGoogle = await waitUntil(timeout: 1) { actions.lastURL == "https://www.google.com/search?q=skilli%20launcher" } != nil
        details.append("Google row: \(google), opened: \(openedGoogle)")
        await closeLauncher()

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "youtube" { await pressKey(character) }
        let byName = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "YouTube" } != nil
        if byName { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let filled = await waitUntil(timeout: 1) { self.context.launcher.query == "yt " } != nil
        for character in "lofi" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "YouTube · lofi" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let openedYouTube = await waitUntil(timeout: 1) { actions.lastURL == "https://www.youtube.com/results?search_query=lofi" } != nil
        details.append("YouTube by name: \(byName), “yt ” in the field: \(filled), opened: \(openedYouTube)")
        await closeLauncher()

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "zqxw nothing here" { await pressKey(character) }
        let fallback = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.contains("Search Google for “zqxw nothing here”") } != nil
        let askLast = context.launcher.lastResultTitle?.hasPrefix("Ask") == true
        details.append("web search offered: \(fallback), Ask still last: \(askLast)")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        record(name, google && openedGoogle && byName && filled && openedYouTube && fallback && askLast, details.joined(separator: "; "), nil)
    }

    // MARK: - Timers

    /// "timer 3s selftest" from the launcher counts down in the menu bar and
    /// ends with its card; Ask starts one from a sentence with no model.
    /// A card takes only the keys of what the user does with it (the
    /// interactions review, 2026-10-17): a note lets ↩ through to the app
    /// in front and stays; the undo card answers ⌘Z, never ↩; ⌘↩ typed in a
    /// card's field answers it and never reaches the app behind (Send in
    /// Mail); an agent's question lets the keys of its first half second
    /// through; a running timer is not a row for "t", nor the first one.
    private func cardsLeaveTheAppItsKeys() async {
        let name = "Cards leave the app its keys: a note lets ↩ through, undo is ⌘Z, ⌘↩ in a card's field stays there, an agent's question waits; running timers not on “t”"
        let actions = context.aiActions
        let popover = actions.popover
        let presence = actions.userPresenceOverride
        actions.userPresenceOverride = true
        actions.unpromptedGrace = .milliseconds(500)
        defer {
            actions.userPresenceOverride = presence
            actions.unpromptedGrace = .zero
        }
        final class Flag { var on = false }
        func reached(_ code: Int, command: Bool = false) -> Bool {
            recorder.events.contains { $0.keyCode == UInt16(code) && $0.flags.contains(.command) == command }
        }
        var details: [String] = []

        // A note: ↩ goes on to the app, the note stays; esc closes it.
        guard await focusRecorder() else { return }
        actions.notify("Self-test note", caller: "Self-test", run: nil, seconds: 3)
        let noteShown = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText == "Self-test note" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        await pause(150)
        let noteLetReturn = reached(kVK_Return)
        let noteStayed = popover.isVisible && popover.shownText == "Self-test note"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let noteClosed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        details.append("note: shown \(noteShown), ↩ to the app \(noteLetReturn), stayed \(noteStayed), esc closed \(noteClosed)")

        // The undo card: ↩ goes on to the app, ⌘Z undoes.
        guard await focusRecorder() else { return }
        let undone = Flag()
        actions.offerUndo("Self-test Deleted", details: "Self-test layout", seconds: 5) { undone.on = true }
        let undoShown = await waitUntil(timeout: 1) { popover.isVisible && popover.shownTitle == "Self-test Deleted" } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        await pause(150)
        let undoLetReturn = reached(kVK_Return) && !undone.on && popover.isVisible
        await pressKey("z", flags: .maskCommand)
        let undid = await waitUntil(timeout: 1) { undone.on && !popover.isVisible } != nil
        let zKept = !recorder.events.contains { $0.characters == "z" }
        details.append("undo: shown \(undoShown), ↩ to the app and nothing undone \(undoLetReturn), ⌘Z undid \(undid) and stayed in the card \(zKept)")

        // An agent's question: a key in its first half second is the app's;
        // ⌘↩ after typing answers it and never reaches the app.
        guard await focusRecorder() else { return }
        let answering = Task { await actions.ask(PromptQuestion(id: "selftest", question: "Self-test question"), caller: "Self-test", run: nil) }
        let asked = await waitUntil(timeout: 2) { popover.isVisible && popover.phase == .asking } != nil
        await pressKey("q")
        await pause(600)
        let earlyKeyToApp = recorder.events.contains { $0.characters == "q" }
        for character in "ok" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
        let answer = await answering.value
        let commandReturnKept = !reached(kVK_Return, command: true)
        details.append("agent question: shown \(asked), early key to the app \(earlyKeyToApp), ⌘↩ answered “\(answer ?? "nothing")”, ⌘↩ kept from the app \(commandReturnKept)")

        // Running timers: not for "t", and not first for "timer".
        let timers = context.timers
        let running = timers.start(TimerRequest(seconds: 120, label: "Selftest"))
        defer { timers.cancel(running.id) }
        guard await focusTestWindow() else { return }
        let launcher = context.launcher
        func isTimer(_ item: LauncherItem) -> Bool { if case .runningTimer = item { true } else { false } }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        await pressKey("t")
        await pause(250)
        let onT = launcher.results.contains(where: isTimer)
        for character in "imer" { await pressKey(character) }
        await pause(250)
        let onTimer = launcher.results.contains(where: isTimer)
        let timerFirst = launcher.results.first.map(isTimer) == true && launcher.results.count > 1
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        details.append("running timer on “t”: \(onT), on “timer”: \(onTimer), first: \(timerFirst)")

        record(name, noteShown && noteLetReturn && noteStayed && noteClosed && undoShown && undoLetReturn && undid && zKept
               && asked && earlyKeyToApp && answer == "ok" && commandReturnKept && !onT && onTimer && !timerFirst,
               details.joined(separator: "; "), nil)
    }

    private func timersCountDown() async {
        let name = "Timers: “timer 3s selftest” counts down in the menu bar (no card) and rings; Ask starts one from a sentence without a model; unsure, started with ⌘Z"
        let timers = context.timers
        let popover = context.aiActions.popover
        for timer in timers.timers { timers.cancel(timer.id) }
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "timer 3s selftest" { await pressKey(character) }
        let offered = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "Start Timer · Selftest · 3 s" } != nil
        if offered { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let started = await waitUntil(timeout: 1) { timers.timers.count == 1 } != nil
        let counting = await waitUntil(timeout: 2) { timers.menuBarTitle?.contains("0:0") == true } != nil
        // The menu bar counting is the answer: no card says it started.
        let quiet = !popover.isVisible
        let rang = await waitUntil(timeout: 6) { timers.timers.isEmpty && popover.shownText.contains("Selftest") && popover.shownText.contains("done") } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await pause(300)

        // Ask: the timer route and its values as the model reads them
        // (`AskValues`; real ones in `selftest decide`), the label among
        // the request's own words.
        let askStart = ContinuousClock.now
        let sentence = "mets un minuteur de 5 secondes pour le test"
        let spans = AskValues.spans(of: sentence)
        context.aiActions.decisionOverride = AskRouter.Decision(route: .timer, confidence: 0.95, menu: [], routes: [(.timer, 0.95)], label: "Test")
        context.aiActions.valuesOverride = [
            "length": .init(choice: "5 s", confidence: 0.96),
            "label": .init(choice: "phrase \(spans.firstIndex(of: "test") ?? 0)", confidence: 0.9)
        ]
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": sentence])
        let askStarted = await waitUntil(timeout: 1) { timers.timers.contains { $0.label == "Test" && $0.seconds == 5 } } != nil
        let askMs = (ContinuousClock.now - askStart).milliseconds
        _ = await waitUntil(timeout: 7) { timers.timers.isEmpty }
        await pause(300)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // Unsure of the length: started all the same, said with ⌘Z, which
        // cancels it (a timer is undone as easily as it starts).
        context.aiActions.valuesOverride?["length"] = .init(choice: "10 min", confidence: 0.4)
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "mets un minuteur de dix minutes pour le test"])
        let unsureStarted = await waitUntil(timeout: 2) {
            timers.timers.contains { $0.seconds == 600 } && popover.isVisible && popover.shownTitle == "Timer Started"
                && popover.shownText.contains("10 min") && popover.hintTitles == ["Undo", "Close"]
        } != nil
        await pressKey("z", flags: .maskCommand)
        let unsureUndone = await waitUntil(timeout: 2) { !timers.timers.contains { $0.seconds == 600 } && !popover.isVisible } != nil
        for timer in timers.timers where timer.seconds == 600 { timers.cancel(timer.id) }
        context.aiActions.decisionOverride = nil
        context.aiActions.valuesOverride = nil
        record(name, offered && started && counting && quiet && rang && askStarted && unsureStarted && unsureUndone,
               "offered: \(offered), started: \(started), menu bar counting: \(counting) (“\(timers.menuBarTitle ?? "")”), no card: \(quiet), rang with its card: \(rang); Ask started “Test · 5 s” from the model's values: \(askStarted) in \(Int(askMs)) ms; unsure: started with Undo \(unsureStarted), ⌘Z cancelled it \(unsureUndone)",
               askMs)
    }

    // MARK: - Calculator

    /// "12,5 * 4" answers first and Return copies it; "10 km en miles" and
    /// "time in tokyo" answer too.
    private func launcherCalculates() async {
        let name = "Calculator: “12,5 * 4” answers first, its footer and ⌘K say Paste Result ↩ and Copy Result ⌘↩, ↩ pastes it here; ⌘↩ copies “10 km en miles”, ⌘C “time in tokyo”"
        var passed = true
        var details: [String] = []
        // ↩ pastes like a clip, a snippet or an emoji (D4); ⌘↩ and ⌘C copy,
        // nothing said.
        enum Key { case paste, copy, commandC }
        for (typed, key) in [("12,5 * 4", Key.paste), ("10 km en miles", .copy), ("time in tokyo", .commandC)] {
            guard let expected = Calculator.evaluate(typed) else {
                record(name, false, "“\(typed)” is not a calculation here", nil)
                return
            }
            guard await focusTestWindow() else { return }
            window.makeFirstResponder(textView)
            textView.string = ""
            let openBefore = context.launcher.isVisible
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            let opened = await waitUntil(timeout: 0.5) { self.context.launcher.isVisible } != nil
            for character in typed { await pressKey(character) }
            // Read again at each look: "time in tokyo" moves on with the minute.
            let first = await waitUntil(timeout: 1) {
                self.context.launcher.resultTitles.first == (Calculator.evaluate(typed)?.display ?? expected.display)
            } != nil
            passed = passed && first
            var detail = "“\(typed)” → \(context.launcher.resultTitles.first ?? "nothing")"
                + (first ? "" : " (open before ✦Space: \(openBefore), opened by it: \(opened), field “\(context.launcher.query)”, launcher visible: \(context.launcher.isVisible), front: \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"), key window: \(NSApp.keyWindow.map { String(describing: type(of: $0)) } ?? "none"), test text “\(textView.string.suffix(20))”)")
            setClipboard("skilli-selftest")
            switch key {
            case .paste:
                // The footer and ⌘K say what ↩ and ⌘↩ do on it.
                let footer = context.launcher.shownFooter
                let footerSays = footer.first == "Paste Result ↩" && footer.last == "Actions ⌘K"
                await pressKey("k", flags: .maskCommand)
                let listed = await waitUntil(timeout: 1) {
                    self.context.launcher.shownActions.map { "\($0.title) \($0.key ?? "")" } == ["Paste Result ↩", "Copy Result ⌘↩"]
                } != nil
                let list = context.launcher.shownActions.map(\.title)
                await pressKey(nil, code: CGKeyCode(kVK_Escape))
                await pressKey(nil, code: CGKeyCode(kVK_Return))
                let pasted = await waitUntil(timeout: 2) { self.textView.string == expected.copy } != nil
                passed = passed && footerSays && listed && pasted
                detail += ", footer \(footer): \(footerSays), ⌘K \(list): \(listed), ↩ pasted here: \(pasted) (“\(textView.string)”)"
            case .copy, .commandC:
                if key == .copy {
                    await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
                } else {
                    await pressKey("c", flags: .maskCommand)
                }
                let copied = await waitUntil(timeout: 1) { NSPasteboard.general.string(forType: .string) == expected.copy } != nil
                let closed = await waitUntil(timeout: 1) { !self.context.launcher.isVisible } != nil
                let silent = await waitUntil(timeout: 0.6) { self.context.aiActions.popover.isVisible } == nil
                let nothingTyped = textView.string.isEmpty
                passed = passed && copied && closed && silent && nothingTyped
                detail += ", \(key == .copy ? "⌘↩" : "⌘C") copied: \(copied), closed: \(closed), nothing said: \(silent), nothing pasted: \(nothingTyped)"
            }
            await pause(300)
            await closeLauncher()
            details.append(detail)
        }
        textView.string = ""
        record(name, passed, details.joined(separator: "; "), nil)
    }

    // MARK: - Mac controls

    /// The volume set to 30 then raised by the media key (put back after);
    /// System Info reads the disk, memory and uptime; the speed test
    /// measures; the eyedropper, clicked on the test window's mint swatch,
    /// copies #3E8E7E.
    private func macControlsWork() async {
        let name = "Mac controls: volume set and raised by the media key, System Info, speed test, eyedropper on a known color"
        var details: [String] = []
        var passed = true

        if let original = SystemCommands.volume {
            _ = try? SystemCommands.setVolume(30)
            let set = await waitUntil(timeout: 1) { SystemCommands.volume == 30 } != nil
            SystemCommands.mediaKey(0)
            let raised = await waitUntil(timeout: 2) { (SystemCommands.volume ?? 0) > 30 } != nil
            _ = try? SystemCommands.setVolume(original)
            passed = passed && set && raised
            details.append("volume set to 30: \(set), raised by the key: \(raised) (back to \(original))")
        } else {
            details.append("no output volume on this Mac: volume skipped")
        }

        let info = SystemCommands.systemInfo()
        let read = info.contains("Disk:") && info.contains("Memory:") && info.contains("Up:")
        passed = passed && read
        details.append("System Info: \(info.replacingOccurrences(of: "\n", with: " | "))")

        let start = ContinuousClock.now
        let speed = (try? await SystemCommands.speedTest()) ?? "failed"
        let measured = speed.hasPrefix("↓")
        passed = passed && measured
        details.append("speed test: \(speed) in \(Int((ContinuousClock.now - start).milliseconds / 1_000)) s")

        guard await focusTestWindow() else { return }
        let picking = Task { (try? await SystemCommands.pickColor()) ?? "No color picked." }
        await pause(700)
        let swatch = window.convertToScreen(colorSwatch.convert(colorSwatch.bounds, to: nil))
        let height = NSScreen.screens.first?.frame.height ?? 0
        let point = CGPoint(x: swatch.midX, y: height - swatch.midY)
        let source = CGEventSource(stateID: .hidSystemState)
        for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(60)
        }
        let picked = await picking.value
        // The display's color space may move a channel by a step or two.
        let hex = String(picked.prefix(7))
        let channels = stride(from: 1, to: 7, by: 2).compactMap { offset -> Int? in
            guard hex.count == 7 else { return nil }
            let start = hex.index(hex.startIndex, offsetBy: offset)
            return Int(hex[start..<hex.index(start, offsetBy: 2)], radix: 16)
        }
        let close = channels.count == 3 && zip(channels, [62, 142, 126]).allSatisfy { abs($0 - $1) <= 4 }
        let copied = NSPasteboard.general.string(forType: .string) == hex
        passed = passed && close && copied
        details.append("eyedropper: “\(picked)”, close to #3E8E7E: \(close), copied: \(copied)")

        record(name, passed, details.joined(separator: "; "), nil)
    }

    // MARK: - Snippets

    /// ";sgt" typed in the test window becomes the signature with the caret
    /// at {cursor} and the clipboard as it was; "addr" inside "address"
    /// stays; the launcher finds the snippet by name and Return types it.
    private func snippetsExpandAndInsert() async {
        let name = "Snippets: “;sgt” expands with the caret at {cursor} and the clipboard kept; “addr” waits for its word to end; the launcher types one"
        let library = context.snippets
        let signature = library.save(Snippet(id: "", name: "Selftest Signature", keyword: ";sgt", text: "Bien à toi,\nCamille {cursor}!"))
        let address = library.save(Snippet(id: "", name: "Selftest Address", keyword: "addr", text: "12 rue des Lilas"))
        // As soon as it is typed, the default: whatever this Mac's settings say.
        let preferences = context.preferences
        let saved = (preferences.snippetExpansionMode, preferences.snippetExcludedApps, preferences.snippetExpansion)
        preferences.snippetExpansionMode = .immediately
        preferences.snippetExcludedApps = []
        preferences.snippetExpansion = true
        defer {
            library.delete(signature.id)
            library.delete(address.id)
            (preferences.snippetExpansionMode, preferences.snippetExcludedApps, preferences.snippetExpansion) = saved
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "Merci. "
        textView.setSelectedRange(NSRange(location: 7, length: 0))
        let sentinel = "skilli-selftest-\(UUID().uuidString)"
        setClipboard(sentinel)
        let before = context.snippetExpander.expansions
        for character in ";sgt" { await pressKey(character) }
        let expected = "Merci. Bien à toi,\nCamille !"
        let expanded = await waitUntil(timeout: 2) { self.textView.string == expected } != nil
        await pause(500)
        let caret = textView.selectedRange().location == (expected as NSString).length - 1
        let clipboardKept = NSPasteboard.general.string(forType: .string) == sentinel
        let counted = context.snippetExpander.expansions == before + 1
        let typed = textView.string.replacingOccurrences(of: "\n", with: "⏎")

        // A letter keyword inside a word does nothing; as a word, it waits
        // for the space, then keeps it.
        textView.string = ""
        for character in " address" { await pressKey(character) }
        await pause(400)
        let wordKept = textView.string == " address"
        textView.string = ""
        for character in "chez addr " { await pressKey(character) }
        let wordExpanded = await waitUntil(timeout: 2) { self.textView.string == "chez 12 rue des Lilas " } != nil
        _ = await waitUntil(timeout: 2) { !self.context.snippetExpander.isExpanding }
        let wordTyped = textView.string
        let caretAfterSpace = textView.selectedRange().location == ("chez 12 rue des Lilas " as NSString).length

        // From the launcher, by name.
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "selftest address" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "Selftest Address" } != nil
        let shownRows = context.launcher.resultTitles.prefix(3).joined(separator: ", ")
        if listed { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let inserted = await waitUntil(timeout: 2) { self.textView.string == "12 rue des Lilas" } != nil

        record(name, expanded && caret && clipboardKept && counted && wordKept && wordExpanded && caretAfterSpace && listed && inserted,
               "expanded: \(expanded) (“\(typed)”), caret at {cursor}: \(caret), clipboard kept: \(clipboardKept); “address” left alone: \(wordKept), “addr ” expanded with its space: \(wordExpanded) (“\(wordTyped)”), caret after it: \(caretAfterSpace); launcher listed: \(listed) (\(shownRows)), inserted: \(inserted)",
               nil)
    }

    /// A keyword in Safari (2026-10-16: "!!ytva" pasted the last copy
    /// in Safari and Claude, the snippet in WhatsApp): the page takes the
    /// keyword's deletes after ⌘V is sent, and a clipboard put back at the
    /// first change was what it pasted. The snippet lands, the clipboard
    /// comes back after.
    private func snippetsExpandInSafari() async {
        let name = "Snippets in Safari: “!!sftv” types the snippet, never the last copy, and the clipboard comes back"
        let bundleID = "com.apple.Safari"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no Safari", latencyMs: nil))
            return
        }
        let library = context.snippets
        let snippet = library.save(Snippet(id: "", name: "Selftest VAT", keyword: "!!sftv", text: "FR12345678901"))
        let preferences = context.preferences
        let saved = (preferences.snippetExpansionMode, preferences.snippetExcludedApps, preferences.snippetExpansion)
        preferences.snippetExpansionMode = .immediately
        preferences.snippetExcludedApps = []
        preferences.snippetExpansion = true
        let html = """
        <!doctype html><html><head><meta charset="utf-8"><title>Snippet</title></head><body>
        <textarea id="t" autofocus style="position:fixed;inset:0;width:100%;height:100%;box-sizing:border-box;font:16px -apple-system"></textarea>
        <script>const t=document.getElementById('t');t.focus();t.oninput=()=>{document.title='Snippet · '+t.value.replace(/\\n/g,'⏎')};</script>
        </body></html>
        """
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-snippet-\(getpid()).html")
        try? html.write(to: file, atomically: true, encoding: .utf8)
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        defer {
            try? FileManager.default.removeItem(at: file)
            library.delete(snippet.id)
            (preferences.snippetExpansionMode, preferences.snippetExcludedApps, preferences.snippetExpansion) = saved
        }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let opened = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration) else {
            record(name, false, "Safari did not open the page", nil)
            return
        }
        let pid = opened.processIdentifier
        // The page's title says what the field holds.
        func title() -> String {
            let app = AXUIElementCreateApplication(pid)
            AXUIElementSetMessagingTimeout(app, 0.5)
            var window: CFTypeRef?, value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &window) == .success, let window,
                  CFGetTypeID(window) == AXUIElementGetTypeID(),
                  AXUIElementCopyAttributeValue(window as! AXUIElement, kAXTitleAttribute as CFString, &value) == .success
            else { return "" }
            return value as? String ?? ""
        }
        guard await waitUntil(timeout: 10, {
            Self.makeFrontmost(pid: pid)
            return NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && title().hasPrefix("Snippet")
        }) != nil else {
            record(name, false, "the page did not come forward (title “\(title())”)", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        await pause(600)
        // A click in the text box, which fills the page: the middle of
        // Safari's window (Accessibility and events share top-left points).
        var clicked = false
        let app = AXUIElementCreateApplication(pid)
        var window: CFTypeRef?, position: CFTypeRef?, size: CFTypeRef?
        var origin = CGPoint.zero, extent = CGSize.zero
        if AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &window) == .success, let window,
           CFGetTypeID(window) == AXUIElementGetTypeID(),
           AXUIElementCopyAttributeValue(window as! AXUIElement, kAXPositionAttribute as CFString, &position) == .success, let position,
           AXValueGetValue(position as! AXValue, .cgPoint, &origin),
           AXUIElementCopyAttributeValue(window as! AXUIElement, kAXSizeAttribute as CFString, &size) == .success, let size,
           AXValueGetValue(size as! AXValue, .cgSize, &extent) {
            let point = CGPoint(x: origin.x + extent.width / 2, y: origin.y + extent.height * 0.6)
            let source = CGEventSource(stateID: .hidSystemState)
            for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
                CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
                await pause(60)
            }
            clicked = true
        }
        await pause(300)
        var results: [String] = clicked ? [] : ["no window to click in"]
        var allRight = clicked
        // Three times in a row, as tried for real.
        for round in 1...3 {
            let sentinel = "skilli-last-copy-\(round)-\(UUID().uuidString.prefix(6))"
            setClipboard(sentinel)
            for character in " tva !!sftv" { await pressKey(character) }
            // One more snippet in the field each time, the keyword gone.
            func snippets() -> Int { title().components(separatedBy: "FR12345678901").count - 1 }
            let landed = await waitUntil(timeout: 3) { snippets() == round } != nil
            _ = await waitUntil(timeout: 2) { !self.context.snippetExpander.isExpanding }
            await pause(300)
            let shown = title()
            let kept = NSPasteboard.general.string(forType: .string) == sentinel
            let leaked = shown.contains("skilli-last-copy")
            let keywordLeft = shown.contains("sftv")
            allRight = allRight && landed && kept && !leaked && !keywordLeft
            results.append("\(round): “\(shown.suffix(48))” snippet: \(landed), keyword left: \(keywordLeft), last copy pasted: \(leaked), clipboard back: \(kept)")
        }
        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
        record(name, allRight, results.joined(separator: "; "), nil)
    }

    /// Settings → Snippets → Expand, after a space or ↩: ";sgt" waits;
    /// a space expands it and stays, or goes when left out; ↩ is held back
    /// from the app and pressed again after the snippet; in an app left
    /// out, the keyword stays as typed.
    private func snippetsWaitForADelimiter() async {
        let name = "Snippets after a space or ↩: “;sgt” waits; “;sgt␣” keeps the space, left out drops it; ↩ held back then pressed after the snippet; an app left out keeps the keyword"
        let preferences = context.preferences
        let saved = (preferences.snippetExpansionMode, preferences.snippetExcludedApps, preferences.snippetExpansion)
        let library = context.snippets
        let signature = library.save(Snippet(id: "", name: "Selftest Delimiter", keyword: ";sgt", text: "Bien à toi"))
        defer {
            preferences.snippetExpansionMode = saved.0
            preferences.snippetExcludedApps = saved.1
            preferences.snippetExpansion = saved.2
            library.delete(signature.id)
        }
        preferences.snippetExpansion = true
        preferences.snippetExcludedApps = []
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        func settled() async { _ = await waitUntil(timeout: 2) { !self.context.snippetExpander.isExpanding } }

        preferences.snippetExpansionMode = .afterDelimiterKept
        textView.string = ""
        for character in "ok ;sgt" { await pressKey(character) }
        await pause(400)
        let waited = textView.string == "ok ;sgt"
        await pressKey(" ")
        let kept = await waitUntil(timeout: 2) { self.textView.string == "ok Bien à toi " } != nil
        await settled()

        preferences.snippetExpansionMode = .afterDelimiterRemoved
        textView.string = ""
        for character in "ok ;sgt " { await pressKey(character) }
        let dropped = await waitUntil(timeout: 2) { self.textView.string == "ok Bien à toi" } != nil
        await settled()

        // ↩ never reaches the field with the keyword: a chat would send it.
        preferences.snippetExpansionMode = .afterDelimiterKept
        textView.string = ""
        for character in "ok ;sgt" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let returned = await waitUntil(timeout: 2) { self.textView.string == "ok Bien à toi\n" } != nil
        await settled()
        let returnShown = textView.string.replacingOccurrences(of: "\n", with: "⏎")

        // An app left out: skil.li's own, the test window's.
        preferences.snippetExcludedApps = [Bundle.main.bundleIdentifier ?? ""]
        textView.string = ""
        for character in "ok ;sgt " { await pressKey(character) }
        await pause(500)
        let leftOut = textView.string == "ok ;sgt "

        record(name, waited && kept && dropped && returned && leftOut,
               "waited: \(waited), space kept: \(kept), left out: \(dropped), ↩ after it: \(returned) (“\(returnShown)”), app left out: \(leftOut)", nil)
    }

    /// Twelve snippets a person might keep, in memory; their ids by name.
    private func meaningSnippets() -> (SnippetLibrary, [String: String]) {
        let library = SnippetLibrary(folder: nil)
        let snippets = [
            ("IBAN perso", ";iban", "FR76 3000 6000 0112 3456 7890 189 — BIC AGRIFRPP882"),
            ("Adresse bureau", ";bur", "14 avenue de l'Opéra, 75001 Paris, 3e étage"),
            ("Adresse maison", ";mais", "12 rue des Lilas, 75011 Paris"),
            ("Signature pro", ";sig", "Jean-François Martaing\nCEO, Nimbus"),
            ("Merci rapide", ";mer", "Merci beaucoup, je regarde ça et je reviens vers toi."),
            ("Refus poli", ";non", "Merci pour la proposition, mais ce ne sera pas possible pour nous cette fois-ci."),
            ("Lien Calendly", ";cal", "https://calendly.com/camille/30min"),
            ("Numéro de TVA", ";tva", "FR 12 345678901"),
            ("Code wifi", ";wifi", "Réseau Bureau-5G, mot de passe dans 1Password"),
            ("Bio courte", ";bio", "Fondateur de Nimbus, j'aide les équipes à déployer leurs outils."),
            ("Horaires", ";hor", "Ouvert du lundi au vendredi, 9h–18h"),
            ("Date du jour", ";date", "{date}")
        ]
        var ids: [String: String] = [:]
        for (name, keyword, text) in snippets {
            ids[name] = library.save(Snippet(id: "", name: name, keyword: keyword, text: text)).id
        }
        return (library, ids)
    }

    /// The snippets a person names by what they need, decided on the
    /// user's keys: names, keywords and first words only.
    private func snippetsPickedByMeaning() async {
        let (library, ids) = meaningSnippets()
        let cases: [(String, String)] = [
            ("mon iban", ids["IBAN perso"] ?? ""),
            ("l'adresse du bureau", ids["Adresse bureau"] ?? ""),
            ("dire non poliment", ids["Refus poli"] ?? ""),
            ("my VAT number", ids["Numéro de TVA"] ?? ""),
            ("a link to book a meeting with me", ids["Lien Calendly"] ?? "")
        ]
        for provider in DecisionProvider.allCases {
            let name = "Snippets by meaning with \(provider.title): IBAN, office address, a polite no, VAT number, booking link, among 12 snippets"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var passed = true
            var details: [String] = []
            var slowest: Duration = .zero
            for (request, expected) in cases {
                let start = ContinuousClock.now
                let found = await library.searchByMeaning(request, keys: [provider: key])
                slowest = max(slowest, .now - start)
                let first = found?.snippets.first
                passed = passed && first?.id == expected
                // A maybe row is not a pick: said, never counted.
                let maybe = found?.maybe.map { " (maybe \($0.name))" } ?? ""
                details.append("“\(request)” → \(first?.name ?? "nothing")\(maybe)\(first?.id == expected ? "" : " (wrong)")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// "none" narrowly ahead, live: the "non" before an adverb Jev reads as
    /// negating it ("dire non poliment") gets the polite no as a pick or
    /// as the "maybe?" row; a request no snippet is about gets neither.
    /// Requests close to a snippet without being it are said, not judged
    /// (a maybe is what they are).
    private func snippetsMaybeByMeaning() async {
        let (library, ids) = meaningSnippets()
        let no = ids["Refus poli"]
        let polite = ["dire non poliment", "répondre non poliment", "répondre non aimablement", "dire non courtoisement"]
        let unrelated = ["mon numéro de sécu", "my passport number", "une recette de crêpes", "the tracking number of my parcel",
                         "mon numéro de carte vitale", "les conditions générales de vente", "a sorry for being late message",
                         "félicitations pour le bébé", "no idea, a joke maybe"]
        let close = ["mon numéro de SIRET", "l'adresse de ma mère", "my LinkedIn URL"]
        for provider in DecisionProvider.allCases {
            let name = "Snippets by meaning with \(provider.title): “non” before an adverb finds the polite no (a pick or a “maybe?” row), a request no snippet is about gets neither"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            // What the row shows: the first pick, else the maybe.
            func shown(_ found: (snippets: [Snippet], maybe: Snippet?, label: String)?) -> String {
                guard let found else { return "no answer" }
                return found.snippets.first?.name ?? found.maybe.map { "maybe \($0.name)" } ?? "nothing"
            }
            var passed = true
            var details: [String] = []
            for request in polite {
                let found = await library.searchByMeaning(request, keys: [provider: key])
                let right = found?.snippets.first?.id == no || found?.snippets.isEmpty == true && found?.maybe?.id == no
                passed = passed && right
                details.append("“\(request)” → \(shown(found))\(right ? "" : " (wrong)")")
            }
            for request in unrelated {
                let found = await library.searchByMeaning(request, keys: [provider: key])
                let right = found != nil && found?.snippets.isEmpty == true && found?.maybe == nil
                passed = passed && right
                details.append("“\(request)” → \(shown(found))\(right ? "" : " (wrong)")")
            }
            var said: [String] = []
            for request in close {
                let found = await library.searchByMeaning(request, keys: [provider: key])
                said.append("“\(request)” → \(shown(found))")
            }
            record(name, passed, details.joined(separator: "; ") + "; close to a snippet, said only: " + said.joined(separator: "; "), nil)
        }
    }

    /// ⇥ by meaning with "none" narrowly ahead: the snippet it split with
    /// as one dimmed "maybe?" row, never selected by itself (the footer
    /// says ↓, ↩ types nothing until ↓ selects it), the preview on it
    /// once selected, ↩ then types it; after an "Allow …" row, only the
    /// snippet's row is the maybe. The answer is given here: no key, no
    /// request.
    private func snippetsMaybeRow() async {
        let name = "Search Snippets by meaning, “none” narrowly ahead: one dimmed “maybe?” row, not selected (the footer says ↓, ↩ types nothing), ↓ selects it and the preview follows, ↩ types it"
        let library = context.snippets
        let refusal = library.save(Snippet(id: "", name: "Refus poli", keyword: ";non",
                                           text: "Merci pour la proposition, mais ce ne sera pas possible pour nous cette fois-ci."))
        let other = library.save(Snippet(id: "", name: "Adresse bureau", keyword: ";bur", text: "14 avenue de l'Opéra, 75001 Paris"))
        let launcher = context.launcher
        let preview = launcher.snippetsPreview
        let saved = (launcher.snippetMeaningAvailable, launcher.snippetMeaning)
        launcher.snippetMeaningAvailable = { true }
        launcher.snippetMeaning = { _ in ([], refusal, "Jev · 0.21 s") }
        defer {
            (launcher.snippetMeaningAvailable, launcher.snippetMeaning) = saved
            library.delete(refusal.id)
            library.delete(other.id)
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        for character in "snip " { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.isInSnippets }
        for character in "dire non poliment" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let shown = await waitUntil(timeout: 2) { launcher.isShowingSnippetMaybe && launcher.resultTitles == ["Refus poli"] } != nil
        let rows = launcher.resultTitles
        let dimmed = launcher.shownMaybeMarks == [true]
        let unselected = launcher.tableView.selectedRow == -1 && preview.shownID == nil
        let footer = launcher.shownFooter
        await captureLauncherBothWays(as: "launcher-snippets-maybe")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        await pause(300)
        let notTyped = launcher.isVisible && textView.string.isEmpty
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        let selected = await waitUntil(timeout: 1) { launcher.tableView.selectedRow == 0 && preview.shownID == refusal.id } != nil
        let footerSelected = launcher.shownFooter
        await captureLauncherBothWays(as: "launcher-snippets-maybe-selected")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let typed = await waitUntil(timeout: 2) { self.textView.string == refusal.text } != nil
        await closeLauncher()
        let hinted = footer == ["Maybe ↓"] && footerSelected.first == "Paste ↩"

        // An "Allow …" row first (a permission missing): it stays as it
        // is, selected as always; only the snippet's row is the maybe.
        let savedMissing = launcher.missingPermissions
        launcher.missingPermissions = { [.contacts] }
        defer { launcher.missingPermissions = savedMissing }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        for character in "snip " { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.isInSnippets }
        for character in "dire non poliment" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let besideAllow = await waitUntil(timeout: 2) { launcher.isShowingSnippetMaybe && launcher.resultTitles.last == "Refus poli" } != nil
        let allowRows = launcher.resultTitles
        let allowMarks = launcher.shownMaybeMarks
        let allowKept = allowMarks.count == 2 && allowMarks == [false, true] && launcher.tableView.selectedRow == 0
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        let downToMaybe = await waitUntil(timeout: 1) { launcher.tableView.selectedRow == 1 && preview.shownID == refusal.id } != nil
        await closeLauncher()
        record(name, shown && dimmed && unselected && hinted && notTyped && selected && typed && besideAllow && allowKept && downToMaybe,
               "rows \(rows): \(shown), dimmed: \(dimmed), not selected: \(unselected), footer \(footer) then \(footerSelected): \(hinted), "
               + "↩ typed nothing: \(notTyped), ↓ selected it, preview on it: \(selected), ↩ typed it: \(typed); "
               + "after an Allow row \(allowRows): \(besideAllow), marks \(allowMarks), Allow row selected as always: \(allowKept), ↓ to the maybe: \(downToMaybe); "
               + "launcher-snippets-maybe(-selected)-light/-dark.png", nil)
    }

    /// "snip " turns the launcher into Search Snippets: the list narrows
    /// beside the preview, each row the name and its keyword's keycap, the
    /// preview follows ↓; a snippet with placeholders shows as it would
    /// type now (the date filled, the clipboard filled or left as written
    /// when reading it would ask, the caret) and its information (keyword,
    /// when it expands, placeholders, alias, shortcut, size, file date);
    /// code monospaced; nothing found, the quiet tile. A name filters; what
    /// one needs then ⇥ lets the decision model pick (the user's key);
    /// Return types it in the test window; esc puts the list back whole.
    private func snippetsFoundByMeaning() async {
        let name = "Search Snippets: “snip ” opens the mode beside its preview (the snippet as it would type now, its information, ↓ follows), “adresse” filters, “mon iban” then ⇥ picks the IBAN, ↩ types it here"
        let library = context.snippets
        let ibanText = "FR76 3000 6000 0112 3456 7890 \(Int.random(in: 100...999))"
        let datedText = "Rendez-vous confirmé pour le {date}.\nCopié : {clipboard}\nÀ bientôt, {cursor}\nCamille"
        let seeded = [
            library.save(Snippet(id: "", name: "IBAN perso", keyword: ";iban", text: ibanText)),
            library.save(Snippet(id: "", name: "Adresse bureau", keyword: ";bur", text: "14 avenue de l'Opéra, 75001 Paris")),
            library.save(Snippet(id: "", name: "Refus poli", keyword: ";non", text: "Merci, mais ce ne sera pas possible cette fois-ci.")),
            library.save(Snippet(id: "", name: "Lien Calendly", keyword: ";cal", text: "https://calendly.com/camille/30min")),
            library.save(Snippet(id: "", name: "Confirmation datée", keyword: ";conf", text: datedText)),
            library.save(Snippet(id: "", name: "Garde Swift", keyword: ";gs",
                                 text: "guard let url = URL(string: address) else {\n    return nil\n}\nlet data = try Data(contentsOf: url)")),
            // Long and without a keyword: the fade, no Keyword nor Expands.
            library.save(Snippet(id: "", name: "Relance devis", keyword: "", text: (["Bonjour Margot,", ""]
                + Array(repeating: "Je me permets de revenir vers vous au sujet du devis envoyé la semaine dernière pour la refonte du site de Lumière, "
                    + "dont nous avions parlé ensemble.", count: 6) + ["", "Bien à vous,", "Camille"]).joined(separator: "\n")))
        ]
        let dated = seeded[4]
        let launcher = context.launcher
        let preferences = context.preferences
        let store = context.shortcuts
        let keys = userDecisionKeys
        let saved = (launcher.snippetMeaningAvailable, launcher.snippetMeaning)
        let savedAliases = preferences.launcherAliases
        // The self-test's own Keychain items hold no decision key: ⇥ uses
        // the user's here, as the other live checks do.
        launcher.snippetMeaningAvailable = { !keys.isEmpty }
        launcher.snippetMeaning = { request in await library.searchByMeaning(request, keys: keys) }
        // An alias and a shortcut, for the preview to say.
        preferences.launcherAliases.append(LauncherAlias(id: "snippet:\(dated.id)", alias: "rdv", title: dated.name))
        let shortcutID = store.add(.snippet(dated.id))
        // The Shortcut row is checked only if its fixture took: a refusal
        // fails the check and says why.
        var shortcutSet = false
        var shortcutRefused = ""
        do {
            try store.setKeys([Chord(parsing: "ctrl+opt+cmd+8")], for: shortcutID)
            shortcutSet = true
        } catch {
            shortcutRefused = store.lastError?.message ?? error.localizedDescription
        }
        let sentinel = "selftest-copy-\(Int.random(in: 100...999))"
        setClipboard(sentinel)
        defer {
            (launcher.snippetMeaningAvailable, launcher.snippetMeaning) = saved
            preferences.launcherAliases = savedAliases
            store.remove(shortcutID)
            for snippet in seeded { library.delete(snippet.id) }
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        for character in "snip " { await pressKey(character) }
        let mode = await waitUntil(timeout: 1) { launcher.isInSnippets } != nil
        let preview = launcher.snippetsPreview
        let listed = launcher.resultTitles.count
        let split = !preview.isHidden && launcher.tableView.frame.width < 400
        // Each row its keyword's keycap; the preview follows ↓.
        let caps = launcher.shownTrailingKeycaps.prefix(4).map { $0 ?? "none" }
        let capped = launcher.shownTrailingKeycaps.contains(";iban") && launcher.shownTrailingKeycaps.contains(";conf")
        let firstShown = preview.shownID
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        let followed = await waitUntil(timeout: 1) { preview.shownID != nil && preview.shownID != firstShown } != nil

        // As it would type now.
        for character in "confirm" { await pressKey(character) }
        let datedShown = await waitUntil(timeout: 1) { preview.shownID == dated.id } != nil
        let today = DateFormatter.localizedString(from: .now, dateStyle: .long, timeStyle: .none)
        let readable = NSPasteboard.general.accessBehavior == .alwaysAllow
        let expected = "Rendez-vous confirmé pour le \(today).\nCopié : \(readable ? sentinel : "")\nÀ bientôt, \nCamille"
        let typedRight = preview.shownTyped == expected
        let filledRight = preview.shownFilled == (readable ? [today, sentinel] : [today])
            && preview.shownUnfilled == (readable ? [] : ["{clipboard}"]) && preview.shownCaret && !preview.shownCode
        let info = Dictionary(preview.shownInfo, uniquingKeysWith: { first, _ in first })
        let expands = !preferences.snippetExpansion ? "Off" : preferences.snippetExpansionMode.title
        let informed = info["Keyword"] == ";conf" && (info["Expands"] == expands || info["Expands"]?.hasPrefix("Not in") == true)
            && info["Placeholders"] == "{date}, {clipboard}, {cursor}" && info["Alias"] == "rdv"
            && shortcutSet && info["Shortcut"] == "⌃⌥⌘8" && info["Size"]?.contains("characters") == true && info["Modified"] != nil
        let fast = preview.lastShowTime < .milliseconds(8)
        let showTime = preview.lastShowTime
        let datedDetail = "“\(preview.shownTyped.replacingOccurrences(of: "\n", with: "⏎"))”, filled \(preview.shownFilled), "
            + "unfilled \(preview.shownUnfilled), caret \(preview.shownCaret); \(preview.shownInfo.map { "\($0.0): \($0.1)" }.joined(separator: ", "))"
        // Beside the preview, a row is its name and its keyword: no alias cap.
        let nameOnly = launcher.shownTrailingKeycaps.first == ";conf" && launcher.shownAliasCaps.first == .some(nil)
        await captureLauncherBothWays(as: "launcher-snippets")
        for _ in 0..<"confirm".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }

        // Code, monospaced under its language.
        for character in "garde" { await pressKey(character) }
        let code = await waitUntil(timeout: 1) { preview.shownID == seeded[5].id && preview.shownCode } != nil
        await captureLauncherBothWays(as: "launcher-snippets-code")
        for _ in 0..<"garde".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }

        // Long, no keyword: no keycap, no Keyword nor Expands; it fades.
        for character in "relance" { await pressKey(character) }
        let long = await waitUntil(timeout: 1) { preview.shownID == seeded[6].id } != nil
            && launcher.shownTrailingKeycaps.first == .some(nil) && !preview.shownInfo.contains { $0.0 == "Keyword" || $0.0 == "Expands" }
        await captureLauncherBothWays(as: "launcher-snippets-long")
        for _ in 0..<"relance".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }

        // Nothing found: the quiet tile, no information.
        for character in "zzqxw" { await pressKey(character) }
        let quiet = await waitUntil(timeout: 1) { launcher.resultTitles.isEmpty && preview.shownID == nil && preview.shownInfo.isEmpty } != nil
        await captureLauncherBothWays(as: "launcher-snippets-empty")
        for _ in 0..<"zzqxw".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }

        for character in "adresse" { await pressKey(character) }
        let filtered = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Adresse bureau" } != nil
        let plain = await waitUntil(timeout: 1) { preview.shownID == seeded[1].id } != nil
            && preview.shownTyped == "14 avenue de l'Opéra, 75001 Paris" && preview.shownFilled.isEmpty && !preview.shownCaret
            && !preview.shownInfo.contains { $0.0 == "Placeholders" }
        for _ in 0..<"adresse".count { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }

        var meaningDetail = "no decision key: skipped"
        var meaningPassed = true
        if !keys.isEmpty {
            for character in "mon iban" { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Tab))
            let start = ContinuousClock.now
            let found = await waitUntil(timeout: 6) { launcher.isShowingSnippetMeaning && launcher.resultTitles.first == "IBAN perso" } != nil
            let seconds = (ContinuousClock.now - start).milliseconds / 1_000
            let paneFollows = await waitUntil(timeout: 1) { preview.shownID == seeded[0].id } != nil
            await captureLauncherBothWays(as: "launcher-snippets-meaning")
            if found { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
            let typed = await waitUntil(timeout: 2) { self.textView.string == ibanText } != nil
            meaningPassed = found && paneFollows && typed
            meaningDetail = "⇥ found the IBAN: \(found) in \(String(format: "%.2f", seconds)) s (\(launcher.resultTitles.first ?? "nothing")), pane on it: \(paneFollows), typed: \(typed)"
        }
        await closeLauncher()
        let whole = preview.isHidden && launcher.tableView.frame.width > 600
        let paneDetail = "split: \(split), keycaps: \(caps), ↓ followed: \(followed); dated shown: \(datedShown), name and keyword only: \(nameOnly), "
            + "typed as now: \(typedRight), clipboard readable: \(readable), filled: \(filledRight), information: \(informed) (shortcut set: \(shortcutSet)\(shortcutRefused.isEmpty ? "" : ", refused: \(shortcutRefused)")): "
            + "\(datedDetail); shown in \(showTime.compact): \(fast); code: \(code), long without a keyword: \(long), nothing found quiet: \(quiet), plain: \(plain); list whole again: \(whole)"
        record(name, mode && split && capped && followed && datedShown && nameOnly && typedRight && filledRight && informed && fast && code && long && quiet
               && filtered && plain && meaningPassed && whole,
               "mode: \(mode) (\(listed) snippets), \(paneDetail), “adresse” first: \(filtered); \(meaningDetail); "
               + "launcher-snippets(-code, -long, -empty, -meaning)-light/-dark.png", nil)
    }

    /// ✦K V pastes the newest copy, again the one before, again the one
    /// before that; a copy of the user's own starts again from it.
    private func pasteInSequenceWithKeys() async {
        let name = "Paste in Sequence: ✦K V pastes the newest copy, again the one before, again the one before that; a new copy starts again from it"
        guard let store = context.clipboard.store else {
            record(name, false, "no clipboard store", nil)
            return
        }
        let tag = Int.random(in: 1000...9999)
        let words = ["un\(tag) ", "deux\(tag) ", "trois\(tag) "]
        // The newest of the history, oldest first, a moment ago: a copy
        // made after them is newer.
        for (index, word) in words.enumerated() {
            _ = try? store.add(.init(kind: .text, text: word, app: "com.apple.TextEdit", appName: "TextEdit",
                                     hash: ClipboardHistory.hash("text", Data(word.utf8))), at: .now.addingTimeInterval(Double(index) - 3))
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = ""
        var pasted: [String] = []
        for _ in 0..<3 {
            let before = textView.string
            _ = await hyperChord(["k", "v"], trigger: Self.ownTriggerKeyCode)
            _ = await waitUntil(timeout: 2) { self.textView.string != before }
            pasted.append(String(textView.string.dropFirst(before.count)))
            await pause(150)
        }
        let inOrder = pasted == words.reversed()
        // A copy of the user's own: the next run starts from it.
        let fresh = "quatre\(tag) "
        setClipboard(fresh)
        // The history keeps it at its next look (0.4 s), when skil.li may read.
        await pause(700)
        let newest = store.search("", limit: 1).first?.text ?? ""
        let before = textView.string
        _ = await hyperChord(["k", "v"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 2) { self.textView.string != before }
        let restarted = String(textView.string.dropFirst(before.count))
        // The new copy itself, once the history kept it (skil.li may read
        // the clipboard), else the newest kept.
        let startedAgain = restarted == newest && !newest.isEmpty && (newest == fresh || !context.clipboard.mayRead)
        record(name, inOrder && startedAgain,
               "pasted \(pasted.map { "“\($0.trimmingCharacters(in: .whitespaces))”" }.joined(separator: ", ")); after a new copy: “\(restarted.trimmingCharacters(in: .whitespaces))” (newest kept: “\(newest.trimmingCharacters(in: .whitespaces))”)", nil)
    }

    /// "paste latest screenshot" in the launcher, ↩: the newest image macOS
    /// marked as a screen capture (not a newer photo) is pasted here as an
    /// image, from a scratch folder.
    private func pasteLatestScreenshot() async {
        let name = "Paste Latest Screenshot: the launcher row, ↩ pastes the newest marked screenshot (not a newer photo) here as an image"
        guard let commands = context.aiActions.systemCommands else {
            record(name, false, "no Mac commands", nil)
            return
        }
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-shots-\(getpid())", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let savedFolders = commands.screenshotFolders
        commands.screenshotFolders = { [folder] }
        defer {
            commands.screenshotFolders = savedFolders
            try? FileManager.default.removeItem(at: folder)
        }
        /// A plain PNG of `width` × `width / 2` pixels, made `age` seconds ago.
        func write(_ file: String, width: Int, age: Double, marked: Bool) {
            let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: width, pixelsHigh: width / 2, bitsPerSample: 8, samplesPerPixel: 4,
                                       hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)
            guard let rep, let png = rep.representation(using: .png, properties: [:]) else { return }
            let url = folder.appendingPathComponent(file)
            try? png.write(to: url)
            try? FileManager.default.setAttributes([.creationDate: Date.now.addingTimeInterval(-age)], ofItemAtPath: url.path)
            if marked {
                let value = (try? PropertyListSerialization.data(fromPropertyList: true, format: .binary, options: 0)) ?? Data()
                _ = value.withUnsafeBytes { setxattr(url.path, "com.apple.metadata:kMDItemIsScreenCapture", $0.baseAddress, value.count, 0, 0) }
            }
        }
        write("older.png", width: 48, age: 120, marked: true)
        write("latest.png", width: 64, age: 60, marked: true)
        write("vacances.png", width: 80, age: 5, marked: false)

        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        let wasRich = (textView.isRichText, textView.importsGraphics)
        textView.isRichText = true
        textView.importsGraphics = true
        textView.string = ""
        defer {
            textView.string = ""
            (textView.isRichText, textView.importsGraphics) = wasRich
        }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { self.context.launcher.isVisible }
        for character in "paste latest screenshot" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { self.context.launcher.topResultName == "Paste Latest Screenshot" } != nil
        let top = context.launcher.topResultName ?? "nothing"
        if listed { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        func attachment() -> Bool {
            var found = false
            textView.textStorage?.enumerateAttribute(.attachment, in: NSRange(location: 0, length: textView.textStorage?.length ?? 0)) { value, _, _ in
                if value != nil { found = true }
            }
            return found
        }
        let pasted = await waitUntil(timeout: 2) { attachment() } != nil
        let width = NSPasteboard.general.data(forType: .png).flatMap { NSBitmapImageRep(data: $0) }?.pixelsWide ?? 0
        record(name, listed && pasted && width == 64,
               "row first: \(listed) (\(top)), an image pasted: \(pasted), the one on the clipboard \(width) px wide (the latest marked: 64)", nil)
    }

    /// Settings → Snippets and Settings → Clipboard, light and dark, page
    /// by page and with Clipboard's Advanced open: each fits the window.
    private func snippetsAndClipboardPanes() async {
        let name = "Settings → Snippets and Clipboard: fit the window, light and dark, Advanced open too"
        let settings = context.settings
        var overflowing: [String] = []
        // As on a Mac with both deciding keys: the line says what leaves.
        var sample = PrivacyMap.Setup()
        sample.typeSafeKey = true
        sample.openAIKey = true
        PrivacyPane.sample = sample
        defer {
            Advanced.startsOpen = false
            PrivacyPane.sample = nil
            settings.setAppearance(nil)
            settings.close()
        }
        let preferences = context.preferences
        let mode = preferences.snippetExpansionMode
        defer { preferences.snippetExpansionMode = mode }
        // The preview after a space or ↩, left out: what waits shows.
        preferences.snippetExpansionMode = .afterDelimiterRemoved
        settings.show(pane: .general)
        await pause(150)
        settings.show(pane: .snippets)
        await pause(400)
        await captureSettingsBothWays(as: "settings-snippets-left-out")
        preferences.snippetExpansionMode = .immediately
        for (pane, advanced) in [(SettingsPane.snippets, false), (.snippets, true), (.clipboard, false), (.clipboard, true)] {
            Advanced.startsOpen = advanced
            settings.show(pane: .general)
            await pause(150)
            settings.show(pane: pane)
            await pause(400)
            let overflow = settings.paneOverflow()
            if overflow > 1 { overflowing.append("\(pane.rawValue)\(advanced ? " (advanced)" : "") +\(Int(overflow)) pt") }
            let base = "settings-\(pane.rawValue)\(advanced ? "-advanced" : "")"
            await captureSettingsBothWays(as: base)
            var page = 1
            while settings.scrollPaneOnePage(), page < 4 {
                page += 1
                await pause(200)
                await captureSettingsBothWays(as: "\(base)-\(page)")
            }
        }
        record(name, overflowing.isEmpty, overflowing.isEmpty ? "every page fits" : overflowing.joined(separator: ", "), nil)
    }

    /// Settings → Clipboard (2026-10-17: a shorter Keep copies for
    /// deleted older copies on the spot): "1 week" picked from its menu
    /// with a real click and the Custom stepper pressed delete nothing,
    /// the line under them says what goes within the hour; Custom starts
    /// from the choice before it (a week: 7 days); the hourly pass then
    /// removes them and the line goes. `settings-clipboard-retention-*.png`.
    private func clipboardRetentionWaitsForTheHour() async {
        let name = "Settings → Clipboard: a shorter Keep copies for deletes nothing at once and says what goes within the hour; Custom starts from the choice; the hourly pass removes them"
        let preferences = context.preferences
        let settings = context.settings
        let history = context.clipboard
        guard let store = history.store else {
            record(name, false, "no clipboard store", nil)
            return
        }
        let retention = preferences.clipboardRetention
        preferences.clipboardRetention = .month
        // Three copies from ten days ago: kept by a month, not by a week.
        let nineDaysAgo = Date.now.addingTimeInterval(-9 * 86_400)
        let baseline = store.count(before: nineDaysAgo)
        var seeded: [ClipboardStore.Item] = []
        for index in 1...3 {
            let text = "skilli-selftest-retention-\(index)-\(UUID().uuidString.prefix(6))"
            let new = ClipboardStore.NewItem(kind: .text, text: text, app: nil, appName: "skil.li self-test",
                                             hash: ClipboardHistory.hash("text", Data(text.utf8)))
            if let added = try? store.add(new, at: Date.now.addingTimeInterval(-10 * 86_400)) { seeded.append(added.item) }
        }
        defer {
            preferences.clipboardRetention = retention
            for item in seeded { history.delete(item) }
            settings.setAppearance(nil)
            settings.close()
        }
        func older() -> Int { store.count(before: nineDaysAgo) }
        func line() -> String? { Self.axElements(roles: [kAXStaticTextRole], where: { $0.contains(" older than ") }).first.flatMap(Self.axTitle) }
        settings.show(pane: .general)
        await pause(150)
        settings.show(pane: .clipboard)
        await pause(500)
        let noLineAtFirst = line() == nil

        // "1 week" from the menu, as a click: the binding the pane runs.
        var menu = await openMenu(titled: "Keep copies for", capture: "settings-clipboard-keep-menu.png", pick: "1 week")
        if !menu.opened { menu = await openMenu(titled: "1 month", capture: "settings-clipboard-keep-menu.png", pick: "1 week") }
        _ = await waitUntil(timeout: 2) { preferences.clipboardRetention == .week }
        await pause(300)
        let weekKept = preferences.clipboardRetention == .week && older() == baseline + seeded.count
        let weekLine = line()
        let weekSaid = seeded.count == 3 && weekLine == ClipboardRetention.week.removalLine(older: history.pendingRemoval)
        await captureSettingsBothWays(as: "settings-clipboard-retention")

        // Custom: from the week, 7 days; the stepper one day down.
        var custom = await openMenu(titled: "Keep copies for", capture: "settings-clipboard-keep-custom.png", pick: "Custom")
        if !custom.opened { custom = await openMenu(titled: "1 week", capture: "settings-clipboard-keep-custom.png", pick: "Custom") }
        _ = await waitUntil(timeout: 2) { preferences.clipboardRetention != .week }
        await pause(300)
        let customFromWeek = preferences.clipboardRetention == .days(7)
        let stepper = Self.axElements(role: kAXIncrementorRole).first
        let stepped = stepper.map { AXUIElementPerformAction($0, kAXDecrementAction as CFString) == .success } ?? false
        _ = await waitUntil(timeout: 2) { preferences.clipboardRetention == .days(6) }
        await pause(300)
        let customKept = preferences.clipboardRetention == .days(6) && older() == baseline + seeded.count
        let customLine = line()
        await captureSettingsBothWays(as: "settings-clipboard-retention-custom")

        // The hourly pass: they go, and the line with them.
        history.prune()
        let removed = await waitUntil(timeout: 2) { older() == 0 && line() == nil } != nil
        record(
            name,
            noLineAtFirst && menu.opened && weekKept && weekSaid && custom.opened && customFromWeek && stepped && customKept
                && customLine?.contains("older than 6 days") == true && removed,
            "no line on a month: \(noLineAtFirst); “1 week” picked: \(menu.opened), nothing deleted: \(weekKept) (\(older()) older than 9 days now), line: “\(weekLine ?? "none")” \(weekSaid); Custom picked: \(custom.opened), from the week: \(customFromWeek) (\(preferences.clipboardRetention.rawValue)), stepper down: \(stepped), nothing deleted: \(customKept), line: “\(customLine ?? "none")”; hourly pass removed them and the line: \(removed)",
            nil
        )
    }

    // MARK: - Windows

    /// A TextEdit window (another app: Accessibility): ✦W ← puts it on the
    /// left half, ← again soon on two thirds, then one third, then the half
    /// again; ✦W F fills the screen, F again puts it back where it was;
    /// "right half" in the launcher, Return. Then with 12 points between
    /// windows: ✦W ← and ✦W I leave the gap at the edges and between them,
    /// and ✦W N takes the quarter to the other display, the same place.
    private func windowsPlaceTheFrontWindow() async {
        let name = "Windows: ✦W ← left half, again ⅔, ⅓, ½; ✦W F fills then restores, ✦W 1 on the number row, “right half” from the launcher"
        let gapBefore = context.preferences.windowGap
        context.preferences.windowGap = 0
        defer { context.preferences.windowGap = gapBefore }
        let bundleID = "com.apple.TextEdit"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "TextEdit not installed", nil)
            return
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-window-\(getpid()).txt")
        try? "window".write(to: file, atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: file) }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let pid = (try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration))?.processIdentifier else {
            record(name, false, "could not open TextEdit", nil)
            return
        }
        await pause(300)
        Self.makeFrontmost(pid: pid)
        guard await waitUntil(timeout: 6, { NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && Self.windowFrame(pid: pid) != nil }) != nil,
              let original = Self.windowFrame(pid: pid) else {
            record(name, false, "TextEdit's window never came to front", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        // The usable area of the screen showing most of the window.
        let visible = NSScreen.screens
            .map { (frame: WindowManager.topLeft($0.frame), visible: WindowManager.topLeft($0.visibleFrame)) }
            .max { $0.frame.intersection(original).width * $0.frame.intersection(original).height
                < $1.frame.intersection(original).width * $1.frame.intersection(original).height }?.visible ?? .zero
        func expect(_ layout: WindowLayout, size: Int = 0, gap: CGFloat = 0, from current: CGRect) -> CGRect? {
            if case .frame(let frame) = layout.target(current: current, visible: visible, gap: gap, size: size) { return frame }
            return nil
        }
        func arrives(at frame: CGRect?) async -> Bool {
            guard let frame else { return false }
            return await waitUntil(timeout: 2) { Self.windowFrame(pid: pid).map { WindowLayout.matches($0, frame) } ?? false } != nil
        }
        /// ✦W, then a key: the self-test's own Hyper trigger held throughout.
        /// Returns when the key went down.
        func hyperW(_ code: CGKeyCode) async -> ContinuousClock.Instant {
            postKey(Self.ownTriggerKeyCode, down: true)
            await pause(15)
            var lastDown = ContinuousClock.now
            for key in [keyCode("w") ?? CGKeyCode(kVK_ANSI_W), code] {
                lastDown = .now
                postKey(key, down: true)
                await pause(12)
                postKey(key, down: false)
                await pause(12)
            }
            postKey(Self.ownTriggerKeyCode, down: false)
            return lastDown
        }

        guard ensureFrontmost(bundleID, before: "✦W ←") else { return }
        let pressed = await hyperW(CGKeyCode(kVK_LeftArrow))
        let half = expect(.leftHalf, from: original)
        let leftHalf = await arrives(at: half)
        let latency = leftHalf ? (ContinuousClock.now - pressed).milliseconds : nil
        // Again within a second and a half: ⅔, ⅓, then the half again.
        var sizes: [Bool] = []
        for size in [1, 2, 0] {
            guard ensureFrontmost(bundleID, before: "✦W ← again") else { return }
            _ = await hyperW(CGKeyCode(kVK_LeftArrow))
            sizes.append(await arrives(at: expect(.leftHalf, size: size, from: original)))
        }
        let twoThirds = sizes[0]
        let cycled = sizes == [true, true, true]
        guard ensureFrontmost(bundleID, before: "✦W F") else { return }
        _ = await hyperW(keyCode("f") ?? CGKeyCode(kVK_ANSI_F))
        let filled = await arrives(at: expect(.maximize, from: original))
        guard ensureFrontmost(bundleID, before: "✦W F again") else { return }
        _ = await hyperW(keyCode("f") ?? CGKeyCode(kVK_ANSI_F))
        let restored = await arrives(at: original)
        // The number row is 1 to 3 even where it types & é " alone (AZERTY);
        // typing a character still finds the key that types it.
        guard ensureFrontmost(bundleID, before: "✦W 1") else { return }
        _ = await hyperW(CGKeyCode(kVK_ANSI_1))
        let third = await arrives(at: expect(.leftThird, from: original))
        let ampersand = context.layout.keyCode(for: .character("&"))
        let typingKept = ampersand == nil || ampersand == CGKeyCode(kVK_ANSI_1)

        // From the launcher: it opens over TextEdit, which stays in front.
        guard ensureFrontmost(bundleID, before: "launcher") else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "right half" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == WindowLayout.rightHalf.title } != nil
        if listed { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let right = await arrives(at: expect(.rightHalf, from: original))
        record(name, leftHalf && twoThirds && cycled && filled && restored && third && typingKept && listed && right,
               "left half: \(leftHalf), again ⅔ → ⅓ → ½: \(sizes), filled: \(filled), restored: \(restored); ✦W 1 on the number row: \(third) (typing & kept: \(typingKept)); launcher listed “Right Half”: \(listed), moved: \(right)",
               latency)

        // Space between windows: 12 points at the edges and between two.
        let gapName = "Windows: 12 points between windows, ✦W ← and ✦W I leave them at the edges and between; ✦W N keeps the place on the other display"
        context.preferences.windowGap = 12
        // Not "again": a new press after the pause.
        await pause(1_700)
        guard ensureFrontmost(bundleID, before: "✦W ← with a gap") else { return }
        _ = await hyperW(CGKeyCode(kVK_LeftArrow))
        let gappedLeft = expect(.leftHalf, gap: 12, from: original)
        let leftWithGap = await arrives(at: gappedLeft)
        let leftFrame = Self.windowFrame(pid: pid)
        guard ensureFrontmost(bundleID, before: "✦W I with a gap") else { return }
        _ = await hyperW(keyCode("i") ?? CGKeyCode(kVK_ANSI_I))
        let gappedQuarter = expect(.topRight, gap: 12, from: original)
        let quarterWithGap = await arrives(at: gappedQuarter)
        let quarterFrame = Self.windowFrame(pid: pid)
        // Read back: the whole gap at the edges, one gap between the two.
        let edges = leftFrame.map { abs($0.minX - visible.minX - 12) <= 1 && abs($0.minY - visible.minY - 12) <= 1 } ?? false
        let between = (leftFrame.flatMap { left in quarterFrame.map { abs($0.minX - left.maxX - 12) <= 1 } }) ?? false
            && quarterFrame.map { abs(visible.maxX - $0.maxX - 12) <= 1 } ?? false
        // The other display, when there is one: the same quarter there.
        var display = "skipped: one display"
        var displayKept = true
        let screens = NSScreen.screens.map { (frame: WindowManager.topLeft($0.frame), visible: WindowManager.topLeft($0.visibleFrame)) }
        if screens.count > 1, let current = quarterFrame {
            let ordered = screens.indices.sorted { (screens[$0].frame.minX, screens[$0].frame.minY) < (screens[$1].frame.minX, screens[$1].frame.minY) }
            let here = screens.indices.max { screens[$0].frame.intersection(current).width * screens[$0].frame.intersection(current).height
                < screens[$1].frame.intersection(current).width * screens[$1].frame.intersection(current).height } ?? 0
            let next = ordered[((ordered.firstIndex(of: here) ?? 0) + 1) % ordered.count]
            guard ensureFrontmost(bundleID, before: "✦W N") else { return }
            _ = await hyperW(keyCode("n") ?? CGKeyCode(kVK_ANSI_N))
            displayKept = await arrives(at: WindowLayout.topRight.frame(in: screens[next].visible, gap: 12))
            display = "the top right quarter on the next display: \(displayKept)"
        }
        context.preferences.windowGap = 0
        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
        record(gapName, leftWithGap && quarterWithGap && edges && between && displayKept,
               "left half with the gap: \(leftWithGap) (\(leftFrame.map(Self.describe) ?? "?")), top right quarter: \(quarterWithGap) (\(quarterFrame.map(Self.describe) ?? "?")); 12 points at the edges: \(edges), between the two: \(between); \(display)",
               nil)
    }

    private static func describe(_ rect: CGRect) -> String {
        "\(Int(rect.minX)),\(Int(rect.minY)) \(Int(rect.width))×\(Int(rect.height))"
    }

    /// Arrange Windows (docs/smart-layout.md): two TextEdit windows put
    /// by hand on the left and right halves (Accessibility, not skil.li's
    /// own moves), learned as TextEdit leaves the front; moved away; then
    /// "arrange windows" in the launcher puts each back on its own half,
    /// told apart by its title and file, and Arrange again within 10 s
    /// puts both where they were.
    private func arrangeWindowsLearnsAndPutsBack() async {
        let name = "Arrange Windows: two windows of one app placed by hand are learned as it leaves the front; “arrange windows” puts each on its own half, again puts them back"
        guard let learner = context.windowLearner else {
            record(name, false, "no window learner", nil)
            return
        }
        let gapBefore = context.preferences.windowGap
        context.preferences.windowGap = 0
        defer { context.preferences.windowGap = gapBefore }
        let bundleID = "com.apple.TextEdit"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "TextEdit not installed", nil)
            return
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let marker = Int.random(in: 1000...9999)
        let files = ["alpha", "beta"].map { FileManager.default.temporaryDirectory.appendingPathComponent("skilli-arrange-\($0)-\(marker).txt") }
        for file in files { try? "arrange".write(to: file, atomically: true, encoding: .utf8) }
        defer { for file in files { try? FileManager.default.removeItem(at: file) } }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let pid = (try? await NSWorkspace.shared.open(files, withApplicationAt: appURL, configuration: configuration))?.processIdentifier else {
            record(name, false, "could not open TextEdit", nil)
            return
        }
        /// TextEdit's window showing `file`, read through Accessibility.
        func window(_ file: URL) -> AXUIElement? {
            let app = AXUIElementCreateApplication(pid)
            var value: CFTypeRef?
            guard AXUIElementCopyAttributeValue(app, kAXWindowsAttribute as CFString, &value) == .success, let list = value as? [AXUIElement] else { return nil }
            return list.first { element in
                var title: CFTypeRef?
                AXUIElementCopyAttributeValue(element, kAXTitleAttribute as CFString, &title)
                return (title as? String)?.contains(file.deletingPathExtension().lastPathComponent) == true
            }
        }
        func frame(_ element: AXUIElement) -> CGRect? {
            var position: CFTypeRef?
            var size: CFTypeRef?
            guard AXUIElementCopyAttributeValue(element, kAXPositionAttribute as CFString, &position) == .success,
                  AXUIElementCopyAttributeValue(element, kAXSizeAttribute as CFString, &size) == .success,
                  let position, let size else { return nil }
            var point = CGPoint.zero
            var extent = CGSize.zero
            AXValueGetValue(position as! AXValue, .cgPoint, &point)
            AXValueGetValue(size as! AXValue, .cgSize, &extent)
            return CGRect(origin: point, size: extent)
        }
        /// As a hand would: straight through Accessibility, not skil.li's
        /// own placing (which marks the window as moved by skil.li).
        func move(_ element: AXUIElement, to target: CGRect) {
            var origin = target.origin
            var size = target.size
            guard let originValue = AXValueCreate(.cgPoint, &origin), let sizeValue = AXValueCreate(.cgSize, &size) else { return }
            AXUIElementSetAttributeValue(element, kAXSizeAttribute as CFString, sizeValue)
            AXUIElementSetAttributeValue(element, kAXPositionAttribute as CFString, originValue)
            AXUIElementSetAttributeValue(element, kAXSizeAttribute as CFString, sizeValue)
        }
        func at(_ element: AXUIElement, _ target: CGRect) async -> Bool {
            await waitUntil(timeout: 2) { frame(element).map { WindowLayout.matches($0, target) } ?? false } != nil
        }
        /// The test's own two windows closed by their close buttons (never
        /// ⌘W: TextEdit may have the user's windows too), TextEdit quit
        /// only when the test opened it.
        func closeTestWindows() async {
            for file in files {
                guard let element = window(file) else { continue }
                var button: CFTypeRef?
                if AXUIElementCopyAttributeValue(element, kAXCloseButtonAttribute as CFString, &button) == .success, let button,
                   CFGetTypeID(button) == AXUIElementGetTypeID() {
                    AXUIElementPerformAction(unsafeDowncast(button, to: AXUIElement.self), kAXPressAction as CFString)
                }
            }
            _ = await waitUntil(timeout: 2) { files.allSatisfy { window($0) == nil } }
            if !wasRunning {
                let apps = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID)
                for app in apps { app.terminate() }
                _ = await waitUntil(timeout: 3) { apps.allSatisfy(\.isTerminated) }
            }
        }
        await pause(300)
        Self.makeFrontmost(pid: pid)
        guard await waitUntil(timeout: 6, { NSWorkspace.shared.frontmostApplication?.processIdentifier == pid && window(files[0]) != nil && window(files[1]) != nil }) != nil,
              let alpha = window(files[0]), let beta = window(files[1]), let start = frame(alpha) else {
            record(name, false, "TextEdit's two windows never came", nil)
            await closeTestWindows()
            return
        }
        // The usable area of the screen showing the first window.
        let visible = NSScreen.screens
            .map { (frame: WindowManager.topLeft($0.frame), visible: WindowManager.topLeft($0.visibleFrame)) }
            .max { $0.frame.intersection(start).width * $0.frame.intersection(start).height
                < $1.frame.intersection(start).width * $1.frame.intersection(start).height }?.visible ?? .zero
        guard let left = WindowLayout.leftHalf.frame(in: visible), let right = WindowLayout.rightHalf.frame(in: visible) else {
            record(name, false, "no left or right half in the visible area \(Self.describe(visible))", nil)
            await closeTestWindows()
            return
        }
        // Read as TextEdit came to the front: the moves from here count.
        await pause(600)
        move(alpha, to: left)
        move(beta, to: right)
        let alphaLeft = await at(alpha, left)
        let placedByHand = await at(beta, right) && alphaLeft
        /// A placement of the window showing `file` at `layout`, learned.
        func learnedAt(_ file: URL, _ layout: WindowLayout) -> Bool {
            let title = file.deletingPathExtension().lastPathComponent
            return learner.placements.entries.filter { $0.key.hasPrefix(bundleID + "\n") }.flatMap(\.value).contains {
                $0.title.contains(title) && $0.place.layout == layout.rawValue
            }
        }
        // TextEdit leaves the front: both placements learned.
        guard await focusTestWindow() else {
            await closeTestWindows()
            return
        }
        let learned = await waitUntil(timeout: 3) { learnedAt(files[0], .leftHalf) && learnedAt(files[1], .rightHalf) } != nil
        // Somewhere else, both of them.
        let away = CGRect(x: visible.minX + 80, y: visible.minY + 60, width: min(640, visible.width / 2), height: min(480, visible.height / 2))
        let awayBeta = away.offsetBy(dx: 60, dy: 40)
        move(alpha, to: away)
        move(beta, to: awayBeta)
        let alphaAway = await at(alpha, away)
        let movedAway = await at(beta, awayBeta) && alphaAway

        // From the launcher over TextEdit.
        Self.makeFrontmost(pid: pid)
        guard await waitUntil(timeout: 3, { NSWorkspace.shared.frontmostApplication?.processIdentifier == pid }) != nil else {
            record(name, false, "TextEdit did not come back in front before “arrange windows” (learned: \(learned))", nil)
            await closeTestWindows()
            return
        }
        // Lost focus: the run stops (ensureFrontmost records it); its windows still go.
        guard ensureFrontmost(bundleID, before: "arrange windows") else {
            await closeTestWindows()
            return
        }
        await pause(400)
        func arrange() async -> Bool {
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "arrange windows" { await pressKey(character) }
            let listed = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == SystemCommand.arrangeWindows.title } != nil
            await pressKey(nil, code: CGKeyCode(listed ? kVK_Return : kVK_Escape))
            return listed
        }
        let listed = await arrange()
        let alphaArranged = await at(alpha, left)
        let arranged = await at(beta, right) && alphaArranged
        let arrangedFrames = "\(frame(alpha).map(Self.describe) ?? "?"), \(frame(beta).map(Self.describe) ?? "?")"
        guard ensureFrontmost(bundleID, before: "arrange windows again") else {
            record(name, false, "TextEdit lost the front before “arrange windows” again (arranged: \(arranged))", nil)
            await closeTestWindows()
            return
        }
        let listedAgain = await arrange()
        let alphaBack = await at(alpha, away)
        let putBack = await at(beta, awayBeta) && alphaBack
        await closeTestWindows()
        record(name, placedByHand && learned && movedAway && listed && arranged && listedAgain && putBack,
               "put by hand: \(placedByHand), learned as TextEdit left the front: \(learned), moved away: \(movedAway); “arrange windows” listed: \(listed), each on its half: \(arranged) (\(arrangedFrames)); again listed: \(listedAgain), put back: \(putBack)",
               nil)
    }

    /// A TextEdit window on the left half saved as a layout from the
    /// launcher, through the editor (every other window left out, Return
    /// saves; with its display and its file), moved right, put back by
    /// picking the layout; minimized, put back; closed, its file opened
    /// again in its place. Then Switch Window brings TextEdit forward from
    /// the test window.
    private func windowLayoutsAndSwitching() async {
        let name = "Window layouts: “save layout …” opens the editor, Return saves (display, file), the layout puts a moved, minimized or closed window back; Switch Window brings TextEdit forward"
        let bundleID = "com.apple.TextEdit"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "TextEdit not installed", nil)
            return
        }
        let arranger = context.arranger
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let marker = "skilli-layout-\(Int.random(in: 1000...9999))"
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("\(marker).txt")
        try? "layout".write(to: file, atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: file) }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        _ = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration)
        func textEditWindow() -> WindowArranger.OpenWindow? { arranger.windows().first { $0.title.contains(marker) } }
        guard await waitUntil(timeout: 6, { textEditWindow() != nil }) != nil, let window = textEditWindow() else {
            record(name, false, "the TextEdit window never showed", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        let visible = NSScreen.screens.first.map { WindowManager.topLeft($0.visibleFrame) } ?? .zero
        let left = CGRect(x: visible.minX, y: visible.minY, width: (visible.width / 2).rounded(), height: visible.height)
        let right = CGRect(x: visible.minX + (visible.width / 2).rounded(), y: visible.minY, width: (visible.width / 2).rounded(), height: visible.height)
        try? WindowManager.place(window.element, of: window.appElement, at: left)
        await pause(300)

        // Saved from the launcher.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        // Synthetic keys type no capitals: the name is lowercase.
        for character in "save layout selftest layout" { await pressKey(character) }
        let offered = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "Save Window Layout “selftest layout”" } != nil
        if offered { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        defer { arranger.delete(Snippet.fileID(for: "selftest layout")) }
        // The editor shows every window taken, nothing saved yet.
        let editor = context.layoutEditor
        let reviewed = await waitUntil(timeout: 3) { editor.isKey && editor.draft?.items.contains { $0.window.title.contains(marker) } == true } != nil
        let notYet = arranger.layout(named: "selftest layout") == nil
        // Every window but the test's left out, as a person unticks them:
        // the other windows on this Mac (the user's, other people's on the
        // Mac mini) are never put back by this test.
        if let draft = editor.draft {
            for item in draft.items { draft.setIncluded(item.id, item.window.title.contains(marker)) }
        }
        if let directory = context.snapshotDirectory, let png = await editor.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("layout-editor.png"))
        }
        // Saved with Return, only when the editor has the keys.
        if reviewed, editor.isKey { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { editor.close() }
        let saved = await waitUntil(timeout: 3) { arranger.layout(named: "selftest layout") != nil && !editor.isVisible } != nil
        // Saved with its display (who it is) and its file, the rest left out.
        let layout = arranger.layout(named: "selftest layout")
        let entry = layout?.windows.first { $0.title.contains(marker) }
        let known = layout.map { !$0.displays.isEmpty && !$0.displays[0].fingerprint.uuid.isEmpty && $0.windows.count == 1 } ?? false
            && entry?.display != nil && entry?.document.flatMap { URL(string: $0) }?.lastPathComponent == file.lastPathComponent
        // Settings → Windows lists it (a picture to look at), with 8 points
        // between windows in its preview, light and dark, top and bottom.
        context.settings.show(pane: .windows)
        await pause(500)
        if let directory = context.snapshotDirectory, let png = await context.settings.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("settings-windows.png"))
        }
        if let directory = context.snapshotDirectory {
            let gap = context.preferences.windowGap
            context.preferences.windowGap = 8
            // Advanced shown, to look at what it holds.
            Advanced.startsOpen = true
            defer { Advanced.startsOpen = false }
            for dark in [false, true] {
                context.settings.show(pane: .general)
                context.settings.setAppearance(NSAppearance(named: dark ? .darkAqua : .aqua))
                await pause(150)
                context.settings.show(pane: .windows)
                await pause(400)
                if let png = await context.settings.snapshotPNG() {
                    try? png.write(to: directory.appendingPathComponent("settings-windows-\(dark ? "dark" : "light").png"))
                }
                if context.settings.scrollPaneToBottom() {
                    await pause(200)
                    if let png = await context.settings.snapshotPNG() {
                        try? png.write(to: directory.appendingPathComponent("settings-windows-\(dark ? "dark" : "light")-bottom.png"))
                    }
                }
            }
            context.settings.setAppearance(nil)
            context.preferences.windowGap = gap
        }
        await closeSettings()

        // Moved away, then put back by picking the layout.
        try? WindowManager.place(window.element, of: window.appElement, at: right)
        await pause(300)
        await pause(3_200)
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "selftest layout" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "selftest layout" } != nil
        if listed { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let back = await waitUntil(timeout: 5) { textEditWindow().map { WindowLayout.matches($0.frame, left) } ?? false } != nil

        // Out of the Dock, back in its place.
        var unminimized = false
        var reopened = false
        if let layout = arranger.layout(named: "selftest layout"), !layout.windows.isEmpty, let current = textEditWindow() {
            AXUIElementSetAttributeValue(current.element, kAXMinimizedAttribute as CFString, kCFBooleanTrue)
            _ = await waitUntil(timeout: 3) { arranger.windows(all: true).first { $0.title.contains(marker) }?.state == .minimized }
            _ = await arranger.apply(layout)
            unminimized = await waitUntil(timeout: 5) { textEditWindow().map { WindowLayout.matches($0.frame, left) } ?? false } != nil
            // Closed: its file opened again, in its place.
            if let open = textEditWindow() {
                var button: CFTypeRef?
                if AXUIElementCopyAttributeValue(open.element, kAXCloseButtonAttribute as CFString, &button) == .success, let button {
                    AXUIElementPerformAction(button as! AXUIElement, kAXPressAction as CFString)
                }
                if await waitUntil(timeout: 3, { textEditWindow() == nil }) != nil {
                    _ = await arranger.apply(layout)
                    reopened = await waitUntil(timeout: 6) { textEditWindow().map { WindowLayout.matches($0.frame, left) } ?? false } != nil
                }
            }
        }

        // Started empty, TextEdit added by hand on the main display's first
        // free half; saved with Return; applied, it brings the window back.
        editor.startEmpty(name: "selftest empty")
        defer { arranger.delete(Snippet.fileID(for: "selftest empty")) }
        let empty = await waitUntil(timeout: 3) { editor.isKey && editor.draft?.items.isEmpty == true } != nil
        editor.draft?.add(app: bundleID, name: "TextEdit")
        let addedLeft = editor.draft?.items.first.map { WindowLayout.matches($0.window.frame, left) } ?? false
        if let directory = context.snapshotDirectory, let png = await editor.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("layout-editor-empty.png"))
        }
        if empty, editor.isKey { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { editor.close() }
        var fromEmpty = false
        if await waitUntil(timeout: 3, { arranger.layout(named: "selftest empty") != nil && !editor.isVisible }) != nil,
           let made = arranger.layout(named: "selftest empty"), let open = textEditWindow() {
            try? WindowManager.place(open.element, of: open.appElement, at: right)
            _ = await arranger.apply(made)
            fromEmpty = await waitUntil(timeout: 5) { textEditWindow().map { WindowLayout.matches($0.frame, left) } ?? false } != nil
        }
        record("Window layouts: one started empty, TextEdit added by hand, puts its window back",
               empty && addedLeft && fromEmpty,
               "empty editor: \(empty), added on the free left half: \(addedLeft), saved and applied, window back on the left: \(fromEmpty)", nil)

        await displayPluggedAsks(marker: marker, left: left, right: right, window: textEditWindow)

        // Switch Window, from the test window.
        await pause(3_200)
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "switch window" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "Switch Window" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let windowsMode = await waitUntil(timeout: 1) { self.context.launcher.isInWindows } != nil
        for character in marker { await pressKey(character) }
        let found = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first?.contains(marker) == true } != nil
        if found { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let switched = await waitUntil(timeout: 3) { NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID } != nil

        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
        record(name, offered && reviewed && notYet && saved && listed && back && known && unminimized && reopened && windowsMode && found && switched,
               "save offered: \(offered), editor with the windows: \(reviewed), nothing saved before: \(notYet), saved with Return: \(saved); layout listed: \(listed), window back on the left: \(back); display and file saved: \(known), out of the Dock and back: \(unminimized), file reopened in place: \(reopened); Switch Window mode: \(windowsMode), TextEdit window found: \(found), brought forward: \(switched)",
               nil)
    }

    /// A layout that opens a file (TextEdit) and a link (Safari, a page
    /// served on this Mac), made in the editor as its + adds them, each
    /// placed on a half, saved with Return. Applied with neither open: the
    /// file and the page open and their windows take their places. Applied
    /// again: nothing opens twice.
    private func layoutOpensAFileAndALink() async {
        let name = "Window layouts: a layout opens a file and a link; their windows take their places, nothing opens twice"
        let textEdit = "com.apple.TextEdit", safari = "com.apple.Safari"
        guard NSWorkspace.shared.urlForApplication(withBundleIdentifier: textEdit) != nil,
              NSWorkspace.shared.urlForApplication(withBundleIdentifier: safari) != nil else {
            record(name, true, "skipped: TextEdit or Safari not installed", nil)
            return
        }
        let marker = "skilli-opens-\(Int.random(in: 1000...9999))"
        guard let server = LoopbackServer(handler: { _ in
            .html("<!doctype html><html><head><title>\(marker)</title></head><body><h1>skil.li layout</h1></body></html>")
        }), let port = await server.port() else {
            record(name, false, "no page served on this Mac", nil)
            return
        }
        defer { server.stop() }
        let link = "http://127.0.0.1:\(port)/\(marker)"
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("\(marker).txt")
        try? "opened by a layout".write(to: file, atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: file) }
        let textEditWasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: textEdit).isEmpty
        let safariWasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: safari).isEmpty
        let arranger = context.arranger
        func window(_ bundleID: String) -> WindowArranger.OpenWindow? {
            arranger.windows().first { $0.app.bundleIdentifier == bundleID && $0.title.contains(marker) }
        }
        func count(_ bundleID: String) -> Int {
            arranger.windows().filter { $0.app.bundleIdentifier == bundleID && $0.title.contains(marker) }.count
        }

        // Made in the editor: the file on the left half, the link on the right.
        let editor = context.layoutEditor
        editor.startEmpty(name: "selftest opens")
        defer { arranger.delete(Snippet.fileID(for: "selftest opens")) }
        let empty = await waitUntil(timeout: 3) { editor.isKey && editor.draft?.items.isEmpty == true } != nil
        if let draft = editor.draft {
            let fileItem = draft.add(opening: file.absoluteString, appID: textEdit, appName: "TextEdit")
            draft.place(fileItem, .leftHalf)
            let linkItem = draft.add(opening: link, appID: safari, appName: "Safari")
            draft.place(linkItem, .rightHalf)
            draft.selection = nil
        }
        let listed = editor.draft?.openings.count == 2
        if let directory = context.snapshotDirectory, let window = NSApp.windows.first(where: { $0.isVisible && $0.title == "New Empty Window Layout" }) {
            for dark in [false, true] {
                window.appearance = NSAppearance(named: dark ? .darkAqua : .aqua)
                await pause(250)
                if let png = await editor.snapshotPNG() {
                    try? png.write(to: directory.appendingPathComponent("layout-editor-opens-\(dark ? "dark" : "light").png"))
                }
            }
            window.appearance = nil
        }
        if empty, editor.isKey { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { editor.close() }
        let saved = await waitUntil(timeout: 3) { arranger.layout(named: "selftest opens")?.openings.count == 2 && !editor.isVisible } != nil
        guard saved, let layout = arranger.layout(named: "selftest opens"),
              let left = layout.windows.first(where: { $0.bundleID == textEdit })?.frame,
              let right = layout.windows.first(where: { $0.bundleID == safari })?.frame else {
            record(name, false, "editor empty: \(empty), both listed: \(listed), saved with both: \(saved)", nil)
            return
        }

        // Applied: the file and the page open, each in its place.
        let report = await arranger.apply(layout)
        let fileThere = await waitUntil(timeout: 6) { window(textEdit).map { WindowLayout.matches($0.frame, left) } ?? false } != nil
        let pageThere = await waitUntil(timeout: 8) { window(safari).map { WindowLayout.matches($0.frame, right) } ?? false } != nil
        let opened = (count(textEdit), count(safari))
        // Not seen: what skil.li sees of Safari, while it is still there.
        let unseen = pageThere ? "" : "; Safari as seen: \(Self.seen(bundleID: safari, name: "Safari", marker: marker))"
        // Applied again: they show already, nothing opens twice.
        _ = await arranger.apply(layout)
        await pause(800)
        let once = count(textEdit) == opened.0 && count(safari) == opened.1

        // Closed, the apps quit when they were not running before.
        for bundleID in [safari, textEdit] {
            while let open = window(bundleID) {
                var button: CFTypeRef?
                guard AXUIElementCopyAttributeValue(open.element, kAXCloseButtonAttribute as CFString, &button) == .success, let button else { break }
                AXUIElementPerformAction(button as! AXUIElement, kAXPressAction as CFString)
                guard await waitUntil(timeout: 3, { window(bundleID).map { !CFEqual($0.element, open.element) } ?? true }) != nil else { break }
            }
        }
        if !safariWasRunning { await cleanUp(bundleID: safari, wasRunning: false) }
        if !textEditWasRunning { await cleanUp(bundleID: textEdit, wasRunning: false) }
        record(name, empty && listed && fileThere && pageThere && once && report.placed == 2,
               "editor: \(empty), file and link listed: \(listed), saved; applied: \(report.placed) of 2 placed, the file on the left: \(fileThere), the page on the right: \(pageThere) (windows: TextEdit \(opened.0), Safari \(opened.1)); applied again, nothing opened twice: \(once)\(unseen)",
               nil)
    }

    /// An app's windows from three sides, to tell which one lost them:
    /// NSWorkspace by bundle ID and by name, Accessibility per process,
    /// and the window server. Titles only when they hold the test's
    /// `marker`: the report is logged in clear, other pages stay out.
    private static func seen(bundleID: String, name: String, marker: String) -> String {
        func shown(_ title: String?) -> String { title.map { $0.contains(marker) ? "“\($0)”" : "other" } ?? "untitled" }
        let byID = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID)
        let byName = NSWorkspace.shared.runningApplications.filter { $0.localizedName == name }
        var parts = ["by ID \(byID.map(\.processIdentifier)), by name \(byName.map { "\($0.processIdentifier) \($0.bundleIdentifier ?? "no ID") policy \($0.activationPolicy.rawValue)" })"]
        for app in byName {
            let element = AXUIElementCreateApplication(app.processIdentifier)
            AXUIElementSetMessagingTimeout(element, 0.5)
            var raw: CFTypeRef?
            let error = AXUIElementCopyAttributeValue(element, kAXWindowsAttribute as CFString, &raw)
            let windows = (raw as? [AXUIElement] ?? []).map { window -> String in
                var subrole: CFTypeRef?, title: CFTypeRef?
                AXUIElementCopyAttributeValue(window, kAXSubroleAttribute as CFString, &subrole)
                AXUIElementCopyAttributeValue(window, kAXTitleAttribute as CFString, &title)
                return "\(subrole as? String ?? "?") \(shown(title as? String))"
            }
            parts.append("AX \(app.processIdentifier): error \(error.rawValue), \(windows)")
        }
        let server = (CGWindowListCopyWindowInfo([.optionOnScreenOnly, .excludeDesktopElements], kCGNullWindowID) as? [[String: Any]] ?? [])
            .filter { $0[kCGWindowOwnerName as String] as? String == name && $0[kCGWindowLayer as String] as? Int == 0 }
            .map { "\($0[kCGWindowOwnerPID as String] ?? "?") \(shown($0[kCGWindowName as String] as? String))" }
        parts.append("on screen \(server)")
        return parts.joined(separator: "; ")
    }

    /// A display "plugged in" (offered as if it had just been): the layouts
    /// saved on it are asked in its middle, without the keyboard right after
    /// a key; ↓ picks, ⌘K lists the rest, esc ignores, ↩ puts the window
    /// back. Needs a display that is not the built-in one.
    private func displayPluggedAsks(marker: String, left: CGRect, right: CGRect, window: () -> WindowArranger.OpenWindow?) async {
        let name = "Display plugged in: its layouts asked in its middle; not the keyboard while typing; ↓, ⌘K, esc, ↩ puts the window back"
        let arranger = context.arranger
        let prompt = context.displayPrompt
        let displays = Displays.current()
        guard let external = displays.first(where: { !$0.fingerprint.builtIn }) else {
            record(name, true, "skipped: no display other than the built-in one", nil)
            return
        }
        // A layout with only the test's window, on every display there is.
        var made = arranger.capture("selftest plugged")
        made.windows = made.windows.filter { $0.title.contains(marker) }
        made.hiddenApps = []
        try? arranger.store(made)
        defer { arranger.delete(Snippet.fileID(for: "selftest plugged")) }
        if let open = window() { try? WindowManager.place(open.element, of: open.appElement, at: right) }
        func quiet() async { _ = await waitUntil(timeout: 3) { CGEventSource.secondsSinceLastEventType(.combinedSessionState, eventType: .keyDown) > 1.1 } }
        func ours() async -> Bool {
            for _ in 0..<6 where prompt.isKey {
                if prompt.offers.indices.contains(prompt.selected), prompt.offers[prompt.selected].layout.id == made.id { return true }
                await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
            }
            return prompt.offers.indices.contains(prompt.selected) && prompt.offers[prompt.selected].layout.id == made.id
        }

        // Right after a key: shown, the keyboard left where it is.
        guard await focusTestWindow() else { return }
        await pressKey("x")
        context.offerDisplays([external.fingerprint])
        let shownTyping = prompt.isVisible
        let keptKeyboard = !prompt.isKey
        prompt.ignoreOnce()
        textView.string = ""

        // Not typing: it takes the keyboard, in the middle of that display.
        await quiet()
        context.offerDisplays([external.fingerprint])
        let asked = await waitUntil(timeout: 2) { prompt.isVisible && prompt.isKey } != nil
        let middle = prompt.frame.map { WindowManager.bottomLeft(external.frame).contains(NSPoint(x: $0.midX, y: $0.midY)) } ?? false
        let offered = prompt.offers.contains { $0.layout.id == made.id }
        let picked = asked ? await ours() : false
        if let directory = context.snapshotDirectory, let png = await prompt.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("display-prompt.png"))
        }
        var listed = false
        if prompt.isKey {
            await pressKey("k", flags: .maskCommand)
            listed = await waitUntil(timeout: 1) { prompt.isShowingActions } != nil
            if let directory = context.snapshotDirectory, let png = await prompt.snapshotPNG() {
                try? png.write(to: directory.appendingPathComponent("display-prompt-actions.png"))
            }
            if prompt.isKey { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
            listed = listed && !prompt.isShowingActions && prompt.isVisible
        }
        let ignored = prompt.isKey ? await { () async -> Bool in
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return await waitUntil(timeout: 1) { !prompt.isVisible } != nil
        }() : false
        prompt.hide()

        // Asked again, ↩ puts the window back on the left.
        await quiet()
        context.offerDisplays([external.fingerprint])
        var back = false
        if await waitUntil(timeout: 2, { prompt.isKey }) != nil, await ours() {
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            back = await waitUntil(timeout: 5) { !prompt.isVisible && (window().map { WindowLayout.matches($0.frame, left) } ?? false) } != nil
        }
        prompt.hide()
        record(name, shownTyping && keptKeyboard && asked && middle && offered && picked && listed && ignored && back,
               "on \(external.fingerprint.name): shown while typing: \(shownTyping), keyboard left alone: \(keptKeyboard); asked with the keyboard: \(asked), in its middle: \(middle), layout offered: \(offered), picked with ↓: \(picked), ⌘K list and back: \(listed), esc ignores: \(ignored), ↩ puts the window back: \(back)",
               nil)
    }

    // MARK: - Files

    /// A command, awaited without blocking the main thread: waitUntilExit
    /// would spin a nested run loop inside this task, where a timer's
    /// MainActor.assumeIsolated crashes the Swift runtime (seen with
    /// mdimport's few seconds).
    private static func run(_ path: String, _ arguments: [String]) async {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: path)
        process.arguments = arguments
        process.standardOutput = FileHandle.nullDevice
        process.standardError = FileHandle.nullDevice
        await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
            process.terminationHandler = { _ in continuation.resume() }
            do {
                try process.run()
            } catch {
                process.terminationHandler = nil
                continuation.resume()
            }
        }
    }

    /// Files the self-test leaves in the home folder for Spotlight, indexed
    /// at once with mdimport; removed after.
    private func seedFiles(_ names: [String]) async -> URL? {
        let folder = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent("skilli-selftest-files-\(getpid())", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        for name in names {
            try? "skil.li self-test".write(to: folder.appendingPathComponent(name), atomically: true, encoding: .utf8)
        }
        await Self.run("/usr/bin/mdimport", [folder.path])
        return folder
    }

    /// Spotlight sees a name: polled, indexing takes a moment.
    private func spotlightFinds(_ name: String, timeout: Double = 20) async -> Bool {
        let deadline = ContinuousClock.now + .seconds(timeout)
        while ContinuousClock.now < deadline {
            if await FileSearch.search(name).contains(where: { $0.name == name }) { return true }
            try? await Task.sleep(for: .milliseconds(500))
        }
        return false
    }

    /// "bail" and "plage" are in no name: only what they mean finds them.
    private static let fileRequests = [("mon bail", "lease"), ("la facture d'électricité", "bill"),
                                       ("les photos de la plage cet été", "photos")]

    /// A lease, a bill and holiday photos seeded in the home folder are
    /// among what Spotlight gathers for each request. Nothing sent.
    private func filesGatheredBySpotlight() async {
        let name = "Files by meaning: Spotlight gathers a seeded lease, bill and photos among the candidates"
        let marker = Int.random(in: 1000...9999)
        let seeded = ["lease": "Contrat-location-appartement-\(marker).pdf", "bill": "Facture-EDF-octobre-\(marker).pdf",
                      "photos": "Photos-vacances-Bretagne-\(marker).zip"]
        let names = Array(seeded.values) + ["Notes-reunion-produit-\(marker).txt"]
        guard let folder = await seedFiles(names) else { return }
        defer { try? FileManager.default.removeItem(at: folder) }
        // mdimport returns at once and Spotlight takes the files one by one,
        // seconds apart: waiting for the photos alone left the lease out of
        // "mon bail" on the Mac mini.
        var indexed = true
        for file in names where indexed { indexed = await spotlightFinds(file) }
        guard indexed else {
            record(name, false, "Spotlight never indexed the files", nil)
            return
        }
        var details: [String] = []
        var passed = true
        for (request, kind) in Self.fileRequests {
            let candidates = await FileSearch.candidates(for: request)
            let found = candidates.contains { $0.name == seeded[kind] }
            passed = passed && found
            details.append("“\(request)”: \(found ? "in" : "missing") (\(candidates.count))")
        }
        record(name, passed, details.joined(separator: "; "), nil)
    }

    /// The same lease, bill and photos picked first among look-alikes from
    /// how a person asks: a fixed list (the Mac's own files can fit as
    /// well, a real lease for "mon bail"), nothing on disk. Decided only.
    private func filesPickedByMeaning() async {
        let expected = ["lease": "Contrat-location-appartement.pdf", "bill": "Facture-EDF-octobre.pdf", "photos": "Photos-vacances-Bretagne.zip"]
        let folder = URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent("Documents", isDirectory: true)
        func file(_ name: String, daysAgo: Double) -> FileSearch.File {
            let url = folder.appendingPathComponent(name)
            return FileSearch.File(url: url, name: name, kind: UTType(filenameExtension: url.pathExtension)?.localizedDescription ?? "",
                                   modified: .now.addingTimeInterval(-daysAgo * 86_400), used: nil)
        }
        let candidates = [
            file("Assurance-habitation-2026.pdf", daysAgo: 12), file("Facture-Free-box-septembre.pdf", daysAgo: 20),
            file("Devis-peinture-salon.pdf", daysAgo: 5), file(expected["lease"]!, daysAgo: 0), file("Releve-compte-septembre.pdf", daysAgo: 8),
            file("Photos-anniversaire-Lea.zip", daysAgo: 30), file(expected["bill"]!, daysAgo: 0), file("Billets-train-Rennes.pdf", daysAgo: 40),
            file("CV-2026.pdf", daysAgo: 60), file("Capture d’écran 2026-10-10 à 14.32.11.png", daysAgo: 2),
            file(expected["photos"]!, daysAgo: 0), file("Presentation-Q3.key", daysAgo: 15), file("Notes-reunion-produit.txt", daysAgo: 1)
        ]
        for provider in DecisionProvider.allCases {
            let name = "Files by meaning with \(provider.title): a lease, a bill, holiday photos in the first two among look-alikes"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var passed = true
            var details: [String] = []
            var slowest: Duration = .zero
            for (request, kind) in Self.fileRequests {
                let start = ContinuousClock.now
                let found = await FileSearch.searchByMeaning(request, keys: [provider: key], among: candidates)
                slowest = max(slowest, .now - start)
                // The list shows the likely ones best first: one of the first
                // two ("bail d'habitation" pulls the home insurance up).
                let names = found?.files.map(\.name) ?? []
                let rank = names.firstIndex { $0 == expected[kind] }
                passed = passed && (rank ?? 2) < 2
                details.append("“\(request)” → \(names.first ?? "nothing")" + (rank.map { $0 == 0 ? "" : " (expected #\($0 + 1))" } ?? " (expected missing)"))
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// "f contrat-location…" finds the file by name and ⌘Return shows it in
    /// Finder; "f mon contrat de location" ⇥ finds it by meaning.
    private func launcherFindsFiles() async {
        let name = "Search Files: “f …” finds a file by name, ⌘Return shows it in Finder; a description ⇥ finds it by meaning"
        let marker = Int.random(in: 1000...9999)
        let lease = "Contrat-location-appartement-\(marker).pdf"
        guard let folder = await seedFiles([lease, "Facture-EDF-octobre-\(marker).pdf"]) else { return }
        defer { try? FileManager.default.removeItem(at: folder) }
        guard await spotlightFinds(lease) else {
            record(name, false, "Spotlight never indexed the file", nil)
            return
        }
        let launcher = context.launcher
        let keys = userDecisionKeys
        let saved = (launcher.filesByMeaningAvailable, launcher.fileDecisionKeys)
        launcher.filesByMeaningAvailable = { !keys.isEmpty }
        launcher.fileDecisionKeys = { keys }
        defer { (launcher.filesByMeaningAvailable, launcher.fileDecisionKeys) = saved }

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "f contrat-location-appartement-\(marker)" { await pressKey(character) }
        let filesMode = await waitUntil(timeout: 1) { launcher.isInFiles } != nil
        let found = await waitUntil(timeout: 3) { launcher.resultTitles.first == lease } != nil
        if found { await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let shown = await waitUntil(timeout: 3) { NSWorkspace.shared.frontmostApplication?.bundleIdentifier == "com.apple.finder" } != nil
        if shown { await pressKey("w", flags: .maskCommand) }

        var meaningDetail = "no decision key: skipped"
        var meaningPassed = true
        if !keys.isEmpty {
            guard await focusTestWindow() else { return }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "f mon contrat de location" { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Tab))
            let byMeaning = await waitUntil(timeout: 8) { launcher.isShowingFileMeaning && launcher.resultTitles.prefix(3).contains(lease) } != nil
            await captureLauncher(as: "launcher-files-meaning.png")
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            meaningPassed = byMeaning
            meaningDetail = "by meaning: \(byMeaning) (\(launcher.resultTitles.first ?? "nothing"))"
        }
        await closeLauncher()
        record(name, filesMode && found && shown && meaningPassed,
               "Files mode: \(filesMode), found by name: \(found), shown in Finder: \(shown); \(meaningDetail)", nil)
    }

    /// Two local pages in Safari: the Tabs mode lists both; "beta" and
    /// Return bring Safari forward on that page.
    private func browserTabsAreFound() async {
        let name = "Browser tabs: Safari's two pages listed in the Tabs mode; “alpha” (the hidden one) + Return shows it"
        let bundleID = "com.apple.Safari"
        guard let safari = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "Safari not installed", nil)
            return
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let marker = Int.random(in: 1000...9999)
        let folder = FileManager.default.temporaryDirectory
        let pages = ["alpha", "beta"].map { word -> URL in
            let url = folder.appendingPathComponent("skilli-tab-\(word)-\(marker).html")
            try? "<!doctype html><title>skilli tab \(word) \(marker)</title><p>\(word)</p>".write(to: url, atomically: true, encoding: .utf8)
            return url
        }
        defer { for page in pages { try? FileManager.default.removeItem(at: page) } }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = false
        for page in pages {
            _ = try? await NSWorkspace.shared.open([page], withApplicationAt: safari, configuration: configuration)
            await pause(600)
        }
        let listedBoth = await waitUntil(timeout: 8) {
            let titles = BrowserTabs.all().map(\.title)
            return titles.contains { $0.contains("alpha \(marker)") } && titles.contains { $0.contains("beta \(marker)") }
        } != nil

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        // Beta opened last and shows: alpha is the one to switch to.
        for character in "tab alpha \(marker)" { await pressKey(character) }
        let tabsMode = await waitUntil(timeout: 1) { self.context.launcher.isInTabs } != nil
        let found = await waitUntil(timeout: 2) { self.context.launcher.resultTitles.first?.contains("alpha \(marker)") == true } != nil
        if found { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let forward = await waitUntil(timeout: 3) {
            NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID
                && BrowserTabs.all().contains { $0.title.contains("alpha \(marker)") && $0.selected }
        } != nil
        let seen = BrowserTabs.all().filter { $0.title.contains("\(marker)") }.map { "\($0.title)\($0.selected ? " ✓" : "")\($0.element == nil ? " (window)" : "")" }
        let tree = listedBoth ? "" : " tree: " + Self.roleTree(bundleID: bundleID)

        // Close what was opened.
        if !wasRunning {
            NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).forEach { $0.terminate() }
        } else {
            for _ in pages {
                if NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID { await pressKey("w", flags: .maskCommand) }
                await pause(300)
            }
        }
        record(name, listedBoth && tabsMode && found && forward,
               "both listed: \(listedBoth) (\(seen.joined(separator: ", "))); Tabs mode: \(tabsMode), alpha first: \(found), Safari forward showing it: \(forward)" + tree,
               nil)
    }

    /// The roles under a browser's front window, for a failing tabs check:
    /// "AXWindow > AXToolbar > AXTabGroup[2]…", titles of tab-like nodes only.
    private static func roleTree(bundleID: String) -> String {
        guard let app = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).first else { return "no app" }
        let element = AXUIElementCreateApplication(app.processIdentifier)
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXFocusedWindowAttribute as CFString, &value) == .success, let value else { return "no window" }
        var lines: [String] = []
        func walk(_ node: AXUIElement, _ depth: Int) {
            guard depth < 9, lines.count < 90 else { return }
            var role: CFTypeRef?, subrole: CFTypeRef?, title: CFTypeRef?, children: CFTypeRef?
            AXUIElementCopyAttributeValue(node, kAXRoleAttribute as CFString, &role)
            AXUIElementCopyAttributeValue(node, kAXSubroleAttribute as CFString, &subrole)
            AXUIElementCopyAttributeValue(node, kAXTitleAttribute as CFString, &title)
            AXUIElementCopyAttributeValue(node, kAXChildrenAttribute as CFString, &children)
            let kids = (children as? [AXUIElement]) ?? []
            let name = (title as? String).map { $0.contains("skilli") || $0.count < 20 ? " “\($0)”" : "" } ?? ""
            lines.append(String(repeating: ".", count: depth) + "\(role as? String ?? "?")/\(subrole as? String ?? "")\(name)[\(kids.count)]")
            for kid in kids.prefix(12) { walk(kid, depth + 1) }
        }
        walk(value as! AXUIElement, 0)
        return lines.joined(separator: " ")
    }

    /// Another app's front window's title, read through Accessibility.
    private static func focusedWindowTitle(pid: pid_t) -> String? {
        let app = AXUIElementCreateApplication(pid)
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &value) == .success, let value else { return nil }
        var title: CFTypeRef?
        guard AXUIElementCopyAttributeValue(value as! AXUIElement, kAXTitleAttribute as CFString, &title) == .success else { return nil }
        return title as? String
    }

    /// Another app's front window, read through Accessibility.
    private static func windowFrame(pid: pid_t) -> CGRect? {
        let app = AXUIElementCreateApplication(pid)
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute as CFString, &value) == .success, let value else { return nil }
        let window = value as! AXUIElement
        var positionValue: CFTypeRef?
        var sizeValue: CFTypeRef?
        guard AXUIElementCopyAttributeValue(window, kAXPositionAttribute as CFString, &positionValue) == .success,
              AXUIElementCopyAttributeValue(window, kAXSizeAttribute as CFString, &sizeValue) == .success,
              let positionValue, let sizeValue else { return nil }
        var position = CGPoint.zero
        var size = CGSize.zero
        AXValueGetValue(positionValue as! AXValue, .cgPoint, &position)
        AXValueGetValue(sizeValue as! AXValue, .cgSize, &size)
        return CGRect(origin: position, size: size)
    }

    /// System Settings' panes read from this Mac's Settings extensions:
    /// names a person reads, Displays holding Night Shift, each with a link
    /// that opens it.
    private func systemSettingsPanesRead() {
        let name = "System Settings: its panes read on this Mac, in the user's languages, with what each holds"
        let start = ContinuousClock.now
        let panes = SystemSettingsPanes.all()
        let took = ContinuousClock.now - start
        let displays = panes.first { $0.id == "com.apple.Displays-Settings.extension" }
        let unreadable = panes.filter { !SystemSettingsPane.isReadable($0.name) }.map(\.name)
        let unlinked = panes.filter { $0.url == nil }.map(\.name)
        let named = Set(panes.map(\.name)).count == panes.count
        let passed = panes.count >= 35 && displays?.sections.contains(where: { $0.hasPrefix("Night Shift") }) == true && unreadable.isEmpty && unlinked.isEmpty && named
        let shown = displays.map { "\($0.name) / \($0.otherNames.joined(separator: ", ")), \($0.sections.count) sections" } ?? "missing"
        record(name, passed, "\(panes.count) panes (\(panes.map(\.name).joined(separator: ", "))); Displays: \(shown); "
               + "unreadable \(unreadable), no link \(unlinked), names unique \(named), in \(took.compact)", took.milliseconds)
    }

    /// A pane's name typed whole finds it first, before rows the words only
    /// describe (`LauncherRank`): "display" before Move to Next Display,
    /// whose keyword it is; "wifi" before Turn Wi-Fi Off. "night shift" by
    /// what it holds. "réglages bluetooth" and "bluetooth settings" ask for
    /// the pane: first, Allow Bluetooth next while macOS has not asked.
    /// Return opens System Settings on it; a stray word finds no pane.
    private func launcherOpensSettingsPanes() async {
        let name = "Launcher: a pane's name typed whole finds it first (“displays”, “display”, “wifi”, “wi-fi”), “night shift” too, “réglages bluetooth” before Allow Bluetooth; Return opens it there"
        let launcher = context.launcher
        let settingsID = "com.apple.systempreferences"
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).isEmpty
        guard let displays = SystemSettingsPanes.pane(id: "com.apple.Displays-Settings.extension") else {
            record(name, false, "no Displays pane read", nil)
            return
        }
        let names = Set([displays.name] + displays.otherNames)
        // Allow Bluetooth is offered while macOS has not asked (the mini).
        let offersBluetooth = BluetoothDevices.authorization == .notDetermined
        var cases = [("displays", displays.name), ("display", displays.name), ("night shift", displays.name),
                     ("réglages bluetooth", "Bluetooth"), ("bluetooth settings", "Bluetooth")]
        if let wifi = SystemSettingsPanes.pane(id: "com.apple.wifi-settings-extension") {
            cases.append(("wifi", wifi.name))
            // Typed with a plain hyphen; the pane's name has a non-breaking one.
            cases.append(("wi-fi", wifi.name))
        }
        var details: [String] = []
        var passed = true
        for (query, expected) in cases {
            guard await focusTestWindow() else { return }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            guard await waitUntil(timeout: 1, { launcher.isVisible }) != nil else {
                record(name, false, "launcher did not open", nil)
                return
            }
            for character in query { await pressKey(character) }
            let offer = offersBluetooth && query.contains("bluetooth")
            let found = await waitUntil(timeout: 1) {
                launcher.resultTitles.first == expected
                    && (!offer || launcher.resultTitles.dropFirst().first?.hasPrefix("Allow Bluetooth") == true)
            } != nil
            if query == "night shift" { await captureLauncher(as: "launcher-settings-pane.png") }
            if query == "réglages bluetooth" { await captureLauncher(as: "launcher-settings-pane-asked.png") }
            details.append("“\(query)” → \(launcher.resultTitles.prefix(3).joined(separator: ", "))\(found ? "" : " ✗")")
            passed = passed && found
            if query == "displays", found {
                await pressKey(nil, code: CGKeyCode(kVK_Return))
                let opened = await waitUntil(timeout: 5) {
                    guard let app = NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).first else { return false }
                    return Self.focusedWindowTitle(pid: app.processIdentifier).map(names.contains) == true
                } != nil
                let title = NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).first
                    .flatMap { Self.focusedWindowTitle(pid: $0.processIdentifier) } ?? "no window"
                details.append("Return: System Settings on “\(title)”")
                passed = passed && opened
            } else {
                await pressKey(nil, code: CGKeyCode(kVK_Escape))
            }
        }
        // A word no pane holds lists none ("slack" scattered over sections).
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 1) { launcher.isVisible }
        for character in "slack" { await pressKey(character) }
        await pause(150)
        let paneNames = Set(SystemSettingsPanes.all().map(\.name))
        let stray = launcher.resultTitles.filter(paneNames.contains)
        details.append("“slack” → no pane: \(stray.isEmpty ? "yes" : "no, \(stray)")")
        passed = passed && stray.isEmpty
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        if !wasRunning {
            NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).forEach { $0.terminate() }
        }
        record(name, passed, details.joined(separator: "; "), nil)
    }

    /// A shortcut set on a pane (Keys → Add Shortcut → System Settings)
    /// is listed by the pane's name and opens Settings there.
    private func shortcutOpensSettingsPane() async {
        let name = "Keys: a shortcut set on System Settings' Displays pane (✦Y) opens Settings there"
        guard let displays = SystemSettingsPanes.pane(id: "com.apple.Displays-Settings.extension") else {
            record(name, false, "no Displays pane read", nil)
            return
        }
        let settingsID = "com.apple.systempreferences"
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).isEmpty
        let store = context.shortcuts
        let action = SkilliAction.mac(.settings(displays))
        let offered = ActionCatalog.settingsPanes().contains(action)
        let id = store.add(action)
        defer {
            store.remove(id)
            if !wasRunning { NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).forEach { $0.terminate() } }
        }
        guard await focusRecorder() else { return }
        store.beginRecording(id)
        _ = await hyperChord(["y"], trigger: Self.ownTriggerKeyCode)
        _ = await waitUntil(timeout: 3) { store.recordingID == nil }
        let saved = keys(id)
        guard await focusRecorder() else { return }
        _ = await hyperChord(["y"], trigger: Self.ownTriggerKeyCode)
        let names = Set([displays.name] + displays.otherNames)
        let opened = await waitUntil(timeout: 5) {
            guard let app = NSRunningApplication.runningApplications(withBundleIdentifier: settingsID).first else { return false }
            return Self.focusedWindowTitle(pid: app.processIdentifier).map(names.contains) == true
        } != nil
        record(name, offered && saved == "hyper+y" && opened && action.title == "System Settings · \(displays.name)",
               "offered in Add Shortcut: \(offered), listed as “\(action.title)”, saved: \(saved ?? "none"), opened Settings on it: \(opened)", nil)
    }

    /// Ask picks the pane named or described, and still opens System
    /// Settings itself or runs a Mac command when that is asked (decided
    /// only, nothing opened).
    private func askOpensSystemSettings() async {
        let entries = await Task.detached { AppScanner.scan().map { ($0.name, $0.url) } }.value
        let apps = await Task.detached { AppCandidates.apps(entries) }.value
        let panes = SystemSettingsPanes.all()
        func pane(_ id: String) -> MacAction? { panes.first { $0.id == id }.map(MacAction.settings) }
        let displays = pane("com.apple.Displays-Settings.extension")
        let cases: [(String, AskRoute, MacAction?)] = [
            ("Ouvre les réglages système dans la partie display", .command, displays),
            ("go to the display settings", .command, displays),
            ("va dans les réglages du clavier", .command, pane("com.apple.Keyboard-Settings.extension")),
            ("ouvre les réglages bluetooth", .command, pane("com.apple.BluetoothSettings")),
            ("open the wifi settings", .command, pane("com.apple.wifi-settings-extension")),
            ("où je règle night shift", .command, displays),
            ("ouvre les réglages système", .open, nil),
            ("passe en mode sombre", .command, .system(.toggleDarkMode))
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask opens System Settings on the pane asked for with \(provider.title) (decided only, nothing opened)"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = !panes.isEmpty && displays != nil
            var slowest: Duration = .zero
            for (instruction, route, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: apps,
                                                      settings: panes, keys: [provider: key])
                slowest = max(slowest, .now - start)
                let picked = decision?.command.map { "\($0.command.title) \(Int($0.probability * 100))%" }
                    ?? decision?.apps.first.map { "app \($0.app.name)" } ?? ""
                let right = decision?.route == route && (route == .open
                    ? decision?.apps.first?.app.url.lastPathComponent == "System Settings.app"
                    : decision?.command?.command == expected)
                passed = passed && right
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(picked)\(right ? "" : " ✗")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// French requests pick the Mac command or the window's place (decided
    /// only, nothing run).
    private func askRunsMacCommands() async {
        let cases: [(String, MacAction)] = [
