    /// Ask's calendar and reminders read by the model, never a regex: the
    /// route, then what is asked and every value, put together in code
    /// (`AskValues.plan`); decided only, nothing added.
    private func askReadsPlans() async {
        let calendar = Calendar.current
        let now = Date.now
        let today = calendar.startOfDay(for: now)
        func day(_ offset: Int, _ hour: Int = 0, _ minute: Int = 0) -> Date {
            let date = calendar.date(byAdding: .day, value: offset, to: today) ?? today
            return calendar.date(bySettingHour: hour, minute: minute, second: 0, of: date) ?? date
        }
        // The coming Thursday (today's while 14:00 is still ahead).
        let thursdayAhead = (5 - calendar.component(.weekday, from: today) + 7) % 7
        let thursday = thursdayAhead == 0 && day(0, 14) <= now ? 7 : thursdayAhead
        func titled(_ plan: AskValues.Plan, _ words: String) -> Bool {
            switch plan {
            case .reminder(let request, _): request.title.localizedCaseInsensitiveContains(words)
            case .event(let request, _): request.title.localizedCaseInsensitiveContains(words)
            default: false
            }
        }
        let cases: [(String, (AskValues.Plan) -> Bool)] = [
            ("rappelle-moi d'appeler Paul demain à 9h", { plan in
                if case .reminder(let request, _) = plan { return titled(plan, "appeler Paul") && request.due == day(1, 9) && request.hasTime }
                return false }),
            ("rappelle-moi dans une heure trente de sortir le linge", { plan in
                if case .reminder(let request, _) = plan { return titled(plan, "sortir le linge") && abs((request.due ?? .distantPast).timeIntervalSince(now) - 5_400) < 180 }
                return false }),
            ("remind me to buy bread tomorrow morning", { plan in
                if case .reminder(let request, _) = plan { return titled(plan, "buy bread") && request.due == day(1, 9) }
                return false }),
            ("n'oublie pas de payer le loyer le 5 de chaque mois", { plan in
                if case .reminder(let request, _) = plan {
                    return titled(plan, "payer le loyer") && request.due.map { calendar.component(.day, from: $0) == 5 } == true
                        && request.recurrence?.frequency == .monthly
                }
                return false }),
            ("rappelle-moi d'acheter du pain en partant du bureau", { plan in
                if case .reminder(let request, _) = plan { return titled(plan, "acheter du pain") && request.place == ReminderPlace(name: "bureau", arriving: false) }
                return false }),
            ("crée un rdv demain à 14h avec Paul", { plan in
                if case .event(let request, _) = plan { return request.start == day(1, 14) && request.end == day(1, 15) }
                return false }),
            ("bloque 2h demain matin pour écrire", { plan in
                if case .event(let request, _) = plan { return titled(plan, "écrire") && request.start == day(1, 9) && request.end == day(1, 11) }
                return false }),
            ("réunion budget jeudi de 14h à 15h30", { plan in
                if case .event(let request, _) = plan { return request.start == day(thursday, 14) && request.end == day(thursday, 15, 30) }
                return false }),
            ("qu'est-ce que j'ai demain ?", { $0 == .agenda(.day(offset: 1)) }),
            ("rejoins la réunion", { $0 == .agenda(.next(join: true)) }),
            ("suis-je libre jeudi après-midi ?", { $0 == .agenda(.free(from: max(day(thursday, 12), min(now, day(thursday, 18))), to: day(thursday, 18))) }),
            ("mes rappels", { $0 == .reminders(.today) }),
            ("mets un minuteur de 10 minutes", { _ in false })
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask reads calendar and reminders with \(provider.title), never a regex: reminders (when, a delay, every month, a place), events (a length, an end), a day, join, free, to-dos; a timer is not one"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            let keys = [provider: key]
            var details: [String] = []
            var right = 0
            var slowest: Duration = .zero
            for (sentence, wanted) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(sentence, hasSelection: false, app: "Finder", menu: [], apps: [], keys: keys)
                var got = decision?.route.rawValue ?? "failed"
                var ok = false
                if decision?.route == .plans {
                    let words = AskValues.words(of: sentence)
                    let lists = ["Courses", "Travail"], calendars = ["Perso", "Pro"]
                    let answers = await AskRouter.values(AskValues.planQuestions(words: words, lists: lists, calendars: calendars),
                                                         instruction: sentence, keys: keys) ?? [:]
                    let plan = AskValues.plan(answers, words: words, lists: lists, calendars: calendars, now: now)
                    ok = wanted(plan)
                    let unsure = answers.filter { $0.value.confidence < AskValues.sureFrom && $0.value.choice != "none" }
                        .sorted { $0.key < $1.key }.map { "\($0.key) \($0.value.choice) \(Int($0.value.confidence * 100))%" }
                    got += " → \(Self.said(plan))" + (unsure.isEmpty ? "" : " [unsure: \(unsure.joined(separator: ", "))]")
                } else {
                    ok = sentence.hasPrefix("mets un minuteur") && decision?.route == .timer
                }
                slowest = max(slowest, .now - start)
                if ok { right += 1 }
                details.append("\(ok ? "✓" : "✗") “\(sentence)” → \(got)")
            }
            record(name, right == cases.count, "\(right)/\(cases.count): " + details.joined(separator: "; ") + "; slowest \(Int(slowest.milliseconds)) ms",
                   slowest.milliseconds)
        }
    }

    /// Ask about a contact read by the model: who, or a mail (and whether
    /// it says what to write), the person in the request's own words; the
    /// sentences the regex it replaces was tested with. Decided only.
    private func askReadsContacts() async {
        let cases: [(String, AskValues.ContactAsk)] = [
            ("qui est le contact Jean-François qui travaille chez Lumière ?", .who(person: "Jean-François")),
            ("c'est qui Paul Durand", .who(person: "Paul Durand")),
            ("le numéro de François Leroy", .who(person: "François Leroy")),
            ("who is Jean at Lumière", .who(person: "Jean")),
            ("crée un mail à françois de chez horizon", .mail(person: "françois", says: false)),
            ("écris à Paul pour lui dire que la réunion est décalée", .mail(person: "Paul", says: true)),
            ("envoie un mail à Marie : on se voit demain", .mail(person: "Marie", says: true)),
            ("Écris un nouveau mail pour François de chez Horizon, l'objet c'est un nouveau contrat.", .mail(person: "François", says: true)),
            ("email to Anna with the subject Q4 budget", .mail(person: "Anna", says: true))
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask reads who and what about a contact with \(provider.title), never a regex: who they are, a mail, whether it says what to write"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            let keys = [provider: key]
            var details: [String] = []
            var right = 0
            var slowest: Duration = .zero
            for (sentence, wanted) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(sentence, hasSelection: false, app: "Finder", menu: [], apps: [], keys: keys)
                var got = decision?.route.rawValue ?? "failed"
                var ok = false
                if decision?.route == .contact {
                    let words = AskValues.words(of: sentence)
                    let answers = await AskRouter.values(AskValues.contactQuestions(words: words), instruction: sentence, keys: keys) ?? [:]
                    let read = AskValues.contact(answers, words: words)
                    got += " → \(read)"
                    // The person's words found, whatever else came with them.
                    switch (read, wanted) {
                    case (.who(let person), .who(let named)): ok = person.localizedCaseInsensitiveContains(named)
                    case (.mail(let person, let says), .mail(let named, let said)): ok = person.localizedCaseInsensitiveContains(named) && says == said
                    default: ok = false
                    }
                }
                slowest = max(slowest, .now - start)
                if ok { right += 1 }
                details.append("\(ok ? "✓" : "✗") “\(sentence)” → \(got)")
            }
            record(name, right == cases.count, "\(right)/\(cases.count): " + details.joined(separator: "; ") + "; slowest \(Int(slowest.milliseconds)) ms",
                   slowest.milliseconds)
        }
    }

    /// Asks on a schedule and apps named, read by the model, never a regex:
    /// how often, when and what to do; a repeating reminder is not one;
    /// quit, force quit, uninstall and the app's name. Decided only.
    private func askReadsSchedulesAndApps() async {
        enum Want { case schedule(String, String), plans, app(AskRouter.AppAction, String) }
        let cases: [(String, Want)] = [
            ("tous les lundis à 9h résume mes PR", .schedule("Every Monday at 9:00", "résume mes PR")),
            ("every weekday at 8:30 tell me my day", .schedule("Every weekday at 8:30", "tell me my day")),
            ("le 1er de chaque mois à 9h envoie-moi le point", .schedule("Every month on the 1st at 9:00", "envoie-moi le point")),
            ("est-ce que tu pourrais me faire un résumé de mes mails chaque soir", .schedule("Every day at 19:00", "résumé de mes mails")),
            ("rappelle-moi tous les lundis de sortir les poubelles", .plans),
            ("kill creative cloud", .app(.quit, "creative cloud")),
            ("quitte de force Teams", .app(.forceQuit, "Teams")),
            ("désinstalle Slack", .app(.uninstall, "Slack"))
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask reads schedules and apps with \(provider.title), never a regex: how often, when, what to do; a repeating reminder is not one; quit, force quit, uninstall what it names"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            let keys = [provider: key]
            var details: [String] = []
            var right = 0
            var slowest: Duration = .zero
            for (sentence, wanted) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(sentence, hasSelection: false, app: "Finder", menu: [], apps: [], keys: keys)
                var got = (decision?.route.rawValue ?? "failed") + (decision?.appAction.map { " \($0.rawValue)" } ?? "")
                var ok = false
                let words = AskValues.words(of: sentence)
                switch wanted {
                case .schedule(let spoken, let ask):
                    if decision?.route == .schedule {
                        let answers = await AskRouter.values(AskValues.scheduleQuestions(words: words), instruction: sentence, keys: keys) ?? [:]
                        let read = AskValues.schedule(answers, words: words)
                        got += " → \(read)"
                        if case .schedule(let schedule, let what) = read {
                            ok = schedule.spoken == spoken && what.localizedCaseInsensitiveContains(ask)
                        }
                    }
                case .plans:
                    if decision?.route == .plans {
                        ok = true
                    } else if decision?.route == .schedule {
                        let answers = await AskRouter.values(AskValues.scheduleQuestions(words: words), instruction: sentence, keys: keys) ?? [:]
                        ok = AskValues.schedule(answers, words: words) == .plans
                        got += ok ? " → plans" : ""
                    }
                case .app(let action, let target):
                    if decision?.route == .command, decision?.appAction == action {
                        let answers = await AskRouter.values(AskValues.targetQuestions(words: words), instruction: sentence, keys: keys) ?? [:]
                        let named = AskValues.target(answers, words: words)
                        got += " → “\(named ?? "")”"
                        ok = named?.localizedCaseInsensitiveCompare(target) == .orderedSame
                    }
                }
                slowest = max(slowest, .now - start)
                if ok { right += 1 }
                details.append("\(ok ? "✓" : "✗") “\(sentence)” → \(got)")
            }
            record(name, right == cases.count, "\(right)/\(cases.count): " + details.joined(separator: "; ") + "; slowest \(Int(slowest.milliseconds)) ms",
                   slowest.milliseconds)
        }
    }

    /// A plan said in a line, for the report.
    private static func said(_ plan: AskValues.Plan) -> String {
        let format = { (date: Date?) in date?.formatted(date: .abbreviated, time: .shortened) ?? "no date" }
        switch plan {
        case .reminder(let request, let sure):
            return "reminder “\(request.title)” \(format(request.due))\(request.recurrence.map { " " + $0.spoken } ?? "")"
                + "\(request.place.map { " \($0.arriving ? "arriving" : "leaving") \($0.name)" } ?? "") \(Int(sure * 100))%"
        case .event(let request, let sure):
            return "event “\(request.title)” \(format(request.start))–\(request.end.formatted(date: .omitted, time: .shortened)) \(Int(sure * 100))%"
        case .agenda(let request): return "agenda \(request)"
        case .reminders(let request): return "reminders \(request)"
        case .missing(let missing): return "missing: \(missing.question)"
        }
    }

    /// Ask's values read by the model, never a regex (2026-10-16: "une
    /// heure trente" kept the Mac awake one hour; "rappelle-moi dans 1h et
    /// quart…" started a timer): each sentence routed for real, then its
    /// value read and put together (`AskValues`), decided only, nothing run.
    /// An answer typed in the card for a value the request did not give,
    /// read alone by each real model, as the request would be: a length,
    /// a level, an app's name, a day and a time. Four small requests each.
    private func askReadsAnswersInTheCard() async {
        let now = Date.now
        let calendar = Calendar.current
        let tomorrowAtNine = calendar.date(bySettingHour: 9, minute: 0, second: 0,
                                           of: calendar.date(byAdding: .day, value: 1, to: calendar.startOfDay(for: now)) ?? now)
        let cases: [(reply: String, missing: AskValues.Missing, wanted: String)] = [
            ("une heure trente", .length, "1 h 30"),
            ("trente pour cent", .level, "30 %"),
            ("Creative Cloud", .app, "Creative Cloud"),
            ("demain à 9h", .reminderWhen, tomorrowAtNine.map { $0.formatted(date: .abbreviated, time: .shortened) } ?? "")
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask reads an answer typed in the card alone with \(provider.title): a length, a level, an app's name, a day and a time"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var right = 0
            var slowest: Duration = .zero
            for (reply, missing, wanted) in cases {
                let start = ContinuousClock.now
                let read = await AskRouter.values(missing.questions(reply: reply), instruction: reply, keys: [provider: key]) ?? [:]
                slowest = max(slowest, .now - start)
                let answers = missing.answers(read, reply: reply)
                let got: String = switch missing.value {
                case .length: AskValues.duration(answers, now: now).map { TimerRequest.spoken($0.seconds) } ?? "nothing"
                case .level: AskValues.level(answers).map { "\($0.level) %" } ?? "nothing"
                case .app: answers["target"]?.said ?? "nothing"
                default: AskValues.when(answers, now: now)?.date.map { $0.formatted(date: .abbreviated, time: .shortened) } ?? "nothing"
                }
                let ok = got == wanted
                if ok { right += 1 }
                details.append("\(ok ? "✓" : "✗") “\(reply)” → \(got)")
            }
            record(name, right == cases.count, "\(right)/\(cases.count): " + details.joined(separator: "; ") + "; slowest \(Int(slowest.milliseconds)) ms",
                   slowest.milliseconds)
        }
    }

    private func askReadsValues() async {
        enum Want { case awake(Int?), timer(Int, String?), volume(Int), notTimer }
        var calendar = Calendar.current
        calendar.timeZone = .current
        let now = Date.now
        func until(_ hour: Int, _ minute: Int) -> Int {
            let today = calendar.date(bySettingHour: hour, minute: minute, second: 0, of: now) ?? now
            let end = today > now ? today : calendar.date(byAdding: .day, value: 1, to: today) ?? today
            return Int(end.timeIntervalSince(now).rounded())
        }
        let cases: [(String, Want)] = [
            ("Maintiens mon ordinateur allumé pour une heure.", .awake(3_600)),
            ("garde mon ordi hors veille pendant une heure trente", .awake(5_400)),
            ("keep my mac awake for an hour and a half", .awake(5_400)),
            ("garde le mac éveillé 1h et quart", .awake(4_500)),
            ("pas de veille jusqu'à 18h30", .awake(until(18, 30))),
            ("keep the mac awake", .awake(nil)),
            ("mets un minuteur de dix minutes pour les pâtes", .timer(600, "pâtes")),
            ("timer for an hour and a half", .timer(5_400, nil)),
            ("minuteur 1h et quart pour le four", .timer(4_500, "four")),
            ("préviens-moi dans 20 minutes", .timer(1_200, nil)),
            ("préviens-moi dans un quart d'heure", .timer(900, nil)),
            ("minuteur de 45 secondes", .timer(45, nil)),
            ("garde le mac allumé deux heures", .awake(7_200)),
            ("mets le son à trente pour cent", .volume(30)),
            ("baisse le son à 20", .volume(20)),
            ("rappelle-moi dans 1h et quart d'appeler Paul", .notTimer)
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask reads its values with \(provider.title), never a regex, in the route's own request: keep awake for a length or until a time, timers and what for, a volume level; a reminder is not a timer"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            let keys = [provider: key]
            var details: [String] = []
            var right = 0
            var slowest: Duration = .zero
            for (sentence, want) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(sentence, hasSelection: false, app: "Finder", menu: [], apps: [], keys: keys)
                var got = decision.map { "\($0.route.rawValue) \($0.command?.command.title ?? "")" } ?? "failed"
                var ok = false
                switch want {
                case .awake(let seconds):
                    if decision?.route == .command, decision?.command?.command == .system(.keepAwake) {
                        // Read with the route, in the same request (D8).
                        let read = decision.flatMap { AskValues.duration($0.values, now: now) }
                        got += " → \(read.map { "\(TimerRequest.spoken($0.seconds)) \(Int($0.confidence * 100))%" } ?? "until stopped")"
                        ok = seconds.map { wanted in read.map { abs($0.seconds - wanted) <= 90 } ?? false } ?? (read == nil)
                    }
                case .timer(let seconds, let label):
                    if decision?.route == .timer {
                        let spans = AskValues.spans(of: sentence)
                        let answers = decision?.values ?? [:]
                        let read = AskValues.duration(answers, now: now)
                        let named = AskValues.label(answers, spans: spans)
                        got += " → \(read.map { "\(TimerRequest.spoken($0.seconds)) \(Int($0.confidence * 100))%" } ?? "no length") “\(named ?? "")”"
                        ok = read?.seconds == seconds && (label.map { named?.localizedCaseInsensitiveContains($0) == true } ?? true)
                    }
                case .volume(let level):
                    if decision?.route == .command, case .volume(AskRouter.levelToRead)? = decision?.command?.command {
                        let read = decision.flatMap { AskValues.level($0.values) }
                        got += " → \(read.map { "\($0.level) % \(Int($0.confidence * 100))%" } ?? "no level")"
                        ok = read?.level == level
                    }
                case .notTimer:
                    ok = decision != nil && decision?.route != .timer
                }
                slowest = max(slowest, .now - start)
                if ok { right += 1 }
                details.append("\(ok ? "✓" : "✗") “\(sentence)” → \(got)")
            }
            record(name, right == cases.count, "\(right)/\(cases.count): " + details.joined(separator: "; ") + "; slowest \(Int(slowest.milliseconds)) ms",
                   slowest.milliseconds)
        }
    }

    /// The new Mac commands said in French, decided only (nothing run):
    /// Bluetooth devices from a stand-in list (the mini's own are not
    /// connected), Wi-Fi off, the desktop; the volume at a level read
    /// without a model.
    private func askRunsNewMacCommands() async {
        let airpods = BluetoothTarget(address: "a4-83-e7-00-00-01", name: "AirPods Pro de Camille", kind: .headphones)
        let keyboard = BluetoothTarget(address: "a4-83-e7-00-00-02", name: "Magic Keyboard", kind: .keyboard)
        let bluetooth: [MacAction] = [.bluetooth(airpods, connect: true), .bluetooth(keyboard, connect: false)]
        let cases: [(String, MacAction)] = [
            ("connecte mes AirPods", .bluetooth(airpods, connect: true)),
            ("déconnecte le clavier bluetooth", .bluetooth(keyboard, connect: false)),
            ("coupe le wifi", .system(.wifiOff)),
            ("rallume le wi-fi", .system(.wifiOn)),
            ("montre le bureau", .system(.showDesktop))
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask picks the new Mac commands with \(provider.title): AirPods connected, the keyboard disconnected, Wi-Fi off and on, the desktop; “mets le son à 30 %”'s level read by the model"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            let level = await AskRouter.values(AskValues.levelQuestions, instruction: "mets le son à 30 %", keys: [provider: key])
                .flatMap { AskValues.level($0)?.level }
            var details: [String] = []
            var passed = level == 30
            var slowest: Duration = .zero
            for (instruction, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: [],
                                                      settings: SystemSettingsPanes.all(), bluetooth: bluetooth, keys: [provider: key])
                slowest = max(slowest, .now - start)
                let picked = decision?.command?.command
                let right: Bool
                if case .bluetooth(let target, let connect)? = picked, case .bluetooth(let wanted, let wantedConnect) = expected {
                    right = target == wanted && connect == wantedConnect
                } else {
                    right = picked == expected
                }
                passed = passed && decision?.route == .command && right
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(picked?.title ?? "")")
            }
            record(name, passed, details.joined(separator: "; ") + "; “mets le son à 30 %” → \(level.map(String.init) ?? "nil") read by the model, slowest \(Int(slowest.milliseconds)) ms",
                   slowest.milliseconds)
        }
    }

    /// Backups, on scratch copies only: skil.li's folder (the socket and
    /// the clipboard history never in it) and settings (this Mac's state
    /// left out) zipped into a scratch destination; restoring unpacks
    /// first, backs up what is there, then puts files and settings back. An
    /// older backup holding a clipboard history: put back without it, the
    /// history on this Mac kept.
    private func backupGoesAndComesBack() async {
        let name = "Backup: a zip of skil.li's files and settings without the clipboard history, listed in the user's words; restore puts them back after a backup of now; an older backup's clipboard history is left out"
        let backup = context.backup
        let files = FileManager.default
        let source = backup.sourceFolder
        let defaults = backup.sourceDefaults
        let scratch = files.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())", isDirectory: true)
        let destination = scratch.appendingPathComponent("backups", isDirectory: true)
        let preferences = context.preferences
        let saved = (preferences.backupFolder, preferences.backupKeep)
        defer {
            preferences.backupFolder = saved.0
            preferences.backupKeep = saved.1
            try? files.removeItem(at: destination)
            try? files.removeItem(at: scratch.appendingPathComponent("older"))
            try? files.removeItem(at: source)
            for key in defaults.dictionaryRepresentation().keys where key.hasPrefix("Preferences.") { defaults.removeObject(forKey: key) }
        }
        do {
            for (path, text) in [("snippets/hello.md", "Hello"), ("snippets/sign.md", "Camille"), ("layouts/desk.json", "{}"),
                                 ("quicklinks.json", #"[{"a":1},{"b":2}]"#), ("mcp.sock", ""), ("Clipboard/history.sqlite", "x")] {
                let url = source.appendingPathComponent(path)
                try files.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                try Data(text.utf8).write(to: url)
            }
            defaults.set("one", forKey: "Preferences.selftestBackup")
            defaults.set(true, forKey: "Preferences.didCompleteSetup")
            preferences.backupFolder = destination.path
            preferences.backupKeep = 10

            let url = try await backup.backUpNow()
            let listed = backup.backups()
            let contents = try await backup.contents(of: url)
            let expected = ["1 setting", "2 snippets", "2 quicklinks", "1 window layout"]
            let zipped = Self.zipEntries(url) ?? []
            let noClipboard = !zipped.isEmpty && !zipped.contains { $0.contains("/Clipboard/") || $0.hasSuffix("mcp.sock") }

            try files.removeItem(at: source.appendingPathComponent("snippets/sign.md"))
            try Data("New".utf8).write(to: source.appendingPathComponent("snippets/new.md"))
            defaults.set("two", forKey: "Preferences.selftestBackup")
            defaults.set("extra", forKey: "Preferences.selftestBackupExtra")
            try await backup.restore(url)
            let snippets = (try? files.contentsOfDirectory(atPath: source.appendingPathComponent("snippets").path))?.sorted() ?? []
            let kept = files.fileExists(atPath: source.appendingPathComponent("mcp.sock").path)
                && files.fileExists(atPath: source.appendingPathComponent("Clipboard/history.sqlite").path)
            let settingsBack = defaults.string(forKey: "Preferences.selftestBackup") == "one"
                && defaults.object(forKey: "Preferences.selftestBackupExtra") == nil && defaults.bool(forKey: "Preferences.didCompleteSetup")

            // A backup made before, with the clipboard history in it.
            let olderName = BackupPlan.name(at: Date.now.addingTimeInterval(-86_400))
            let olderRoot = scratch.appendingPathComponent("older/\((olderName as NSString).deletingPathExtension)", isDirectory: true)
            for (path, text) in [("skil.li/snippets/old.md", "Old"), ("skil.li/Clipboard/history.sqlite", "older history")] {
                let url = olderRoot.appendingPathComponent(path)
                try files.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                try Data(text.utf8).write(to: url)
            }
            try PropertyListSerialization.data(fromPropertyList: ["Preferences.selftestBackup": "older"], format: .xml, options: 0)
                .write(to: olderRoot.appendingPathComponent("Settings.plist"))
            let older = destination.appendingPathComponent(olderName)
            let ditto = Process()
            ditto.executableURL = URL(fileURLWithPath: "/usr/bin/ditto")
            ditto.arguments = ["-c", "-k", "--sequesterRsrc", "--keepParent", olderRoot.path, older.path]
            try ditto.run()
            ditto.waitUntilExit()
            let olderContents = try await backup.contents(of: older)
            try await backup.restore(older)
            let history = (try? String(contentsOf: source.appendingPathComponent("Clipboard/history.sqlite"), encoding: .utf8)) ?? ""
            let olderSnippets = (try? files.contentsOfDirectory(atPath: source.appendingPathComponent("snippets").path))?.sorted() ?? []
            let olderBack = olderSnippets == ["old.md"] && history == "x" && !olderContents.contains { $0.contains("clipboard") }
                && defaults.string(forKey: "Preferences.selftestBackup") == "older"

            let passed = listed.count == 1 && listed.first?.url.lastPathComponent == url.lastPathComponent && contents == expected && noClipboard
                && snippets == ["hello.md", "sign.md"] && kept && settingsBack && olderBack && backup.backups().count == 4
            record(name, passed, "\(url.lastPathComponent): \(contents.joined(separator: ", ")); no clipboard history or socket in the zip \(noClipboard) (\(zipped.count) entries); after restore snippets \(snippets), socket and clipboard kept \(kept), settings back \(settingsBack); older backup (\(olderContents.joined(separator: ", "))) put back without its clipboard history: \(olderBack) (snippets \(olderSnippets), history on this Mac \(history == "x" ? "kept" : "replaced")); backups \(backup.backups().count) (one before each restore)", nil)
        } catch {
            record(name, false, error.localizedDescription, nil)
        }
    }

    /// The paths a zip holds (`zipinfo -1`), or nil.
    private static func zipEntries(_ zip: URL) -> [String]? {
        guard let text = toolOutput("/usr/bin/zipinfo", ["-1", zip.path]) else { return nil }
        return String(decoding: text, as: UTF8.self).split(separator: "\n").map(String.init)
    }

    /// What `tool` writes with `arguments`, nil when it fails.
    private static func toolOutput(_ tool: String, _ arguments: [String]) -> Data? {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: tool)
        process.arguments = arguments
        let output = Pipe()
        process.standardOutput = output
        process.standardError = FileHandle.nullDevice
        guard (try? process.run()) != nil else { return nil }
        let data = output.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        return process.terminationStatus == 0 ? data : nil
    }

    /// The words said in recordings never reach a backup
    /// (docs/meeting-recorder.md, "Where it lives"), on scratch copies: the
    /// index, open in WAL mode with its `-wal` and `-shm`, is left out by
    /// its exact names (a file merely named like it is backed up), and no
    /// transcript's text is anywhere in the zip; a restore leaves this
    /// Mac's index as it is, an older backup's is not brought back; an
    /// index file SQLite cannot read is made again from the transcripts.
    private func backupLeavesTheWordsSaidOut() async {
        let name = "Backup: no transcript text in a backup (the words-said index and its WAL files left out by their exact names); a restore leaves this Mac's index as it is, an older backup's stays out; an unreadable index is made again from the transcripts"
        let backup = context.backup
        let files = FileManager.default
        let source = backup.sourceFolder
        let scratch = files.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())", isDirectory: true)
        let destination = scratch.appendingPathComponent("backups-words", isDirectory: true)
        let recordings = scratch.appendingPathComponent("words-recordings", isDirectory: true)
        let older = scratch.appendingPathComponent("older-words", isDirectory: true)
        let garbage = scratch.appendingPathComponent("garbage-index", isDirectory: true)
        let defaults = backup.sourceDefaults
        let preferences = context.preferences
        let saved = (preferences.backupFolder, preferences.backupKeep)
        defer {
            preferences.backupFolder = saved.0
            preferences.backupKeep = saved.1
            for folder in [destination, recordings, older, garbage, source] { try? files.removeItem(at: folder) }
            for key in defaults.dictionaryRepresentation().keys where key.hasPrefix("Preferences.") { defaults.removeObject(forKey: key) }
        }
        do {
            // A recording's transcript, and the index that holds its words.
            let folder = recordings.appendingPathComponent("2026-10-22 14.00 Weekly sync", isDirectory: true)
            try files.createDirectory(at: folder, withIntermediateDirectories: true)
            let words = "We agreed on the purple elephant budget for the third quarter".split(separator: " ").enumerated()
                .map { TranscriptWord(String($0.element), start: Double($0.offset), end: Double($0.offset) + 0.5) }
            try MeetingTranscript.File(language: "en-US", engine: "SpeechTranscriber", lines: [TranscriptLine(speaker: .them, words: words)])
                .encoded().write(to: folder.appendingPathComponent("transcript.json"))
            for (path, text) in [("snippets/hello.md", "Hello"), ("recordings-index.sqlite.bak", "the user's own file")] {
                let url = source.appendingPathComponent(path)
                try files.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
                try Data(text.utf8).write(to: url)
            }
            let indexURL = source.appendingPathComponent(RecordingSearch.indexFile)
            let index = RecordingIndex(url: indexURL)
            index.sync(root: recordings, folders: [folder.lastPathComponent])
            let indexed = !index.search("elephant").isEmpty
            let present = RecordingSearch.indexFiles.filter { files.fileExists(atPath: source.appendingPathComponent($0).path) }
            preferences.backupFolder = destination.path
            preferences.backupKeep = 10

            let url = try await backup.backUpNow()
            let zipped = Self.zipEntries(url) ?? []
            let indexInZip = zipped.filter { entry in RecordingSearch.indexFiles.contains { entry.hasSuffix("/" + $0) } }
            let lookalikeKept = zipped.contains { $0.hasSuffix("/recordings-index.sqlite.bak") }
            let unzipped = Self.toolOutput("/usr/bin/unzip", ["-p", url.path]) ?? Data()
            let noWords = !unzipped.isEmpty && !String(decoding: unzipped, as: UTF8.self).contains("elephant")

            // Restored: this Mac's index as it was.
            try await backup.restore(url)
            let keptAfterRestore = !RecordingIndex(url: indexURL).search("elephant").isEmpty

            // A backup made by an older version, with an index in it.
            let olderName = BackupPlan.name(at: Date.now.addingTimeInterval(-86_400))
            let olderRoot = older.appendingPathComponent((olderName as NSString).deletingPathExtension, isDirectory: true)
            for (path, text) in [("skil.li/snippets/old.md", "Old"), ("skil.li/\(RecordingSearch.indexFile)", "older words index"),
                                 ("skil.li/\(RecordingSearch.indexFile)-wal", "older words log")] {
                let file = olderRoot.appendingPathComponent(path)
                try files.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
                try Data(text.utf8).write(to: file)
            }
            try PropertyListSerialization.data(fromPropertyList: ["Preferences.selftestBackup": "older"], format: .xml, options: 0)
                .write(to: olderRoot.appendingPathComponent("Settings.plist"))
            let olderZip = destination.appendingPathComponent(olderName)
            guard Self.toolOutput("/usr/bin/ditto", ["-c", "-k", "--sequesterRsrc", "--keepParent", olderRoot.path, olderZip.path]) != nil else {
                record(name, false, "the older backup could not be zipped", nil)
                return
            }
            try await backup.restore(olderZip)
            let current = RecordingSearch.indexFiles.compactMap { try? Data(contentsOf: source.appendingPathComponent($0)) }
            let olderLeftOut = !current.contains { String(decoding: $0, as: UTF8.self).contains("older words") }
                && !RecordingIndex(url: indexURL).search("elephant").isEmpty

            // Not a database: made again from the transcripts.
            try files.createDirectory(at: garbage, withIntermediateDirectories: true)
            let garbageURL = garbage.appendingPathComponent(RecordingSearch.indexFile)
            try Data(String(repeating: "not a database ", count: 300).utf8).write(to: garbageURL)
            try Data("x".utf8).write(to: URL(fileURLWithPath: garbageURL.path + "-wal"))
            let remade = RecordingIndex(url: garbageURL)
            remade.sync(root: recordings, folders: [folder.lastPathComponent])
            let rebuilt = !remade.search("elephant").isEmpty

            let passed = indexed && present.contains(RecordingSearch.indexFile + "-wal") && indexInZip.isEmpty && lookalikeKept && noWords
                && keptAfterRestore && olderLeftOut && rebuilt
            record(name, passed,
                   "index with the words \(indexed), beside it \(present); in the zip: index files \(indexInZip), the look-alike kept \(lookalikeKept), no transcript text \(noWords) (\(zipped.count) entries, \(unzipped.count) bytes unzipped); after restore the index kept \(keptAfterRestore); an older backup's index left out \(olderLeftOut); an unreadable index made again \(rebuilt)",
                   nil)
        } catch {
            record(name, false, error.localizedDescription, nil)
        }
    }

    /// Jev with images, measured: each kind of picture tagged at three
    /// sizes (tokens, time, right or not), icon-only buttons picked among
    /// small images, the Settings page a screenshot shows. Every picture is
    /// drawn here (a wallpaper of macOS for the photo); a report and the
    /// pictures are left for review.
    private func jevSeesImages() async {
        let name = "Jev with images: tags each kind of picture, picks icon-only buttons, reads a screen; tokens and time per size"
        guard let key = Keychain.read(account: DecisionProvider.typeSafe.keychainAccount), !key.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no TypeSafe key saved in Settings", latencyMs: nil))
            return
        }
        func render(_ width: CGFloat, _ height: CGFloat, _ draw: @escaping (NSRect) -> Void) -> NSImage {
            NSImage(size: NSSize(width: width, height: height), flipped: true) { rect in
                draw(rect)
                return true
            }
        }
        func text(_ string: String, _ point: NSPoint, size: CGFloat, weight: NSFont.Weight = .regular, color: NSColor = .black, mono: Bool = false) {
            let font = mono ? NSFont.monospacedSystemFont(ofSize: size, weight: weight) : NSFont.systemFont(ofSize: size, weight: weight)
            (string as NSString).draw(at: point, withAttributes: [.font: font, .foregroundColor: color])
        }
        var samples: [(kind: String, image: NSImage)] = []
        samples.append(("code", render(1200, 800) { rect in
            NSColor(white: 0.12, alpha: 1).setFill(); rect.fill()
            let lines = ["import Foundation", "", "struct Invoice: Codable {", "    let number: String", "    let total: Decimal",
                         "", "    func formatted() -> String {", "        \"#\\(number): \\(total)\"", "    }", "}", "",
                         "let invoices = try JSONDecoder().decode([Invoice].self, from: data)", "print(invoices.map { $0.formatted() })"]
            for (index, line) in lines.enumerated() {
                text(line, NSPoint(x: 40, y: 40 + CGFloat(index) * 44), size: 26, color: index % 3 == 0 ? .systemPink : .white, mono: true)
            }
        }))
        samples.append(("chart", render(1200, 800) { rect in
            NSColor.white.setFill(); rect.fill()
            text("Revenue by quarter, 2026", NSPoint(x: 60, y: 30), size: 34, weight: .semibold)
            NSColor.black.setFill(); NSRect(x: 100, y: 120, width: 3, height: 560).fill(); NSRect(x: 100, y: 680, width: 1000, height: 3).fill()
            for (index, value) in [220, 360, 300, 520].enumerated() {
                NSColor.systemBlue.setFill()
                NSRect(x: 180 + CGFloat(index) * 230, y: 680 - CGFloat(value), width: 140, height: CGFloat(value)).fill()
                text("Q\(index + 1)", NSPoint(x: 230 + CGFloat(index) * 230, y: 700), size: 28)
            }
        }))
        samples.append(("invoice", render(900, 1200) { rect in
            NSColor.white.setFill(); rect.fill()
            text("INVOICE", NSPoint(x: 60, y: 60), size: 52, weight: .bold)
            text("Free SAS · 8 rue de la Ville l'Évêque, Paris", NSPoint(x: 60, y: 140), size: 22)
            text("Invoice no. 2026-1015 · 15 Oct 2026", NSPoint(x: 60, y: 175), size: 22)
            NSColor(white: 0.85, alpha: 1).setFill(); NSRect(x: 60, y: 260, width: 780, height: 2).fill()
            for (index, line) in ["Freebox Ultra · 1 · 49,99 €", "Mobile plan · 1 · 19,99 €", "Option TV · 1 · 9,99 €"].enumerated() {
                text(line, NSPoint(x: 60, y: 290 + CGFloat(index) * 50), size: 26)
            }
            NSRect(x: 60, y: 460, width: 780, height: 2).fill()
            text("Total due: 79,97 €", NSPoint(x: 480, y: 490), size: 30, weight: .semibold)
        }))
        samples.append(("chat", render(900, 1200) { rect in
            NSColor.white.setFill(); rect.fill()
            let messages = [("Are we still on for lunch?", false), ("Yes! 12:30 at Le Comptoir?", true), ("Perfect, see you there", false),
                            ("I'll book a table", true), ("👍", false)]
            for (index, message) in messages.enumerated() {
                let y = 80 + CGFloat(index) * 170
                let bubble = NSRect(x: message.1 ? 360 : 60, y: y, width: 480, height: 110)
                (message.1 ? NSColor.systemBlue : NSColor(white: 0.9, alpha: 1)).setFill()
                NSBezierPath(roundedRect: bubble, xRadius: 40, yRadius: 40).fill()
                text(message.0, NSPoint(x: bubble.minX + 30, y: y + 38), size: 26, color: message.1 ? .white : .black)
            }
        }))
        samples.append(("diagram", render(1200, 800) { rect in
            NSColor.white.setFill(); rect.fill()
            let boxes = [("Browser", NSPoint(x: 80, y: 330)), ("API", NSPoint(x: 480, y: 330)), ("Database", NSPoint(x: 880, y: 160)),
                         ("Cache", NSPoint(x: 880, y: 500))]
            for box in boxes {
                NSColor.systemOrange.withAlphaComponent(0.25).setFill()
                let frame = NSRect(origin: box.1, size: NSSize(width: 240, height: 120))
                NSBezierPath(roundedRect: frame, xRadius: 16, yRadius: 16).fill()
                NSColor.black.setStroke(); NSBezierPath(roundedRect: frame, xRadius: 16, yRadius: 16).stroke()
                text(box.0, NSPoint(x: frame.minX + 40, y: frame.minY + 42), size: 30)
            }
            NSColor.black.setStroke()
            for (from, to) in [(NSPoint(x: 320, y: 390), NSPoint(x: 480, y: 390)), (NSPoint(x: 720, y: 370), NSPoint(x: 880, y: 220)),
                               (NSPoint(x: 720, y: 410), NSPoint(x: 880, y: 560))] {
                let path = NSBezierPath(); path.move(to: from); path.line(to: to); path.lineWidth = 4; path.stroke()
            }
        }))
        samples.append(("document", render(900, 1200) { rect in
            NSColor.white.setFill(); rect.fill()
            text("Compte rendu de réunion", NSPoint(x: 60, y: 60), size: 40, weight: .bold)
            let paragraph = "Nous avons revu le planning du trimestre et décidé de livrer la nouvelle version en novembre. Chaque équipe prépare sa partie et les tests se font sur la machine partagée."
            for line in 0..<12 {
                (paragraph as NSString).draw(in: NSRect(x: 60, y: 150 + CGFloat(line) * 80, width: 780, height: 80),
                                             withAttributes: [.font: NSFont.systemFont(ofSize: 22), .foregroundColor: NSColor.black])
            }
        }))
        // A real photo: macOS's own landscapes, when downloaded (most of its
        // wallpapers are abstract: "other" is right for those).
        let photos = ["Big Sur Coastline", "Big Sur Aerial", "Big Sur Mountains", "Big Sur Road", "Catalina Coast", "Catalina Rock"]
        if let path = photos.flatMap({ ["/System/Library/Desktop Pictures/\($0).heic", "/System/Library/Desktop Pictures/.thumbnails/\($0).heic"] })
            .first(where: { FileManager.default.fileExists(atPath: $0) }), let image = NSImage(contentsOfFile: path) {
            samples.append(("photo", image))
        }
        context.settings.show(pane: .calendar)
        await pause(600)
        if let png = await context.settings.snapshotPNG(), let image = NSImage(data: png) { samples.append(("screenshot", image)) }
        await closeSettings()

        let kinds: [(value: String, criteria: String)] = [
            ("screenshot", "A screenshot of an app or a website: windows, buttons, menus, settings"),
            ("code", "Source code or a terminal"), ("chat", "A chat or messages conversation"),
            ("document", "A document or a page of text"), ("invoice", "An invoice, a receipt or a bill"),
            ("chart", "A chart or a graph of numbers"), ("diagram", "A diagram, a schema or a flowchart"),
            ("photo", "A photo of the real world: people, places, landscapes, objects"), ("other", "Anything else")
        ]
        struct Row: Codable { let kind: String; let size: Int; let bytes: Int; let tokens: Int; let ms: Int; let tag: String; let probability: Double; let right: Bool }
        var rows: [Row] = []
        var failures: [String] = []
        for sample in samples {
            for size in [512, 1024, 1568] {
                guard let data = JevImages.jpeg(sample.image, longest: CGFloat(size)) else { continue }
                if size == 1024, let directory = context.snapshotDirectory { try? data.write(to: directory.appendingPathComponent("vision-\(sample.kind).jpg")) }
                let reference = "img-\(UUID().uuidString)"
                do {
                    let answers = try await JevImages.judge(state: ["image": reference], images: [.init(reference: reference, data: data, format: "jpeg")],
                                                            questions: [.choice(name: "kind", instructions: "What kind of picture is `image`?", options: kinds)],
                                                            key: key)
                    let tag = answers.results["kind"]
                    rows.append(Row(kind: sample.kind, size: size, bytes: data.count, tokens: answers.inputTokens, ms: Int(answers.milliseconds),
                                    tag: tag?.choice ?? "none", probability: tag.map { $0.probabilities[$0.choice] ?? 0 } ?? 0,
                                    right: tag?.choice == sample.kind))
                } catch {
                    failures.append("\(sample.kind) \(size): \(error.localizedDescription)")
                }
            }
        }

        // Icon-only buttons: which one deletes, shares, prints.
        let icons = ["trash", "square.and.arrow.up", "gearshape", "magnifyingglass", "printer", "paperplane", "star", "folder"]
        var options: [(value: String, criteria: String)] = []
        var iconImages: [JevImages.Image] = []
        for icon in icons {
            guard let symbol = Theme.symbol(icon, pointSize: 120, weight: .regular) else { continue }
            let tile = render(256, 256) { rect in
                NSColor.white.setFill(); rect.fill()
                symbol.draw(in: NSRect(x: 64, y: 64, width: 128, height: 128))
            }
            guard let data = JevImages.jpeg(tile, longest: 256) else { continue }
            let reference = "icon-\(UUID().uuidString)"
            iconImages.append(.init(reference: reference, data: data, format: "jpeg"))
            options.append((icon, reference))
        }
        var iconResults: [String] = []
        var iconRight = 0
        var iconTokens = 0, iconMs = 0
        do {
            let asked = [("delete", "Which of these toolbar buttons deletes the selected item?", "trash"),
                         ("share", "Which of these toolbar buttons shares the document with someone?", "square.and.arrow.up"),
                         ("print", "Which of these toolbar buttons prints?", "printer")]
            let answers = try await JevImages.judge(state: [:], images: iconImages,
                                                    questions: asked.map { .choice(name: $0.0, instructions: $0.1, options: options) }, key: key)
            iconTokens = answers.inputTokens
            iconMs = Int(answers.milliseconds)
            for question in asked {
                let picked = answers.results[question.0]?.choice ?? "none"
                if picked == question.2 { iconRight += 1 }
                iconResults.append("\(question.0) → \(picked)")
            }
        } catch {
            failures.append("icons: \(error.localizedDescription)")
        }

        // A screen: which Settings page shows.
        var screen = "no screenshot"
        var screenRight = false
        if let shot = samples.first(where: { $0.kind == "screenshot" }), let data = JevImages.jpeg(shot.image, longest: 1024) {
            let reference = "screen-\(UUID().uuidString)"
            let pages = ["General", "Launcher", "Clipboard", "Snippets", "Windows", "Agenda", "Reminders", "Backup"].map { ($0.lowercased(), "The \($0) page") }
            do {
                let answers = try await JevImages.judge(state: ["window": reference], images: [.init(reference: reference, data: data, format: "jpeg")],
                                                        questions: [.choice(name: "page", instructions: "Which page of the Settings window does `window` show?", options: pages),
                                                                    .noul(name: "calls", instructions: "Does `window` let the user choose what happens when a meeting starts?")],
                                                        key: key)
                screenRight = answers.results["page"]?.choice == "agenda"
                screen = "page \(answers.results["page"]?.choice ?? "none"), meeting setting there: \(Int((answers.results["calls"]?.confidence ?? 0) * 100)) %, \(answers.inputTokens) tokens, \(Int(answers.milliseconds)) ms"
            } catch {
                failures.append("screen: \(error.localizedDescription)")
            }
        }

        if let directory = context.snapshotDirectory, let json = try? JSONEncoder().encode(rows) {
            try? json.write(to: directory.appendingPathComponent("vision-report.json"))
        }
        func summary(_ size: Int) -> String {
            let at = rows.filter { $0.size == size }
            guard !at.isEmpty else { return "\(size) px: none" }
            let tokens = at.map(\.tokens).reduce(0, +) / at.count
            let ms = at.map(\.ms).sorted()[at.count / 2]
            return "\(size) px: \(at.filter(\.right).count)/\(at.count) right, ~\(tokens) tokens, median \(ms) ms"
        }
        let wrong = rows.filter { !$0.right && $0.size == 1024 }.map { "\($0.kind)→\($0.tag)" }
        record(name, failures.isEmpty && !rows.isEmpty,
               ([summary(512), summary(1024), summary(1568)].joined(separator: "; ")
                + "; wrong at 1024: \(wrong.isEmpty ? "none" : wrong.joined(separator: ", "))"
                + "; icons \(iconRight)/3 (\(iconResults.joined(separator: ", ")), \(iconTokens) tokens, \(iconMs) ms)"
                + "; screen: \(screenRight ? "right" : "wrong"), \(screen)"
                + (failures.isEmpty ? "" : "; failed: \(failures.joined(separator: " | "))")), nil)
    }

    /// Images by what they show, end to end on the self-test's own history:
    /// an invoice copied, then a chart saved in a watched scratch folder,
    /// each tagged by Jev (the user's TypeSafe key) and found by a word of
    /// its kind in French, as the launcher searches.
    private func imagesTaggedAndFound() async {
        let name = "Images by what they show: a copied invoice and a chart saved in a watched folder, tagged by Jev, found as “facture” and “graphique”"
        guard let key = Keychain.read(account: DecisionProvider.typeSafe.keychainAccount), !key.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no TypeSafe key saved in Settings", latencyMs: nil))
            return
        }
        let history = context.clipboard
        guard let store = history.store else {
            record(name, false, "no scratch clipboard store", nil)
            return
        }
        let preferences = context.preferences
        let saved = (history.imageKey, preferences.imageTagsClipboard, preferences.clipboardHistory)
        history.imageKey = { key }
        preferences.imageTagsClipboard = true
        preferences.clipboardHistory = true
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/Screens \(Int.random(in: 1000...9999))", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let watcher = ImageFolderWatcher()
        var kept: [Int64] = []
        defer {
            watcher.stop()
            for id in kept { try? store.delete(id) }
            try? FileManager.default.removeItem(at: folder)
            history.imageKey = saved.0
            preferences.imageTagsClipboard = saved.1
            preferences.clipboardHistory = saved.2
        }
        func picture(_ draw: @escaping (NSRect) -> Void) -> NSImage {
            NSImage(size: NSSize(width: 900, height: 700), flipped: true) { rect in
                NSColor.white.setFill(); rect.fill()
                draw(rect)
                return true
            }
        }
        func write(_ string: String, at point: NSPoint, size: CGFloat, weight: NSFont.Weight = .regular) {
            (string as NSString).draw(at: point, withAttributes: [.font: NSFont.systemFont(ofSize: size, weight: weight), .foregroundColor: NSColor.black])
        }
        // A unique mark: the scratch store may hold other test copies.
        let mark = "\(Int.random(in: 100_000...999_999))"
        let invoice = picture { _ in
            write("INVOICE", at: NSPoint(x: 50, y: 50), size: 54, weight: .bold)
            write("Free SAS · Invoice no. \(mark)", at: NSPoint(x: 50, y: 130), size: 24)
            for (index, line) in ["Freebox Ultra · 49,99 €", "Mobile plan · 19,99 €"].enumerated() {
                write(line, at: NSPoint(x: 50, y: 220 + CGFloat(index) * 50), size: 26)
            }
            write("Total due: 69,98 €", at: NSPoint(x: 480, y: 360), size: 30, weight: .semibold)
        }
        let chart = picture { _ in
            write("Visitors \(mark)", at: NSPoint(x: 50, y: 30), size: 32, weight: .semibold)
            NSColor.black.setFill(); NSRect(x: 80, y: 100, width: 3, height: 520).fill(); NSRect(x: 80, y: 620, width: 760, height: 3).fill()
            for (index, value) in [180, 320, 260, 450].enumerated() {
                NSColor.systemTeal.setFill()
                NSRect(x: 150 + CGFloat(index) * 170, y: 620 - CGFloat(value), width: 110, height: CGFloat(value)).fill()
            }
        }

        // Copied: on the clipboard, then kept as the history keeps a copy.
        let pasteboard = NSPasteboard.general
        pasteboard.clearContents()
        pasteboard.writeObjects([invoice])
        let copied = history.capture()
        if let copied { kept.append(copied.id) }
        let copiedTagged = await waitUntil(timeout: 15) {
            store.search(mark).contains { $0.id == copied?.id && $0.tags != nil }
        } != nil
        let foundCopy = copied.map { item in store.search("facture").contains { $0.id == item.id } } ?? false
        let copyTitle = store.search(mark).first { $0.id == copied?.id }?.title ?? "none"

        // Saved in the watched folder: joins the history by itself.
        let source = FileManager.default.displayName(atPath: folder.path)
        watcher.onImage = { url, date in
            if let item = history.keepImage(at: url, made: date, from: source) { kept.append(item.id) }
        }
        let watching = watcher.watch(folder)
        if let tiff = chart.tiffRepresentation, let png = NSBitmapImageRep(data: tiff)?.representation(using: .png, properties: [:]) {
            try? png.write(to: folder.appendingPathComponent("Screenshot \(mark).png"))
        }
        let joined = await waitUntil(timeout: 20) {
            store.search("graphique").contains { $0.appName == source }
        } != nil
        let saved_ = store.search("").first { $0.appName == source }
        record(name, copied != nil && copiedTagged && foundCopy && copyTitle.hasPrefix("Invoice") && watching && joined,
               "copied: kept \(copied != nil), tagged \(copiedTagged), “facture” finds it \(foundCopy), title “\(copyTitle.prefix(40))”; "
                   + "folder: watched \(watching), joined and found as “graphique” \(joined) (\(saved_?.title.prefix(30) ?? "nothing"), tags “\(saved_?.tags?.prefix(30) ?? "")”)", nil)
    }

    /// Raycast's snippet and quicklink exports become skil.li's own: in the
    /// self-test's snippets folder and an in-memory quicklinks store.
    private func raycastExportsImport() async {
        let name = "Raycast import: an exported snippets file becomes snippets (a keyword already used left off), a quicklinks file quicklinks with {query}"
        let snippets = """
        [{"name": "Raycast Sig Selftest", "text": "Cheers,\\n{clipboard}", "keyword": ";rcx1"},
         {"name": "Raycast Order Selftest", "text": "Order {uuid}", "keyword": ";rcx1"}]
        """
        let library = context.snippets
        let before = Set(library.all.map(\.id))
        let result = library.importRaycast(Data(snippets.utf8))
        let added = library.all.filter { !before.contains($0.id) }
        defer { for snippet in added { library.delete(snippet.id) } }
        let snippetsOK = result?.imported == 2 && result?.keywordsLeftOff == 1 && result?.unknown == ["{uuid}"]
            && added.map(\.name).sorted() == ["Raycast Order Selftest", "Raycast Sig Selftest"]
            && added.first { $0.name == "Raycast Sig Selftest" }?.keyword == ";rcx1"
            && added.first { $0.name == "Raycast Order Selftest" }?.keyword == ""
        let notSnippets = library.importRaycast(Data(#"[{"name": "x", "link": "https://x.com"}]"#.utf8)) == nil

        let store = QuicklinkStore(fileURL: nil)
        let count = store.links.count
        let links = """
        [{"name": "npm Search", "link": "https://www.npmjs.com/search?q={Query}"},
         {"name": "Google", "link": "https://www.google.com/search?q={Query}"},
         {"name": "Clip", "link": "https://translate.google.com/?text={clipboard}"}]
        """
        let linkResult = store.importRaycast(Data(links.utf8))
        let npm = store.links.first { $0.name == "npm Search" }
        let linksOK = linkResult?.imported == 1 && linkResult?.skipped == ["Clip"] && store.links.count == count + 1
            && npm?.url == "https://www.npmjs.com/search?q={query}" && npm?.takesQuery == true
        record(name, snippetsOK && notSnippets && linksOK,
               "snippets: \(result.map { "\($0.imported) imported, \($0.keywordsLeftOff) keyword left off, not filled \($0.unknown)" } ?? "refused"), a quicklinks file refused: \(notSnippets); quicklinks: \(linkResult.map { "\($0.imported) imported (Google already there), left out \($0.skipped)" } ?? "refused"), npm \(npm?.url ?? "missing")", nil)
    }

    /// Homebrew: "brew hello" finds GNU hello by name with its description,
    /// Return asks to install it (recorded here), the installed ones list
    /// with no text; brew itself only ever runs with --dry-run; agents
    /// search and install (dry run), an unknown name refused.
    private func homebrewSearchAndInstall() async {
        let name = "Homebrew: “brew hello” found with its description, Return asks to install it, installed ones listed; dry-run install; agents search and install"
        let tools = context.tools.tools
        guard let homebrew = tools.homebrew, homebrew.brew != nil else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "Homebrew is not installed", latencyMs: nil))
            return
        }
        guard homebrew.dryRun else {
            record(name, false, "the self-test's Homebrew is not in dry-run: nothing tried", nil)
            return
        }
        let names = homebrew.allNames()
        let listed = names.formulae.count > 1_000 && names.formulae.contains("hello")
        let described = (await homebrew.descriptions([BrewPackage(name: "hello", isCask: false)]))["hello"] ?? ""
        let installedFormula = homebrew.installed().formulae.keys.sorted().first

        let launcher = context.launcher
        let saved = launcher.onBrew
        defer { launcher.onBrew = saved }
        var asked: [String] = []
        launcher.onBrew = { action, package in asked.append("\(action.rawValue) \(package?.name ?? "all")") }

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "brew hello" { await pressKey(character) }
        let mode = await waitUntil(timeout: 1) { launcher.isInBrew } != nil
        let found = await waitUntil(timeout: 2) { launcher.resultTitles.first == "hello" } != nil
        await captureLauncher(as: "launcher-brew.png")
        // ⌘⌫ on a package that is not installed: nothing asked.
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let noUninstall = asked.isEmpty
        await pressKey(nil, code: CGKeyCode(found ? kVK_Return : kVK_Escape))
        let askedInstall = await waitUntil(timeout: 1) { asked.last == "install hello" } != nil

        var installedListed = true
        if let installedFormula {
            guard await focusTestWindow() else { return }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "brew " { await pressKey(character) }
            installedListed = await waitUntil(timeout: 2) { launcher.resultTitles.contains(installedFormula) } != nil
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
        }
        await closeLauncher()

        // While the list refreshes, as when a user installs right away.
        async let listing = homebrew.outdated()
        let dryRun: String
        do {
            dryRun = try await homebrew.run(.install, BrewPackage(name: "hello", isCask: false))
        } catch {
            dryRun = "failed: \(error.localizedDescription)"
        }
        _ = await listing
        let toolSearch = (try? await tools.call("brew_search", arguments: ["query": "hello"], run: nil)) ?? ""
        let toolInstall = (try? await tools.call("brew_install", arguments: ["name": "hello"], run: nil)) ?? "failed"
        let refused = (try? await tools.call("brew_install", arguments: ["name": "zzzz-not-a-formula"], run: nil)) == nil
        record(name, listed && described.contains("GNU") && mode && found && noUninstall && askedInstall && installedListed
               && dryRun.contains("hello") && toolSearch.hasPrefix("hello (formula): ") && toolInstall.contains("hello") && refused,
               "names: \(names.formulae.count) formulae, \(names.casks.count) casks; hello: “\(described)”; Brew mode: \(mode), first: \(found), ⌘⌫ ignored: \(noUninstall), Return asks: \(asked.joined(separator: ", ")); installed \(installedFormula ?? "none") listed: \(installedListed); dry run: “\(dryRun.replacingOccurrences(of: "\n", with: " | "))”; tools: search “\(toolSearch.prefix(80))”, install dry run: \(toolInstall.contains("hello")), unknown refused: \(refused)", nil)
    }

    /// Pages a person remembers, picked first among look-alikes (a fixed
    /// list: nothing of the Mac's browsers read). Decided only.
    private func historyPickedByMeaning() async {
        let now = Date.now
        func visit(_ url: String, _ title: String, hoursAgo: Double, _ browser: String = "Chrome") -> HistoryVisit {
            HistoryVisit(url: url, title: title, browser: browser, bundleID: "com.google.Chrome", visited: now.addingTimeInterval(-hoursAgo * 3_600), visits: 1)
        }
        let visits = [
            visit("https://www.impots.gouv.fr/accueil", "Déclarer mes revenus 2026", hoursAgo: 20),
            visit("https://www.service-public.fr/particuliers/vosdroits/F1342", "Taxe foncière : calcul et paiement", hoursAgo: 50),
            visit("https://www.marmiton.org/recettes/tarte-aux-pommes", "Tarte aux pommes facile", hoursAgo: 40),
            visit("https://www.swift.org/documentation/concurrency", "Swift Concurrency — Documentation", hoursAgo: 2),
            visit("https://www.sncf-connect.com/app/trips", "Billets de train Paris Rennes", hoursAgo: 6, "Zen"),
            visit("https://www.leboncoin.fr/velos/2741", "Vélo de route occasion taille M", hoursAgo: 120, "Zen"),
            visit("https://www.youtube.com/watch?v=jfKfPfyJRdk", "lofi hip hop radio - beats to relax/study to", hoursAgo: 3),
            visit("https://github.com/nomdelasociete/skilli/pulls", "Pull requests · nomdelasociete/skilli", hoursAgo: 1)
        ]
        let cases = [("la page des impôts sur le revenu", visits[0]), ("le train pour la bretagne", visits[4]),
                     ("la recette de dessert", visits[2]), ("le vélo d'occasion que je regardais", visits[5])]
        for provider in DecisionProvider.allCases {
            let name = "History by meaning with \(provider.title): pages picked first among look-alikes"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = true
            var slowest: Duration = .zero
            for (request, expected) in cases {
                let start = ContinuousClock.now
                let found = await BrowserHistory.searchByMeaning(request, keys: [provider: key], among: visits)
                slowest = max(slowest, .now - start)
                let first = found?.visits.first
                passed = passed && first?.url == expected.url
                details.append("“\(request)” → \(first?.title ?? "nothing")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// Search Browser History on a scratch Chrome and Zen: "history tarte"
    /// finds the page by words and Return opens it in Chrome (recorded);
    /// a description ⇥ finds one by meaning; agents search; non-web pages
    /// left out.
    private func browserHistorySearch() async {
        let name = "Browser history: Safari's, Chrome's and Zen's pages by words, Return opens in its browser, ⇥ by meaning; agents search"
        let base = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-history", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: base) }
        let chrome = base.appendingPathComponent("Google/Chrome/Default/History")
        let zen = base.appendingPathComponent("zen/Profiles/selftest.default/places.sqlite")
        for file in [chrome, zen] { try? FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true) }
        let now = Date.now.timeIntervalSince1970
        func chromeTime(_ hoursAgo: Double) -> Int64 { Int64((now - hoursAgo * 3_600 + 11_644_473_600) * 1_000_000) }
        func zenTime(_ hoursAgo: Double) -> Int64 { Int64((now - hoursAgo * 3_600) * 1_000_000) }
        let chromeRows = [("https://www.impots.gouv.fr/accueil", "Déclarer mes revenus 2026", 20.0),
                          ("https://www.marmiton.org/recettes/tarte-aux-pommes", "Tarte aux pommes facile", 40),
                          ("https://www.swift.org/documentation/concurrency", "Swift Concurrency — Documentation", 2),
                          ("chrome://settings", "Settings", 1)]
            .map { "INSERT INTO urls (url, title, visit_count, last_visit_time) VALUES ('\($0.0)', '\($0.1)', 1, \(chromeTime($0.2)));" }
        await Self.run("/usr/bin/sqlite3", [chrome.path, "CREATE TABLE urls(id INTEGER PRIMARY KEY AUTOINCREMENT, url LONGVARCHAR, title LONGVARCHAR, visit_count INTEGER DEFAULT 0 NOT NULL, typed_count INTEGER DEFAULT 0 NOT NULL, last_visit_time INTEGER NOT NULL, hidden INTEGER DEFAULT 0 NOT NULL);" + chromeRows.joined()])
        let zenRows = [("https://www.sncf-connect.com/app/trips", "Billets de train Paris Rennes", 6.0),
                       ("https://www.leboncoin.fr/velos/2741", "Vélo de route occasion taille M", 120)]
            .map { "INSERT INTO moz_places (url, title, visit_count, last_visit_date) VALUES ('\($0.0)', '\($0.1)', 1, \(zenTime($0.2)));" }
        await Self.run("/usr/bin/sqlite3", [zen.path, "CREATE TABLE moz_places (id INTEGER PRIMARY KEY, url LONGVARCHAR, title LONGVARCHAR, visit_count INTEGER DEFAULT 0, hidden INTEGER DEFAULT 0 NOT NULL, last_visit_date INTEGER);" + zenRows.joined()])
        // Safari: pages and their visits, titles on the visits, seconds since 2001.
        let safari = base.appendingPathComponent("Library/Safari/History.db")
        try? FileManager.default.createDirectory(at: safari.deletingLastPathComponent(), withIntermediateDirectories: true)
        func safariTime(_ hoursAgo: Double) -> Double { Date.now.timeIntervalSinceReferenceDate - hoursAgo * 3_600 }
        await Self.run("/usr/bin/sqlite3", [safari.path, """
            CREATE TABLE history_items (id INTEGER PRIMARY KEY AUTOINCREMENT, url TEXT NOT NULL UNIQUE, domain_expansion TEXT NULL, visit_count INTEGER NOT NULL);
            CREATE TABLE history_visits (id INTEGER PRIMARY KEY AUTOINCREMENT, history_item INTEGER NOT NULL, visit_time REAL NOT NULL, title TEXT NULL);
            INSERT INTO history_items (url, visit_count) VALUES ('https://www.marmiton.org/recettes/gratin-dauphinois', 2);
            INSERT INTO history_visits (history_item, visit_time, title) VALUES (1, \(safariTime(30)), 'Ancien titre'), (1, \(safariTime(10)), 'Gratin dauphinois');
            """])
        let installed: Set<String> = ["com.google.Chrome", "app.zen-browser.zen", "com.apple.Safari"]
        let source = BrowserHistory.Source(root: base, library: base.appendingPathComponent("Library", isDirectory: true),
                                           installed: { installed.contains($0) })

        let recent = await BrowserHistory.recent(source: source)
        let read = recent.map(\.title) == ["Swift Concurrency — Documentation", "Billets de train Paris Rennes", "Gratin dauphinois",
                                           "Déclarer mes revenus 2026", "Tarte aux pommes facile", "Vélo de route occasion taille M"]
        let launcher = context.launcher
        let tools = context.tools.tools
        let saved = (launcher.historySource, launcher.onOpenVisit, launcher.historyByMeaningAvailable, launcher.historyDecisionKeys, tools.historySource)
        defer { (launcher.historySource, launcher.onOpenVisit, launcher.historyByMeaningAvailable, launcher.historyDecisionKeys, tools.historySource) = saved }
        var opened: [String] = []
        let keys = userDecisionKeys
        launcher.historySource = source
        launcher.onOpenVisit = { visit, copy in opened.append("\(visit.title) \(copy ? "copied" : visit.browser)") }
        launcher.historyByMeaningAvailable = { !keys.isEmpty }
        launcher.historyDecisionKeys = { keys }
        tools.historySource = source

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "history tarte" { await pressKey(character) }
        let mode = await waitUntil(timeout: 1) { launcher.isInHistory } != nil
        let byWords = await waitUntil(timeout: 2) { launcher.resultTitles.first == "Tarte aux pommes facile" } != nil
        await pressKey(nil, code: CGKeyCode(byWords ? kVK_Return : kVK_Escape))
        let openedInChrome = opened.last == "Tarte aux pommes facile Chrome"
        // Safari's page by words, opened in Safari.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "history gratin" { await pressKey(character) }
        let fromSafari = await waitUntil(timeout: 2) { launcher.resultTitles.first == "Gratin dauphinois" } != nil
        await pressKey(nil, code: CGKeyCode(fromSafari ? kVK_Return : kVK_Escape))
        let openedInSafari = opened.last == "Gratin dauphinois Safari"

        var meaningDetail = "no decision key: skipped"
        var meaningPassed = true
        if !keys.isEmpty {
            guard await focusTestWindow() else { return }
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            for character in "history le train pour la bretagne" { await pressKey(character) }
            await pressKey(nil, code: CGKeyCode(kVK_Tab))
            let byMeaning = await waitUntil(timeout: 8) { launcher.isShowingHistoryMeaning && launcher.resultTitles.first == "Billets de train Paris Rennes" } != nil
            await captureLauncher(as: "launcher-history-meaning.png")
            await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
            let copied = await waitUntil(timeout: 1) { opened.last == "Billets de train Paris Rennes copied" } != nil
            meaningPassed = byMeaning && copied
            meaningDetail = "by meaning: \(byMeaning) (\(launcher.resultTitles.first ?? "nothing")), ⌘Return copies: \(copied)"
        }
        await closeLauncher()

        let listing = (try? await tools.call("search_history", arguments: ["query": "swift"], run: nil)) ?? ""
        let toolFound = listing.hasPrefix("Swift Concurrency — Documentation — https://www.swift.org/documentation/concurrency — Chrome")
        record(name, read && mode && byWords && openedInChrome && fromSafari && openedInSafari && meaningPassed && toolFound,
               "read: \(read) (\(recent.map(\.title)), chrome:// left out); History mode: \(mode), “tarte” first: \(byWords), opened in Chrome: \(openedInChrome); Safari's “gratin”: \(fromSafari), opened in Safari: \(openedInSafari); \(meaningDetail); tool: \(toolFound)", nil)
    }

    /// Skillies from the self-test's own folder: listed with their
    /// metadata; "say hello" + Return shows the last line; a text and a
    /// dropdown argument filled in the launcher reach the script; inline
    /// shows its line in the row; a failure says its last line; a script
    /// without the executable bit runs through its shebang; a Raycast
    /// Script Command imported becomes one; agents list, create and run.
    private func scriptCommandsRun() async {
        let name = "Skillies: listed, run from the launcher (last line, arguments with a dropdown, inline line), failures and shebang, the Running… card unless showsRunning false; Raycast import; agents create, list and run"
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/skillies", isDirectory: true)
        let raycast = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/raycast", isDirectory: true)
        for url in [folder, raycast] { try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true) }
        defer { for url in [folder, raycast] { try? FileManager.default.removeItem(at: url) } }
        let marker = String((0..<5).map { _ in "abcdefghijklmnopqrstuvwxyz".randomElement()! })
        func write(_ file: String, _ text: String, in place: URL? = nil, executable: Bool = true) {
            let url = (place ?? folder).appendingPathComponent(file)
            try? text.write(to: url, atomically: true, encoding: .utf8)
            try? FileManager.default.setAttributes([.posixPermissions: executable ? 0o755 : 0o644], ofItemAtPath: url.path)
        }
        write("hello.sh", "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Say Hello Selftest\n# @skilli.mode compact\n# @skilli.icon 👋\necho first line\necho \"Hello from a script\"\n")
        write("greet.sh", "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Greet Someone Selftest\n# @skilli.mode fullOutput\n# @skilli.argument1 { \"type\": \"text\", \"placeholder\": \"Name\" }\n# @skilli.argument2 { \"type\": \"dropdown\", \"placeholder\": \"Mood\", \"data\": [{\"title\": \"Happy\", \"value\": \"happy\"}, {\"title\": \"Calm\", \"value\": \"calm\"}] }\necho \"Hi $1, you look $2\"\n")
        write("clock.sh", "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Selftest Clock\n# @skilli.mode inline\n# @skilli.refreshTime 10s\necho tick-\(marker)\n")
        write("fail.sh", "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Failing Selftest\n# @skilli.mode compact\necho \"Something broke\"\nexit 3\n")
        write("plain.sh", "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Not Executable Selftest\n# @skilli.mode silent\necho shebang-\(marker)\n", executable: false)
        write("slow.sh", "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Slow Selftest\n# @skilli.mode compact\nsleep 1.5\necho slow-\(marker)\n")
        write("quiet.sh", "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Quiet Selftest\n# @skilli.mode compact\n# @skilli.showsRunning false\nsleep 1.5\necho quiet-\(marker)\n")
        write("notes.txt", "# @skilli.title Not a skillie without a mode\n")
        write("flush.sh", "#!/bin/bash\n# @raycast.schemaVersion 1\n# @raycast.title Imported From Raycast Selftest\n# @raycast.mode compact\necho imported-\(marker)\n", in: raycast)
        write("readme.md", "Not a command", in: raycast)

        let tools = context.tools.tools
        guard let library = tools.scripts else {
            record(name, false, "no skillies library", nil)
            return
        }
        let titles = library.all().map(\.title)
        let listed = titles == ["Failing Selftest", "Greet Someone Selftest", "Not Executable Selftest", "Quiet Selftest", "Say Hello Selftest", "Selftest Clock", "Slow Selftest"]
        let launcher = context.launcher
        let popover = context.aiActions.popover
        var details = ["listed: \(listed) (\(titles.joined(separator: ", ")))"]

        // "say hello" + Return: compact, its last line in the card.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "say hello selftest" { await pressKey(character) }
        let hello = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Say Hello Selftest" } != nil
        await pressKey(nil, code: CGKeyCode(hello ? kVK_Return : kVK_Escape))
        let lastLine = await waitUntil(timeout: 4) { popover.isVisible && popover.shownText == "Hello from a script" } != nil
        details.append("compact: \(lastLine)")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // Arguments: a name typed, then Happy picked in the dropdown.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "greet someone selftest" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Greet Someone Selftest" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let asked = await waitUntil(timeout: 1) { launcher.isInScript } != nil
        // ↩ with the name missing says what to type, in the footer's place.
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let missingSaid = await waitUntil(timeout: 1) { launcher.shownNote == "Greet Someone Selftest needs “Name”: type it, then ↩." } != nil
            && launcher.isInScript
        for character in "lea" { await pressKey(character) }
        // ⇥ on the argument: its actions (Next ↩), never Ask on what is typed.
        let argumentFooter = launcher.shownFooter
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let tabActions = await waitUntil(timeout: 1) { launcher.isShowingActions && launcher.shownActions.map(\.title) == ["Next"] } != nil
            && !popover.isVisible && launcher.query == "lea"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !launcher.isShowingActions }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let dropdown = await waitUntil(timeout: 1) { launcher.resultTitles == ["Happy", "Calm"] } != nil
        await captureLauncher(as: "launcher-skillie-dropdown.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let greeted = await waitUntil(timeout: 4) { popover.isVisible && popover.shownText == "Hi lea, you look happy" } != nil
        details.append("arguments asked: \(asked), ↩ without one said so: \(missingSaid), footer \(argumentFooter), ⇥ its actions, no Ask: \(tabActions), dropdown: \(dropdown), output: \(greeted)")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))

        // Inline: the row shows its line once read.
        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "selftest clock" { await pressKey(character) }
        let clock = library.all().first { $0.title == "Selftest Clock" }
        let inline = await waitUntil(timeout: 3) { clock.flatMap(library.inlineLine) == "tick-\(marker)" } != nil
        let inlineRow = launcher.resultTitles.first == "Selftest Clock"
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        details.append("inline: \(inline), row first: \(inlineRow)")

        // In the menu bar (Settings → Skillies): its line there; gone once removed.
        let preferences = context.preferences
        let savedMenuBar = preferences.skilliesInMenuBar
        if let clock { preferences.skilliesInMenuBar = [clock.path] }
        let shownInMenuBar = await waitUntil(timeout: 4) {
            clock.flatMap { self.context.menuBarSkillies.shown[$0.path] } == "tick-\(marker)"
        } != nil
        // Settings → Skillies with them listed: the inline one's switch is on.
        context.settings.show(pane: .skillies)
        let switchOn = await waitUntil(timeout: 2) { self.context.settings.switchStates().contains(true) } != nil
        if let directory = context.snapshotDirectory {
            await pause(600)
            if let png = await context.settings.snapshotPNG() {
                try? png.write(to: directory.appendingPathComponent("settings-skillies-menubar.png"))
            }
        }
        await closeSettings()
        preferences.skilliesInMenuBar = savedMenuBar
        let goneFromMenuBar = await waitUntil(timeout: 2) { clock.flatMap { self.context.menuBarSkillies.shown[$0.path] } == nil } != nil
        details.append("menu bar: \(shownInMenuBar), its switch on in Settings: \(switchOn), removed: \(goneFromMenuBar)")

        // A failure says its last line; no executable bit: the shebang runs it.
        let failing = library.all().first { $0.title == "Failing Selftest" }!
        var failed = false
        if let run = try? await library.run(failing, arguments: []) {
            failed = !run.succeeded && run.status == 3 && ScriptCommand.lastLine(run.output) == "Something broke"
        }
        let plain = library.all().first { $0.title == "Not Executable Selftest" }!
        let shebang = (try? await library.run(plain, arguments: []))?.output.contains("shebang-\(marker)") == true
        details.append("failure: \(failed), shebang: \(shebang)")

        // The "Running…" card while one runs, then its line; one that says
        // `showsRunning false` shows no card until its line.
        var running: [Bool] = []
        var said: [Bool] = []
        for title in ["Slow Selftest", "Quiet Selftest"] {
            guard let command = library.all().first(where: { $0.title == title }) else { continue }
            context.aiActions.runScript?(command, false)
            // The quiet one: no card at all before its line (it prints after 1.5 s).
            running.append(await waitUntil(timeout: 1) {
                popover.isVisible && (title == "Quiet Selftest" || popover.shownText == "Running “\(title)”…")
            } != nil)
            let line = (title == "Slow Selftest" ? "slow-" : "quiet-") + marker
            said.append(await waitUntil(timeout: 5) { popover.isVisible && popover.shownText == line } != nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
        }
        let runningCard = running == [true, false] && said == [true, true]
        details.append("Running… card shown \(running) (default, showsRunning false), line after \(said)")

        // Raycast's Script Command imported: renamed metadata, then it runs.
        let imported: (imported: [String], skipped: Int) = (try? library.importRaycast([raycast])) ?? ([], 0)
        let importedCommand = library.all().first { $0.title == "Imported From Raycast Selftest" }
        let importedText = importedCommand.flatMap { try? String(contentsOfFile: $0.path, encoding: .utf8) } ?? ""
        var importedRuns = false
        if let importedCommand, let run = try? await library.run(importedCommand, arguments: []) {
            importedRuns = run.output.contains("imported-\(marker)")
        }
        let importOK = imported.imported == ["Imported From Raycast Selftest"] && imported.skipped == 1
            && importedText.contains("# @skilli.title") && !importedText.contains("@raycast.") && importedRuns
        details.append("Raycast import: \(importOK) (\(imported.imported.count) imported, \(imported.skipped) skipped)")

        let created = (try? await tools.call("create_skillie", arguments: ["title": "Selftest Echo", "language": "zsh", "code": "echo \"made-$1\"",
                                                                          "arguments": ["Word"], "description": "Says a word back"], run: nil)) ?? "failed"
        let duplicate = (try? await tools.call("create_skillie", arguments: ["title": "Selftest Echo", "language": "bash", "code": "echo again"], run: nil)) == nil
        let toolList = (try? await tools.call("list_skillies", arguments: [:], run: nil)) ?? ""
        let toolListed = toolList.contains("Greet Someone Selftest — arguments: Name, Mood [happy, calm]") && toolList.contains("Selftest Echo: Says a word back — arguments: Word")
        let toolRun = (try? await tools.call("run_skillie", arguments: ["title": "Greet Someone Selftest", "arguments": ["Max", "calm"]], run: nil)) ?? "failed"
        let echoed = (try? await tools.call("run_skillie", arguments: ["title": "Selftest Echo", "arguments": ["zebra"]], run: nil)) ?? "failed"
        let missing = (try? await tools.call("run_skillie", arguments: ["title": "Greet Someone Selftest"], run: nil)) == nil
        details.append("tools: created “\(created.prefix(60))”, duplicate refused: \(duplicate), listed \(toolListed), ran “\(toolRun)”, created one ran “\(echoed)”, missing argument refused: \(missing)")

        // Settings → Skillies lists them, for design review.
        context.settings.show(pane: .skillies)
        await pause(500)
        if let directory = context.snapshotDirectory, let png = await context.settings.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent("settings-skillies-listed.png"))
        }
        await closeSettings()

        record(name, listed && hello && lastLine && asked && missingSaid && argumentFooter == ["Next ↩", "Actions ⌘K"] && tabActions && dropdown && greeted && inline && inlineRow && shownInMenuBar && switchOn && goneFromMenuBar && failed && shebang && runningCard && importOK
               && created.hasPrefix("Created the skillie “Selftest Echo”") && duplicate && toolListed && toolRun == "Hi Max, you look calm"
               && echoed == "made-zebra" && missing, details.joined(separator: "; "), nil)
    }

    /// A `.skilli` file opened in skil.li (docs/skillie-files.md): Settings
    /// → Skillies shows it whole, with where it came from, before Add; Add
    /// writes it into the folder, listed and run; the same file again has
    /// nothing to add; a new version replaces it in place; a file that is
    /// not a skillie says why.
    private func skillieFilesAdded() async {
        let name = "Skillie files: a .skilli shown whole (where from, its code) before Add; added, run; the same again nothing to add; a new version replaces it in place; not a skillie said"
        guard let library = context.tools.tools.scripts else {
            record(name, false, "no skillies library", nil)
            return
        }
        let settings = context.settings
        let model = settings.skillies
        let manager = FileManager.default
        let scratch = manager.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/skillie-files", isDirectory: true)
        try? manager.createDirectory(at: scratch, withIntermediateDirectories: true)
        defer { try? manager.removeItem(at: scratch) }
        let marker = String((0..<5).map { _ in "abcdefghijklmnopqrstuvwxyz".randomElement()! })
        let text = "#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title Selftest From A File\n# @skilli.mode compact\n# @skilli.icon 📦\n"
            + "# @skilli.description Says where it came from.\n# @skilli.needsConfirmation true\n\necho from-file-\(marker)\n"
        let file = scratch.appendingPathComponent("Selftest From A File.skilli")
        try? text.write(to: file, atomically: true, encoding: .utf8)
        // Where it came from, as a browser writes it on the file.
        if let whereFrom = try? PropertyListSerialization.data(fromPropertyList: ["https://example.com/skillies/from-a-file.skilli", "https://example.com/skillies"],
                                                                format: .binary, options: 0) {
            _ = whereFrom.withUnsafeBytes { setxattr(file.path, "com.apple.metadata:kMDItemWhereFroms", $0.baseAddress, whereFrom.count, 0, 0) }
        }
        func sheetGone() async { _ = await waitUntil(timeout: 2) { !NSApp.windows.contains { $0.isVisible && $0.isSheet } } }

        settings.show(pane: .skillies)
        await model.receive(files: [file])
        let sheet = await waitUntil(timeout: 2) { NSApp.windows.contains { $0.isVisible && $0.isSheet } } != nil
        let candidate = model.pendingImport.first
        let whole = model.pendingImport.count == 1 && candidate?.source == "example.com" && candidate?.checked.fileName == "selftest-from-a-file.sh"
            && candidate?.checked.text == text && candidate?.replacing == nil && candidate?.same == false
        await pause(500)
        await captureSettingsBothWays(as: "settings-skillies-import")
        let pressed = Self.pressLastButton(labelled: "Add Skillie")
        let added = await waitUntil(timeout: 2) { library.all().contains { $0.title == "Selftest From A File" } } != nil
        let installed = library.all().first { $0.title == "Selftest From A File" }
        let named = installed?.path.hasSuffix("/selftest-from-a-file.sh") == true
        var ran = false
        if let installed, let run = try? await library.run(installed, arguments: []) { ran = run.output.contains("from-file-\(marker)") }
        await sheetGone()
        var details = ["sheet \(sheet), shown whole \(whole) (from \(candidate?.source ?? "-"), as \(candidate?.checked.fileName ?? "-")), Add pressed \(pressed), added \(added) as \(installed.map { ($0.path as NSString).lastPathComponent } ?? "-") \(named), runs \(ran) \(model.importErrors.joined(separator: " "))"]

        // The same file again: nothing to add, no button.
        await model.receive(files: [file])
        let same = model.pendingImport.first?.same == true && model.toAdd.isEmpty
        model.isImporting = false
        await sheetGone()

        // A new version (its title kept): Replace, in place.
        let newer = text.replacingOccurrences(of: "from-file-", with: "replaced-")
        try? newer.write(to: file, atomically: true, encoding: .utf8)
        await model.receive(files: [file])
        let replacing = installed != nil && model.pendingImport.first?.replacing?.path == installed?.path
        await pause(400)
        let replacePressed = Self.pressLastButton(labelled: "Replace Skillie")
        let replaced = await waitUntil(timeout: 2) { installed.flatMap { try? String(contentsOfFile: $0.path, encoding: .utf8) } == newer } != nil
            && library.all().filter { $0.title == "Selftest From A File" }.count == 1
        await sheetGone()
        details.append("same again: nothing to add \(same); new version: replaces \(replacing), Replace pressed \(replacePressed), in place \(replaced)")

        // Not a skillie: said in words, nothing to add.
        let notes = scratch.appendingPathComponent("notes.skilli")
        try? "Just notes, no shebang.\n".write(to: notes, atomically: true, encoding: .utf8)
        await model.receive(files: [notes])
        let refusal = model.importErrors.first ?? ""
        let said = model.toAdd.isEmpty && refusal.hasPrefix("notes.skilli: Its first line does not say what runs it")
        await pause(400)
        await captureSettingsBothWays(as: "settings-skillies-import-refused")
        model.isImporting = false
        await sheetGone()
        details.append("not a skillie said: \(said) “\(refusal)”")
        await closeSettings()
        if let installed { try? manager.removeItem(atPath: installed.path) }

        record(name, sheet && whole && pressed && added && named && ran && same && replacing && replacePressed && replaced && said,
               details.joined(separator: "; "), nil)
    }

    /// An agent writes a skillie when asked: Claude Code (Haiku) calls
    /// create_skillie, allowed in the card; the new skillie is listed and
    /// prints today's date.
    private func agentCreatesSkillie() async {
        let name = "Skillies: an agent asked for a command writes one with create_skillie (allowed in the card); it is listed and runs"
        await context.ai.refresh()
        guard let library = context.tools.tools.scripts else {
            record(name, false, "no skillies library", nil)
            return
        }
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .auto
        let command = scratchCommand(
            prompt: "Create a skil.li skillie titled “Selftest Today” in zsh that prints today's date as YYYY-MM-DD, with a one-sentence description. Then reply with just: Done.",
            output: .card
        )
        var act = command
        act.tools = ["actions"]
        act.model = .claude("haiku")
        context.aiCommands.save(act)
        defer {
            settings.mode = mode
            context.aiCommands.delete(command.id)
            if let made = library.all().first(where: { $0.title == "Selftest Today" }) { try? FileManager.default.removeItem(atPath: made.path) }
        }
        let start = ContinuousClock.now
        guard await run(act, on: "") else {
            record(name, false, "the card did not show", nil)
            return
        }
        var approvals = 0
        var asking = await waitUntil(timeout: 60, { popover.phase == .approving }) != nil
        while asking, approvals < 3 {
            approvals += 1
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            await pause(500)
            let settled = await waitUntil(timeout: 30) { popover.phase == .approving || popover.phase == .done || popover.phase == .failed } != nil
            asking = settled && popover.phase == .approving
        }
        _ = await waitUntil(timeout: 45) { popover.phase == .done || popover.phase == .failed }
        let latency = ContinuousClock.now - start
        let steps = context.aiActions.lastSteps.map(\.title)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let made = library.all().first { $0.title == "Selftest Today" }
        var output = ""
        if let made, let run = try? await library.run(made, arguments: []) { output = run.output.trimmingCharacters(in: .whitespacesAndNewlines) }
        let formatter = DateFormatter()
        formatter.dateFormat = "yyyy-MM-dd"
        let today = formatter.string(from: .now)
        record(name, made != nil && output.contains(today),
               "steps \(steps), approvals \(approvals), created: \(made != nil) (\(made?.description ?? "")), it printed “\(output)”, \(Int(latency.milliseconds / 1_000)) s", latency.milliseconds)
    }

    /// Clean Keyboard from the launcher: typed keys and Shift never reach
    /// the test window behind the glass card; a real click on Done turns
    /// them back on; the end of the countdown too.
    private func cleanKeyboardBlocksKeys() async {
        let name = "Clean Keyboard: from the launcher, keys and Shift kept from the apps behind a glass card; a click on Done and the countdown's end turn them back on"
        guard let cleaner = context.aiActions.systemCommands?.cleaner else {
            record(name, false, "no system commands", nil)
            return
        }
        // Whatever happens, the keys come back.
        defer { cleaner.stop() }
        guard await focusTestWindow() else { return }
        // The keys typed below land in the text view, not in a control an
        // earlier check left the keyboard on (late in the ai group).
        window.makeFirstResponder(textView)
        textView.string = ""
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "clean keyboard" { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { self.context.launcher.resultTitles.first == "Clean Keyboard" } != nil
        await pressKey(nil, code: CGKeyCode(listed ? kVK_Return : kVK_Escape))
        let started = await waitUntil(timeout: 2) { cleaner.isCleaning } != nil
        guard started, await focusTestWindow() else {
            record(name, false, "listed: \(listed), started: \(started)", nil)
            return
        }
        for character in "abc" { await pressKey(character) }
        await pressKey("a", flags: .maskShift)
        await pause(300)
        let swallowed = cleaner.swallowed
        let kept = textView.string.isEmpty && swallowed >= 6

        // The card alone, over the test window (centered behind it).
        if let overlay = cleaner.overlay, let card = overlay.contentView?.subviews.first, let directory = context.snapshotDirectory {
            let frame = overlay.convertToScreen(card.convert(card.bounds, to: nil)).insetBy(dx: -40, dy: -40)
            if window.frame.contains(frame), let image = await GlassCheck.screenshot(of: frame),
               let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("clean-keyboard.png"))
            }
        }
        // A real click on Done: the mouse still works.
        var clicked = false
        if let overlay = cleaner.overlay, let done = Self.button(in: overlay.contentView, label: "Done Cleaning") {
            let frame = overlay.convertToScreen(done.convert(done.bounds, to: nil))
            let height = NSScreen.screens.first?.frame.height ?? 0
            let point = CGPoint(x: frame.midX, y: height - frame.midY)
            let source = CGEventSource(stateID: .hidSystemState)
            for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
                CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
                await pause(60)
            }
            clicked = await waitUntil(timeout: 1) { !cleaner.isCleaning } != nil
        }
        guard await focusTestWindow() else { return }
        await pressKey("z")
        let back = await waitUntil(timeout: 1) { self.textView.string == "z" } != nil

        try? cleaner.start(seconds: 1)
        let ended = await waitUntil(timeout: 3) { !cleaner.isCleaning } != nil
        record(name, listed && started && kept && clicked && back && ended,
               "listed: \(listed), started: \(started), kept from the window: \(kept) (\(swallowed) events), Done clicked: \(clicked), keys back: \(back) (text “\(textView.string)”), ended by the countdown: \(ended)", nil)
    }

    private static func button(in view: NSView?, label: String) -> NSButton? {
        guard let view else { return nil }
        if let button = view as? NSButton, button.accessibilityLabel() == label { return button }
        for child in view.subviews {
            if let found = button(in: child, label: label) { return found }
        }
        return nil
    }

    /// Recent projects from a scratch Cursor and Zed (their own file
    /// formats, nothing of the Mac's editors read): "alpha <tag>" finds the
    /// Cursor one, Return opens it there (recorded); Search Projects lists
    /// both, ⌘Return shows one in Finder; agents list and open.
    private func editorProjectsFound() async {
        let name = "Projects: Cursor's and Zed's recent folders found by name, Return opens in the editor, Search Projects lists both; agents list and open"
        let tag = String((0..<5).map { _ in "abcdefghijklmnopqrstuvwxyz".randomElement()! })
        let base = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())-projects", isDirectory: true)
        defer { try? FileManager.default.removeItem(at: base) }
        let alpha = base.appendingPathComponent("code/alpha-\(tag)", isDirectory: true)
        let beta = base.appendingPathComponent("code/beta-\(tag)", isDirectory: true)
        let root = base.appendingPathComponent("Application Support", isDirectory: true)
        let cursorDB = root.appendingPathComponent("Cursor/User/globalStorage/state.vscdb")
        let zedDB = root.appendingPathComponent("Zed/db/0-stable/db.sqlite")
        for folder in [alpha, beta, cursorDB.deletingLastPathComponent(), zedDB.deletingLastPathComponent()] {
            try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        }
        let recent = #"{"entries":[{"folderUri":"\#(alpha.absoluteString)"},{"fileUri":"file:///tmp/notes.md"},{"folderUri":"vscode-remote://ssh-remote%2Bbox/srv/app"}]}"#
        await Self.run("/usr/bin/sqlite3", [cursorDB.path, "CREATE TABLE ItemTable (key TEXT UNIQUE ON CONFLICT REPLACE, value BLOB); INSERT INTO ItemTable VALUES ('history.recentlyOpenedPathsList', '\(recent)');"])
        await Self.run("/usr/bin/sqlite3", [zedDB.path, "CREATE TABLE workspaces (workspace_id INTEGER PRIMARY KEY, paths TEXT, remote_connection_id INTEGER, timestamp TEXT DEFAULT CURRENT_TIMESTAMP NOT NULL); INSERT INTO workspaces (paths) VALUES ('\(beta.path)');"])
        let installed: Set<String> = ["com.todesktop.230313mzl4w4u92", "dev.zed.Zed"]
        let projects = EditorProjects(root: root, installed: { installed.contains($0) ? URL(fileURLWithPath: "/Applications") : nil })
        let found = projects.all().map { "\($0.name) (\($0.editor))" }
        let read = Set(found) == ["alpha-\(tag) (Cursor)", "beta-\(tag) (Zed)"]

        let launcher = context.launcher
        let tools = context.tools.tools
        let saved = (launcher.projects, launcher.onOpenProject, tools.projects, tools.openProject)
        defer { (launcher.projects, launcher.onOpenProject, tools.projects, tools.openProject) = saved }
        var opened: [String] = []
        launcher.projects = { projects.all() }
        launcher.onOpenProject = { project, reveal in opened.append("\(project.name) \(reveal ? "Finder" : project.editor)") }
        tools.projects = projects
        tools.openProject = { opened.append("tool \($0.name) \($0.editor)") }

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "alpha \(tag)" { await pressKey(character) }
        let byName = await waitUntil(timeout: 1) { launcher.resultTitles.first == "alpha-\(tag)" } != nil
        if byName { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let openedInCursor = opened.last == "alpha-\(tag) Cursor"

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "search projects" { await pressKey(character) }
        _ = await waitUntil(timeout: 1) { launcher.resultTitles.first == "Search Projects" }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let mode = await waitUntil(timeout: 1) { launcher.isInProjects } != nil
        for character in tag { await pressKey(character) }
        let listed = await waitUntil(timeout: 1) { Set(launcher.resultTitles) == ["alpha-\(tag)", "beta-\(tag)"] } != nil
        await captureLauncher(as: "launcher-projects.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskCommand)
        let shown = await waitUntil(timeout: 1) { opened.last?.hasSuffix("Finder") == true } != nil
        await closeLauncher()

        let listing = (try? await tools.call("list_projects", arguments: [:], run: nil)) ?? ""
        let toolListed = listing.contains("alpha-\(tag) — Cursor — \(alpha.path)") && listing.contains("beta-\(tag) — Zed")
        let said = (try? await tools.call("open_project", arguments: ["name": "beta-\(tag)"], run: nil)) ?? "failed"
        let toolOpened = opened.last == "tool beta-\(tag) Zed"

        record(name, read && byName && openedInCursor && mode && listed && shown && toolListed && toolOpened,
               "read: \(found.joined(separator: ", ")); “alpha \(tag)” first: \(byName), opened: \(opened.first ?? "nothing"); Projects mode: \(mode), both listed: \(listed), ⌘Return shows in Finder: \(shown); tools: listed \(toolListed), “\(said)”", nil)
    }

    /// Ask opens a recent project in its editor, from a fixed list (nothing
    /// of the Mac's editors read, nothing opened); an app alone stays an
    /// app. Decided only.
    private func askOpensProjects() async {
        let home = NSHomeDirectory()
        func project(_ path: String, _ editor: String, _ bundleID: String, _ rank: Int) -> EditorProject {
            EditorProject(path: home + path, kind: .folder, editor: editor, bundleID: bundleID, rank: rank)
        }
        let cursor = "com.todesktop.230313mzl4w4u92", zed = "dev.zed.Zed"
        let projects = [project("/Documents/Github/skilli", "Cursor", cursor, 0), project("/Code/nimbus-api", "Zed", zed, 0),
                        project("/Code/nimbus-web", "Cursor", cursor, 1), project("/Sites/portfolio", "Sublime Text", "com.sublimetext.4", 0),
                        project("/dotfiles", "Cursor", cursor, 2)]
        let cases = [("ouvre le projet skilli dans cursor", projects[0]), ("je veux bosser sur l'api nimbus", projects[1]),
                     ("ouvre mon portfolio", projects[3])]
        // Requests about something else never open a project, whatever the
        // route ("met la chanson suivante" once opened one at 0 %).
        let elsewhere = ["met la chanson suivante", "quelle heure est-il à Tokyo", "mets le son plus fort", "verrouille l'écran"]
        for provider in DecisionProvider.allCases {
            let name = "Ask opens recent projects in their editor with \(provider.title) (decided only, nothing opened); other requests never open one"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = true
            var slowest: Duration = .zero
            for (instruction, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: [], projects: projects,
                                                      keys: [provider: key])
                slowest = max(slowest, .now - start)
                let picked = decision?.command?.command.rawValue
                passed = passed && decision?.route == .command && picked == MacAction.project(expected).rawValue
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(decision?.command?.command.title ?? "")"
                    + (decision?.command.map { " (\(Int($0.probability * 100)) %)" } ?? ""))
            }
            for instruction in elsewhere {
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: [], projects: projects,
                                                      keys: [provider: key])
                var opensProject = false
                if case .project? = decision?.command?.command { opensProject = true }
                passed = passed && decision != nil && !opensProject
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(decision?.command?.command.title ?? "")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// Ask runs one of the user's scripts by what it does, from a fixed list
    /// (nothing run). Decided only.
    private func askRunsScripts() async {
        func script(_ title: String, _ description: String) -> ScriptCommand {
            ScriptCommand.parse("#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title \(title)\n# @skilli.mode compact\n# @skilli.description \(description)\n",
                                path: "/tmp/\(title).sh")!
        }
        let scripts = [script("Backup Photos", "Copies the photo library to the NAS"), script("Restart Wi-Fi", "Turns Wi-Fi off and on again"),
                       script("Deploy Website", "Builds the site and uploads it"), script("Clear DNS Cache", "Flushes the DNS cache")]
        let cases = [("lance la sauvegarde de mes photos", scripts[0]), ("relance le wifi", scripts[1]), ("mets le site en ligne", scripts[2])]
        for provider in DecisionProvider.allCases {
            let name = "Ask runs the user's skillies by what they do with \(provider.title) (decided only, nothing run)"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = true
            var slowest: Duration = .zero
            for (instruction, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: [], scripts: scripts,
                                                      keys: [provider: key])
                slowest = max(slowest, .now - start)
                passed = passed && decision?.route == .command && decision?.command?.command == .script(expected)
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(decision?.command?.command.title ?? "")"
                    + (decision?.command.map { " (\(Int($0.probability * 100)) %)" } ?? ""))
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// Ask runs one of the user's shortcuts (Apple's Shortcuts app) by its
    /// name, from a fixed list of 64 made-up ones (two questions; nothing
    /// run); a request for something else picks none. Decided only.
    private func askRunsShortcuts() async {
        // 60 others first: the ones asked for are in the second question.
        let names = (1...60).map { "Filler \($0)" } + ["Morning Routine", "Text Camille I'm Late", "Log Water", "Resize Images for the Web"]
        let shortcuts = names.enumerated().map { index, name in
            AppleShortcut(id: String(format: "00000000-0000-4000-8000-%012d", index), name: name)
        }
        // By its name, said as people say it; a shortcut is named, not
        // guessed ("préviens Camille…" is as much a message to send).
        let cases = [("lance ma routine du matin", shortcuts[60]), ("lance le raccourci log water", shortcuts[62]),
                     ("redimensionne mes images pour le web avec mon raccourci", shortcuts[63])]
        let elsewhere = ["mets le son à 30 %"]
        for provider in DecisionProvider.allCases {
            let name = "Ask runs the user's shortcuts by their names with \(provider.title) (decided only, nothing run)"
            guard let key = userDecisionKeys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = true
            var slowest: Duration = .zero
            for (instruction, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: [], shortcuts: shortcuts,
                                                      keys: [provider: key])
                slowest = max(slowest, .now - start)
                passed = passed && decision?.route == .command && decision?.command?.command == .shortcut(expected, withSelection: false)
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(decision?.command?.command.description ?? "")"
                    + (decision?.command.map { " (\(Int($0.probability * 100)) %)" } ?? ""))
            }
            for instruction in elsewhere {
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: [], shortcuts: shortcuts,
                                                      keys: [provider: key])
                var runsOne = false
                if case .shortcut? = decision?.command?.command { runsOne = true }
                passed = passed && decision != nil && !runsOne
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(decision?.command?.command.title ?? "")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// Ask hears which sound device: the built-in speakers and the display
    /// when the Mac has exactly one of each. Decided only, nothing switched.
    private func askSwitchesSound() async {
        let outputs = AudioDevices.devices(output: true)
        var cases: [(String, MacAction)] = []
        let builtIn = outputs.filter { $0.transport == .builtIn }
        if builtIn.count == 1 {
            let speakers = MacAction.sound(AudioTarget(builtIn[0], output: true))
            cases += [("mets le son sur les haut-parleurs du Mac", speakers), ("bascule l'audio sur les enceintes intégrées", speakers)]
        }
        let displays = outputs.filter { $0.transport == .display }
        if displays.count == 1 {
            let screen = MacAction.sound(AudioTarget(displays[0], output: true))
            cases += [("passe le son sur l'écran", screen), ("je veux entendre le son sur la télé", screen)]
        }
        for provider in DecisionProvider.allCases {
            let name = "Ask picks the sound output with \(provider.title) (decided only, nothing switched)"
            guard let key = userDecisionKeys[provider], !cases.isEmpty else {
                let why = cases.isEmpty ? "no single built-in or display output on this Mac" : "no \(provider.title) key saved in Settings"
                checks.append(Check(name: name, passed: true, skipped: true, detail: why, latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = true
            var slowest: Duration = .zero
            for (instruction, expected) in cases {
                let start = ContinuousClock.now
                let decision = await AskRouter.decide(instruction, hasSelection: false, app: "Finder", menu: [], apps: [],
                                                      settings: SystemSettingsPanes.all(), keys: [provider: key])
                slowest = max(slowest, .now - start)
                passed = passed && decision?.route == .command && decision?.command?.command == expected
                details.append("“\(instruction)” → \(decision?.route.rawValue ?? "failed") \(decision?.command?.command.title ?? "")"
                    + (decision?.command.map { " (\(Int($0.probability * 100)) %)" } ?? ""))
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// A sound output found in the launcher by its name and switched with
    /// Return; agents list the devices and switch one; the output macOS
    /// used is put back after each. Changes where the sound goes: Mac mini.
    /// Ask "mets le son à 30 %": the level set at once, no model, said in
    /// the card (macOS shows nothing); put back after.
    private func askSetsTheVolume() async {
        let name = "Ask: “mets le son à 30 %” sets the volume (the level read by the model), nothing said; unsure, set with ⌘Z to put it back"
        guard let original = SystemCommands.volume else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "this output has no volume", latencyMs: nil))
            return
        }
        let target = original == 30 ? 35 : 30
        // The route and the level as the model reads them (real ones in
        // `selftest decide`).
        context.aiActions.decisionOverride = AskRouter.Decision(route: .command, confidence: 0.95, menu: [], routes: [(.command, 0.95)],
                                                                command: (.volume(AskRouter.levelToRead), 0.93),
                                                                commands: [(.volume(AskRouter.levelToRead), 0.93)], label: "Test")
        context.aiActions.valuesOverride = ["level": .init(choice: "\(target)", confidence: 0.96)]
        defer {
            context.aiActions.decisionOverride = nil
            context.aiActions.valuesOverride = nil
            _ = try? SystemCommands.setVolume(original)
        }
        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        guard await openAsk() else {
            record(name, false, "no question in the card", nil)
            return
        }
        for character in "mets le son à \(target) %" { await pressKey(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let set = await waitUntil(timeout: 2) { SystemCommands.volume == target } != nil
        // Sure of the level: set, and the card goes without a word.
        let quiet = await waitUntil(timeout: 1) { !self.context.aiActions.popover.isVisible } != nil
        if context.aiActions.popover.isVisible { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        // Unsure: set all the same, said with ⌘Z, which puts the level back.
        let unsure = target == 30 ? 45 : 30
        context.aiActions.valuesOverride = ["level": .init(choice: "\(unsure)", confidence: 0.4)]
        context.aiActions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": "mets le son à \(unsure) %"])
        let popover = context.aiActions.popover
        let unsureSet = await waitUntil(timeout: 2) {
            SystemCommands.volume == unsure && popover.isVisible && popover.shownTitle == "Volume Set" && popover.hintTitles == ["Undo", "Close"]
        } != nil
        await pressKey("z", flags: .maskCommand)
        let putBack = await waitUntil(timeout: 2) { SystemCommands.volume == target && !popover.isVisible } != nil
        record(name, set && quiet && context.aiActions.lastRoute == .command && unsureSet && putBack,
               "set \(set) (\(SystemCommands.volume.map(String.init) ?? "?")), nothing said \(quiet); unsure \(unsure) %: set with Undo \(unsureSet), ⌘Z back to \(target) %: \(putBack); back to \(original)", nil)
    }

    private func soundDevicesSwitch() async {
        let name = "Sound: an output typed in the launcher and switched with Return, nothing said; agents list and switch; the original put back"
        let outputs = AudioDevices.devices(output: true)
        guard let original = AudioDevices.current(output: true),
              let target = outputs.first(where: { $0.uid != original.uid && $0.transport == .builtIn })
                ?? outputs.first(where: { $0.uid != original.uid })
        else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "fewer than two sound outputs", latencyMs: nil))
            return
        }
        defer { _ = try? AudioDevices.select(uid: original.uid, output: true) }
        // Two words of its name, as a person types them ("haut parleurs"):
        // one alone can be a window place's ("haut"). A microphone of the
        // same name (AirPods, NDI Audio) scores the same: the output comes
        // first all the same.
        let sharesName = AudioDevices.devices(output: false).contains { $0.name == target.name }
        let word = target.name.lowercased().split(whereSeparator: { !$0.isLetter }).prefix(2).joined(separator: " ")
        let title = AudioRoute.title(name: target.name, output: true)
        let launcher = context.launcher

        guard await focusTestWindow() else { return }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in word { await pressKey(character) }
        let listed = await waitUntil(timeout: 2) { launcher.resultTitles.first == title } != nil
        let shown = launcher.resultTitles.prefix(3).joined(separator: ", ")
        var switched = false
        if listed {
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            switched = await waitUntil(timeout: 3) { AudioDevices.current(output: true)?.uid == target.uid } != nil
        } else {
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
        }
        _ = try? AudioDevices.select(uid: original.uid, output: true)
        // Switched: nothing said.
        await pause(300)
        let quiet = !context.aiActions.popover.isVisible
        if !quiet { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }

        let tools = context.tools.tools
        let listing = (try? await tools.call("list_audio_devices", arguments: [:], run: nil)) ?? ""
        let toolListed = listing.contains("Output: \(target.name) (") && listing.contains("Output: \(original.name) (") && listing.contains("· in use")
        let said = (try? await tools.call("set_audio_device", arguments: ["device": target.name], run: nil)) ?? "failed"
        let toolSwitched = AudioDevices.current(output: true)?.uid == target.uid
        _ = try? AudioDevices.select(uid: original.uid, output: true)
        let restored = AudioDevices.current(output: true)?.uid == original.uid
        record(name, listed && switched && quiet && toolListed && toolSwitched && restored,
               "“\(word)”\(sharesName ? " (a microphone has the same name)" : "") → \(listed ? title : "not first (\(shown))"), switched: \(switched), nothing said: \(quiet); tools: listed \(toolListed), “\(said)”, switched \(toolSwitched); back on \(original.name): \(restored)", nil)
    }

    /// Ask by Voice's AVAudioEngine leaves CoreAudio's aggregate of the
    /// default input and output in skil.li ("CADefaultDeviceAggregate-
    /// <pid>-<n>") until it quits; it was listed and switched to as a sound
    /// output. A private aggregate of the built-in output stands in for it
    /// (nothing played, removed after); CoreAudio's own is checked too when
    /// the microphone ran before (`ai`).
    private func privateAggregatesLeftOut() async {
        let name = "Sound: an aggregate private to skil.li (what the microphone leaves behind) is never listed; the Mac's own devices are"
        guard let builtIn = AudioDevices.devices(output: true).first(where: { $0.transport == .builtIn }) else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no built-in output to build one on", latencyMs: nil))
            return
        }
        let description: [String: Any] = [
            kAudioAggregateDeviceUIDKey: "li.skil.selftest.aggregate-\(getpid())",
            kAudioAggregateDeviceNameKey: "skil.li self-test aggregate",
            kAudioAggregateDeviceIsPrivateKey: 1,
            kAudioAggregateDeviceSubDeviceListKey: [[kAudioSubDeviceUIDKey: builtIn.uid]]
        ]
        var id = AudioObjectID(kAudioObjectUnknown)
        let status = AudioHardwareCreateAggregateDevice(description as CFDictionary, &id)
        guard status == noErr else {
            record(name, false, "CoreAudio did not make the aggregate (\(status))", nil)
            return
        }
        defer { AudioHardwareDestroyAggregateDevice(id) }
        // An output, like the one the microphone leaves: only being private
        // can leave it out.
        let playable = await waitUntil(timeout: 2) { Self.outputStreamCount(id) > 0 } != nil
        let leftOut = AudioDevices.device(id) == nil
        let kept = AudioDevices.device(builtIn.id) != nil
        let coreAudios = Self.audioDeviceIDs().filter { Self.audioUID($0)?.hasPrefix("CADefaultDeviceAggregate") == true }
        let listed = AudioDevices.all().filter { $0.uid.hasPrefix("CADefaultDeviceAggregate") }.map(\.name)
        record(name, playable && leftOut && kept && listed.isEmpty,
               "stand-in has an output: \(playable), left out: \(leftOut); \(builtIn.name) kept: \(kept); CoreAudio's default-device aggregates here: \(coreAudios.count), listed: \(listed.isEmpty ? "none" : listed.joined(separator: ", "))", nil)
    }

    private static func audioDeviceIDs() -> [AudioObjectID] {
        var address = AudioObjectPropertyAddress(mSelector: kAudioHardwarePropertyDevices, mScope: kAudioObjectPropertyScopeGlobal,
                                                 mElement: kAudioObjectPropertyElementMain)
        var size: UInt32 = 0
        guard AudioObjectGetPropertyDataSize(AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size) == noErr, size > 0 else { return [] }
        var ids = [AudioObjectID](repeating: 0, count: Int(size) / MemoryLayout<AudioObjectID>.stride)
        guard AudioObjectGetPropertyData(AudioObjectID(kAudioObjectSystemObject), &address, 0, nil, &size, &ids) == noErr else { return [] }
        return ids
    }

    private static func audioUID(_ id: AudioObjectID) -> String? {
        var address = AudioObjectPropertyAddress(mSelector: kAudioDevicePropertyDeviceUID, mScope: kAudioObjectPropertyScopeGlobal,
                                                 mElement: kAudioObjectPropertyElementMain)
        var size = UInt32(MemoryLayout<Unmanaged<CFString>?>.size)
        var uid: Unmanaged<CFString>?
        let status = withUnsafeMutablePointer(to: &uid) { AudioObjectGetPropertyData(id, &address, 0, nil, &size, $0) }
        guard status == noErr, let uid else { return nil }
        return uid.takeRetainedValue() as String
    }

    private static func outputStreamCount(_ id: AudioObjectID) -> Int {
        var address = AudioObjectPropertyAddress(mSelector: kAudioDevicePropertyStreams, mScope: kAudioObjectPropertyScopeOutput,
                                                 mElement: kAudioObjectPropertyElementMain)
        var size: UInt32 = 0
        guard AudioObjectGetPropertyDataSize(id, &address, 0, nil, &size) == noErr else { return 0 }
        return Int(size) / MemoryLayout<AudioStreamID>.stride
    }

    /// The recipes' edges, without touching the user's apps: Finder has no
    /// update path; send_message refuses an app it cannot drive. (Sending
    /// through Slack is checked by hand: it would open a real conversation.)
    private func recipesAnswerClearly() async {
        let name = "Recipes: update_app sends macOS's own apps to Software Update; send_message names what it supports"
        let tools = context.tools.tools
        // Finder updates with macOS: the answer says so (and opens Software
        // Update, harmless).
        let update = (try? await tools.call("update_app", arguments: ["name": "Finder"], run: nil)) ?? "failed"
        var refused = ""
        do {
            _ = try await tools.call("send_message", arguments: ["app": "Teams", "to": "Thomas", "text": "Hi"], run: nil)
        } catch {
            refused = error.localizedDescription
        }
        record(name, update.contains("part of macOS") && refused.contains("Slack and Discord"),
               "update_app Finder → “\(update)”; send_message Teams → “\(refused)”", nil)
    }

    /// The real router on the user's own decision keys (read only): what
    /// the user types picks answer, rewrite or act, with recent projects and
    /// skillies in the request as in real use (none of them pulled in).
    /// Ask's route on volume: every request of `AskRouteCorpus` on each
    /// decision key, with what a real Mac sends along (Finder in front and
    /// its menus, installed apps, recent projects, skillies, shortcuts,
    /// System Settings' panes, connected services). Right per route, for
    /// the half a change may be tuned on and for the half it never is;
    /// only the tuned half's misses are listed, with the routes'
    /// probabilities. Decided only, nothing opened.
    private func askRoutesOnVolume() async {
        var menu: [MenuReader.Item] = []
        if let finder = NSRunningApplication.runningApplications(withBundleIdentifier: "com.apple.finder").first {
            let pid = finder.processIdentifier
            menu = await Task.detached { MenuReader.shareableItems(pid: pid) }.value
        }
        let home = NSHomeDirectory()
        func project(_ path: String, _ editor: String, _ bundleID: String, _ rank: Int) -> EditorProject {
            EditorProject(path: home + path, kind: .folder, editor: editor, bundleID: bundleID, rank: rank)
        }
        let cursor = "com.todesktop.230313mzl4w4u92"
        let projects = [project("/Documents/Github/skilli", "Cursor", cursor, 0), project("/Code/nimbus-api", "Zed", "dev.zed.Zed", 0),
                        project("/Code/nimbus-web", "Cursor", cursor, 1), project("/Sites/portfolio", "Sublime Text", "com.sublimetext.4", 0),
                        project("/dotfiles", "Cursor", cursor, 2)]
        let scripts = [("Backup Photos", "Copies the photo library to the NAS"), ("Restart Wi-Fi", "Turns Wi-Fi off and on again"),
                       ("Deploy Website", "Builds the site and uploads it"), ("Clear DNS Cache", "Flushes the DNS cache")].compactMap { title, description in
            ScriptCommand.parse("#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title \(title)\n# @skilli.mode compact\n# @skilli.description \(description)\n",
                                path: "/tmp/\(title).sh")
        }
        let shortcuts = ["Morning Routine", "Log Water", "Start Focus Session", "Envoyer mon heure d'arrivée"].enumerated()
            .map { AppleShortcut(id: "volume-\($0.offset)", name: $0.element) }
        // Apps a Mac commonly has, with the kind their Info.plist gives.
        let apps = [("Safari", "web browser"), ("Google Chrome", "web browser"), ("Arc", "web browser"), ("Mail", "productivity"), ("Calendar", "productivity"),
                    ("Notes", "productivity"), ("Reminders", "productivity"), ("Clock", "utilities"), ("Photos", "photography"),
                    ("Music", "music"), ("Messages", "social networking"), ("Preview", "graphics design"), ("TextEdit", "productivity"),
                    ("Calculator", "utilities"), ("System Settings", "utilities"), ("Terminal", "developer tools"), ("Xcode", "developer tools"),
                    ("Cursor", "developer tools"), ("Zed", "developer tools"), ("Sublime Text", "developer tools"),
                    ("Visual Studio Code", "developer tools"), ("Slack", "business"), ("Zoom", "business"), ("Notion", "productivity"),
                    ("Spotify", "music"), ("Figma", "graphics design"), ("Affinity Designer 2", "graphics design"), ("Keynote", "productivity"),
                    ("Pages", "productivity"), ("Numbers", "productivity"), ("1Password", "productivity"), ("Obsidian", "productivity"),
                    ("WhatsApp", "social networking")]
            .map { AppCandidates.App(name: $0.0, url: URL(fileURLWithPath: "/Applications/\($0.0).app"), kind: $0.1) }
        let settings = SystemSettingsPanes.all()
        let services: [(name: String, tools: [String])] = [
            (name: "nimbus-deployment", tools: ["whoami", "listUsers", "listDeployments", "getDeployment", "listMilestones", "listTasks", "getTask",
                                               "createTask", "updateTask", "createDeployment", "setFeatureFlag", "listAuditLog"]),
            (name: "linear", tools: ["list_issues", "get_issue", "create_issue", "list_projects"])
        ]
        func item(_ decision: AskRouter.Decision?) -> String? {
            switch decision?.command?.command {
            case .project(let project)?: project.name
            case .script(let script)?: script.title
            case .shortcut(let shortcut, _)?: shortcut.name
            default: nil
            }
        }
        // A missed command says which one ran: a pane opened, or another command.
        func picked(_ decision: AskRouter.Decision?) -> String? {
            item(decision) ?? (decision?.route == .command ? decision?.command.map { "“\($0.command.title)”" } : nil)
        }
        for provider in DecisionProvider.allCases {
            for (half, cases, listsMisses) in [("tuned on", AskRouteCorpus.tune, true), ("never tuned on", AskRouteCorpus.holdout, false)] {
                let name = "Ask's routes on volume with \(provider.title), the half \(half): \(cases.count) requests in French and English, 90 % right or more"
                guard let key = userDecisionKeys[provider] else {
                    checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                    continue
                }
                var right: [AskRoute: Int] = [:], total: [AskRoute: Int] = [:]
                var misses: [String] = []
                var slowest: Duration = .zero
                for request in cases {
                    let start = ContinuousClock.now
                    let decision = await AskRouter.decide(request.text, hasSelection: request.selected, app: "Finder", menu: menu, apps: apps,
                                                          projects: projects, scripts: scripts, shortcuts: shortcuts, settings: settings,
                                                          services: services, keys: [provider: key])
                    slowest = max(slowest, .now - start)
                    total[request.route, default: 0] += 1
                    if decision?.route == request.route, request.item == nil || item(decision) == request.item {
                        right[request.route, default: 0] += 1
                    } else {
                        let routes = decision?.routes.prefix(2).map { "\($0.route.rawValue) \(Int($0.probability * 100)) %" }.joined(separator: ", ") ?? ""
                        misses.append("“\(request.text)” → \(decision?.route.rawValue ?? "failed")\(picked(decision).map { " \($0)" } ?? "")"
                            + " (wanted \(request.route.rawValue)\(request.item.map { " \($0)" } ?? ""); \(routes))")
                    }
                }
                let count = right.values.reduce(0, +)
                let perRoute = AskRoute.allCases.compactMap { route in total[route].map { "\(route.rawValue) \(right[route] ?? 0)/\($0)" } }
                record(name, Double(count) >= 0.9 * Double(cases.count),
                       "\(count)/\(cases.count) (\(count * 100 / max(cases.count, 1)) %): " + perRoute.joined(separator: ", ")
                           + (listsMisses && !misses.isEmpty ? "; missed: " + misses.joined(separator: "; ") : "")
                           + "; slowest \(Int(slowest.milliseconds)) ms",
                       slowest.milliseconds)
            }
        }
    }

    private func askRoutesLive() async {
        let home = NSHomeDirectory()
        let projects = [EditorProject(path: home + "/Documents/Github/skilli", kind: .folder, editor: "Cursor", bundleID: "com.todesktop.230313mzl4w4u92", rank: 0),
                        EditorProject(path: home + "/Code/nimbus-api", kind: .folder, editor: "Zed", bundleID: "dev.zed.Zed", rank: 0),
                        EditorProject(path: home + "/Sites/portfolio", kind: .folder, editor: "Sublime Text", bundleID: "com.sublimetext.4", rank: 0)]
        let scripts = [("Backup Photos", "Copies the photo library to the NAS"), ("Deploy Website", "Builds the site and uploads it")].compactMap { title, description in
            ScriptCommand.parse("#!/bin/bash\n# @skilli.schemaVersion 1\n# @skilli.title \(title)\n# @skilli.mode compact\n# @skilli.description \(description)\n",
                                path: "/tmp/\(title).sh")
        }
        // Connected services as Ask sends them: they must not pull the
        // other routes, and a request about them goes to the agent.
        let services: [(name: String, tools: [String])] = [
            (name: "nimbus-deployment", tools: ["whoami", "listUsers", "listDeployments", "getDeployment", "listMilestones", "listTasks", "getTask",
                                               "createTask", "updateTask", "createDeployment", "setFeatureFlag", "listAuditLog"]),
            (name: "linear", tools: ["list_issues", "get_issue", "create_issue", "list_projects"])
        ]
        let cases: [(String, Bool, AskRoute)] = [
            ("explique ce passage", true, .answer),
            ("corrige les fautes", true, .rewrite),
            ("rappelle-moi de relire ça ce soir", true, .plans),
            ("qui est Paul Durand ?", false, .contact),
            ("dis à Thomas sur Slack que j'ai 5 minutes de retard", false, .act),
            ("où est le menu pour exporter en PDF ?", false, .find),
            ("j'ai des taches nimbus deployment en cours ?", false, .act),
            ("quelles sont mes tâches en cours ?", false, .act),
            ("liste mes déploiements", false, .act),
            ("c'est quoi un déploiement continu ?", false, .answer),
            ("coche la case newsletter et enregistre", false, .control),
            ("clique sur le bouton partager", false, .control),
            ("remplis le champ nom avec Jean Dupont", false, .control),
            ("exporte en PDF dans mes documents", false, .control),
            ("enregistre ce document en PDF sur le bureau", false, .control),
            // Read on this Mac first; the decision is for what it misses.
            ("tous les lundis à 9h résume mes PR", false, .schedule),
            ("every weekday at 8:30 tell me what's on my calendar", false, .schedule),
            ("est-ce que tu pourrais me faire un résumé de mes mails chaque soir", false, .schedule)
        ]
        for provider in DecisionProvider.allCases {
            let name = "Ask routes with \(provider.title): answer, rewrite, find, control, act; connected services go to the agent"
            guard let key = Keychain.read(account: provider.keychainAccount) else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = true
            var slowest: Duration = .zero
            for (instruction, selected, expected) in cases {
                let start = ContinuousClock.now
                let routed = await AskRouter.decide(instruction, hasSelection: selected, app: "", menu: [], apps: [], projects: projects,
                                                    scripts: scripts, services: services, keys: [provider: key])
                slowest = max(slowest, .now - start)
                // A named service sent elsewhere still reaches the agent:
                // the card offers it first.
                let offered = expected == .act && routed?.route != .act && routed?.services.isEmpty == false
                passed = passed && (routed?.route == expected || offered)
                details.append("“\(instruction)” → \(routed?.route.rawValue ?? "failed")\(offered ? " (agent offered: \(routed?.services ?? []))" : "")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

    /// Your rules on the user's own decision keys (read only), on both
    /// providers: each call falls under the rule it should, a rule about
    /// reading never allows a change, unrelated calls under none.
    private func approvalRulesJudgedLive() async {
        let rules = [ApprovalRule(id: "calendar", text: "Reading my calendar or reminders is fine", effect: .allow),
                     ApprovalRule(id: "send", text: "Ask before anything that sends a message", effect: .ask),
                     ApprovalRule(id: "delete", text: "Never delete files", effect: .never),
                     ApprovalRule(id: "clipboard", text: "Reading my clipboard is fine", effect: .allow)]
        enum Expect { case rule(String), none, notAllow }
        func own(_ tool: String, _ arguments: [String: Any]) -> ApprovalRules.Call {
            let definition = SkilliTools.definition(tool)
            return ApprovalRules.Call(tool: tool, title: definition?.title ?? "", description: definition?.description ?? "",
                                      kind: MCPService.kind(definition?.risk ?? .changes), caller: "Claude Code",
                                      arguments: ToolCallSummary.arguments(arguments))
        }
        func server(_ server: String, _ tool: String, _ description: String, _ kind: MCPToolInfo.Kind, _ arguments: [String: Any]) -> ApprovalRules.Call {
            ApprovalRules.Call(tool: tool, description: description, kind: MCPService.kind(kind), server: server, caller: "Claude Code",
                               arguments: ToolCallSummary.arguments(arguments))
        }
        let cases: [(String, ApprovalRules.Call, Expect)] = [
            ("get_clipboard", own("get_clipboard", [:]), .rule("clipboard")),
            ("list_events", server("calendar", "list_events", "Lists the events of the user's calendars between two dates.", .reads,
                                   ["from": "2026-10-16", "to": "2026-10-17"]), .rule("calendar")),
            ("send_message", own("send_message", ["app": "Slack", "to": "Thomas", "text": "J'ai 5 minutes de retard"]), .rule("send")),
            ("send_email", server("gmail", "send_email", "Sends an email from the user's mailbox.", .changes,
                                  ["to": "paul@example.com", "subject": "Facture", "body": "Voici la facture."]), .rule("send")),
            ("delete_file", server("filesystem", "delete_file", "Deletes a file or a folder.", .destroys, ["path": "/Users/me/Documents/old.txt"]),
             .rule("delete")),
            ("emptyTrash", own("run_mac_command", ["command": "emptyTrash"]), .notAllow),
            ("create_event", server("calendar", "create_event", "Adds an event to one of the user's calendars.", .changes,
                                    ["title": "Dentiste", "start": "2026-10-16T09:30"]), .notAllow),
            ("open_url", own("open_url", ["url": "https://example.com"]), .none),
            ("set_volume", own("set_volume", ["percent": "30"]), .none)
        ]
        let keys = Self.usersDecisionKeys
        for provider in DecisionProvider.allCases {
            let name = "Your rules judged by \(provider.title): reading, sending, deleting, each to its rule; a change never allowed by a reading rule; the rest none"
            guard let key = keys[provider] else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            var details: [String] = []
            var passed = true
            var slowest: Duration = .zero
            for (label, call, expected) in cases {
                let start = ContinuousClock.now
                let verdict = try? await RuleJudge.judge(call, rules: rules, provider: provider, key: key).0
                slowest = max(slowest, .now - start)
                let picked: String? = if case .rule(let rule, _)? = verdict { rule.id } else { nil }
                let isAllow = if case .rule(let rule, _)? = verdict { rule.effect == .allow } else { false }
                let ok = switch expected {
                case .rule(let id): picked == id
                case .none: verdict == ApprovalRules.Verdict.none
                case .notAllow: verdict != nil && !isAllow
                }
                passed = passed && ok
                let said = verdict.map { verdict -> String in
                    switch verdict {
                    case .rule(let rule, let probability): "\(rule.id) \(Int(probability * 100))%"
                    case .none: "none"
                    case .unchecked(let why): why
                    }
                } ?? "failed"
                details.append("\(label) → \(said)\(ok ? "" : " ✗")")
            }
            record(name, passed, details.joined(separator: "; ") + ", slowest \(Int(slowest.milliseconds)) ms", slowest.milliseconds)
        }
    }

