        var github = MCPImport.Candidate(source: .claudeCode, name: "github")
        github.url = "https://api.githubcopilot.com/mcp/"
        github.token = "Bearer x"
        var memory = MCPImport.Candidate(source: .claudeCode, project: "/Users/me/Documents/app", name: "memory")
        memory.command = "npx"
        memory.args = ["-y", "@modelcontextprotocol/server-memory"]
        var old = MCPImport.Candidate(source: .claudeDesktop, name: "notes")
        old.url = "https://example.com/sse"
        old.problem = "Uses the older SSE transport, which skil.li does not speak yet."
        var figma = MCPImport.Candidate(source: .codex, name: "figma")
        figma.url = "https://mcp.figma.com/mcp"
        figma.tokenVariable = "FIGMA_TOKEN"
