    /// One real Act command: Claude Code reads the selection with skil.li's
    /// tool, asks to replace it (Return allows), and the text changes.
    private func actCommandWithClaudeCode() async {
        let name = "Act command with Claude Code: get_selection, replace_selection after Return; steps in the card"
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .auto
        let command = scratchCommand(
            prompt: "Read the selected text with get_selection, then replace it with the same text in uppercase using replace_selection. Then reply with just: Done.",
            output: .card
        )
        var act = command
        act.tools = ["selection"]
        act.model = .claude("haiku")
        context.aiCommands.save(act)
        defer {
            settings.mode = mode
            context.aiCommands.delete(command.id)
        }
        let start = ContinuousClock.now
        guard await run(act, on: "bonjour skilli") else {
            record(name, false, "the card did not show", nil)
            return
        }
        let asked = await waitUntil(timeout: 60) { popover.phase == .approving } != nil
        await pause(200)
        await saveScreenshot(of: popover.window, as: "ai-card-act-approval.png")
        if asked { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        let done = await waitUntil(timeout: 60) { popover.phase == .done || popover.phase == .failed } != nil
        let latency = ContinuousClock.now - start
        await pause(250)
        await saveScreenshot(of: popover.window, as: "ai-card-act-done.png")
        let steps = context.aiActions.lastSteps.map { "\($0.title) \($0.state)" }
        let replaced = textView.string == "BONJOUR SKILLI"
        let result = popover.result
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, asked && done && replaced && popover.phase != .failed,
               "steps \(steps), text “\(textView.string)”, reply “\(result)”, \(String(format: "%.1f", Double(latency.components.seconds) + Double(latency.components.attoseconds) / 1e18)) s",
               latency.milliseconds)
    }

    // MARK: - AI actions

    private static let aiOriginal = "les enfant on manger des pome"
    private static let aiFixed = "Les enfants ont mangé des pommes."

    /// Puts `text` in the test window, selected (or with an empty
    /// selection), and triggers ✦K → G with skil.li's own Hyper.
    private func triggerFixAction(on text: String, selected: Bool = true) async -> Bool {
        guard await focusTestWindow() else { return false }
        window.makeFirstResponder(textView)
        textView.string = text
        textView.undoManager?.removeAllActions()
        if selected {
            textView.selectAll(nil)
        } else {
            textView.setSelectedRange(NSRange(location: (text as NSString).length, length: 0))
        }
        await pause(60)
        _ = await hyperChord(["k", "g"], trigger: Self.ownTriggerKeyCode)
        return await waitUntil(timeout: 2, { self.context.aiActions.popover.isVisible }) != nil
    }

    /// A rewrite equal to the selection says so and Return leaves the text
    /// alone; ✦K → U on capitals pastes nothing and says why.
    private func aiActionSaysNothingToChange() async {
        let name = "Nothing to change: a rewrite equal to the selection says so and Return leaves it; ✦K → U on capitals pastes nothing"
        let popover = context.aiActions.popover
        let correct = "Les enfants ont mangé des pommes."
        context.ai.testEngine = FakeTextEngine(chunks: [correct], delay: .milliseconds(50))
        defer { context.ai.testEngine = nil }
        guard await triggerFixAction(on: correct) else {
            record(name, false, "the card did not show", nil)
            return
        }
        let said = await waitUntil(timeout: 3) { popover.phase == .done && popover.shownText.hasPrefix("Nothing to change") } != nil
        await saveScreenshot(of: popover.window, as: "ai-card-unchanged.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let closed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
        await pause(300)
        let untouched = textView.string == correct && textView.undoManager?.canUndo != true

        guard await focusTestWindow() else { return }
        window.makeFirstResponder(textView)
        textView.string = "DÉJÀ PRÊT"
        textView.undoManager?.removeAllActions()
        textView.selectAll(nil)
        let sentinel = "skilli-selftest-\(UUID().uuidString)"
        setClipboard(sentinel)
        let before = context.actions.unchangedCount
        _ = await hyperChord(["k", "u"], trigger: Self.ownTriggerKeyCode)
        let noted = await waitUntil(timeout: 2) { self.context.actions.unchangedCount > before } != nil
        let cardSaid = await waitUntil(timeout: 2) { popover.isVisible && popover.shownText.contains("already in UPPERCASE") } != nil
        await pause(300)
        let capitalsKept = textView.string == "DÉJÀ PRÊT" && textView.undoManager?.canUndo != true
            && NSPasteboard.general.string(forType: .string) == sentinel
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, said && closed && untouched && noted && cardSaid && capitalsKept,
               "card said nothing to change: \(said), Return closed it: \(closed), text untouched: \(untouched); ✦K → U on capitals noted: \(noted), card: \(cardSaid), text and clipboard kept: \(capitalsKept)",
               nil)
    }

    private func aiActionStreamsAndReplaces() async {
        let name = "AI action: answer streams into the card, Return replaces, ⌘Z undoes"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: ["Les enfants ", "ont mangé ", "des pommes."], delay: .milliseconds(150))
        defer { context.ai.testEngine = nil }
        guard await triggerFixAction(on: Self.aiOriginal) else {
            record(name, false, "the card did not show", nil)
            return
        }
        await pause(200)
        await saveScreenshot(of: popover.window, as: "ai-card-streaming.png")
        guard await waitUntil(timeout: 3, { popover.phase == .done }) != nil else {
            record(name, false, "no answer; card shows “\(popover.shownText)”", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        await pause(300)
        await saveScreenshot(of: popover.window, as: "ai-card-done.png")
        let edge = (await WindowCapture.image(of: popover.window)).map(WindowCapture.edgeAlpha) ?? 1
        let result = popover.result
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == Self.aiFixed } != nil
        let closed = !popover.isVisible
        var undone = false
        if replaced, await focusTestWindow() {
            await pressKey("z", flags: .maskCommand)
            undone = await waitUntil(timeout: 1) { self.textView.string == Self.aiOriginal } != nil
        }
        record(
            name,
            result == Self.aiFixed && replaced && closed && undone && edge <= 0.02,
            "result “\(result)”, replaced: \(replaced), card closed: \(closed), ⌘Z: \(undone), card edge opacity \(String(format: "%.3f", edge))",
            nil
        )
    }

    private func aiActionEscapeCancels() async {
        let name = "AI action: Esc while Claude writes cancels, text untouched"
        let popover = context.aiActions.popover
        let engine = FakeTextEngine(chunks: ["Slow ", "answer ", "that never lands."], delay: .milliseconds(600))
        context.ai.testEngine = engine
        defer { context.ai.testEngine = nil }
        guard await triggerFixAction(on: Self.aiOriginal) else {
            record(name, false, "the card did not show", nil)
            return
        }
        await pause(300)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let closed = await waitUntil(timeout: 0.5) { !popover.isVisible } != nil
        // A late chunk must not bring the card back or touch the text.
        await pause(1500)
        let stayedClosed = !popover.isVisible
        let untouched = textView.string == Self.aiOriginal
        record(name, closed && stayedClosed && untouched && engine.wasCancelled,
               "closed: \(closed), stayed closed: \(stayedClosed), text untouched: \(untouched), stream cancelled: \(engine.wasCancelled)", nil)
    }

    private func aiActionNeedsSelection() async {
        let name = "AI action with nothing selected and an empty field says so, Esc closes"
