    /// Arc answered a lone no-break space as the selection through
    /// Accessibility: the command reads the real one with ⌘C instead of
    /// sending blanks (Claude then answered nothing).
    private func aiActionBlankAccessibilityReadsWithCopy() async {
        let name = "AI action: a selection Accessibility gives as blanks is read with ⌘C, Return replaces it"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: [Self.aiFixed], delay: .milliseconds(20))
        context.selection.accessibilitySelectionOverride = "\u{00A0}"
        defer {
            context.ai.testEngine = nil
            context.selection.accessibilitySelectionOverride = nil
        }
        guard await triggerFixAction(on: Self.aiOriginal), await waitUntil(timeout: 3, { popover.phase == .done }) != nil else {
            record(name, false, "no answer; card “\(popover.shownText)”", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        let message = context.aiActions.lastMessage ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == Self.aiFixed } != nil
        let sent = message.contains(Self.aiOriginal) && !message.contains("\u{00A0}")
        record(name, sent && replaced, "sent the selection: \(sent), text now “\(textView.string)”", nil)
    }

    /// Nothing selected in a short field: the command selects all of it,
