    private func aiActionTakesTheField() async {
        let name = "AI action with nothing selected takes the whole field, selected; Return replaces it"
        let popover = context.aiActions.popover
        context.ai.testEngine = FakeTextEngine(chunks: [Self.aiFixed], delay: .milliseconds(20))
        defer { context.ai.testEngine = nil }
        guard await triggerFixAction(on: Self.aiOriginal, selected: false),
              await waitUntil(timeout: 3, { popover.phase == .done }) != nil else {
            record(name, false, "no answer; card “\(popover.shownText)”", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        let selected = textView.selectedRange() == NSRange(location: 0, length: (Self.aiOriginal as NSString).length)
        let message = context.aiActions.lastMessage ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == Self.aiFixed } != nil
        record(name, selected && message.contains(Self.aiOriginal) && replaced,
               "field selected: \(selected), sent the field: \(message.contains(Self.aiOriginal)), text now “\(textView.string)”", nil)
    }

    /// Nothing selected in a long document: only the paragraph at the
