        textView.string = document
        textView.setSelectedRange(NSRange(location: (filler as NSString).length + 5, length: 0))
        await pause(60)
        _ = await hyperChord(["k", "g"], trigger: Self.ownTriggerKeyCode)
        guard await waitUntil(timeout: 3, { popover.phase == .done }) != nil else {
            record(name, false, "no answer; card “\(popover.shownText)”", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        let message = context.aiActions.lastMessage ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == filler + "\n" + Self.aiFixed + "\nFin." } != nil
        record(name, message.contains(Self.aiOriginal) && !message.contains("Une phrase") && replaced,
               "sent only the paragraph: \(!message.contains("Une phrase")), replaced only it: \(replaced)", nil)
    }

    /// No engine (API key mode, no key): the card offers Settings → AI.
