            record(name, false, "the card did not show", nil)
            return
        }
        _ = await waitUntil(timeout: 2) { popover.phase == .failed }
        await pause(250)
        await saveScreenshot(of: popover.window, as: "ai-card-setup.png")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let opened = await waitUntil(timeout: 2) { self.context.settings.isVisible } != nil
        await closeSettings()
        record(name, opened && !popover.isVisible, "message “\(popover.shownText)”, Settings opened: \(opened)", nil)
