    /// One real request: Claude fixes the selection and Return puts it in.
    private func aiActionWithClaude() async {
        let name = "AI action with Claude: ✦K → G fixes the selection"
        let preferences = context.preferences
        let original = (preferences.aiEngineMode, preferences.keepClaudeReady)
        defer {
            preferences.aiEngineMode = original.0
            preferences.keepClaudeReady = original.1
        }
        preferences.aiEngineMode = .subscription
        preferences.keepClaudeReady = true
        _ = await waitUntil(timeout: 3) { self.context.ai.subscription.hasSpare }
        await pause(1000)
        let popover = context.aiActions.popover
        guard await triggerFixAction(on: Self.aiOriginal) else {
            record(name, false, "the card did not show", nil)
            return
        }
        guard await waitUntil(timeout: 15, { popover.phase != .streaming }) != nil, popover.phase == .done else {
            record(name, false, "Claude did not answer: “\(popover.shownText)”", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        await pause(300)
        await saveScreenshot(of: popover.window, as: "ai-card-claude.png")
        let result = popover.result
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let replaced = await waitUntil(timeout: 2) { self.textView.string == result } != nil
        let timing = context.aiActions.lastRun
        let fixed = result.lowercased().hasPrefix("les enfants") && (result.contains("ont mangé") || result.contains("mangent"))
            && result.contains("pommes") && !result.contains("\"\"\"")
        record(
            name,
            fixed && replaced,
            "“\(result)”, first word \(timing.map { "\(Int($0.firstWord.milliseconds)) ms" } ?? "?") after the keys, done \(timing.map { "\(Int($0.total.milliseconds)) ms" } ?? "?"), replaced: \(replaced)",
            timing?.firstWord.milliseconds
        )
    }

    /// Only what skil.li draws: the window itself, no margin around it, and
    /// a see-through card only while the test window is behind all of it.
    /// The user's own windows never end up in a capture.
    private func saveScreenshot(of window: NSWindow, as name: String) async {
        if !window.isOpaque, !(self.window.isVisible && self.window.frame.contains(window.frame)) {
            Log.perf.notice("Capture \(name, privacy: .public) skipped: the card is not over the test window")
            return
        }
        guard let directory = context.snapshotDirectory,
              let image = await GlassCheck.screenshot(around: window, padding: 0),
              let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:])
        else { return }
        try? png.write(to: directory.appendingPathComponent(name))
    }

    /// The API key round-trips through skil.li's own Keychain item, and the
    /// engine choice follows it. No network.
    private func aiKeychainAndEngineChoice() async {
        let ai = context.ai
        let preferences = context.preferences
        let originalMode = preferences.aiEngineMode
        defer {
            ai.removeAPIKey()
            preferences.aiEngineMode = originalMode
        }
        ai.removeAPIKey()
        preferences.aiEngineMode = .apiKey
        let noKey = ai.activeEngine == nil
        var saved = false
        do {
            try ai.saveAPIKey("  sk-ant-selftest-0000  ")
            saved = ai.hasAPIKey
        } catch {
            record("AI: API key saved in the Keychain, engine follows", false, "save failed: \(error.localizedDescription)", nil)
            return
        }
        let readBack = Keychain.read(account: "selftest-anthropic-api-key") == "sk-ant-selftest-0000"
        let usesKey = ai.activeEngine == .apiKey
        await snapshotAIPane("settings-ai-accounts-key-saved.png")
        ai.removeAPIKey()
        let removed = !ai.hasAPIKey && Keychain.read(account: "selftest-anthropic-api-key") == nil && ai.activeEngine == nil
        record(
            "AI: API key saved in the Keychain, engine follows",
            noKey && saved && readBack && usesKey && removed,
            "no key → no engine: \(noKey), saved: \(saved), read back trimmed: \(readBack), engine = key: \(usesKey), removed: \(removed)",
            nil
        )
    }

    private func aiFindsClaudeCode() async {
        let start = ContinuousClock.now
        await context.ai.refresh()
        let elapsed = (ContinuousClock.now - start).milliseconds
        let path = context.ai.claudeBinary?.path ?? "none"
        switch context.ai.claudeStatus {
        case .signedIn(let plan):
            record("AI: Claude Code found and signed in", true, "\(path), plan \(plan ?? "console")", elapsed)
        case .signedOut:
            record("AI: Claude Code found and signed in", false, "\(path) is not signed in", elapsed)
        case .notInstalled, nil:
            checks.append(Check(name: "AI: Claude Code found and signed in", passed: true, skipped: true, detail: "Claude Code not installed", latencyMs: elapsed))
        }
    }

    /// The spare answers the sample, a new spare replaces it, and sleep or
    /// screen lock drop it until wake. One real request on the plan.
    private func aiSubscriptionSpare() async {
        let ai = context.ai
        let preferences = context.preferences
        let original = (preferences.aiEngineMode, preferences.keepClaudeReady)
        defer {
            preferences.aiEngineMode = original.0
            preferences.keepClaudeReady = original.1
        }
        preferences.aiEngineMode = .subscription
        preferences.keepClaudeReady = true
        guard await waitUntil(timeout: 3, { ai.subscription.hasSpare }) != nil, let usedPID = ai.subscription.sparePID else {
            record("AI: subscription answers from a spare, replaced at once", false, "no spare process started", nil)
            return
        }
        // A spare is ready ~0.5 s after it starts.
        await pause(1000)
        let result = await ai.test(.subscription)
        let replaced = await waitUntil(timeout: 3) { ai.subscription.hasSpare && ai.subscription.sparePID != usedPID } != nil
        await snapshotAIPane("settings-ai-accounts-tested.png")
        switch result {
        case .passed(let text, let firstWord, let total):
            // "on manger" reads as "ont mangé" or "mangent"; both are right.
            // A capital is not the point: the original had none, and Fix keeps
            // the text's form. "on" must become "ont".
            let fixed = text.lowercased().hasPrefix("les enfants") && (text.contains("ont mangé") || text.contains("mangent"))
                && text.contains("pommes") && !text.contains("\"\"\"")
            let fast = firstWord < .milliseconds(1500)
            record(
                "AI: subscription answers from a spare, replaced at once",
                fixed && fast && replaced,
                "“\(text)”, first word \(firstWord.milliseconds.rounded()) ms, done \(total.milliseconds.rounded()) ms, new spare: \(replaced)",
                firstWord.milliseconds
            )
        case .failed(let message):
            record("AI: subscription answers from a spare, replaced at once", false, message, nil)
        case .running:
            record("AI: subscription answers from a spare, replaced at once", false, "still running", nil)
        }

        let center = NSWorkspace.shared.notificationCenter
        center.post(name: NSWorkspace.willSleepNotification, object: NSWorkspace.shared)
        let dropped = await waitUntil(timeout: 1) { !ai.subscription.hasSpare } != nil
        center.post(name: NSWorkspace.didWakeNotification, object: NSWorkspace.shared)
        let back = await waitUntil(timeout: 3) { ai.subscription.hasSpare } != nil
        record("AI: no spare while the Mac sleeps, a new one on wake", dropped && back, "dropped on sleep: \(dropped), back on wake: \(back)", nil)
    }

    /// The AI pane as it stands, for design review.
    private func snapshotAIPane(_ name: String) async {
        guard let directory = context.snapshotDirectory else { return }
        context.settings.show(pane: .aiAccounts)
        await pause(400)
        if let png = await context.settings.snapshotPNG() {
            try? png.write(to: directory.appendingPathComponent(name))
        }
        await closeSettings()
    }

    /// Decision keys round-trip through skil.li's own (self-test) items.
    private func aiDecisionKeysInKeychain() {
        let ai = context.ai
        var states: [String] = []
        var passed = true
        for provider in DecisionProvider.allCases {
            ai.removeDecisionKey(for: provider)
            try? ai.saveDecisionKey("  test-\(provider.rawValue)  ", for: provider)
            let saved = ai.decisionKeys.contains(provider) && ai.decisionKey(for: provider) == "test-\(provider.rawValue)"
            ai.removeDecisionKey(for: provider)
            let removed = !ai.decisionKeys.contains(provider) && ai.decisionKey(for: provider) == nil
            passed = passed && saved && removed
            states.append("\(provider.title): saved \(saved), removed \(removed)")
        }
        record("Decisions: keys saved in the Keychain and removed", passed, states.joined(separator: "; "), nil)
    }

    /// A real decision per provider whose key the user saved (read-only).
    private func aiDecisionsLive() async {
        for provider in DecisionProvider.allCases {
            let name = "Decisions: \(provider.title) picks “reminder” for a reminder request"
            guard let key = Keychain.read(account: provider.keychainAccount) else {
                checks.append(Check(name: name, passed: true, skipped: true, detail: "no \(provider.title) key saved in Settings", latencyMs: nil))
                continue
            }
            let start = ContinuousClock.now
            do {
                let answer = try await DecisionClient.decide(.sample, input: DecisionQuestion.sampleInput, provider: provider, key: key)
                let latency = ContinuousClock.now - start
                record(name, answer.choice == "reminder", "→ \(answer.choice), confidence \(String(format: "%.2f", answer.confidence)), \(Int(latency.milliseconds)) ms", latency.milliseconds)
            } catch {
                record(name, false, error.localizedDescription, nil)
            }
        }
    }

