    /// Codex's status and the models it lists for the plan, the OpenAI key's
    /// models (read-only, the user's key): what the menus offer.
    private func writersFoundAndListed() async {
        let name = "Writers: Codex's models for the plan and the OpenAI key's models are listed"
        let ai = context.ai
        await ai.refresh()
        let start = ContinuousClock.now
        await ai.refreshCodex()
        let codexTime = ContinuousClock.now - start
        var parts: [String] = []
        var passed = true
        switch ai.codexStatus {
        case .signedIn(let apiKey):
            let listed = ai.codexModels.map { offer in "\(offer.id) [\(offer.efforts.map(\.rawValue).joined(separator: "/"))]" }
            parts.append("Codex \(apiKey ? "on an API key" : "on ChatGPT") (status in \(Int(codexTime.milliseconds)) ms): \(listed.joined(separator: ", "))")
            passed = !ai.codexModels.isEmpty
        case .signedOut:
            parts.append("Codex signed out")
        case .notInstalled, nil:
            parts.append("Codex not installed")
        }
        if let key = Keychain.read(account: DecisionProvider.openAI.keychainAccount), !key.isEmpty {
            let start = ContinuousClock.now
            let all = await OpenAIEngine.models(key: key)
            let current = all.map(ModelCatalog.current) ?? []
            parts.append("OpenAI key in \(Int((ContinuousClock.now - start).milliseconds)) ms: \(all?.count ?? 0) text models (\(all?.prefix(12).map(\.id).joined(separator: ", ") ?? "none")), offered: \(current.map(\.id).joined(separator: ", "))")
            passed = passed && !current.isEmpty
        } else {
            parts.append("no OpenAI key saved in Settings")
        }
        record(name, passed, parts.joined(separator: " · "), codexTime.milliseconds)
    }

    /// One real answer from ChatGPT through Codex, the way a user runs it:
    /// Fix on GPT-6 Luna Low (✦K → G), the card saying who wrote it.
    private func chatGPTWritesACommand() async {
        let name = "ChatGPT: a command on GPT-6 Luna Low fixes the selection, the card says “ChatGPT · GPT-6 Luna Low”"
        let ai = context.ai
        if ai.codexStatus == nil { await ai.refreshCodex() }
        guard case .signedIn = ai.codexStatus else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "Codex not signed in on this Mac", latencyMs: nil))
            return
        }
        let library = context.aiCommands.library
        guard let original = library.command("fix") else {
            record(name, false, "no Fix command", nil)
            return
        }
        var fix = original
        fix.model = ModelChoice(provider: .chatGPT, model: "gpt-6-luna", effort: .low)
        library.save(fix)
        defer { library.save(original) }
        let popover = context.aiActions.popover
        guard await triggerFixAction(on: Self.aiOriginal) else {
            record(name, false, "the card did not show", nil)
            return
        }
        guard await waitUntil(timeout: 40, { popover.phase != .streaming }) != nil, popover.phase == .done else {
            record(name, false, "ChatGPT did not answer: “\(popover.shownText)”", nil)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            return
        }
        await pause(300)
        await saveScreenshot(of: popover.window, as: "ai-card-chatgpt.png")
        let result = popover.result, status = popover.shownStatus
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let timing = context.aiActions.lastRun
        let fixed = result.lowercased().hasPrefix("les enfants") && (result.contains("ont mangé") || result.contains("mangent"))
            && result.contains("pommes") && !result.contains("\"\"\"")
        record(name, fixed && status.contains("ChatGPT · GPT-6 Luna Low"),
               "“\(result)”, status “\(status)”, first word \(timing.map { "\(Int($0.firstWord.milliseconds)) ms" } ?? "?") after the keys, done \(timing.map { "\(Int($0.total.milliseconds)) ms" } ?? "?")",
               timing?.total.milliseconds)
    }

    /// A model ChatGPT does not offer: the card says so in words, never
    /// "answered nothing".
    private func chatGPTSaysWhatWentWrong() async {
        let name = "ChatGPT: a model the plan does not offer is said in words"
        let ai = context.ai
        guard case .signedIn = ai.codexStatus else {
