    /// The OpenAI API with the user's own key, read-only: GPT-6 Luna Low
    /// twice (the second on a warm connection), GPT-6.1 Sol Low once.
    private func openAIWritesLive() async {
        let name = "OpenAI API: the user's key writes with GPT-6 Luna Low and GPT-6.1 Sol Low, streamed"
        guard Keychain.read(account: DecisionProvider.openAI.keychainAccount) != nil else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no OpenAI key saved in Settings", latencyMs: nil))
            return
        }
        let engine = OpenAIEngine { Keychain.read(account: DecisionProvider.openAI.keychainAccount) }
        var runs: [String] = []
        var passed = true
        var warm: Double?
        for (index, model) in ["gpt-6-luna", "gpt-6-luna", "gpt-6.1-sol"].enumerated() {
            var request = AIPrompt.sample
            request.model = ModelChoice(provider: .openAI, model: model, effort: .low)
            let start = ContinuousClock.now
            var firstWord: Duration?
            var text = ""
            var chunks = 0
            do {
                for try await chunk in engine.stream(request) {
                    firstWord = firstWord ?? .now - start
                    text += chunk
                    chunks += 1
                }
                let total = ContinuousClock.now - start
                text = text.trimmingCharacters(in: .whitespacesAndNewlines)
                let fixed = text.lowercased().hasPrefix("les enfants") && text.contains("pommes")
                passed = passed && fixed
                if index == 1 { warm = (firstWord ?? total).milliseconds }
                runs.append("\(model) low: “\(text)” in \(chunks) chunks, first word \(Int((firstWord ?? total).milliseconds)) ms, done \(Int(total.milliseconds)) ms")
            } catch {
                passed = false
                runs.append("\(model) low: \(error.localizedDescription)")
            }
        }
        record(name, passed, runs.joined(separator: " · "), warm)
    }

