    /// Opens the menu button whose title starts with `title` with a real
    /// click (SwiftUI draws it: no AppKit button to call), captures the open
    /// menu alone (`capture`), then presses the item titled `pick`, or
    /// leaves with Escape. The menu's item titles, and whether it opened.
    private func openMenu(titled title: String, capture: String, pick: String? = nil) async -> (titles: [String], opened: Bool) {
        guard let button = Self.axElements(roles: [kAXMenuButtonRole, kAXPopUpButtonRole], where: { $0.hasPrefix(title) }).first,
              let frame = Self.axFrame(button) else {
            Log.actions.error("SELFTEST no menu button “\(title, privacy: .public)”")
            return ([], false)
        }
        let source = CGEventSource(stateID: .hidSystemState)
        let point = CGPoint(x: frame.midX, y: frame.midY)
        // Never left open: Escape from another thread if the main one is
        // held by the menu longer than this.
        let guardTimer = DispatchWorkItem {
            for down in [true, false] {
                CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
            }
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + 10, execute: guardTimer)
        defer { guardTimer.cancel() }
        for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(60)
        }
        await pause(700)
        let items = Self.axElements(roles: [kAXMenuItemRole], under: button) { _ in true }
        let titles = items.compactMap { Self.axTitle($0) }.filter { !$0.isEmpty }
        if let directory = context.snapshotDirectory, let image = await WindowCapture.openMenuImage(),
           let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
            try? png.write(to: directory.appendingPathComponent(capture))
        }
        if let pick, let item = items.first(where: { Self.axTitle($0) == pick }) {
            AXUIElementPerformAction(item, kAXPressAction as CFString)
        } else {
            for down in [true, false] {
                CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
            }
        }
        await pause(300)
        return (titles, !titles.isEmpty)
    }

    /// skil.li's own elements with one of `roles` whose title, value or
    /// description passes `matches`, under `root` (the app by default).
    private static func axElements(roles: [String], under root: AXUIElement? = nil, where matches: (String) -> Bool) -> [AXUIElement] {
        var found: [AXUIElement] = []
        walkAX(from: root ?? AXUIElementCreateApplication(getpid())) { element in
            var role: CFTypeRef?
            AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &role)
            if let role = role as? String, roles.contains(role), let title = axTitle(element), matches(title) {
                found.append(element)
            }
            return true
        }
        return found
    }

    /// `visit` on `root` and every element under it, depth first, each one
    /// once, `depth` levels down at most; `visit` says false to stop.
    /// Once: while skil.li is not the active app (measured with the login
    /// window in front), its application lists itself twice among its own
    /// children, and a walk that went in again went down every level twice
    /// over (2026-10-22: 2^40 elements, the main thread held for 9 hours;
    /// 129 when each is walked once).
    private static func walkAX(from root: AXUIElement, depth limit: Int = 40, _ visit: (AXUIElement) -> Bool) {
        var seen: [CFHashCode: [AXUIElement]] = [:]
        var stopped = false
        func walk(_ element: AXUIElement, depth: Int) {
            guard !stopped, depth < limit else { return }
            let hash = CFHash(element)
            guard seen[hash]?.contains(where: { CFEqual($0, element) }) != true else { return }
            seen[hash, default: []].append(element)
            guard visit(element) else {
                stopped = true
                return
            }
            var children: CFTypeRef?
            guard AXUIElementCopyAttributeValue(element, kAXChildrenAttribute as CFString, &children) == .success,
                  let list = children as? [AXUIElement] else { return }
            for child in list { walk(child, depth: depth + 1) }
        }
        walk(root, depth: 0)
    }

    private static func axTitle(_ element: AXUIElement) -> String? {
        for attribute in [kAXTitleAttribute, kAXValueAttribute, kAXDescriptionAttribute] {
            var value: CFTypeRef?
            AXUIElementCopyAttributeValue(element, attribute as CFString, &value)
            if let text = value as? String, !text.isEmpty { return text }
        }
        return nil
    }

    /// In screen coordinates from the top left, as mouse events take them.
    private static func axFrame(_ element: AXUIElement) -> CGRect? {
        var position: CFTypeRef?, size: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXPositionAttribute as CFString, &position) == .success,
              AXUIElementCopyAttributeValue(element, kAXSizeAttribute as CFString, &size) == .success,
              let position, let size else { return nil }
        var origin = CGPoint.zero, extent = CGSize.zero
        AXValueGetValue(position as! AXValue, .cgPoint, &origin)
        AXValueGetValue(size as! AXValue, .cgSize, &extent)
        return CGRect(origin: origin, size: extent)
    }

    /// The window alone, as it shows (a sheet without its parent).
    private func saveWindow(_ window: NSWindow, as name: String) async {
        guard let directory = context.snapshotDirectory, let png = await WindowCapture.png(of: window) else { return }
        try? png.write(to: directory.appendingPathComponent(name))
    }

    /// Scrolls the tallest overflowing scroll view of `window` to `fraction`
    /// of the way down (1: its end).
    private static func scroll(_ window: NSWindow, to fraction: CGFloat = 1) {
        func scrollViews(_ view: NSView) -> [NSScrollView] {
            view.subviews.flatMap(scrollViews) + ((view as? NSScrollView).map { [$0] } ?? [])
        }
        guard let content = window.contentView,
              let scrollView = scrollViews(content).filter({ ($0.documentView?.frame.height ?? 0) > $0.contentView.bounds.height + 1 })
                .max(by: { $0.frame.height < $1.frame.height }),
              let document = scrollView.documentView
        else { return }
        let range = document.frame.height - scrollView.contentView.bounds.height
        scrollView.contentView.scroll(to: NSPoint(x: 0, y: document.isFlipped ? range * fraction : range * (1 - fraction)))
        scrollView.reflectScrolledClipView(scrollView.contentView)
    }

    /// The user's own key, read-only, if they saved one in Settings.
    private func aiAPIKeyLive() async {
        guard Keychain.read(account: AIStore.apiKeyAccount) != nil else {
            checks.append(Check(name: "AI: API key answers", passed: true, skipped: true, detail: "no API key saved in Settings", latencyMs: nil))
            return
        }
        let engine = ClaudeAPIEngine { Keychain.read(account: AIStore.apiKeyAccount) }
        engine.model = AIModel(choice: context.preferences.writingModel) ?? .haiku
        let start = ContinuousClock.now
        var firstWord: Duration?
        var text = ""
        do {
            for try await chunk in engine.stream(AIPrompt.sample) {
                firstWord = firstWord ?? .now - start
                text += chunk
            }
            record("AI: API key answers", text.contains("enfants"), "“\(text.trimmingCharacters(in: .whitespacesAndNewlines))”, first word \((firstWord ?? .zero).milliseconds.rounded()) ms", firstWord?.milliseconds)
        } catch {
            record("AI: API key answers", false, error.localizedDescription, nil)
        }
    }

    /// App icons are rendered once into small Retina bitmaps; drawn at the
    /// wrong scale they fill only the bottom-left quarter.
    private func appIconsFillTheirSize() async {
        let launcher = context.launcher
        launcher.show(triggeredAt: .now)
        // Right after launch the app index may still be scanning.
        _ = await waitUntil(timeout: 5) {
            _ = launcher.simulateTyping("safari")
            return launcher.topResultIcon != nil
        }
        let icon = launcher.topResultIcon
        launcher.hide()
        guard let icon, let bitmap = icon.representations.first as? NSBitmapImageRep else {
            record("App icons fill their size", false, "no bitmap icon for \"\(launcher.topResultName ?? "none")\"", nil)
            return
        }
        // The top-right quarter of an app icon is never empty.
        var opaque = 0
        for x in (bitmap.pixelsWide / 2)..<bitmap.pixelsWide {
            for y in 0..<(bitmap.pixelsHigh / 2) where (bitmap.colorAt(x: x, y: y)?.alphaComponent ?? 0) > 0.5 {
                opaque += 1
            }
        }
        let share = Double(opaque) / Double(max(1, bitmap.pixelsWide * bitmap.pixelsHigh / 4))
        record(
            "App icons fill their size",
            share > 0.3,
            "\(launcher.topResultName ?? "?"): \(bitmap.pixelsWide) px, top-right quarter \(Int(share * 100)) % opaque",
            nil
        )
    }

    private func reportGlass(_ name: String, _ measures: [GlassCheck.Measure]?) {
        guard let measures, let worst = measures.max(by: { $0.edgeStep < $1.edgeStep }) else {
            record(name, false, "screen capture failed, or the window moved (mouse on another screen?)", nil)
            return
        }
        let outside = measures.map(\.outsideStep).max() ?? 0
        let format = { (value: Double) in String(format: "%.3f", value) }
        record(
            name,
            worst.edgeStep <= GlassCheck.edgeLimit && outside <= GlassCheck.edgeLimit,
            "worst edge step \(format(worst.edgeStep)) on \(worst.backdrop.rawValue)/\(worst.appearance) "
                + "(max \(format(GlassCheck.edgeLimit))); outside the window \(format(outside))",
            nil
        )
    }

    private func tapEscapePreference() async {
        guard await focusRecorder() else { return }
        context.preferences.hyperTapSendsEscape = false
        postKey(Self.ownTriggerKeyCode, down: true)
        await pause(30)
        postKey(Self.ownTriggerKeyCode, down: false)
        await pause(300)
        let escapedWhileOff = recorder.events.contains { $0.keyCode == UInt16(kVK_Escape) }
        context.preferences.hyperTapSendsEscape = true
        record(
            "“Tap Caps Lock alone to send Escape” off stops the Escape (F19)",
            !escapedWhileOff && context.router.tapSendsEscape,
            "Escape sent while off: \(escapedWhileOff), restored: \(context.router.tapSendsEscape)",
            nil
        )
    }

    /// A launcher "Allow …" row while another app is in front: the setup
    /// window comes to the front with the keyboard (a window of the test's
    /// own, states frozen: nothing is asked of macOS). Only Accessibility's
    /// row opens it now (D7); it is on here, so "Allow Contacts" stands in,
    /// its row routed to the test's window.
    private func setupComesToFrontFromLauncher() async {
        let name = "Setup comes to front over another app from the launcher's Allow row (Contacts' standing in for Accessibility's)"
        let bundleID = "com.apple.TextEdit"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID), context.launcher.contacts?.isAllowed == false else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "TextEdit missing, or Contacts already allowed on this Mac", latencyMs: nil))
            return
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-setup-front-\(getpid()).txt")
        try? "front".write(to: file, atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: file) }
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let textEdit = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration) else {
            record(name, false, "could not open TextEdit", nil)
            return
        }
        let textEditPID = textEdit.processIdentifier
        // Accessibility makes an app frontmost only once it has finished
        // launching (kAXErrorCannotComplete before): a TextEdit started
        // just now stayed behind.
        guard await waitUntil(timeout: 5, { textEdit.isFinishedLaunching }) != nil else {
            record(name, false, "TextEdit never finished launching", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        let permissions = PermissionCenter()
        permissions.frozenStates = [.accessibility: .granted, .microphone: .notAsked, .reminders: .notAsked, .contacts: .notAsked]
        let setup = SetupWindowController(permissions: permissions, ai: context.ai, preferences: context.preferences)
        let onSetup = context.launcher.onSetup
        context.launcher.onSetup = { _ in setup.show(at: .accessibility) }
        defer {
            context.launcher.onSetup = onSetup
            setup.close()
        }
        Self.makeFrontmost(pid: textEditPID)
        guard await waitUntil(timeout: 4, { NSWorkspace.shared.frontmostApplication?.processIdentifier == textEditPID }) != nil else {
            record(name, false, "TextEdit never came to front", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        await pressKey("@")
        let allowRow = await waitUntil(timeout: 2) { self.context.launcher.topResultName?.hasPrefix("Allow Contacts") == true } != nil
        if allowRow { await pressKey(nil, code: CGKeyCode(kVK_Return)) } else { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        let front = await waitUntil(timeout: 2) {
            NSWorkspace.shared.frontmostApplication?.processIdentifier == getpid() && setup.shownWindow?.isKeyWindow == true
        }
        let detail = "Allow row: \(allowRow); frontmost \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"), setup key: \(setup.shownWindow?.isKeyWindow == true)"
        setup.close()
        Self.makeFrontmost(pid: textEditPID)
        _ = await waitUntil(timeout: 2) { NSWorkspace.shared.frontmostApplication?.processIdentifier == textEditPID }
        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
        record(name, allowRow && front != nil, detail, front?.milliseconds)
    }

    /// The real situation: another app is in front and skil.li is not
    /// active. Settings must come to the front and take the keyboard,
    /// whether opened from the menu bar or from the launcher.
    private func settingsComeToFrontOverAnotherApp() async {
        let bundleID = "com.apple.TextEdit"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record("Settings come to front over another app", false, "TextEdit not installed", nil)
            return
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-front-\(getpid()).txt")
        try? "front".write(to: file, atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: file) }

        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        guard let textEdit = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration) else {
            record("Settings come to front over another app", false, "could not open TextEdit", nil)
            return
        }
        let textEditPID = textEdit.processIdentifier
        // Accessibility makes an app frontmost only once it has finished
        // launching (kAXErrorCannotComplete before): a TextEdit started
        // just now stayed behind, and the check failed before Settings opened.
        guard await waitUntil(timeout: 5, { textEdit.isFinishedLaunching }) != nil else {
            record("Settings come to front over another app", false, "TextEdit never finished launching", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }

        func bringTextEditForward() async -> Bool {
            Self.makeFrontmost(pid: textEditPID)
            return await waitUntil(timeout: 4) { NSWorkspace.shared.frontmostApplication?.processIdentifier == textEditPID } != nil
        }
        func settingsInFront() -> Bool {
            NSWorkspace.shared.frontmostApplication?.processIdentifier == getpid()
                && context.settings.isKey
                && NSApp.isActive
        }

        // From the menu bar.
        guard await bringTextEditForward() else {
            record("Settings come to front over another app", false, "TextEdit never came to front", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        _ = context.performStatusMenuSettings()
        let fromMenu = await waitUntil(timeout: 2) { settingsInFront() }
        let menuDetail = "menu: frontmost \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"), key \(context.settings.isKey)"
        // Read while the window is on screen: the policy alone is set before it shows.
        let inDockWhileOpen = context.settings.isVisible && NSRunningApplication.current.activationPolicy == .regular
        await closeSettings()
        let outOfDockOnClose = await waitUntil(timeout: 1) { NSRunningApplication.current.activationPolicy == .accessory } != nil
        record("Settings: skil.li in the Dock only while Settings is open", inDockWhileOpen && outOfDockOnClose,
               "in the Dock while open \(inDockWhileOpen), out of it once closed \(outOfDockOnClose)", nil)

        // From the launcher, typed like a user.
        var launcherDetail = "launcher: TextEdit never came back to front"
        var fromLauncher: Duration?
        if await bringTextEditForward() {
            _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
            if await waitUntil(timeout: 1, { self.context.launcher.isVisible }) != nil {
                for character in "settings" {
                    await pressKey(character)
                }
                if await waitUntil(timeout: 1, { self.context.launcher.topResultName == "skil.li Settings" }) != nil {
                    await pressKey(nil, code: CGKeyCode(kVK_Return))
                    fromLauncher = await waitUntil(timeout: 2) { settingsInFront() }
                    launcherDetail = "launcher: frontmost \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"), key \(context.settings.isKey)"
                } else {
                    launcherDetail = "launcher got \"\(context.launcher.query)\", top \"\(context.launcher.topResultName ?? "none")\""
                    await pressKey(nil, code: CGKeyCode(kVK_Escape))
                }
            } else {
                launcherDetail = "launcher did not open over TextEdit"
            }
            if fromLauncher == nil, !launcherDetail.hasPrefix("launcher got"), !launcherDetail.hasPrefix("launcher did") {
                launcherDetail = "launcher: frontmost \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"), key \(context.settings.isKey)"
            }
            await closeSettings()
        }

        record(
            "Settings come to front over another app (menu bar, launcher)",
            fromMenu != nil && fromLauncher != nil,
            "\(menuDetail); \(launcherDetail)",
            fromMenu?.milliseconds
        )
        if await bringTextEditForward() {
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
        }
    }

    private func closeSettings() async {
        context.settings.close()
        _ = await waitUntil(timeout: 1) { !self.context.settings.isVisible }
    }

    // MARK: - Settings' search

    /// Settings' search with real keys: ⌘F takes the field; “escape” finds
    /// Keys → Tap Caps Lock alone…, selected; ↓↑ move; ↩ opens Keys at that
    /// row, in sight and glowing (Advanced opened); esc gives the sidebar
    /// back; “clipboard” then ↩ opens the pane itself; a letter typed while
    /// the sidebar has the keys goes into the field; nothing found says so.
    /// The sidebar searching, the glow and nothing found, light and dark.
    private func settingsSearchFindsAndOpens() async {
        let name = "Settings search: ⌘F, “escape” finds Keys → Tap Caps Lock alone…, ↓↑ move, ↩ opens it in sight and glowing, esc restores the sidebar, ↩ on a pane opens it, “emoji” finds the Catalog's entry, letters typed in the sidebar search, nothing found says so"
        let settings = context.settings
        let search = settings.search
        defer {
            SettingsSearchModel.holdsGlow = false
            search.clear()
        }
        let opening = !settings.isVisible
        settings.show(pane: .general)
        guard await waitUntil(timeout: 2, { settings.isVisible && settings.isKey }) != nil else {
            record(name, false, "Settings did not come forward", nil)
            return
        }
        await pause(400)
        // As it opens, the panes' list has the keys (↑↓ move through them), not the field.
        let listFirst = !opening || settings.sidebarHasKeys

        // ⌘F, then a word.
        await pressKey("f", flags: .maskCommand)
        let focused = await waitUntil(timeout: 1) { settings.searchFieldFocused } != nil
        for character in "escape" { await pressKey(character) }
        let found = await waitUntil(timeout: 1) { search.query == "escape" && search.selected == "hyperTapSendsEscape" } != nil
        let firstPane = search.rows.first?.pane
        let keystroke = search.lastSearch
        let shown = search.rows.map { $0.item?.title ?? "[\($0.pane.title)]" }
        await captureSettingsBothWays(as: "settings-search-results")

        // ↑ to the pane's row, then ↓ back to the setting's.
        let before = search.selected
        await pressKey(nil, code: CGKeyCode(kVK_UpArrow))
        let moved = await waitUntil(timeout: 1) { search.selected == SettingsSearch.paneAnchor(SettingsPane.keys.rawValue) } != nil
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        let back = await waitUntil(timeout: 1) { search.selected == before } != nil

        // ↩: Keys, at the row, under Advanced, glowing.
        SettingsSearchModel.holdsGlow = true
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let landed = await waitUntil(timeout: 2) { search.landed == "hyperTapSendsEscape" } != nil
        let inSight = await waitUntil(timeout: 1) { settings.anchorVisibility("hyperTapSendsEscape") > 0.95 } != nil
        let pane = settings.pane
        await pause(250)
        await captureSettingsBothWays(as: "settings-search-glow")
        SettingsSearchModel.holdsGlow = false
        let stillSearching = search.isSearching && settings.searchFieldFocused

        // esc: the sidebar again, Keys selected in it.
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let restored = await waitUntil(timeout: 1) { !search.isSearching && search.rows.isEmpty } != nil

        // A pane's own name, ↩: the pane.
        for character in "clipboard" { await pressKey(character) }
        let paneSelected = await waitUntil(timeout: 1) { search.selected == SettingsSearch.paneAnchor(SettingsPane.clipboard.rawValue) } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let paneOpened = await waitUntil(timeout: 1) { settings.pane == .clipboard } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !search.isSearching }

        // What skil.li does, in the Catalog (asked: "emoji" found nothing):
        // the entry found, ↩ opens Catalog at its row.
        for character in "emoji" { await pressKey(character) }
        let emojiFound = await waitUntil(timeout: 1) {
            search.query == "emoji" && search.rows.contains { $0.pane == .catalog && $0.item?.kind == .entry }
        } != nil
        let emojiRow = search.rows.first { $0.pane == .catalog && $0.item?.kind == .entry }?.id
        if let emojiRow, search.selected != emojiRow {
            for _ in 0..<12 where search.selected != emojiRow { await pressKey(nil, code: CGKeyCode(kVK_DownArrow)) }
        }
        await captureSettingsBothWays(as: "settings-search-emoji")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let emojiLanded = await waitUntil(timeout: 3) { emojiRow != nil && search.landed == emojiRow } != nil
        let emojiInSight = await waitUntil(timeout: 1) { emojiRow.map { settings.anchorVisibility($0) > 0.95 } == true } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !search.isSearching }

        // A word many panes hold: the long list, captured.
        for character in "search" { await pressKey(character) }
        let many = await waitUntil(timeout: 1) { search.query == "search" && Set(search.rows.map(\.pane)).count >= 4 } != nil
        let manyPanes = Set(search.rows.map(\.pane)).count
        await captureSettingsBothWays(as: "settings-search-many")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !search.isSearching }

        // Typed while the sidebar's list has the keys: into the field.
        let listFocused = settings.focusSidebar()
        await pause(150)
        for character in "zzqx" { await pressKey(character) }
        let typedFromSidebar = await waitUntil(timeout: 1) { search.query == "zzqx" && settings.searchFieldFocused } != nil
        let nothing = search.isSearching && search.rows.isEmpty
        await captureSettingsBothWays(as: "settings-search-none")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 1) { !search.isSearching }

        // How a section's header and a row with a line under it glow.
        SettingsSearchModel.holdsGlow = true
        for (anchor, pane, file) in [("approvalRules", SettingsPane.ask, "settings-search-glow-header"),
                                     ("fileMeaningSearch", SettingsPane.launcher, "settings-search-glow-detail")] {
            search.reveal(anchor, in: pane)
            _ = await waitUntil(timeout: 2) { search.landed == anchor }
            _ = await waitUntil(timeout: 1) { settings.anchorVisibility(anchor) > 0.95 }
            await pause(250)
            await captureSettingsBothWays(as: file)
        }
        SettingsSearchModel.holdsGlow = false
        await closeSettings()

        let passed = listFirst && focused && found && firstPane == .keys && keystroke < .milliseconds(5) && moved && back && landed && inSight
            && pane == .keys && stillSearching && restored && paneSelected && paneOpened && many && listFocused && typedFromSidebar && nothing
            && emojiFound && emojiLanded && emojiInSight
        record(name, passed,
               "opened with the panes' list taking the keys: \(listFirst); ⌘F focused the field: \(focused); “escape” found, its row selected: \(found) (\(shown.joined(separator: ", "))), first pane \(firstPane?.title ?? "none"), "
                   + "search \(String(format: "%.2f", keystroke.milliseconds)) ms; ↓ moved: \(moved), ↑ back: \(back); ↩ landed: \(landed), in sight: \(inSight), "
                   + "pane \(pane?.title ?? "none"), still searching after: \(stillSearching); esc restored: \(restored); “clipboard” selects the pane: \(paneSelected), "
                   + "↩ opens it: \(paneOpened); “emoji” in the Catalog: \(emojiFound), ↩ landed \(emojiLanded), in sight \(emojiInSight); “search” lists \(manyPanes) panes; sidebar list focused: \(listFocused), typed into the field: \(typedFromSidebar) (“\(search.query)”), no results: \(nothing)",
               keystroke.milliseconds)
    }

    /// Every setting of `SettingsTable`, every row of `SettingsSearch.rows`,
    /// every permission and every shortcut in Keys: looked for as a search
    /// result is (from another pane), it shows in its pane, in sight, with
    /// Advanced opened when it is under it; or, while its pane shows it only
    /// with another setting on, that one does (`SettingsSearch.shownWith`).
    private func settingsSearchReachesEverySetting() async {
        let name = "Settings search: every setting, section, permission and shortcut opens its pane at its row, in sight (Advanced opened; a row hidden until another setting is on shows that one)"
        let settings = context.settings
        let search = settings.search
        settings.show(pane: .general)
        guard await waitUntil(timeout: 2, { settings.isVisible }) != nil else {
            record(name, false, "Settings did not open", nil)
            return
        }
        await pause(300)
        let targets: [(anchor: String, pane: String)] = SettingsTable.entries.map { ($0.key, $0.pane) }
            + SettingsSearch.rows.map { ($0.anchor, $0.pane) }
            + Permission.allCases.map { (SettingsSearch.permissionAnchor($0.rawValue), SettingsPane.privacy.rawValue) }
            + context.shortcuts.config.shortcuts.map { (SettingsSearch.shortcutAnchor($0.id), SettingsPane.keys.rawValue) }
            + [(SettingsSearch.shortcutAnchor(ShortcutStore.launcherOpenSettingsID), SettingsPane.launcher.rawValue)]
            // A linked app's commands, in Apps.
            + MacAction.appLinks().compactMap { action -> (anchor: String, pane: String)? in
                guard case .appLink(let command, _) = action else { return nil }
                return (SettingsSearch.entryAnchor(FeatureCatalog.appLinkEntryID(command.id)), SettingsPane.apps.rawValue)
            }
            // The user's shortcuts, in Apps on Shortcuts' page.
            + AppleShortcuts.all().map { (SettingsSearch.entryAnchor(FeatureCatalog.shortcutEntryID($0.id)), SettingsPane.apps.rawValue) }
        var failures: [String] = []
        var instead: [String] = []
        var slowest = Duration.zero
        var times: [(anchor: String, took: Duration)] = []
        for target in targets {
            guard let pane = SettingsPane(rawValue: target.pane) else {
                failures.append("\(target.anchor): no pane \(target.pane)")
                continue
            }
            // From another pane, as a search does.
            _ = settings.showAndDraw(pane == .general ? .about : .general)
            let start = ContinuousClock.now
            search.reveal(target.anchor, in: pane)
            guard await waitUntil(timeout: 2, { search.landed != nil }) != nil, let landed = search.landed else {
                failures.append("\(target.anchor): never shown")
                continue
            }
            slowest = max(slowest, .now - start)
            times.append((target.anchor, .now - start))
            if landed != target.anchor {
                // Allowed only where the table says the row waits for another.
                var allowed: [String] = []
                var next = target.anchor
                while let other = SettingsSearch.shownWith[next] {
                    allowed.append(other)
                    if other.isEmpty { break }
                    next = other
                }
                guard allowed.contains(landed) else {
                    failures.append("\(target.anchor): shown as “\(landed)”")
                    continue
                }
                instead.append("\(target.anchor)→\(landed.isEmpty ? "top" : landed)")
            }
            guard !landed.isEmpty else { continue }
            if await waitUntil(timeout: 1, { settings.anchorVisibility(landed) > 0.95 }) == nil {
                failures.append("\(target.anchor): out of sight (\(String(format: "%.2f", settings.anchorVisibility(landed))))")
            }
        }
        _ = settings.showAndDraw(.general)
        await closeSettings()
        let slow = times.sorted { $0.took > $1.took }.prefix(4).map { "\($0.anchor) \(String(format: "%.0f", $0.took.milliseconds)) ms" }
        let median = times.isEmpty ? .zero : times.map(\.took).sorted()[times.count / 2]
        record(name, failures.isEmpty,
               "\(targets.count) rows; shown with another: \(instead.isEmpty ? "none" : instead.joined(separator: ", ")); "
                   + "median \(String(format: "%.0f", median.milliseconds)) ms, slowest \(slow.joined(separator: ", ")); "
                   + "failures: \(failures.isEmpty ? "none" : failures.joined(separator: "; "))",
               slowest.milliseconds)
    }

    /// Every Settings pane fits the window (nothing cut on the right), with
    /// its optional parts shown (Agenda's alerts and their preview, Advanced
    /// open); a PNG of each, top and bottom, for design review.
    private func snapshotSettingsTabs() async {
        let name = "Settings: every pane fits the window, nothing cut on the right (Calendar's alerts and their card preview shown, the panes judged by the twelve rules light and dark with Advanced open too); the sidebar's blocks hold every pane once"
        let directory = context.snapshotDirectory
        let preferences = context.preferences
        let savedAlerts = preferences.agendaAlerts
        let savedAutoQuit = (preferences.autoQuit, preferences.autoQuitNever)
        preferences.agendaAlerts = [MeetingAlert(minutes: 0, style: .card), MeetingAlert(minutes: 5, style: .dark)]
        // Auto Quit shown on (its delay, an app never quit, what leaves the Mac).
        preferences.autoQuit = true
        preferences.autoQuitNever = ["com.apple.TextEdit"]
        defer {
            preferences.agendaAlerts = savedAlerts
            preferences.autoQuit = savedAutoQuit.0
            preferences.autoQuitNever = savedAutoQuit.1
        }
        var overflowing: [String] = []
        for pane in SettingsPane.allCases {
            context.settings.show(pane: pane)
            await pause(300)
            let overflow = context.settings.paneOverflow()
            if overflow > 1 { overflowing.append("\(pane.rawValue) +\(Int(overflow)) pt") }
            if let directory, let png = await context.settings.snapshotPNG() {
                try? png.write(to: directory.appendingPathComponent("settings-\(pane.rawValue).png"))
            }
            if context.settings.scrollPaneToBottom() {
                await pause(200)
                if let directory, let png = await context.settings.snapshotPNG() {
                    try? png.write(to: directory.appendingPathComponent("settings-\(pane.rawValue)-bottom.png"))
                }
            }
        }
        overflowing += await snapshotRuledPanes()
        // Settings → Privacy page by page, light then dark: what leaves the
        // Mac is most of it. Every row points to a pane that exists.
        var privacyPages = 0
        if let directory {
            for dark in [false, true] {
                context.settings.show(pane: .general)
                context.settings.setAppearance(NSAppearance(named: dark ? .darkAqua : .aqua))
                await pause(150)
                context.settings.show(pane: .privacy)
                await pause(400)
                for page in 1...12 {
                    if let png = await context.settings.snapshotPNG() {
                        try? png.write(to: directory.appendingPathComponent("settings-privacy-\(dark ? "dark" : "light")-\(page).png"))
                    }
                    privacyPages = max(privacyPages, page)
                    guard context.settings.scrollPaneOnePage() else { break }
                    await pause(200)
                }
            }
            context.settings.setAppearance(nil)
            // Every place in use, as on a Mac with every account and key:
            // each row drawn once (`settings-privacy-all-N.png`).
            var sample = PrivacyMap.Setup()
            sample.claude = .claudeCode
            sample.chatGPT = true
            sample.openAIKey = true
            sample.typeSafeKey = true
            sample.claudeCode = true
            sample.askWriter = .claude
            sample.commands = [.init(title: "Fix Spelling & Grammar", writer: .claude), .init(title: "Improve Writing", writer: .claude),
                               .init(title: "Translate to English", writer: .chatGPT), .init(title: "Plan My Day", writer: nil, acts: true)]
            sample.continueIn = .claude
            sample.fileMeaning = false
            sample.imageFolder = "Screenshots"
            sample.githubLogin = "octocat"
            sample.relayHost = "relay.example.com"
            sample.servers = ["linear", "nimbus-deployment"]
            sample.webhooks = ["n8n"]
            PrivacyPane.sample = sample
            context.settings.show(pane: .general)
            context.settings.setAppearance(NSAppearance(named: .aqua))
            await pause(150)
            context.settings.show(pane: .privacy)
            await pause(400)
            for page in 1...14 {
                if let png = await context.settings.snapshotPNG() {
                    try? png.write(to: directory.appendingPathComponent("settings-privacy-all-\(page).png"))
                }
                guard context.settings.scrollPaneOnePage() else { break }
                await pause(200)
            }
            PrivacyPane.sample = nil
            context.settings.setAppearance(nil)
        }
        let unknownPanes = PrivacyMap.all.compactMap(\.pane).filter { SettingsPane(rawValue: $0) == nil }
        record("Settings → Privacy: every row points to a pane that exists", unknownPanes.isEmpty,
               unknownPanes.isEmpty ? "\(PrivacyMap.all.count) rows, \(privacyPages) pages light and dark" : "unknown: \(unknownPanes)", nil)
        context.settings.show(pane: .general)
        // The sidebar's blocks hold every pane once, in the panes' order.
        let blocks = SettingsPane.blocks.flatMap { $0 } == SettingsPane.allCases
        record(name, overflowing.isEmpty && blocks,
               (overflowing.isEmpty ? "\(SettingsPane.allCases.count) panes fit" : "too wide: \(overflowing.joined(separator: ", "))")
                   + (blocks ? ", in \(SettingsPane.blocks.count) sidebar blocks" : ", the sidebar's blocks miss or repeat a pane"), nil)
    }

    /// The panes the Settings plan's twelve rules were applied to (General,
    /// Keys, Backup, GitHub, Your Details, Ask, SI Accounts, Tools,
    /// Commands), as they are
    /// judged: light and dark, Advanced closed then open where there is
    /// one, top and bottom (`settings-ask-light-advanced-bottom.png`…); SI
    /// Accounts with each provider writing, its account under Writing
    /// (`settings-aiAccounts-writes-chatgpt.png`…). The panes that run past
    /// the window, as "ask (dark, Advanced) +12 pt".
    private func snapshotRuledPanes() async -> [String] {
        var overflowing: [String] = []
        let preferences = context.preferences
        let saved = (preferences.writingModel, preferences.aiEngineMode)
        defer {
            Advanced.startsOpen = false
            preferences.writingModel = saved.0
            preferences.aiEngineMode = saved.1
            context.settings.setAppearance(nil)
        }
        func shoot(_ pane: SettingsPane, dark: Bool, as name: String, bottom: Bool = true) async {
            context.settings.show(pane: .general)
            context.settings.setAppearance(NSAppearance(named: dark ? .darkAqua : .aqua))
            await pause(150)
            context.settings.show(pane: pane)
            await pause(400)
            let overflow = context.settings.paneOverflow()
            if overflow > 1 {
                overflowing.append("\(pane.rawValue) (\(dark ? "dark" : "light")\(Advanced.startsOpen ? ", Advanced" : "")) +\(Int(overflow)) pt")
            }
            guard let directory = context.snapshotDirectory else { return }
            if let png = await context.settings.snapshotPNG() { try? png.write(to: directory.appendingPathComponent("\(name).png")) }
            // Keys: its shortcut list's sections, named by their chains.
            if pane == .keys, bottom, let window = NSApp.windows.first(where: { $0.isVisible && $0.title == SettingsPane.keys.title }) {
                Self.scroll(window, to: 0.3)
                await pause(200)
                if let png = await context.settings.snapshotPNG() { try? png.write(to: directory.appendingPathComponent("\(name)-chains.png")) }
            }
            if bottom, context.settings.scrollPaneToBottom() {
                await pause(200)
                if let png = await context.settings.snapshotPNG() { try? png.write(to: directory.appendingPathComponent("\(name)-bottom.png")) }
            }
        }
        let withAdvanced: [SettingsPane] = [.general, .keys, .github, .ask, .aiAccounts, .tools, .commands, .calendar, .windows]
        for open in [false, true] {
            Advanced.startsOpen = open
            for dark in [false, true] {
                for pane in [SettingsPane.general, .keys, .backup, .github, .apps, .yourDetails, .ask, .aiAccounts, .tools, .commands, .calendar,
                             .reminders, .windows]
                where !open || withAdvanced.contains(pane) {
                    await shoot(pane, dark: dark, as: "settings-\(pane.rawValue)-\(dark ? "dark" : "light")\(open ? "-advanced" : "")")
                }
            }
        }
        // Your Rules: a few written, without a key, then with one (a
        // stand-in: nothing is judged while the pane shows).
        Advanced.startsOpen = false
        let toolSettings = context.tools.settings
        let rules = toolSettings.rules
        toolSettings.setRulesForSelfTest(ApprovalRules.suggestions.map { ApprovalRule(text: $0.text, effect: $0.effect) }
            + [ApprovalRule(text: "Reading my clipboard is fine, but ask before replacing what I selected", effect: .allow)])
        let judgeKeys = context.tools.judge?.keys
        for dark in [false, true] {
            context.tools.judge?.keys = { [:] }
            await shoot(.ask, dark: dark, as: "settings-ask-rules-nokey-\(dark ? "dark" : "light")")
            context.tools.judge?.keys = { [.typeSafe: "selftest-stand-in"] }
            await shoot(.ask, dark: dark, as: "settings-ask-rules-\(dark ? "dark" : "light")")
            await shoot(.tools, dark: dark, as: "settings-tools-rules-\(dark ? "dark" : "light")", bottom: false)
        }
        if let judgeKeys { context.tools.judge?.keys = judgeKeys }
        toolSettings.setRulesForSelfTest(rules)
        // Each provider writing: what it needs shows under Writing.
        Advanced.startsOpen = false
        let writers: [(String, ModelChoice, AIEngineMode)] = [
            ("chatgpt", ModelChoice(provider: .chatGPT, model: "gpt-6-luna", effort: .low), saved.1),
            ("openai", ModelChoice(provider: .openAI, model: "gpt-6-luna", effort: .low), saved.1),
            ("claude-key", .standard, .apiKey)
        ]
        for (file, choice, mode) in writers {
            preferences.writingModel = choice
            preferences.aiEngineMode = mode
            await shoot(.aiAccounts, dark: false, as: "settings-aiAccounts-writes-\(file)", bottom: false)
        }
        return overflowing
    }

    // MARK: - Settings tools

    /// `selftest settingtools`: skil.li's settings through its tools, on
    /// scratch preferences (never the Mac's own): every setting has a tool,
    /// get_settings reads every pane and no secret, set_setting waits for
    /// the card (Esc changes nothing, Return applies it and an open pane
    /// shows it), refusals name what is valid, the lists' tools round-trip,
    /// the skill ships with the server.
    // MARK: - Asks on a schedule

    /// The scheduled asks this check made, removed after it.
    private func keepingScheduledAsks(_ body: () async -> Void) async {
        let scheduler = context.scheduler
        let before = Set(scheduler.asks.map(\.id))
        await body()
        for ask in scheduler.asks where !before.contains(ask.id) { scheduler.remove(ask.id) }
        scheduler.clock = { .now }
        scheduler.refresh()
    }

    /// Said in Ask (French and English): said back in the card, Keep ↩ /
    /// Cancel esc; esc keeps nothing, ↩ keeps it and the card closes
    /// without a word.
    private func scheduleSaidInAskIsKept() async {
        let name = "Ask on a schedule: “every weekday at 8:30 …” said back in the card (Keep ↩, Cancel esc), esc keeps nothing; “tous les lundis à 9h résume mes PR” kept with ↩, the card gone"
        let actions = context.aiActions
        let popover = actions.popover
        let scheduler = context.scheduler
        await keepingScheduledAsks {
            guard await focusTestWindow() else { return }
            window.makeFirstResponder(textView)
            textView.string = ""
            let count = scheduler.asks.count
            // What the model reads (real ones in `selftest decide`, `askReadsSchedules`).
            let english = "every weekday at 8:30 tell me my day"
            plansRead(phrase(english, "ask", "tell me my day", longest: 8)
                .merging(["schedule_repeat": "every weekday", "hour": "8", "minute": "30", "is_reminder": "no"]) { $1 }, route: .schedule)
            defer { plansRead(nil) }
            actions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": english])
            let asked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .done && popover.shownTitle == "On a Schedule" } != nil
            await pause(250)
            let englishSaid = popover.shownText
            let hints = popover.hintTitles
            // As the Mac shows it: glass flipped to another appearance in place is not.
            await saveScreenshot(of: popover.window, as: "ask-schedule-confirm.png")
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
            let escKeptNothing = scheduler.asks.count == count

            guard await focusTestWindow() else { return }
            let frenchSaid = "tous les lundis à 9h résume mes PR"
            plansRead(phrase(frenchSaid, "ask", "résume mes PR", longest: 8)
                .merging(["schedule_repeat": "some days", "day_1": "monday", "day_2": "none", "hour": "9", "minute": "0", "is_reminder": "no"]) { $1 }, route: .schedule)
            actions.run(PromptLibrary.askID, triggeredAt: .now, answers: ["instruction": frenchSaid])
            let askedFrench = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .done && popover.shownTitle == "On a Schedule" } != nil
            let french = popover.shownText
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let closed = await waitUntil(timeout: 1) { !popover.isVisible } != nil
            let kept = scheduler.asks.last
            let passed = asked && askedFrench && englishSaid.contains("Every weekday at 8:30: tell me my day") && englishSaid.contains("First:")
                && hints == ["Keep", "Cancel"] && escKeptNothing && closed && kept?.ask == "résume mes PR"
                && kept?.schedule.spoken == "Every Monday at 9:00" && actions.lastRoute == .schedule
            record(name, passed, "said “\(englishSaid.replacingOccurrences(of: "\n", with: " ⏎ "))”, keys \(hints), esc kept nothing: \(escKeptNothing); “\(french.replacingOccurrences(of: "\n", with: " ⏎ "))” kept as “\(kept?.spoken ?? "nothing")”, the card closed: \(closed)", nil)
        }
    }

    /// One a minute ahead: its timer is set for that minute; fired early (the
    /// clock moved to it), it runs out of sight; the user away, its answer
    /// waits; back, it shows as Ask's card in the launcher's place (its
    /// Markdown styled, ⇥ follows up, the schedule in its status); kept on
    /// the row, next run tomorrow.
    private func scheduledAskFiresAndShowsItsCard() async {
        let name = "Scheduled ask: a minute ahead, its timer set for it; fired early it runs out of sight, waits while the user is away, then shows its answer in the card; kept, next tomorrow"
        let actions = context.aiActions
        let popover = actions.popover
        let scheduler = context.scheduler
        let answer = "## 3 pull requests\n- **#12** ready to merge\n- **#14** waiting for review\n- **#15** checks failing"
        context.ai.testEngine = FakeTextEngine(chunks: [answer], delay: .milliseconds(10))
        actions.routeOverride = .answer
        let spot = actions.launcherSpot
        let frame = window.frame
        // In the test window: a see-through card is captured only over it.
        actions.launcherSpot = { NSRect(x: frame.minX + 70, y: frame.maxY - 230, width: 580, height: 60) }
        defer {
            context.ai.testEngine = nil
            actions.routeOverride = nil
            actions.userPresenceOverride = nil
            actions.launcherSpot = spot
        }
        await keepingScheduledAsks {
            guard await focusTestWindow() else { return }
            let calendar = Calendar.current
            let now = Date.now
            let soon = now.addingTimeInterval(60)
            let schedule = AskSchedule(.daily, hour: calendar.component(.hour, from: soon), minute: calendar.component(.minute, from: soon),
                                       start: calendar.startOfDay(for: now))
            let ask = scheduler.add("sum up my pull requests", schedule: schedule)
            guard let due = schedule.next(after: now) else {
                record(name, false, "no next time", nil)
                return
            }
            let timerSet = scheduler.nextFire.map { abs($0.timeIntervalSince(due)) < 2 } ?? false
            // Away: it runs, its answer waits.
            actions.userPresenceOverride = false
            scheduler.clock = { due.addingTimeInterval(1) }
            scheduler.fireDue()
            let ran = await waitUntil(timeout: 5) { scheduler.ask(ask.id)?.lastAnswer == answer && !scheduler.running.contains(ask.id) } != nil
            await pause(700)
            let waited = !popover.isVisible
            // Back: the card.
            actions.userPresenceOverride = true
            let shown = await waitUntil(timeout: 5) { popover.isVisible && popover.phase == .done && actions.lastScheduledShown?.id == ask.id } != nil
            await pause(300)
            let text = popover.shownText
            let status = popover.shownStatus
            let title = popover.shownTitle
            let hints = popover.hintTitles
            // As the Mac shows it: glass flipped to another appearance in place is not.
            await saveScreenshot(of: popover.window, as: "ask-schedule-answer.png")
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 2) { !scheduler.running.contains(ask.id) }
            let after = scheduler.ask(ask.id)
            let tomorrow = calendar.date(byAdding: .day, value: 1, to: due) ?? due
            let next = after?.due()
            let passed = timerSet && ran && waited && shown && title == "Sum up my pull requests" && text.contains("#12 ready to merge")
                && !text.contains("**") && status.hasPrefix(schedule.spoken) && hints.contains("Follow up")
                && after?.lastAnswer == answer && after?.lastFailed == false && next.map { calendar.isDate($0, inSameDayAs: tomorrow) } == true
            record(name, passed, "timer set for its minute: \(timerSet), ran: \(ran), waited away: \(waited), shown: \(shown) “\(title)” · “\(status)” \(hints), kept: \(after?.lastAnswer == answer), next \(next.map { ScheduledAsks.moment($0) } ?? "none")", nil)
        }
    }

    /// Asleep through three of its times: at wake it runs once, a minute
    /// later, then waits for the next.
    private func missedScheduledAskRunsOnceAtWake() async {
        let name = "Scheduled ask: three times missed while asleep run once, a minute after the wake; nothing more until the next"
        final class Count: @unchecked Sendable { var runs = 0 }
        let scheduler = context.scheduler
        let count = Count()
        let run = scheduler.run
        scheduler.run = { _ in
            count.runs += 1
            return ("Done.", false)
        }
        defer { scheduler.run = run }
        await keepingScheduledAsks {
            let calendar = Calendar.current
            let now = Date.now
            let earlier = now.addingTimeInterval(-3_600)
            scheduler.clock = { now.addingTimeInterval(-3 * 86_400 - 7_200) }
            let ask = scheduler.add("tell me my day", schedule: AskSchedule(.daily, hour: calendar.component(.hour, from: earlier),
                                                                             minute: calendar.component(.minute, from: earlier),
                                                                             start: calendar.startOfDay(for: now.addingTimeInterval(-3 * 86_400))))
            scheduler.clock = { now }
            scheduler.refresh(caughtUp: true)
            let aMinuteLater = scheduler.nextFire.map { abs($0.timeIntervalSince(now) - ScheduledAsks.catchUpDelay) < 2 } ?? false
            scheduler.clock = { now.addingTimeInterval(61) }
            scheduler.fireDue()
            _ = await waitUntil(timeout: 2) { count.runs > 0 && !scheduler.running.contains(ask.id) }
            scheduler.fireDue()
            await pause(200)
            let next = scheduler.ask(ask.id)?.due()
            let tomorrow = calendar.date(byAdding: .day, value: 1, to: earlier) ?? earlier
            record(name, aMinuteLater && count.runs == 1 && next.map { calendar.isDate($0, inSameDayAs: tomorrow) } == true,
                   "first run a minute after the wake: \(aMinuteLater), \(count.runs) run(s), next \(next.map { ScheduledAsks.moment($0) } ?? "none")", nil)
        }
    }

    /// The tools: add asks in the card every time (no Always), esc changes
    /// nothing; list reads when and what, a last answer only as set;
    /// pause, then remove.
    private func scheduledAsksThroughTools() async {
        let name = "Scheduled asks through tools: add, pause, remove ask in the card every time (no Always), esc changes nothing; list and get_settings say a last answer only as set"
        let popover = context.aiActions.popover
        let scheduler = context.scheduler
        let secret = "Paul Confidentiel owes 1 234 €"
        let run = scheduler.run
        scheduler.run = { _ in (secret, false) }
        defer { scheduler.run = run }
        await keepingScheduledAsks {
            guard await focusTestWindow() else { return }
            async let added = skilliCall(SettingsTable.Tool.addScheduledAsk, #"{"when":"every weekday at 8:30","ask":"tell me my day"}"#)
            let asked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
            await pause(250)
            let card = popover.shownText
            let hints = popover.hintTitles
            await saveScreenshot(of: popover.window, as: "ai-card-add-scheduled-ask.png")
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let add = await added
            guard let ask = scheduler.asks.first(where: { $0.ask == "tell me my day" }) else {
                record(name, false, "not added: \(add.output)", nil)
                return
            }
            scheduler.runNow(ask.id)
            _ = await waitUntil(timeout: 2) { scheduler.ask(ask.id)?.lastAnswer == secret }
            let list = await skilliCall(SettingsTable.Tool.listScheduledAsks)
            let report = await skilliCall(SettingsTable.Tool.getSettings, #"{"pane":"Ask"}"#)
            let listed = list.output.contains("Every weekday at 8:30") && list.output.contains("tell me my day")
                && list.output.contains(#""last_answer":"set""#) && !list.output.contains("Confidentiel") && !report.output.contains("Confidentiel")

            guard await focusTestWindow() else { return }
            async let paused = skilliCall(SettingsTable.Tool.pauseScheduledAsk, #"{"ask":"tell me my day"}"#)
            _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
            await pause(250)
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let pausing = await paused
            let isPaused = scheduler.ask(ask.id)?.isOn == false

            guard await focusTestWindow() else { return }
            async let declined = skilliCall(SettingsTable.Tool.removeScheduledAsk, #"{"ask":"tell me my day"}"#)
            _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
            await pause(250)
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            let kept = await declined
            let stillThere = scheduler.ask(ask.id) != nil && kept.status != 0
            guard await focusTestWindow() else { return }
            async let removed = skilliCall(SettingsTable.Tool.removeScheduledAsk, #"{"ask":"tell me my day"}"#)
            _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
            await pause(250)
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let remove = await removed
            let gone = scheduler.ask(ask.id) == nil
            let passed = asked && card.contains("Ask → On a Schedule + Every weekday at 8:30: tell me my day") && hints == ["Allow", "Deny"]
                && add.status == 0 && listed && pausing.status == 0 && isPaused && stillThere && remove.status == 0 && gone
            record(name, passed, "card “\(card.replacingOccurrences(of: "\n", with: " ⏎ "))” \(hints); listed: \(listed); paused: \(isPaused); esc kept it: \(stillThere); removed: \(gone) (\(remove.output.prefix(80)))", nil)
        }
    }

    /// Settings → Ask: the skills folder and On a Schedule last, its rows
    /// with when, what and the last run; a row's switch pauses it. Within
    /// the window; light and dark.
    private func scheduledAsksInSettings() async {
        let name = "Settings → Ask: Skills (folder, Claude Code's too) and On a Schedule last: when, what, the last run's line; a switch pauses; fits the window"
        let scheduler = context.scheduler
        let settings = context.settings
        let run = scheduler.run
        scheduler.run = { ask in
            ask.ask.hasPrefix("tell") ? ("**You have 3 meetings**, the first at 10:00 with Paul.", false) : ("Claude Code: not signed in.", true)
        }
        defer { scheduler.run = run }
        await keepingScheduledAsks {
            let monday = scheduler.add("sum up my pull requests", schedule: AskSchedule(.weekly, weekdays: [2], hour: 9, start: .now))
            let day = scheduler.add("tell me my day", schedule: AskSchedule(.weekly, weekdays: [2, 3, 4, 5, 6], hour: 8, minute: 30, start: .now))
            let month = scheduler.add("list my subscriptions and what they cost", schedule: AskSchedule(.monthly, day: 1, hour: 9, start: .now))
            let failing = scheduler.add("check the deploys", schedule: AskSchedule(.daily, hour: 18, start: .now))
            scheduler.runNow(day.id)
            scheduler.runNow(failing.id)
            _ = await waitUntil(timeout: 2) { scheduler.running.isEmpty }
            scheduler.setOn(month.id, false)
            // Advanced open: the skills' rows above the list.
            Advanced.startsOpen = true
            defer { Advanced.startsOpen = false }
            settings.show(pane: .ask)
            await pause(600)
            let overflow = settings.paneOverflow()
            _ = settings.scrollPaneToBottom()
            await pause(400)
            await captureSettingsBothWays(as: "settings-ask-schedule")
            let rows = Self.axElements(roles: [kAXStaticTextRole], where: { $0.contains("Every Monday at 9:00") || $0.contains("Every weekday at 8:30") })
            let lastLine = Self.axElements(roles: [kAXStaticTextRole, kAXButtonRole], where: { $0.contains("You have 3 meetings") })
            scheduler.setOn(monday.id, false)
            let paused = scheduler.ask(monday.id)?.isOn == false && scheduler.ask(monday.id)?.due() == nil
            await closeSettings()
            record(name, overflow <= 1 && !rows.isEmpty && paused,
                   "overflow \(Int(overflow)) pt, rows read: \(rows.count), last run's line read: \(!lastLine.isEmpty), paused: \(paused)", nil)
        }
    }

    /// The real Claude Code (skipped without it): a skill in the user's
    /// folder reaches Ask's agent as Claude Code's own skill (the plugin
    /// folder made for the run) and is used.
    private func agentUsesTheUsersSkills() async {
        let name = "Skills: a SKILL.md in skil.li's skills folder reaches Ask's agent (the real Claude Code, Haiku) and its answer follows it"
        await context.ai.refresh()
        guard context.ai.subscription.binary != nil, context.ai.isSignedIn else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "Claude Code is not signed in here", latencyMs: nil))
            return
        }
        guard let folder = context.tools.tools.skillsFolder else {
            record(name, false, "no skills folder", nil)
            return
        }
        let skill = folder.appendingPathComponent("selftest-secret-word", isDirectory: true)
        try? FileManager.default.createDirectory(at: skill, withIntermediateDirectories: true)
        try? AgentSkill.markdown(name: "selftest-secret-word", description: "Use when the user asks for the self-test's secret word.",
                                 instructions: "The self-test's secret word is pamplemousse-42. Answer with the word only.")
            .write(to: skill.appendingPathComponent(AgentSkill.fileName), atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: skill) }
        let popover = context.aiActions.popover
        let command = scratchCommand(prompt: "What is the self-test's secret word? Reply with the word only.", output: .card)
        var act = command
        act.tools = ["apps"]
        act.model = .claude("haiku")
        context.aiCommands.save(act)
        defer { context.aiCommands.delete(command.id) }
        guard await focusTestWindow() else { return }
        let start = ContinuousClock.now
        guard await run(act, on: "") else {
            record(name, false, "the card did not show", nil)
            return
        }
        _ = await waitUntil(timeout: 90) { popover.phase == .done || popover.phase == .failed }
        let latency = ContinuousClock.now - start
        let text = popover.shownText
        let steps = context.aiActions.lastSteps.map(\.title)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        record(name, text.contains("pamplemousse-42"), "answered “\(text.prefix(80))”, steps \(steps), \(Int(latency.milliseconds / 1_000)) s", latency.milliseconds)
    }

    private func settingToolsChecks() async {
        guard let tools = context.tools.settingTools else {
            record("Settings tools", false, "the tool server has no settings tools", nil)
            return
        }
        let suite = "skilli-selftest-settings-\(getpid())"
        guard let defaults = UserDefaults(suiteName: suite) else {
            record("Settings tools", false, "no scratch defaults", nil)
            return
        }
        let scratch = Preferences(defaults: defaults)
        let saved = tools.preferences
        tools.preferences = scratch
        defer {
            tools.preferences = saved
            UserDefaults.standard.removePersistentDomain(forName: suite)
        }
        context.settings.close()
        settingsTableCoversEveryPreference(tools, scratch: scratch)
        await getSettingsReadsEveryPaneAndNoSecret(scratch)
        await settingToolsRefuseWhatIsNotValid(scratch)
        await setSettingWaitsForTheCard(scratch)
        await settingListsRoundTrip(scratch)
        await settingsSkillShipsWithTheServer()
    }

    /// Every `Preferences` property is in `SettingsTable` (or said not to
    /// be in a pane), every pane exists, every key is bound, every choice
    /// the pane offers is taken and read back.
    private func settingsTableCoversEveryPreference(_ tools: SettingTools, scratch: Preferences) {
        let name = "Every setting has a tool: each preference in the table, each key bound, each choice taken and read back"
        let stored = Mirror(reflecting: scratch).children.compactMap(\.label)
            .filter { $0.hasPrefix("_") && !$0.hasPrefix("_$") }.map { String($0.dropFirst()) }
        let missing = Set(stored).subtracting(SettingsTable.preferences).subtracting(SettingsTable.notInPanes.keys).sorted()
        let panes = SettingsTable.entries.filter { SettingsPane(rawValue: $0.pane) == nil }.map(\.key)
            + SettingsPane.allCases.filter { !SettingsTable.panes.contains($0.rawValue) }.map(\.rawValue)
        var unbound: [String] = []
        for entry in SettingsTable.entries {
            guard let binding = tools.bindings[entry.key] else {
                unbound.append(entry.key)
                continue
            }
            guard entry.usesSetSetting else { continue }
            switch entry.kind {
            case .list(_, let adds):
                if binding.remove == nil || (adds && binding.add == nil) { unbound.append(entry.key) }
            default:
                // A change that takes time sets through `setAsync`.
                if binding.set == nil && binding.setAsync == nil { unbound.append(entry.key) }
            }
        }
        var refused: [String] = []
        for entry in SettingsTable.entries where entry.preference != nil && entry.usesSetSetting {
            guard let binding = tools.bindings[entry.key], let set = binding.set else { continue }
            let values: [SettingValue] = switch entry.kind {
            case .toggle: [.bool(false), .bool(true)]
            case .choice(let options): options.map { .text($0.value) }
            case .choiceOrNumber(let options, _, let unit): options.map { .text($0.value) } + [.text("\(unit):14")]
            default: []
            }
            for value in values {
                do {
                    try set(value)
                    if binding.get() != value { refused.append("\(entry.key)=\(value)") }
                } catch {
                    refused.append("\(entry.key)=\(value): \(error.localizedDescription)")
                }
            }
        }
        let definitions = SettingsTable.Tool.all.compactMap(SkilliTools.definition)
        let tooled = definitions.count == SettingsTable.Tool.all.count && definitions.allSatisfy { $0.group == .settings }
            && definitions.allSatisfy { $0.risk == (SettingsTable.Tool.reads.contains($0.name) ? .read : .changes) }
        let counts = SettingsTable.panes.compactMap { pane -> String? in
            let entries = SettingsTable.entries.filter { $0.pane == pane }
            guard !entries.isEmpty else { return nil }
            return "\(SettingTools.title(of: pane)) \(entries.filter(\.isSettable).count)/\(entries.count)"
        }
        record(name, stored.count > 40 && missing.isEmpty && panes.isEmpty && unbound.isEmpty && refused.isEmpty && tooled,
               "\(stored.count) preferences; without an entry: \(missing); panes unknown: \(panes); unbound: \(unbound); choices refused: \(refused.prefix(6)); tools: \(tooled); settable by pane: \(counts.joined(separator: ", "))",
               nil)
    }

    /// get_settings: every pane by its title (SI Accounts, never AI), every
    /// key; keys and tokens only as set or not set; the user's own content
    /// (About You, a field's value, a snippet's text, a place's address, a
    /// person, a quicklink's address) never, only whether it is set; a pane
    /// alone.
    private func getSettingsReadsEveryPaneAndNoSecret(_ scratch: Preferences) async {
        let name = "get_settings: every pane and setting; keys, Keychain fields and the user's own content only as set or not set"
        let iban = "FR7630006000011234567890189"
        let siret = "98765432100019"
        let about = "Selftest-about: I write to Margot in French"
        let signature = "Selftest-signature: call me on 06 98 76 54 32"
        let address = "12 rue Selftest-Secrète, Paris"
        let person = "Margot Selftest-Person"
        let link = "https://intranet.selftest-secret.example/search?q={query}"
        let sensitive = FormExtra(label: "IBAN", isSensitive: true)
        FormSecrets.save(iban, for: sensitive)
        let profile = PromptLibrary.shared.profile
        PromptLibrary.shared.saveProfile(about)
        let snippet = context.snippets.save(Snippet(id: "", name: "Selftest Signature", keyword: ";stsig", text: signature))
        let quicklinks = context.tools.settingTools?.quicklinks
        let intranet = Quicklink(name: "Selftest Intranet", keyword: "stin", url: link)
        quicklinks?.save(intranet)
        defer {
            FormSecrets.forget(sensitive)
            PromptLibrary.shared.saveProfile(profile)
            context.snippets.delete(snippet.id)
            quicklinks?.delete(intranet.id)
        }
        scratch.formProfiles = FormProfiles(mine: [FormExtra(label: "SIRET", isSensitive: false, value: siret), sensitive],
                                            others: [FormPerson(name: person)])
        scratch.reminderPlaces = [SavedPlace(name: "Selftest Office", address: address, latitude: 48.85, longitude: 2.35)]
        let start = ContinuousClock.now
        let all = await skilliCall(SettingsTable.Tool.getSettings)
        let latency = ContinuousClock.now - start
        let backup = await skilliCall(SettingsTable.Tool.getSettings, #"{"pane":"Backup"}"#)
        if let directory = context.snapshotDirectory { try? Data(all.output.utf8).write(to: directory.appendingPathComponent("get-settings.json")) }
        let root = (try? JSONSerialization.jsonObject(with: Data(all.output.utf8))) as? [String: Any]
        let panes = root?["panes"] as? [[String: Any]] ?? []
        let titles = panes.compactMap { $0["pane"] as? String }
        let expected = SettingsTable.panes.filter { pane in SettingsTable.entries.contains { $0.pane == pane } }.map(SettingTools.title(of:))
        let settings = panes.flatMap { $0["settings"] as? [[String: Any]] ?? [] }
        let keys = Set(settings.compactMap { $0["key"] as? String })
        let secrets = settings.filter { item in SettingsTable.entries.contains { $0.key == item["key"] as? String && $0.secret } }
        // Every secret the table holds (the keys, the relay's token, Klipy's), each only set or not.
        let secretsHidden = secrets.count == SettingsTable.entries.filter(\.secret).count
            && secrets.allSatisfy { ["set", "not set"].contains($0["value"] as? String ?? "") }
        // The decision keys the self-test may hold: never in what agents read.
        let keyValues = [context.ai.decisionKey(for: .openAI), context.ai.decisionKey(for: .typeSafe)].compactMap { $0 }.filter { $0.count > 8 }
        let noKey = !keyValues.contains { all.output.contains($0) } && !all.output.contains("sk-ant-")
        // The user's own content: none of it, only whether it is set.
        let leaked = [iban, siret, about, "Selftest-about", signature, "Selftest-signature", address, "Selftest-Secrète", person,
                      "Selftest-Person", link, "selftest-secret"].filter { all.output.contains($0) }
        func value(_ key: String) -> Any? { settings.first { $0["key"] as? String == key }?["value"] }
        let said = (value("aboutYou") as? String) == "set (7 words)"
            && (value("otherDetails") as? [[String: String]]) == [["field": "SIRET", "value": "set"], ["field": "IBAN", "kept": "in the Keychain", "value": "set"]]
            && (value("people") as? String) == "set (1)"
            && (value("reminderPlaces") as? [[String: String]]) == [["name": "Selftest Office", "address": "set"]]
            && (value("snippets") as? [[String: String]])?.contains(["name": "Selftest Signature", "keyword": ";stsig", "text": "set"]) == true
            && (value("quicklinks") as? [[String: String]])?.contains(["name": "Selftest Intranet", "keyword": "stin", "address": "set"]) == true
        let onePane = ((try? JSONSerialization.jsonObject(with: Data(backup.output.utf8))) as? [String: Any])?["panes"] as? [[String: Any]]
        let backupOnly = onePane?.count == 1 && onePane?.first?["pane"] as? String == "Backup"
        let brand = titles.contains("SI Accounts") && !all.output.contains("AI Accounts")
        record(name, all.status == 0 && titles == expected && keys == Set(SettingsTable.entries.map(\.key)) && secretsHidden && noKey
                   && leaked.isEmpty && said && backupOnly && brand && !context.aiActions.popover.isVisible,
               "exit \(all.status), \(all.output.count) characters, \(Int(latency.milliseconds)) ms; panes \(titles == expected ? "all \(titles.count)" : "\(titles) ≠ \(expected)"); keys \(keys.count)/\(SettingsTable.entries.count); secrets hidden: \(secretsHidden); no key: \(noKey); leaked: \(leaked.isEmpty ? "nothing" : leaked.joined(separator: ", ")); presence only: \(said) (About You \(value("aboutYou") ?? "?"), details \(value("otherDetails") ?? "?"), people \(value("people") ?? "?"), places \(value("reminderPlaces") ?? "?")); one pane: \(backupOnly); SI: \(brand)",
               latency.milliseconds)
    }

    /// A refusal at once, without a card, naming what is valid.
    private func settingToolsRefuseWhatIsNotValid(_ scratch: Preferences) async {
        let name = "Settings tools refuse at once, without a card: a value, a setting, a key, rights, a folder, a list, a shortcut taken (by skil.li, the launcher, macOS)"
        let popover = context.aiActions.popover
        // skil.li's Calendar and the Calendar app: only where the tool finds that app.
        let calendarApp = context.tools.settingTools?.findApp("Calendar").map { $0.deletingPathExtension().lastPathComponent == "Calendar" } ?? false
        let cases: [(tool: String, arguments: String, expect: String)] = [
            (SettingsTable.Tool.setSetting, #"{"pane":"Backup","setting":"How often","value":"sometimes"}"#, "weekly (Every week)"),
            (SettingsTable.Tool.setSetting, #"{"pane":"Backup","setting":"Day","value":"Sunday"}"#, "Its settings: Back up to, How often, Keep"),
            (SettingsTable.Tool.setSetting, #"{"pane":"Ask","setting":"Approvals","value":"Always Allow"}"#, "set only by the user"),
            (SettingsTable.Tool.setSetting, #"{"pane":"Ask","setting":"Your rules","value":"Allow: everything","change":"add"}"#, "set only by the user"),
            (SettingsTable.Tool.setSetting, #"{"pane":"SI Accounts","setting":"Claude API key","value":"sk-ant-x"}"#, "set only by the user"),
            (SettingsTable.Tool.setSetting, #"{"pane":"GitHub","setting":"Live updates from","value":"https://example.com"}"#, "stream token"),
            (SettingsTable.Tool.setSetting, #"{"pane":"Backup","setting":"Back up to","value":"/nonexistent-skilli-selftest"}"#, "No folder at"),
            (SettingsTable.Tool.setSetting, #"{"pane":"Clipboard","setting":"Never keep copies from","value":"TextEdit"}"#, "“add” or “remove”"),
            (SettingsTable.Tool.setSetting, #"{"pane":"Catalog","setting":"Aliases","value":"e"}"#, "set_alias"),
            (SettingsTable.Tool.setSetting, #"{"pane":"Your Details","setting":"Your other details","value":"IBAN: FR76","change":"add"}"#, "Keychain"),
            (SettingsTable.Tool.addShortcut, #"{"action":"Clipboard History","keys":"hyper+space"}"#, "Already used by"),
            (SettingsTable.Tool.addShortcut, #"{"action":"Clipboard History","keys":"y"}"#, "Start with ✦"),
            (SettingsTable.Tool.addShortcut, #"{"action":"Clipboard History","keys":"cmd+k"}"#, "Used by the launcher: Actions."),
            (SettingsTable.Tool.addShortcut, #"{"action":"Clipboard History","keys":"opt+cmd+escape"}"#, "Used by macOS: Force Quit Applications"),
            // Every launcher command takes one: found by name (refused for its keys only).
            (SettingsTable.Tool.addShortcut, #"{"action":"Search Snippets","keys":"y"}"#, "Start with ✦"),
            (SettingsTable.Tool.setAlias, #"{"alias":"two words","item":"Emoji"}"#, "without a space"),
            (SettingsTable.Tool.createQuicklink, #"{"name":"Bad","url":"ftp://example.com/{query}"}"#, "https://")
        ] + (calendarApp ? [(SettingsTable.Tool.addShortcut, #"{"action":"Calendar","keys":"ctrl+opt+cmd+8"}"#, "Two are named “Calendar”")] : [])
        let schedule = scratch.backupSchedule
        let details = scratch.formProfiles
        var wrong: [String] = []
        for test in cases {
            let reply = await skilliCall(test.tool, test.arguments)
            if reply.status == 0 || !reply.output.contains(test.expect) { wrong.append("\(test.arguments): “\(reply.output.prefix(140))”") }
            if popover.isVisible { wrong.append("\(test.arguments): a card") }
        }
        let unchanged = scratch.backupSchedule == schedule && scratch.formProfiles == details
        record(name, wrong.isEmpty && unchanged, wrong.isEmpty ? "\(cases.count) refused with what is valid; nothing changed: \(unchanged)" : wrong.joined(separator: " | "), nil)
    }

    /// set_setting: the card says the change in the pane's words; Esc
    /// changes nothing; Return applies it, and an open pane shows it.
    private func setSettingWaitsForTheCard(_ scratch: Preferences) async {
        let name = "set_setting asks every time: “Backup: How often → Every week”, no Always, an allow right and Always Allow ignored, Esc changes nothing, Return applies it, the open pane shows it"
        let popover = context.aiActions.popover
        scratch.backupSchedule = .daily
        scratch.snippetExpansion = true
        let pane = NSWindow(contentViewController: NSHostingController(rootView: SnippetsPane(preferences: scratch, context: context.settings.makeContext(), open: { _ in })
            .frame(width: 560, height: 360)))
        pane.title = "Snippets (self-test)"
        pane.isReleasedWhenClosed = false
        // Beside the test window, not over it: its capture shows the pane alone.
        let screen = window.screen?.visibleFrame ?? .zero
        pane.setFrameOrigin(NSPoint(x: min(window.frame.maxX + 16, screen.maxX - pane.frame.width), y: window.frame.maxY - pane.frame.height))
        pane.orderFrontRegardless()
        defer { pane.close() }
        guard await focusTestWindow() else { return }

        // Declined: nothing changes.
        async let declined = skilliCall(SettingsTable.Tool.setSetting, #"{"pane":"Backup","setting":"How often","value":"Every week"}"#)
        let asked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        await pause(250)
        let card = popover.shownText
        let hints = popover.hintTitles
        await saveScreenshot(of: popover.window, as: "ai-card-set-setting.png")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let refusal = await declined
        let kept = scratch.backupSchedule == .daily && refusal.status != 0 && refusal.output.contains("declined")
        _ = await waitUntil(timeout: 1) { !popover.isVisible }

        // Allowed: applied, said back.
        guard await focusTestWindow() else { return }
        async let allowed = skilliCall(SettingsTable.Tool.setSetting, #"{"pane":"Backup","setting":"How often","value":"Every week"}"#)
        _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
        await pause(250)
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let applied = await allowed
        let set = scratch.backupSchedule == .weekly && applied.status == 0 && applied.output.contains("Backup: How often → Every week")
        let again = await skilliCall(SettingsTable.Tool.setSetting, #"{"setting":"backupSchedule","value":"weekly"}"#)
        let already = again.status == 0 && again.output.contains("already") && !popover.isVisible

        // The pane open on these preferences shows the change at once: its
        // one switch, read through Accessibility in its window.
        func paneSwitch() -> Int? {
            guard let root = Self.axElements(roles: [kAXWindowRole], where: { $0 == pane.title }).first else { return nil }
            return Self.axSwitchValues(under: root).first
        }
        let before = paneSwitch()
        guard await focusTestWindow() else { return }
        async let toggled = skilliCall(SettingsTable.Tool.setSetting, #"{"pane":"Snippets","setting":"Expand keywords as you type","value":"false"}"#)
        _ = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving }
        await pause(250)
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let off = await toggled
        let shown = await waitUntil(timeout: 1.5) { paneSwitch() == 0 } != nil
        // The switch's own animation, before the capture.
        await pause(400)
        await saveScreenshot(of: pane, as: "settings-tool-snippets-pane.png")
        let live = off.status == 0 && !scratch.snippetExpansion && before == 1 && shown
        // An "always allow" right for set_setting and the Always Allow
        // mode change nothing: the card still asks.
        let tools = context.tools.settings
        let mode = tools.mode
        tools.setOverride(.always, for: SettingsTable.Tool.setSetting)
        tools.mode = .always
        guard await focusTestWindow() else {
            tools.setOverride(nil, for: SettingsTable.Tool.setSetting)
            tools.mode = mode
            return
        }
        async let forced = skilliCall(SettingsTable.Tool.setSetting, #"{"pane":"Backup","setting":"How often","value":"Every day"}"#)
        let askedAnyway = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
        await pause(250)
        let hintsAnyway = popover.hintTitles
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let refusedAnyway = await forced
        tools.setOverride(nil, for: SettingsTable.Tool.setSetting)
        tools.mode = mode
        let everyTime = askedAnyway && hintsAnyway == ["Allow", "Deny"] && refusedAnyway.status != 0 && scratch.backupSchedule == .weekly
        _ = await waitUntil(timeout: 1) { !popover.isVisible }
        record(name, asked && card.contains("Backup: How often → Every week") && hints == ["Allow", "Deny"] && kept && set && already && live && everyTime,
               "card: \(asked) “\(card.replacingOccurrences(of: "\n", with: " / "))” \(hints); with Always Allow and an allow right: asked \(askedAnyway) \(hintsAnyway), Esc kept it: \(everyTime); Esc: \(kept) “\(refusal.output.prefix(90))”; Return: \(set) “\(applied.output.prefix(90))”; again: \(already); pane switch \(before.map(String.init) ?? "not read") → \(paneSwitch().map(String.init) ?? "not read"), live: \(live)",
               nil)
    }

    /// The lists' tools, each through the card: a quicklink and its alias,
    /// a snippet, a shortcut added, changed, removed, an app left out, an
    /// alert.
    private func settingListsRoundTrip(_ scratch: Preferences) async {
        let name = "Lists through their tools, each after Return in the card: quicklink + alias, snippet, shortcut add/change/remove, an app left out, an alert, a Catalog entry out of search"
        let popover = context.aiActions.popover
        let shortcuts = context.shortcuts
        let quicklinks = context.tools.settingTools?.quicklinks
        var steps: [String] = []
        var passed = true
        func allow(_ tool: String, _ arguments: String, _ check: @MainActor () -> Bool) async {
            guard !aborted, await focusTestWindow() else {
                passed = false
                return
            }
            async let reply = skilliCall(tool, arguments)
            let asked = await waitUntil(timeout: 3) { popover.isVisible && popover.phase == .approving } != nil
            let card = popover.shownText.components(separatedBy: "\n").dropFirst().first ?? ""
            await pause(200)
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            let result = await reply
            _ = await waitUntil(timeout: 1) { !popover.isVisible }
            let ok = asked && result.status == 0 && check()
            if !ok { passed = false }
            steps.append("\(tool) \(ok ? "✓" : "✗") “\(card)”" + (ok ? "" : " → \(result.output.prefix(120))"))
        }
        let settingsEntry = { shortcuts.config.shortcuts.first { $0.id == "settings" } }
        let keysBefore = settingsEntry()?.keys

        await allow(SettingsTable.Tool.createQuicklink, #"{"name":"Selftest Docs","keyword":"sdq","url":"https://example.com/search?q={query}"}"#) {
            quicklinks?.links.contains { $0.name == "Selftest Docs" && $0.keyword == "sdq" } == true
        }
        await allow(SettingsTable.Tool.setAlias, #"{"alias":"zq","item":"Selftest Docs"}"#) {
            scratch.launcherAliases.contains { $0.alias == "zq" && $0.id.hasPrefix("quicklink:") && $0.title == "Selftest Docs" }
        }
        await allow(SettingsTable.Tool.removeAlias, #"{"alias":"zq"}"#) { !scratch.launcherAliases.contains { $0.alias == "zq" } }
        await allow(SettingsTable.Tool.updateQuicklink, #"{"name":"sdq","keyword":"sdz"}"#) {
            quicklinks?.links.contains { $0.name == "Selftest Docs" && $0.keyword == "sdz" } == true
        }
        await allow(SettingsTable.Tool.deleteQuicklink, #"{"name":"Selftest Docs"}"#) {
            quicklinks?.links.contains { $0.name == "Selftest Docs" } == false
        }
        await allow(SettingsTable.Tool.createSnippet, #"{"name":"Selftest Signature","keyword":";sts","text":"Best, {name}"}"#) {
            self.context.snippets.all.contains { $0.name == "Selftest Signature" && $0.keyword == ";sts" }
        }
        await allow(SettingsTable.Tool.deleteSnippet, #"{"name":";sts"}"#) {
            !self.context.snippets.all.contains { $0.name == "Selftest Signature" }
        }
        await allow(SettingsTable.Tool.addShortcut, #"{"action":"Open Settings","keys":"ctrl+opt+cmd+9"}"#) {
            settingsEntry()?.keys == "ctrl+opt+cmd+9"
        }
        await allow(SettingsTable.Tool.changeShortcut, #"{"keys":"⌃⌥⌘9","new_keys":"ctrl+opt+cmd+8"}"#) {
            settingsEntry()?.keys == "ctrl+opt+cmd+8"
        }
        await allow(SettingsTable.Tool.removeShortcut, #"{"keys":"ctrl+opt+cmd+8"}"#) {
            settingsEntry() != nil && settingsEntry()?.keys == nil
        }
        await allow(SettingsTable.Tool.setSetting, #"{"pane":"Clipboard","setting":"Never keep copies from","change":"add","value":"TextEdit"}"#) {
            scratch.clipboardExcludedApps.contains("com.apple.TextEdit")
        }
        await allow(SettingsTable.Tool.setSetting, #"{"pane":"Clipboard","setting":"Never keep copies from","change":"remove","value":"TextEdit"}"#) {
            !scratch.clipboardExcludedApps.contains("com.apple.TextEdit")
        }
        await allow(SettingsTable.Tool.setSetting, #"{"pane":"Calendar","setting":"Alerts","change":"add","value":"5 min before, screens dark"}"#) {
            scratch.agendaAlerts.contains(MeetingAlert(minutes: 5, style: .dark))
        }
        await allow(SettingsTable.Tool.setSetting, #"{"pane":"Calendar","setting":"Alerts","change":"remove","value":"5 min before"}"#) {
            !scratch.agendaAlerts.contains { $0.minutes == 5 }
        }
        await allow(SettingsTable.Tool.setSetting, #"{"pane":"Catalog","setting":"Show in search","change":"add","value":"Calculator"}"#) {
            scratch.catalogOff.contains("catalog.calculator")
        }
        await allow(SettingsTable.Tool.setSetting, #"{"pane":"Catalog","setting":"Show in search","change":"remove","value":"Calculator"}"#) {
            !scratch.catalogOff.contains("catalog.calculator")
        }
        // Put back what a failure may have left.
        if let entry = settingsEntry(), entry.keys != keysBefore { try? shortcuts.setKeys(keysBefore.flatMap { try? Chord.sequence($0) }, for: entry.id) }
        if let link = quicklinks?.links.first(where: { $0.name == "Selftest Docs" }) { quicklinks?.delete(link.id) }
        if let snippet = context.snippets.all.first(where: { $0.name == "Selftest Signature" }) { context.snippets.delete(snippet.id) }
        record(name, passed && steps.count == 16, steps.joined(separator: " | "), nil)
    }

    /// The skill: a resource and a prompt of skil.li's MCP server, named in
    /// its instructions; the settings tools listed outside a command, not
    /// in a command that does not allow them.
    private func settingsSkillShipsWithTheServer() async {
        let name = "The skill ships with the server: instructions name it, resources/read and prompts/get give it, tools/list has the settings tools"
        let requests: [[String: Any]] = [
            ["jsonrpc": "2.0", "id": 1, "method": "initialize",
             "params": ["protocolVersion": "2025-06-18", "capabilities": [:], "clientInfo": ["name": "selftest", "version": "1"]]],
            ["jsonrpc": "2.0", "id": 2, "method": "resources/list"],
            ["jsonrpc": "2.0", "id": 3, "method": "resources/read", "params": ["uri": SettingsSkill.uri]],
            ["jsonrpc": "2.0", "id": 4, "method": "prompts/list"],
            ["jsonrpc": "2.0", "id": 5, "method": "prompts/get", "params": ["name": SettingsSkill.name, "arguments": ["request": "Add the alias gh for GitHub"]]],
            ["jsonrpc": "2.0", "id": 6, "method": "tools/list"]
        ]
        let lines = await mcpSession(requests.compactMap { try? JSONSerialization.data(withJSONObject: $0) })
        let replies = lines.compactMap { (try? JSONSerialization.jsonObject(with: $0)) as? [String: Any] }
        func result(_ id: Int) -> [String: Any]? {
            replies.first { ($0["id"] as? Int) == id }?["result"] as? [String: Any]
        }
        let initialized = result(1)
        let instructions = (initialized?["instructions"] as? String)?.contains(SettingsSkill.uri) == true
            && (initialized?["capabilities"] as? [String: Any])?["prompts"] != nil
        let listed = ((result(2)?["resources"] as? [[String: Any]])?.first?["uri"] as? String) == SettingsSkill.uri
        let read = ((result(3)?["contents"] as? [[String: Any]])?.first?["text"] as? String) == SettingsSkill.markdown
        let prompt = ((result(4)?["prompts"] as? [[String: Any]])?.first?["name"] as? String) == SettingsSkill.name
        let message = (((result(5)?["messages"] as? [[String: Any]])?.first?["content"] as? [String: Any])?["text"] as? String) ?? ""
        let got = message.hasPrefix(SettingsSkill.markdown) && message.hasSuffix("Add the alias gh for GitHub")
        let tools = Set((result(6)?["tools"] as? [[String: Any]] ?? []).compactMap { $0["name"] as? String })
        let offered = Set(SettingsTable.Tool.all).isSubset(of: tools)
        // A command that allows only the selection: no settings tools.
        let run = AgentContext(title: "Self-test", groups: [.selection], read: nil, targetPID: nil)
        context.tools.register(run)
        defer { context.tools.unregister(run) }
        let inRun = await skilliCall(SettingsTable.Tool.getSettings, run: run.id)
        let hidden = inRun.status != 0 && inRun.output.contains("Unknown tool")
        record(name, instructions && listed && read && prompt && got && offered && hidden,
               "\(replies.count)/6 replies; instructions: \(instructions); resource listed: \(listed), read: \(read); prompt: \(prompt), got: \(got); tools/list: \(offered) (\(tools.count) tools); in a selection-only command: \(hidden)",
               nil)
    }

    /// The values of the switches and checkboxes under `root`, in order.
    private static func axSwitchValues(under root: AXUIElement) -> [Int] {
        var values: [Int] = []
        walkAX(from: root) { element in
            var role: CFTypeRef?
            var subrole: CFTypeRef?
            AXUIElementCopyAttributeValue(element, kAXRoleAttribute as CFString, &role)
            AXUIElementCopyAttributeValue(element, kAXSubroleAttribute as CFString, &subrole)
            if role as? String == kAXCheckBoxRole || role as? String == "AXSwitch" || subrole as? String == "AXSwitch" {
                var value: CFTypeRef?
                AXUIElementCopyAttributeValue(element, kAXValueAttribute as CFString, &value)
                if let number = value as? NSNumber { values.append(number.intValue) }
            }
            return true
        }
        return values
    }

    /// `Skilli mcp` over stdio, as an agent runs it: one line per request,
    /// one per answer; stopped after 10 s whatever happens.
    private func mcpSession(_ requests: [Data]) async -> [Data] {
        guard let executable = Bundle.main.executablePath, let socket = context.tools.socketPath else { return [] }
        return await withCheckedContinuation { continuation in
            DispatchQueue.global().async {
                let process = Process()
                process.executableURL = URL(fileURLWithPath: executable)
                process.arguments = ["mcp", "--socket", socket]
                let input = Pipe()
                let output = Pipe()
                process.standardInput = input
                process.standardOutput = output
                process.standardError = FileHandle.nullDevice
                do {
                    try process.run()
                } catch {
                    continuation.resume(returning: [])
                    return
                }
                DispatchQueue.global().asyncAfter(deadline: .now() + 10) { if process.isRunning { process.terminate() } }
                var lines: [Data] = []
                var buffer = Data()
                for request in requests {
                    input.fileHandleForWriting.write(request + Data("\n".utf8))
                    while true {
                        if let newline = buffer.firstIndex(of: 0x0A) {
                            lines.append(Data(buffer[buffer.startIndex..<newline]))
                            buffer = Data(buffer[buffer.index(after: newline)...])
                            break
                        }
                        let chunk = output.fileHandleForReading.availableData
                        if chunk.isEmpty { break }
                        buffer.append(chunk)
                    }
                }
                try? input.fileHandleForWriting.close()
                if process.isRunning { process.terminate() }
                continuation.resume(returning: lines)
            }
        }
    }

