    /// Search Menu Items over TextEdit, without SI: "m " lists its menus,
    /// read through Accessibility; the first item of Edit › Transformations
    /// (Make Upper Case, in TextEdit's own words, whatever the language)
    /// typed by its name comes first with its place; ↩ chooses it and the
    /// selected text is in capitals. ⌘Z puts it back.
    private func menuSearchChoosesInTextEdit() async {
        let name = "Search Menu Items: TextEdit's menus by their names, ↩ chooses Make Upper Case through Accessibility"
        let original = "menu search check"
        let file = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-menus-\(getpid()).txt")
        try? original.write(to: file, atomically: true, encoding: .utf8)
        defer { try? FileManager.default.removeItem(at: file) }
        let bundleID = "com.apple.TextEdit"
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "TextEdit not installed", nil)
            return
        }
        // The test window shown first, behind TextEdit: the launcher's
        // captures need it under the glass.
        window.center()
        guard await focusTestWindow() else { return }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        let opened = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration)
        guard let pid = opened?.processIdentifier else {
            record(name, false, "TextEdit did not open the file", nil)
            return
        }
        await pause(300)
        Self.makeFrontmost(pid: pid)
        let ready = await waitUntil(timeout: 5) {
            NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID && Self.focusedValue()?.contains(original) == true
        } != nil
        guard ready, ensureFrontmost(bundleID, before: "the menus") else {
            record(name, false, "the document never got focus", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        // The item as TextEdit names it here ("Make Upper Case", "Mettre en majuscules").
        let items = await Task.detached { MenuReader.items(pid: pid) }.value
        guard let upper = items.first(where: { $0.components.count == 3 && $0.components[1] == "Transformations" }),
              let title = upper.components.last else {
            record(name, false, "no Transformations menu in TextEdit (\(items.count) items read)", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }
        await pressKey("a", flags: .maskCommand)
        await pause(150)

        let launcher = context.launcher
        _ = await hyperChord([" "], trigger: Self.ownTriggerKeyCode)
        for character in "m " { await pressKey(character) }
        let mode = await waitUntil(timeout: 1) { launcher.mode == .menus } != nil
        let read = await waitUntil(timeout: 3) { launcher.resultTitles.count > 10 }
        let readCount = launcher.resultTitles.count
        for character in title.lowercased() { await pressKey(character) }
        let first = await waitUntil(timeout: 1) { launcher.selectedResultTitle == title } != nil
        await captureLauncherBothWays(as: "launcher-menus")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let chosen = await waitUntil(timeout: 3) { Self.focusedValue()?.contains(original.uppercased()) == true } != nil
        await closeLauncher()
        // Back as it was: closing asks nothing.
        if ensureFrontmost(bundleID, before: "undo") { await pressKey("z", flags: .maskCommand) }
        await pause(300)
        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)

        record(
            name,
            mode && read != nil && first && chosen,
            "mode: \(mode); \(readCount) items read in \(read.map { "\(Int($0.milliseconds)) ms" } ?? "never"); “\(title.lowercased())” first: \(first); ↩ made it “\(original.uppercased())”: \(chosen); launcher-menus-light/-dark.png",
            read?.milliseconds
        )
    }

