    /// Opens `file` in the app, waits for its text to be focused, runs
    /// ✦K → U, checks the result and ⌘Z, then closes what it opened.
    private func roundTrip(name: String, bundleID: String, file: URL, original: String, selectAll: Bool) async {
        let expected = original.uppercased()
        guard let appURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: bundleID) else {
            record(name, false, "\(bundleID) not installed", nil)
            return
        }
        let wasRunning = !NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).isEmpty
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.activates = true
        let opened = try? await NSWorkspace.shared.open([file], withApplicationAt: appURL, configuration: configuration)
        if let pid = opened?.processIdentifier {
            await pause(300)
            Self.makeFrontmost(pid: pid)
        }

        var ready = await waitUntil(timeout: 5) {
            NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID
                && Self.focusedValue()?.contains(original) == true
        }
        // A browser already running opens the file in a tab with its
        // address bar focused: the page's text area gets the focus through
        // Accessibility, its text selected.
        var selectAll = selectAll
        if ready == nil {
            // The page may still be loading: look for its text area again
            // until it takes the focus.
            ready = await waitUntil(timeout: 4) {
                Self.focusWebTextArea(bundleID: bundleID) && Self.focusedValue()?.contains(original) == true
            }
            selectAll = true
        }
        guard ready != nil else {
            record(name, false, "document never got focus (frontmost: \(NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"), focused value: \(Self.focusedValue() ?? "nil"))", nil)
            await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
            return
        }

        guard ensureFrontmost(bundleID, before: "select all") else { return }
        if selectAll {
            await pressKey("a", flags: .maskCommand)
        }
        await pause(150)
        let sentinel = "skilli-selftest-\(UUID().uuidString)"
        setClipboard(sentinel)

        guard ensureFrontmost(bundleID, before: "✦K → U") else { return }
        let transformsBefore = context.actions.transformCount
        let start = await hyperChord(["k", "u"])
        let matched = await waitUntil(timeout: 3) { Self.focusedValue() == expected }
        let latency = matched.map { _ in ContinuousClock.now - start }
        _ = await waitUntil(timeout: 1.5) { self.context.actions.transformCount > transformsBefore }
        var problems: [String] = []
        if latency == nil {
            problems.append("value is \"\(Self.focusedValue() ?? "nil")\", expected \"\(expected)\"")
        } else {
            await pause(450)
            if NSPasteboard.general.string(forType: .string) != sentinel {
                problems.append("clipboard not restored")
            }
            guard ensureFrontmost(bundleID, before: "⌘Z") else { return }
            await pressKey("z", flags: .maskCommand)
            if await waitUntil(timeout: 2, { Self.focusedValue() == original }) == nil {
                problems.append("⌘Z gave \"\(Self.focusedValue() ?? "nil")\"")
            }
        }
        let source = context.actions.lastTransform?.source.rawValue ?? "?"
        let visible = context.actions.lastTransform.map { String(format: "%.1f", $0.visible.milliseconds) } ?? "?"
        record(
            "\(name): ✦K → U, ⌘Z",
            problems.isEmpty,
            problems.isEmpty ? "ok via \(source), visible \(visible) ms after trigger" : problems.joined(separator: "; "),
            latency?.milliseconds
        )
        await cleanUp(bundleID: bundleID, wasRunning: wasRunning)
    }

    /// Closes our document window; quits the app only if we launched it.
    /// The first text area of the app's front window (a web page's), given
    /// the focus; false when there is none.
    private static func focusWebTextArea(bundleID: String) -> Bool {
        guard let app = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).first else { return false }
        let element = AXUIElementCreateApplication(app.processIdentifier)
        var window: CFTypeRef?
        guard AXUIElementCopyAttributeValue(element, kAXFocusedWindowAttribute as CFString, &window) == .success,
              let window, CFGetTypeID(window) == AXUIElementGetTypeID() else { return false }
        var queue = [window as! AXUIElement]
        var visited = 0
        while !queue.isEmpty, visited < 4_000 {
            let node = queue.removeFirst()
            visited += 1
            var role: CFTypeRef?
            AXUIElementCopyAttributeValue(node, kAXRoleAttribute as CFString, &role)
            if role as? String == "AXTextArea" {
                return AXUIElementSetAttributeValue(node, kAXFocusedAttribute as CFString, kCFBooleanTrue) == .success
            }
            var children: CFTypeRef?
            if AXUIElementCopyAttributeValue(node, kAXChildrenAttribute as CFString, &children) == .success, let list = children as? [AXUIElement] {
                queue += list
            }
        }
        return false
    }

    private func cleanUp(bundleID: String, wasRunning: Bool) async {
        if NSWorkspace.shared.frontmostApplication?.bundleIdentifier == bundleID {
            await pressKey("w", flags: .maskCommand)
            await pause(400)
        }
        if !wasRunning {
            // Gone for real before the next check opens it again: a file
            // opened in an app still quitting is lost with it.
            let apps = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID)
            for app in apps { app.terminate() }
            _ = await waitUntil(timeout: 3) { apps.allSatisfy(\.isTerminated) }
        }
    }

    // MARK: - Meeting recorder (docs/meeting-recorder.md, phase 1)

    /// Every recorder check, on the self-test's own Recordings folder.
    // MARK: - Phase 4: voices, import, editing (docs/meeting-recorder-views.md)

    /// Phase 4's checks: the played-back calls through the recorder's own
    /// transcript, the voices told apart; an import; a line edited, given
    /// to another speaker, deleted and brought back; speakers renamed and
    /// merged; Transcribe Again as picked.
    private func voicesChecks() async {
        let (consent, language) = (context.preferences.recorderConsentShown, context.preferences.voiceLanguage)
        defer {
            context.preferences.recorderConsentShown = consent
            context.preferences.voiceLanguage = language
        }
        context.preferences.recorderConsentShown = true
        context.preferences.voiceLanguage = "en-US"
        let call = await voicesToldApartInTheCalls()
        var imported: URL?
        if !aborted { imported = await importMakesARecording() }
        if !aborted, let imported { await linesEditedAndUndone(imported) }
        if !aborted, let call { await speakersRenamedAndMerged(call) }
        if !aborted, let call { await transcribeAgainAsPicked(call) }
    }

    /// The played-back calls (`script/recorder-measure`), their names
    /// ("en01"…"fr08"); none on this Mac: empty.
    private static var playedBackCalls: [URL] {
        ((try? FileManager.default.contentsOfDirectory(at: recorderCalls, includingPropertiesForKeys: nil)) ?? [])
            .filter { $0.lastPathComponent.range(of: #"^(en|fr)\d\d$"#, options: .regularExpression) != nil }
            .sorted { $0.lastPathComponent < $1.lastPathComponent }
    }

    /// A WAV as the recorder's own tracks are written (AAC in M4A).
    nonisolated private static func m4a(from wav: URL, to url: URL) -> Bool {
        guard let input = try? AVAudioFile(forReading: wav),
              let output = try? AVAudioFile(forWriting: url, settings: [AVFormatIDKey: kAudioFormatMPEG4AAC,
                                                                         AVSampleRateKey: input.processingFormat.sampleRate,
                                                                         AVNumberOfChannelsKey: input.processingFormat.channelCount],
                                            commonFormat: .pcmFormatFloat32, interleaved: false),
              let buffer = AVAudioPCMBuffer(pcmFormat: input.processingFormat, frameCapacity: 65536) else { return false }
        while input.framePosition < input.length {
            guard (try? input.read(into: buffer, frameCount: 65536)) != nil, buffer.frameLength > 0, (try? output.write(from: buffer)) != nil else {
                return false
            }
        }
        return true
    }

    /// Of `lines` on `track` (nil: every line), the words given to the
    /// person speaking at their time, the voices mapped one to one to the
    /// people by the time they share (most first); words where nobody of
    /// that side speaks are left out.
    nonisolated private static func attribution(_ lines: [TranscriptLine], track: Speaker?, turns: [CallTruth.Turn]) -> (right: Int, of: Int) {
        let side = turns.filter { track == nil || $0.me == (track == .me) }
        var heard: [(voice: Voice, people: Set<String>)] = []
        for line in lines where track == nil || line.speaker.track == track {
            for word in line.words where !MeetingTranscript.folded(word.text).isEmpty {
                let people = Set(side.filter { $0.start - 0.25 <= word.time && word.time <= $0.end + 0.25 }.compactMap(\.speaker))
                if !people.isEmpty { heard.append((line.speaker, people)) }
            }
        }
        var shared: [Voice: [String: Int]] = [:]
        for word in heard {
            for person in word.people { shared[word.voice, default: [:]][person, default: 0] += 1 }
        }
        var mapping: [Voice: String] = [:]
        let pairs = shared.flatMap { voice, people in people.map { (voice, $0.key, $0.value) } }.sorted { $0.2 > $1.2 }
        for (voice, person, _) in pairs where mapping[voice] == nil && !mapping.values.contains(person) { mapping[voice] = person }
        return (heard.filter { mapping[$0.voice].map($0.people.contains) ?? false }.count, heard.count)
    }

    /// Every played-back call transcribed by the recorder's own code
    /// (`MeetingTranscriber`, macOS's engine), the other side's voices
    /// told apart by `skil.li Transcriber`; then its one-track mix as an
    /// import. The transcripts and the voices' stretches are written for
    /// `script/recorder-measure`'s scorers (`voices/app-st`, `voices/app-sk`),
    /// to compare with the Measured tables. en01's call is kept for the
    /// checks after.
    private func voicesToldApartInTheCalls() async -> URL? {
        let name = "Recorder phase 4: the played-back calls transcribed as skil.li does, the other side's voices told apart (SpeakerKit, in skil.li Transcriber), and each call's one-track mix as an import"
        let calls = Self.playedBackCalls
        guard !calls.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true,
                                detail: "no played-back calls on this Mac (script/recorder-measure/push.sh puts them in ~/recorder-measure)", latencyMs: nil))
            return nil
        }
        guard TranscriberHelper.executable != nil, TranscriberHelper.speakerModels != nil else {
            record(name, false, "this build has no skil.li Transcriber or no SpeakerKit models", nil)
            return nil
        }
        let recordings = Recordings(root: recorderScratch.appendingPathComponent("voices-recordings", isDirectory: true))
        let out = context.snapshotDirectory?.appendingPathComponent("voices", isDirectory: true)
        var kept: URL?
        var rows: [String] = []
        var errors = (me: 0.0, meWords: 0, them: 0.0, themWords: 0)
        var given = (call: (right: 0, of: 0), mix: (right: 0, of: 0))
        var counts = (callRight: 0, callFewer: 0, mixRight: 0, mixFewer: 0)
        var audio = 0.0, wall = 0.0
        for call in calls {
            guard let data = try? Data(contentsOf: call.appendingPathComponent("truth.json")),
                  let truth = try? JSONDecoder().decode(CallTruth.self, from: data) else { continue }
            let language = truth.language == "fr" ? "fr-FR" : "en-US"
            let user = truth.turns.first(where: \.me)?.speaker
            let others = Set(truth.turns.filter { !$0.me }.compactMap(\.speaker)), everyone = Set(truth.turns.compactMap(\.speaker))
            // As a call: the microphone and the Mac's sound.
            guard let folder = try? recordings.makeFolder(title: call.lastPathComponent, started: .now),
                  let mix = try? recordings.makeFolder(title: call.lastPathComponent + " mix", started: .now) else { continue }
            let converted = await Task.detached {
                Self.m4a(from: call.appendingPathComponent("me.wav"), to: folder.appendingPathComponent(Speaker.me.file))
                    && Self.m4a(from: call.appendingPathComponent("them.wav"), to: folder.appendingPathComponent(Speaker.them.file))
                    && Self.m4a(from: call.appendingPathComponent("mix.wav"), to: mix.appendingPathComponent(Speaker.me.file))
            }.value
            guard converted else {
                rows.append("\(call.lastPathComponent): not converted")
                continue
            }
            var record = MeetingRecord(title: call.lastPathComponent, started: .now, language: language, recorder: nil)
            record.attendees = (truth.attendees ?? []).filter { $0 != user }
            record.seconds = truth.seconds ?? 0
            record.state = .transcribing
            var single = record
            single.unused = [.them]
            single.imported = "mix.wav"
            single.speakers = [Voice.me.rawValue: RecordingImport.laneName]
            let start = ContinuousClock.now
            guard let done = try? await MeetingTranscriber.transcribe(folder, record: record, step: { _ in }),
                  let oneTrack = try? await MeetingTranscriber.transcribe(mix, record: single, step: { _ in }),
                  let transcript = recordings.transcript(folder), let mixed = recordings.transcript(mix) else {
                rows.append("\(call.lastPathComponent): no transcript")
                continue
            }
            wall += (ContinuousClock.now - start).milliseconds / 1000
            audio += 2 * (truth.seconds ?? 0)
            try? recordings.write(done, to: folder)
            try? recordings.write(oneTrack, to: mix)
            if call.lastPathComponent == "en01" { kept = folder }
            // Each side against the script.
            let mine = Self.errorsPerHundred(truth.turns.filter(\.me).map(\.text).joined(separator: " "),
                                             transcript.lines.filter { $0.speaker.track == .me }.map(\.text).joined(separator: " "))
            let theirs = Self.errorsPerHundred(truth.turns.filter { !$0.me }.map(\.text).joined(separator: " "),
                                               transcript.lines.filter { $0.speaker.track == .them }.map(\.text).joined(separator: " "))
            errors.me += mine.errors * Double(mine.words) / 100
            errors.meWords += mine.words
            errors.them += theirs.errors * Double(theirs.words) / 100
            errors.themWords += theirs.words
            // The voices against the people.
            let callVoices = Set(transcript.lines.filter { $0.speaker.track == .them }.map(\.speaker))
            let mixVoices = Set(mixed.lines.map(\.speaker))
            let callGiven = Self.attribution(transcript.lines, track: .them, turns: truth.turns)
            let mixGiven = Self.attribution(mixed.lines, track: nil, turns: truth.turns)
            given.call.right += callGiven.right
            given.call.of += callGiven.of
            given.mix.right += mixGiven.right
            given.mix.of += mixGiven.of
            counts.callRight += callVoices.count == others.count ? 1 : 0
            counts.callFewer += callVoices.count < others.count ? 1 : 0
            counts.mixRight += mixVoices.count == everyone.count ? 1 : 0
            counts.mixFewer += mixVoices.count < everyone.count ? 1 : 0
            rows.append(String(format: "%@ them %d/%d voices %.0f %%, mix %d/%d %.0f %%", call.lastPathComponent, callVoices.count, others.count,
                               100 * Double(callGiven.right) / Double(max(1, callGiven.of)), mixVoices.count, everyone.count,
                               100 * Double(mixGiven.right) / Double(max(1, mixGiven.of))))
            // For the scorers: the text of each side; each track's stretches.
            if let out {
                for (track, lines) in [("me", transcript.lines.filter { $0.speaker.track == .me }), ("them", transcript.lines.filter { $0.speaker.track == .them })] {
                    let file = out.appendingPathComponent("app-st/\(call.lastPathComponent)/\(track).json")
                    try? FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
                    try? JSONSerialization.data(withJSONObject: ["text": lines.map(\.text).joined(separator: " ")]).write(to: file)
                }
                for (track, url) in [("them", folder.appendingPathComponent(Speaker.them.file)), ("mix", mix.appendingPathComponent(Speaker.me.file))] {
                    let began = ContinuousClock.now
                    let stretches = (try? await TranscriberHelper.voices(of: url) { _ in }) ?? nil
                    let seconds = (ContinuousClock.now - began).milliseconds / 1000
                    let file = out.appendingPathComponent("app-sk/\(call.lastPathComponent)/\(track).json")
                    try? FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
                    let segments = (stretches ?? []).map { ["speaker": "S\($0.voice)", "start": $0.start, "end": $0.end] as [String: Any] }
                    try? JSONSerialization.data(withJSONObject: ["segments": segments, "audioSeconds": truth.seconds ?? 0, "wallSeconds": seconds,
                                                                 "maxRSSMB": 0] as [String: Any]).write(to: file)
                }
            }
        }
        let callShare = 100 * Double(given.call.right) / Double(max(1, given.call.of))
        let mixShare = 100 * Double(given.mix.right) / Double(max(1, given.mix.of))
        let me = 100 * errors.me / Double(max(1, errors.meWords)), them = 100 * errors.them / Double(max(1, errors.themWords))
        // Measured (SpeakerKit): never fewer voices than people on the Mac's
        // sound; the words given to the right person, most of them.
        let passed = rows.count == calls.count && kept != nil && counts.callFewer == 0 && callShare >= 85 && mixShare >= 75 && me <= 30 && them <= 25
        record(name, passed,
               String(format: "%d calls (%.0f min of tracks in %.0f s, ×%.0f real time); errors per hundred words me %.1f (%d words), them %.1f (%d words), numbers left out; the other side's words given to the right person %.1f %%, voices found right in %d calls, fewer in %d; one-track mix %.1f %%, right in %d, fewer in %d; %@",
                      rows.count, audio / 60, wall, audio / max(1, wall), me, errors.meWords, them, errors.themWords, callShare, counts.callRight,
                      counts.callFewer, mixShare, counts.mixRight, counts.mixFewer, rows.joined(separator: "; ")),
               nil)
        return kept
    }

    /// `import_recording` with a played-back call's one-track mix: its
    /// window at once, a recording named after the file, the sound one
    /// lane ("Sound"), its voices Speaker 1, 2…, the file untouched; a
    /// video with no sound said, nothing made. Its folder, for the
    /// editing checks.
    private func importMakesARecording() async -> URL? {
        let name = "Recorder phase 4: Import (import_recording): a one-track recording named after the file, its window at once, voices told apart (Speaker 1, 2…), the file untouched; a video with no sound is said, nothing made"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return nil
        }
        let call = Self.recorderCalls.appendingPathComponent("en03")
        guard let data = try? Data(contentsOf: call.appendingPathComponent("truth.json")), let truth = try? JSONDecoder().decode(CallTruth.self, from: data)
        else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no played-back calls on this Mac", latencyMs: nil))
            return nil
        }
        let file = recorderScratch.appendingPathComponent("Board call.wav")
        try? FileManager.default.removeItem(at: file)
        guard (try? FileManager.default.copyItem(at: call.appendingPathComponent("mix.wav"), to: file)) != nil else {
            record(name, false, "the file could not be made", nil)
            return nil
        }
        let before = try? file.resourceValues(forKeys: [.fileSizeKey, .contentModificationDateKey])
        let settings = context.tools.settings
        let mode = settings.mode
        settings.mode = .always
        defer { settings.mode = mode }
        let started = Task { await self.skilliCall("import_recording", "{\"path\":\"\(file.path)\"}") }
        let atOnce = await waitUntil(timeout: 10) { center.openWindows.contains { $0.record.imported == "Board call.wav" } } != nil
        let (status, said) = await started.value
        let made = await waitUntil(timeout: 180) {
            center.openWindows.contains { $0.record.imported == "Board call.wav" && !$0.shownLines.isEmpty }
        } != nil
        guard atOnce, made, let controller = center.openWindows.first(where: { $0.record.imported == "Board call.wav" }),
              let record = center.recordings.read(controller.folder) else {
            self.record(name, false, "window at once \(atOnce), transcript \(made); the tool said (\(status)) “\(said)”", nil)
            return nil
        }
        let voices = MeetingVoices.order(of: controller.shownLines)
        let names = voices.map { MeetingVoices.name(of: $0, in: controller.shownNames) }
        let people = Set(truth.turns.compactMap(\.speaker))
        let given = Self.attribution(controller.shownLines, track: nil, turns: truth.turns)
        let after = try? file.resourceValues(forKeys: [.fileSizeKey, .contentModificationDateKey])
        await captureRecordingWindow(controller, as: "recorder-import")
        controller.showDropRing(true)
        await captureRecordingWindow(controller, as: "recorder-window-drop")
        controller.showDropRing(false)
        // A video with no sound: said, nothing made.
        let silent = recorderScratch.appendingPathComponent("No sound.mov")
        let wrote = await Self.writeSilentVideo(silent)
        let folders = (try? FileManager.default.contentsOfDirectory(atPath: center.recordings.root.path))?.count ?? 0
        let (refusedStatus, refused) = await skilliCall("import_recording", "{\"path\":\"\(silent.path)\"}")
        let foldersAfter = (try? FileManager.default.contentsOfDirectory(atPath: center.recordings.root.path))?.count ?? 0
        let passed = status == 0 && said.contains("Imported") && record.imported == "Board call.wav" && record.unused == [.them] && record.state == .done
            && record.title == "Board call" && controller.shownAbout.hasPrefix("Imported from Board call.wav") && controller.shownLanes == ["Sound"]
            && voices.allSatisfy { $0.rawValue.hasPrefix("s") } && voices.count >= 2 && names.first == "Speaker 1"
            && Double(given.right) >= 0.75 * Double(given.of) && before?.fileSize == after?.fileSize
            && before?.contentModificationDate == after?.contentModificationDate
            && wrote && refusedStatus != 0 && refused.contains("has no sound to transcribe") && folders == foldersAfter
        self.record(name, passed,
                    String(format: "the tool said (%d) “%@”; “%@”, %@, lanes %@, %d voices for %d people (%@), %.0f %% of words to the right person; the file untouched %@; a video with no sound (%d) “%@”, folders %d → %d",
                           status, said, record.title, controller.shownAbout, controller.shownLanes.joined(separator: ", "), voices.count, people.count,
                           names.joined(separator: ", "), 100 * Double(given.right) / Double(max(1, given.of)),
                           "\(before?.fileSize == after?.fileSize && before?.contentModificationDate == after?.contentModificationDate)",
                           refusedStatus, refused, folders, foldersAfter),
                    nil)
        return controller.folder
    }

    /// A one-second black video with no sound track.
    nonisolated private static func writeSilentVideo(_ url: URL) async -> Bool {
        try? FileManager.default.removeItem(at: url)
        guard let writer = try? AVAssetWriter(outputURL: url, fileType: .mov) else { return false }
        let input = AVAssetWriterInput(mediaType: .video, outputSettings: [AVVideoCodecKey: AVVideoCodecType.h264, AVVideoWidthKey: 64,
                                                                           AVVideoHeightKey: 64])
        let adaptor = AVAssetWriterInputPixelBufferAdaptor(assetWriterInput: input, sourcePixelBufferAttributes: nil)
        writer.add(input)
        guard writer.startWriting() else { return false }
        writer.startSession(atSourceTime: .zero)
        for frame in 0..<10 {
            var buffer: CVPixelBuffer?
            CVPixelBufferCreate(nil, 64, 64, kCVPixelFormatType_32BGRA, nil, &buffer)
            guard let buffer else { return false }
            while !input.isReadyForMoreMediaData { try? await Task.sleep(for: .milliseconds(5)) }
            adaptor.append(buffer, withPresentationTime: CMTime(value: CMTimeValue(frame), timescale: 10))
        }
        input.markAsFinished()
        await writer.finishWriting()
        return writer.status == .completed
    }

    /// The window has the keyboard before keys are pressed into it; else
    /// every later check is skipped (no key may land in another app).
    private func recordingWindowHasKeys(_ controller: RecordingWindowController, _ name: String) async -> Bool {
        controller.present()
        if await waitUntil(timeout: 2, { controller.nsWindow.isKeyWindow && NSApp.isActive }) != nil { return true }
        aborted = true
        let front = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"
        record(name, false, "the recording's window did not take the keyboard (front: \(front)): stopped so no key lands elsewhere", nil)
        return false
    }

    /// A real click at the middle of `frame` (AppKit's coordinates).
    private func click(_ frame: NSRect) async {
        let screenHeight = NSScreen.screens.first?.frame.maxY ?? 0
        let point = CGPoint(x: frame.midX, y: screenHeight - frame.midY)
        let source = CGEventSource(stateID: .hidSystemState)
        for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(60)
        }
    }

    /// In the import's window, with keys: a click selects a line (and
    /// plays it), ↓ the next, ↩ edits it in place (typed, ↩ kept, written),
    /// ⇥ gives it to the next speaker and ⇧⇥ back, ⌘⌫ deletes it with the
    /// undo card whose ⌘Z brings it back, ⌘Z in the window undoes the rest
    /// and ⇧⌘Z does it again, esc lets go.
    private func linesEditedAndUndone(_ folder: URL) async {
        let name = "Recorder phase 4: a line selected in its window: ↩ edits it in place, ⇥ ⇧⇥ change its speaker, ⌘⌫ deletes it (the undo card's ⌘Z brings it back), ⌘Z and ⇧⌘Z undo and redo, each change written at once"
        guard let center = context.recorder(), let controller = center.window(for: folder), controller.shownLines.count > 4 else {
            record(name, false, "no import's window with lines", nil)
            return
        }
        // A card left by the import's tool calls is not under the click.
        let popover = context.aiActions.popover
        if popover.isVisible {
            await pressKey(nil, code: CGKeyCode(kVK_Escape))
            _ = await waitUntil(timeout: 8) { !popover.isVisible }
        }
        guard await recordingWindowHasKeys(controller, name) else { return }
        guard let frame = controller.screenFrame(ofLine: 1) else {
            record(name, false, "line 2 not on screen", nil)
            return
        }
        let cardBefore = popover.isVisible ? "a card “\(popover.shownTitle)” in front" : "no card"
        await click(frame)
        let clicked = await waitUntil(timeout: 2) { controller.selectedLine == 1 } != nil
        let clickDetail = clicked ? "" : " (\(cardBefore); key window “\(NSApp.keyWindow?.title ?? "none")”, the line at \(Int(frame.midX)),\(Int(frame.midY)))"
        if controller.playing { await pressKey(nil, code: CGKeyCode(kVK_Space)) }
        await pressKey(nil, code: CGKeyCode(kVK_DownArrow))
        let moved = await waitUntil(timeout: 1) { controller.selectedLine == 2 } != nil
        let hints = controller.shownHints
        await captureRecordingWindow(controller, as: "recorder-line-selected")
        let original = controller.shownLines[2]
        let count = controller.shownLines.count
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let editing = await waitUntil(timeout: 1) { controller.isEditingLine } != nil
        await pressKey("a", flags: .maskCommand)
        for character in "We meet at noon" { _ = await typeCharacter(character) }
        await captureRecordingWindow(controller, as: "recorder-line-editing")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let edited = await waitUntil(timeout: 2) { !controller.isEditingLine && controller.shownLines[2].text == "We meet at noon" } != nil
        let written = center.recordings.transcript(folder)?.lines[2].text == "We meet at noon" && center.recordings.read(folder)?.edited == true
        let order = MeetingVoices.order(of: controller.shownLines)
        let next = MeetingVoices.next(after: original.speaker, in: order)
        await pressKey(nil, code: CGKeyCode(kVK_Tab))
        let given = await waitUntil(timeout: 1) { controller.shownLines[2].speaker == next } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Tab), flags: .maskShift)
        let back = await waitUntil(timeout: 1) { controller.shownLines[2].speaker == original.speaker } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Delete), flags: .maskCommand)
        let deleted = await waitUntil(timeout: 2) { controller.shownLines.count == count - 1 && popover.isVisible } != nil
        let card = "“\(popover.shownTitle)”: \(popover.shownText.prefix(80))"
        await pressKey("z", flags: .maskCommand)
        let cameBack = await waitUntil(timeout: 2) { controller.shownLines.count == count && !popover.isVisible } != nil
        let backInPlace = cameBack && controller.shownLines[2].text == "We meet at noon"
        // The rest, from the window: ⇧⇥, ⇥, the edit.
        for _ in 0..<3 { await pressKey("z", flags: .maskCommand) }
        let undone = await waitUntil(timeout: 2) { controller.shownLines[2].text == original.text && controller.shownLines[2].speaker == original.speaker } != nil
        await pressKey("z", flags: [.maskCommand, .maskShift])
        let redone = await waitUntil(timeout: 2) { controller.shownLines[2].text == "We meet at noon" } != nil
        let writtenAgain = center.recordings.transcript(folder)?.lines.map(\.text) == controller.shownLines.map(\.text)
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let letGo = await waitUntil(timeout: 1) { controller.selectedLine == nil } != nil
        let passed = clicked && moved && hints.first == "Edit" && editing && edited && written && given && back && deleted
            && popover.shownTitle == "Line Deleted" && backInPlace && undone && redone && writtenAgain && letGo
        record(name, passed,
               "clicked \(clicked)\(clickDetail), ↓ \(moved), hints \(hints.joined(separator: " · ")); ↩ edits \(editing), kept \(edited), written \(written); ⇥ to \(next.rawValue) \(given), ⇧⇥ back \(back); ⌘⌫ \(deleted) (card \(card)), its ⌘Z \(backInPlace); ⌘Z ×3 \(undone), ⇧⌘Z \(redone), on disk \(writtenAgain); esc \(letGo)",
               nil)
    }

    /// In en01's window (its attendees, Me and the other side's voices):
    /// a click on a speaker's name opens the menu of names (the attendees
    /// first); one picked renames that speaker everywhere; the same name
    /// given to another voice merges them; Other Name… typed in place;
    /// the user's own name joins Me; ⌘Z undoes the merges.
    private func speakersRenamedAndMerged(_ folder: URL) async {
        let name = "Recorder phase 4: speakers renamed from the menu under a name (the attendees first), two given the same name become one, Other Name… typed in place, the user's own name joins Me, ⌘Z undoes"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return
        }
        center.open(folder)
        guard let controller = center.window(for: folder) else {
            record(name, false, "en01's window did not open", nil)
            return
        }
        let them = MeetingVoices.order(of: controller.shownLines).filter { $0.track == .them }
        guard them.count >= 2, let first = controller.shownLines.firstIndex(where: { $0.speaker == them[0] }),
              let second = controller.shownLines.firstIndex(where: { $0.speaker == them[1] }) else {
            record(name, false, "fewer than two voices on the other side: \(them.map(\.rawValue))", nil)
            return
        }
        guard await recordingWindowHasKeys(controller, name) else { return }
        controller.standInOwnName("Camille Rocher")
        // A click on the first voice's name: its menu, captured light and dark.
        var items: [String] = []
        for (suffix, appearance) in GlassCheck.appearances {
            controller.nsWindow.appearance = appearance
            await pause(300)
            guard let frame = controller.screenFrame(ofSpeakerIn: first) else { continue }
            let guardTimer = escapeLater(10)
            await click(frame)
            await pause(600)
            if let menu = controller.renameMenu {
                items = menu.items.filter { !$0.isSeparatorItem }.map(\.title)
                if let directory = context.snapshotDirectory, let image = await WindowCapture.openMenuImage(),
                   let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                    try? png.write(to: directory.appendingPathComponent("recorder-rename-menu-\(suffix).png"))
                }
                menu.cancelTracking()
            }
            guardTimer.cancel()
            await pause(300)
        }
        controller.nsWindow.appearance = nil
        let attendees = Array(items.dropFirst().prefix(3))
        // Picked: the first attendee for the first voice, then the same name for the second.
        let picked = await pickName(controller, line: first, item: attendees.first ?? "")
        let renamed = controller.shownNames[them[0].rawValue] == attendees.first
        let secondCount = controller.shownLines.filter { $0.speaker == them[1] }.count
        let firstCount = controller.shownLines.filter { $0.speaker == them[0] }.count
        let merged = await pickName(controller, line: second, item: "\(attendees.first ?? "") — joins \(attendees.first ?? "")’s lines")
        let mergedRight = controller.shownLines.filter { $0.speaker == them[0] }.count == firstCount + secondCount
            && !controller.shownLines.contains { $0.speaker == them[1] } && controller.shownNames[them[1].rawValue] == nil
        await captureRecordingWindow(controller, as: "recorder-window-voices")
        // Other Name… on a third voice (else on the merged one): typed, ↩.
        let third = them.count > 2 ? controller.shownLines.firstIndex { $0.speaker == them[2] } ?? first : first
        let typedVoice = controller.shownLines[third].speaker
        let other = await pickName(controller, line: third, item: "Other Name…")
        let fieldShown = await waitUntil(timeout: 1) { controller.isRenaming } != nil
        await captureRecordingWindow(controller, as: "recorder-rename-field")
        await pressKey("a", flags: .maskCommand)
        for character in "Bartholomew" { _ = await typeCharacter(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let typed = await waitUntil(timeout: 2) { controller.shownNames[typedVoice.rawValue] == "Bartholomew" } != nil
        // The user's own name: that voice's lines join Me, Me's name kept.
        let meBefore = controller.shownLines.filter { $0.speaker == .me }.count
        let typedCount = controller.shownLines.filter { $0.speaker == typedVoice }.count
        _ = await pickName(controller, line: controller.shownLines.firstIndex { $0.speaker == typedVoice } ?? third, item: "Other Name…")
        _ = await waitUntil(timeout: 1) { controller.isRenaming }
        await pressKey("a", flags: .maskCommand)
        for character in "Camille Rocher" { _ = await typeCharacter(character) }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let joinedMe = await waitUntil(timeout: 2) { controller.shownLines.filter { $0.speaker == .me }.count == meBefore + typedCount } != nil
        let meKept = MeetingVoices.name(of: .me, in: controller.shownNames) == "Me"
        // ⌘Z: Me's lines back to that voice, then the merge undone.
        await pressKey("z", flags: .maskCommand)
        let unjoined = await waitUntil(timeout: 2) { controller.shownLines.filter { $0.speaker == .me }.count == meBefore } != nil
        await pressKey("z", flags: .maskCommand)
        await pressKey("z", flags: .maskCommand)
        let unmerged = await waitUntil(timeout: 2) { controller.shownLines.filter { $0.speaker == them[1] }.count == secondCount } != nil
        let saved = center.recordings.read(folder)?.speakers[them[0].rawValue] == attendees.first
        let passed = items.first?.hasPrefix("Rename “") == true && attendees.count == 3 && !attendees.contains("Camille Rocher")
            && items.contains("Me — joins your lines") && items.last == "Other Name…" && picked && renamed && merged && mergedRight && other
            && fieldShown && typed && joinedMe && meKept && unjoined && unmerged && saved
        record(name, passed,
               "menu \(items.joined(separator: " | ")); renamed \(renamed), merged \(mergedRight) (\(firstCount)+\(secondCount) lines); Other Name… field \(fieldShown), typed \(typed); own name joins Me \(joinedMe), Me kept \(meKept); ⌘Z unjoins \(unjoined), unmerges \(unmerged); written \(saved)",
               nil)
    }

    /// Esc posted `seconds` from now unless cancelled: a menu left open
    /// never holds the run.
    private func escapeLater(_ seconds: Double) -> DispatchWorkItem {
        let work = DispatchWorkItem {
            let source = CGEventSource(stateID: .hidSystemState)
            for down in [true, false] {
                CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
            }
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + seconds, execute: work)
        return work
    }

    /// The line selected, ⌥↩ opens its speaker's menu, `item` chosen in
    /// it (as a click on it does). False when the menu or the item was not
    /// there.
    private func pickName(_ controller: RecordingWindowController, line: Int, item: String) async -> Bool {
        guard let frame = controller.screenFrame(ofLine: line) else { return false }
        await click(frame)
        if controller.playing { await pressKey(nil, code: CGKeyCode(kVK_Space)) }
        let guardTimer = escapeLater(10)
        defer { guardTimer.cancel() }
        await pressKey(nil, code: CGKeyCode(kVK_Return), flags: .maskAlternate)
        guard await waitUntil(timeout: 2, { controller.renameMenu != nil }) != nil,
              let menu = controller.renameMenu, let index = menu.items.firstIndex(where: { $0.title == item }) else {
            controller.renameMenu?.cancelTracking()
            return false
        }
        await pause(200)
        menu.cancelTracking()
        menu.performActionForItem(at: index)
        await pause(200)
        return true
    }

    /// Transcribe Again on en01, edited: its panel (the languages, the
    /// engine, the changes said replaced), French picked: made in French
    /// with macOS's engine, the names given kept; then English again.
    private func transcribeAgainAsPicked(_ folder: URL) async {
        let name = "Recorder phase 4: Transcribe Again in the language and engine picked (its panel says the changes are replaced), the names given kept"
        guard let center = context.recorder(), let controller = center.window(for: folder) else {
            record(name, false, "no window", nil)
            return
        }
        guard await recordingWindowHasKeys(controller, name) else { return }
        let names = center.recordings.read(folder)?.speakers ?? [:]
        controller.showTranscribeAgain()
        guard let panel = controller.againPanel, await waitUntil(timeout: 5, { panel.isShown && panel.isLoaded }) != nil else {
            record(name, false, "no panel", nil)
            return
        }
        let languages = panel.shownLanguages, engines = panel.shownEngines, note = panel.shownNote
        if let directory = context.snapshotDirectory, let window = panel.window {
            for (suffix, appearance) in GlassCheck.appearances {
                window.appearance = appearance
                controller.nsWindow.appearance = appearance
                await pause(400)
                if let png = await WindowCapture.png(of: window) { try? png.write(to: directory.appendingPathComponent("recorder-transcribe-again-\(suffix).png")) }
            }
            window.appearance = nil
            controller.nsWindow.appearance = nil
        }
        await panel.pick(language: "fr-FR", engine: .macOS)
        panel.press()
        let showsProgress = await waitUntil(timeout: 10) { controller.shownState.hasPrefix("Transcribing") } != nil
        let madeAgain = await waitUntil(timeout: 120) { center.recordings.transcript(folder)?.language == "fr-FR" && !controller.shownLines.isEmpty } != nil
        let record = center.recordings.read(folder)
        let kept = names.filter { !MeetingVoices.isStandard($0.value) }.allSatisfy { id, given in record?.speakers[id] == nil || record?.speakers[id] == given }
        // English again, for the window's last captures.
        controller.showTranscribeAgain()
        if let back = controller.againPanel, await waitUntil(timeout: 5, { back.isLoaded }) != nil {
            await back.pick(language: "en-US", engine: .macOS)
            back.press()
            _ = await waitUntil(timeout: 120) { center.recordings.transcript(folder)?.language == "en-US" && !controller.shownLines.isEmpty }
        }
        await captureRecordingWindow(controller, as: "recorder-window-again")
        controller.close()
        let passed = languages.contains { $0.hasPrefix("English") } && languages.contains { $0.hasPrefix("French") } && engines == ["macOS"]
            && note == "Your changes to the lines are replaced." && showsProgress && madeAgain && record?.language == "fr-FR"
            && record?.engine == TranscriptEngine.macOS.rawValue && record?.edited == nil && kept
        self.record(name, passed,
                    "\(languages.count) languages, engines \(engines), note “\(note)”; progress shown \(showsProgress), made again in \(record?.language ?? "?") with \(record?.engine ?? "?") \(madeAgain), edited \(record?.edited.map(String.init) ?? "nil"), names given kept \(kept) (\(record?.speakers ?? [:]))",
                    nil)
    }

    // MARK: - Phase 4: Better transcription (docs/meeting-recorder-views.md)

    /// Better transcription's checks: the download (a stand-in server
    /// serving the measurement's own model), whisper on the played-back
    /// calls through the recorder's own transcript, the echo drop with its
    /// times on the recording's clock, the engine offered and removed.
    private func whisperChecks() async {
        let (language, hint) = (context.preferences.voiceLanguage, context.preferences.recorderBetterHintShown)
        defer {
            context.preferences.voiceLanguage = language
            context.preferences.recorderBetterHintShown = hint
        }
        context.preferences.voiceLanguage = "en-US"
        guard await betterTranscriptionDownloads() else { return }
        var them: [String: [TranscriptWord]] = [:]
        var kept: URL?
        if !aborted { (them, kept) = await whisperOnTheCalls() }
        if !aborted, !them.isEmpty { await echoDropWithWhisper(them) }
        if !aborted, let kept { await whisperOfferedAndRemoved(kept) }
    }

    /// The measurement's own files (`script/recorder-measure/setup.sh`),
    /// the same as the download's.
    private static var measuredModels: URL {
        FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("recorder-measure/models", isDirectory: true)
    }

    /// A recording made by macOS's engine, for the window's line: two
    /// silent tracks, a transcript of two lines.
    private func recordingMadeByMacOS(_ recordings: Recordings, title: String) -> URL? {
        guard let folder = try? recordings.makeFolder(title: title, started: .now) else { return nil }
        let silence = recorderScratch.appendingPathComponent("silence-2s.wav")
        guard Self.clip(nil, seconds: 2, beeps: [], to: silence),
              Self.m4a(from: silence, to: folder.appendingPathComponent(Speaker.me.file)),
              Self.m4a(from: silence, to: folder.appendingPathComponent(Speaker.them.file)) else { return nil }
        var record = MeetingRecord(title: title, started: .now, language: "en-US", recorder: nil)
        record.state = .done
        record.engine = TranscriptEngine.macOS.rawValue
        record.seconds = 2
        let lines = [TranscriptLine(speaker: .me, words: [TranscriptWord("Hello", start: 0.1, end: 0.4)]),
                     TranscriptLine(speaker: .them, words: [TranscriptWord("Hi", start: 0.6, end: 0.9)])]
        guard (try? recordings.write(record, to: folder)) != nil,
              (try? MeetingTranscript.File(language: "en-US", engine: record.engine!, lines: lines).encoded()
                .write(to: folder.appendingPathComponent("transcript.json"))) != nil else { return nil }
        return folder
    }

    /// The download from a stand-in server serving the measurement's own
    /// model (its real bytes, checked by the real SHA-256): before it, the
    /// first window on a transcript macOS made says it once, the next one
    /// not; a wrong file is thrown away; the row in Settings → Recorder as
    /// it downloads (captured), Cancel at a third and Download again goes
    /// on from there (a range asked), checked, downloaded.
    private func betterTranscriptionDownloads() async -> Bool {
        let name = "Recorder phase 4: Better transcription: taught once in a window, downloaded from a stand-in server (the real model, its SHA-256 checked), cancelled and resumed from where it stopped, a wrong file thrown away, its row in Settings → Recorder"
        let models = Self.measuredModels
        let files = BetterTranscription.files.map { (file: $0, source: models.appendingPathComponent($0.name)) }
        guard files.allSatisfy({ FileManager.default.fileExists(atPath: $0.source.path) }) else {
            checks.append(Check(name: name, passed: true, skipped: true,
                                detail: "no measured model on this Mac (script/recorder-measure/push.sh puts it in ~/recorder-measure/models)", latencyMs: nil))
            return false
        }
        guard let center = context.recorder(), let folder = BetterTranscription.testFolder else {
            record(name, false, "no recorder, or no self-test folder for the models", nil)
            return false
        }
        // Taught once: the first window on a transcript macOS made, not the next.
        context.preferences.recorderBetterHintShown = false
        var hints: [String?] = []
        for title in ["Taught once", "Quiet after"] {
            guard let made = recordingMadeByMacOS(center.recordings, title: title) else { continue }
            center.open(made)
            await pause(600)
            let window = center.window(for: made)
            hints.append(window?.shownHint)
            if title == "Taught once", let window { await captureRecordingWindow(window, as: "recorder-window-better-hint") }
            window?.close()
        }
        // The stand-in server: the files by name; a wrong file's checksum.
        guard let server = ModelStandIn(files: Dictionary(uniqueKeysWithValues: files.map { ($0.file.name, $0.source) })),
              await waitUntil(timeout: 3, { server.port != nil }) != nil, let port = server.port else {
            record(name, false, "the stand-in server did not start", nil)
            return false
        }
        defer { server.stop() }
        let base = "http://127.0.0.1:\(port)/"
        BetterTranscription.testFiles = files.map {
            BetterTranscription.File(name: $0.file.name, url: URL(string: base + $0.file.name)!, size: $0.file.size, sha256: $0.file.sha256)
        }
        let wrongFolder = recorderScratch.appendingPathComponent("wrong-models", isDirectory: true)
        let wrong = BetterTranscription(folder: wrongFolder, files: [BetterTranscription.File(name: files[0].file.name, url: URL(string: base + files[0].file.name)!,
                                                                                             size: files[0].file.size, sha256: String(repeating: "0", count: 64))])
        wrong.download()
        let refused = await waitUntil(timeout: 30) { wrong.state == .wrongFile } != nil
        let nothingKept = ((try? FileManager.default.contentsOfDirectory(atPath: wrongFolder.path)) ?? []).filter { !$0.hasPrefix(".") }.isEmpty
        // The app's own download, its row shown.
        guard let store = context.betterTranscription() else {
            record(name, false, "no Better transcription store", nil)
            return false
        }
        store.refresh()
        context.settings.show(pane: .recorder)
        await pause(800)
        let notDownloaded = store.state == .notDownloaded
        await captureSettingsBothWays(as: "settings-recorder-better")
        server.bytesPerSecond = 200_000_000
        store.download()
        let third = await waitUntil(timeout: 60) {
            if case .downloading(let received, let total, _) = store.state { return received > total / 3 }
            return false
        } != nil
        let downloadingLine = store.line
        await captureSettingsBothWays(as: "settings-recorder-downloading")
        store.cancel()
        let cancelled = await waitUntil(timeout: 15) { store.state == .notDownloaded } != nil
        let resumeKept = ((try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []).contains { $0.hasSuffix(".resume") }
        server.bytesPerSecond = nil
        var sawChecking = false
        store.download()
        let done = await waitUntil(timeout: 240) {
            if store.state == .checking { sawChecking = true }
            return store.state == .downloaded
        } != nil
        let ranged = server.ranges.contains { $0 > 0 }
        await pause(500)
        await captureSettingsBothWays(as: "settings-recorder-downloaded")
        context.settings.close()
        let ready = BetterTranscription.isReady()
        let passed = hints.count == 2 && hints[0]?.contains("Better transcription") == true && hints[1] == nil && refused && nothingKept
            && notDownloaded && third && cancelled && resumeKept && done && sawChecking && ranged && ready
        record(name, passed,
               "window lines \(hints.map { $0 ?? "none" }); a wrong file refused \(refused), nothing kept \(nothingKept); row not downloaded \(notDownloaded); a third downloaded \(third) (“\(downloadingLine)”), cancelled \(cancelled), what came kept \(resumeKept); downloaded again \(done) from where it stopped \(ranged) (ranges asked \(server.ranges)), checked \(sawChecking); ready \(ready)",
               nil)
        return ready
    }

    /// whisper (Better transcription, the default once downloaded) on
    /// every played-back call through the recorder's own transcript: the
    /// names in its prompt (the attendees, then the user's and the
    /// contacts' as Dictate orders them), its VAD, its two failures taken
    /// out, the voices told apart. Written for the kit's scorers
    /// (`voices/app-w`). The other side's words, for the echo check.
    private func whisperOnTheCalls() async -> ([String: [TranscriptWord]], URL?) {
        let name = "Recorder phase 4: whisper (the default once downloaded) on the played-back calls as skil.li runs it: the names in its prompt, its VAD, its two failures taken out, the voices told apart"
        let calls = Self.playedBackCalls
        guard !calls.isEmpty else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no played-back calls on this Mac", latencyMs: nil))
            return ([:], nil)
        }
        let recordings = Recordings(root: recorderScratch.appendingPathComponent("whisper-recordings", isDirectory: true))
        let out = context.snapshotDirectory?.appendingPathComponent("voices", isDirectory: true)
        var them: [String: [TranscriptWord]] = [:]
        var kept: URL?
        var rows: [String] = []
        var errors = (me: 0.0, meWords: 0, them: 0.0, themWords: 0)
        var given = (right: 0, of: 0)
        var engines: Set<String> = []
        var audio = 0.0, wall = 0.0
        for call in calls {
            guard let data = try? Data(contentsOf: call.appendingPathComponent("truth.json")),
                  let truth = try? JSONDecoder().decode(CallTruth.self, from: data),
                  let folder = try? recordings.makeFolder(title: call.lastPathComponent, started: .now) else { continue }
            let converted = await Task.detached {
                Self.m4a(from: call.appendingPathComponent("me.wav"), to: folder.appendingPathComponent(Speaker.me.file))
                    && Self.m4a(from: call.appendingPathComponent("them.wav"), to: folder.appendingPathComponent(Speaker.them.file))
            }.value
            guard converted else { continue }
            let user = truth.turns.first(where: \.me)?.speaker
            // The contacts as the measurement had them (attendees first in
            // vocab.txt); the user's own name first, as Dictate puts it.
            let vocabulary = ((try? String(contentsOf: call.appendingPathComponent("vocab.txt"), encoding: .utf8)) ?? "")
                .split(separator: "\n").map(String.init)
            let attendees = (truth.attendees ?? []).filter { $0 != user }
            var record = MeetingRecord(title: call.lastPathComponent, started: .now, language: truth.language == "fr" ? "fr-FR" : "en-US", recorder: nil)
            record.attendees = attendees
            record.state = .transcribing
            let setup = MeetingTranscriber.Setup(standard: .whisper, whisperReady: true,
                                                 contacts: [user].compactMap { $0 } + vocabulary.filter { !(truth.attendees ?? []).contains($0) })
            let start = ContinuousClock.now
            guard let done = try? await MeetingTranscriber.transcribe(folder, record: record, setup: setup, step: { _ in }),
                  let transcript = recordings.transcript(folder) else {
                rows.append("\(call.lastPathComponent): no transcript")
                continue
            }
            let seconds = (ContinuousClock.now - start).milliseconds / 1000
            wall += seconds
            audio += 2 * (truth.seconds ?? 0)
            try? recordings.write(done, to: folder)
            engines.insert(done.engine ?? "none")
            if call.lastPathComponent == "en01" { kept = folder }
            let mine = transcript.lines.filter { $0.speaker.track == .me }, theirs = transcript.lines.filter { $0.speaker.track == .them }
            them[call.lastPathComponent] = theirs.flatMap(\.words)
            let me = Self.errorsPerHundred(truth.turns.filter(\.me).map(\.text).joined(separator: " "), mine.map(\.text).joined(separator: " "))
            let other = Self.errorsPerHundred(truth.turns.filter { !$0.me }.map(\.text).joined(separator: " "), theirs.map(\.text).joined(separator: " "))
            errors.me += me.errors * Double(me.words) / 100
            errors.meWords += me.words
            errors.them += other.errors * Double(other.words) / 100
            errors.themWords += other.words
            let right = Self.attribution(transcript.lines, track: .them, turns: truth.turns)
            given.right += right.right
            given.of += right.of
            rows.append(String(format: "%@ me %.1f them %.1f, %d voices, %.0f s", call.lastPathComponent, me.errors, other.errors,
                               Set(theirs.map(\.speaker)).count, seconds))
            if let out {
                for (track, lines) in [("me", mine), ("them", theirs)] {
                    Self.writeForScorers(lines.flatMap(\.words), text: lines.map(\.text).joined(separator: " "),
                                         to: out.appendingPathComponent("app-w/\(call.lastPathComponent)/\(track)"), seconds: seconds / 2)
                }
            }
        }
        let me = 100 * errors.me / Double(max(1, errors.meWords)), other = 100 * errors.them / Double(max(1, errors.themWords))
        let share = 100 * Double(given.right) / Double(max(1, given.of))
        // Measured (whisper turbo, VAD, names): 10.8 per hundred words
        // against macOS's 17.9; numbers are left out here, so the gate is
        // loose, the kit's scorer gives the table.
        let passed = rows.count == calls.count && engines == [TranscriptEngine.whisper.rawValue] && me <= 20 && other <= 15 && share >= 85
        record(name, passed,
               String(format: "%d calls (%.0f min of tracks in %.0f s, ×%.0f real time), engine %@; errors per hundred words me %.1f (%d words), them %.1f (%d words), numbers left out; the other side's words to the right person %.1f %%; %@",
                      rows.count, audio / 60, wall, audio / max(1, wall), engines.sorted().joined(separator: ","), me, errors.meWords, other,
                      errors.themWords, share, rows.joined(separator: "; ")),
               nil)
        return (them, kept)
    }

    /// A track's words as the kit's scorers read them: `<path>.json` with
    /// its text (`score_engines.py`) and each word's time (`echo_dedup.py`),
    /// `<path>.log` with the time it took.
    nonisolated private static func writeForScorers(_ words: [TranscriptWord], text: String, to path: URL, seconds: Double) {
        try? FileManager.default.createDirectory(at: path.deletingLastPathComponent(), withIntermediateDirectories: true)
        let json: [String: Any] = ["text": text, "words": words.map { ["w": $0.text, "start": $0.start, "end": $0.end] as [String: Any] }]
        try? JSONSerialization.data(withJSONObject: json).write(to: path.appendingPathExtension("json"))
        try? "wall \(seconds) rc 0\n".write(to: path.appendingPathExtension("log"), atomically: true, encoding: .utf8)
    }

    /// No headphones, with whisper (docs/meeting-recorder.md, "To check"):
    /// the microphone's track with the other side heard again 12 and 20 dB
    /// under (the measurement's `echo-12`, `echo-20`), its words' times on
    /// the recording's clock (whisper.cpp adds its VAD's cuts back), then
    /// the drop by word times against the Mac's sound. Written for
    /// `echo_dedup.py`; here, the words left against the clean track's.
    private func echoDropWithWhisper(_ them: [String: [TranscriptWord]]) async {
        let name = "Recorder phase 4: no headphones with whisper: its word times on the recording's clock, the other side's words heard again dropped by word times"
        let out = context.snapshotDirectory?.appendingPathComponent("voices", isDirectory: true)
        var rows: [String] = []
        var totals = (clean: 0, heard: 0, kept: 0)
        for call in Self.playedBackCalls {
            guard let heard = them[call.lastPathComponent],
                  let data = try? Data(contentsOf: call.appendingPathComponent("truth.json")),
                  let truth = try? JSONDecoder().decode(CallTruth.self, from: data) else { continue }
            let language = truth.language == "fr" ? "fr" : "en"
            let attendees = (truth.attendees ?? []).filter { $0 != truth.turns.first(where: \.me)?.speaker }
            var clean = 0
            if let words = try? Data(contentsOf: (out ?? call).appendingPathComponent("app-w/\(call.lastPathComponent)/me.json")),
               let json = try? JSONSerialization.jsonObject(with: words) as? [String: Any] {
                clean = (json["words"] as? [Any])?.count ?? 0
            }
            for level in ["12", "20"] {
                let track = recorderScratch.appendingPathComponent("\(call.lastPathComponent)-echo-\(level).m4a")
                let converted = await Task.detached { Self.m4a(from: call.appendingPathComponent("echo-\(level).wav"), to: track) }.value
                guard converted else { continue }
                let start = ContinuousClock.now
                guard let run = try? await TranscriberHelper.whisper(of: track, language: language, prompt: WhisperTranscript.prompt(
                    attendees: attendees, contacts: [], language: language), progress: { _ in }) ?? nil else {
                    rows.append("\(call.lastPathComponent) -\(level): no words")
                    continue
                }
                let phrases = WhisperTranscript.phrases(of: run, attendees: attendees)
                let (left, dropped) = MeetingTranscript.droppingEcho(phrases, heard: heard)
                let words = phrases.flatMap { $0 }
                if level == "12" {
                    totals.clean += clean
                    totals.heard += words.count
                    totals.kept += left.flatMap { $0 }.count
                }
                rows.append("\(call.lastPathComponent) -\(level) dB: \(words.count) words, \(dropped) dropped")
                if let out {
                    Self.writeForScorers(words, text: MeetingTranscript.joined(words),
                                         to: out.appendingPathComponent("app-w/\(call.lastPathComponent)/echo-\(level)"),
                                         seconds: (ContinuousClock.now - start).milliseconds / 1000)
                }
            }
        }
        // The words left close to the clean track's (Measured with whisper's
        // times off: about twice as many; with each word's time, macOS's
        // engine left 3 % of the other side).
        let ratio = Double(totals.kept) / Double(max(1, totals.clean))
        let passed = totals.clean > 0 && ratio <= 1.35
        record(name, passed,
               String(format: "-12 dB: %d words heard without headphones, %d left after the drop, the clean track %d (×%.2f); %@", totals.heard, totals.kept,
                      totals.clean, ratio, rows.joined(separator: "; ")),
               nil)
    }

    /// On en01's whisper transcript: Transcribe Again offers both engines,
    /// Better transcription picked as it was, its languages; macOS picked
    /// makes it with macOS's; the Record card's languages hold whisper's
    /// (Welsh); Remove puts the model in the Trash, macOS's engine from
    /// then on, ⌘Z brings it back.
    private func whisperOfferedAndRemoved(_ folder: URL) async {
        let name = "Recorder phase 4: Transcribe Again offers Better transcription and macOS, each used as picked; whisper's languages listed; Remove to the Trash with the undo card, ⌘Z brings it back"
        guard let center = context.recorder(), let store = context.betterTranscription() else {
            record(name, false, "no recorder", nil)
            return
        }
        center.open(folder)
        guard let controller = center.window(for: folder) else {
            record(name, false, "no window", nil)
            return
        }
        controller.showTranscribeAgain()
        guard let panel = controller.againPanel, await waitUntil(timeout: 5, { panel.isShown && panel.isLoaded }) != nil else {
            record(name, false, "no panel", nil)
            return
        }
        let engines = panel.shownEngines, whisperLanguages = panel.shownLanguages.count
        if let directory = context.snapshotDirectory, let window = panel.window {
            for (suffix, appearance) in GlassCheck.appearances {
                window.appearance = appearance
                controller.nsWindow.appearance = appearance
                await pause(400)
                if let png = await WindowCapture.png(of: window) { try? png.write(to: directory.appendingPathComponent("recorder-transcribe-again-whisper-\(suffix).png")) }
            }
            window.appearance = nil
            controller.nsWindow.appearance = nil
        }
        await panel.pick(language: "en-US", engine: .macOS)
        panel.press()
        let byMacOS = await waitUntil(timeout: 120) { center.recordings.read(folder)?.engine == TranscriptEngine.macOS.rawValue && !controller.shownLines.isEmpty } != nil
        controller.close()
        let welsh = await MeetingTranscriber.languages().contains { $0.id == "cy" }
        // Remove: the undo card; ⌘Z puts it back.
        guard await focusTestWindow() else {
            record(name, false, "the test window did not take the keyboard", nil)
            return
        }
        let popover = context.aiActions.popover
        try? context.deletes?.betterTranscription(store)
        let removed = await waitUntil(timeout: 2) { !BetterTranscription.isReady() && popover.isVisible } != nil
        let card = popover.shownTitle
        await pressKey("z", flags: .maskCommand)
        let back = await waitUntil(timeout: 5) { BetterTranscription.isReady() && store.state == .downloaded } != nil
        let passed = engines == ["macOS", "Better transcription"] && whisperLanguages >= 90 && byMacOS && welsh && removed && card == "Better Transcription Removed" && back
        record(name, passed,
               "engines \(engines), Better transcription's languages \(whisperLanguages); macOS as picked \(byMacOS); Welsh listed \(welsh); removed \(removed) (card “\(card)”), ⌘Z back \(back)",
               nil)
    }

    private func recorderChecks() async {
        let (consent, language) = (context.preferences.recorderConsentShown, context.preferences.voiceLanguage)
        defer {
            context.preferences.recorderConsentShown = consent
            context.preferences.voiceLanguage = language
        }
        context.preferences.recorderConsentShown = false
        // The calls are English; the test Mac types French: Ask's language
        // says English, as a user would set it.
        context.preferences.voiceLanguage = "en-US"
        await recorderCardShowsBothSourcesLive()
        if !aborted { await recorderRecordsAPlayedBackCall() }
        if !aborted { await recorderPausesBothTracksTogether() }
        if !aborted { await recorderOffersOneNeverStopped() }
        if !aborted { await recorderQuitClosesItWhole() }
        if !aborted { await recorderSleepPausesUntilResumed() }
        if !aborted { await recorderFromLinksAndTools() }
    }

    /// The played-back calls (`script/recorder-measure`: `push.sh` puts them
    /// on the test Mac): each call's two sides and its script.
    private static var recorderCalls: URL {
        FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("recorder-measure/audio/calls", isDirectory: true)
    }

    /// One call's script, as `truth.json` has it: who says what, when.
    private struct CallTruth: Decodable {
        struct Turn: Decodable {
            let me: Bool
            let start: Double
            let end: Double
            let text: String
            let speaker: String?
        }

        let language: String
        let turns: [Turn]
        let attendees: [String]?
        let seconds: Double?
    }

    /// The self-test's scratch audio.
    private var recorderScratch: URL {
        let folder = FileManager.default.temporaryDirectory.appendingPathComponent("skilli-selftest-\(getpid())/recorder-audio", isDirectory: true)
        try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        return folder
    }

    /// `source`'s first `seconds` (16 kHz WAV) with a 40 ms beep at each of
    /// `beeps` (s), written to `name` in the scratch folder: the same beeps
    /// in both sides tell where each landed in its track.
    /// `ppm`: as a microphone whose clock runs that fast or slow hears it:
    /// stretched (or squeezed) by as much, a frame of it a moment of the
    /// call at that clock's rate.
    nonisolated private static func clip(_ source: URL?, seconds: Double, beeps: [Double], ppm: Double = 0, to url: URL) -> Bool {
        let rate = 16000.0
        let factor = 1 + ppm * 1e-6
        let frames = Int(seconds * rate * factor)
        guard let format = AVAudioFormat(standardFormatWithSampleRate: rate, channels: 1),
              let buffer = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: AVAudioFrameCount(frames)), let data = buffer.floatChannelData?[0]
        else { return false }
        buffer.frameLength = AVAudioFrameCount(frames)
        data.update(repeating: 0, count: frames)
        let wanted = Int(seconds * rate) + 2
        if let source, let file = try? AVAudioFile(forReading: source), file.processingFormat.sampleRate == rate,
           let read = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: AVAudioFrameCount(wanted)),
           (try? file.read(into: read, frameCount: AVAudioFrameCount(min(Int64(wanted), file.length)))) != nil, let samples = read.floatChannelData?[0] {
            let count = Int(read.frameLength)
            if ppm == 0 {
                data.update(from: samples, count: min(count, frames))
            } else {
                for index in 0..<frames {
                    let at = Double(index) / factor
                    let low = Int(at), weight = Float(at - Double(low))
                    guard low + 1 < count else { break }
                    data[index] = samples[low] * (1 - weight) + samples[low + 1] * weight
                }
            }
        }
        for beep in beeps {
            let start = Int((beep * rate * factor).rounded())
            for index in start..<min(frames, start + Int(0.04 * rate)) {
                data[index] = 0.6 * Float(sin(2 * Double.pi * 2000 * Double(index - start) / rate))
            }
        }
        try? FileManager.default.removeItem(at: url)
        guard let out = try? AVAudioFile(forWriting: url, settings: format.settings) else { return false }
        return (try? out.write(from: buffer)) != nil
    }

    /// Both tracks' beeps against each other: each of the microphone's with
    /// the other's at the most common offset (the other side plays a little
    /// later), within 50 ms of it; a beep half a second away is the next one.
    private struct BeepPairs {
        /// Where each of the microphone's track's beeps landed (s).
        let mine: [Double]
        /// A beep of the microphone's track, and how much later the other's.
        let paired: [(at: Double, offset: Double)]

        init(me: [Double], them: [Double]) {
            let nearest = me.map { mine in (mine, them.min { abs($0 - mine) < abs($1 - mine) }.map { $0 - mine } ?? .nan) }
            let sorted = nearest.map(\.1).filter { !$0.isNaN }.sorted()
            let median = sorted.isEmpty ? 0 : sorted[sorted.count / 2]
            mine = me
            paired = nearest.filter { abs($0.1 - median) < 0.05 }.map { (at: $0.0, offset: $0.1) }
        }

        /// The offsets 3 s each side of `moment` (0.3 s around it left out:
        /// a glitch of the other app's playback elsewhere stays out of it).
        func around(_ moment: Double) -> (before: [Double], after: [Double]) {
            (paired.filter { $0.at < moment - 0.3 && $0.at > moment - 3.3 }.map(\.offset),
             paired.filter { $0.at > moment + 0.3 && $0.at < moment + 3.3 }.map(\.offset))
        }

        /// How far the offset moved across `moment` (nan without beeps on
        /// both sides).
        func step(at moment: Double) -> Double {
            let (before, after) = around(moment)
            return abs(Self.mean(after) - Self.mean(before))
        }

        static func mean(_ values: [Double]) -> Double { values.isEmpty ? .nan : values.reduce(0, +) / Double(values.count) }
    }

    /// A recording's two tracks' beeps, found off the main thread.
    nonisolated private static func beepPairs(in folder: URL) async -> BeepPairs {
        await Task.detached {
            BeepPairs(me: beeps(in: folder.appendingPathComponent(Speaker.me.file)), them: beeps(in: folder.appendingPathComponent(Speaker.them.file)))
        }.value
    }

    /// Where each beep (2 kHz, 40 ms) starts in a track, in seconds: the
    /// 2 kHz power in 5 ms windows a quarter of a millisecond apart.
    nonisolated private static func beeps(in url: URL) -> [Double] {
        guard let file = try? AVAudioFile(forReading: url), file.length > 0,
              let buffer = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: AVAudioFrameCount(file.length)),
              (try? file.read(into: buffer)) != nil, let data = buffer.floatChannelData?[0] else { return [] }
        let rate = file.processingFormat.sampleRate
        let window = Int(rate * 0.005), hop = max(1, Int(rate * 0.00025))
        let k = Float(2 * cos(2 * Double.pi * 2000 / rate))
        var powers: [Float] = []
        var start = 0
        while start + window < Int(buffer.frameLength) {
            var s1: Float = 0, s2: Float = 0
            for index in 0..<window {
                let s0 = data[start + index] + k * s1 - s2
                s2 = s1
                s1 = s0
            }
            powers.append(s1 * s1 + s2 * s2 - k * s1 * s2)
            start += hop
        }
        guard let loudest = powers.max(), loudest > 0 else { return [] }
        var onsets: [Double] = []
        var last = -1.0
        for (index, power) in powers.enumerated() where power > loudest * 0.25 {
            let time = Double(index * hop) / rate
            if time - last > 0.3 { onsets.append(time) }
            last = time
        }
        return onsets
    }

    /// Errors per hundred words of `reference` (substitutions, deletions,
    /// insertions), case, accents, punctuation and how a number is written
    /// left out, as the measurement scored them.
    nonisolated private static func errorsPerHundred(_ reference: String, _ hypothesis: String) -> (errors: Double, words: Int) {
        let numbers: Set<String> = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve",
                                    "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen", "twenty", "thirty",
                                    "forty", "fifty", "sixty", "seventy", "eighty", "ninety", "hundred", "thousand", "million", "percent",
                                    "euro", "euros"]
        func words(_ text: String) -> [String] {
            let folded = text.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: nil)
            let spaced = String(folded.unicodeScalars.map { CharacterSet.alphanumerics.contains($0) ? Character($0) : " " })
            return spaced.split(separator: " ").map(String.init).filter { !numbers.contains($0) && !$0.allSatisfy(\.isNumber) }
        }
        let ref = words(reference), hyp = words(hypothesis)
        guard !ref.isEmpty else { return (hyp.isEmpty ? 0 : 100, 0) }
        var row = Array(0...hyp.count)
        for (i, word) in ref.enumerated() {
            var next = [i + 1] + [Int](repeating: 0, count: hyp.count)
            for j in 0..<hyp.count {
                next[j + 1] = min(row[j + 1] + 1, next[j] + 1, row[j] + (word == hyp[j] ? 0 : 1))
            }
            row = next
        }
        return (100 * Double(row[hyp.count]) / Double(ref.count), ref.count)
    }

    /// `afplay` playing `url` (another app playing the call's other side,
    /// heard by the tap); killed with the check.
    private func playElsewhere(_ url: URL) -> Process? {
        let play = Process()
        play.executableURL = URL(fileURLWithPath: "/usr/bin/afplay")
        play.arguments = [url.path]
        try? play.run()
        return play
    }

    /// The newest recording folder in the self-test's Recordings.
    private func newestRecording(in root: URL) -> URL? {
        let folders = (try? FileManager.default.contentsOfDirectory(at: root, includingPropertiesForKeys: [.creationDateKey], options: [.skipsHiddenFiles])) ?? []
        return folders.max { a, b in
            ((try? a.resourceValues(forKeys: [.creationDateKey]))?.creationDate ?? .distantPast)
                < ((try? b.resourceValues(forKeys: [.creationDateKey]))?.creationDate ?? .distantPast)
        }
    }

    private func trackLength(_ url: URL) -> Double {
        (try? AVAudioFile(forReading: url)).map { Double($0.length) / $0.processingFormat.sampleRate } ?? 0
    }

    /// The card over the test window, light and dark: the screen around it.
    private func captureRecordCard(_ center: RecorderCenter, as name: String) async {
        guard let directory = context.snapshotDirectory, let panel = center.cardWindow else { return }
        let (panelAppearance, testAppearance) = (panel.appearance, window.appearance)
        defer {
            panel.appearance = panelAppearance
            window.appearance = testAppearance
        }
        for (suffix, appearance) in GlassCheck.appearances {
            panel.appearance = appearance
            window.appearance = appearance
            await pause(900)
            if let image = await GlassCheck.screenshot(around: panel, padding: -Theme.glassMargin + 16),
               let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                try? png.write(to: directory.appendingPathComponent("\(name)-\(suffix).png"))
            }
        }
    }

    /// A recording's window, light and dark.
    private func captureRecordingWindow(_ controller: RecordingWindowController, as name: String) async {
        guard let directory = context.snapshotDirectory else { return }
        let window = controller.nsWindow
        let saved = window.appearance
        defer { window.appearance = saved }
        for (suffix, appearance) in GlassCheck.appearances {
            window.appearance = appearance
            await pause(500)
            if let png = await WindowCapture.png(of: window) { try? png.write(to: directory.appendingPathComponent("\(name)-\(suffix).png")) }
        }
    }

    /// Opens the recorder's menu in the menu bar with a real click, captures
    /// it, then chooses `pick` (else esc). Its items.
    private func openRecorderMenu(_ center: RecorderCenter, capture: String, pick: String? = nil, pickPrefix: Bool = false,
                                  picked: () -> Void = {}) async -> [String] {
        guard let button = center.menuBar.button, let frame = button.window?.frame else { return [] }
        let source = CGEventSource(stateID: .hidSystemState)
        let screenHeight = NSScreen.screens.first?.frame.maxY ?? 0
        let point = CGPoint(x: frame.midX, y: screenHeight - frame.midY)
        let guardTimer = DispatchWorkItem {
            for down in [true, false] {
                CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
            }
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + 10, execute: guardTimer)
        defer { guardTimer.cancel() }
        for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(60)
        }
        await pause(700)
        // The status items' menu bar only: the app's own menus are not this
        // menu (and its Apple menu names the Mac's account).
        var extras: CFTypeRef?
        AXUIElementCopyAttributeValue(AXUIElementCreateApplication(getpid()), kAXExtrasMenuBarAttribute as CFString, &extras)
        let items = extras.map { Self.axElements(roles: [kAXMenuItemRole], under: ($0 as! AXUIElement)) { _ in true } } ?? []
        let titles = items.compactMap { Self.axTitle($0) }.filter { !$0.isEmpty }
        if let directory = context.snapshotDirectory, let image = await WindowCapture.openMenuImage(),
           let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
            try? png.write(to: directory.appendingPathComponent(capture))
        }
        if let pick, let item = items.first(where: { pickPrefix ? Self.axTitle($0)?.hasPrefix(pick) == true : Self.axTitle($0) == pick }) {
            picked()
            AXUIElementPerformAction(item, kAXPressAction as CFString)
        } else {
            for down in [true, false] {
                CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
            }
        }
        await pause(300)
        return titles
    }

    /// The Record card has the keyboard before a key is pressed into it;
    /// else every later check is skipped: no key may land in another app.
    private func recordCardHasKeys(_ center: RecorderCenter, _ name: String) async -> Bool {
        if await waitUntil(timeout: 1.5, { center.cardWindow?.isKeyWindow == true }) != nil { return true }
        aborted = true
        let front = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"
        // macOS's own question in front (a permission skil.li asked for):
        // its owner answers it once on this Mac.
        let why = front == "com.apple.UserNotificationCenter" ? "macOS asks a question in front (a permission: answer it on this Mac once)" : "front: \(front)"
        let view = center.cardView
        record(name, false, "the Record card did not take the keyboard (\(why)): stopped so no key lands elsewhere; the card said microphone “\(view.microphoneLine)”, the Mac's sound “\(view.macLine)”, language “\(view.languageShown)”, note “\(view.noteText)”", nil)
        return false
    }

    /// Types `text` into the launcher, open from the test window.
    private func typeInLauncher(_ text: String) async -> Bool {
        guard await openLauncher() else { return false }
        for character in text { _ = await typeCharacter(character) }
        return await waitUntil(timeout: 1) { self.context.launcher.query == text } != nil
    }

    /// The Record card from the launcher ("rec weekly sync" ↩): its name in
    /// the field, the first time the consent, both sources live (the
    /// meters rise while the Mac plays and the stand-in microphone speaks:
    /// they are the permission check), esc records nothing.
    private func recorderCardShowsBothSourcesLive() async {
        let name = "Recorder: “rec weekly sync” ↩ opens the Record card named so, the consent the first time, both meters live (the Mac's sound, the microphone), esc records nothing"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return
        }
        let train = recorderScratch.appendingPathComponent("train.wav")
        _ = Self.clip(nil, seconds: 20, beeps: stride(from: 0.5, to: 20, by: 0.25).map { $0 }, to: train)
        center.recorder.standIn(microphone: train, alsoLeaveOut: [])
        let before = (try? FileManager.default.contentsOfDirectory(atPath: center.recordings.root.path))?.count ?? 0
        guard await typeInLauncher("rec weekly sync") else {
            record(name, false, "the launcher did not take “rec weekly sync”", nil)
            return
        }
        let row = context.launcher.results.first?.title ?? ""
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let view = center.cardView
        let shown = await waitUntil(timeout: 3) { center.isCardVisible && view.microphoneLine != "Starting…" && view.macLine != "Starting…" } != nil
        let named = view.name == "weekly sync"
        let consent = view.consentShown
        // The Mac plays (another app) and the stand-in microphone speaks.
        let play = playElsewhere(train)
        try? center.recorder.microphone.playStandIn(at: mach_absolute_time())
        var levels = (mic: 0.0, mac: 0.0)
        _ = await waitUntil(timeout: 4) {
            let now = center.recorder.levels
            levels = (max(levels.mic, now.mic), max(levels.mac, now.mac))
            return levels.mic > 0.2 && levels.mac > 0.2
        }
        let lines = "microphone “\(view.microphoneLine)”, the Mac's sound “\(view.macLine)”, note “\(view.noteText)”, language \(view.languageShown)"
        await captureRecordCard(center, as: "recorder-card")
        play?.terminate()
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let gone = await waitUntil(timeout: 2) { !center.isCardVisible && center.recorder.phase == .idle } != nil
        let after = (try? FileManager.default.contentsOfDirectory(atPath: center.recordings.root.path))?.count ?? 0
        record(name, row == "Record “weekly sync”" && shown && named && consent && levels.mic > 0.2 && levels.mac > 0.2 && gone && after == before,
               "row “\(row)”, card \(shown), named “\(view.name)”, consent \(consent), levels mic \(String(format: "%.2f", levels.mic)) mac \(String(format: "%.2f", levels.mac)); \(lines); closed \(gone), folders \(before) → \(after)",
               nil)
    }

    /// The first 75 s of a scripted call (en01): the user's side stands in
    /// for the microphone, the other side plays in another app (`afplay`,
    /// heard by the tap). ↩ in the card records; stopped from the menu bar;
    /// then the transcript: each side against the script, the two tracks
    /// in step (a beep at each end of both sides), the window's lines.
    private func recorderRecordsAPlayedBackCall() async {
        let name = "Recorder: a played-back call (en01's first 75 s): two tracks in step, each side transcribed against the script, Me and Them by time, its window"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return
        }
        let call = Self.recorderCalls.appendingPathComponent("en01")
        guard let data = try? Data(contentsOf: call.appendingPathComponent("truth.json")), let truth = try? JSONDecoder().decode(CallTruth.self, from: data)
        else {
            checks.append(Check(name: name, passed: true, skipped: true,
                                detail: "no played-back calls on this Mac (script/recorder-measure/push.sh puts them in ~/recorder-measure)", latencyMs: nil))
            return
        }
        // Cut where a turn ends, before 75 s; a beep at each end.
        let cut = (truth.turns.map(\.end).filter { $0 <= 75 }.max() ?? 75) + 0.8
        let turns = truth.turns.filter { $0.end <= cut - 0.5 }
        let beeps = [0.3, cut - 0.4]
        let me = recorderScratch.appendingPathComponent("en01-me.wav"), them = recorderScratch.appendingPathComponent("en01-them.wav")
        // The microphone's clock 100 ppm fast, as a USB or Bluetooth one may
        // run: 7 ms off the other side by the end, uncorrected.
        guard Self.clip(call.appendingPathComponent("me.wav"), seconds: cut, beeps: beeps, ppm: 100, to: me),
              Self.clip(call.appendingPathComponent("them.wav"), seconds: cut, beeps: beeps, to: them) else {
            record(name, false, "the call could not be cut", nil)
            return
        }
        center.recorder.standIn(microphone: me, alsoLeaveOut: [])
        guard await typeInLauncher("rec played call") else {
            record(name, false, "the launcher did not take “rec played call”", nil)
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        guard await waitUntil(timeout: 3, { center.isCardVisible && center.cardView.microphoneLine != "Starting…" }) != nil else {
            record(name, false, "no Record card", nil)
            return
        }
        // Shown until a first recording starts.
        let consentUntilFirst = center.cardView.consentShown
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        guard await waitUntil(timeout: 2, { center.recorder.phase == .recording }) != nil else {
            record(name, false, "↩ did not start the recording (\(center.recorder.phase))", nil)
            return
        }
        let consentKept = context.preferences.recorderConsentShown
        let start = ContinuousClock.now
        var wall = 0.0
        try? center.recorder.microphone.playStandIn(at: mach_absolute_time(), ppm: 100)
        let play = playElsewhere(them)
        defer { play?.terminate() }
        // While it records: the menu bar, the launcher's row.
        await pause(4000)
        let bar = center.menuBar.shown ?? ""
        if let button = center.menuBar.button { await captureStatusItem(button, "recorder-menubar") }
        let menu = await openRecorderMenu(center, capture: "recorder-menu.png")
        _ = await typeInLauncher("rec")
        let liveRow = context.launcher.results.first?.title ?? ""
        await captureLauncherBothWays(as: "recorder-launcher-row")
        await closeLauncher()
        // To the end of the call, then Stop from the menu bar.
        let left = cut + 0.6 - (ContinuousClock.now - start).milliseconds / 1000
        if left > 0 { try? await Task.sleep(for: .seconds(left)) }
        _ = await openRecorderMenu(center, capture: "recorder-menu-stop.png", pick: "Stop and Transcribe", picked: { wall = (ContinuousClock.now - start).milliseconds / 1000 })
        let stopped = await waitUntil(timeout: 5) { center.recorder.phase == .idle } != nil
        _ = await waitUntil(timeout: 3) { center.recorder.transcribing != nil }
        if let button = center.menuBar.button, center.recorder.transcribing != nil { await captureStatusItem(button, "recorder-menubar-transcribing") }
        let transcribed = await waitUntil(timeout: 120) { center.recorder.transcribing == nil && !center.openWindows.isEmpty } != nil
        guard stopped, transcribed, let folder = newestRecording(in: center.recordings.root), let controller = center.window(for: folder),
              let record = center.recordings.read(folder), let transcript = center.recordings.transcript(folder) else {
            self.record(name, false, "stopped \(stopped), transcribed \(transcribed), bar “\(bar)”, menu \(menu)", nil)
            return
        }
        // The two tracks: as long as the call was recorded, in step.
        let lengths = (me: trackLength(folder.appendingPathComponent("me.m4a")), them: trackLength(folder.appendingPathComponent("them.m4a")))
        let found = await Task.detached { (Self.beeps(in: folder.appendingPathComponent("me.m4a")), Self.beeps(in: folder.appendingPathComponent("them.m4a"))) }.value
        let offsets = zip(found.0, found.1).map { $1 - $0 }
        let drift = (offsets.max() ?? 0) - (offsets.min() ?? 0)
        // Each side against the script.
        let mine = Self.errorsPerHundred(turns.filter(\.me).map(\.text).joined(separator: " "),
                                         transcript.lines.filter { $0.speaker == .me }.map(\.text).joined(separator: " "))
        let theirs = Self.errorsPerHundred(turns.filter { !$0.me }.map(\.text).joined(separator: " "),
                                           transcript.lines.filter { $0.speaker.track == .them }.map(\.text).joined(separator: " "))
        // Me and Them by time: the script's turns and the lines alternate
        // alike (the other side's voices told apart since phase 4).
        let speakers = transcript.lines.map(\.speaker.track)
        let both = speakers.contains(.me) && speakers.contains(.them)
        // The window: its lines; a click on the third plays from it.
        let shownLines = controller.shownLines.count
        await captureRecordingWindow(controller, as: "recorder-window")
        var clickedPlays = false
        var clickDetail = "fewer than four lines"
        if controller.shownLines.count > 3, let frame = controller.screenFrame(ofLine: 2) {
            // A real click on the third line, its window in front.
            controller.present()
            guard await waitUntil(timeout: 2, { controller.nsWindow.isKeyWindow && NSApp.isActive }) != nil else {
                aborted = true
                controller.close()
                let front = NSWorkspace.shared.frontmostApplication?.bundleIdentifier ?? "?"
                self.record(name, false, "the recording window did not take the keyboard (front: \(front)): stopped so no click or key lands elsewhere", nil)
                return
            }
            let screenHeight = NSScreen.screens.first?.frame.maxY ?? 0
            let point = CGPoint(x: frame.midX, y: screenHeight - frame.midY)
            let source = CGEventSource(stateID: .hidSystemState)
            for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
                CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
                await pause(60)
            }
            let third = controller.shownLines[2]
            clickedPlays = await waitUntil(timeout: 3) { controller.playing && controller.litLine == 2 && controller.spaceHint == "Pause" } != nil
            clickDetail = String(format: "playing %@ at %.2f s (the line starts at %.2f s), lit %@, space says “%@”", "\(controller.playing)", controller.currentTime,
                                 third.start, controller.litLine.map(String.init) ?? "none", controller.spaceHint ?? "")
            await captureRecordingWindow(controller, as: "recorder-window-playing")
            // Space pauses it.
            await pressKey(nil, code: CGKeyCode(kVK_Space))
            let pausedAgain = await waitUntil(timeout: 2) { !controller.playing && controller.spaceHint == "Play" } != nil
            clickedPlays = clickedPlays && pausedAgain
            clickDetail += ", space pauses \(pausedAgain)"
        }
        controller.close()
        let inStep = found.0.count == 2 && found.1.count == 2 && drift < 0.002 && abs(lengths.me - lengths.them) < 0.05
        let passed = consentUntilFirst && consentKept && bar.contains(":") && menu.contains("Pause Recording") && menu.contains("Stop and Transcribe")
            && liveRow.hasPrefix("Recording “played call”") && inStep && abs(lengths.me - wall) < 0.5
            && mine.errors <= 35 && theirs.errors <= 25 && both && shownLines == transcript.lines.count && clickedPlays
            && record.state == .done && record.engine == MeetingTranscriber.engine
        self.record(name, passed,
                    String(format: "tracks %.2f s / %.2f s (recorded %.2f s, the call %.1f s); beeps me %@ them %@, offsets %@ (drift %.1f ms, the microphone 100 ppm fast); errors per hundred words: me %.1f (%d words), them %.1f (%d words); %d lines (Me %d, Them %d); consent until the first recording %@; menu bar “%@”, menu %@; launcher row “%@”; a line clicked: %@; %@ in %@",
                           lengths.me, lengths.them, wall, cut, found.0.map { String(format: "%.3f", $0) }.joined(separator: ","),
                           found.1.map { String(format: "%.3f", $0) }.joined(separator: ","), offsets.map { String(format: "%.3f", $0) }.joined(separator: ","),
                           drift * 1000, mine.errors, mine.words, theirs.errors, theirs.words, transcript.lines.count,
                           speakers.filter { $0 == .me }.count, speakers.filter { $0 == .them }.count, "\(consentUntilFirst && consentKept)", bar, menu.joined(separator: " | "),
                           liveRow, clickDetail, record.engine ?? "no engine", record.language),
                    nil)
    }

    /// Pause from the menu bar: nothing written to either track until
    /// Resume, the clock stopped, the dot hollow; the beeps (one every
    /// half second, in both sides) keep the same offset before and after.
    private func recorderPausesBothTracksTogether() async {
        let name = "Recorder: Pause from the menu bar writes nothing to either track until Resume, the clock stops; both tracks keep their offset across it"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return
        }
        let train = recorderScratch.appendingPathComponent("pause-train.wav")
        // The microphone's clock 100 ppm slow, as a USB or Bluetooth one may run.
        _ = Self.clip(nil, seconds: 30, beeps: stride(from: 0.5, to: 30, by: 0.5).map { $0 }, ppm: -100, to: train)
        center.recorder.standIn(microphone: train, alsoLeaveOut: [])
        center.showCard(title: "Pause check")
        guard await waitUntil(timeout: 3, { center.isCardVisible && center.cardView.microphoneLine != "Starting…" }) != nil else {
            record(name, false, "no Record card", nil)
            return
        }
        // Said once: not after a first recording.
        let consentGone = !center.cardView.consentShown
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        guard await waitUntil(timeout: 2, { center.recorder.phase == .recording }) != nil else {
            record(name, false, "not recording", nil)
            return
        }
        let began = ContinuousClock.now
        try? center.recorder.microphone.playStandIn(at: mach_absolute_time(), ppm: -100)
        let play = playElsewhere(train)
        defer { play?.terminate() }
        await pause(8000)
        _ = await openRecorderMenu(center, capture: "recorder-menu-pause.png", pick: "Pause Recording")
        let paused = await waitUntil(timeout: 2) { center.recorder.phase == .paused } != nil
        let frozen = center.menuBar.shown
        if let button = center.menuBar.button { await captureStatusItem(button, "recorder-menubar-paused") }
        await pause(4000)
        let stillFrozen = center.menuBar.shown == frozen
        let resumeMenu = await openRecorderMenu(center, capture: "recorder-menu-paused.png", pick: "Resume Recording")
        let resumed = await waitUntil(timeout: 2) { center.recorder.phase == .recording } != nil
        await pause(4000)
        // The audio setup changes (a device plugged): the microphone's
        // engine starts again, its track keeps its time.
        let restartsBefore = center.recorder.microphone.restarts
        let restartAt = center.recorder.elapsed
        center.recorder.microphone.simulateConfigurationChange()
        let restarted = center.recorder.microphone.restarts == restartsBefore + 1
        await pause(4000)
        let wall = (ContinuousClock.now - began).milliseconds / 1000
        center.control(.stop)
        let done = await waitUntil(timeout: 60) { center.recorder.phase == .idle && center.recorder.transcribing == nil && !center.openWindows.isEmpty } != nil
        guard done, let folder = newestRecording(in: center.recordings.root), let record = center.recordings.read(folder) else {
            self.record(name, false, "paused \(paused), resumed \(resumed), never done", nil)
            return
        }
        center.openWindows.forEach { $0.close() }
        let lengths = (me: trackLength(folder.appendingPathComponent("me.m4a")), them: trackLength(folder.appendingPathComponent("them.m4a")))
        let pairs = await Self.beepPairs(in: folder)
        let offsets = pairs.paired.map(\.offset)
        let pauseAt = record.pauses.first?.at ?? 0
        // The two tracks against each other around the pause and around the
        // engine started again.
        let (before, after) = pairs.around(pauseAt)
        let step = pairs.step(at: pauseAt)
        let spread = ((before + after).max() ?? 1) - ((before + after).min() ?? 0)
        let restartStep = pairs.step(at: restartAt)
        // Each track's own slip, as the recorder moved it back at Resume.
        let jumps = center.recorder.resumeJumps
        let worstJump = jumps.values.flatMap { $0 }.map(abs).max() ?? .nan
        let jumpLine = Speaker.allCases.map { speaker in
            "\(speaker.rawValue) " + (jumps[speaker] ?? []).map { String(format: "%+.2f ms", $0 * 1000) }.joined(separator: ", ")
        }.joined(separator: "; ")
        // Recorded: from ↩ to Stop, the pause taken out.
        let expected = wall - (record.pauses.first?.seconds ?? 0)
        let conditions: [(String, Bool)] = [
            ("consent gone", consentGone), ("paused", paused), ("clock still", stillFrozen), ("resumed", resumed), ("started again", restarted),
            ("menu says Resume", resumeMenu.contains("Resume Recording")), ("one pause", record.pauses.count == 1),
            ("pause long enough", (record.pauses.first?.seconds ?? 0) > 4), ("tracks alike", abs(lengths.me - lengths.them) < 0.05),
            ("recorded as long", abs(lengths.me - expected) < 0.5), ("slip under 1 ms", !(worstJump >= 0.001)),
            ("step under 2 ms", step < 0.002), ("spread under 2 ms", spread < 0.002), ("restart under 2 ms", restartStep < 0.002),
            ("beeps around the pause", before.count >= 4 && after.count >= 4)
        ]
        let failed = conditions.filter { !$0.1 }.map(\.0)
        let passed = failed.isEmpty
        self.record(name, passed,
                    (failed.isEmpty ? "" : "failed: \(failed.joined(separator: ", ")); ") + String(format: "consent gone %@; paused %@, clock still “%@” %@, resumed %@, the microphone started again %@; pause at %.2f s for %.2f s; tracks %.2f s / %.2f s (%.2f s recorded); %d of %d beeps in step, offset %.1f ms before the pause, %.1f ms after (step %.2f ms, spread %.1f ms), at the engine started again a step of %.2f ms; each track moved back at Resume by %@ (the microphone 100 ppm slow)",
                           "\(consentGone)", "\(paused)", frozen ?? "", "\(stillFrozen)", "\(resumed)", "\(restarted)", pauseAt, record.pauses.first?.seconds ?? 0, lengths.me, lengths.them,
                           expected, offsets.count, pairs.mine.count, BeepPairs.mean(before) * 1000, BeepPairs.mean(after) * 1000, step * 1000, spread * 1000,
                           restartStep * 1000, jumpLine),
                    nil)
    }

    /// A recording skil.li never stopped: another skil.li records, killed
    /// (SIGKILL, as a crash or a power cut); its files play up to their
    /// last second, the card offers it, ↩ saves it (its transcript, its
    /// window). Then one discarded with ⌘⌫: to the Trash, ⌘Z puts it back.
    private func recorderOffersOneNeverStopped() async {
        let name = "Recorder: a recording never stopped (another skil.li killed while recording) plays to its last second, is offered with Save ↩, saved and transcribed; one discarded with ⌘⌫ comes back with ⌘Z"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return
        }
        let (me, them) = recorderCallClips("kill")
        let root = center.recordings.root

        /// Another skil.li records for `seconds`, then is killed; its folder.
        func recordThenKill(seconds: Double) async -> URL? {
            await recordInAnotherSkilli(root: root, me: me, them: them, seconds: seconds, ending: SIGKILL)?.folder
        }

        guard let folder = await recordThenKill(seconds: 12) else {
            record(name, false, "the other skil.li did not record", nil)
            return
        }
        let lengths = (me: trackLength(folder.appendingPathComponent("me.m4a")), them: trackLength(folder.appendingPathComponent("them.m4a")))
        let left = center.recordings.read(folder)
        // It takes the keyboard only after a second without a key.
        await pause(1200)
        let offered = center.offerUnfinishedNow()
        let view = center.cardView
        let shown = await waitUntil(timeout: 2) { center.isCardVisible && view.eyebrowText == "UNFINISHED RECORDING" } != nil
        let detail = view.detailText
        await captureRecordCard(center, as: "recorder-unfinished")
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let saved = await waitUntil(timeout: 60) { center.recorder.transcribing == nil && center.window(for: folder) != nil } != nil
        let after = center.recordings.read(folder)
        let lines = center.recordings.transcript(folder)?.lines.count ?? 0
        center.openWindows.forEach { $0.close() }

        // Discarded: to the Trash at once, ⌘Z brings it back.
        var discarded = false, inTrash = false, undone = false
        if let second = await recordThenKill(seconds: 5) {
            await pause(1200)
            _ = center.offerUnfinishedNow()
            if await waitUntil(timeout: 2, { center.isCardVisible && view.eyebrowText == "UNFINISHED RECORDING" }) != nil {
                guard await recordCardHasKeys(center, name) else { return }
                await pressHolding(.maskCommand, keys: [CGKeyCode(kVK_Delete)])
                discarded = await waitUntil(timeout: 3) { !FileManager.default.fileExists(atPath: second.path) } != nil
                inTrash = await waitUntil(timeout: 2) { self.context.aiActions.popover.isVisible && self.context.aiActions.popover.shownTitle == "Recording Deleted" } != nil
                // The layout's Z: kVK_ANSI_Z types W on AZERTY.
                await pressHolding(.maskCommand, keys: [keyCode("z") ?? CGKeyCode(kVK_ANSI_Z)])
                undone = await waitUntil(timeout: 3) { FileManager.default.fileExists(atPath: second.path) } != nil
                // Not offered again in this run: put to rest.
                if var record = center.recordings.read(second) {
                    record.state = .pending
                    try? center.recordings.write(record, to: second)
                }
            }
        }
        let passed = lengths.me > 9 && lengths.them > 9 && left?.state == .recording && offered >= 1 && shown && detail.contains("s, stopped")
            && saved && after?.state == .done && lines > 0 && discarded && inTrash && undone
        record(name, passed,
               String(format: "killed after 12 s: tracks %.2f s / %.2f s, left “%@”; offered %d, card %@ “%@”; saved %@ (%@, %d lines); discarded %@, Recording Deleted card %@, ⌘Z back %@",
                      lengths.me, lengths.them, left?.state.rawValue ?? "nothing", offered, "\(shown)", detail, "\(saved)", after?.state.rawValue ?? "?",
                      lines, "\(discarded)", "\(inTrash)", "\(undone)"),
               nil)
    }

    /// A call's two sides, 40 s of the first played-back call (beeps when
    /// the test Mac has none), as `<prefix>-me.wav` and `<prefix>-them.wav`.
    private func recorderCallClips(_ prefix: String) -> (me: URL, them: URL) {
        let call = Self.recorderCalls.appendingPathComponent("en01")
        let me = recorderScratch.appendingPathComponent("\(prefix)-me.wav"), them = recorderScratch.appendingPathComponent("\(prefix)-them.wav")
        let haveCall = FileManager.default.fileExists(atPath: call.appendingPathComponent("me.wav").path)
        _ = Self.clip(haveCall ? call.appendingPathComponent("me.wav") : nil, seconds: 40, beeps: haveCall ? [] : [1, 2, 3], to: me)
        _ = Self.clip(haveCall ? call.appendingPathComponent("them.wav") : nil, seconds: 40, beeps: haveCall ? [] : [1.5, 2.5], to: them)
        return (me, them)
    }

    /// What became of another skil.li that recorded.
    private struct ChildRecording {
        let folder: URL
        /// From its first line (recording) to the signal, in seconds.
        let recorded: Double
        /// From the signal to its end, in seconds; nil: still running 20 s
        /// later (then killed).
        let ended: Double?
        let reason: Process.TerminationReason
        let status: Int32
    }

    /// Another skil.li (`Skilli recorderchild`) records into `root`, `me`
    /// standing in for the microphone and `them` played as the other side,
    /// for `seconds`, then is sent `ending`: SIGKILL (a crash, a power cut)
    /// or SIGTERM (a quit, as `pkill`: through `NSApp.terminate`, as the
    /// menu's Quit or a logout). Nil when it never recorded.
    private func recordInAnotherSkilli(root: URL, me: URL, them: URL, seconds: Double, ending: Int32) async -> ChildRecording? {
        guard let executable = Bundle.main.executablePath else { return nil }
        let child = Process()
        child.executableURL = URL(fileURLWithPath: executable)
        child.arguments = ["recorderchild", root.path, me.path]
        let output = Pipe()
        child.standardOutput = output
        let exited = DispatchSemaphore(value: 0)
        child.terminationHandler = { _ in exited.signal() }
        guard (try? child.run()) != nil else { return nil }
        let play = playElsewhere(them)
        defer { play?.terminate() }
        // Its first line, 20 s at most: a child silent that long is
        // stopped, which closes its output and ends the read.
        let deadline = DispatchWorkItem { if child.isRunning { child.terminate() } }
        DispatchQueue.global().asyncAfter(deadline: .now() + 20, execute: deadline)
        let line = await Task.detached { () -> String in
            var data = Data()
            while !data.contains(UInt8(ascii: "\n")) {
                let chunk = output.fileHandleForReading.availableData
                if chunk.isEmpty { break }
                data.append(chunk)
            }
            return (String(data: data, encoding: .utf8) ?? "").split(separator: "\n").first.map(String.init) ?? ""
        }.value
        deadline.cancel()
        guard line.hasPrefix("recording ") else {
            child.terminate()
            return nil
        }
        let folder = URL(fileURLWithPath: String(line.dropFirst("recording ".count)).trimmingCharacters(in: .whitespacesAndNewlines))
        let began = ContinuousClock.now
        try? await Task.sleep(for: .seconds(seconds))
        let recorded = (ContinuousClock.now - began).milliseconds / 1000
        let signalled = ContinuousClock.now
        kill(child.processIdentifier, ending)
        let ended = await Task.detached { Self.signalled(exited, within: 20) }.value
        let took = (ContinuousClock.now - signalled).milliseconds / 1000
        if !ended {
            kill(child.processIdentifier, SIGKILL)
            child.waitUntilExit()
        }
        return ChildRecording(folder: folder, recorded: recorded, ended: ended ? took : nil, reason: child.terminationReason,
                              status: child.terminationStatus)
    }

    /// Whether `semaphore` is signalled within `seconds` (off the main
    /// thread).
    nonisolated private static func signalled(_ semaphore: DispatchSemaphore, within seconds: Double) -> Bool {
        semaphore.wait(timeout: .now() + seconds) == .success
    }

    /// skil.li quit while recording (docs/meeting-recorder.md, "Quit and
    /// sleep"): another skil.li records, then is sent SIGTERM, which quits
    /// it as skil.li quits; its recording is closed before it exits, both
    /// tracks whole and as long as what it recorded, `stopped` (not
    /// offered as unfinished). Then the next launch's pick-up: its
    /// transcript made without a card and without opening its window.
    private func recorderQuitClosesItWhole() async {
        let name = "Recorder: skil.li quit while recording (another skil.li sent SIGTERM) closes both tracks whole before it exits, left stopped, never offered as unfinished; the next launch makes its transcript without a card or a window"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return
        }
        let (me, them) = recorderCallClips("quit")
        let root = center.recordings.root
        center.openWindows.forEach { $0.close() }
        guard let child = await recordInAnotherSkilli(root: root, me: me, them: them, seconds: 10, ending: SIGTERM) else {
            record(name, false, "the other skil.li did not record", nil)
            return
        }
        let folder = child.folder
        let lengths = (me: trackLength(folder.appendingPathComponent(Speaker.me.file)), them: trackLength(folder.appendingPathComponent(Speaker.them.file)))
        let left = center.recordings.read(folder)
        // Whole: both tracks end at the same moment, as long as what was
        // recorded until the quit (a kill loses the last second or so).
        let whole = abs(lengths.me - lengths.them) < 0.05 && abs(lengths.me - child.recorded) < 0.5
            && abs((left?.seconds ?? 0) - max(lengths.me, lengths.them)) < 0.05
        let quitClean = child.reason == .exit && child.status == 0 && (child.ended ?? 99) < 5
        let stopped = left?.state == .stopped && left?.recorder == nil && left?.stopped != nil
        let notUnfinished = left.map { !$0.isUnfinished(isRunning: Recordings.isRunning) } ?? false

        // The next launch: what it finds, then its pick-up.
        let found = await RecorderCenter.left(in: root)
        let toMake = found.toTranscribe.filter { $0.0.standardizedFileURL == folder.standardizedFileURL }
        let offered = found.unfinished.contains { $0.0.standardizedFileURL == folder.standardizedFileURL }
        center.pickUp(RecorderCenter.Left(toTranscribe: toMake))
        let ring = await waitUntil(timeout: 3) { center.recorder.transcribing?.folder.standardizedFileURL == folder.standardizedFileURL } != nil
        let made = await waitUntil(timeout: 90) { center.recorder.transcribing == nil && center.recordings.read(folder)?.state != .stopped
            && center.recordings.read(folder)?.state != .transcribing } != nil
        // A moment for a window that would open.
        await pause(800)
        let after = center.recordings.read(folder)
        let lines = center.recordings.transcript(folder)?.lines.count ?? 0
        let noWindow = center.openWindows.isEmpty
        let noCard = !center.isCardVisible
        let haveCall = FileManager.default.fileExists(atPath: Self.recorderCalls.appendingPathComponent("en01/me.wav").path)
        let passed = quitClean && whole && stopped && notUnfinished && toMake.count == 1 && !offered && ring && made && after?.state == .done
            && (!haveCall || lines > 0) && noWindow && noCard
        record(name, passed,
               String(format: "recorded %.2f s, SIGTERM → exit %@ (%@ %d); tracks %.2f s / %.2f s, meeting.json %.2f s “%@”, its recorder %@, unfinished %@; found for the next launch's transcript %d, offered %@; transcribing at once %@, made %@ (“%@”, %d lines), window %@, card %@",
                      child.recorded, child.ended.map { String(format: "%.2f s", $0) } ?? "never", child.reason == .exit ? "exit" : "signal", child.status,
                      lengths.me, lengths.them, left?.seconds ?? 0, left?.state.rawValue ?? "nothing", left?.recorder == nil ? "none" : "kept",
                      "\(!notUnfinished)", toMake.count, "\(offered)", "\(ring)", "\(made)", after?.state.rawValue ?? "?", lines,
                      noWindow ? "none" : "opened", noCard ? "none" : "shown"),
               nil)
        // Not found again by a later check.
        if after?.state != .done, var rest = after {
            rest.state = .pending
            try? center.recordings.write(rest, to: folder)
        }
    }

    /// The Mac goes to sleep while recording (docs/meeting-recorder.md,
    /// "Quit and sleep"). macOS's two notifications are posted here: the
    /// test Mac cannot be woken without a person, so the sources go on
    /// through it. The recording pauses, both tracks at that moment;
    /// nothing resumes at wake; the card offers Resume ↩ (never taking the
    /// keys), the tracks in step across it. One the user paused stays
    /// paused and nothing shows at wake. ⌘↩ on the card stops.
    private func recorderSleepPausesUntilResumed() async {
        let name = "Recorder: the Mac's sleep pauses the recording (both tracks at that moment, in step after), nothing resumes at wake, the card offers Resume ↩ and Stop ⌘↩; one the user paused stays so, no card"
        guard let center = context.recorder() else {
            record(name, false, "no recorder", nil)
            return
        }
        let train = recorderScratch.appendingPathComponent("sleep-train.wav")
        _ = Self.clip(nil, seconds: 40, beeps: stride(from: 0.5, to: 40, by: 0.5).map { $0 }, to: train)
        center.recorder.standIn(microphone: train, alsoLeaveOut: [])
        center.showCard(title: "Sleep check")
        guard await waitUntil(timeout: 3, { center.isCardVisible && center.cardView.microphoneLine != "Starting…" }) != nil else {
            record(name, false, "no Record card", nil)
            return
        }
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        guard await waitUntil(timeout: 2, { center.recorder.phase == .recording }) != nil else {
            record(name, false, "not recording", nil)
            return
        }
        let began = ContinuousClock.now
        try? center.recorder.microphone.playStandIn(at: mach_absolute_time())
        let play = playElsewhere(train)
        defer { play?.terminate() }
        let workspace = NSWorkspace.shared.notificationCenter
        let view = center.cardView
        await pause(6000)

        // Asleep: paused at once, both tracks.
        workspace.post(name: NSWorkspace.willSleepNotification, object: NSWorkspace.shared)
        let paused = await waitUntil(timeout: 1) { center.recorder.phase == .paused } != nil
        await pause(2500)
        workspace.post(name: NSWorkspace.didWakeNotification, object: NSWorkspace.shared)
        let card = await waitUntil(timeout: 2) { center.isCardVisible && view.eyebrowText == "RECORDING PAUSED" } != nil
        let said = (title: view.name, line: view.detailText, button: view.buttonTitle, clock: view.clockText)
        if card { await captureRecordCard(center, as: "recorder-slept") }
        // Never resumed by itself.
        await pause(1000)
        let stayed = center.recorder.phase == .paused
        guard card else {
            center.control(.stop)
            _ = await waitUntil(timeout: 60) { center.recorder.phase == .idle && center.recorder.transcribing == nil }
            center.openWindows.forEach { $0.close() }
            record(name, false, "paused \(paused), no card at wake", nil)
            return
        }
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let resumed = await waitUntil(timeout: 2) { center.recorder.phase == .recording } != nil
        let cardGone = !center.isCardVisible
        await pause(6000)

        // Paused by the user, then asleep: it stays so, nothing at wake.
        center.control(.pause)
        workspace.post(name: NSWorkspace.willSleepNotification, object: NSWorkspace.shared)
        await pause(500)
        workspace.post(name: NSWorkspace.didWakeNotification, object: NSWorkspace.shared)
        let quietWake = await waitUntil(timeout: 1.5) { center.isCardVisible } == nil && center.recorder.phase == .paused
        center.control(.resume)
        await pause(3000)

        // Asleep again: ⌘↩ on the card stops and transcribes.
        workspace.post(name: NSWorkspace.willSleepNotification, object: NSWorkspace.shared)
        await pause(500)
        workspace.post(name: NSWorkspace.didWakeNotification, object: NSWorkspace.shared)
        var stoppedByCard = false
        if await waitUntil(timeout: 2, { center.isCardVisible && view.eyebrowText == "RECORDING PAUSED" }) != nil, await recordCardHasKeys(center, name) {
            await pressHolding(.maskCommand, keys: [CGKeyCode(kVK_Return)])
            stoppedByCard = await waitUntil(timeout: 3) { center.recorder.phase != .paused } != nil
        }
        if center.recorder.isRecording { center.control(.stop) }
        let wall = (ContinuousClock.now - began).milliseconds / 1000
        let done = await waitUntil(timeout: 60) { center.recorder.phase == .idle && center.recorder.transcribing == nil && !center.openWindows.isEmpty } != nil
        guard done, let folder = newestRecording(in: center.recordings.root), let record = center.recordings.read(folder) else {
            self.record(name, false, "paused \(paused), card \(card), resumed \(resumed), never done", nil)
            return
        }
        center.openWindows.forEach { $0.close() }
        let lengths = (me: trackLength(folder.appendingPathComponent(Speaker.me.file)), them: trackLength(folder.appendingPathComponent(Speaker.them.file)))
        let pairs = await Self.beepPairs(in: folder)
        let sleepAt = record.pauses.first?.at ?? 0
        let (before, after) = pairs.around(sleepAt)
        let step = pairs.step(at: sleepAt)
        let pausedFor = record.pauses.map(\.seconds).reduce(0, +)
        let expected = wall - pausedFor
        let conditions: [(String, Bool)] = [
            ("paused at once", paused), ("card at wake", card), ("never resumed by itself", stayed), ("Resume ↩", said.button == "Resume"),
            ("the sleep's time said", said.line.hasPrefix("The Mac went to sleep at ")), ("resumed", resumed), ("card gone", cardGone),
            ("no card for the user's pause", quietWake), ("⌘↩ stops", stoppedByCard), ("three pauses", record.pauses.count == 3),
            ("tracks alike", abs(lengths.me - lengths.them) < 0.05), ("recorded as long", abs(lengths.me - expected) < 0.5),
            ("step under 2 ms", step < 0.002), ("beeps around the sleep", before.count >= 4 && after.count >= 4)
        ]
        let failed = conditions.filter { !$0.1 }.map(\.0)
        self.record(name, failed.isEmpty,
                    (failed.isEmpty ? "" : "failed: \(failed.joined(separator: ", ")); ")
                    + String(format: "card “%@” “%@” at %@, button %@; asleep at %.2f s; pauses %@; tracks %.2f s / %.2f s (%.2f s recorded); offset %.1f ms before the sleep, %.1f ms after (step %.2f ms), %d of %d beeps paired",
                             said.title, said.line, said.clock, said.button, sleepAt,
                             record.pauses.map { String(format: "%.2f s at %.2f s", $0.seconds, $0.at) }.joined(separator: ", "),
                             lengths.me, lengths.them, expected, BeepPairs.mean(before) * 1000, BeepPairs.mean(after) * 1000, step * 1000,
                             pairs.paired.count, pairs.mine.count),
                    nil)
    }

    /// From a skillie or an agent: `skilli://record?title=` opens the card
    /// with its name (esc records nothing); `record/stop` with nothing
    /// recording says so; `record_meeting` waits for ↩ in the card,
    /// `recording_status` says it, a link's pause asks first (esc keeps it
    /// going), `pause_recording` and `stop_recording` ask in the card.
    private func recorderFromLinksAndTools() async {
        let name = "Recorder from skillies: skilli://record?title= opens the card named so (mid-typing, without taking the keys), record/stop with none says so, record_meeting waits for ↩, recording_status, a link's pause asks first, pause_recording and stop_recording ask in the card"
        guard let center = context.recorder(), let links = context.links else {
            record(name, false, "no recorder", nil)
            return
        }
        let popover = context.aiActions.popover
        let settings = context.tools.settings
        let mode = settings.mode
        // Ask Before Changes: opening the card runs, pausing and stopping ask.
        settings.mode = .auto
        defer { settings.mode = mode }
        let train = recorderScratch.appendingPathComponent("train.wav")
        center.recorder.standIn(microphone: train, alsoLeaveOut: [])
        // No key for a second: the card from a link takes the keyboard.
        await pause(1100)
        await links.openNow(SkilliLink.record(title: "From a link").url)
        let linkCard = await waitUntil(timeout: 3) { center.isCardVisible && center.cardView.name == "From a link" } != nil
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        let linkClosed = await waitUntil(timeout: 2) { !center.isCardVisible && center.recorder.phase == .idle } != nil
        // A link opening it just after a key (the user typing elsewhere):
        // shown, the keyboard left alone, so a Return on its way records nothing.
        await links.openNow(SkilliLink.record(title: "Typed over").url)
        let typedOverShown = await waitUntil(timeout: 3) { center.isCardVisible && center.cardView.name == "Typed over" } != nil
        await pause(400)
        let typedOverLeftKeys = typedOverShown && center.cardWindow?.isKeyWindow != true
        center.closeCardWithoutKeys()
        let typedOverClosed = await waitUntil(timeout: 3) { !center.isCardVisible && center.recorder.phase == .idle } != nil
        await links.openNow(SkilliLink.recording(.stop).url)
        let noneSaid = links.log.last == "no recording"
        if await waitUntil(timeout: 1, { popover.isVisible }) != nil { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        _ = await waitUntil(timeout: 8) { !popover.isVisible }

        // No key for a second: the card from a tool takes the keyboard.
        await pause(1100)
        let started = Task { await self.skilliCall("record_meeting", #"{"title":"From a tool"}"#) }
        let toolCard = await waitUntil(timeout: 5) { center.isCardVisible && center.cardView.name == "From a tool" } != nil
        guard await recordCardHasKeys(center, name) else {
            started.cancel()
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let (status, said) = await started.value
        let (_, now) = await skilliCall("recording_status")
        // A link pausing it asks first: esc keeps it going.
        let asked = Task { await links.openNow(SkilliLink.recording(.pause).url) }
        let linkAsks = await waitUntil(timeout: 10) {
            popover.isVisible && (popover.shownTitle + " " + popover.shownText).contains("Pause the recording")
        } != nil
        let pauseCard = "“\(popover.shownTitle)”: \(popover.shownText.prefix(120))"
        if linkAsks { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        if linkAsks { await asked.value } else { asked.cancel() }
        let keptGoing = center.recorder.phase == .recording
        let pausing = Task { await self.skilliCall("pause_recording") }
        let pauseAsks = await waitUntil(timeout: 3) { popover.isVisible } != nil
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let (pauseStatus, pauseSaid) = await pausing.value
        let pausedNow = center.recorder.phase == .paused
        let stopping = Task { await self.skilliCall("stop_recording") }
        _ = await waitUntil(timeout: 3) { popover.isVisible }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let (stopStatus, stopSaid) = await stopping.value
        _ = await waitUntil(timeout: 60) { center.recorder.transcribing == nil && !center.openWindows.isEmpty }
        center.openWindows.forEach { $0.close() }
        let passed = linkCard && linkClosed && typedOverLeftKeys && typedOverClosed && noneSaid && toolCard && status == 0 && said.contains("Recording “From a tool” started")
            && now.contains("Recording “From a tool”") && linkAsks && keptGoing && pauseAsks && pauseStatus == 0 && pausedNow
            && stopStatus == 0 && stopSaid.contains("Stopped “From a tool”")
        record(name, passed,
               "link card \(linkCard), closed \(linkClosed); opened mid-typing: keys left alone \(typedOverLeftKeys), closed \(typedOverClosed); none said \(noneSaid); tool card \(toolCard), exit \(status) “\(said)”; status “\(now)”; link asks \(linkAsks) (\(pauseCard)), kept going \(keptGoing); pause asks \(pauseAsks), exit \(pauseStatus) “\(pauseSaid)”, paused \(pausedNow); stop exit \(stopStatus) “\(stopSaid.prefix(80))”",
               nil)
    }

    // MARK: - The recorder's moment (phase 2)

    // MARK: - The recorder's pictures (phase 3)

    /// The webcam and the screen (docs/meeting-recorder.md, Phases): a
    /// stand-in camera (the test Mac has none) and a test window showing
    /// slides with known text at known times, recorded with a call whose
    /// microphone's beeps the window and the camera flash with.
    private func picturesChecks() async {
        guard let center = context.recorder() else {
            record("Recorder's pictures", false, "no recorder", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.recorderConsentShown, preferences.voiceLanguage, preferences.recorderWebcam, preferences.recorderScreen)
        let visible = (NSScreen.main ?? NSScreen.screens[0]).visibleFrame
        let slides = SlidesWindow(frame: NSRect(x: visible.minX + 20, y: visible.minY + 40, width: min(900, visible.width * 0.55), height: 560))
        let camera = StandInCamera()
        ScreenWindows.includesOwn = true
        center.recorder.standIn(camera: camera)
        defer {
            preferences.recorderConsentShown = saved.0
            preferences.voiceLanguage = saved.1
            preferences.recorderWebcam = saved.2
            preferences.recorderScreen = saved.3
            slides.window.orderOut(nil)
            ScreenWindows.includesOwn = false
            center.recorder.standIn(camera: nil)
        }
        preferences.recorderConsentShown = true
        preferences.voiceLanguage = "en-US"
        preferences.recorderWebcam = false
        preferences.recorderScreen = false
        slides.show(["skil.li", "Lumière · weekly review"])
        slides.window.orderFront(nil)
        await picturesRecordSlidesInStep(center, slides, camera)
        if !aborted { await picturesSayAWindowWithoutPictures(center, slides) }
        if !aborted { await picturesInAScratchChrome(center) }
    }

    /// A real click on a row of the Record card.
    private func clickCardRow(_ center: RecorderCenter, _ source: PictureSource) async -> Bool {
        guard let frame = center.cardView.screenFrame(of: source) else { return false }
        let screenHeight = NSScreen.screens.first?.frame.maxY ?? 0
        // On the row's title, left of its picture and of the ⌃⌄.
        let point = CGPoint(x: frame.minX + 40, y: screenHeight - frame.midY)
        let source = CGEventSource(stateID: .hidSystemState)
        for type in [CGEventType.mouseMoved, .leftMouseDown, .leftMouseUp] {
            CGEvent(mouseEventSource: source, mouseType: type, mouseCursorPosition: point, mouseButton: .left)?.post(tap: .cghidEventTap)
            await pause(60)
        }
        return true
    }

    /// The menu open in skil.li (a pop-up list): its item titled `title`
    /// pressed; else esc. Whether it was.
    private func pickInOpenMenu(_ title: String) async -> (picked: Bool, titles: [String]) {
        let items = Self.axElements(roles: [kAXMenuItemRole], under: AXUIElementCreateApplication(getpid())) { _ in true }
        let titles = items.compactMap { Self.axTitle($0) }.filter { !$0.isEmpty }
        if let item = items.first(where: { Self.axTitle($0) == title }) {
            AXUIElementPerformAction(item, kAXPressAction as CFString)
            await pause(300)
            return (true, titles)
        }
        let source = CGEventSource(stateID: .hidSystemState)
        for down in [true, false] {
            CGEvent(keyboardEventSource: source, virtualKey: CGKeyCode(kVK_Escape), keyDown: down)?.post(tap: .cghidEventTap)
        }
        await pause(300)
        return (false, titles)
    }

    /// The spec's phase-3 check: the Record card's webcam row clicked on
    /// (the stand-in camera), its screen row clicked (no meeting's window:
    /// the list opens) and the slides window picked, both pictures live
    /// (light and dark); ↩ records a 24 s call whose microphone beeps at
    /// known times, the window flashing white and the camera too at each
    /// beep, four slides at known times, a pause of 2 s; then
    /// `slides.json` holds each slide's text at its time within a second,
    /// `screen.mp4` and `webcam.mp4` keep the beeps' times across the
    /// pause, the files as long as the sound; the window plays both beside
    /// the lines, in step; Search Recordings finds a slide's words.
    private func picturesRecordSlidesInStep(_ center: RecorderCenter, _ slides: SlidesWindow, _ camera: StandInCamera) async {
        let name = "Recorder's pictures: the card turns the webcam and the screen on (a window picked from its list), both live; a 24 s call records them in step with the sound across a pause; slides.json holds the four slides at their times within a second; the window plays both beside the lines in step; the slides are found by search"
        // Beeps at the microphone's known times; a pause from 13 to 15 s.
        let beeps: [Double] = [1, 3, 5, 7, 9, 11, 17, 19, 21, 23]
        let shown: [(at: Double, lines: [String])] = [
            (2.0, ["Quarterly review", "Lumière, third quarter"]),
            (6.4, ["Budget 2027", "Revenue up 12 %"]),
            (10.2, ["Hiring plan", "Two designers in Q1"]),
            (18.6, ["Next steps", "Ship the recorder in November"]),
        ]
        let (pauseAt, resumeAt, end) = (13.0, 15.0, 24.5)
        let mic = recorderScratch.appendingPathComponent("pictures-me.wav")
        guard Self.clip(nil, seconds: end + 1, beeps: beeps, to: mic) else {
            record(name, false, "the microphone's stand-in could not be made", nil)
            return
        }
        center.recorder.standIn(microphone: mic, alsoLeaveOut: [])
        guard await typeInLauncher("rec slides call") else {
            record(name, false, "the launcher did not take “rec slides call”", nil)
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let view = center.cardView
        guard await waitUntil(timeout: 3, { center.isCardVisible && view.microphoneLine != "Starting…" }) != nil else {
            record(name, false, "no Record card", nil)
            return
        }
        guard await recordCardHasKeys(center, name) else { return }
        let offBefore = (view.webcamLine, view.screenLine)
        // The webcam's row: on, its picture live.
        _ = await clickCardRow(center, .webcam)
        let webcamOn = await waitUntil(timeout: 3) { view.webcamLine == "FaceTime HD Camera" && center.recorder.pictures.webcam.sink.latestPicture != nil } != nil
        // The screen's row: no meeting's window, its list opens; the slides picked.
        _ = await clickCardRow(center, .screen)
        await pause(700)
        let (picked, listed) = await pickInOpenMenu("skil.li · Slides")
        let screenOn = await waitUntil(timeout: 4) { view.screenLine == "skil.li · Slides" && center.recorder.pictures.screen.sink.latestPicture != nil } != nil
        await captureRecordCard(center, as: "recorder-pictures-card")
        guard webcamOn, screenOn, await recordCardHasKeys(center, name) else {
            record(name, false, "rows before “\(offBefore.0)” / “\(offBefore.1)”; webcam on \(webcamOn) “\(view.webcamLine)”, screen picked \(picked) from \(listed), on \(screenOn) “\(view.screenLine)”", nil)
            center.closeCardWithoutKeys()
            return
        }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        guard await waitUntil(timeout: 3, { center.recorder.phase == .recording }) != nil, let folder = center.recorder.folder else {
            record(name, false, "↩ did not record (\(center.recorder.phase))", nil)
            return
        }
        // The call's clock: the microphone's file from now, the flashes at
        // its beeps.
        let start = mach_absolute_time()
        let zero = HostClock.seconds(start)
        try? center.recorder.microphone.playStandIn(at: start)
        camera.flash(at: beeps.map { zero + $0 })
        var events: [(at: Double, run: () -> Void)] = beeps.map { beep in (beep, { slides.flash() }) }
        events += shown.map { slide in (slide.at, { slides.show(slide.lines) }) }
        events.append((pauseAt, { center.control(.pause) }))
        events.append((resumeAt, { center.control(.resume) }))
        // The corner's counter, four times a second: new pictures that are
        // no slide (as a call's video moving).
        events += stride(from: 0.125, to: end, by: 0.25).enumerated().map { index, at in (at, { slides.tick(index) }) }
        for event in events.sorted(by: { $0.at < $1.at }) {
            let wait = zero + event.at - HostClock.now
            if wait > 0 { try? await Task.sleep(for: .seconds(wait)) }
            event.run()
        }
        let rest = zero + end - HostClock.now
        if rest > 0 { try? await Task.sleep(for: .seconds(rest)) }
        center.control(.stop)
        _ = await waitUntil(timeout: 60) { center.recorder.phase == .idle && center.recorder.transcribing == nil && center.window(for: folder) != nil }
        guard let controller = center.window(for: folder) else {
            record(name, false, "no window after Stop (\(center.recorder.phase))", nil)
            return
        }
        // The sound's beeps are the recording's clock: where each landed.
        let urls = (me: folder.appendingPathComponent("me.m4a"), screen: folder.appendingPathComponent(RecorderPictures.screenFile),
                    webcam: folder.appendingPathComponent(RecorderPictures.webcamFile))
        let found = await Task.detached { Self.beeps(in: urls.me) }.value
        let screenFlashes = await PictureCheck.flashes(in: urls.screen)
        let webcamFlashes = await PictureCheck.flashes(in: urls.webcam)
        let screenOffsets = PictureCheck.offsets(found, screenFlashes)
        let webcamOffsets = PictureCheck.offsets(found, webcamFlashes)
        // Before the pause and after it: the same offset.
        let paused = found.count == beeps.count ? 6 : found.firstIndex { $0 > pauseAt - 0.5 } ?? found.count
        func spread(_ values: [Double]) -> Double { (values.max() ?? 0) - (values.min() ?? 0) }
        func mean(_ values: [Double]) -> Double { values.isEmpty ? 0 : values.reduce(0, +) / Double(values.count) }
        let screenStep = abs(mean(Array(screenOffsets.prefix(paused))) - mean(Array(screenOffsets.dropFirst(paused))))
        let webcamStep = abs(mean(Array(webcamOffsets.prefix(paused))) - mean(Array(webcamOffsets.dropFirst(paused))))
        // Each slide's time on the recording's clock, from the beep before
        // it in the same part (a beep lands at its own time).
        let kept = RecordingWindowController.slides(in: folder)
        var slideDetail: [String] = []
        var slidesRight = found.count == beeps.count
        for slide in shown {
            guard let index = beeps.lastIndex(where: { $0 <= slide.at && ($0 < pauseAt) == (slide.at < pauseAt) }), index < found.count else {
                slidesRight = false
                continue
            }
            let expected = found[index] + slide.at - beeps[index]
            let match = kept.first { candidate in
                slide.lines.allSatisfy { line in candidate.lines.contains { SlideLog.folded($0) == SlideLog.folded(line) } }
            }
            let off = match.map { $0.start - expected }
            if off.map({ abs($0) > 1 }) ?? true { slidesRight = false }
            slideDetail.append("“\(slide.lines[0])” \(off.map { String(format: "%+.2f s", $0) } ?? "missing")")
        }
        let lengths = (me: trackLength(urls.me), screen: await PictureCheck.length(urls.screen), webcam: await PictureCheck.length(urls.webcam))
        // The window: both pictures beside the lines, the slides among them;
        // played, the pictures keep up with the sound.
        await captureRecordingWindow(controller, as: "recorder-pictures-window")
        let pictures = controller.shownPictures
        let slideRows = controller.shownSlides.count
        controller.seek(to: 4, play: true)
        await pause(1500)
        let audio = controller.currentTime
        let behind = controller.pictureTimes.map { abs($0 - audio) }.max() ?? 99
        await captureRecordingWindow(controller, as: "recorder-pictures-window-playing")
        controller.togglePlay()
        controller.close()
        // Found by search: a slide's words.
        var foundBySlide = ""
        if let library = context.recordings() {
            library.reload()
            _ = await waitUntil(timeout: 3) { library.recordings.contains { $0.folder == folder.lastPathComponent } }
            foundBySlide = await library.searchWords("designers").first { $0.folder == folder.lastPathComponent }?.snippet ?? ""
        }
        let inStep = screenOffsets.count >= 8 && webcamOffsets.count >= 8 && spread(screenOffsets) <= 0.09 && abs(mean(screenOffsets)) <= 0.15
            && spread(webcamOffsets) <= 0.045 && abs(mean(webcamOffsets)) <= 0.05 && screenStep <= 0.07 && webcamStep <= 0.035
        let passed = offBefore == ("Off", "Off") && picked && inStep && slidesRight && abs(lengths.screen - lengths.me) <= 0.15
            && abs(lengths.webcam - lengths.me) <= 0.15 && pictures == 2 && slideRows >= 4 && behind <= 0.1 && foundBySlide.hasPrefix("On screen:")
        record(name, passed,
               String(format: "beeps found %d of %d; the screen's flashes %d, offsets %@ (spread %.0f ms, mean %.0f ms, across the pause %.0f ms); the webcam's %d, offsets %@ (spread %.0f ms, mean %.0f ms, across the pause %.0f ms); slides %@ (%d kept); lengths me %.2f s, screen %.2f s, webcam %.2f s; the window: %d pictures, %d slide rows, pictures %.0f ms from the sound while playing; search “designers”: “%@”",
                      found.count, beeps.count, screenFlashes.count, screenOffsets.map { String(format: "%.0f", $0 * 1000) }.joined(separator: ","),
                      spread(screenOffsets) * 1000, mean(screenOffsets) * 1000, screenStep * 1000, webcamFlashes.count,
                      webcamOffsets.map { String(format: "%.0f", $0 * 1000) }.joined(separator: ","), spread(webcamOffsets) * 1000,
                      mean(webcamOffsets) * 1000, webcamStep * 1000, slideDetail.joined(separator: ", "), kept.count, lengths.me, lengths.screen,
                      lengths.webcam, pictures, slideRows, behind * 1000, foundBySlide),
               nil)
    }

    /// The slides window minimized while it is recorded: within two
    /// seconds the menu bar's mark and the menu's line ("… is minimized");
    /// back, both gone. Covered whole by another window and still for 5 s:
    /// "stopped painting"; uncovered, gone. The red dot's menu turns the
    /// webcam off and on, and picks the screen Off.
    private func picturesSayAWindowWithoutPictures(_ center: RecorderCenter, _ slides: SlidesWindow) async {
        let name = "Recorder's pictures: a recorded window minimized is said in the menu bar (an orange mark, its line in the menu) and the saying goes when it is back; covered whole and still for 5 s, “stopped painting”; the red dot's menu turns the webcam and the screen off"
        let silence = recorderScratch.appendingPathComponent("silence.wav")
        _ = Self.clip(nil, seconds: 120, beeps: [], to: silence)
        center.recorder.standIn(microphone: silence, alsoLeaveOut: [])
        context.preferences.recorderWebcam = true
        context.preferences.recorderScreen = true
        guard let window = ScreenWindows.window(CGWindowID(slides.window.windowNumber)) else {
            record(name, false, "the slides window is not in the window list", nil)
            return
        }
        // ⌘R's way: the sources from Settings, the screen's window given.
        center.recordForTest(screen: window)
        guard await waitUntil(timeout: 4, { center.recorder.isRecording && center.recorder.pictures.screen.window != nil }) != nil,
              let folder = center.recorder.folder else {
            record(name, false, "no recording with the screen (\(center.recorder.phase))", nil)
            return
        }
        await pause(1500)
        let before = center.menuBar.button?.accessibilityLabel() ?? ""
        slides.window.miniaturize(nil)
        let minimized = await waitUntil(timeout: 4) { center.recorder.pictures.screen.problem == .minimized } != nil
        await pause(400)
        let said = center.menuBar.button?.accessibilityLabel() ?? ""
        if let button = center.menuBar.button { await captureStatusItem(button, "recorder-pictures-menubar") }
        let menu = await openRecorderMenu(center, capture: "recorder-pictures-menu.png")
        slides.window.deminiaturize(nil)
        let back = await waitUntil(timeout: 5) { center.recorder.pictures.screen.problem == nil } != nil
        // Covered whole by another window, the slide still.
        let cover = NSWindow(contentRect: slides.window.frame.insetBy(dx: -40, dy: -40), styleMask: [.borderless], backing: .buffered, defer: false)
        cover.backgroundColor = .windowBackgroundColor
        cover.isOpaque = true
        cover.isReleasedWhenClosed = false
        cover.orderFront(nil)
        let covered = await waitUntil(timeout: 9) { center.recorder.pictures.screen.problem == .stoppedPainting } != nil
        let coveredMenu = center.menuBar.menuTitles.first { $0.hasPrefix("Screen ·") } ?? ""
        cover.orderOut(nil)
        let uncovered = await waitUntil(timeout: 4) { center.recorder.pictures.screen.problem == nil } != nil
        // The red dot's menu: the webcam off, the screen off.
        _ = await openRecorderMenu(center, capture: "recorder-pictures-menu-webcam.png", pick: "Webcam · ", pickPrefix: true)
        let webcamOff = await waitUntil(timeout: 3) { !center.recorder.sources.webcam && !center.recorder.pictures.webcam.isOn } != nil
        await center.recorder.setScreen(nil)
        let screenOff = !center.recorder.sources.screen && center.recorder.pictures.screen.window == nil
        await momentStop(center)
        center.openWindows.forEach { $0.close() }
        let files = [RecorderPictures.screenFile, RecorderPictures.webcamFile].filter { FileManager.default.fileExists(atPath: folder.appendingPathComponent($0).path) }
        let screenLine = menu.first { $0.hasPrefix("Screen ·") } ?? ""
        record(name, !before.contains("no picture") && minimized && said.contains("the screen gives no picture") && screenLine.contains("is minimized") && back
               && covered && coveredMenu.contains("stopped painting") && uncovered && webcamOff && screenOff && files.count == 2,
               "before “\(before)”; minimized: said \(minimized), label “\(said)”, menu “\(screenLine)”; back \(back); covered: \(covered) “\(coveredMenu)”, uncovered \(uncovered); webcam off \(webcamOff), screen off \(screenOff); files \(files)",
               nil)
    }

    /// A scratch Chrome showing a meeting's page: its window recorded,
    /// covered whole it stops painting (Measured) and is said so. With
    /// skil.li allowed to script Chrome, the meeting's tab (behind another
    /// one) comes forward without a reload; without, the card's line says
    /// what to do (macOS's question needs a person: never answered here).
    private func picturesInAScratchChrome(_ center: RecorderCenter) async {
        let name = "Recorder's pictures: a scratch Chrome's meeting window recorded; covered whole, Chrome stops painting and it is said; the meeting's tab brought forward without a reload when skil.li may script Chrome"
        guard let chromeURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: "com.google.Chrome") else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no Google Chrome on this Mac", latencyMs: nil))
            return
        }
        let profile = recorderScratch.appendingPathComponent("chrome-pictures", isDirectory: true)
        /// The meeting page's loads (a reload would leave the call).
        final class Loads: @unchecked Sendable {
            private let lock = NSLock()
            private var value = 0
            var count: Int { lock.withLock { value } }
            func add() { lock.withLock { value += 1 } }
        }
        let loads = Loads()
        let page = """
            <!doctype html><meta charset="utf-8"><title>Weekly design review</title>
            <body style="font:28px -apple-system;padding:40px;background:#111;color:#eee"><h1>Weekly design review</h1><div id="c">0</div>
            <script>let n = 0; (function f() { document.getElementById('c').textContent = ++n; requestAnimationFrame(f) })()</script>
            """
        guard let server = LoopbackServer(handler: { request in
            if request.target.hasPrefix("/meet/") { loads.add() }
            return .html(page)
        }), let port = await server.port() else {
            record(name, false, "the meeting's page could not be served", nil)
            return
        }
        defer { server.stop() }
        let meeting = URL(string: "http://127.0.0.1:\(port)/meet/lumiere-weekly")!
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.createsNewApplicationInstance = true
        configuration.activates = false
        // The meeting's tab first, another tab in front of it.
        configuration.arguments = ["--user-data-dir=\(profile.path)", "--no-first-run", "--no-default-browser-check", meeting.absoluteString,
                                   "http://127.0.0.1:\(port)/other"]
        let chrome = try? await NSWorkspace.shared.openApplication(at: chromeURL, configuration: configuration)
        let pid = chrome?.processIdentifier ?? 0
        defer {
            chrome?.forceTerminate()
            try? FileManager.default.removeItem(at: profile)
        }
        _ = await waitUntil(timeout: 15) { MicrophoneUse.frontWindow(of: pid) != nil && loads.count > 0 }
        await pause(1500)
        let app = MicrophoneApp(bundleID: "com.google.Chrome", name: chrome?.localizedName ?? "Google Chrome", pid: pid)
        // The tab: only when macOS already lets skil.li script Chrome.
        let automation = AutomationAccess.state(of: "com.google.Chrome")
        var tabDetail = "not tried: skil.li may not script Chrome on this Mac (\(automation)); macOS asks a person once"
        var tabRight = true
        let loadsBefore = loads.count
        if automation == .granted {
            let plan = await MeetingTabSelect.plan(for: meeting, in: app)
            if case .tab(let tab, let id) = plan {
                let selected = MeetingTabSelect.select(tab, in: app.bundleID)
                await pause(1200)
                tabRight = selected && id != nil && loads.count == loadsBefore && NSWorkspace.shared.frontmostApplication?.processIdentifier != pid
                tabDetail = "tab \(tab.index) of window \(tab.window) selected \(selected), its window \(id.map(String.init) ?? "none"), reloads \(loads.count - loadsBefore), Chrome brought forward \(NSWorkspace.shared.frontmostApplication?.processIdentifier == pid)"
            } else {
                tabRight = false
                tabDetail = "plan \(plan)"
            }
        }
        guard let id = MicrophoneUse.frontWindow(of: pid), let window = ScreenWindows.window(id),
              let frame = (CGWindowListCopyWindowInfo([.optionIncludingWindow], id) as? [[String: Any]])?.first?[kCGWindowBounds as String] as? NSDictionary,
              let bounds = CGRect(dictionaryRepresentation: frame) else {
            record(name, false, "no Chrome window (\(tabDetail))", nil)
            return
        }
        let silence = recorderScratch.appendingPathComponent("silence.wav")
        center.recorder.standIn(microphone: silence, alsoLeaveOut: [])
        context.preferences.recorderWebcam = false
        context.preferences.recorderScreen = true
        center.recordForTest(screen: window)
        guard await waitUntil(timeout: 4, { center.recorder.isRecording && center.recorder.pictures.screen.window?.id == id }) != nil else {
            record(name, false, "Chrome's window not recorded (\(center.recorder.phase))", nil)
            return
        }
        await pause(2000)
        let painting = center.recorder.pictures.screen.problem == nil
        // Covered whole (AppKit's frame: from the bottom of the main screen).
        let screenHeight = NSScreen.screens.first?.frame.maxY ?? 0
        let cover = NSWindow(contentRect: NSRect(x: bounds.minX - 30, y: screenHeight - bounds.maxY - 30, width: bounds.width + 60, height: bounds.height + 60),
                             styleMask: [.borderless], backing: .buffered, defer: false)
        cover.backgroundColor = .windowBackgroundColor
        cover.isReleasedWhenClosed = false
        cover.orderFront(nil)
        let stopped = await waitUntil(timeout: 10) { center.recorder.pictures.screen.problem == .stoppedPainting } != nil
        cover.orderOut(nil)
        let again = await waitUntil(timeout: 4) { center.recorder.pictures.screen.problem == nil } != nil
        await momentStop(center)
        center.openWindows.forEach { $0.close() }
        record(name, painting && stopped && again && tabRight,
               "Chrome \(pid), window \(id) “\(window.name)”; painting \(painting); covered: stopped painting said \(stopped); uncovered \(again); \(tabDetail)",
               nil)
    }

    /// The recorder's moment (docs/meeting-recorder-views.md, phase 2), on
    /// stand-in events and, but for the browser call, stand-in apps on the
    /// microphone: never the user's calendars or calls. A silent file stands
    /// in for the microphone (the test Mac has none); the Mac's sound is the
    /// real tap. The call's end comes sooner (1 s, 3 s).
    private func momentChecks() async {
        guard let center = context.recorder(), let book = context.launcher.calendar else {
            record("Recorder's moment", false, "no recorder or no calendar", nil)
            return
        }
        let preferences = context.preferences
        let saved = (preferences.recorderConsentShown, preferences.recorderCardHintShown, preferences.voiceLanguage, preferences.recorderMeetingCard,
                     preferences.recorderRetention, preferences.recorderMicrophone, preferences.recorderMacSound, preferences.agendaMenuBar,
                     preferences.agendaAutoJoin, preferences.agendaAlerts)
        let openURL = book.openURL
        defer {
            preferences.recorderConsentShown = saved.0
            preferences.recorderCardHintShown = saved.1
            preferences.voiceLanguage = saved.2
            preferences.recorderMeetingCard = saved.3
            preferences.recorderRetention = saved.4
            preferences.recorderMicrophone = saved.5
            preferences.recorderMacSound = saved.6
            preferences.agendaMenuBar = saved.7
            preferences.agendaAutoJoin = saved.8
            preferences.agendaAlerts = saved.9
            book.testEvents = nil
            book.openURL = openURL
            center.standInMicrophone(nil)
            context.meetingWatch.microphone.standIn = nil
            context.meetingWatch.resetForTest()
            context.meetingWatch.refresh()
            context.meetingCard.dismiss()
        }
        // The calls are English; the test Mac types French.
        preferences.voiceLanguage = "en-US"
        preferences.agendaAlerts = []
        preferences.agendaAutoJoin = .off
        preferences.recorderMeetingCard = true
        let silence = recorderScratch.appendingPathComponent("silence.wav")
        _ = Self.clip(nil, seconds: 120, beeps: [], to: silence)
        center.recorder.standIn(microphone: silence, alsoLeaveOut: [])
        center.watchTimings = (appGrace: 1, quietFor: 3)
        // Joining opens nothing: the links are kept.
        book.openURL = { [weak self] url in self?.momentOpened.append(url) }
        context.meetingWatch.microphone.standIn = .idle
        await momentCasesTold(center, book)
        if !aborted { await momentCardRecordsAndJoins(center, book) }
        if !aborted { await momentCardKeyIsTheUsersOnly(center, book) }
        if !aborted { await momentInPersonRecordsTheRoom(center, book) }
        if !aborted { await momentLauncherRowRecords(center, book) }
        if !aborted { await momentRecordDuringClosing(center, book) }
        if !aborted { await momentMenuBarRecords(center, book) }
        if !aborted { await momentRedDotSwitchesSources(center, book) }
        if !aborted { await momentCallEndOffersStop(center, book) }
        if !aborted { await momentBrowserCallsMicrophone(center, book) }
        if !aborted { await momentSearchRecordings(center) }
        if !aborted { await momentRecorderPane(center) }
        if !aborted { await momentRetentionAndFolder(center) }
    }

    /// The links a Join would have opened.
    private var momentOpened: [URL] = []

    /// A stand-in meeting: `seconds` from now (before: negative), a Meet
    /// link or `location`, two invented people.
    private func momentEvent(_ id: String, _ title: String, in seconds: TimeInterval, link: Bool, location: String = "",
                             minutes: Double = 30) -> AgendaEvent {
        let start = Date.now.addingTimeInterval(seconds)
        return AgendaEvent(id: id, title: title, start: start, end: start.addingTimeInterval(minutes * 60), calendar: "Work", location: location,
                           notes: link ? "https://meet.google.com/abc-defg-hij" : "",
                           attendees: [.init(name: "Margot Martin", email: nil), .init(name: "Camille", email: nil)])
    }

    /// The stand-in apps on the microphone (no real pids: none runs).
    private static let standInDiscord = MicrophoneApp(bundleID: "com.hnc.Discord", name: "Discord", pid: 999_901)
    private static let standInGather = MicrophoneApp(bundleID: "com.example.gather", name: "Gather", pid: 999_902)

    /// Stops the recording on now, waits for its transcript and its
    /// window, closes the window; its folder and record.
    @discardableResult
    private func momentStop(_ center: RecorderCenter) async -> (URL, MeetingRecord)? {
        guard let folder = center.recorder.folder else { return nil }
        center.control(.stop)
        _ = await waitUntil(timeout: 60) { center.recorder.phase == .idle && center.recorder.transcribing == nil && center.window(for: folder) != nil }
        let record = center.recordings.read(folder)
        return record.map { (folder, $0) }
    }

    /// A recording stopped some other way (the call's end card): settled
    /// once its transcript's window opened, then closed (else it opens
    /// later, over the next check's keys).
    private func momentSettled(_ center: RecorderCenter, _ folder: URL?) async {
        guard let folder else { return }
        _ = await waitUntil(timeout: 60) { center.recorder.phase == .idle && center.window(for: folder) != nil }
        center.openWindows.forEach { $0.close() }
    }

    /// The meeting card, shown and given a second (⌘R is the user's then),
    /// light and dark captured.
    private func momentShowCard(_ event: AgendaEvent, capture name: String? = nil) async {
        let card = context.meetingCard
        card.dismiss()
        // Not typing: the card takes the keyboard.
        await pause(1100)
        card.show(event, dark: false)
        _ = await waitUntil(timeout: 2) { card.isVisible && card.isKey }
        if let name, let directory = context.snapshotDirectory, let panel = card.window {
            let (panelAppearance, testAppearance) = (panel.appearance, window.appearance)
            for (suffix, appearance) in GlassCheck.appearances {
                panel.appearance = appearance
                window.appearance = appearance
                await pause(700)
                if let image = await GlassCheck.screenshot(around: panel, padding: -Theme.glassMargin + 16),
                   let png = NSBitmapImageRep(cgImage: image).representation(using: .png, properties: [:]) {
                    try? png.write(to: directory.appendingPathComponent("\(name)-\(suffix).png"))
                }
            }
            panel.appearance = panelAppearance
            window.appearance = testAppearance
        }
        await pause(1100)
    }

    /// The five cases, as the meeting card, the Record card and the
    /// recorder read them (the event, the apps on the microphone): no
    /// model. A call with no event is named by its app.
    private func momentCasesTold(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: the five cases told apart by the event and the microphone's apps (a call link, in an app, in person, a call with no event, nothing to go on); the card's label; a call with no event named by its app"
        let link = momentEvent("st-moment-link", "Weekly design review", in: 60, link: true)
        let gather = momentEvent("st-moment-app", "Team standup", in: 0, link: false, location: "Gather · Lumière HQ")
        let room = momentEvent("st-moment-room", "Budget review", in: 60, link: false, location: "Salle Lumière, 3e étage")
        let online = momentEvent("st-moment-online", "Catch-up", in: 60, link: false, location: "Online")
        let cases: [(String, AgendaEvent?, MicrophoneHolders, MeetingMoment.Kind, MeetingMoment.Sources, String)] = [
            ("call link", link, .none, .callLink, .both, "Record"),
            ("in an app", gather, MicrophoneHolders(apps: [Self.standInGather]), .inApp, .both, "Record"),
            ("in person", room, .none, .inPerson, MeetingMoment.Sources(microphone: true, macSound: false), "Record (in person)"),
            ("no event", nil, MicrophoneHolders(apps: [Self.standInDiscord]), .callWithoutEvent, .both, ""),
            ("nothing", online, MicrophoneHolders(unnamed: 1), .nothing, .both, "Record")
        ]
        var wrong: [String] = []
        var said: [String] = []
        for (label, event, holders, kind, sources, cardLabel) in cases {
            center.standInMicrophone(holders)
            let reading = center.moment(for: event)
            let offer = event.flatMap { context.meetingCard.recordOffer($0) }
            said.append("\(label): \(reading.kind.rawValue)\(reading.app.map { " (\($0.name))" } ?? "")\(offer.map { ", “\($0.label)”" } ?? "")")
            if reading.kind != kind || reading.sources != sources || (event != nil && offer?.label != cardLabel) { wrong.append(label) }
        }
        // The current meeting comes from the calendar: on now first.
        book.testEvents = [link, gather]
        let current = center.currentMeeting()?.id
        // A call with no event: the Record card is named by its app.
        book.testEvents = []
        center.standInMicrophone(MicrophoneHolders(apps: [Self.standInDiscord]))
        center.showCard(title: nil)
        let view = center.cardView
        let shown = await waitUntil(timeout: 3) { center.isCardVisible && view.macLine != "Starting…" } != nil
        let named = view.name.hasPrefix("Discord call ")
        center.closeCardWithoutKeys()
        _ = await waitUntil(timeout: 2) { !center.isCardVisible && center.recorder.phase == .idle }
        center.standInMicrophone(.none)
        record(name, wrong.isEmpty && current == gather.id && shown && named,
               "\(said.joined(separator: "; ")); wrong: \(wrong.isEmpty ? "none" : wrong.joined(separator: ", ")); current meeting \(current ?? "none") (on now first); no event, card named “\(view.name)”",
               nil)
    }

    /// The meeting card's Record ⌘R, first time: its line (what ⌘R does,
    /// the others must agree), said once; ⌘R records at once, then joins;
    /// the recording is named and peopled by the event.
    private func momentCardRecordsAndJoins(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: the meeting card's Record ⌘R, the line the first time only; ⌘R records at once, then joins; the recording takes the event's title and attendees"
        let preferences = context.preferences
        preferences.recorderConsentShown = false
        preferences.recorderCardHintShown = false
        center.standInMicrophone(.none)
        momentOpened = []
        let event = momentEvent("st-moment-card", "Weekly design review", in: 45, link: true)
        book.testEvents = [event]
        let card = context.meetingCard
        await momentShowCard(event, capture: "recorder-meeting-card-first")
        let firstLabel = card.shownRecord
        let line = card.shownRecordLine ?? ""
        let hintSaved = preferences.recorderCardHintShown
        let before = Date.now
        await pressKey("r", flags: .maskCommand)
        let recording = await waitUntil(timeout: 4) { center.recorder.isRecording } != nil
        let joined = await waitUntil(timeout: 3) { self.momentOpened.contains { $0.absoluteString.contains("meet.google.com") } } != nil
        let made = center.recorder.record
        let sources = center.recorder.sources
        await pause(2000)
        let stopped = await momentStop(center)
        let kept = stopped?.1
        // The next card: the keycap alone.
        await momentShowCard(momentEvent("st-moment-card-2", "Weekly design review", in: 45, link: true), capture: "recorder-meeting-card")
        let quiet = card.shownRecord == "Record" && card.shownRecordLine == nil
        card.dismiss()
        let passed = firstLabel == "Record" && line.contains("⌘R records this call") && line.contains("must agree") && hintSaved && recording && joined
            && made?.title == "Weekly design review" && made?.attendees == ["Margot Martin", "Camille"] && made?.kind == .callLink
            && made?.event?.id == event.id && sources == .both && preferences.recorderConsentShown && kept?.state == .done && quiet
        record(name, passed,
               "first card “\(firstLabel ?? "none")”, line “\(line)”, said once: \(hintSaved); ⌘R recorded \(recording) in \(String(format: "%.1f", Date.now.timeIntervalSince(before))) s, joined after: \(joined); record “\(made?.title ?? "")” \(made?.kind?.rawValue ?? "?") attendees \(made?.attendees ?? []), sources mic \(sources.microphone) mac \(sources.macSound); consent kept \(preferences.recorderConsentShown); stopped: \(kept?.state.rawValue ?? "?"); next card quiet: \(quiet)",
               nil)
    }

    /// ⌘R records only when the card is the user's: never while the user
    /// was typing as it came (it leaves the keyboard alone), never in its
    /// first second, never when Settings turned it off or one records.
    private func momentCardKeyIsTheUsersOnly(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: ⌘R never records when the card is not the user's (typing as it came, its first second, turned off in Settings, a recording on)"
        let card = context.meetingCard
        let event = momentEvent("st-moment-typing", "Standup", in: 45, link: true)
        book.testEvents = [event]
        center.standInMicrophone(.none)
        // Typing in the test window as it comes: the card leaves the keys alone.
        card.dismiss()
        _ = await focusTestWindow()
        window.makeFirstResponder(textView)
        textView.string = ""
        await pressKey("a")
        await pause(150)
        await pressKey("a")
        card.show(event, dark: false)
        let leftAlone = card.isVisible && !card.isKey
        await pause(1200)
        await pressKey("r", flags: .maskCommand)
        await pause(1200)
        let notWhileTyping = !center.recorder.isRecording
        card.dismiss()
        // Its first second: nothing; after it: records.
        await pause(1100)
        card.show(event, dark: false)
        _ = await waitUntil(timeout: 2) { card.isKey }
        await pause(300)
        await pressKey("r", flags: .maskCommand)
        await pause(900)
        let notTooSoon = !center.recorder.isRecording && card.isVisible
        await pause(400)
        await pressKey("r", flags: .maskCommand)
        let afterASecond = await waitUntil(timeout: 4) { center.recorder.isRecording } != nil
        // A recording on: no Record on the next card.
        card.show(momentEvent("st-moment-next", "Standup", in: 45, link: true), dark: false)
        let noSecond = card.shownRecord == nil
        card.dismiss()
        await momentStop(center)
        // Turned off: no keycap, ⌘R is not the card's.
        context.preferences.recorderMeetingCard = false
        await momentShowCard(event)
        let offShown = card.shownRecord
        await pressKey("r", flags: .maskCommand)
        await pause(1200)
        let offNothing = !center.recorder.isRecording
        card.dismiss()
        context.preferences.recorderMeetingCard = true
        center.openWindows.forEach { $0.close() }
        record(name, leftAlone && notWhileTyping && notTooSoon && afterASecond && noSecond && offShown == nil && offNothing,
               "typing: keys left alone \(leftAlone), ⌘R recorded nothing \(notWhileTyping); first second: nothing \(notTooSoon), after it: recorded \(afterASecond); while recording, Record offered again: \(!noSecond); off: keycap “\(offShown ?? "none")”, ⌘R nothing \(offNothing)",
               nil)
    }

    /// In person: "Record (in person)", the microphone only (no tap), one
    /// lane named Room, the attendees in the window's line.
    private func momentInPersonRecordsTheRoom(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: in person, “Record (in person) ⌘R” records the microphone only; the window shows one lane, Room, and who was there"
        let event = momentEvent("st-moment-room-rec", "Budget review", in: 30, link: false, location: "Salle Lumière, 3e étage")
        book.testEvents = [event]
        center.standInMicrophone(.none)
        momentOpened = []
        let card = context.meetingCard
        await momentShowCard(event, capture: "recorder-meeting-card-in-person")
        let label = card.shownRecord
        await pressKey("r", flags: .maskCommand)
        let recording = await waitUntil(timeout: 4) { center.recorder.isRecording } != nil
        let sources = center.recorder.sources
        await pause(2500)
        let stopped = await momentStop(center)
        let made = stopped?.1
        let controller = stopped.flatMap { center.window(for: $0.0) }
        let lanes = controller?.shownLanes ?? []
        let about = controller?.shownAbout ?? ""
        if let controller { await captureRecordingWindow(controller, as: "recorder-window-in-person") }
        center.openWindows.forEach { $0.close() }
        let passed = label == "Record (in person)" && recording && sources == MeetingMoment.Sources(microphone: true, macSound: false)
            && made?.kind == .inPerson && made?.unused == [.them] && made?.speakers["me"] == "Room" && made?.place == "Salle Lumière, 3e étage"
            && lanes == ["Room"] && about.contains("with Margot and Camille") && momentOpened.isEmpty
        record(name, passed,
               "card “\(label ?? "none")”; recording \(recording), mic \(sources.microphone), Mac's sound \(sources.macSound); record \(made?.kind?.rawValue ?? "?"), unused \(made?.unused?.map(\.rawValue) ?? []), me “\(made?.speakers["me"] ?? "")”, place “\(made?.place ?? "")”; window lanes \(lanes), “\(about)”; nothing joined \(momentOpened.isEmpty)",
               nil)
    }

    /// The launcher's meeting row: ⌘K lists Record ⌘R; the first time
    /// (nobody told yet), ⌘R opens the Record card, the meeting's, "Record
    /// and Join"; then ⌘R records at once and joins.
    private func momentLauncherRowRecords(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: the launcher's meeting row, ⌘K lists Record ⌘R; the first time ⌘R opens the meeting's Record card (Record and Join, its attendees), then ⌘R records at once and joins"
        let launcher = context.launcher
        let preferences = context.preferences
        let event = momentEvent("st-moment-row", "Weekly design review", in: 90, link: true)
        book.testEvents = [event]
        center.standInMicrophone(.none)
        momentOpened = []
        preferences.recorderConsentShown = false
        _ = await focusTestWindow()
        guard await openLauncher() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        let row = await waitUntil(timeout: 2) { if case .event? = launcher.results.first { true } else { false } } != nil
        await pressKey("k", flags: .maskCommand)
        _ = await waitUntil(timeout: 1) { !launcher.shownActions.isEmpty }
        let listed = launcher.shownActions.contains { $0.title == "Record" && $0.key == "⌘R" }
        await captureLauncherBothWays(as: "recorder-launcher-row-actions")
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await pause(200)
        await pressKey("r", flags: .maskCommand)
        let view = center.cardView
        let firstCard = await waitUntil(timeout: 3) { center.isCardVisible && view.macLine != "Starting…" } != nil
        let button = view.buttonTitle
        let people = view.detailText
        await captureRecordCard(center, as: "recorder-card-meeting")
        let firstNothing = !center.recorder.isRecording
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await waitUntil(timeout: 2) { !center.isCardVisible && center.recorder.phase == .idle }
        // Told once: at once from then on.
        preferences.recorderConsentShown = true
        _ = await focusTestWindow()
        guard await openLauncher() else {
            record(name, false, "the launcher did not open again", nil)
            return
        }
        _ = await waitUntil(timeout: 2) { if case .event? = launcher.results.first { true } else { false } }
        await pressKey("r", flags: .maskCommand)
        let recording = await waitUntil(timeout: 4) { center.recorder.isRecording } != nil
        let joined = await waitUntil(timeout: 3) { self.momentOpened.contains { $0.absoluteString.contains("meet.google.com") } } != nil
        let title = center.recorder.title
        await pause(1000)
        await momentStop(center)
        center.openWindows.forEach { $0.close() }
        // A meeting in two hours: no Record on its row.
        book.testEvents = [momentEvent("st-moment-later", "Quarterly planning", in: 7200, link: true)]
        let laterLabel = launcher.recordLabel(momentEvent("st-moment-later", "Quarterly planning", in: 7200, link: true))
        record(name, row && listed && firstCard && button == "Record and Join" && people == "With Margot and Camille" && firstNothing && recording && joined
               && title == "Weekly design review" && laterLabel == nil,
               "row first \(row), ⌘K lists Record ⌘R \(listed); first ⌘R: card \(firstCard) “\(button)”, “\(people)”, nothing recorded \(firstNothing); then ⌘R recorded \(recording) “\(title)”, joined \(joined); a meeting in 2 h offers Record: \(laterLabel ?? "no")",
               nil)
    }

    /// ⌘R pressed while the last recording still closes its files (here 2
    /// s, the self-test's own delay): never dropped, it records once they
    /// are closed; the menu bar's dot never goes; both recordings whole.
    private func momentRecordDuringClosing(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: ⌘R pressed while the last recording closes its files records once they are closed (never dropped), the menu bar's dot stays throughout, both recordings whole"
        let event = momentEvent("st-moment-closing", "Weekly design review", in: 30, link: true)
        book.testEvents = [event]
        center.standInMicrophone(.none)
        context.preferences.recorderConsentShown = true
        _ = await focusTestWindow()
        guard await openLauncher() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        await pressKey("r", flags: .maskCommand)
        guard await waitUntil(timeout: 4, { center.recorder.isRecording }) != nil, let first = center.recorder.folder else {
            record(name, false, "the first recording did not start", nil)
            return
        }
        await pause(2500)
        center.recorder.closingDelay = .seconds(2)
        defer { center.recorder.closingDelay = .zero }
        _ = await focusTestWindow()
        guard await openLauncher() else {
            record(name, false, "the launcher did not open again", nil)
            return
        }
        center.control(.stop)
        let closing = await waitUntil(timeout: 1) { center.recorder.phase == .stopping } != nil
        await pressKey("r", flags: .maskCommand)
        let pressedWhileClosing = center.recorder.phase == .stopping
        var dotGone = false
        let second = await waitUntil(timeout: 8) {
            if center.menuBar.shown == nil { dotGone = true }
            return center.recorder.isRecording && center.recorder.folder != first
        } != nil
        let next = center.recorder.folder
        let titleAfter = center.recorder.title
        center.recorder.closingDelay = .zero
        await pause(2500)
        await momentStop(center)
        _ = await waitUntil(timeout: 60) { center.recorder.transcribing == nil }
        center.openWindows.forEach { $0.close() }
        // Whole: transcribed, both tracks as long as it was recorded.
        func whole(_ folder: URL?) -> (Bool, String) {
            guard let folder, let made = center.recordings.read(folder) else { return (false, "missing") }
            let me = trackLength(folder.appendingPathComponent(Speaker.me.file))
            let them = trackLength(folder.appendingPathComponent(Speaker.them.file))
            let ok = made.state == .done && made.seconds > 1.5 && abs(me - them) < 0.2 && abs(me - made.seconds) < 0.3
            return (ok, "\(made.state.rawValue), \(String(format: "%.2f", made.seconds)) s, me \(String(format: "%.2f", me)), them \(String(format: "%.2f", them))")
        }
        let (firstWhole, firstSaid) = whole(first)
        let (nextWhole, nextSaid) = whole(next)
        record(name, closing && pressedWhileClosing && second && next != first && !dotGone && firstWhole && nextWhole && titleAfter == "Weekly design review",
               "closing \(closing), ⌘R while closing \(pressedWhileClosing); the second recorded \(second) “\(titleAfter)”; dot gone meanwhile: \(dotGone); first: \(firstSaid); second: \(nextSaid)",
               nil)
    }

    /// The menu bar's meeting, once in its call: Record “…” ⌘R in its
    /// menu, gone while recording.
    private func momentMenuBarRecords(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: the menu bar's meeting, once in the call, offers Record “…” ⌘R; chosen, it records; gone while recording"
        let watch = context.meetingWatch
        let preferences = context.preferences
        preferences.agendaMenuBar = .tenBefore
        let event = momentEvent("st-moment-menu", "Weekly design review", in: -60, link: true)
        book.testEvents = [event]
        center.standInMicrophone(.none)
        watch.resetForTest()
        watch.refresh()
        let before = watch.shownMenu
        // Joined (its Join): in the call.
        book.join(event)
        watch.refresh()
        let menu = watch.shownMenu
        let offered = menu.contains("Record “Weekly design review”")
        if let item = watch.itemMenu?.items.first(where: { $0.title == "Record “Weekly design review”" }), let index = watch.itemMenu?.index(of: item) {
            watch.itemMenu?.performActionForItem(at: index)
        }
        let recording = await waitUntil(timeout: 4) { center.recorder.isRecording } != nil
        watch.refresh()
        let gone = !watch.shownMenu.contains { $0.hasPrefix("Record “") }
        await pause(800)
        await momentStop(center)
        center.openWindows.forEach { $0.close() }
        watch.resetForTest()
        record(name, !before.contains { $0.hasPrefix("Record “") } && offered && recording && gone,
               "before joining: \(before); in the call: \(menu); recorded \(recording); while recording, Record gone \(gone)", nil)
    }

    /// The red dot's menu names each source with its level and the call's
    /// app; a source turned off and on again for the rest of the recording,
    /// both tracks keeping their time.
    private func momentRedDotSwitchesSources(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: the red dot's menu names each source (its level) and the call's app; the Mac's sound turned off then on, both tracks keep their time"
        book.testEvents = []
        center.standInMicrophone(MicrophoneHolders(apps: [Self.standInDiscord]))
        context.preferences.recorderConsentShown = true
        center.showCard(title: "Sources check")
        let view = center.cardView
        _ = await waitUntil(timeout: 3) { center.isCardVisible && view.macLine != "Starting…" }
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        guard await waitUntil(timeout: 3, { center.recorder.isRecording }) != nil else {
            record(name, false, "the recording did not start", nil)
            return
        }
        await pause(1500)
        let titles = await openRecorderMenu(center, capture: "recorder-menu-sources.png", pick: "The Mac's Sound · Every app", pickPrefix: true)
        let off = await waitUntil(timeout: 2) { !center.recorder.sources.macSound } != nil
        await pause(2000)
        let offTitles = await openRecorderMenu(center, capture: "recorder-menu-sources-off.png", pick: "The Mac's Sound · Off", pickPrefix: true)
        let on = await waitUntil(timeout: 3) { center.recorder.sources.macSound } != nil
        await pause(1500)
        let stopped = await momentStop(center)
        let folder = stopped?.0
        let lengths = folder.map { (me: trackLength($0.appendingPathComponent(Speaker.me.file)), them: trackLength($0.appendingPathComponent(Speaker.them.file))) }
        center.openWindows.forEach { $0.close() }
        center.standInMicrophone(.none)
        let sameLength = lengths.map { abs($0.me - $0.them) < 0.2 && $0.me > 4 } ?? false
        let passed = titles.contains { $0.hasPrefix("Microphone · ") } && titles.contains { $0.hasPrefix("The Mac's Sound · Every app") }
            && titles.contains("The Call: Discord") && off && offTitles.contains { $0.hasPrefix("The Mac's Sound · Off") } && on && sameLength
            && stopped?.1.unused == nil
        record(name, passed,
               "menu \(titles); off \(off), then \(offTitles.filter { $0.hasPrefix("The Mac") }); on \(on); tracks me \(String(format: "%.2f", lengths?.me ?? 0)) s, them \(String(format: "%.2f", lengths?.them ?? 0)) s; unused \(stopped?.1.unused?.map(\.rawValue) ?? [])",
               nil)
    }

    /// The call ends: its app leaves (here a stand-in, for a second) and a
    /// card offers Stop; the app back withdraws it; Keep Recording ends
    /// that reason's offers. A meeting over and quiet: Stop offered too.
    private func momentCallEndOffersStop(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: the call's app leaving offers Stop (never taking the keys), its return withdraws it, ↩ stops; a meeting over and quiet offers Stop, Keep Recording esc keeps it going"
        book.testEvents = []
        center.standInMicrophone(MicrophoneHolders(apps: [Self.standInDiscord]))
        center.showCard(title: nil)
        let view = center.cardView
        _ = await waitUntil(timeout: 3) { center.isCardVisible && view.macLine != "Starting…" }
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        guard await waitUntil(timeout: 3, { center.recorder.isRecording }) != nil else {
            record(name, false, "the recording did not start", nil)
            return
        }
        let title = center.recorder.title
        let named = title.hasPrefix("Discord call ")
        let discordFolder = center.recorder.folder
        await pause(1500)
        // Discord leaves the call.
        center.standInMicrophone(.none)
        let offered = await waitUntil(timeout: 5) { if case .callEnded? = center.cardContent { true } else { false } } != nil
        let line = view.detailText
        if offered { await captureRecordCard(center, as: "recorder-call-ended") }
        // Back: the offer goes.
        center.standInMicrophone(MicrophoneHolders(apps: [Self.standInDiscord]))
        let withdrawn = await waitUntil(timeout: 4) { !center.isCardVisible } != nil
        center.standInMicrophone(.none)
        let again = await waitUntil(timeout: 5) { if case .callEnded? = center.cardContent { true } else { false } } != nil
        guard await recordCardHasKeys(center, name) else { return }
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let stoppedByCard = await waitUntil(timeout: 4) { !center.recorder.isRecording } != nil
        await momentSettled(center, discordFolder)

        // A meeting over two seconds from now, nothing heard: quiet.
        let short = momentEvent("st-moment-quiet", "Short sync", in: -60, link: false, location: "Online", minutes: 62.0 / 60)
        book.testEvents = [short]
        center.recordMeeting(short, joining: false)
        _ = await waitUntil(timeout: 4) { center.recorder.isRecording }
        let quietOffered = await waitUntil(timeout: 12) { if case .callEnded? = center.cardContent { true } else { false } } != nil
        let quietLine = view.detailText
        if quietOffered, await recordCardHasKeys(center, name) { await pressKey(nil, code: CGKeyCode(kVK_Escape)) }
        await pause(5000)
        let kept = center.recorder.isRecording && !center.isCardVisible
        await momentStop(center)
        center.openWindows.forEach { $0.close() }
        record(name, named && offered && line == "Discord left the call." && withdrawn && again && stoppedByCard && quietOffered
               && quietLine.hasPrefix("The meeting ended at ") && kept,
               "named “\(title)”: \(named); left: offered \(offered) “\(line)”, back: withdrawn \(withdrawn), left again: offered \(again), ↩ stopped \(stoppedByCard); over and quiet: offered \(quietOffered) “\(quietLine)”, esc kept recording \(kept)",
               nil)
    }

    /// A browser call's microphone, for real: a scratch Chrome (its own
    /// profile, the page's question answered by Chrome's test flag) runs a
    /// WebRTC page standing in for Gather; Core Audio's process running the
    /// input is Chrome's helper, mapped to that Chrome and its window. A
    /// meeting with no link at that time is "in an app"; no meeting, a
    /// browser is not a call app. Recorded, Chrome quitting is the call's
    /// end.
    private func momentBrowserCallsMicrophone(_ center: RecorderCenter, _ book: CalendarBook) async {
        let name = "Recorder's moment: a WebRTC call in a scratch Chrome (standing in for Gather): its helper on the microphone mapped to Chrome and its window; “in an app” with a meeting, nothing to go on without; Chrome leaving the call offers Stop"
        guard let chromeURL = NSWorkspace.shared.urlForApplication(withBundleIdentifier: "com.google.Chrome") else {
            checks.append(Check(name: name, passed: true, skipped: true, detail: "no Google Chrome on this Mac", latencyMs: nil))
            return
        }
        center.standInMicrophone(nil)
        let profile = recorderScratch.appendingPathComponent("chrome-profile", isDirectory: true)
        let page = """
            <!doctype html><meta charset="utf-8"><title>Lumière HQ</title>
            <body style="font:20px -apple-system;padding:40px"><h1>Lumière HQ</h1><div id="s">starting…</div>
            <script>
            navigator.mediaDevices.getUserMedia({audio:true}).then(stream => {
              const a = new RTCPeerConnection(), b = new RTCPeerConnection();
              a.onicecandidate = e => e.candidate && b.addIceCandidate(e.candidate);
              b.onicecandidate = e => e.candidate && a.addIceCandidate(e.candidate);
              stream.getTracks().forEach(t => a.addTrack(t, stream));
              a.createOffer().then(o => a.setLocalDescription(o)).then(() => b.setRemoteDescription(a.localDescription))
                .then(() => b.createAnswer()).then(o => b.setLocalDescription(o)).then(() => a.setRemoteDescription(b.localDescription));
              document.getElementById('s').textContent = 'in the call';
            }).catch(e => document.getElementById('s').textContent = 'error: ' + e);
            </script>
            """
        // getUserMedia needs a secure origin: 127.0.0.1 is one.
        guard let server = LoopbackServer(handler: { _ in .html(page) }), let port = await server.port() else {
            record(name, false, "the call's page could not be served", nil)
            return
        }
        defer { server.stop() }
        let before = Set(NSRunningApplication.runningApplications(withBundleIdentifier: "com.google.Chrome").map(\.processIdentifier))
        let configuration = NSWorkspace.OpenConfiguration()
        configuration.createsNewApplicationInstance = true
        configuration.activates = false
        configuration.arguments = ["--user-data-dir=\(profile.path)", "--no-first-run", "--no-default-browser-check", "--use-fake-ui-for-media-stream",
                                   "http://127.0.0.1:\(port)/"]
        let chrome = try? await NSWorkspace.shared.openApplication(at: chromeURL, configuration: configuration)
        let pid = chrome?.processIdentifier ?? 0
        defer {
            chrome?.forceTerminate()
            try? FileManager.default.removeItem(at: profile)
        }
        var holders = MicrophoneHolders.none
        let mapped = await waitUntil(timeout: 20) {
            holders = MicrophoneUse.read().holders
            return holders.apps.contains { $0.pid == pid && $0.bundleID == "com.google.Chrome" }
        } != nil
        let fresh = !before.contains(pid)
        let window = MicrophoneUse.frontWindow(of: pid)
        let windowOwner = window.flatMap { id in
            (CGWindowListCopyWindowInfo([.optionIncludingWindow], id) as? [[String: Any]])?.first?[kCGWindowOwnerPID as String] as? NSNumber
        }?.int32Value
        // With a meeting and no link: in that app; without one: a browser is
        // not a call app.
        let meeting = momentEvent("st-moment-chrome", "Team standup", in: -30, link: false, location: "Gather · Lumière HQ")
        let inApp = center.moment(for: meeting)
        let noEvent = center.moment(for: nil)
        // Recorded, then Chrome quits: the call's end.
        book.testEvents = [meeting]
        center.recordMeeting(meeting, joining: false)
        _ = await waitUntil(timeout: 4) { center.recorder.isRecording }
        let chromeFolder = center.recorder.folder
        let watched = center.callApp?.pid == pid && center.callWindow == window
        await pause(2000)
        chrome?.terminate()
        let ended = await waitUntil(timeout: 15) { if case .callEnded? = center.cardContent { true } else { false } } != nil
        let line = center.cardView.detailText
        if ended, await recordCardHasKeys(center, name) { await pressKey(nil, code: CGKeyCode(kVK_Return)) }
        await momentSettled(center, chromeFolder)
        let others = holders.apps.filter { $0.pid != pid }.map(\.bundleID)
        record(name, mapped && fresh && window != nil && windowOwner == pid && inApp.kind == .inApp && inApp.app?.pid == pid && noEvent.kind == .nothing
               && watched && ended && line == "Google Chrome left the call.",
               "scratch Chrome \(pid) (new instance \(fresh)); on the microphone: mapped to it \(mapped), unnamed \(holders.unnamed), other apps \(others); its window \(window.map(String.init) ?? "none") owned by \(windowOwner.map(String.init) ?? "?"); with a meeting: \(inApp.kind.rawValue) \(inApp.app?.name ?? ""), without: \(noEvent.kind.rawValue); watched \(watched); quit: Stop offered \(ended) “\(line)”",
               nil)
    }

    /// Recordings written as the recorder writes them (no sound: what the
    /// lists read), in the self-test's own Recordings: `daysAgo` old, the
    /// words said as their transcript.
    @discardableResult
    private func momentSeed(_ center: RecorderCenter, _ title: String, daysAgo: Double, attendees: [String], said: [String],
                            state: MeetingRecord.State = .done) -> URL? {
        let started = Date.now.addingTimeInterval(-daysAgo * 86_400)
        guard let folder = try? center.recordings.makeFolder(title: title, started: started) else { return nil }
        var record = MeetingRecord(title: title, started: started, language: "en-US", recorder: nil)
        record.seconds = 1_920
        record.state = state
        record.attendees = attendees
        record.engine = MeetingTranscriber.engine
        let lines = said.enumerated().map { index, text in
            TranscriptLine(speaker: index % 2 == 0 ? .me : .them,
                           words: text.split(separator: " ").enumerated().map { TranscriptWord(String($1), start: Double(index * 10 + $0), end: Double(index * 10 + $0) + 0.5) })
        }
        try? center.recordings.write(record, to: folder)
        try? MeetingTranscript.File(language: "en-US", engine: MeetingTranscriber.engine, lines: lines).encoded()
            .write(to: folder.appendingPathComponent("transcript.json"))
        try? MeetingTranscriber.markdown(record, lines: lines).write(to: folder.appendingPathComponent("transcript.md"), atomically: true, encoding: .utf8)
        return folder
    }

    /// Search Recordings: every recording, by title, date and attendees at
    /// once, by the words said a moment later (the words around shown);
    /// ↩ opens one. In any search, a recording by its title.
    private func momentSearchRecordings(_ center: RecorderCenter) async {
        let name = "Recorder's moment: Search Recordings (“recs ”) lists them, finds one by an attendee at once and by the words said a moment later (the words shown), ↩ opens its window; any search finds one by its title"
        guard let library = context.recordings() else {
            record(name, false, "no recordings list", nil)
            return
        }
        let launcher = context.launcher
        momentSeed(center, "Quarterly budget", daysAgo: 2, attendees: ["Ysaline Vandevelde", "Camille"],
                   said: ["Let's start with the numbers.", "The budget for the third quarter is on track.", "Good, then the hiring plan."])
        momentSeed(center, "Weekly design review", daysAgo: 1, attendees: ["Jean-François Martaing"],
                   said: ["The new icons are ready.", "We ship them on Thursday."])
        momentSeed(center, "Standup", daysAgo: 0.5, attendees: [], said: ["Nothing blocking today."])
        library.reload()
        _ = await waitUntil(timeout: 3) { library.recordings.contains { $0.record.title == "Quarterly budget" } }
        let count = library.recordings.count
        // Any search: by its title.
        _ = await focusTestWindow()
        guard await typeInLauncher("quarterly bud") else {
            record(name, false, "the launcher did not take “quarterly bud”", nil)
            return
        }
        let anySearch = launcher.results.contains { if case .recorded(let found) = $0 { found.summary.title == "Quarterly budget" } else { false } }
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        await pressKey(nil, code: CGKeyCode(kVK_Escape))
        _ = await focusTestWindow()
        guard await openLauncher() else {
            record(name, false, "the launcher did not open", nil)
            return
        }
        // The prefix turns it into the mode: the field empties.
        for character in "recs " { _ = await typeCharacter(character) }
        let mode = await waitUntil(timeout: 1) { launcher.isInRecordings } != nil
        let listed = launcher.results.count
        for character in "ysaline" { _ = await typeCharacter(character) }
        _ = await waitUntil(timeout: 1) { launcher.query.hasSuffix("ysaline") }
        let byPerson = launcher.results.first?.title
        for _ in 0..<7 { await pressKey(nil, code: CGKeyCode(kVK_Delete)) }
        for character in "third quar" { _ = await typeCharacter(character) }
        var said: String?
        let byWords = await waitUntil(timeout: 3) {
            guard case .recorded(let found)? = launcher.results.first else { return false }
            said = found.said
            return found.summary.title == "Quarterly budget" && found.said?.contains("third quarter") == true
        } != nil
        await captureLauncherBothWays(as: "recorder-search")
        await pressKey(nil, code: CGKeyCode(kVK_Return))
        let opened = await waitUntil(timeout: 3) { center.openWindows.contains { $0.isVisible && $0.nsWindow.title == "Quarterly budget" } } != nil
        center.openWindows.forEach { $0.close() }
        record(name, count >= 3 && anySearch && mode && listed >= 3 && byPerson == "Quarterly budget" && byWords && opened,
               "\(count) recordings; any search “quarterly bud”: “Quarterly budget” \(anySearch); recs: mode \(mode), \(listed) rows; “ysaline” → “\(byPerson ?? "none")”; “third quar” → words \(byWords) “\(said ?? "")”; ↩ opened \(opened)",
               nil)
    }

    /// Settings → Recorder: its settings first, the recordings last by
    /// month; within the window; light and dark.
    private func momentRecorderPane(_ center: RecorderCenter) async {
        let name = "Recorder's moment: Settings → Recorder, the settings first, the recordings last by month, within the window, light and dark"
        let settings = context.settings
        settings.show(pane: .recorder)
        await pause(700)
        let overflow = settings.paneOverflow()
        await captureSettingsBothWays(as: "settings-recorder")
        let bottom = settings.scrollPaneToBottom()
        if bottom {
            await pause(300)
            await captureSettingsBothWays(as: "settings-recorder-bottom")
        }
        settings.close()
        record(name, overflow <= 1 && bottom, "overflow \(Int(overflow)) pt; scrolled to its list \(bottom)", nil)
    }

    /// Delete after: nothing goes as it is set; the pane's line says what
    /// the next pass moves to the Trash; the pass moves only the expired
    /// ones that are done. Keep recordings in: the recordings move there,
    /// refused while one records.
    private func momentRetentionAndFolder(_ center: RecorderCenter) async {
        let name = "Recorder's moment: Delete after removes nothing as set, says what goes, the pass moves only expired finished ones to the Trash; Keep recordings in moves them, puts them all back when one cannot move, refused while recording; no recording starts while they move"
        guard let library = context.recordings() else {
            record(name, false, "no recordings list", nil)
            return
        }
        let preferences = context.preferences
        let old = momentSeed(center, "Old planning", daysAgo: 40, attendees: [], said: ["An old meeting."])
        let oldPending = momentSeed(center, "Old waiting", daysAgo: 45, attendees: [], said: [], state: .pending)
        let oldNeverStopped = momentSeed(center, "Old never stopped", daysAgo: 50, attendees: [], said: [], state: .recording)
        library.reload()
        _ = await waitUntil(timeout: 3) { library.recordings.contains { $0.record.title == "Old planning" } }
        preferences.recorderRetention = .month
        let line = preferences.recorderRetention.removalLine(older: library.expiredCount(.month)) ?? ""
        context.settings.show(pane: .recorder)
        await pause(700)
        await captureSettingsBothWays(as: "settings-recorder-retention")
        context.settings.close()
        let keptAsSet = [old, oldPending].allSatisfy { $0.map { FileManager.default.fileExists(atPath: $0.path) } ?? false }
        let pruned = await library.prune(.month)
        let gone = [old, oldPending].allSatisfy { $0.map { !FileManager.default.fileExists(atPath: $0.path) } ?? false }
        let neverStoppedKept = oldNeverStopped.map { FileManager.default.fileExists(atPath: $0.path) } ?? false
        // The test's own, out of the Trash again.
        let trash = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(".Trash")
        for folder in [old, oldPending].compactMap({ $0 }) {
            let trashed = (try? FileManager.default.contentsOfDirectory(atPath: trash.path))?.filter { $0.hasPrefix(folder.lastPathComponent) } ?? []
            trashed.forEach { try? FileManager.default.removeItem(at: trash.appendingPathComponent($0)) }
        }
        if let oldNeverStopped { try? FileManager.default.removeItem(at: oldNeverStopped) }
        preferences.recorderRetention = .never

        // Keep recordings in: moved there, then back.
        let root = center.recordings.root
        let elsewhere = root.deletingLastPathComponent().appendingPathComponent("Recordings elsewhere", isDirectory: true)
        library.reload()
        _ = await waitUntil(timeout: 3) { !library.recordings.contains { $0.record.title == "Old planning" } }
        var names = Set(library.recordings.map(\.folder))
        // One the list has not read yet: it moves too (the folder is read).
        if let unlisted = momentSeed(center, "Not listed yet", daysAgo: 3, attendees: [], said: ["Moved all the same."]) {
            names.insert(unlisted.lastPathComponent)
        }
        // One whose meeting.json cannot be decoded: it moves too.
        if let broken = momentSeed(center, "Broken record", daysAgo: 4, attendees: [], said: []) {
            try? Data("{".utf8).write(to: broken.appendingPathComponent(Recordings.record))
            names.insert(broken.lastPathComponent)
        }
        let listedBefore = library.recordings.count
        // Slowed, to ask for a recording while they move: said, not started.
        let notify = center.notify
        var said: [String] = []
        center.notify = { said.append($0) }
        library.moveStepDelay = .milliseconds(300)
        let moving = Task { await context.moveRecordings(elsewhere) }
        _ = await waitUntil(timeout: 3) { library.moving != nil }
        center.showCard(title: "During the move")
        let blocked = !center.isCardVisible && said.last?.hasPrefix("Your recordings are moving to another folder") == true
        let refusedNone = await moving.value
        library.moveStepDelay = .zero
        center.notify = notify
        let there = Set((try? FileManager.default.contentsOfDirectory(atPath: elsewhere.path)) ?? [])
        let moved = !names.isEmpty && names.isSubset(of: there) && center.recordings.root == elsewhere && names.count == listedBefore + 2
        _ = await context.moveRecordings(root)
        let back = names.isSubset(of: Set((try? FileManager.default.contentsOfDirectory(atPath: root.path)) ?? []))
        // One that cannot move (made immutable, the oldest: moved last):
        // those moved before it come back, the folder stays the same.
        let stuck = momentSeed(center, "Stuck", daysAgo: 20, attendees: [], said: ["Kept."])
        if let stuck { try? FileManager.default.setAttributes([.immutable: true], ofItemAtPath: stuck.path) }
        library.reload()
        _ = await waitUntil(timeout: 3) { library.recordings.contains { $0.record.title == "Stuck" } }
        let all = Set(library.recordings.map(\.folder))
        let stuckSaid = await context.moveRecordings(elsewhere)
        let rolledBack = stuckSaid?.contains("could not move") == true && all.isSubset(of: Set((try? FileManager.default.contentsOfDirectory(atPath: root.path)) ?? [])) && library.root == root
            && center.recordings.root == root && library.moveFailures.first?.contains("could not move") == true
        let failureSaid = library.moveFailures.first ?? ""
        if let stuck {
            try? FileManager.default.setAttributes([.immutable: false], ofItemAtPath: stuck.path)
            try? FileManager.default.removeItem(at: stuck)
        }
        // A row older than a move naming another recording's folder: its
        // delete trashes nothing.
        var staleKept = false
        if let target = library.recordings.first(where: { $0.record.title == "Not listed yet" }) {
            var stale = RecordingSummary(folder: target.folder, record: target.record)
            stale.started = target.record.started.addingTimeInterval(-86_400)
            context.launcher.onDeleteRecording?(stale)
            staleKept = FileManager.default.fileExists(atPath: library.folder(target.folder).path)
        }
        // A folder that cannot be read: nothing moved, never "done" with none.
        try? FileManager.default.setAttributes([.posixPermissions: 0o000], ofItemAtPath: root.path)
        let unreadableSaid = await context.moveRecordings(elsewhere)
        try? FileManager.default.setAttributes([.posixPermissions: 0o700], ofItemAtPath: root.path)
        let unreadableKept = unreadableSaid?.contains("could not be read") == true && library.root == root && center.recordings.root == root
        try? FileManager.default.removeItem(at: elsewhere)
        preferences.recorderFolderPath = ""
        // While recording: refused.
        center.standInMicrophone(.none)
        center.showCard(title: "Refused move")
        _ = await waitUntil(timeout: 3) { center.isCardVisible && center.cardView.macLine != "Starting…" }
        var refused: String?
        if await recordCardHasKeys(center, name) {
            await pressKey(nil, code: CGKeyCode(kVK_Return))
            _ = await waitUntil(timeout: 3) { center.recorder.isRecording }
            refused = await context.moveRecordings(elsewhere)
            await momentStop(center)
            center.openWindows.forEach { $0.close() }
        }
        record(name, line.hasPrefix("2 recordings are older than a month") && keptAsSet && pruned == 2 && gone && neverStoppedKept && refusedNone == nil
               && blocked && moved && back && rolledBack && unreadableKept && staleKept && refused != nil,
               "line “\(line)”; kept as set \(keptAsSet); pass moved \(pruned) to the Trash, gone \(gone), never stopped kept \(neverStoppedKept); the card asked while moving: said, not shown \(blocked) “\(said.last ?? "")”; moved \(names.count) there \(moved), back \(back); one stuck: all put back \(rolledBack) “\(failureSaid)”; an unreadable folder: kept \(unreadableKept) “\(unreadableSaid ?? "moved")”; a stale row's delete kept it \(staleKept); while recording: “\(refused ?? "not refused")”",
               nil)
    }


    // MARK: - Event helpers

    /// Holds the Hyper trigger, presses `keys`, releases the trigger.
    /// Returns when the last key went down.
    @discardableResult
    private func hyperChord(_ keys: [Character], trigger: CGKeyCode? = nil) async -> ContinuousClock.Instant {
        let trigger = trigger ?? context.triggerKeyCode
        postKey(trigger, down: true)
        await pause(15)
        var lastDown = ContinuousClock.now
        for key in keys {
            guard let code = keyCode(key) else { continue }
            lastDown = .now
            postKey(code, down: true)
            await pause(12)
            postKey(code, down: false)
            await pause(12)
        }
        postKey(trigger, down: false)
        return lastDown
    }

    private func pressKey(_ character: Character?, code: CGKeyCode? = nil, flags: CGEventFlags = []) async {
        guard let code = code ?? character.flatMap(keyCode) else { return }
        postKey(code, down: true, flags: flags)
        await pause(12)
        postKey(code, down: false, flags: flags)
        await pause(12)
    }

    /// Holds `modifiers` down as a keyboard does (their own key-downs, so
    /// macOS's shortcuts see them as well as the flags), presses `keys`
    /// one after the other, then lets the modifiers go.
    private func pressHolding(_ modifiers: CGEventFlags, keys: [CGKeyCode]) async {
        let held = Self.modifierKeys.filter { modifiers.contains($0.flag) }
        var flags: CGEventFlags = []
        for modifier in held {
            flags.insert(modifier.flag)
            postKey(modifier.code, down: true, flags: flags)
            await pause(10)
        }
        for key in keys {
            postKey(key, down: true, flags: flags)
            await pause(12)
            postKey(key, down: false, flags: flags)
            await pause(12)
        }
        for modifier in held.reversed() {
            flags.remove(modifier.flag)
            postKey(modifier.code, down: false, flags: flags)
            await pause(10)
        }
    }

    private static let modifierKeys: [(code: CGKeyCode, flag: CGEventFlags)] = [
        (CGKeyCode(kVK_Control), .maskControl), (CGKeyCode(kVK_Option), .maskAlternate),
        (CGKeyCode(kVK_Shift), .maskShift), (CGKeyCode(kVK_Command), .maskCommand)
    ]

    private func keyCode(_ character: Character) -> CGKeyCode? {
        character == " " ? CGKeyCode(kVK_Space) : context.layout.keyCode(for: .character(character))
    }

    /// Hardware-like event: system state source, no skil.li marker.
    /// Flags are always explicit: inheriting the source state let a ⌘ from
    /// an earlier ⌘W leak into plain letters.
    private func postKey(_ code: CGKeyCode, down: Bool, flags: CGEventFlags = []) {
        let source = CGEventSource(stateID: .hidSystemState)
        guard let event = CGEvent(keyboardEventSource: source, virtualKey: code, keyDown: down) else { return }
        event.flags = flags
        event.post(tap: .cghidEventTap)
    }

    private func focusRecorder() async -> Bool {
        guard await focusTestWindow() else { return false }
        window.makeFirstResponder(recorder)
        recorder.events.removeAll()
        return true
    }

    private func setClipboard(_ string: String) {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(string, forType: .string)
    }

    private func pause(_ milliseconds: Int) async {
        try? await Task.sleep(for: .milliseconds(milliseconds))
    }

    /// Polls every 2 ms; returns the elapsed time when `condition` held.
    private func waitUntil(timeout seconds: Double, _ condition: @MainActor () -> Bool) async -> Duration? {
        let start = ContinuousClock.now
        let deadline = start + .milliseconds(Int(seconds * 1_000))
        while ContinuousClock.now < deadline {
            if condition() { return .now - start }
            try? await Task.sleep(for: .milliseconds(2))
        }
        return condition() ? .now - start : nil
    }

    private func record(_ name: String, _ passed: Bool, _ detail: String, _ latencyMs: Double?) {
        checks.append(Check(name: name, passed: passed, detail: detail, latencyMs: latencyMs))
        if passed {
            Log.actions.notice("SELFTEST PASS \(name, privacy: .public) — \(detail, privacy: .public)")
        } else {
            Log.actions.error("SELFTEST FAIL \(name, privacy: .public) — \(detail, privacy: .public)")
        }
    }

    nonisolated static func emit(_ report: Report, to path: String?) {
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        guard let data = try? encoder.encode(report) else { return }
        if let path {
            try? data.write(to: URL(fileURLWithPath: path))
        } else {
            FileHandle.standardOutput.write(data)
        }
    }

    private static func makeFrontmost(pid: pid_t) {
        let app = AXUIElementCreateApplication(pid)
        AXUIElementSetAttributeValue(app, kAXFrontmostAttribute as CFString, kCFBooleanTrue)
    }

    /// Value of the focused text element in the frontmost app, via AX.
    private static func focusedValue() -> String? {
        let system = AXUIElementCreateSystemWide()
        AXUIElementSetMessagingTimeout(system, 0.25)
        var focused: CFTypeRef?
        guard AXUIElementCopyAttributeValue(system, kAXFocusedUIElementAttribute as CFString, &focused) == .success,
              let focused, CFGetTypeID(focused) == AXUIElementGetTypeID()
        else { return nil }
        var value: CFTypeRef?
        guard AXUIElementCopyAttributeValue(unsafeDowncast(focused, to: AXUIElement.self), kAXValueAttribute as CFString, &value) == .success else { return nil }
        return (value as? String)?.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

/// First responder that records every key it receives, including ⌘ chords.
final class KeyRecorderView: NSView {
    struct Event {
        let keyCode: UInt16
        let characters: String
        let flags: NSEvent.ModifierFlags
    }

    var events: [Event] = []

    var summary: String {
        events.isEmpty ? "nothing" : events.map { "\($0.characters)(\($0.keyCode)) \($0.flags.rawValue)" }.joined(separator: ", ")
    }

    override var acceptsFirstResponder: Bool { true }

    override func keyDown(with event: NSEvent) {
        record(event)
    }

    override func performKeyEquivalent(with event: NSEvent) -> Bool {
        guard window?.firstResponder === self, event.type == .keyDown else { return false }
        record(event)
        return true
    }

    override func cancelOperation(_ sender: Any?) {}

    private func record(_ event: NSEvent) {
        events.append(Event(
            keyCode: event.keyCode,
            characters: event.charactersIgnoringModifiers?.lowercased() ?? "",
            flags: event.modifierFlags.intersection(.deviceIndependentFlagsMask)
        ))
    }
}

/// Stands in for Claude in the self-test: fixed chunks at a fixed pace, no
/// tokens. Remembers whether its stream was cancelled.
@MainActor
private final class FakeTextEngine: TextEngine {
    private let rounds: [[String]]
    private let delay: Duration
    private let cancelled = CancelFlag()
    private let calls = CallCount()

    var wasCancelled: Bool { cancelled.isSet }

    init(chunks: [String], delay: Duration) {
        self.rounds = [chunks]
        self.delay = delay
    }

    /// One answer per request, in order; the last one again after.
    init(rounds: [[String]], delay: Duration) {
        self.rounds = rounds
        self.delay = delay
    }

    func stream(_ request: AIRequest) -> AsyncThrowingStream<String, Error> {
        let chunks = rounds[min(calls.next(), rounds.count - 1)], delay = delay, cancelled = cancelled
        return AsyncThrowingStream { continuation in
            let task = Task {
                for chunk in chunks {
                    try? await Task.sleep(for: delay)
                    guard !Task.isCancelled else { return }
                    continuation.yield(chunk)
                }
                continuation.finish()
            }
            continuation.onTermination = { termination in
                task.cancel()
                if case .cancelled = termination { cancelled.set() }
            }
        }
    }
}

private final class CallCount: @unchecked Sendable {
    private let lock = NSLock()
    private var value = 0

    /// The calls before this one.
    func next() -> Int { lock.withLock { defer { value += 1 }; return value } }
}

private final class CancelFlag: @unchecked Sendable {
    private let lock = NSLock()
    private var value = false

    var isSet: Bool { lock.withLock { value } }
    func set() { lock.withLock { value = true } }
}


