/// A stand-in for huggingface.co (Better transcription's download): files
/// by name on 127.0.0.1, with ranges (a download resumed) and as slow as
/// asked; the ranges asked kept.
private final class ModelStandIn: @unchecked Sendable {
    private let listener: NWListener
    private let files: [String: URL]
    private let lock = NSLock()
    private var boundPort: UInt16?
    private var asked: [Int64] = []
    private var rate: Double?

    var port: UInt16? { lock.withLock { boundPort } }
    /// Where each request started (0: the whole file).
    var ranges: [Int64] { lock.withLock { asked } }
    /// Bytes a second at most; nil: as fast as it goes.
    var bytesPerSecond: Double? {
        get { lock.withLock { rate } }
        set { lock.withLock { rate = newValue } }
    }

    init?(files: [String: URL]) {
        self.files = files
        let parameters = NWParameters.tcp
        parameters.requiredLocalEndpoint = NWEndpoint.hostPort(host: "127.0.0.1", port: .any)
        guard let listener = try? NWListener(using: parameters) else { return nil }
        self.listener = listener
        listener.stateUpdateHandler = { [weak self] state in
            guard case .ready = state, let port = listener.port?.rawValue, let self else { return }
            self.lock.withLock { self.boundPort = port }
        }
        listener.newConnectionHandler = { [weak self] connection in
            connection.start(queue: .global())
            self?.receive(connection, buffer: Data())
        }
        listener.start(queue: .global())
    }

    private func receive(_ connection: NWConnection, buffer: Data) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 65536) { [weak self] data, _, isComplete, error in
            var buffer = buffer
            if let data { buffer.append(data) }
            guard let end = buffer.range(of: Data("\r\n\r\n".utf8)) else {
                if isComplete || error != nil { connection.cancel() } else { self?.receive(connection, buffer: buffer) }
                return
            }
            self?.answer(String(decoding: buffer[..<end.lowerBound], as: UTF8.self), on: connection)
        }
    }

    private func answer(_ head: String, on connection: NWConnection) {
        let lines = head.components(separatedBy: "\r\n")
        let parts = lines.first?.split(separator: " ") ?? []
        let path = parts.count > 1 ? String(parts[1].dropFirst()) : ""
        guard let url = files[path], let handle = try? FileHandle(forReadingFrom: url),
              let size = (try? url.resourceValues(forKeys: [.fileSizeKey]))?.fileSize.map(Int64.init) else {
            connection.send(content: Data("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".utf8),
                            completion: .contentProcessed { _ in connection.cancel() })
            return
        }
        var from: Int64 = 0
        if let range = lines.first(where: { $0.lowercased().hasPrefix("range:") }), let equals = range.firstIndex(of: "=") {
            from = Int64(range[range.index(after: equals)...].split(separator: "-").first.map { $0.trimmingCharacters(in: .whitespaces) } ?? "") ?? 0
        }
        lock.withLock { asked.append(from) }
        var header = "HTTP/1.1 \(from > 0 ? "206 Partial Content" : "200 OK")\r\nContent-Type: application/octet-stream\r\nContent-Length: \(size - from)\r\n"
            + "Accept-Ranges: bytes\r\nETag: \"selftest-\(path)\"\r\nLast-Modified: Mon, 26 Oct 2026 00:00:00 GMT\r\nConnection: close\r\n"
        if from > 0 { header += "Content-Range: bytes \(from)-\(size - 1)/\(size)\r\n" }
        header += "\r\n"
        try? handle.seek(toOffset: UInt64(from))
        connection.send(content: Data(header.utf8), completion: .contentProcessed { [weak self] error in
            guard error == nil, let self else {
                try? handle.close()
                connection.cancel()
                return
            }
            self.stream(handle, on: connection, started: Date(), sent: 0)
        })
    }

    private func stream(_ handle: FileHandle, on connection: NWConnection, started: Date, sent: Int64) {
        let chunk = (try? handle.read(upToCount: 1 << 20)) ?? Data()
        guard !chunk.isEmpty else {
            try? handle.close()
            connection.send(content: nil, contentContext: .finalMessage, isComplete: true, completion: .contentProcessed { _ in connection.cancel() })
            return
        }
        if let rate = bytesPerSecond {
            let due = Double(sent + Int64(chunk.count)) / rate - Date().timeIntervalSince(started)
            if due > 0 { usleep(useconds_t(min(due, 1) * 1_000_000)) }
        }
        connection.send(content: chunk, completion: .contentProcessed { [weak self] error in
            guard error == nil, let self else {
                try? handle.close()
                connection.cancel()
                return
            }
            self.stream(handle, on: connection, started: started, sent: sent + Int64(chunk.count))
        })
    }

    func stop() {
        listener.cancel()
    }
}

/// A one-route HTTP server on 127.0.0.1 for the webhook check: keeps the
/// last request (head and body) and answers `reply`.
private final class LocalHook: @unchecked Sendable {
    private let listener: NWListener
    private let lock = NSLock()
    private var request: String?
    private var boundPort: UInt16?

    var lastRequest: String? { lock.withLock { request } }
    var port: UInt16? { lock.withLock { boundPort } }

    init?(reply: String) {
        let parameters = NWParameters.tcp
        parameters.requiredLocalEndpoint = NWEndpoint.hostPort(host: "127.0.0.1", port: .any)
        guard let listener = try? NWListener(using: parameters) else { return nil }
        self.listener = listener
        listener.stateUpdateHandler = { [weak self] state in
            guard case .ready = state, let port = listener.port?.rawValue, let self else { return }
            self.lock.withLock { self.boundPort = port }
        }
        listener.newConnectionHandler = { [weak self] connection in
            connection.start(queue: .global())
            self?.receive(connection, buffer: Data(), reply: reply)
        }
        listener.start(queue: .global())
    }

    private func receive(_ connection: NWConnection, buffer: Data, reply: String) {
        connection.receive(minimumIncompleteLength: 1, maximumLength: 65536) { [weak self] data, _, isComplete, error in
            var buffer = buffer
            if let data { buffer.append(data) }
            let text = String(decoding: buffer, as: UTF8.self)
            if let headEnd = text.range(of: "\r\n\r\n") {
                let head = text[..<headEnd.lowerBound].lowercased()
                let length = head.components(separatedBy: "\r\n").first { $0.hasPrefix("content-length:") }
                    .flatMap { Int($0.dropFirst("content-length:".count).trimmingCharacters(in: .whitespaces)) } ?? 0
                if text.utf8.count - text[..<headEnd.upperBound].utf8.count >= length {
                    if let self { self.lock.withLock { self.request = text } }
                    let response = "HTTP/1.1 200 OK\r\nContent-Type: text/plain\r\nContent-Length: \(reply.utf8.count)\r\nConnection: close\r\n\r\n\(reply)"
                    connection.send(content: Data(response.utf8), completion: .contentProcessed { _ in connection.cancel() })
                    return
                }
            }
            if isComplete || error != nil {
                connection.cancel()
                return
            }
            self?.receive(connection, buffer: buffer, reply: reply)
        }
    }

    func stop() {
        listener.cancel()
    }
}


/// A stand-in Klipy for the self-test: Trending, a search ("cat"),
/// items by slug, shares and the media, on 127.0.0.1; every request kept.
private final class KlipyStandIn: @unchecked Sendable {
    static let key = "testkey"
    private let lock = NSLock()
    private var list: [LoopbackServer.Request] = []
    private var origin = ""
    private let gif: Data
    private let jpeg: Data

    init(gif: Data, jpeg: Data) {
        self.gif = gif
        self.jpeg = jpeg
    }

    /// Where its media are served: "http://127.0.0.1:…".
    var base: String {
        get { lock.withLock { origin } }
        set { lock.withLock { origin = newValue } }
    }

    var requests: [LoopbackServer.Request] { lock.withLock { list } }
    var paths: [String] { requests.map { $0.target.split(separator: "?").first.map(String.init) ?? $0.target } }
    /// The words of each search, in order.
    var searches: [String] {
        requests.filter { $0.target.contains("/gifs/search?") }.compactMap { Self.query($0.target)["q"] }
    }
    /// The slugs each items request read back.
    var itemSlugs: [[String]] {
        requests.filter { $0.target.contains("/gifs/items?") }.map { (Self.query($0.target)["slugs"] ?? "").split(separator: ",").map(String.init) }
    }
    var shares: [(slug: String, query: String)] {
        requests.filter { $0.method == "POST" && $0.target.contains("/gifs/share/") }.map { request in
            let body = (try? JSONSerialization.jsonObject(with: request.body) as? [String: String]) ?? [:]
            return (String(request.target.split(separator: "/").last ?? ""), body["q"] ?? "")
        }
    }

    func answer(_ request: LoopbackServer.Request) -> LoopbackServer.Response {
        lock.withLock { list.append(request) }
        let path = request.target.split(separator: "?").first.map(String.init) ?? request.target
        if path.hasPrefix("/media/") {
            let still = path.hasSuffix(".jpg")
            return LoopbackServer.Response(headers: ["Content-Type": still ? "image/jpeg" : "image/gif"], body: still ? jpeg : gif)
        }
        let prefix = "/api/v1/\(Self.key)/gifs/"
        guard path.hasPrefix(prefix) else { return LoopbackServer.Response(status: 404) }
        let action = String(path.dropFirst(prefix.count))
        let query = Self.query(request.target)
        switch action {
        case "trending": return page((1...6).map { ("trend-\($0)", "Trending \($0)") })
        case "search": return page(query["q"] == "cat" ? (1...4).map { ("cat-\($0)", "Cat \($0)") } : [])
        case "items":
            let slugs = (query["slugs"] ?? "").split(separator: ",").map(String.init)
            return page(slugs.map { slug in (slug, slug.hasPrefix("cat-") ? "Cat \(slug.dropFirst(4))" : slug) })
        default:
            if action.hasPrefix("share/"), request.method == "POST" { return .json(["result": true]) }
            return LoopbackServer.Response(status: 404)
        }
    }

    private func page(_ items: [(slug: String, title: String)]) -> LoopbackServer.Response {
        let base = self.base
        let data: [[String: Any]] = items.map { slug, title in
            var file: [String: Any] = [:]
            for size in ["hd", "md", "sm", "xs"] {
                file[size] = ["gif", "webp", "jpg"].reduce(into: [String: Any]()) { formats, kind in
                    formats[kind] = ["url": "\(base)/media/\(slug)/\(size).\(kind)", "width": 160, "height": 120, "size": 4000]
                }
            }
            return ["id": abs(slug.hashValue), "slug": slug, "title": title, "file": file, "tags": [], "type": "gif"]
        }
        return .json(["result": true, "data": ["data": data, "current_page": 1, "per_page": 48, "has_next": false]])
    }

    private static func query(_ target: String) -> [String: String] {
        let items = URLComponents(string: "http://stand.in" + target)?.queryItems ?? []
        return Dictionary(items.map { ($0.name, $0.value ?? "") }, uniquingKeysWith: { first, _ in first })
    }
}

/// Counts presses of the self-test's stand-in menu item.
@MainActor
private final class PressCounter: NSObject {
    private(set) var count = 0

    @objc func press(_ sender: Any?) {
        count += 1
    }
}

/// A stand-in GitHub for the self-test: the device flow (pending once, then
/// a token), the inbox's GraphQL answer, the notifications (304 once asked
/// with their Last-Modified), merging and marking read, recorded.
private final class GitHubStandIn: @unchecked Sendable {
    private let lock = NSLock()
    private var base = ""
    private var polls = 0
    private var notModifiedCount = 0
    private var mergedList: [String] = []
    private var readList: [String] = []
    private static let token = "Bearer selftest-token"
    private static let lastModified = "Mon, 12 Oct 2026 10:00:00 GMT"

    var notModified: Int { lock.withLock { notModifiedCount } }
    var merged: [String] { lock.withLock { mergedList } }
    var read: [String] { lock.withLock { readList } }

    func setBase(_ value: String) { lock.withLock { base = value } }

    func answer(_ request: LoopbackServer.Request) -> LoopbackServer.Response {
        lock.withLock { respond(request) }
    }

    private func respond(_ request: LoopbackServer.Request) -> LoopbackServer.Response {
        let path = request.target.split(separator: "?").first.map(String.init) ?? request.target
        switch (request.method, path) {
        case ("POST", "/login/device/code"):
            return .json(["device_code": "dc-1", "user_code": "WDJB-MJHT", "verification_uri": base + "/login/device", "expires_in": 900, "interval": 1])
        case ("POST", "/login/oauth/access_token"):
            polls += 1
            return polls < 2 ? .json(["error": "authorization_pending"]) : .json(["access_token": "selftest-token", "token_type": "bearer", "scope": "repo"])
        default:
            break
        }
        guard request.headers["authorization"] == Self.token else { return .json(["message": "Bad credentials"], status: 401) }
        switch (request.method, path) {
        case ("POST", "/graphql"):
            return LoopbackServer.Response(headers: ["Content-Type": "application/json"], body: Data(Self.inbox.utf8))
        case ("GET", "/notifications"):
            if request.headers["if-modified-since"] == Self.lastModified {
                notModifiedCount += 1
                return LoopbackServer.Response(status: 304, headers: ["X-Poll-Interval": "60"])
            }
            return LoopbackServer.Response(headers: ["Content-Type": "application/json", "Last-Modified": Self.lastModified, "X-Poll-Interval": "60"],
                                           body: Data(Self.notifications.utf8))
        case ("PUT", let path) where path.hasSuffix("/merge"):
            let body = (try? JSONSerialization.jsonObject(with: request.body)) as? [String: Any] ?? [:]
            let parts = path.split(separator: "/")
            if parts.count >= 6 {
                mergedList.append("\(parts[1])/\(parts[2])#\(parts[4]) \(body["merge_method"] as? String ?? "?") \(body["sha"] as? String ?? "?")")
            }
            return .json(["merged": true, "message": "Pull Request successfully merged"])
        case ("PATCH", let path) where path.hasPrefix("/notifications/threads/"):
            readList.append(String(path.dropFirst("/notifications/threads/".count)))
            return LoopbackServer.Response(status: 205)
        default:
            return .json(["message": "Not Found"], status: 404)
        }
    }

    /// As GitHub sends it: running or failing required checks block the
    /// merge box (BLOCKED), all green is CLEAN.
    private static func pullRequest(_ number: Int, title: String, rollup: String, contexts: String, created: String) -> String {
        let mergeState = rollup == "SUCCESS" ? "CLEAN" : "BLOCKED"
        return #"{"databaseId":\#(number),"number":\#(number),"title":"\#(title)","url":"https://github.com/nomdelasociete/skilli/pull/\#(number)","state":"OPEN","isDraft":false,"createdAt":"\#(created)","updatedAt":"2026-10-12T08:00:00Z","author":{"login":"selftest"},"headRefOid":"abc\#(number)","repository":{"nameWithOwner":"nomdelasociete/skilli","name":"skilli","isArchived":false,"viewerDefaultMergeMethod":"SQUASH","viewerPermission":"WRITE"},"reviewDecision":"APPROVED","mergeStateStatus":"\#(mergeState)","mergeable":"MERGEABLE","reviewRequests":{"nodes":[]},"commits":{"nodes":[{"commit":{"statusCheckRollup":{"state":"\#(rollup)","contexts":{"nodes":[\#(contexts)]}}}}]}}"#
    }

    private static let inbox = #"{"data":{"viewer":{"login":"selftest","pullRequests":{"nodes":["#
        + pullRequest(1, title: "Add the GitHub strip", rollup: "SUCCESS",
                      contexts: #"{"__typename":"CheckRun","name":"build","status":"COMPLETED","conclusion":"SUCCESS"}"#, created: "2026-10-10T08:00:00Z") + ","
        + pullRequest(2, title: "Faster history", rollup: "PENDING",
                      contexts: #"{"__typename":"StatusContext","context":"ci/woodpecker/pr/build","state":"PENDING"}"#, created: "2026-10-11T08:00:00Z") + ","
        + pullRequest(3, title: "Fix the build", rollup: "FAILURE",
                      contexts: #"{"__typename":"CheckRun","name":"lint","status":"COMPLETED","conclusion":"FAILURE"}"#, created: "2026-10-09T08:00:00Z")
        + #"]}},"search":{"nodes":[]}}}"#

    private static let notifications = #"""
        [{"id":"21","reason":"ci_activity","unread":true,"updated_at":"2026-10-12T09:00:00Z",
          "subject":{"title":"CI failed on main","url":null,"type":"CheckSuite"},"repository":{"full_name":"nomdelasociete/skilli"}},
         {"id":"22","reason":"review_requested","unread":true,"updated_at":"2026-10-12T10:00:00Z",
          "subject":{"title":"Review the new API","url":"https://api.github.com/repos/nimbus-hq/nimbus/pulls/7","type":"PullRequest"},
          "repository":{"full_name":"nimbus-hq/nimbus"}}]
        """#
}

/// Self-test hook: the main display recorded to a movie (the chess demo),
/// through ScreenCaptureKit's recording output; Screen Recording needed.
@MainActor
final class ScreenRecorder: NSObject, SCStreamDelegate, SCRecordingOutputDelegate {
    private var stream: SCStream?
    private(set) var failure: String?

    /// The main display, or only `apps`' windows cut to `area` (screen
    /// points, top-left origin): nothing else shows.
    func start(to url: URL, apps: [pid_t] = [], area: CGRect? = nil) async {
        try? FileManager.default.removeItem(at: url)
        do {
            // Every app, not only those on screen now: skil.li's card shows
            // later.
            let content = try await SCShareableContent.excludingDesktopWindows(false, onScreenWindowsOnly: false)
            guard let display = content.displays.first else {
                failure = "no display"
                return
            }
            let shown = content.applications.filter { apps.contains($0.processID) }
            let filter = shown.isEmpty ? SCContentFilter(display: display, excludingWindows: [])
                : SCContentFilter(display: display, including: shown, exceptingWindows: [])
            let configuration = SCStreamConfiguration()
            let rect = area?.intersection(CGRect(x: 0, y: 0, width: display.width, height: display.height))
            if let rect, !rect.isNull, rect.width > 0 {
                configuration.sourceRect = rect
                // Retina sharp, even sizes for the encoder.
                configuration.width = Int(rect.width * 2) / 2 * 2
                configuration.height = Int(rect.height * 2) / 2 * 2
            } else {
                configuration.width = display.width
                configuration.height = display.height
            }
            configuration.minimumFrameInterval = CMTime(value: 1, timescale: 30)
            configuration.showsCursor = true
            let stream = SCStream(filter: filter, configuration: configuration, delegate: self)
            let output = SCRecordingOutputConfiguration()
            output.outputURL = url
            output.outputFileType = .mov
            output.videoCodecType = .h264
            try stream.addRecordingOutput(SCRecordingOutput(configuration: output, delegate: self))
            try await stream.startCapture()
            self.stream = stream
        } catch {
            failure = error.localizedDescription
        }
    }

    func stop() async {
        try? await stream?.stopCapture()
        stream = nil
        // The movie is finished writing once the output says so.
        try? await Task.sleep(for: .milliseconds(800))
    }

    nonisolated func stream(_ stream: SCStream, didStopWithError error: any Error) {
        let message = error.localizedDescription
        Task { @MainActor in self.failure = message }
    }

    nonisolated func recordingOutput(_ recordingOutput: SCRecordingOutput, didFailWithError error: any Error) {
        let message = error.localizedDescription
        Task { @MainActor in self.failure = message }
    }
}

/// Ends a self-test that stops moving on, even with the main thread held:
/// 2026-10-22, a walk of skil.li's Accessibility tree started after the
/// focus was lost kept the main thread for 9 hours, and every other run
/// waited behind it. From its own queue it writes what was recorded, with
/// its own failure, then ends skil.li.
final class SelfTestWatchdog: Sendable {
    /// After the focus is lost the rest is skipped: the run ends at once.
    static let afterFocusLost: Duration = .seconds(60)
    /// The main run loop answers within this whatever a step waits for:
    /// the main actor's awaits leave the main thread free.
    static let mainThreadHeld: Duration = .seconds(60)
    /// Longer than any check takes (Chess's records once, its games played).
    static let withoutACheck: Duration = .seconds(1_800)

    private struct State {
        var checks: [SelfTest.Check] = []
        var lastCheck = ContinuousClock.now
        var lastAnswer = ContinuousClock.now
        var asked = false
        var focusLost: ContinuousClock.Instant?
        var over = false
        var report: SelfTest.Report?
    }

    private let state = Mutex(State())
    private let timer: DispatchSourceTimer

    init(reportPath: String?) {
        let timer = DispatchSource.makeTimerSource(queue: DispatchQueue(label: "com.nomdelasociete.Skilli.selftest-watchdog"))
        self.timer = timer
        timer.schedule(deadline: .now() + 5, repeating: 5)
        timer.setEventHandler { [weak self] in self?.look(reportPath: reportPath) }
        timer.resume()
    }

    func recorded(_ checks: [SelfTest.Check]) {
        state.withLock {
            $0.checks = checks
            $0.lastCheck = .now
        }
    }

    func focusLost() {
        state.withLock { $0.focusLost = $0.focusLost ?? .now }
    }

    /// The run is over: nothing more to watch. The report written, if the
    /// watchdog ended it first.
    func stop() -> SelfTest.Report? {
        timer.cancel()
        return state.withLock {
            $0.over = true
            return $0.report
        }
    }

    private func look(reportPath: String?) {
        // The main run loop is asked to answer. Its own blocks run in a
        // menu's or a modal session's loop too: only a main thread held in
        // code that does not return leaves it unanswered.
        let ask = state.withLock {
            defer { $0.asked = true }
            return !$0.asked
        }
        if ask {
            CFRunLoopPerformBlock(CFRunLoopGetMain(), CFRunLoopMode.commonModes.rawValue) { [weak self] in
                self?.state.withLock {
                    $0.lastAnswer = .now
                    $0.asked = false
                }
            }
            CFRunLoopWakeUp(CFRunLoopGetMain())
        }
        let report: SelfTest.Report? = state.withLock {
            guard !$0.over else { return nil }
            let now = ContinuousClock.now
            let why: String
            if let lost = $0.focusLost, now - lost > Self.afterFocusLost {
                why = "the run went on \(Self.seconds(now - lost)) s after the focus was lost"
            } else if now - $0.lastAnswer > Self.mainThreadHeld {
                why = "the main thread did not answer for \(Self.seconds(now - $0.lastAnswer)) s"
            } else if now - $0.lastCheck > Self.withoutACheck {
                why = "no check finished for \(Self.seconds(now - $0.lastCheck)) s"
            } else {
                return nil
            }
            // The main run loop's mode: a menu's or a modal session's loop
            // shows there; code that does not return, the mode it was called in.
            let mode = CFRunLoopCopyCurrentMode(CFRunLoopGetMain()).map { $0.rawValue as String } ?? "none"
            $0.over = true
            $0.report = SelfTest.Report(checks: $0.checks + [SelfTest.Check(
                name: "Watchdog", passed: false,
                detail: "\(why), after “\($0.checks.last?.name ?? "the start")”; the main thread last answered \(Self.seconds(now - $0.lastAnswer)) s ago, its run loop in \(mode); ended",
                latencyMs: nil
            )])
            return $0.report
        }
        guard let report else { return }
        timer.cancel()
        Log.actions.error("SELFTEST FAIL Watchdog — \(report.checks.last?.detail ?? "", privacy: .public)")
        SelfTest.emit(report, to: reportPath)
        AppDelegate.terminateFromAnyThread(grace: .seconds(10)) { exit(EXIT_FAILURE) }
    }

    private static func seconds(_ duration: Duration) -> Int {
        Int(duration.components.seconds)
    }
}

extension SelfTest.Report {
    init(checks: [SelfTest.Check]) {
        let skipped = checks.filter(\.skipped).count
        let passed = checks.filter { $0.passed && !$0.skipped }.count
        self.init(passed: passed, failed: checks.count - passed - skipped, skipped: skipped, checks: checks)
    }
}
#endif
